asm_global_link	equ	$162                    ; where asm_find_symbol would add it to the globals
asm_name_tree	equ	$166                    ; the root link of the names tree: macros, modules (type 9), include
                                                ;   files (type 11)
asm_section_table	equ	$16e            ; TEXT, DATA and BSS, 12 bytes each: +0 the start in the program, +4 the
                                                ;   size
text_size	equ	$172                    ; the text section's size
text_relocation	equ	$176                    ; the text's relocation list (blocks of 50 offsets), 0 for none
asm_data_start	equ	$17a                    ; in it: the DATA start
data_size	equ	$17e                    ; the data section's size
data_relocation	equ	$182                    ; the data's relocation list, 0 for none
asm_bss_start	equ	$186                    ; in it: the BSS start
bss_size	equ	$18a                    ; the BSS section's size
line_end_hook	equ	$196                    ; a routine to run after the line, 0 for none
include_file	equ	$19a                    ; the current include file's entry, 0 in the main source
line_code_size	equ	$19e                    ; the bytes the current line made, for the listing
binary_handle	equ	$1a2                    ; the binary file's handle, 0 when not open
output_handle	equ	$1a4                    ; the low word of output_file: the handle for Fseek
incbin_handle	equ	$1a6                    ; INCBIN's file handle while it reads
asm_source_name	equ	$1aa                    ; the descriptor of the source file named on the command line, 0 for the
                                                ;   source in memory
reserve_bytes	equ	$1ae                    ; bytes the line's end steps the PC past without code (DS, INCBIN, RORG)
asm_optimise_count	equ	$1b2            ; the optimisations made
asm_optimise_saved	equ	$1b4            ; the bytes they saved
name_after_comma	equ	$1b6            ; where the source goes on after the comma that ended a section name, 0
                                                ;   for none
program_buffer	equ	$1ba                    ; assembling to memory: the program buffer (header then the image), else
                                                ;   0
program_buffer_end	equ	$1be            ; the program buffer's end
cmdline_z	equ	$1c2                    ; -Z: the listing routine runs in pass 1 too
cmdline_small_buffers	equ	$1c3            ; -M: every buffer at its smallest size
linker_format	equ	$1c4                    ; linkable output's format: 0 GST, 1 DRI
symbol_length	equ	$1c6                    ; the significant length of symbol names and one (OPT C)
cmdline_case	equ	$1c8                    ; -C: labels in any case (copied with the next three to $fe-$101)
cmdline_linkable	equ	$1c9            ; -L: linkable output
cmdline_symbol_table	equ	$1ca            ; -S: the symbol table at the listing's end
cmdline_listing	equ	$1cb                    ; -P: a listing
asm_line_sp	equ	$1cc                    ; the stack at the line's start: a fatal error in a line goes back to it
pass_two	equ	$1d0                    ; nonzero on pass 2
size_code	equ	$1d1                    ; the instruction's size suffix: 0 none, 1 .B/.S, 2 .W, 3 .L
return_code	equ	$1d2                    ; the result: 0, 5 warnings, 10 errors, 20 fatal, 100 not started
address_operand	equ	$1d3                    ; $ff while an <ea> is read for LEA/PEA/Scc: no odd address or # checks
asm_lines_total	equ	$1d4                    ; the lines assembled
line_number	equ	$1d6                    ; the line number in the current file
asm_code_size	equ	$1d8                    ; the bytes of code made
program_counter	equ	$1dc                    ; the assembly address of the current line
memory_source	equ	$1e0                    ; the source in memory, from the editor; 0 for a file
asm_source_ptr	equ	$1e4                    ; the next line to read there
asm_source_end	equ	$1e8                    ; its end
asm_line_start	equ	$1ec                    ; the start of the line being assembled
asm_global_root	equ	$1f0                    ; the global symbols tree's root
asm_name_root	equ	$1f4                    ; the names tree's root
code_buffer_ptr	equ	$1f8                    ; where the current line's code is built (normally code_buffer at $530)
line_code_start	equ	$1fc                    ; where the current line's code starts
offset_section_record	equ	$200            ; the OFFSET section's record (its PC at +8; size not worked out here)
walk_stack	equ	$30c                    ; the stack kept while a tree walk is left from inside when found
asm_mnemonic_symbol	equ	$310            ; the descriptor of a name read in the mnemonic field: pointer, flag,
                                                ;   length, name
line_label	equ	$396                    ; the line's label: +0 text pointer, +5 length, +6 128-byte name copy
asm_label_exported	equ	$39a            ; in it: the label ended "::"
line_label_text	equ	$39c                    ; line_label's name copy, also a file name for INCBIN/INCLUDE
name_buffer	equ	$41c                    ; the name just read: +0 pointer to the name, +4 flag, +5 length, +6 128
                                                ;   bytes of text
source_record	equ	$4a2                    ; the command line's source file: +0 points to its name, +5 its length,
                                                ;   +6 the name
source_name_length	equ	$4a7            ; its name's length, with the $0b end mark
source_name	equ	$4a8                    ; its name, .S added when it has none, ended by $0b
mnemonic_name	equ	$528                    ; the line's opcode upper-cased, padded with spaces (or 0 in
                                                ;   line_opcode)
line_code	equ	$530                    ; the line's code in pass 1; also where file headers and symbol records
                                                ;   are made
listing_sentinel_name	equ	$546            ; the symbol listing's dummy name: length 127, 128 bytes $ff
asm_operator_stack	equ	$5b0            ; the expression's operator stack: a byte count, then a word per token
asm_value_stack	equ	$5d8                    ; the expression's value stack: a byte count, then value and type, 8
                                                ;   bytes each
asm_output_name	equ	$650                    ; -O: the output file name
output_base_name	equ	$6a2            ; the source's name without its extension, the output's name is made
                                                ;   from it
asm_incdir_list	equ	$6f4                    ; the INCDIR paths, 0-ended strings; 0 for none
asm_stack_top	equ	$4768                   ; the assembler's stack starts here and grows down
asm_list_level	equ	$476c                   ; LIST+ / LIST- level: the listing is on while 0 or more
asm_list_marker	equ	$476d                   ; what the listing shows in place of the code: "=" and a value, $ff an
                                                ;   address, 0 the code
listing_value	equ	$476e                   ; the value or address the listing shows on this line
rs_step	equ	$4772                           ; the RS direction and alignment step (1)
rs_counter	equ	$4776                   ; the RS counter (__RS)
rs_counter_low	equ	$4779                   ; the low byte of rs_counter, for its odd test
if_depth	equ	$477a                   ; the IF levels open
macro_call_number	equ	$477c           ; the \@ number of the last macro call that used \@
macro_frame	equ	$477e                   ; the frame of the macro that runs, 0 for none
macro_stack_free	equ	$4782           ; the bytes left in the stack of macro call frames
macro_stack_top	equ	$4784                   ; where the next macro call frame goes
rept_count	equ	$4788                   ; the times the REPT body is still to play
rept_block	equ	$478c                   ; the REPT body's block being read, 0 when no REPT plays
rept_read	equ	$4790                   ; the REPT body's read pointer
macro_depth	equ	$4794                   ; the macro calls nested now
rept_macro_depth	equ	$4796           ; the macro depth at the REPT: its lines get that macro's parameters
mnemonic_hash_table	equ	$4798           ; 2335 words: each the offset of a mnemonic record, -1 for none
reloc_terms_end	equ	$59d6                   ; the end of reloc_terms
expr_terms	equ	$59da                   ; the expression's XREF and section terms: pairs of words (operator ++,
                                                ;   XREF number or $ff,section), 0 to end
next_optimisation	equ	$5a2a           ; pass 2: the program offset of the next recorded optimisation, -1 none
optimisation_first	equ	$5a2e           ; the first optimisation record block
optimisation_block	equ	$5a32           ; the current optimisation record block
optimisation_end	equ	$5a36           ; pass 2: the end of the last block's records
asm_listing_wanted	equ	$5a3a           ; -P: a listing is wanted
asm_listing_active	equ	$5a3b           ; listing output goes on now
listing_handle	equ	$5a3c                   ; the listing file's handle, 0 for none
listing_buffer	equ	$5a40                   ; the listing file's output buffer
listing_pointer	equ	$5c40                   ; the next free byte in it
listing_buffer_end	equ	$5c44           ; its end
page_width	equ	$5c48                   ; listing columns (132)
page_length	equ	$5c4a                   ; listing lines a page (60)
listing_column	equ	$5c4c                   ; the column on the listing line
page_line	equ	$5c4e                   ; the line on the page, -1: a header first
page_number	equ	$5c50                   ; the listing's page number
tab_width	equ	$5c52                   ; the listing's tab width (8)
listing_date	equ	$5c54                   ; the date for the page header
listing_title	equ	$5c68                   ; the TTL title
listing_subtitle	equ	$5cb9           ; the SUBTTL subtitle
listing_format	equ	$5d0a                   ; FORMAT flags, bit 7-n for parameter n; bit 0 also a page throw from
                                                ;   PAGE
exe_text_buffer	equ	$5d0c                   ; executable: the text's buffer record: +0 buffer, +4 its size, +8 PC
                                                ;   limit, +$c code pointer, +$10 file offset (DRI: +0 the whole text)
exe_text_buffer_size	equ	$5d10           ; its size
text_buffer_limit	equ	$5d14           ; the text address where it must be written out
exe_text_pointer	equ	$5d18           ; the text's code pointer while in another section
text_file_position	equ	$5d1c           ; where the text buffer goes in the file
data_buffer	equ	$5d20                   ; executable: the data output buffer (start of a 20-byte block, passed
                                                ;   in a1)
data_buffer_size	equ	$5d24           ; its size
data_buffer_limit	equ	$5d28           ; the data address where it must be written out
exe_data_pointer	equ	$5d2c           ; the data's code pointer while in another section
data_file_position	equ	$5d30           ; where the data buffer goes in the file
binary_length	equ	$5d34                   ; the binary file's length so far
exe_file_length_low	equ	$5d37           ; its low byte, for the odd test
symbol_table_size	equ	$5d38           ; the symbol table's size, for the header
header_flags	equ	$5d3c                   ; the program header's flags (COMMENT HEAD=)
section_start_bytes	equ	$5d40           ; pass 1: bytes_made when the current section was entered
gst_buffer_size	equ	$5d44                   ; GST: the stream buffer's size (DRI: the stack kept while the XREF walk
                                                ;   runs)
gst_buffer	equ	$5d48                   ; GST: the stream buffer
gst_room	equ	$5d4c                   ; GST: the bytes left in it
gst_pointer	equ	$5d50                   ; GST: the write pointer in it
gst_fixups_end	equ	$5d54                   ; GST: the end of the line's xref list
gst_records_end	equ	$5d58                   ; GST: the end of the line's xref records
gst_fixups	equ	$5d5c                   ; GST: the line's xref list, 10 bytes each (code place, record, size), 0
                                                ;   to end
gst_records	equ	$5f1c                   ; GST: the line's xref records
basepage	equ	$611c                   ; the assembler's basepage
wait_at_exit	equ	$6120                   ; nonzero: wait for a key at the end (-Q, or the command line typed in)
memory_total	equ	$6122                   ; the heap's size at the start
source_dir_end	equ	$6126                   ; the end of the folders in source_dir: where an include file's name is
                                                ;   put
source_dir	equ	$612a                   ; the source's folders as given, to find include files in
listing_name	equ	$61ce                   ; -P: the listing file's name, empty for the source's name with .LST
start_time	equ	$6220                   ; the 200 Hz clock at the start
heap_last	equ	$6224                   ; the last block allocated, 0 for none
heap_start	equ	$6228                   ; the heap's free start
heap_end	equ	$622c                   ; the heap's end
include_path	equ	$6230                   ; an INCDIR folder and an include file's name being tried
heap_base	equ	$62fc                   ; the end of the variables: the heap starts here

	section	text

;------------------------------------------------------------------------------
; GenST 2.25 starts here.  a6 is set to the data section's start ($c212) and stays there for the whole
; program, so every d(a6) operand is a program variable.  The code at startup then:
; - takes the basepage from 4(sp), moves sp to GenST's own stack and sets assembler_linked when the
;   assembler is part of this image (the basepage's data start is not $4924, where an editor-only build's
;   data would start; such a build calls a resident assembler through trap #10);
; - gives back the memory past the BSS (Mshrink), notes the basepage and whether there is a command line;
; - starts GEM (appl_init, the workstation, the menu, the window), copies the find code's case folding
;   routine into RAM, reads the preferences and loads MonST when they say so;
; - clears the find and replace strings, the block marks, the file name and the undo line, takes the text
;   buffer with Malloc and empties it, then loads the file named on the command line, if any;
; - falls into editor_loop, which updates the status line, waits for an event and hands it on: a key to
;   editor_key, an Alt key to editor_alt_key (the A-Z table alt_key_table), a menu item, mouse click or
;   window message to editor_command_event, and the window's redraw messages to the code at $31f2.
; The text is held as lines ending in CR ($0d) from text_start to text_end, where one more CR always ends it.
; In the editor a4 is the start of the cursor's line, d7 the cursor's row in the window and d6 its column
; (tabs expanded), top_line the first line shown and top_line_number its number counting from 0.
;------------------------------------------------------------------------------
start:
	lea	data_base,a6                    ; a6 = the program's variables for good
	bra.w	startup                         ; on to the start-up code
	dc.w	$4afb,$322e,$3030               ; $4afb then "2.00": the mark in front of the preferences kept in the
                                                ;   program
default_tab_size:	; from: gem_init
	dc.w	$0008                           ; the tab size at the start (8)
default_extension:	; from: default_fsel_path
	dc.w	$5300,$0000                     ; the source extension the file selector shows: "S"
default_backups:	; from: menu_preferences, save_preferences, load_preferences, save_text_file
	dc.b	$00                             ; nonzero: keep the old file as a backup when saving
default_numeric_pad:	; from: gem_init
	dc.b	$01                             ; nonzero: the numeric pad gives numbers (zero: it moves the cursor)

;------------------------------------------------------------------------------
; Fill vdi_params with the addresses of the five VDI arrays.
;------------------------------------------------------------------------------
vdi_init_params:	; from: gem_init
	lea	vdi_params(a6),a1               ; the VDI parameter block
	lea	contrl(a6),a0                   ; contrl
	move.l	a0,(a1)+
	lea	intin(a6),a0                    ; intin
	move.l	a0,(a1)+
	lea	ptsin(a6),a0                    ; ptsin
	move.l	a0,(a1)+
	lea	intout(a6),a0                   ; intout
	move.l	a0,(a1)+
	lea	ptsout(a6),a0                   ; ptsout
	move.l	a0,(a1)+
	rts

;------------------------------------------------------------------------------
; Call the VDI function d0 on GenST's own workstation; the caller has set the counts and arrays.
;------------------------------------------------------------------------------
vdi_call:                                       ; from: prepare_tos_screen, restore_tos_screen, prepare_gem_program,
                                                ;   get_char_cell, no_window_quit, window_geometry, 13 more
	move.w	vdi_handle(a6),contrl_handle(a6) ; the workstation handle

;------------------------------------------------------------------------------
; Call the VDI function d0 with the handle the caller put in contrl[6].
;------------------------------------------------------------------------------
vdi_call_handle_set:                            ; from: prepare_gem_program, open_workstation, redraw_under_dialog,
                                                ;   appl_find_name, editor_set_clip, clear_text_area, 1 more
	move.w	d0,contrl(a6)                   ; the opcode
	lea	vdi_params(a6),a0               ; the parameter block
	move.l	a0,d1                           ; to d1
	moveq	#115,d0                         ; 115: VDI
	trap	#2                              ; VDI
	rts

;------------------------------------------------------------------------------
; Fill aes_params with the addresses of the AES arrays and clear the global array's pointer fields.
;------------------------------------------------------------------------------
aes_init_params:	; from: gem_init
	lea	aes_params(a6),a1               ; the AES parameter block
	lea	contrl(a6),a0                   ; control
	move.l	a0,(a1)+
	lea	aes_global(a6),a0               ; global
	clr.l	$a(a0)                          ; its pointer words cleared
	clr.l	$e(a0)
	clr.l	$12(a0)
	clr.l	$16(a0)
	clr.l	$1a(a0)
	move.l	a0,(a1)+
	lea	intin(a6),a0                    ; int_in
	move.l	a0,(a1)+
	lea	intout(a6),a0                   ; int_out
	move.l	a0,(a1)+
	lea	ptsin(a6),a0                    ; addr_in
	move.l	a0,(a1)+
	lea	ptsout(a6),a0                   ; addr_out
	move.l	a0,(a1)+
	rts

;------------------------------------------------------------------------------
; Call the AES function d0 (10 up) with int_in, addr_in and the rest already set: the control array's
; counts come from aes_sizes.  Returns int_out[0] in d0 with the flags set from it.
;------------------------------------------------------------------------------
aes_call:                                       ; from: editor_command_event, window_sized, editor_init,
                                                ;   open_found_file, set_gem_check, prepare_tos_screen, 30 more
	move.w	d0,contrl(a6)                   ; control[0]: the opcode
	subi.w	#$a,d0                          ; from 10
	mulu.w	#$3,d0                          ; 3 bytes each
	lea	aes_sizes(pc),a0                ; the sizes table
	adda.w	d0,a0                           ; the opcode's entry
	moveq	#0,d0
	move.b	(a0)+,d0                        ; int_in count
	move.w	d0,contrl_count(a6)             ; to control[1]
	move.b	(a0)+,d0                        ; int_out count
	move.w	d0,contrl_count_out(a6)         ; to control[2]
	move.b	(a0)+,d0                        ; addr_in count
	move.w	d0,contrl_intin_count(a6)       ; to control[3]
	clr.w	contrl_count_addrout(a6)        ; no addr_out
	cmpi.w	#$70,contrl(a6)                 ; rsrc_gaddr?
	bne.s	aes_call_trap                   ; no
	move.w	#$1,contrl_count_addrout(a6)    ; yes: one addr_out
aes_call_trap:
	lea	aes_params(a6),a0               ; the parameter block
	move.l	a0,d1                           ; to d1
	move.w	#$c8,d0                         ; 200: AES
	trap	#2                              ; AES
	move.w	intout(a6),d0                   ; int_out[0]
	rts
aes_sizes:
	dc.w	$0001,$0002,$0101,$0201,$0100,$0101,$0201,$0101 ; 3 bytes per AES opcode from 10 (appl_init) to 125: the
                                                ;   int_in, int_out and addr_in counts
	dc.w	$0101,$0000,$0000,$0000,$0000,$0000,$0100,$0001
	dc.w	$0003,$0500,$0505,$0000,$0101,$0201,$0010,$0701
	dc.w	$0201,$0000,$0000,$0000,$0000,$0000,$0101,$0102
	dc.w	$0101,$0201,$0102,$0101,$0101,$0201,$0101,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0201,$0101,$0101
	dc.w	$0601,$0104,$0101,$0103,$0102,$0101,$0402,$0108
	dc.w	$0101,$0000,$0000,$0000,$0101,$0109,$0100,$0101
	dc.w	$0101,$0100,$0005,$0103,$0301,$0202,$0100,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; opcodes 62-89 unused
	dcb.b	20,0
	dc.w	$0403,$0008,$0300,$0601,$0008,$0100,$0801,$0004 ; 90 fsel_input on
	dc.w	$0101,$0301,$0100,$0500,$0101,$0100,$0500,$0001
	dc.w	$0100,$0101,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0002,$0200
	dcb.b	26,0
	dc.w	$0501,$0005,$0100,$0101,$0001,$0100,$0205,$0006 ; 100 wind_create on
	dc.w	$0100,$0201,$0001,$0100,$0605,$0000,$0000,$0001
	dc.w	$0100,$0100,$0201,$0002,$0101,$0101,$0100,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0203
	dc.w	$0102,$0000,$0000,$0000,$0001,$0100,$0103 ; up to 125
startup:	; from: start
	movea.l	4(sp),a5                        ; the basepage
	lea	stack_top(a6),sp                ; GenST's own stack
	cmpi.l	#asm_entry,$10(a5)              ; the data start at $4924: an editor-only build
	sne	assembler_linked(a6)            ; else the assembler is in this image
	move.l	$c(a5),d0                       ; text length
	add.l	$14(a5),d0                      ; + data
	add.l	$1c(a5),d0                      ; + BSS
	addi.l	#$100,d0                        ; + the basepage
	move.l	d0,-(sp)                        ; the size to keep
	move.l	a5,-(sp)                        ; the block
	move.w	d0,-(sp)
	move.w	#$4a,-(sp)
	trap	#1                              ; Mshrink, Mshrink: give back the rest of memory
	move.l	a5,own_basepage(a6)             ; GenST's basepage
	tst.b	$80(a5)                         ; a command line?
	sne	command_line_given(a6)          ; noted
	bsr.w	gem_init                        ; start GEM: workstation, menu, window, resources
	lea	case_fold_code(a6),a1           ; the RAM copy of the case folding code
	lea	find_upper_case(pc),a0          ; from find_upper_case
	moveq	#8,d0                           ; 9 words
startup_copy_fold:
	move.w	(a0)+,(a1)+
	dbra	d0,startup_copy_fold
	bsr.w	editor_init                     ; the preferences, MonST
	bne.w	quit_editor
	moveq	#0,d0
	move.w	d0,find_string(a6)              ; no find string
	move.w	d0,replace_string(a6)           ; no replace string
	move.l	d0,block_start(a6)              ; no block start
	move.l	d0,block_end(a6)                ; no block end
	move.w	d0,file_name(a6)                ; no file name
	move.b	d0,block_shown(a6)              ; no block shown
	move.l	d0,block_copy(a6)               ; no remembered block
	move.w	d0,undo_line(a6)                ; no undo line
	move.w	d0,left_column(a6)              ; left column 0
	move.l	d0,text_start(a6)               ; no text buffer yet
	bsr.w	alloc_edit_buffer               ; take the text buffer and empty it
	bsr.w	reset_view                      ; one line, top line 0, the sliders
	pea	quit_no_memory(pc)              ; left on the stack (editor_loop resets sp)
	sf	text_modified(a6)               ; not modified
	st	text_touched(a6)
	clr.w	top_line_number(a6)             ; top line 0
	bsr.w	editor_cursor_home              ; cursor home
	movea.l	text_start(a6),a4               ; the first line
	move.l	a4,top_line(a6)                 ; is the top line
	bsr.w	clear_error_list                ; no errors
	tst.b	command_line_given(a6)          ; a command line?
	beq.s	editor_loop                     ; no
	bsr.w	editor_load_file                ; yes: load the file it names

;------------------------------------------------------------------------------
; The editor's main loop: every command ends by coming back here, which resets the stack.  Updates the
; status line, waits for an event (editor_wait_event leaves its kind in event_kind) and hands it on.
;------------------------------------------------------------------------------
editor_loop:	; from: aes_call, editor_key, key_cursor_left, key_cursor_right, key_cursor_up, key_cursor_down, 32 more
	lea	stack_top(a6),sp                ; the stack reset
	bsr.w	update_status_line              ; the status line's Line, Col and Mem
	bsr.w	get_event                       ; wait for an event
editor_dispatch_event:	; from: line_edit
	cmpi.w	#$3,event_type(a6)              ; a key?
	beq.s	editor_key                      ; yes
	cmpi.w	#$7,event_type(a6)              ; an Alt key command?
	beq.w	editor_alt_key                  ; yes
	cmpi.w	#$5,event_type(a6)              ; a menu item, click or window message?
	beq.w	editor_command_event            ; yes
	bsr.w	handle_message                  ; else the window's redraw and arrow messages
	bra.s	editor_loop                     ; again

;------------------------------------------------------------------------------
; A key in d1: the editing keys go to line_edit, the rest are cursor and block commands.  The codes from
; $e8 up are the function keys (F1-F5 and shifted) and Control with the cursor keys.
;------------------------------------------------------------------------------
editor_key:	; from: editor_loop, line_edit
	bsr.w	update_status_line              ; the status line
	cmp.b	#$d,d1                          ; Return?
	beq.w	key_return                      ; yes: split the line
	cmp.b	#$9,d1                          ; Tab?
	beq.w	line_edit                       ; yes: edit the line
	cmp.b	#$8,d1                          ; Backspace?
	beq.w	line_edit                       ; yes
	cmp.b	#$7f,d1                         ; Delete?
	beq.w	line_edit                       ; yes
	cmp.b	#$14,d1                         ; ^T?
	beq.w	menu_preferences                ; yes: the preferences
	cmp.b	#$15,d1                         ; ^U (and Undo)?
	beq.w	key_undo                        ; yes: put back the deleted line
	cmp.b	#$c0,d1                         ; a command code?
	bcc.s	editor_key_control              ; yes
	cmp.b	#$20,d1                         ; printable?
	bcc.w	line_edit                       ; yes: edit the line
editor_key_control:
	cmp.b	#$13,d1                         ; ^S (and left)?
	beq.w	key_cursor_left                 ; yes: cursor left
	cmp.b	#$4,d1                          ; ^D (and right)?
	beq.w	key_cursor_right                ; yes: cursor right
	cmp.b	#$5,d1                          ; ^E (and up)?
	beq.w	key_cursor_up                   ; yes: cursor up
	cmp.b	#$18,d1                         ; ^X (and down)?
	beq.w	key_cursor_down                 ; yes: cursor down
	cmp.b	#$1b,d1                         ; Esc?
	beq.w	redraw_and_loop                 ; yes: redraw the window
	cmp.b	#$12,d1                         ; ^R?
	beq.w	key_page_up                     ; yes: page up
	cmp.b	#$3,d1                          ; ^C?
	beq.w	key_page_down                   ; yes: page down
	cmp.b	#$19,d1                         ; ^Y?
	beq.w	key_delete_line                 ; yes: delete the line
	cmp.b	#$11,d1                         ; ^Q?
	beq.w	key_delete_to_end               ; yes: delete to the line's end
	cmp.b	#$e8,d1                         ; F1?
	beq.w	key_block_start                 ; yes: block start
	cmp.b	#$ec,d1                         ; F2?
	beq.w	key_block_end                   ; yes: block end
	cmp.b	#$f2,d1                         ; Shift-F5?
	beq.w	key_block_delete                ; yes: block delete
	cmp.b	#$f0,d1                         ; F3?
	beq.w	key_block_save                  ; yes: block save
	cmp.b	#$f4,d1                         ; F4?
	beq.w	key_block_copy                  ; yes: block copy
	cmp.b	#$fd,d1                         ; Control-left?
	beq.w	cursor_line_start               ; yes: the line's start
	cmp.b	#$fe,d1                         ; Control-right?
	beq.w	cursor_line_end                 ; yes: the line's end
	cmp.b	#$1,d1                          ; ^A?
	beq.w	key_word_left                   ; yes: word left
	cmp.b	#$6,d1                          ; ^F?
	beq.w	key_word_right                  ; yes: word right
	cmp.b	#$f8,d1                         ; F5?
	beq.w	key_block_paste                 ; yes: block paste
	cmp.b	#$f6,d1                         ; Shift-F4?
	beq.w	key_block_remember              ; yes: block remember
	bra.w	editor_loop                     ; else nothing

;------------------------------------------------------------------------------
; ^S: cursor left one character, past a whole tab; at column 0 to the end of the line above when the
; preferences say Wrap.
;------------------------------------------------------------------------------
key_cursor_left:	; from: editor_key
	tst.w	d6                              ; column 0?
	beq.s	key_left_wrap                   ; yes
	subq.w	#1,d6                           ; one left
	move.w	d6,-(sp)
	bsr.w	cursor_char                     ; what is there
	movem.w	(sp)+,d6                        ; (the flags kept)
	bgt.s	key_cursor_left                 ; inside a tab: on left
	bsr.w	editor_cursor_visible           ; placed
	bra.w	editor_loop
key_left_wrap:
	tst.b	end_of_line_wrap(a6)            ; Wrap?
	beq.w	editor_loop                     ; no: stay
	tst.w	d7                              ; the top row?
	beq.s	key_left_wrap_scroll            ; yes
	subq.w	#1,d7                           ; the row above
	bsr.w	text_prev_line                  ; its line
	bra.w	cursor_line_end                 ; to its end
key_left_wrap_scroll:
	tst.w	top_line_number(a6)             ; the file's first line?
	beq.w	show_top_of_file                ; yes: "Top of file"
	subq.w	#1,top_line_number(a6)          ; the window one line back
	bsr.w	scroll_to_previous_line         ; scrolled
	bsr.w	redraw_cursor_line              ; the line drawn
	bra.w	cursor_line_end                 ; to its end

;------------------------------------------------------------------------------
; ^D: cursor right one character (past a tab); at the end of the line on to the next line's start when the
; preferences say Wrap, else up to column 255.
;------------------------------------------------------------------------------
key_cursor_right:	; from: editor_key
	tst.b	end_of_line_wrap(a6)            ; Wrap?
	beq.s	key_right_step                  ; no
	move.w	d6,-(sp)
	bsr.w	cursor_char                     ; what is under the cursor
	movem.w	(sp)+,d6
	bmi.s	key_right_wrap                  ; past the end: wrap
	cmpi.b	#$d,(a1)                        ; the line's end?
	bne.s	key_right_step                  ; no
key_right_wrap:
	cmp.w	last_row(a6),d7                 ; the bottom row?
	beq.s	key_right_wrap_scroll           ; yes: scroll
	bsr.w	text_next_line                  ; the next line
	bne.w	show_end_of_file                ; none: "End of file"
	addq.w	#1,d7                           ; the row below
	moveq	#0,d6                           ; column 0
	bra.s	key_right_place
key_right_step:
	cmp.w	#$ff,d6                         ; column 255?
	beq.s	key_right_done                  ; yes: no further
	addq.w	#1,d6                           ; one right
	bsr.w	cursor_char                     ; to a tab's end
key_right_place:
	bsr.w	editor_cursor_visible           ; the cursor placed
key_right_done:
	bra.w	editor_loop
key_right_wrap_scroll:
	bsr.w	text_next_line                  ; the next line
	bne.w	show_end_of_file                ; none: "End of file"
	moveq	#0,d6                           ; column 0
	bsr.w	editor_cursor_visible           ; placed
	bra.w	key_down_scroll_done            ; the window one line on

;------------------------------------------------------------------------------
; ^E: cursor up a line, scrolling the window at its top row.
;------------------------------------------------------------------------------
key_cursor_up:	; from: editor_key
	tst.w	d7                              ; the top row?
	beq.s	key_up_scroll                   ; yes
	subq.w	#1,d7                           ; the row above
	bsr.w	editor_cursor_visible           ; placed
	bsr.w	text_prev_line                  ; its line
	bra.w	editor_loop
key_up_scroll:
	tst.w	top_line_number(a6)             ; the file's first line?
	beq.w	show_top_of_file                ; yes: "Top of file"
	subq.w	#1,top_line_number(a6)          ; one line back
	bsr.w	scroll_to_previous_line         ; scrolled
	bsr.w	redraw_cursor_line              ; the line drawn
	bra.w	editor_loop

;------------------------------------------------------------------------------
; ^X: cursor down a line, scrolling the window at its bottom row.
;------------------------------------------------------------------------------
key_cursor_down:	; from: editor_key
	cmp.w	last_row(a6),d7                 ; the bottom row?
	beq.w	key_down_scroll                 ; yes
	bsr.w	text_next_line                  ; the next line
	bne.w	show_end_of_file                ; none: "End of file"
	addq.w	#1,d7                           ; the row below
	bsr.w	editor_cursor_visible           ; placed
	bra.w	editor_loop

;------------------------------------------------------------------------------
; Control-left: the cursor to the line's start.
;------------------------------------------------------------------------------
cursor_line_start:	; from: editor_key, word_left_prev_char
	moveq	#0,d6                           ; column 0
	bsr.w	editor_cursor_visible           ; placed
	bra.w	editor_loop

;------------------------------------------------------------------------------
; Control-right: the cursor to the line's end.
;------------------------------------------------------------------------------
cursor_line_end:	; from: editor_key, key_cursor_left, key_word_right, word_right_next_char, key_word_left
	movea.l	a4,a1                           ; from the line's start
cursor_line_end_find:
	cmpi.b	#$d,(a1)+                       ; the CR?
	bne.s	cursor_line_end_find            ; no
	subq.l	#1,a1                           ; on it
	bsr.w	set_cursor_column               ; the cursor there
	bra.w	editor_loop

;------------------------------------------------------------------------------
; ^F: the cursor to the start of the next word (past the rest of this one and the spaces and tabs after
; it); at the line's end it stops there.
;------------------------------------------------------------------------------
key_word_right:	; from: editor_key
	bsr.w	cursor_char                     ; what is under the cursor
	bmi.s	cursor_line_end                 ; past the end: to the end
	bsr.s	word_right_next_char            ; a space?
	beq.s	word_right_skip_space           ; yes: past the spaces only
word_right_skip_word:
	bsr.s	word_right_next_char            ; the rest of the word
	bne.s	word_right_skip_word
word_right_skip_space:
	bsr.s	word_right_next_char            ; then the spaces
	beq.s	word_right_skip_space
	subq.l	#1,a1                           ; back to the word's start
	bsr.w	set_cursor_column               ; the cursor there
	bra.w	editor_loop

;------------------------------------------------------------------------------
; The next character from a1 for word right: Z set on a space or tab; at the CR the command ends at the
; line's end.
;------------------------------------------------------------------------------
word_right_next_char:	; from: key_word_right
	move.b	(a1)+,d1                        ; a character
	cmp.b	#$d,d1                          ; the CR?
	beq.s	word_right_at_end               ; yes
	cmp.b	#$20,d1                         ; a space?
	beq.s	word_right_char_done            ; yes: Z
	cmp.b	#$9,d1                          ; a tab?
word_right_char_done:
	rts
word_right_at_end:
	addq.l	#4,sp                           ; off the caller
	bra.s	cursor_line_end                 ; to the line's end

;------------------------------------------------------------------------------
; ^A: the cursor to the start of the word before it; at the line's start it stops there.
;------------------------------------------------------------------------------
key_word_left:	; from: editor_key
	bsr.w	cursor_char                     ; what is under the cursor
	bmi.s	cursor_line_end                 ; past the end: to the end
word_left_skip_space:
	bsr.s	word_left_prev_char             ; back past the spaces
	beq.s	word_left_skip_space
word_left_skip_word:
	bsr.s	word_left_prev_char             ; then the word
	bne.s	word_left_skip_word
	addq.l	#1,a1                           ; the word's first character
	bsr.w	set_cursor_column               ; the cursor there
	bra.w	editor_loop

;------------------------------------------------------------------------------
; The character before a1 for word left: Z set on a space or tab; at the line's or text's start the
; command ends at the line's start.
;------------------------------------------------------------------------------
word_left_prev_char:	; from: key_word_left
	move.b	-(a1),d1                        ; a character back
	cmpa.l	text_start(a6),a1               ; the text's start?
	bls.s	word_left_at_start              ; yes
	cmp.b	#$d,d1                          ; the line before's CR?
	beq.s	word_left_at_start              ; yes
	cmp.b	#$20,d1                         ; a space?
	beq.s	word_left_char_done             ; yes: Z
	cmp.b	#$9,d1                          ; a tab?
word_left_char_done:
	rts
word_left_at_start:
	addq.l	#4,sp                           ; off the caller
	bra.w	cursor_line_start               ; to the line's start

;------------------------------------------------------------------------------
; Show "End of file" (or the message at a1 from show_editor_message) with a bell and go back to the loop.
;------------------------------------------------------------------------------
show_end_of_file:	; from: key_cursor_right, key_cursor_down, key_page_down
	lea	msg_end_of_file(pc),a1          ; "End of file"
show_editor_message:
	bsr.w	message_beep                    ; shown, with a bell
	bra.w	editor_loop
show_top_of_file:	; from: key_cursor_left, key_cursor_up, key_page_up
	lea	msg_top_of_file(pc),a1          ; "Top of file"
	bra.s	show_editor_message
msg_top_of_file:
	dc.w	$000b                           ; its length
	dc.b	'Top of file',0
key_down_scroll:	; from: key_cursor_down
	bsr.w	text_next_line                  ; the next line
	bne.s	show_end_of_file                ; none: "End of file"
key_down_scroll_done:	; from: key_cursor_right
	bsr.s	window_scroll_forward           ; the window one line on
	bra.w	editor_loop

;------------------------------------------------------------------------------
; Move the window one line further into the text: the top line on by one, the window's contents scrolled
; up and the cursor's line drawn.
;------------------------------------------------------------------------------
window_scroll_forward:	; from: show_end_of_file
	addq.w	#1,top_line_number(a6)          ; the top line's number
	move.l	a4,-(sp)
	movea.l	top_line(a6),a4                 ; the top line
	bsr.w	text_next_line                  ; on one
	move.l	a4,top_line(a6)
	movea.l	(sp)+,a4
	bsr.w	scroll_text_up                  ; scrolled up
	bra.w	redraw_cursor_line              ; the cursor's line drawn

;------------------------------------------------------------------------------
; ^R: a window less one line back; at the file's start the cursor goes to its first line.
;------------------------------------------------------------------------------
key_page_up:	; from: editor_key
	tst.w	top_line_number(a6)             ; the top line the first?
	bne.s	page_up_move                    ; no
	tst.w	d7                              ; the cursor on the top row?
	bne.s	page_up_first_row               ; no: to the top row
	beq.s	show_top_of_file                ; yes: "Top of file"
page_up_move:
	move.w	last_row(a6),d5                 ; a window's lines less one
	cmp.w	top_line_number(a6),d5          ; more than there are above?
	bcc.s	page_up_to_top                  ; yes: to the file's start
	sub.w	d5,top_line_number(a6)          ; the new top line number
	subq.w	#1,d5
page_up_loop:
	bsr.w	text_prev_line                  ; the cursor's line back
	bsr.s	top_line_back                   ; the top line back
	dbra	d5,page_up_loop
editor_redraw_window:	; from: key_page_down, key_block_delete, key_block_copy, menu_preferences
	movem.l	d6-d7/a4,-(sp)
	bsr.w	redraw_text                     ; the window drawn
	movem.l	(sp)+,d6-d7/a4
editor_cursor_placed:	; from: top_line_back
	bsr.w	editor_cursor_visible           ; the cursor placed
	bra.w	editor_loop
page_up_to_top:
	move.w	top_line_number(a6),d5          ; the lines above the top line
	clr.w	top_line_number(a6)             ; now 0
	subq.w	#1,d5
	move.w	d5,d4
page_up_top_loop:
	bsr.s	top_line_back                   ; the top line back
	dbra	d5,page_up_top_loop
	move.w	d4,d5
page_up_cursor_loop:
	bsr.w	text_prev_line                  ; the cursor's line back as far
	dbra	d5,page_up_cursor_loop
	bra.s	editor_redraw_window

;------------------------------------------------------------------------------
; The top line one line back (a4 kept).
;------------------------------------------------------------------------------
top_line_back:	; from: key_page_up
	move.l	a4,-(sp)
	movea.l	top_line(a6),a4                 ; the top line
	bsr.w	text_prev_line                  ; back one
	move.l	a4,top_line(a6)
	movea.l	(sp)+,a4
	rts
page_up_first_row:	; from: key_page_up
	moveq	#0,d7                           ; the top row
	movea.l	text_start(a6),a4               ; the first line
	bra.s	editor_cursor_placed

;------------------------------------------------------------------------------
; ^C: a window less one line on; near the end as many lines as there are, "End of file" when none.
;------------------------------------------------------------------------------
key_page_down:	; from: editor_key
	move.w	last_row(a6),d5                 ; a window's lines less one
	movea.l	a4,a2                           ; the cursor's line kept
	move.w	d5,d4
	subq.w	#1,d5
page_down_cursor_loop:
	bsr.w	text_next_line                  ; the cursor's line on
	bne.s	page_down_short                 ; the end reached
	dbra	d5,page_down_cursor_loop
	add.w	d4,top_line_number(a6)          ; the new top line number
	move.w	d4,d5
	subq.w	#1,d5
	movea.l	a4,a2                           ; the cursor's new line
	movea.l	top_line(a6),a4                 ; the top line
page_down_top_loop:
	bsr.w	text_next_line                  ; on as far
	dbra	d5,page_down_top_loop
	move.l	a4,top_line(a6)
	subq.w	#1,d4
	movea.l	a2,a4                           ; the cursor's line
	bra.s	editor_redraw_window            ; redraw
page_down_short:
	move.w	d4,d0                           ; the lines moved
	subq.w	#1,d0
	sub.w	d5,d0
	beq.s	page_down_none                  ; none
	movea.l	a4,a2                           ; the cursor's line kept
	subq.w	#1,d0
	move.w	d0,d3
	movea.l	top_line(a6),a4                 ; the top line
page_down_short_loop:
	bsr.w	text_next_line                  ; on one
	addq.w	#1,top_line_number(a6)
	dbra	d3,page_down_short_loop
	move.l	a4,top_line(a6)
	movea.l	a2,a4
	bra.w	editor_redraw_window            ; redraw
page_down_none:
	movea.l	a2,a4                           ; the cursor's line as it was
	bra.w	show_end_of_file                ; "End of file"

;------------------------------------------------------------------------------
; ^Y: delete the cursor's line, keeping it for ^U; the last line (the one with no CR of its own) is only
; emptied.
;------------------------------------------------------------------------------
key_delete_line:	; from: editor_key
	movea.l	a4,a2
	moveq	#0,d1                           ; its length with the CR
delete_line_length:
	addq.l	#1,d1
	cmpi.b	#$d,(a2)+
	bne.s	delete_line_length
	cmpa.l	text_end(a6),a2                 ; the end's own CR?
	bhi.s	delete_line_last                ; yes: only empty it
	bsr.w	save_undo_line                  ; kept for undo
	subq.w	#1,line_count(a6)               ; one line fewer
	bne.s	delete_line_remove
	addq.w	#1,line_count(a6)               ; but at least one
delete_line_remove:
	movea.l	a4,a3
	bsr.w	text_delete_bytes               ; removed

;------------------------------------------------------------------------------
; The cursor's line is gone from the window: scroll the lines below it up, clear and draw the bottom row's
; line, then draw the cursor's line.
;------------------------------------------------------------------------------
editor_close_line_gap:	; from: line_edit
	bsr.w	scroll_close_line               ; scrolled up below the cursor
	bsr.w	clear_bottom_line               ; the bottom row cleared
	bsr.w	redraw_cursor_line              ; the cursor's line drawn
	movem.l	d6-d7/a4,-(sp)
	move.w	d7,d5                           ; from the cursor's row
	move.w	last_row(a6),d7                 ; to the bottom row
	bsr.w	editor_cursor_visible
close_gap_find_last:
	cmp.w	last_row(a6),d5                 ; the bottom row reached?
	beq.s	close_gap_draw_last             ; yes: draw it
	addq.w	#1,d5
	bsr.w	text_next_line                  ; the next line
	beq.s	close_gap_find_last
close_gap_done:
	movem.l	(sp)+,d6-d7/a4
	bsr.w	editor_cursor_visible           ; the cursor placed
	bra.w	editor_loop
close_gap_draw_last:
	bsr.w	redraw_cursor_line              ; the bottom row's line drawn
	bra.s	close_gap_done
delete_line_last:	; from: key_delete_line
	moveq	#0,d6                           ; column 0
	bsr.w	editor_cursor_visible           ; placed

;------------------------------------------------------------------------------
; ^Q: delete from the cursor to the line's end, keeping the line for ^U.
;------------------------------------------------------------------------------
key_delete_to_end:	; from: editor_key
	bsr.w	save_undo_line                  ; kept for undo
	move.w	d6,-(sp)
	bsr.w	cursor_char                     ; what is under the cursor
	movem.w	(sp)+,d6                        ; (the flags kept)
	bmi.w	editor_loop                     ; past the end: nothing
	moveq	#-1,d1
	movea.l	a1,a3                           ; from here
delete_to_end_count:
	addq.l	#1,d1
	cmpi.b	#$d,(a1)+                       ; up to the CR
	bne.s	delete_to_end_count
	tst.l	d1                              ; anything?
	beq.w	editor_loop                     ; no
	bsr.w	text_delete_bytes               ; deleted
	bsr.w	redraw_cursor_line              ; the line drawn
	bra.w	editor_loop

;------------------------------------------------------------------------------
; F1: the block starts at the cursor.
;------------------------------------------------------------------------------
key_block_start:	; from: editor_key
	bsr.w	cursor_char                     ; where the cursor is
	move.l	a1,block_start(a6)              ; the block's start
block_marks_changed:	; from: key_block_end
	move.l	block_start(a6),d0              ; a start?
	beq.s	block_marks_hidden              ; no
	move.l	block_end(a6),d1                ; an end?
	beq.s	block_marks_hidden              ; no
	cmp.l	d1,d0                           ; after the start?
	bcc.s	block_marks_hidden              ; no
	st	block_shown(a6)                 ; yes: shown
block_marks_redraw:
	bsr.w	redraw_window                   ; the window drawn again
	bra.w	editor_loop
block_marks_hidden:
	move.b	block_shown(a6),d0              ; was it shown?
	sf	block_shown(a6)                 ; not any more
	tst.b	d0
	bne.s	block_marks_redraw              ; yes: drawn without it
	bra.w	editor_loop

;------------------------------------------------------------------------------
; F2: the block ends at the cursor.
;------------------------------------------------------------------------------
key_block_end:	; from: editor_key
	bsr.w	cursor_char                     ; where the cursor is
	move.l	a1,block_end(a6)                ; the block's end
	bra.s	block_marks_changed

;------------------------------------------------------------------------------
; Return when a block is marked (both marks set, the start before the end); else show "What blocks!" and
; go back to the loop.
;------------------------------------------------------------------------------
editor_check_block:	; from: key_block_delete, key_block_save, key_block_copy, key_block_remember, cmd_print_block
	move.l	block_start(a6),d0              ; a start?
	beq.s	check_block_bad                 ; no
	tst.l	block_end(a6)                   ; an end?
	beq.s	check_block_bad                 ; no
	cmp.l	block_end(a6),d0                ; the start first?
	bcc.s	check_block_bad                 ; no
	rts
check_block_bad:
	lea	msg_what_blocks(pc),a1          ; "What blocks!"
	bsr.w	message_beep                    ; shown
	bra.w	editor_loop
msg_what_blocks:
	dc.w	$000c                           ; its length
	dc.b	'What blocks!'

;------------------------------------------------------------------------------
; Shift-F5: remember the block and delete it from the text; the marks go and the cursor stays on the same
; text (or the block's start when it was inside it).
;------------------------------------------------------------------------------
key_block_delete:	; from: editor_key
	bsr.s	editor_check_block              ; a block?
	bsr.w	cursor_char                     ; where the cursor is
	move.l	a1,-(sp)
	movea.l	block_start(a6),a3              ; the block's start
	move.l	block_end(a6),d1
	sub.l	a3,d1                           ; its length
	bsr.w	remember_block                  ; remembered
	bne.w	editor_loop                     ; no memory and not deleted
	bsr.w	text_delete_bytes               ; deleted
	clr.l	block_start(a6)                 ; no block start
	move.l	block_end(a6),d3                ; the end, moved back to the start
	add.l	d1,d3                           ; the old end
	clr.l	block_end(a6)                   ; no block end
	sf	block_shown(a6)                 ; not shown
	bsr.w	text_count_lines                ; the lines counted
	movea.l	(sp)+,a1                        ; the cursor
	cmpa.l	a3,a1                           ; before the block?
	bcs.w	editor_redraw_window            ; yes: redraw
	beq.w	editor_redraw_window
	cmpa.l	d3,a1                           ; after it?
	bcc.s	block_delete_after              ; yes
	movea.l	a3,a1                           ; in it: to its start
	bra.s	block_delete_place
block_delete_after:
	suba.l	d1,a1                           ; back by the block's length
block_delete_place:
	movea.l	a1,a4
	bsr.w	text_line_start                 ; its line
	move.w	d6,-(sp)
	bsr.w	show_cursor_line                ; shown in the window
	move.w	(sp)+,d6
	bsr.w	editor_cursor_visible           ; the cursor placed
	bra.w	editor_loop

;------------------------------------------------------------------------------
; F3: save the block to a file the file selector names; the text's modified flag stays as it was.
;------------------------------------------------------------------------------
key_block_save:	; from: editor_key
	bsr.w	editor_check_block              ; a block?
	clr.w	selector_name(a6)               ; no name offered
	bsr.w	select_save_block               ; "Save a block"
	bne.s	block_command_done              ; cancelled
	movea.l	block_start(a6),a3              ; the block
	move.l	block_end(a6),d1
	sub.l	a3,d1                           ; its length
	beq.s	block_command_done              ; none
	move.b	text_modified(a6),d0            ; the modified flag
	move.w	d0,-(sp)                        ; kept
	moveq	#-1,d0                          ; -1: a block, no backup
	bsr.w	save_text_file                  ; written
	move.w	(sp)+,d0
	move.b	d0,text_modified(a6)            ; as it was
block_command_done:	; from: key_block_copy, key_block_paste
	clr.w	selector_name(a6)               ; the name cleared
	bra.w	editor_loop

;------------------------------------------------------------------------------
; F4: copy the block to the cursor; not into the block itself ("Invalid block").
;------------------------------------------------------------------------------
key_block_copy:	; from: editor_key
	bsr.w	cursor_char                     ; where the cursor is
	bsr.w	editor_check_block              ; a block?
	cmpa.l	block_start(a6),a1              ; before it?
	bcs.s	block_copy_insert               ; yes
	cmpa.l	block_end(a6),a1                ; after it?
	bcc.s	block_copy_insert               ; yes
	lea	msg_invalid_block(pc),a1        ; "Invalid block"
	bsr.w	message_beep                    ; shown
	bra.w	editor_loop
block_copy_insert:
	movea.l	a1,a3                           ; at the cursor
	move.l	block_end(a6),d1                ; the block's length
	sub.l	block_start(a6),d1
	bsr.w	text_make_room                  ; room made
	bne.s	block_command_done              ; no memory
	movea.l	block_start(a6),a0              ; the block's start, moved if after
block_copy_bytes:	; from: key_block_paste
	subq.l	#1,d1                           ; all?
	bcs.s	block_copy_done                 ; yes
	move.b	(a0)+,(a3)+                     ; a byte
	bra.s	block_copy_bytes
block_copy_done:
	bsr.w	text_count_lines                ; the lines counted
	bra.w	editor_redraw_window            ; redraw

;------------------------------------------------------------------------------
; F5: insert the remembered block at the cursor.
;------------------------------------------------------------------------------
key_block_paste:	; from: editor_key
	tst.l	block_copy(a6)                  ; one remembered?
	beq.w	editor_loop                     ; no
	bsr.w	cursor_char                     ; where the cursor is
	movea.l	a1,a3
	move.l	remembered_length(a6),d1        ; its length
	bsr.w	text_make_room                  ; room made
	bne.s	block_command_done              ; no memory
	movea.l	block_copy(a6),a0               ; the remembered copy
	bra.s	block_copy_bytes                ; copied

;------------------------------------------------------------------------------
; Shift-F4: copy the block into memory for F5.
;------------------------------------------------------------------------------
key_block_remember:	; from: editor_key
	bsr.w	editor_check_block              ; a block?
	move.l	block_end(a6),d1                ; its end
	movea.l	block_start(a6),a3              ; its start
	sub.l	a3,d1                           ; its length
	bsr.w	remember_block                  ; remembered
	bra.w	editor_loop
msg_invalid_block:	; from: key_block_copy
	dc.b	$00                             ; its length word
	dc.b	13,'Invalid block',0

;------------------------------------------------------------------------------
; Alt-W: print the lines of the block, or of the whole file when no block is marked.
;------------------------------------------------------------------------------
cmd_print_block:	; from: editor_alt_key
	move.l	block_start(a6),d0              ; any mark?
	or.l	block_end(a6),d0
	beq.s	print_whole_file                ; no: the whole file
	bsr.w	editor_check_block              ; a block?
	move.l	a4,-(sp)
	movea.l	block_end(a6),a4                ; its end
	bsr.w	text_prev_line                  ; the line its last character is on
	movea.l	a4,a3                           ; the last line to print
	movea.l	block_start(a6),a4              ; its start
print_block_lines:
	bsr.w	text_line_start                 ; from its line's start
	bsr.w	print_block                     ; printed
	movea.l	(sp)+,a4
print_block_done:
	rts
print_whole_file:
	move.l	text_end(a6),d0                 ; the end
	cmp.l	text_start(a6),d0               ; anything?
	beq.s	print_block_done                ; no
	move.l	a4,-(sp)
	movea.l	d0,a4
	bsr.w	text_prev_line                  ; the last line
	movea.l	a4,a3                           ; the last line to print
	movea.l	text_start(a6),a4               ; from the first
	bra.s	print_block_lines

;------------------------------------------------------------------------------
; A menu item, mouse click or window message (event_code: 1 menu, 2 click, else the AES message number,
; event_item the item or the window).  WM_TOPPED puts the window on top.
;------------------------------------------------------------------------------
editor_command_event:	; from: editor_loop
	move.w	event_code(a6),d0               ; what
	cmp.w	#$15,d0                         ; WM_TOPPED?
	bne.s	command_menu                    ; no
	move.w	event_item(a6),d0               ; the window
	cmp.w	window_handle(a6),d0            ; ours?
	bne.w	editor_loop                     ; no
	move.w	d0,intin(a6)                    ; wind_set
	move.w	#$a,intin1(a6)                  ; WF_TOP
	move.w	d0,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
	bsr.w	draw_status_line                ; the status line drawn
	move.w	#$0,output_mode(a6)             ; output to the window
	bra.w	editor_loop
command_menu:
	cmp.w	#$1,d0                          ; a menu item?
	bne.w	command_mouse                   ; no
	move.w	event_item(a6),d1               ; which
	cmp.w	#$16,d1                         ; 22 Save?
	beq.s	command_menu_save               ; yes
	cmp.w	#$27,d1                         ; 39 Replace All?
	beq.w	command_menu_replace_all        ; yes
	cmp.w	#$38,d1                         ; 56 Run Other?
	beq.w	menu_run_other                  ; yes
	cmp.w	#$1c,d1                         ; 28 Delete File?
	beq.w	cmd_delete_file                 ; yes
	cmp.w	#$a,d1                          ; 10 About?
	bne.s	command_menu_done               ; no
	bsr.w	about_dialog                    ; yes: the About box
command_menu_done:
	bra.w	editor_loop
command_menu_replace_all:
	bsr.w	replace_all                     ; replace them all
	bra.s	command_menu_done

;------------------------------------------------------------------------------
; Save (Shift-Alt-S): save under the file's name, or through Save As when it has none.
;------------------------------------------------------------------------------
command_menu_save:	; from: editor_command_event
	pea	editor_loop(pc)                 ; back to the loop after
	tst.b	file_name(a6)                   ; a name?
	beq.w	cmd_save_as                     ; no: Save As
	bsr.w	selector_from_file              ; the selector's path and name from it
	bra.w	editor_save_text                ; written

;------------------------------------------------------------------------------
; A click in the text: the cursor to the character under the mouse.
;------------------------------------------------------------------------------
command_mouse:	; from: editor_command_event
	cmp.w	#$2,d0                          ; a click?
	bne.w	command_window                  ; no
	movem.w	click_x(a6),d0-d1               ; where
	sub.w	text_x(a6),d0                   ; the column's pixels
	bcc.s	mouse_column
	moveq	#0,d0                           ; left of the text: 0
mouse_column:
	andi.l	#$ffff,d0
	divu.w	char_width(a6),d0               ; the column
	sub.w	text_top(a6),d1                 ; the row's pixels
	andi.l	#$ffff,d1
	divu.w	char_height(a6),d1              ; the row
	cmp.w	window_columns(a6),d0           ; past the width?
	bcc.w	editor_loop                     ; yes: nothing
	cmp.w	last_row(a6),d1                 ; past the bottom row?
	bhi.w	editor_loop                     ; yes: nothing
	move.w	d6,d4
	move.w	left_column(a6),d6
	add.w	d0,d6                           ; the column in the text
	sub.w	d7,d1                           ; rows to move
	beq.s	mouse_place                     ; none
	bpl.s	mouse_down                      ; down
	neg.w	d1                              ; up
	subq.w	#1,d1
mouse_up_loop:
	subq.w	#1,d7
	bsr.w	text_prev_line                  ; a line back
	dbra	d1,mouse_up_loop
	bra.s	mouse_place
mouse_down:
	subq.w	#1,d1
mouse_down_loop:
	bsr.w	text_next_line                  ; a line on
	bne.s	mouse_place                     ; the end: stop
	addq.w	#1,d7
	dbra	d1,mouse_down_loop
mouse_place:
	bsr.w	editor_place_cursor             ; the cursor placed
	bra.w	editor_loop
command_window:
	cmp.w	#$1b,d0                         ; WM_SIZED?
	beq.s	window_sized                    ; yes
	cmp.w	#$1c,d0                         ; WM_MOVED?
	bne.s	window_check_fulled             ; no

;------------------------------------------------------------------------------
; WM_SIZED and WM_MOVED (and WM_FULLED from below): set the window's new place and size, at least 37
; columns by 10 lines, work out the text area again and redraw it all.
;------------------------------------------------------------------------------
window_sized:	; from: command_mouse
	move.w	message_window(a6),d0           ; the window
	cmp.w	window_handle(a6),d0            ; ours?
	bne.w	editor_loop                     ; no
	movem.w	message_values(a6),d0-d3        ; the new x, y, w and h
window_set_size:	; from: window_check_fulled
	bsr.w	limit_window_size               ; not below the least size
	move.w	window_handle(a6),intin(a6)     ; wind_set
	move.w	#$5,intin1(a6)                  ; WF_CURRXYWH
	movem.w	d0-d3,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
	bsr.w	window_geometry                 ; the work area and text area
	bsr.w	editor_cursor_home              ; cursor home
	bsr.w	clip_to_window                  ; the clip area
	bsr.w	update_sliders                  ; the slider's size
	bsr.w	redraw_whole_window             ; the window redrawn
	move.w	#$0,output_mode(a6)             ; output to the window
	movea.l	top_line(a6),a4                 ; the top line is the cursor's
	bra.w	editor_loop

;------------------------------------------------------------------------------
; WM_FULLED: between the full size and the size before it.
;------------------------------------------------------------------------------
window_check_fulled:	; from: command_mouse
	cmp.w	#$17,d0                         ; WM_FULLED?
	bne.s	window_check_vslid              ; no
	move.w	window_handle(a6),d1
	moveq	#7,d0                           ; WF_FULLXYWH
	bsr.w	window_get                      ; wind_get
	move.l	intout1(a6),-(sp)               ; the full size
	move.l	intout3(a6),-(sp)
	move.w	window_handle(a6),d1
	moveq	#5,d0                           ; WF_CURRXYWH
	bsr.w	window_get                      ; wind_get
	movem.l	intout1(a6),d0-d1               ; the size now
	cmp.l	(sp),d1                         ; full already?
	bne.s	window_full_size                ; no
	cmp.l	4(sp),d0
	bne.s	window_full_size                ; no
	addq.l	#8,sp
	movem.w	window_previous(a6),d0-d3       ; yes: the size before
	bra.s	window_set_size
window_full_size:
	movem.l	d0-d1,window_previous(a6)       ; the size before, kept
	moveq	#7,d0                           ; WF_FULLXYWH
	move.w	window_handle(a6),d1
	bsr.w	window_get                      ; wind_get
	movem.w	intout1(a6),d0-d3               ; full
	addq.l	#8,sp
	bra.w	window_set_size

;------------------------------------------------------------------------------
; WM_VSLID: to the line the slider's place (0-1000) stands for.
;------------------------------------------------------------------------------
window_check_vslid:	; from: window_check_fulled
	cmp.w	#$1a,d0                         ; WM_VSLID?
	bne.s	window_check_arrowed            ; no
	move.w	message_window(a6),d0           ; the window
	cmp.w	window_handle(a6),d0            ; ours?
	bne.w	editor_loop                     ; no
	move.w	message_values(a6),d0           ; the place
	bne.s	vslid_line
	moveq	#1,d0                           ; at least 1
vslid_line:
	mulu.w	line_count(a6),d0               ; by the lines
	subq.l	#1,d0
	divu.w	#$3e7,d0                        ; over 999: the line
	moveq	#-1,d4                          ; high word -1: no "End of file"
	move.w	d0,d4
	bmi.w	editor_loop
	bne.s	vslid_goto
	addq.w	#1,d4                           ; line 0 is line 1
vslid_goto:
	bsr.w	editor_goto_line                ; to the line
window_message_done:	; from: window_check_arrowed
	bra.w	editor_loop

;------------------------------------------------------------------------------
; WM_HSLID: the left column from the slider (0-255 in steps of 16); WM_ARROWED here is page left or right.
;------------------------------------------------------------------------------
window_check_arrowed:	; from: window_check_vslid
	cmp.w	#$18,d0                         ; WM_ARROWED?
	beq.s	arrowed_page_sideways           ; yes
	cmp.w	#$19,d0                         ; WM_HSLID?
	bne.s	window_message_done             ; no
	move.w	message_window(a6),d0           ; the window
	cmp.w	window_handle(a6),d0            ; ours?
	bne.s	window_message_done             ; no
	moveq	#0,d0
	move.w	message_values(a6),d0           ; the place
	bne.s	hslid_column
	moveq	#1,d0                           ; at least 1
hslid_column:
	subq.w	#1,d0
	lsl.l	#8,d0                           ; times 256
	divu.w	#$3e7,d0                        ; over 999: the column
	cmp.w	#$100,d0                        ; over 255?
	bcs.s	hscroll_set                     ; no
	move.w	#$ff,d0                         ; yes: 255
hscroll_set:
	andi.w	#$fff0,d0                       ; in steps of 16
	cmp.w	left_column(a6),d0              ; the same?
	beq.s	window_message_done             ; yes: nothing
	move.w	d0,left_column(a6)              ; the new left column
	move.w	d0,d6                           ; the cursor there
	beq.s	hscroll_redraw
	addi.w	#$10,d6                         ; or 16 in from it
hscroll_redraw:
	movem.l	d6-d7/a4,-(sp)
	bsr.w	redraw_text                     ; the window drawn
	movem.l	(sp)+,d6-d7/a4
	bsr.w	editor_place_cursor             ; the cursor placed
	bra.s	arrowed_page_done
arrowed_page_sideways:
	moveq	#-4,d2                          ; the width less 4
	add.w	window_columns(a6),d2
	move.w	left_column(a6),d1              ; the left column
	subq.w	#4,message_values(a6)           ; page left (4)?
	bne.s	arrowed_page_right              ; no: right
	cmp.w	d2,d6                           ; the cursor near the left?
	bcs.s	arrowed_page_left_edge          ; yes: to column 0
	sub.w	d2,d1                           ; back a page
	bcc.s	arrowed_page_column
arrowed_page_left_edge:
	moveq	#0,d1                           ; the left column 0
	moveq	#0,d6                           ; the cursor too
arrowed_page_column:
	move.w	d1,d0
	bra.s	hscroll_set                     ; set it
arrowed_page_done:
	bra.w	editor_loop
arrowed_page_right:
	move.w	d6,d0                           ; the cursor a page on
	add.b	d2,d0
	bcs.s	arrowed_page_done               ; past 255: nothing
	add.b	d2,d1                           ; the left column a page on
	bcs.s	arrowed_page_done               ; past 255: nothing
	bra.s	arrowed_page_column

;------------------------------------------------------------------------------
; Typing on a line: the line is copied to line_buffer and edited there (a4 = line_buffer, d4 its length
; with the CR, at most 250) while the keys are Tab, printable, Backspace or Delete.  Any other key or event
; puts the line back into the text (line_edit_finish) and is then handled as usual.  Backspace at column 0
; joins the line to the one above; Delete at the end joins the next one when the preferences say Wrap.
;------------------------------------------------------------------------------
line_edit:	; from: editor_key
	move.l	a4,-(sp)                        ; the line in the text
	lea	path_buffer(a6),a1              ; the edit copy
	st	text_modified(a6)               ; modified
	st	text_touched(a6)
	moveq	#0,d4
line_edit_copy:
	addq.w	#1,d4
	move.b	(a4)+,(a1)+                     ; copied
	cmpi.b	#$d,-$1(a1)                     ; up to the CR
	bne.s	line_edit_copy
	lea	path_buffer(a6),a4              ; edit the copy
	bra.s	line_edit_key                   ; the key
line_edit_next_key:
	bsr.w	update_status_line              ; the status line
	bsr.w	get_event                       ; wait for an event
	cmpi.w	#$3,event_type(a6)              ; a key?
	beq.s	line_edit_key                   ; yes
	moveq	#-1,d1                          ; else -1: finish
line_edit_key:
	cmp.b	#$9,d1                          ; Tab?
	beq.s	line_edit_insert                ; yes: insert it
	cmp.b	#$8,d1                          ; Backspace?
	beq.w	line_edit_backspace             ; yes
	cmp.b	#$7f,d1                         ; Delete?
	beq.w	line_edit_delete                ; yes
	cmp.b	#$c0,d1                         ; a command code?
	bcc.w	line_edit_finish                ; yes: finish
	cmp.b	#$20,d1                         ; a control key?
	bcs.w	line_edit_finish                ; yes: finish
line_edit_insert:
	cmp.w	#$fa,d4                         ; 250 characters?
	bcc.s	line_edit_next_key              ; yes: no more
	move.w	d1,-(sp)
	move.w	d4,-(sp)
	bsr.w	cursor_char                     ; where the cursor is
	beq.s	line_edit_insert_char           ; on a character
	bpl.s	line_edit_insert_place          ; in a tab: moved past it
	sub.w	d5,d6                           ; past the end: back to it
line_edit_insert_place:
	move.l	a1,-(sp)
	bsr.w	editor_cursor_visible           ; the cursor placed
	movea.l	(sp)+,a1
line_edit_insert_char:
	move.w	(sp)+,d4
	move.w	(sp)+,d1                        ; the key
	lea	$ff(a4),a0                      ; the buffer's end
	suba.l	a1,a0
	move.w	a0,d0                           ; the bytes to move
	lea	$ff(a4),a0
line_edit_insert_shift:
	move.b	-(a0),1(a0)                     ; each one on
	dbra	d0,line_edit_insert_shift
	move.b	d1,(a1)                         ; the character in
	addq.w	#1,d4                           ; the line longer
	addq.w	#1,d6                           ; the cursor on
	move.b	d1,d5
	bsr.w	editor_cursor_visible           ; placed
	cmp.b	#$9,d5                          ; a tab?
	bne.s	line_edit_insert_drawn          ; no
	move.w	d4,-(sp)
	bsr.w	cursor_char                     ; to the tab's end
	bsr.w	editor_cursor_visible           ; placed
	move.w	(sp)+,d4
line_edit_insert_drawn:
	movem.w	d4-d5,-(sp)
	bsr.w	redraw_cursor_line              ; the line drawn
	movem.w	(sp)+,d4-d5
	bra.w	line_edit_next_key              ; the next key
line_edit_backspace:
	tst.w	d6                              ; column 0?
	beq.w	line_edit_join_previous         ; yes: join the line above
	move.w	d4,-(sp)
	bsr.w	cursor_char                     ; where the cursor is
	bmi.s	line_edit_backspace_past_end    ; past the end
	move.w	(sp)+,d4
	subq.l	#1,a1                           ; the character before
line_edit_remove_char:
	lea	0(a4,d4.w),a0                   ; the line's end
	suba.l	a1,a0
	move.l	a0,d0
	subq.w	#1,d0                           ; the bytes to move
	lea	1(a1),a0
line_edit_remove_shift:
	move.b	(a0)+,-$2(a0)                   ; each one back
	dbra	d0,line_edit_remove_shift
	bsr.w	set_cursor_column               ; the cursor there
	subq.w	#1,d4                           ; the line shorter
	move.w	d4,-(sp)
	bsr.w	redraw_cursor_line              ; the line drawn
	move.w	(sp)+,d4
	bra.w	line_edit_next_key              ; the next key
line_edit_backspace_past_end:
	subq.l	#1,a1                           ; the last character
	move.w	(sp)+,d4
	cmp.w	#$1,d4                          ; an empty line?
	bne.s	line_edit_remove_char           ; no: delete it
	moveq	#0,d6                           ; yes: column 0
	bsr.w	editor_cursor_visible           ; placed
	moveq	#1,d4
	bra.w	line_edit_next_key
line_edit_join_previous:
	movea.l	(sp),a3                         ; the line in the text
	cmpa.l	text_start(a6),a3               ; the text's first?
	beq.w	line_edit_next_key              ; yes: nothing
	moveq	#0,d2
join_previous_count:
	addq.w	#1,d2                           ; its length with the CR
	cmpi.b	#$d,(a3)+
	bne.s	join_previous_count
	movea.l	(sp),a3
	movea.l	a4,a0                           ; the edit copy
	movea.l	(sp),a4
	bsr.w	text_prev_line                  ; the line above
	exg	a0,a4                           ; a0 = it, a4 = the copy
	move.w	d2,d0
join_previous_count_prev:
	addq.w	#1,d0                           ; and its length
	cmpi.b	#$d,(a0)+
	bne.s	join_previous_count_prev
	cmp.w	#$f8,d0                         ; the two over 247?
	bcc.w	line_edit_next_key              ; yes: not joined
	subq.l	#1,a3                           ; from the CR above
	move.w	d4,d1                           ; the copy without its CR
	subq.w	#1,d1
	bsr.w	text_replace_bytes              ; over the CR and the old line
	subq.w	#1,line_count(a6)               ; one line fewer
	movea.l	(sp),a4
	bsr.w	text_prev_line                  ; the joined line
	movea.l	(sp)+,a1                        ; the join
	tst.w	d7                              ; the top row?
	bne.s	join_previous_row_up            ; no
	subq.l	#1,a1
	bsr.w	set_cursor_column               ; the cursor at the join
	bsr.w	redraw_cursor_line              ; the line drawn
	subq.w	#1,top_line_number(a6)          ; it is the top line now
	move.l	a4,top_line(a6)
	bra.w	editor_loop
join_previous_row_up:
	subq.w	#1,d7                           ; the row above
	bsr.w	editor_cursor_visible
	subq.l	#1,a1
	bsr.w	set_cursor_column               ; the cursor at the join
	bra.w	editor_close_line_gap           ; the rows below up
line_edit_delete:
	move.w	d4,-(sp)
	bsr.w	cursor_char                     ; what is under the cursor
	bmi.w	line_edit_delete_past_end       ; past the end
	move.w	(sp)+,d4
	cmpi.b	#$d,(a1)                        ; the CR?
	beq.w	line_edit_join_next             ; yes: join the next line
	bra.w	line_edit_remove_char           ; else delete it
line_edit_delete_past_end:
	move.w	(sp)+,d4
line_edit_join_next:
	tst.b	end_of_line_wrap(a6)            ; Wrap?
	beq.s	line_edit_join_refused          ; no: nothing
	movea.l	a4,a0
	moveq	#0,d1
join_next_count:
	addq.w	#1,d1                           ; the copy's length with the CR
	cmpi.b	#$d,(a0)+
	bne.s	join_next_count
	movea.l	(sp),a4                         ; the line in the text
	movea.l	a4,a3
	bsr.w	text_next_line                  ; the next line
	bne.w	line_edit_finish                ; none: finish
	move.l	a4,d2
	sub.l	(sp),d2                         ; the old line's length
	bsr.w	text_next_line                  ; past the next one
	move.l	a4,d0
	sub.l	(sp),d0                         ; both lines
	cmp.w	#$f8,d0                         ; over 247?
	bcc.w	line_edit_next_key              ; yes: not joined
	subq.w	#1,d1                           ; the copy without its CR
	bsr.w	text_replace_bytes              ; over the old line and its CR
	subq.w	#1,line_count(a6)               ; one line fewer
	movea.l	(sp),a4
	movea.l	(sp)+,a1
	bra.w	editor_close_line_gap           ; the rows below up
line_edit_join_refused:
	bra.w	line_edit_next_key
line_edit_finish:
	move.w	d1,-(sp)                        ; the key
	movea.l	2(sp),a1                        ; the line in the text
	moveq	#0,d2
line_edit_finish_count:
	addq.w	#1,d2                           ; its old length with the CR
	cmpi.b	#$d,(a1)+
	bne.s	line_edit_finish_count
	movea.l	2(sp),a3
	move.w	d4,d1                           ; the edited length
	bsr.w	text_replace_bytes              ; the copy put in its place
	movea.l	2(sp),a4
	bsr.w	redraw_cursor_line              ; the line drawn
	move.w	(sp)+,d1
	movea.l	(sp)+,a4
	cmp.b	#$ff,d1                         ; an event, not a key?
	bne.w	editor_key                      ; no: handle the key
	bsr.w	handle_message                  ; the window messages
	bra.w	editor_dispatch_event           ; the other events

;------------------------------------------------------------------------------
; Return: split the line at the cursor; with auto indent the new line starts with the old one's leading
; spaces and tabs.
;------------------------------------------------------------------------------
key_return:	; from: editor_key
	bsr.w	cursor_char                     ; where the cursor is
	moveq	#1,d1                           ; the CR
	movea.l	a1,a3
	tst.b	auto_indent(a6)                 ; auto indent?
	beq.s	return_split                    ; no
	movea.l	a4,a0
return_indent_count:
	cmpa.l	a1,a0                           ; up to the cursor
	bcc.s	return_split
	move.b	(a0)+,d0
	cmp.b	#$9,d0                          ; a tab?
	beq.s	return_indent_more              ; yes
	cmp.b	#$20,d0                         ; a space?
	bne.s	return_split                    ; no: the indent ends
return_indent_more:
	addq.l	#1,d1
	bra.s	return_indent_count
return_split:
	bsr.w	text_make_room                  ; room made
	bne.w	editor_loop                     ; no memory
	move.b	#$d,(a1)+                       ; the CR
	subq.l	#1,d1
	beq.s	return_split_done               ; no indent
	subq.w	#1,d1
	movea.l	a4,a0                           ; from the line's start
return_copy_indent:
	move.b	(a0)+,(a1)+                     ; the indent
	dbra	d1,return_copy_indent
return_split_done:
	move.l	a1,-(sp)                        ; the cursor's place
	addq.w	#1,line_count(a6)               ; one line more
	bsr.w	redraw_cursor_line              ; the line drawn
	cmp.w	last_row(a6),d7                 ; the bottom row?
	beq.s	return_scroll                   ; yes: scroll
	addq.w	#1,d7                           ; the row below
	bsr.w	scroll_open_line                ; a line opened there
return_new_line:
	bsr.w	text_next_line                  ; the new line
	movea.l	(sp)+,a1
	bsr.w	set_cursor_column               ; the cursor after the indent
	bsr.w	redraw_cursor_line              ; the line drawn
	bra.w	editor_loop
return_scroll:
	addq.w	#1,top_line_number(a6)          ; the top line on
	move.l	a4,-(sp)
	movea.l	top_line(a6),a4
	bsr.w	text_next_line
	move.l	a4,top_line(a6)
	movea.l	(sp)+,a4
	bsr.w	scroll_text_up                  ; scrolled up
	bra.s	return_new_line

;------------------------------------------------------------------------------
; a4 to the start of the line before (or stays on the first).
;------------------------------------------------------------------------------
text_prev_line:                                 ; from: key_cursor_left, key_cursor_up, key_page_up, top_line_back,
                                                ;   cmd_print_block, command_mouse, 4 more
	subq.l	#1,a4                           ; into the line before

;------------------------------------------------------------------------------
; a4 to the start of the line it is in.
;------------------------------------------------------------------------------
text_line_start:	; from: key_block_delete, cmd_print_block, cmd_find_next
	cmpa.l	text_start(a6),a4               ; the text's start?
	beq.s	line_start_done                 ; yes
	cmpi.b	#$d,-(a4)                       ; the CR before?
	bne.s	text_line_start                 ; no
	addq.l	#1,a4                           ; after it
line_start_done:
	rts

;------------------------------------------------------------------------------
; a4 to the start of the next line: Z set when moved; NE when a4 is on the last line (a4 kept).
;------------------------------------------------------------------------------
text_next_line:                                 ; from: key_cursor_right, key_cursor_down, show_end_of_file,
                                                ;   window_scroll_forward, key_page_down, editor_close_line_gap, 8 more
	move.l	a4,d0
next_line_loop:
	cmpa.l	text_end(a6),a4                 ; the end?
	bcc.s	next_line_none                  ; yes
	cmpi.b	#$d,(a4)+                       ; the CR?
	bne.s	next_line_loop                  ; no
	rts                                     ; Z
next_line_none:
	movea.l	d0,a4                           ; as it was
	tst.l	d0                              ; NE
	rts

;------------------------------------------------------------------------------
; Find the character at the cursor's column d6 in the line a4: a1 is it.  Z set when the column is on a
; character; GT when it was inside a tab: a1 after the tab and d6 moved to the tab's end; N set (d0 -1)
; when it is past the line's end: a1 on the CR, d4 the line's width, d5 the columns past it.
;------------------------------------------------------------------------------
cursor_char:                                    ; from: key_cursor_left, key_cursor_right, key_word_right,
                                                ;   key_word_left, key_delete_to_end, key_block_start, 10 more
	lea	-$1(a4),a1
	moveq	#0,d4                           ; the next tab stop
	moveq	#0,d5                           ; the column
cursor_char_loop:
	addq.l	#1,a1
	move.b	(a1),d1                         ; the character
	cmp.w	d5,d6                           ; the cursor's column?
	bne.s	cursor_char_step                ; no
	rts                                     ; yes: Z
cursor_char_step:
	cmp.b	#$d,d1                          ; the CR?
	beq.s	cursor_char_past_end            ; yes: past the end
	addq.w	#1,d5
	cmp.b	#$9,d1                          ; a tab?
	bne.s	cursor_char_loop                ; no
cursor_char_tab:
	add.w	tab_size(a6),d4                 ; the next tab stop
	move.w	d4,d0
	sub.w	d5,d0
	bcs.s	cursor_char_tab
	move.w	d4,d5                           ; the column after the tab
	cmp.w	d5,d6                           ; the cursor inside it?
	bcs.s	cursor_char_in_tab              ; yes
	bra.s	cursor_char_loop
cursor_char_in_tab:
	addq.l	#1,a1                           ; after the tab
	move.w	d5,d6                           ; the cursor to its end
	rts
cursor_char_past_end:
	move.w	d5,d4                           ; the line's width
	move.w	d6,d5
	sub.w	d4,d5                           ; the columns past it
	moveq	#-1,d0                          ; N
	rts

;------------------------------------------------------------------------------
; Set the cursor's column d6 to the character at a1 in the line a4 (tabs counted) and place the cursor.
;------------------------------------------------------------------------------
set_cursor_column:                              ; from: cursor_line_end, key_word_right, key_word_left, line_edit,
                                                ;   key_return, cmd_find_next, 1 more
	movem.l	d4-d5/a4,-(sp)
	moveq	#0,d4                           ; the next tab stop
	moveq	#0,d5                           ; the column
set_column_loop:
	cmpa.l	a4,a1                           ; a1 reached?
	bne.s	set_column_char                 ; no
set_column_done:
	move.w	d5,d6                           ; the cursor's column
	bsr.w	editor_cursor_visible           ; placed
	movem.l	(sp)+,d4-d5/a4
	rts
set_column_char:
	move.b	(a4)+,d1                        ; a character
	cmp.b	#$d,d1                          ; the CR?
	beq.s	set_column_done                 ; yes: stop
	cmp.b	#$9,d1                          ; a tab?
	bne.s	set_column_plain                ; no
set_column_tab:
	add.w	tab_size(a6),d4                 ; the next tab stop
	move.w	d4,d0
	sub.w	d5,d0
	bls.s	set_column_tab
	move.w	d4,d5
	bra.s	set_column_loop
set_column_plain:
	addq.w	#1,d5
	bra.s	set_column_loop

;------------------------------------------------------------------------------
; An Alt key command: the letter in event_code runs its routine from alt_key_table.
;------------------------------------------------------------------------------
editor_alt_key:	; from: editor_loop
	move.b	event_code(a6),d1               ; the letter
	andi.b	#$df,d1                         ; upper case
	lea	alt_key_table(pc),a0            ; the table
	subi.b	#$41,d1                         ; from A
	bcs.s	alt_key_unknown                 ; not a letter
	cmp.b	#$1a,d1                         ; past Z?
	bcc.s	alt_key_unknown                 ; yes
	andi.w	#$ff,d1
	add.w	d1,d1
	move.w	0(a0,d1.w),d0                   ; its offset
	beq.s	alt_key_unknown                 ; none
	pea	0(a0,d0.w)                      ; the routine
	movea.l	(sp)+,a0
	jsr	(a0)                            ; run
	bra.w	editor_loop
alt_key_unknown:
	lea	msg_command_not_recognised(pc),a1 ; "Command not recognised"
	bsr.w	message_beep                    ; shown
	bra.w	editor_loop
msg_command_not_recognised:
	dc.w	$0016                           ; its length
	dc.b	'Command not recognised'
alt_key_table:
	dc.w	cmd_assemble-alt_key_table
	dc.w	cmd_goto_bottom-alt_key_table
	dc.w	cmd_clear-alt_key_table
	dc.w	cmd_debug-alt_key_table
	dc.w	0
	dc.w	cmd_find-alt_key_table
	dc.w	cmd_goto_line-alt_key_table
	dc.w	cmd_help-alt_key_table
	dc.w	cmd_insert_file-alt_key_table
	dc.w	cmd_jump_error-alt_key_table
	dc.w	menu_run_with_gem-alt_key_table
	dc.w	cmd_load-alt_key_table
	dc.w	cmd_monst-alt_key_table
	dc.w	cmd_find_next-alt_key_table
	dc.w	menu_run_other_drop-alt_key_table
	dc.w	cmd_find_previous-alt_key_table
	dc.w	cmd_quit-alt_key_table
	dc.w	cmd_replace-alt_key_table
	dc.w	cmd_save_as-alt_key_table
	dc.w	cmd_goto_top-alt_key_table
	dc.w	0
	dc.w	0
	dc.w	cmd_print_block-alt_key_table
	dc.w	cmd_run-alt_key_table
	dc.w	0
	dc.w	0
	moveq	#0,d4                           ; (not called: a decimal number at a1, up to the CR, into d4; NE when
                                                ;   bad)
decimal_parse_loop:
	move.b	(a1)+,d1                        ; a character
	cmp.b	#$d,d1                          ; the CR?
	beq.s	decimal_parse_done              ; yes: done
	subi.b	#$30,d1
	bcs.s	decimal_parse_bad               ; below "0"
	cmp.b	#$d,d1
	bcc.s	decimal_parse_bad
	mulu.w	#$a,d4
	andi.w	#$ff,d1
	add.w	d1,d4                           ; added
	bvc.s	decimal_parse_loop              ; no overflow: on
decimal_parse_bad:
	moveq	#-1,d0                          ; NE
decimal_parse_done:
	rts

;------------------------------------------------------------------------------
; Alt-Q: quit, once the user agrees to lose any changes.
;------------------------------------------------------------------------------
cmd_quit:	; from: editor_alt_key
	moveq	#0,d4
	bsr.w	confirm_lose_changes            ; lose the changes?
	beq.w	quit_editor                     ; yes: quit
	rts

;------------------------------------------------------------------------------
; Alt-H: the help box (with the free memory).
;------------------------------------------------------------------------------
cmd_help:	; from: editor_alt_key
	bra.w	help_dialog
	not.b	auto_indent(a6)                 ; (not called: auto indent on or off)
	rts

;------------------------------------------------------------------------------
; Alt-L: load a file the file selector names, once the user agrees to lose any changes.
;------------------------------------------------------------------------------
cmd_load:	; from: editor_alt_key
	bsr.w	confirm_lose_changes            ; lose the changes?
	bne.w	load_redraw                     ; no
	bsr.w	select_load_file                ; "Load a file"
	bne.w	load_redraw                     ; cancelled

;------------------------------------------------------------------------------
; Load the file the selector's path and name give into the text, replacing it; also used for the file named
; on the command line.  CR LF and lone LF become CR, a ^Z at the end goes, zero bytes become "?" and lines
; are cut at 250 characters.  A file too big for the text buffer is refused with an alert.
;------------------------------------------------------------------------------
editor_load_file:	; from: aes_call
	bsr.w	open_input_file                 ; opened, its length in d1
	bne.w	load_redraw                     ; failed
	bsr.w	set_file_name                   ; the file's name
	bsr.w	set_window_title                ; in the window's title
	move.l	text_start(a6),d0
	add.l	d1,d0
	cmp.l	text_limit(a6),d0               ; will it fit?
	bcs.s	load_into_text                  ; yes
load_too_big:	; from: cmd_insert_file
	clr.w	file_name(a6)                   ; no name
	bsr.w	alert_no_room_to_load           ; "not enough memory" alert
	bsr.w	set_window_title                ; the title again
	bra.w	close_text_file                 ; the file closed
load_into_text:
	move.l	d1,-(sp)                        ; the length
	sf	text_modified(a6)               ; not modified
	st	text_touched(a6)
	bsr.w	clear_text                      ; the text emptied
	movea.l	text_start(a6),a4
	move.l	a4,top_line(a6)                 ; the top line
	clr.w	top_line_number(a6)             ; line 0
	clr.w	left_column(a6)                 ; column 0
	bsr.w	redraw_text                     ; the empty window
	move.l	(sp)+,d1
	beq.s	load_set_end                    ; an empty file
	movea.l	text_start(a6),a3
	subq.l	#1,d1                           ; (the end's CR is already there)
	bsr.w	text_make_room                  ; room made
	bne.w	close_text_file                 ; no memory: closed
	addq.l	#1,d1
	bsr.w	read_text_file                  ; read in, the line ends made CR
load_set_end:
	sf	text_modified(a6)               ; not modified
	clr.w	load_state(a6)
	add.l	text_start(a6),d1               ; the start + the length read
	move.l	d1,text_end(a6)                 ; the text's end
	movea.l	d1,a0
	move.b	#$d,(a0)                        ; its CR
	bsr.w	tidy_text                       ; zero bytes and long lines
load_redraw:	; from: cmd_load
	bsr.w	gem_drop_messages               ; the screen redrawn
	bsr.s	text_count_lines                ; the lines counted
	bra.w	redraw_text                     ; the window drawn

;------------------------------------------------------------------------------
; Count the lines of the text into line_count (the last, empty, line too); when the count changes the
; slider is due an update.
;------------------------------------------------------------------------------
text_count_lines:	; from: key_block_delete, key_block_copy, editor_load_file, cmd_insert_file
	moveq	#1,d0
	movea.l	text_start(a6),a0
count_lines_loop:
	cmpi.b	#$d,(a0)+                       ; a CR
	bne.s	count_lines_loop
	addq.w	#1,d0                           ; a line
	cmpa.l	text_end(a6),a0                 ; the end?
	bcs.s	count_lines_loop                ; no
	cmp.w	line_count(a6),d0               ; the same?
	beq.s	count_lines_done                ; yes
	move.w	d0,line_count(a6)               ; the new count
	st	sliders_stale(a6)               ; the slider to update
count_lines_done:
	rts

;------------------------------------------------------------------------------
; Make the loaded text fit the editor: a zero byte becomes "?" and the 251st character of a line becomes a
; CR, so no line is longer than 250.
;------------------------------------------------------------------------------
tidy_text:	; from: editor_load_file
	movea.l	text_start(a6),a0               ; from the start
	moveq	#13,d2                          ; CR
	bra.s	tidy_text_line
tidy_text_split:
	move.b	#$d,(a0)+                       ; a CR over the 251st character
tidy_text_line:
	moveq	#5,d0                           ; a new line: 250 to go
tidy_text_loop:
	cmpa.l	text_end(a6),a0                 ; the end?
	beq.s	tidy_text_done                  ; yes
	addq.b	#1,d0
	beq.s	tidy_text_split                 ; too long
	move.b	(a0)+,d1                        ; a character
	beq.s	tidy_text_zero                  ; zero?
	cmp.b	d1,d2                           ; the CR?
	bne.s	tidy_text_loop                  ; no
	bra.s	tidy_text_line
tidy_text_zero:
	move.b	#$3f,-$1(a0)                    ; "?"
	bra.s	tidy_text_loop
tidy_text_done:
	move.b	#$d,(a0)                        ; the end's CR again
	rts

;------------------------------------------------------------------------------
; Alt-S: save the text to a file the file selector names; that becomes the file's name.
;------------------------------------------------------------------------------
cmd_save_as:	; from: command_menu_save, editor_alt_key, revert_text
	bsr.w	selector_from_file              ; the selector from the file's name
	bsr.w	select_save_file                ; "Save a file"
	bne.s	save_as_done                    ; cancelled
	bsr.w	set_file_name                   ; the new name
	bsr.w	set_window_title                ; in the title

;------------------------------------------------------------------------------
; Save the whole text, its last CR too, under the selector's path and name.
;------------------------------------------------------------------------------
editor_save_text:	; from: command_menu_save, revert_text
	movea.l	text_start(a6),a3               ; the start
	move.l	text_end(a6),d1
	sub.l	a3,d1                           ; the length
	addq.l	#1,d1                           ; with the end's CR
	moveq	#0,d0                           ; 0: the text, with a backup
	bsr.w	save_text_file                  ; written
save_as_done:	; from: cmd_save_as
	rts

;------------------------------------------------------------------------------
; The file's name (file_name) from the selector's path and name.
;------------------------------------------------------------------------------
set_file_name:	; from: editor_load_file, cmd_save_as, gem_init
	movem.l	d0-d1/a0-a2,-(sp)
	lea	file_name(a6),a2
	lea	selector_name(a6),a0
	bsr.w	make_path_in                    ; combined
	movem.l	(sp)+,d0-d1/a0-a2
	rts

;------------------------------------------------------------------------------
; Set the file selector from the file's name: the path to its folder with "*." and its extension, and the
; name to it.  Nothing changes when there is no name.
;------------------------------------------------------------------------------
selector_from_file:	; from: command_menu_save, cmd_save_as, revert_text
	movem.l	d0-d1/a0-a2,-(sp)
	lea	file_name(a6),a0                ; the file's name
	lea	fsel_path(a6),a1                ; the selector's path
	clr.b	selector_name(a6)               ; no name
	tst.b	(a0)                            ; one?
	beq.s	selector_from_file_done         ; no
	suba.l	a2,a2                           ; no "\" yet
selector_copy_name:
	move.b	(a0)+,d1
	beq.s	selector_name_copied            ; the end
	cmp.b	#$5c,d1                         ; a "\"?
	bne.s	selector_copy_char              ; no
	lea	1(a1),a2                        ; the name starts after it
selector_copy_char:
	move.b	d1,(a1)+
	bra.s	selector_copy_name
selector_name_copied:
	clr.b	(a1)
	move.l	a2,d0                           ; a "\" in it?
	bne.s	selector_split_name             ; yes
	clr.b	selector_name(a6)               ; no: no name
	move.b	#$5c,(a1)+                      ; a "\" added
	suba.l	a2,a2                           ; no extension
	bra.s	selector_add_mask
selector_split_name:
	lea	selector_name(a6),a0            ; the selector's name
	movea.l	a2,a1                           ; from the name's start
	move.l	a2,-(sp)
	suba.l	a2,a2                           ; no extension yet
selector_find_extension:
	move.b	(a1)+,d0
	move.b	d0,(a0)+                        ; copied
	beq.s	selector_name_split
	cmp.b	#$2e,d0                         ; a "."?
	bne.s	selector_find_extension         ; no
	movea.l	a0,a2                           ; the extension after it
	bra.s	selector_find_extension
selector_name_split:
	movea.l	(sp)+,a1                        ; the path after its "\"
selector_add_mask:
	move.b	#$2a,(a1)+                      ; "*"
	move.b	#$2e,(a1)+                      ; "."
	move.l	a2,d0                           ; an extension?
	bne.s	selector_copy_extension         ; yes
	clr.b	(a1)                            ; no
	bra.s	selector_from_file_done
selector_copy_extension:
	move.b	(a2)+,(a1)+
	bne.s	selector_copy_extension
selector_from_file_done:
	movem.l	(sp)+,d0-d1/a0-a2
	rts

;------------------------------------------------------------------------------
; ^U (Undo): put the line ^Y or ^Q last took back in front of the cursor's line.
;------------------------------------------------------------------------------
key_undo:	; from: editor_key
	moveq	#0,d1
	move.w	undo_line(a6),d1                ; its length
	beq.s	undo_done                       ; none
	movea.l	a4,a3                           ; in front of the line
	bsr.w	text_make_room                  ; room made
	bne.s	undo_done                       ; no memory
	lea	undo_text(a6),a1                ; the line kept
	subq.w	#1,d1
	movea.l	a4,a0
undo_copy:
	move.b	(a1)+,(a0)+                     ; copied
	dbra	d1,undo_copy
	addq.w	#1,line_count(a6)               ; one line more
	tst.w	d7                              ; the top row?
	bne.s	undo_row_above                  ; no
	bsr.w	scroll_text_down                ; a line opened at the cursor
	bra.s	undo_redraw
undo_row_above:
	subq.w	#1,d7                           ; the row above
	bsr.w	editor_cursor_visible
	bsr.w	scroll_open_line                ; a line opened below it
	addq.w	#1,d7
	bsr.w	editor_cursor_visible
undo_redraw:
	bsr.w	redraw_cursor_line              ; the line drawn
undo_done:
	bra.w	editor_loop

;------------------------------------------------------------------------------
; Keep a copy of the line a4 (its length word and the line with its CR) for ^U.
;------------------------------------------------------------------------------
save_undo_line:	; from: key_delete_line, key_delete_to_end
	movem.l	d0-d1/a0/a4,-(sp)
	lea	undo_line(a6),a0
	moveq	#1,d0
save_undo_loop:
	move.b	(a4)+,d1                        ; a character
	move.b	d1,1(a0,d0.w)                   ; kept
	cmp.b	#$d,d1                          ; the CR?
	beq.s	save_undo_done                  ; yes
	addq.w	#1,d0
	cmp.b	#$fe,d0                         ; 253 or more?
	bne.s	save_undo_loop                  ; no
	move.b	#$d,2(a0,d0.w)                  ; yes: a CR after them
save_undo_done:
	move.w	d0,(a0)                         ; the length
	movem.l	(sp)+,d0-d1/a0/a4
	rts
msg_what_errors:	; from: jump_first_error, cmd_jump_error
	dc.w	$000c                           ; its length
	dc.b	'what errors!'
msg_no_more_errors:	; from: cmd_jump_error
	dc.w	$000e                           ; its length
	dc.b	'no more errors'

;------------------------------------------------------------------------------
; After an assembly with errors: to the first error's line (warnings alone do not move the cursor).
;------------------------------------------------------------------------------
jump_first_error:	; from: cmd_assemble
	lea	error_list(a6),a0               ; the list of errors
first_error_loop:
	tst.w	(a0)+                           ; the end?
	beq.s	first_error_none                ; yes
	tst.w	(a0)+                           ; a warning?
	bmi.s	first_error_loop                ; yes: the next
	subq.l	#4,a0                           ; the first error
	move.w	#$7fff,d3                       ; the nearest line so far
	moveq	#0,d2                           ; after line 0
	lea	msg_what_errors(pc),a1
	bra.s	jump_error_loop

;------------------------------------------------------------------------------
; Empty the list of errors.
;------------------------------------------------------------------------------
clear_error_list:	; from: aes_call
	clr.w	error_list(a6)
first_error_none:	; from: jump_first_error
	rts

;------------------------------------------------------------------------------
; Alt-J: to the next error or warning after the cursor's line, with its message in the status line.  The
; list holds a line word and a message word (bit 15 set for a warning) for each, 0 at its end.
;------------------------------------------------------------------------------
cmd_jump_error:	; from: editor_alt_key
	lea	msg_what_errors(pc),a1          ; "what errors!"
	lea	error_list(a6),a0               ; the list
	tst.w	(a0)                            ; empty?
	beq.w	jump_error_message_out          ; yes
	move.w	d7,d2                           ; the cursor's line number
	add.w	top_line_number(a6),d2
	addq.w	#1,d2
	move.w	#$7fff,d3                       ; the nearest so far: none
jump_error_loop:	; from: jump_first_error
	move.w	(a0)+,d0                        ; the line
	beq.s	jump_error_found                ; the end
	addq.w	#2,a0
	cmp.w	d2,d0                           ; after the cursor's?
	bls.s	jump_error_loop                 ; no
	cmp.w	d3,d0                           ; nearer?
	bcc.s	jump_error_loop                 ; no
	move.w	d0,d3                           ; the nearest
	movea.l	a0,a1                           ; its entry
	bra.s	jump_error_loop
jump_error_found:
	cmp.w	#$7fff,d3                       ; any?
	beq.s	jump_error_no_more              ; no: "no more errors"
	move.l	a1,-(sp)
	moveq	#-1,d4                          ; no "End of file"
	move.w	d3,d4                           ; the line
	bsr.w	editor_goto_line                ; to it
	bsr.w	update_status_line              ; the status line
	bsr.w	message_area_prepare            ; the message area
	bsr.w	hide_mouse
	movea.l	(sp)+,a1
	lea	asm_entry,a0                    ; the assembler's header
	lea	error_prefix(pc),a2             ; "Error: "
	moveq	#0,d1
	move.w	4(a0),d1                        ; the errors' offset
	move.w	-(a1),d0                        ; the message number
	bpl.s	jump_error_message              ; an error
	andi.w	#$7fff,d0                       ; a warning
	move.w	6(a0),d1                        ; the warnings' offset
	lea	warning_prefix(pc),a2           ; "Warning: "
jump_error_message:
	adda.l	d1,a0                           ; the first message
	subq.w	#1,d0
	beq.s	jump_error_prefix               ; the first one
jump_error_skip:
	tst.b	(a0)+                           ; past one
	bne.s	jump_error_skip
	subq.w	#1,d0
	bne.s	jump_error_skip
jump_error_prefix:
	move.b	(a2)+,d1                        ; "Error: " or "Warning: "
	beq.s	jump_error_text
	bsr.w	editor_put_char                 ; printed
	bra.s	jump_error_prefix
jump_error_text:
	move.b	(a0)+,d1                        ; the message
	beq.s	jump_error_shown
	bsr.w	editor_put_char                 ; printed
	bra.s	jump_error_text
jump_error_shown:
	bsr.w	show_mouse
	move.w	#$0,output_mode(a6)             ; output to the window
	rts
jump_error_no_more:
	lea	msg_no_more_errors(pc),a1       ; "no more errors"
jump_error_message_out:
	bra.w	message_beep                    ; shown
error_prefix:
	dc.b	'Error: ',0
warning_prefix:
	dc.b	'Warning: ',0

;------------------------------------------------------------------------------
; Alt-C: clear the text, once the user agrees to lose any changes.
;------------------------------------------------------------------------------
cmd_clear:	; from: editor_alt_key
	bsr.w	confirm_lose_changes            ; lose the changes?
	bne.s	clear_text_done                 ; no

;------------------------------------------------------------------------------
; Empty the text, with no file name, the cursor home and the window drawn.
;------------------------------------------------------------------------------
editor_clear_text:	; from: menu_preferences
	bsr.w	clear_text                      ; the text emptied
	sf	text_modified(a6)               ; not modified
	st	text_touched(a6)
	bsr.w	editor_cursor_home              ; cursor home
	clr.w	top_line_number(a6)             ; line 0
	clr.w	left_column(a6)                 ; column 0
	movea.l	text_start(a6),a4
	move.l	a4,top_line(a6)                 ; the top line
	move.l	a4,text_end(a6)                 ; the end
	bsr.w	redraw_text                     ; the empty window
	clr.w	selector_name(a6)               ; no name
	clr.w	load_state(a6)
	clr.w	file_name(a6)                   ; no file name
	bsr.w	set_window_title                ; the title
	move.w	#$1,line_count(a6)              ; one line
	bsr.w	update_sliders                  ; the slider
clear_text_done:	; from: cmd_clear
	rts

;------------------------------------------------------------------------------
; Alt-G: to the line number the user types.
;------------------------------------------------------------------------------
cmd_goto_line:	; from: editor_alt_key
	bsr.w	goto_line_dialog                ; the dialog
	bne.s	editor_rts                      ; cancelled
	tst.w	d4                              ; 0?
	beq.s	editor_rts                      ; yes: nothing
	andi.l	#$ffff,d4                       ; high word 0: "End of file" past the end

;------------------------------------------------------------------------------
; To line d4.w (from 1) and show it; past the end to the last line with "End of file" unless d4 is
; negative.  d3 ends as the line's number.
;------------------------------------------------------------------------------
editor_goto_line:	; from: window_check_vslid, cmd_jump_error, cmd_goto_top, cmd_goto_bottom
	movea.l	text_start(a6),a4               ; from the first line
	moveq	#1,d3                           ; line 1
goto_line_loop:
	cmp.w	d3,d4                           ; there?
	beq.s	goto_line_show                  ; yes
	addq.w	#1,d3
	bsr.w	text_next_line                  ; the next line
	beq.s	goto_line_loop
	subq.w	#1,d3                           ; the last line's number
	tst.l	d4                              ; quiet?
	bmi.s	goto_line_show                  ; yes
	lea	msg_end_of_file(pc),a1          ; "End of file"
	bsr.w	message_beep                    ; shown
goto_line_show:
	bra.s	editor_show_line
editor_rts:	; from: cmd_goto_line, cmd_find_next, cmd_find_previous
	rts
msg_end_of_file:	; from: show_end_of_file
	dc.w	$000b                           ; its length
	dc.b	'End of file',0

;------------------------------------------------------------------------------
; Alt-T: to the first line.
;------------------------------------------------------------------------------
cmd_goto_top:	; from: editor_alt_key
	moveq	#1,d4                           ; line 1
	moveq	#0,d6                           ; column 0
	bra.s	editor_goto_line

;------------------------------------------------------------------------------
; Alt-B: to the last line.
;------------------------------------------------------------------------------
cmd_goto_bottom:	; from: editor_alt_key
	moveq	#-1,d4                          ; the last, quietly
	moveq	#0,d6                           ; column 0
	bra.s	editor_goto_line

;------------------------------------------------------------------------------
; Show line a4 (number d3): move the cursor to it when it is in the window, else redraw the window with it
; near the middle.
;------------------------------------------------------------------------------
editor_show_line:	; from: editor_goto_line, cmd_find_next
	cmpa.l	top_line(a6),a4                 ; above the window?
	bcs.s	show_line_centred               ; yes
	move.w	top_line_number(a6),d0
	addq.w	#1,d0
	add.w	d7,d0                           ; the cursor's line number
	move.w	d3,d2
	sub.w	d0,d2                           ; the lines on from it
	bcs.s	show_line_in_window             ; above the cursor: in the window
	move.w	d2,d0
	add.w	d7,d0
	cmp.w	last_row(a6),d0                 ; past the bottom row?
	bcc.s	show_line_centred               ; yes
show_line_in_window:
	add.w	d2,d7                           ; the row
	bra.w	editor_cursor_visible           ; placed

;------------------------------------------------------------------------------
; Show the line a4, its number counted from the text's start, near the middle of the window.
;------------------------------------------------------------------------------
show_cursor_line:	; from: key_block_delete
	movea.l	a4,a2
	movea.l	text_start(a6),a4               ; from the first line
	moveq	#1,d3
show_cursor_line_count:
	cmpa.l	a4,a2                           ; reached?
	beq.s	show_cursor_line_counted        ; yes
	addq.w	#1,d3
	bsr.w	text_next_line                  ; on
	bra.s	show_cursor_line_count
show_cursor_line_counted:
	movea.l	a2,a4
show_line_centred:	; from: editor_show_line
	subq.w	#1,d3                           ; its number from 0
	move.w	d3,top_line_number(a6)          ; the top line's number for now
	move.l	a4,-(sp)
	move.w	last_row(a6),d7
	lsr.w	#1,d7                           ; half a window above it
	move.w	line_count(a6),d0
	sub.w	d3,d0                           ; the lines after it
	cmp.w	d7,d0                           ; fewer?
	bcc.s	centre_back                     ; no
	move.w	last_row(a6),d7                 ; yes: lower in the window
	sub.w	d0,d7
centre_back:
	move.w	d7,d0
	bra.s	centre_back_next
centre_back_loop:
	tst.w	top_line_number(a6)             ; the first line?
	beq.s	centre_back_done                ; yes: stop
	subq.w	#1,top_line_number(a6)
	bsr.w	text_prev_line                  ; a line back
centre_back_next:
	dbra	d0,centre_back_loop
centre_back_done:
	sub.w	d0,d7                           ; the row: the lines gone back
	subq.w	#1,d7
	move.l	a4,top_line(a6)                 ; the top line
	movea.l	(sp)+,a4
	bsr.w	redraw_window                   ; the window drawn
	bra.w	editor_cursor_visible           ; the cursor placed

;------------------------------------------------------------------------------
; Alt-F: the find and replace dialog, then a search forwards (Next) or backwards (Previous).
;------------------------------------------------------------------------------
cmd_find:	; from: editor_alt_key
	bsr.w	find_dialog                     ; the dialog
	beq.w	cmd_find_previous               ; Previous: backwards

;------------------------------------------------------------------------------
; Alt-N: search forwards from after the cursor for the find string, with the case folding the dialog set.
;------------------------------------------------------------------------------
cmd_find_next:	; from: editor_alt_key, cmd_replace
	move.w	find_string(a6),d3              ; its length
	beq.w	editor_rts                      ; none
	bsr.w	cursor_char                     ; where the cursor is
	move.w	d7,d4
	add.w	top_line_number(a6),d4
	addq.w	#1,d4                           ; its line's number
	lea	find_text(a6),a0                ; the string
	subq.w	#2,d3                           ; the rest's count
	cmpi.b	#$d,(a1)                        ; on the CR?
	beq.s	find_next_first                 ; yes: from there
	addq.l	#1,a1                           ; else from the next character
find_next_first:
	move.b	(a0)+,d1                        ; its first character
	jsr	case_fold_code(a6)              ; folded
	move.b	d1,d2
find_next_loop:
	cmpa.l	text_end(a6),a1                 ; the end?
	bcc.s	find_not_found                  ; yes: not found
	move.b	(a1)+,d1
	cmp.b	#$d,d1                          ; a CR?
	bne.s	find_next_compare               ; no
	addq.w	#1,d4                           ; a line on
find_next_compare:
	jsr	case_fold_code(a6)              ; folded
	cmp.b	d2,d1                           ; the first character?
	bne.s	find_next_loop                  ; no
	tst.w	d3                              ; one character only?
	bmi.s	find_next_found                 ; yes: found
	movem.l	d2/a0-a1,-(sp)
	move.w	d3,d2
find_next_rest:
	move.b	(a0)+,d1
	jsr	case_fold_code(a6)              ; folded
	exg	d1,d0
	move.b	(a1)+,d1
	jsr	case_fold_code(a6)              ; folded
	cmp.b	d1,d0                           ; the same?
	dbne	d2,find_next_rest
	movem.l	(sp)+,d2/a0-a1
	bne.s	find_next_loop                  ; no: on
find_next_found:
	subq.l	#1,a1                           ; its start
find_show_match:	; from: cmd_find_previous
	movea.l	a1,a4                           ; the match's line
	bsr.w	text_line_start                 ; its start
	move.w	d4,d3                           ; its number
	move.l	a1,-(sp)
	bsr.w	editor_show_line                ; shown
	movea.l	(sp)+,a1
	bra.w	set_cursor_column               ; the cursor on the match
find_not_found:	; from: cmd_find_previous
	lea	msg_not_found(pc),a1            ; "Not found"
	bra.w	message_beep                    ; shown

;------------------------------------------------------------------------------
; d1 to upper case.  The find code runs the RAM copy at case_fold_code, whose first word is an rts when
; case matters.
;------------------------------------------------------------------------------
find_upper_case:	; from: aes_call, find_dialog, parse_command_line_name, get_event
	cmp.b	#$61,d1                         ; below "a"?
	bcs.s	upper_case_done                 ; yes
	cmp.b	#$7b,d1                         ; past "z"?
	bcc.s	upper_case_done                 ; yes
	subi.b	#$20,d1                         ; upper case
upper_case_done:
	rts
msg_not_found:	; from: cmd_find_next
	dc.b	$00                             ; its length word
	dc.b	9,'Not found',0

;------------------------------------------------------------------------------
; Alt-P: search backwards from the cursor for the find string.
;------------------------------------------------------------------------------
cmd_find_previous:	; from: editor_alt_key, cmd_find
	move.w	find_string(a6),d3              ; its length
	beq.w	editor_rts                      ; none
	bsr.w	cursor_char                     ; where the cursor is
	move.w	d7,d4
	add.w	top_line_number(a6),d4
	addq.w	#1,d4                           ; its line's number
	lea	find_text(a6),a0                ; the string
	subq.w	#2,d3                           ; the rest's count
	move.b	(a0)+,d1                        ; its first character
	jsr	case_fold_code(a6)              ; folded
	move.b	d1,d2
find_previous_loop:
	move.b	-(a1),d1                        ; the character before
	cmpa.l	text_start(a6),a1               ; the text's start?
	bls.s	find_not_found                  ; yes: not found
	jsr	case_fold_code(a6)              ; folded
	cmp.b	#$d,d1                          ; a CR?
	bne.s	find_previous_compare           ; no
	subq.w	#1,d4                           ; a line back
find_previous_compare:
	cmp.b	d2,d1                           ; the first character?
	bne.s	find_previous_loop              ; no
	tst.w	d3                              ; one character only?
	bmi.s	find_show_match                 ; yes: found
	movem.l	d2/a0-a1,-(sp)
	addq.l	#1,a1                           ; after it
	move.w	d3,d2
find_previous_rest:
	move.b	(a0)+,d1
	jsr	case_fold_code(a6)              ; folded
	exg	d1,d0
	move.b	(a1)+,d1
	jsr	case_fold_code(a6)              ; folded
	cmp.b	d1,d0                           ; the same?
	dbne	d2,find_previous_rest
	movem.l	(sp)+,d2/a0-a1
	bne.s	find_previous_loop              ; no: on
	bra.w	find_show_match                 ; found

;------------------------------------------------------------------------------
; Z set when the find string is at a1 (with the case folding set).
;------------------------------------------------------------------------------
match_find_string:	; from: cmd_replace, replace_all
	lea	find_string(a6),a0
	move.w	(a0)+,d2                        ; its length
	subq.w	#1,d2
	bcs.s	match_find_done                 ; none: NE
match_find_loop:
	move.b	0(a0,d2.w),d1                   ; from its end
	jsr	case_fold_code(a6)              ; folded
	exg	d1,d0
	move.b	0(a1,d2.w),d1                   ; the text's
	jsr	case_fold_code(a6)              ; folded
	cmp.b	d0,d1                           ; the same?
	dbne	d2,match_find_loop
match_find_done:
	rts

;------------------------------------------------------------------------------
; Alt-R: when the find string is at the cursor, replace it and search on for the next.
;------------------------------------------------------------------------------
cmd_replace:	; from: editor_alt_key
	bsr.w	cursor_char                     ; where the cursor is
	bne.s	replace_done                    ; not on a character
	bsr.s	match_find_string               ; the string here?
	bne.s	replace_done                    ; no
	bsr.s	replace_at                      ; replaced
	bsr.w	set_cursor_column               ; the cursor at its end
	bsr.w	redraw_cursor_line              ; the line drawn
	bra.w	cmd_find_next                   ; the next
replace_done:
	rts

;------------------------------------------------------------------------------
; Replace the find string at a1 with the replace string; a1 ends on the replacement's last character (or
; where the string was when the replacement is empty).
;------------------------------------------------------------------------------
replace_at:	; from: cmd_replace, replace_all
	lea	replace_string(a6),a0           ; the replace string
	lea	path_buffer(a6),a2              ; to line_buffer
	move.w	(a0)+,d1                        ; its length
	movea.l	a1,a3                           ; where
	subq.w	#1,d1
	bcs.s	replace_at_delete               ; empty: delete only
replace_at_copy:
	move.b	(a0)+,(a2)+
	dbra	d1,replace_at_copy
	move.w	replace_string(a6),d1           ; the new length
	move.w	find_string(a6),d2              ; the old length
	bsr.w	text_replace_bytes              ; the one for the other
	st	text_modified(a6)               ; modified
	st	text_touched(a6)
	lea	-$1(a3),a1                      ; its last character
	rts
replace_at_delete:
	moveq	#0,d1
	move.w	find_string(a6),d1              ; the find string's length
	bsr.w	text_delete_bytes               ; deleted
	movea.l	a3,a1
	rts

;------------------------------------------------------------------------------
; Replace All: replace every find string from the cursor to the end (Esc stops it at a line's end), then
; redraw and show "Replaced" with the count.
;------------------------------------------------------------------------------
replace_all:	; from: editor_command_event
	tst.w	find_string(a6)                 ; a find string?
	beq.s	replace_all_done                ; no
	bsr.w	cursor_char                     ; where the cursor is
	moveq	#0,d4                           ; the count
	subq.l	#1,a1
replace_all_loop:
	addq.l	#1,a1
	cmpa.l	text_end(a6),a1                 ; the end?
	bcc.s	replace_all_end                 ; yes
	move.b	(a1),d1
	cmp.b	#$d,d1                          ; a line's end?
	bne.s	replace_all_try                 ; no
	bsr.w	editor_check_escape             ; Esc pressed?
	bne.s	replace_all_loop                ; no: on
	bra.s	replace_all_end                 ; yes: stop
replace_all_try:
	bsr.w	match_find_string               ; the string here?
	bne.s	replace_all_loop                ; no
	bsr.s	replace_at                      ; replaced
	addq.w	#1,d4                           ; counted
	bra.s	replace_all_loop
replace_all_end:
	tst.w	d4                              ; any?
	beq.s	replace_all_count               ; no
	movem.l	d4/d6-d7/a4,-(sp)
	bsr.w	redraw_text                     ; the window drawn
	movem.l	(sp)+,d4/d6-d7/a4
	bsr.w	editor_cursor_visible           ; the cursor placed
replace_all_count:
	bsr.w	message_replaced                ; "Replaced" and the count
replace_all_done:
	rts

;------------------------------------------------------------------------------
; The find and replace dialog: the case buttons set from case_fold_code, then the find and replace strings
; and the case folding from what the user chose.  Z set when they chose Previous; Cancel empties the
; find string.
;------------------------------------------------------------------------------
find_dialog:	; from: cmd_find
	lea	find_case_object(a6),a0         ; the "test=TEST" button
	lea	$18(a0),a1                      ; the "test<>TEST" button
	cmpi.w	#$4e75,case_fold_code(a6)       ; case matters now?
	beq.s	find_dialog_set_case            ; yes
	exg	a1,a0                           ; no: the other one
find_dialog_set_case:
	move.w	#$0,$a(a0)                      ; not selected
	move.w	#$1,$a(a1)                      ; selected
	lea	find_tree-data_base(a6),a0      ; the dialog
	moveq	#100,d4
	bsr.w	gem_dialog                      ; run
	lea	find_string(a6),a1
	cmp.w	#$9,d4                          ; Cancel?
	bne.s	find_dialog_case                ; no
	clr.w	(a1)                            ; no find string
	rts
find_dialog_case:
	move.w	#$4e75,d0                       ; rts: case matters
	btst	#$0,find_case_state(a6)         ; "test=TEST" chosen?
	beq.s	find_dialog_store               ; no
	move.w	find_upper_case(pc),d0          ; yes: fold to upper case
find_dialog_store:
	move.w	d0,case_fold_code(a6)           ; the case folding set
	movea.l	find_text_spec(a6),a0           ; the find text
	bsr.s	copy_dialog_text
	movea.l	replace_text_spec(a6),a0        ; the replace text
	lea	replace_string(a6),a1
	bsr.s	copy_dialog_text
	bsr.w	gem_drop_messages               ; the screen redrawn
	bsr.w	redraw_under_dialog
	cmp.b	#$a,d4                          ; Previous?
	rts

;------------------------------------------------------------------------------
; Copy the text of the tedinfo at (a0) to a1 as a length word and the characters.
;------------------------------------------------------------------------------
copy_dialog_text:	; from: find_dialog
	moveq	#0,d0
	movea.l	(a0),a0                         ; the text
copy_dialog_text_loop:
	move.b	(a0)+,d1
	beq.s	copy_dialog_text_done           ; the end
	move.b	d1,2(a1,d0.w)
	addq.w	#1,d0
	bra.s	copy_dialog_text_loop
copy_dialog_text_done:
	move.w	d0,(a1)                         ; the length
	rts

;------------------------------------------------------------------------------
; Alt-I: insert a file the file selector names in front of the cursor's line.
;------------------------------------------------------------------------------
cmd_insert_file:	; from: editor_alt_key
	clr.w	selector_name(a6)               ; no name offered
	bsr.w	select_insert_file              ; "Insert a file"
	bne.s	insert_file_done                ; cancelled
	bsr.w	open_input_file                 ; opened, its length in d1
	bne.s	insert_file_done                ; failed
	move.l	text_end(a6),d0
	add.l	d1,d0
	cmp.l	text_limit(a6),d0               ; will it fit?
	bcs.s	insert_file_read                ; yes
	bra.w	load_too_big                    ; no: the alert
insert_file_read:
	movea.l	a4,a3                           ; in front of the line
	bsr.w	text_make_room                  ; room made
	bne.w	close_text_file                 ; no memory: closed
	move.l	d1,-(sp)                        ; the room
	bsr.w	read_text_file                  ; read in, the line ends made CR
	move.l	(sp)+,d2
	bsr.w	text_count_lines                ; the lines counted
	sub.l	d1,d2                           ; the room not used
	beq.s	insert_file_redraw              ; none
	add.l	a4,d1
	movea.l	d1,a3                           ; after what was read
	move.l	d2,d1
	bsr.w	text_delete_bytes               ; taken out again
	bsr.w	gem_drop_messages               ; the screen redrawn
insert_file_redraw:
	st	text_modified(a6)               ; modified
	bsr.w	redraw_text                     ; the window drawn
insert_file_done:
	clr.w	selector_name(a6)
	rts

;------------------------------------------------------------------------------
; Make room for d1 bytes at a3 by moving the text from there up; the block marks move with it.  Z set when
; done, else "Out of memory!" and d0 -1.  d1 and a1 are kept.
;------------------------------------------------------------------------------
text_make_room:	; from: key_block_copy, key_block_paste, key_return, editor_load_file, key_undo, cmd_insert_file, 1 more
	move.l	text_end(a6),d0                 ; the end
	add.l	d1,d0
	cmp.l	text_limit(a6),d0               ; past the limit?
	bcs.s	make_room_move                  ; no
	move.l	a1,-(sp)
	lea	msg_out_of_memory(pc),a1        ; "Out of memory!"
	bsr.w	message_beep                    ; shown
	movea.l	(sp)+,a1
	moveq	#-1,d0                          ; NE
	rts
msg_out_of_memory:
	dc.w	$000e                           ; its length
	dc.b	'Out of memory!'
make_room_move:
	bsr.w	adjust_block_marks              ; the block marks moved
	st	text_modified(a6)               ; modified
	st	text_touched(a6)
	move.l	text_end(a6),d0
	sub.l	a3,d0                           ; the bytes from a3 to the end
	movea.l	text_end(a6),a0
	movem.l	d1/a1,-(sp)
	addq.l	#1,a0                           ; past the end's CR
	lea	0(a0,d1.l),a1                   ; the new end
	addq.l	#1,d0                           ; with the CR
	bsr.s	text_move_up                    ; moved up
	movem.l	(sp)+,d1/a1
	add.l	d1,text_end(a6)                 ; the end moved
	moveq	#0,d0                           ; Z
	rts

;------------------------------------------------------------------------------
; Copy d0 bytes ending at a0 to end at a1, from the top down (for moving text up), 16 at a time.
;------------------------------------------------------------------------------
text_move_up:	; from: text_make_room
	move.l	d0,d1
	andi.w	#$f,d0                          ; the odd ones
	add.w	d0,d0
	lsr.l	#4,d1                           ; the rounds of 16
	neg.w	d0
	addi.w	#$20,d0                         ; the way in
	jmp	move_up_loop(pc,d0.w)
move_up_loop:
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	move.b	-(a0),-(a1)
	dbra	d1,move_up_loop
	rts

;------------------------------------------------------------------------------
; Replace d2 bytes at a3 with the d1 bytes in line_buffer; a3 ends after them.  NE when there was no room.
;------------------------------------------------------------------------------
text_replace_bytes:	; from: line_edit, replace_at
	cmp.w	d1,d2                           ; the same length?
	beq.s	replace_bytes_copy              ; yes
	bcs.s	replace_bytes_grow              ; longer
	move.w	d1,-(sp)
	sub.w	d1,d2
	move.w	d2,d1                           ; the bytes too many
	andi.l	#$ffff,d1
	bsr.w	text_delete_bytes               ; deleted
	move.w	(sp)+,d1
	bra.s	replace_bytes_copy
replace_bytes_grow:
	move.w	d1,-(sp)
	sub.w	d2,d1                           ; the bytes more
	andi.l	#$ffff,d1
	bsr.w	text_make_room                  ; room made
	beq.s	replace_bytes_grown
	addq.w	#2,sp                           ; no room
	rts                                     ; NE
replace_bytes_grown:
	move.w	(sp)+,d1
replace_bytes_copy:
	subq.w	#1,d1
	bcs.s	replace_bytes_done              ; none
	lea	path_buffer(a6),a0              ; the new bytes
replace_bytes_copy_loop:
	move.b	(a0)+,(a3)+
	dbra	d1,replace_bytes_copy_loop
replace_bytes_done:
	rts

;------------------------------------------------------------------------------
; Move the block marks for d1 bytes put in (d1 negative: taken out) at a3.
;------------------------------------------------------------------------------
adjust_block_marks:	; from: text_make_room, text_delete_bytes
	movem.l	d0-d1/a0-a1,-(sp)
	jsr	adjust_marks_after_replace
	movem.l	(sp)+,d0-d1/a0-a1
	rts

;------------------------------------------------------------------------------
; Delete d1 bytes at a3 by moving the text after them down; the block marks move with it.
;------------------------------------------------------------------------------
text_delete_bytes:                              ; from: key_delete_line, key_delete_to_end, key_block_delete,
                                                ;   replace_at, cmd_insert_file, text_replace_bytes
	st	text_modified(a6)               ; modified
	st	text_touched(a6)
	neg.l	d1                              ; taken out
	bsr.s	adjust_block_marks              ; the marks moved
	neg.l	d1
	move.l	text_end(a6),d0
	sub.l	a3,d0                           ; the bytes from a3 on
	beq.s	delete_bytes_end                ; none
	movea.l	a3,a0
	movem.l	d1/a1,-(sp)
	lea	0(a0,d1.l),a1                   ; from after them
	addq.l	#1,d0                           ; with the end's CR
	bsr.s	text_move_down                  ; moved down
	movem.l	(sp)+,d1/a1
delete_bytes_end:
	sub.l	d1,text_end(a6)                 ; the end moved
	movea.l	text_start(a6),a0
	cmpa.l	text_end(a6),a0                 ; past the start?
	bcs.s	delete_bytes_done               ; yes
	move.l	a0,text_end(a6)                 ; no: the end is the start
	move.b	#$d,(a0)                        ; with its CR
delete_bytes_done:
	rts

;------------------------------------------------------------------------------
; Copy d0 bytes from a1 to a0, from the bottom up (for moving text down), 16 at a time.
;------------------------------------------------------------------------------
text_move_down:	; from: text_delete_bytes
	move.l	d0,d1
	andi.w	#$f,d0                          ; the odd ones
	add.w	d0,d0
	lsr.l	#4,d1                           ; the rounds of 16
	neg.w	d0
	addi.w	#$20,d0                         ; the way in
	jmp	move_down_loop(pc,d0.w)
move_down_loop:
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	dbra	d1,move_down_loop
	rts

;------------------------------------------------------------------------------
; Copy the line a4 to expanded_line with its tabs as spaces, cut at 254 columns: a0 = expanded_line and d5
; the length with the CR.
;------------------------------------------------------------------------------
editor_expand_line:	; from: redraw_text, redraw_cursor_line, print_block
	movea.l	a4,a1
	lea	expanded_line(a6),a0            ; the copy
	moveq	#0,d4                           ; the next tab stop
	moveq	#0,d5                           ; the column
expand_line_loop:
	move.b	(a1)+,d1                        ; a character
	cmp.w	#$fe,d5                         ; 254 columns?
	bcs.s	expand_line_char                ; no
	moveq	#13,d1                          ; yes: the end
expand_line_char:
	cmp.b	#$d,d1                          ; the CR?
	bne.s	expand_line_not_cr              ; no
	move.b	d1,0(a0,d5.w)
	addq.w	#1,d5                           ; with it
	rts
expand_line_not_cr:
	cmp.b	#$9,d1                          ; a tab?
	bne.s	expand_line_store               ; no
expand_line_tab:
	add.w	tab_size(a6),d4                 ; the next tab stop
	move.w	d4,d0
	sub.w	d5,d0
	bls.s	expand_line_tab
	subq.w	#1,d0                           ; the spaces to it
	moveq	#32,d1
expand_line_spaces:
	move.b	d1,0(a0,d5.w)
	addq.w	#1,d5
	dbra	d0,expand_line_spaces
	bra.s	expand_line_loop
expand_line_store:
	move.b	d1,0(a0,d5.w)
	addq.w	#1,d5
	bra.s	expand_line_loop

;------------------------------------------------------------------------------
; The number d1 as decimal text at a1, ending with a zero byte (a1 kept).
;------------------------------------------------------------------------------
decimal_to_text:	; from: menu_preferences
	move.l	a5,-(sp)
	movea.l	a1,a5                           ; where
	move.w	output_mode(a6),-(sp)
	move.w	#$ffff,output_mode(a6)          ; the output into memory
	moveq	#1,d2                           ; no leading zeros
	bsr.w	print_decimal_long              ; written
	move.w	(sp)+,output_mode(a6)
	movea.l	a5,a1
	clr.b	(a5)                            ; ended
	movea.l	(sp)+,a5
	rts

;------------------------------------------------------------------------------
; Print the word d4 as five digits, leading zeros as spaces, then a space (the status line's numbers).
;------------------------------------------------------------------------------
status_number:	; from: status_number_at
	movem.l	d0-d3,-(sp)
	move.w	d4,d1
	moveq	#0,d2                           ; leading spaces
	bsr.s	print_decimal_word
number_trailing_space:	; from: print_number_spaced
	moveq	#32,d1
	bsr.w	editor_put_char
	movem.l	(sp)+,d0-d3
	rts

;------------------------------------------------------------------------------
; Print a space, the word d4 with no leading zeros and a space.
;------------------------------------------------------------------------------
print_number_spaced:	; from: message_replaced
	movem.l	d0-d3,-(sp)
	moveq	#32,d1
	bsr.w	editor_put_char
	move.w	d4,d1
	moveq	#1,d2                           ; no leading zeros
	bsr.s	print_decimal_word
	bra.s	number_trailing_space
	movem.l	d0-d3,-(sp)                     ; (not called: the same for the long d1)
	move.l	d1,-(sp)
	moveq	#32,d1
	bsr.w	editor_put_char
	move.l	(sp)+,d1
	moveq	#1,d2
	bsr.w	print_decimal_long
	bra.s	number_trailing_space

;------------------------------------------------------------------------------
; Print the word d1 in decimal, five digits.  d2: 0 leading zeros as spaces, 1 left out, -1 printed.
;------------------------------------------------------------------------------
print_decimal_word:	; from: status_number, print_number_spaced
	move.l	#$2710,d3                       ; from 10000
	moveq	#4,d0                           ; five digits
print_decimal_digit:	; from: print_decimal_long
	andi.l	#$ffff,d1
	divu.w	d3,d1                           ; the digit
	bne.s	print_decimal_nonzero           ; not 0
	tst.b	d0                              ; the last digit?
	beq.s	print_decimal_out               ; yes: printed
	tst.b	d2                              ; past the leading zeros?
	bmi.s	print_decimal_out               ; yes: printed
	bne.s	print_decimal_next              ; left out
	move.b	#$f0,d1                         ; a space
	bra.s	print_decimal_out
print_decimal_nonzero:
	st	d2                              ; the zeros from now printed
print_decimal_out:
	addi.b	#$30,d1
	bsr.w	editor_put_char                 ; printed
print_decimal_next:
	swap	d1                              ; the remainder
	andi.l	#$ffff,d1
	divu.w	#$a,d3                          ; the next power
	dbra	d0,print_decimal_digit
	rts

;------------------------------------------------------------------------------
; Print the long d1 in decimal, ten digits, with d2 as for print_decimal_word.
;------------------------------------------------------------------------------
print_decimal_long:	; from: decimal_to_text, print_number_spaced, help_dialog, update_status_line
	movem.l	d4/a0,-(sp)
	lea	decimal_powers(pc),a0           ; the powers of ten
	move.l	d1,d4
	moveq	#5,d0                           ; six digits here
long_decimal_digit:
	moveq	#-1,d1
long_decimal_subtract:
	addq.b	#1,d1
	sub.l	(a0),d4                         ; the power taken
	bcc.s	long_decimal_subtract           ; until below 0
	add.l	(a0)+,d4                        ; back
	tst.b	d1                              ; not 0?
	bne.s	long_decimal_nonzero
	tst.b	d2                              ; past the leading zeros?
	bmi.s	long_decimal_out                ; yes: printed
	bne.s	long_decimal_next               ; left out
	moveq	#-16,d1                         ; a space
	bra.s	long_decimal_out
long_decimal_nonzero:
	st	d2                              ; the zeros from now printed
long_decimal_out:
	addi.b	#$30,d1
	bsr.w	editor_put_char                 ; printed
long_decimal_next:
	dbra	d0,long_decimal_digit
	move.l	d4,d1                           ; the rest, below 10000
	movem.l	(sp)+,d4/a0
	move.l	#$3e8,d3                        ; from 1000
	moveq	#3,d0                           ; four digits
	bra.s	print_decimal_digit
decimal_powers:
	dc.w	$3b9a,$ca00,$05f5,$e100,$0098,$9680,$000f,$4240 ; 1000000000, 100000000, 10000000, 1000000
	dc.w	$0001,$86a0,$0000,$2710         ; 100000, 10000
status_template:	; from: draw_status_line
	dc.b	$00                             ; the status line, with a length word
	dc.b	' Line:      Col:      Mem:       '

;------------------------------------------------------------------------------
; Delete File: delete a file the file selector names.
;------------------------------------------------------------------------------
cmd_delete_file:	; from: editor_command_event
	clr.b	selector_name(a6)               ; no name offered
	lea	delete_title(a6),a0             ; "Warning - DELETE a file"
	bsr.w	file_selector                   ; the selector
	bne.s	delete_file_done                ; cancelled
	lea	selector_name(a6),a0            ; its name
	bsr.w	make_full_path                  ; with the path
	move.l	a0,-(sp)
	move.w	#$41,-(sp)
	trap	#1                              ; Fdelete
	addq.l	#6,sp
	tst.w	d0
	beq.s	delete_file_done                ; done
	bsr.w	show_dos_error                  ; else the error
delete_file_done:
	bra.w	editor_loop
	move.l	a0,-(sp)                        ; (not called: a command line from the text at a0)
	bra.s	build_command_line

;------------------------------------------------------------------------------
; Run Other: the program a1 in the dialog, then the command line the user types (each "%" the file's name,
; "%%" one "%") into command_line.  a1 = command_line, d0 0; NE when cancelled.
;------------------------------------------------------------------------------
run_other_dialog:	; from: menu_run_other_drop
	move.l	a0,-(sp)
	movea.l	run_name_spec(a6),a0            ; the program's name in it
run_other_copy_name:
	move.b	(a1)+,(a0)+
	bne.s	run_other_copy_name
	moveq	#100,d4
	lea	run_other_tree-data_base(a6),a0 ; the dialog
	bsr.w	gem_dialog                      ; run
	subq.w	#5,d4                           ; OK?
	bne.s	run_other_dialog_done           ; no
	movea.l	run_command_spec(a6),a0         ; the command line typed
	movea.l	(a0),a0
build_command_line:	; from: cmd_delete_file
	lea	command_text(a6),a1             ; after the length byte
	move.l	a1,-(sp)
build_command_loop:
	move.b	(a0)+,d1                        ; a character
	move.b	d1,(a1)+
	beq.s	build_command_done              ; the end
	cmp.b	#$25,d1                         ; "%"?
	bne.s	build_command_loop              ; no
	tst.b	(a0)                            ; the last?
	beq.s	build_command_loop              ; yes: kept
	cmp.b	(a0)+,d1                        ; "%%"?
	beq.s	build_command_loop              ; yes: one
	subq.l	#1,a0
	lea	file_name(a6),a2                ; the file's name
	subq.l	#1,a1                           ; instead of the "%"
build_command_name:
	move.b	(a2)+,(a1)+
	bne.s	build_command_name
	subq.l	#1,a1
	bra.s	build_command_loop
build_command_done:
	move.l	a1,d0
	movea.l	(sp)+,a1
	sub.l	a1,d0
	subq.b	#1,d0                           ; the length
	move.b	d0,-(a1)                        ; in front
	moveq	#0,d0
run_other_dialog_done:
	movea.l	(sp)+,a0
	rts

;------------------------------------------------------------------------------
; Put the assembler's version ("2.25") into the editor's title text, when the assembler is in this image.
;------------------------------------------------------------------------------
set_version_title:	; from: gem_init
	tst.b	assembler_linked(a6)            ; linked?
	beq.s	set_version_done                ; no
	lea	title_version(pc),a1            ; the title's version
	lea	asm_entry(pc),a0                ; the assembler's header
	moveq	#0,d1
	move.w	2(a0),d1                        ; the version's offset
	adda.l	d1,a0
set_version_loop:
	move.b	(a0)+,d1
	cmp.b	#$d,d1                          ; up to the CR
	beq.s	set_version_done
	move.b	d1,(a1)+
	bra.s	set_version_loop
set_version_done:
	rts
monst_file_name:	; from: load_monst
	dc.b	'MONST2.PRG',0
	dc.b	$00

;------------------------------------------------------------------------------
; Load MonST2.PRG into memory and MONST2.INF into its settings.  d0 0 when it is loaded.
;------------------------------------------------------------------------------
load_monst:	; from: editor_init
	move.l	a3,-(sp)
	lea	monst_file_name(pc),a1
	lea	monst_inf_name(pc),a3           ; its settings file
	bsr.s	load_program_image              ; loaded
	movem.l	(sp)+,a3
	rts

;------------------------------------------------------------------------------
; Find and open the program a1 (shel_find), read its header and as many bytes as its text length says into a
; new block (monst_image), then set its settings from the file a3.  d0 0 when done, -1 when not.
;------------------------------------------------------------------------------
load_program_image:	; from: load_monst
	bsr.w	open_found_file                 ; found and opened
	bne.w	load_image_error                ; no
	pea	path_buffer(a6)
	pea	$1c.w                           ; the header
	move.w	d3,-(sp)
	move.w	#$3f,-(sp)
	trap	#1                              ; Fread
	lea	$c(sp),sp
	cmp.l	#$1c,d0                         ; all of it?
	bne.w	load_image_failed               ; no
	move.l	header_text_length(a6),d0       ; the text length
	bsr.w	malloc_leave_free               ; Malloc
	beq.s	load_image_failed               ; no memory
	move.l	d0,monst_image(a6)              ; MonST's image
	move.l	d0,-(sp)
	move.l	header_text_length(a6),-(sp)
	move.w	d3,-(sp)
	move.w	#$3f,-(sp)
	trap	#1                              ; Fread
	lea	$c(sp),sp
	cmp.l	header_text_length(a6),d0       ; all of it?
	bne.s	load_image_read_failed          ; no

;------------------------------------------------------------------------------
; Close the file; when the image has "AP" at +2, mark it and read up to 100 bytes of the settings file a3
; into it at +4.
;------------------------------------------------------------------------------
monst_settings:
	bsr.w	dos_fclose                      ; closed
	movea.l	monst_image(a6),a0
	cmpi.w	#$4150,2(a0)                    ; "AP"?
	bne.s	monst_settings_done             ; no
	st	4(a0)                           ; marked
	movea.l	a3,a0                           ; the settings file
	bsr.w	dos_fopen_read                  ; opened
	bne.s	monst_settings_done             ; no
	movea.l	monst_image(a6),a0
	addq.w	#4,a0                           ; at +4
	moveq	#100,d4                         ; 100 bytes at most
	bsr.w	dos_fread                       ; read
	bsr.w	dos_fclose                      ; closed
monst_settings_done:
	moveq	#0,d0                           ; loaded
	rts
load_image_read_failed:	; from: load_program_image
	move.l	monst_image(a6),-(sp)
	move.w	#$49,-(sp)
	trap	#1                              ; Mfree
	addq.l	#6,sp
load_image_failed:	; from: load_program_image
	bsr.s	monst_settings                  ; closed
load_image_error:	; from: load_program_image
	moveq	#-1,d0                          ; not loaded
cmd_debug_done:	; from: cmd_debug
	rts
no_program_alert:	; from: cmd_debug
	lea	alert_no_program,a1             ; "No program in memory"
	moveq	#1,d1
	bra.w	gem_alert
monst_inf_name:	; from: load_monst
	dc.b	'MONST2.INF',0
	dc.b	$00

;------------------------------------------------------------------------------
; Alt-D: MonST on the program assembled to memory: GenST's basepage holds "AMPM" at +$80 and the program
; at +$84 for it to find.
;------------------------------------------------------------------------------
cmd_debug:	; from: editor_alt_key
	bsr.w	program_in_memory               ; a program?
	beq.s	no_program_alert                ; no
	tst.l	monst_image(a6)                 ; MonST loaded?
	beq.s	cmd_debug_done                  ; no: nothing
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	move.l	#$414d504d,$80(a0)              ; "AMPM"
	move.l	program_block(a6),$84(a0)       ; the program
	bra.s	run_monst

;------------------------------------------------------------------------------
; Alt-M: MonST on its own: "AMP",0 at +$80 of GenST's basepage.
;------------------------------------------------------------------------------
cmd_monst:	; from: editor_alt_key
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	move.l	#$414d5000,$80(a0)              ; "AMP",0
run_monst:	; from: cmd_debug
	lea	path_buffer(a6),a1              ; an empty command line
	clr.w	(a1)
	move.l	a4,-(sp)
	move.l	monst_image(a6),d0              ; MonST's image
	beq.s	run_monst_done                  ; none
	movea.l	d0,a4
	tst.b	run_with_gem(a6)                ; run with GEM?
	bne.s	run_monst_gem                   ; yes
	bsr.w	prepare_tos_screen              ; no: the screen for a TOS program
	bra.s	run_monst_ready
run_monst_gem:
	bsr.w	busy_mouse                      ; the busy mouse
	bsr.w	prepare_gem_program             ; the screen for a GEM program
run_monst_ready:
	bne.s	run_monst_done                  ; failed
	bsr.w	exec_in_memory                  ; run from its image
	move.w	d0,-(sp)
	jsr	(a3)                            ; the screen back
	move.w	(sp)+,d0
	bpl.s	run_monst_done                  ; all right
	bsr.w	show_dos_error                  ; else the error
run_monst_done:
	movea.l	(sp)+,a4
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	clr.l	$80(a0)                         ; the marks cleared
	bra.w	arrow_mouse                     ; the arrow mouse

;------------------------------------------------------------------------------
; The editor's settings at the start: run with GEM, load MonST and stop at a line's end, then the
; preferences file over them.  Loads MonST when they say so; without it MonST and Debug are disabled.
;------------------------------------------------------------------------------
editor_init:	; from: aes_call
	bsr.w	busy_mouse                      ; the busy mouse
	st	run_with_gem(a6)                ; run with GEM
	st	monst_wanted(a6)                ; load MonST
	sf	end_of_line_wrap(a6)            ; stop at a line's end
	bsr.w	load_preferences                ; the preferences file
	bsr.w	set_gem_check                   ; the Run with GEM check mark
	clr.l	program_block(a6)               ; no program
	clr.l	monst_image(a6)                 ; no MonST
	clr.l	startup_long(a6)
	tst.b	monst_wanted(a6)                ; load MonST?
	beq.s	editor_init_no_monst            ; no
	bsr.w	load_monst                      ; loaded
	tst.b	d0
	beq.s	editor_init_done                ; all right
	bsr.w	arrow_mouse                     ; the arrow mouse
	lea	alert_no_monst,a1               ; "Could not find MonST2"
	moveq	#1,d1
	bsr.w	gem_alert
editor_init_no_monst:
	move.l	#$330000,intin(a6)              ; menu item 51 (MonST) disabled
	lea	menu_tree,a0                    ; the menu
	move.l	a0,ptsin(a6)
	moveq	#32,d0                          ; menu_ienable
	bsr.w	aes_call
	move.w	#$32,intin(a6)                  ; item 50 (Debug)
	moveq	#32,d0                          ; menu_ienable
	bsr.w	aes_call
editor_init_done:
	bsr.w	arrow_mouse                     ; the arrow mouse
	moveq	#0,d0                           ; all right
	rts

;------------------------------------------------------------------------------
; Alt-X: run the program assembled to memory, with an empty command line, under the TOS or GEM screen.
;------------------------------------------------------------------------------
cmd_run:	; from: editor_alt_key
	addq.l	#4,sp                           ; back to the loop by itself
	bsr.s	program_in_memory               ; a program?
	beq.s	run_no_program                  ; no
	tst.b	run_with_gem(a6)                ; run with GEM?
	bne.s	run_gem_screen                  ; yes
	bsr.w	prepare_tos_screen              ; no: the screen for a TOS program
	bra.s	run_screen_ready
run_gem_screen:
	bsr.w	busy_mouse                      ; the busy mouse
	bsr.w	prepare_gem_program             ; the screen for a GEM program
run_screen_ready:
	bne.s	run_done                        ; failed
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	clr.l	$80(a0)                         ; no marks
	movem.l	a3-a4,-(sp)
	movea.l	program_block(a6),a4            ; the program
	lea	path_buffer(a6),a1              ; an empty command line
	clr.w	(a1)
	bsr.s	run_program_image               ; run
	movem.l	(sp)+,a3-a4
	jsr	(a3)                            ; the screen back
run_done:
	bra.w	editor_loop
run_no_program:
	lea	alert_no_program,a1             ; "No program in memory"
	moveq	#1,d1
	bsr.w	gem_alert
	bra.w	editor_loop

;------------------------------------------------------------------------------
; Z set when there is no program in memory (no block, or nothing assembled into it yet); a0 the block.
;------------------------------------------------------------------------------
program_in_memory:	; from: cmd_debug, cmd_run
	move.l	program_block(a6),d0            ; the block
	beq.s	program_in_memory_done          ; none
	movea.l	d0,a0
	move.w	(a0),d0                         ; its header's first word
program_in_memory_done:
	rts

;------------------------------------------------------------------------------
; Run the program file image at a4 (a GEMDOS header, text, data, symbols and relocation) with the command
; line a1: a basepage from Pexec 5, the text and data copied in, the BSS cleared, the relocation done, then
; Pexec 4.  An rts from the program ends it through Pterm0.  d0 its result.
;------------------------------------------------------------------------------
run_program_image:	; from: cmd_run
	clr.l	-(sp)                           ; no environment
	move.l	a1,-(sp)                        ; the command line
	clr.l	-(sp)                           ; no name
	move.l	#$4b0005,-(sp)                  ; Pexec 5: a basepage
	trap	#1                              ; Pexec
	lea	$10(sp),sp
	tst.l	d0
	bmi.w	run_program_done                ; failed
	movea.l	d0,a3                           ; the basepage
	move.l	#$100,d1
	add.l	2(a4),d1                        ; + text
	add.l	6(a4),d1                        ; + data
	add.l	$a(a4),d1                       ; + BSS
	add.l	(a3),d1                         ; + its start
	cmp.l	4(a3),d1                        ; past its memory?
	bcc.w	run_free                        ; yes: not run
	addi.l	#$100,d0                        ; the text after the basepage
	lea	8(a3),a0                        ; p_tbase
	move.l	d0,(a0)+
	move.l	2(a4),(a0)                      ; p_tlen
	add.l	(a0)+,d0
	move.l	d0,(a0)+                        ; p_dbase
	move.l	6(a4),(a0)                      ; p_dlen
	add.l	(a0)+,d0
	move.l	d0,(a0)+                        ; p_bbase
	move.l	$a(a4),(a0)                     ; p_blen
	movea.l	8(a3),a0                        ; to the text
	lea	$1c(a4),a1                      ; from after the header
	move.l	2(a4),d0                        ; the text and data
	add.l	6(a4),d0
	lsr.l	#1,d0                           ; in words
	subq.l	#1,d0
	bcs.s	run_clear_bss
run_copy_loop:
	move.w	(a1)+,(a0)+
	dbra	d0,run_copy_loop
	subi.l	#$10000,d0
	bcc.s	run_copy_loop
run_clear_bss:
	move.l	$a(a4),d0                       ; the BSS
	lsr.l	#2,d0                           ; in longs
	subq.l	#1,d0
	bcs.s	run_relocate
	moveq	#0,d1
run_clear_bss_loop:
	move.l	d1,(a0)+
	dbra	d0,run_clear_bss_loop
	subi.l	#$10000,d0
	bcc.s	run_clear_bss_loop
run_relocate:
	movea.l	8(a3),a0                        ; the text's place
	move.l	a0,d2
	moveq	#0,d1
	adda.l	$e(a4),a1                       ; past the symbols
	move.l	(a1)+,d0                        ; the first offset
	beq.s	run_go                          ; none: no relocation
run_relocate_add:
	add.l	d2,0(a0,d0.l)                   ; the long relocated
run_relocate_next:
	move.b	(a1)+,d1                        ; the next step
	beq.s	run_go                          ; the end
	cmp.b	#$1,d1                          ; 1?
	bne.s	run_relocate_step               ; no
	addi.l	#$fe,d0                         ; yes: 254 on
	bra.s	run_relocate_next
run_relocate_step:
	add.l	d1,d0                           ; on
	bra.s	run_relocate_add
run_go:
	movea.l	4(a3),a0                        ; the top of its memory
	lea	run_terminate(pc),a1            ; a way out through Pterm0
	move.l	a1,-$8(a0)                      ; where the program's last rts takes it
	clr.l	-(sp)
	move.l	a3,-(sp)                        ; the basepage
	clr.l	-(sp)
	move.l	#$4b0004,-(sp)                  ; Pexec 4: run it
	trap	#1                              ; Pexec
	lea	$10(sp),sp
run_free:
	move.l	$2c(a3),-(sp)                   ; its environment
	movea.l	a3,a0
	bsr.w	dos_mfree                       ; Mfree the basepage
	movea.l	(sp)+,a0
	bsr.w	dos_mfree                       ; Mfree the environment
run_program_done:
	rts
run_terminate:
	clr.w	-(sp)
	trap	#1                              ; Pterm0

;------------------------------------------------------------------------------
; Alt-A: assemble the text.  The Assembly Options dialog (left out when Shift is held) gives the command line
; (the file's name, then -QT and the tab size and the options: L/L2 GST/DRI linkable, C case independent,
; D/X debug, B no binary, O and a name, M slow, P and CON:, PRN: or AUX: for a listing).  GenST's basepage
; at +$80 holds 0,"AMP", the text's start and end, the error list, the output block and its size.  The
; assembler runs as a program from its place in this image (or by trap #10); then the first error is shown.
;------------------------------------------------------------------------------
cmd_assemble:	; from: editor_alt_key
	addq.l	#4,sp                           ; back to the loop by itself
	andi.b	#$3,intout4_low(a6)             ; Shift held?
	bne.s	assemble_options_set            ; yes: no dialog
	lea	options_tree(pc),a0             ; the Assembly Options dialog
	moveq	#100,d4
	bsr.w	gem_dialog                      ; run
	cmp.w	#$2,d4                          ; Cancel?
	beq.w	editor_loop                     ; yes
assemble_options_set:
	bsr.w	free_program_memory             ; the program and the block freed
	btst	#$0,options_output_memory_state(pc) ; output to memory?
	beq.s	assemble_command_line           ; no
	lea	options_max_text(pc),a1         ; the "Max:___k" text
	bsr.w	parse_line_number               ; as a number
	cmp.w	#$4,d4                          ; below 4?
	bcc.s	assemble_memory_size            ; no
	moveq	#4,d4                           ; 4 K at least
assemble_memory_size:
	moveq	#0,d5
	move.w	d4,d5
	moveq	#10,d1
	lsl.l	d1,d5                           ; in bytes
	move.l	d5,d0
	bsr.w	malloc_leave_free               ; Malloc
	bne.s	assemble_memory_got             ; got it
	moveq	#-39,d0                         ; "insufficient memory"
	bsr.w	show_dos_error                  ; the error
	bra.w	editor_loop
assemble_memory_got:
	move.l	d0,program_block(a6)            ; the output block
	clr.w	(a0)                            ; no program in it yet
assemble_command_line:
	lea	command_text(a6),a2             ; the command line's text
	moveq	#32,d4
	lea	file_name(a6),a0                ; the file's name
	tst.b	(a0)                            ; one?
	bne.s	assemble_copy_name              ; yes
	lea	default_file_name(pc),a0        ; no: "NONAME."
assemble_copy_name:
	move.b	(a0)+,(a2)+
	bne.s	assemble_copy_name
	move.b	d4,-$1(a2)                      ; then a space
	move.b	#$2d,(a2)+                      ; "-"
	move.b	#$51,(a2)+                      ; "Q"
	move.b	#$54,(a2)+                      ; "T"
	moveq	#0,d0
	move.w	tab_size(a6),d0                 ; the tab size
	cmp.b	#$a,d0                          ; below 10?
	bcs.s	assemble_tab_units              ; yes
	divu.w	#$a,d0
	addi.b	#$30,d0                         ; the tens
	move.b	d0,(a2)+
	swap	d0
assemble_tab_units:
	addi.b	#$30,d0                         ; the units
	move.b	d0,(a2)+
	btst	#$0,options_exec_state(pc)      ; Exec?
	bne.s	assemble_case                   ; yes
	move.b	#$4c,(a2)+                      ; no: "L" linkable
	btst	#$0,options_gst_state(pc)       ; GST?
	bne.s	assemble_case                   ; yes
	move.b	#$32,(a2)+                      ; no: "2" DRI
assemble_case:
	btst	#$0,options_case_state(pc)      ; case dependent?
	bne.s	assemble_debug                  ; yes
	move.b	#$43,(a2)+                      ; no: "C"
assemble_debug:
	btst	#$0,options_debug_normal_state(pc) ; normal debug?
	beq.s	assemble_extended               ; no
	move.b	#$44,(a2)+                      ; yes: "D"
assemble_extended:
	btst	#$0,options_debug_extended_state(pc) ; extended debug?
	beq.s	assemble_output                 ; no
	move.b	#$58,(a2)+                      ; yes: "X"
assemble_output:
	btst	#$0,options_output_none_state(pc) ; output none?
	beq.s	assemble_output_disk            ; no
	move.b	#$42,(a2)+                      ; yes: "B"
	bra.s	assemble_speed
assemble_output_disk:
	btst	#$0,options_output_disk_state(pc) ; output to disk?
	beq.s	assemble_speed                  ; no
	move.b	#$4f,(a2)+                      ; yes: "O"
	lea	options_file_text(pc),a0        ; and the name
	lea	options_file_text(pc),a0
assemble_output_name:
	move.b	(a0)+,(a2)+
	bne.s	assemble_output_name
	move.b	#$20,-$1(a2)                    ; then a space
	move.b	#$2d,(a2)+                      ; "-"
assemble_speed:
	btst	#$0,options_slow_state(pc)      ; slow?
	beq.s	assemble_listing                ; no
	move.b	#$4d,(a2)+                      ; yes: "M"
assemble_listing:
	btst	#$0,options_list_none_state(pc) ; no listing?
	bne.s	assemble_trim                   ; yes
	move.b	#$50,(a2)+                      ; "P"
	btst	#$0,options_list_disk_state(pc) ; to disk?
	bne.s	assemble_listing_space          ; yes
	lea	listing_devices(pc),a0          ; the devices
	btst	#$0,options_list_screen_state(pc) ; to the screen?
	bne.s	assemble_listing_device         ; yes: CON
	movem.l	d1-d2/a0-a2,-(sp)
	move.l	#$21ffff,-(sp)                  ; Setprt(-1): the printer's setting
	trap	#14                             ; Setprt
	addq.l	#4,sp
	movem.l	(sp)+,d1-d2/a0-a2
	addq.l	#3,a0                           ; PRN
	btst	#$4,d0                          ; serial?
	beq.s	assemble_listing_device         ; no
	addq.l	#3,a0                           ; yes: AUX
assemble_listing_device:
	move.b	(a0)+,(a2)+
	move.b	(a0)+,(a2)+
	move.b	(a0)+,(a2)+
	move.b	#$3a,(a2)+                      ; ":"
assemble_listing_space:
	move.b	#$20,(a2)+                      ; a space
assemble_trim:
	cmpi.b	#$2d,-$1(a2)                    ; ends in "-"?
	bne.s	assemble_call                   ; no
	subq.l	#2,a2                           ; yes: " -" off
assemble_call:
	lea	command_text(a6),a0
	move.l	a2,d0
	clr.b	(a2)                            ; ended
	sub.l	a0,d0
	move.b	d0,-(a0)                        ; the length in front
	movea.l	own_basepage(a6),a1             ; GenST's basepage
	lea	$80(a1),a1                      ; +$80
	move.l	#$414d50,(a1)+                  ; 0,"AMP"
	move.l	text_start(a6),(a1)+            ; the source's start
	movea.l	text_end(a6),a2                 ; its end
	move.b	#$d,(a2)+                       ; with a CR
	move.l	a2,(a1)+
	lea	error_list_size(a6),a2          ; the error list
	move.l	#$1e0000,(a2)                   ; 30 entries, none yet
	move.l	a2,(a1)+
	move.l	program_block(a6),(a1)+         ; the output block
	move.l	d5,(a1)+                        ; its size
	movea.l	a0,a1                           ; the command line
	lea	asm_entry(pc),a0                ; the assembler
	tst.b	assembler_linked(a6)            ; in this image?
	bne.w	assemble_linked                 ; yes
	trap	#10                             ; no: the resident one
	bra.w	editor_loop
default_file_name:
	dc.b	'NONAME.',0
listing_devices:
	dc.b	'CONPRNAUX',0                   ; the three listing devices
assemble_linked:
	move.l	a4,-(sp)
	movea.l	a0,a4                           ; the assembler's place
	bsr.w	prepare_tos_screen              ; the screen for a TOS program
	bne.s	assemble_finished               ; failed
	bsr.w	exec_in_memory                  ; run as a program
	move.w	d0,-(sp)
	jsr	(a3)                            ; the screen back
	move.w	(sp)+,d0
assemble_finished:
	movea.l	(sp)+,a4
	pea	editor_loop(pc)                 ; back to the loop after
	cmp.w	#$ffe0,d0                       ; -32?
	beq.s	assemble_show_errors            ; yes: no message
	tst.w	d0                              ; an error?
	bmi.w	show_dos_error                  ; yes: the GEMDOS error
assemble_show_errors:
	bsr.w	gem_drop_messages               ; the screen redrawn
	bsr.w	redraw_window                   ; the window drawn
	bra.w	jump_first_error                ; to the first error

;------------------------------------------------------------------------------
; Find a file along the AES search path (shel_find) and open it for reading.
; a1 = the file name.  Out: d0 = 0 and d3 = the handle when opened, d0 = -1 when not found or not
; opened.  The found path is left in path_buffer.
;------------------------------------------------------------------------------
open_found_file:	; from: load_program_image
	lea	path_buffer(a6),a0              ; the name goes to the path buffer
	move.l	a0,ptsin(a6)                    ; the buffer for shel_find
open_found_file_copy:
	move.b	(a1)+,(a0)+                     ; copy the name
	bne.s	open_found_file_copy
	moveq	#124,d0                         ; shel_find
	bsr.w	aes_call
	beq.s	open_found_file_none            ; not found
	clr.w	-(sp)                           ; read only
	pea	path_buffer(a6)                 ; the path it found
	move.w	#$3d,-(sp)
	trap	#1                              ; Fopen, Fopen: open the found file
	addq.l	#8,sp
	move.w	d0,d3                           ; the handle
	bmi.s	open_found_file_none            ; failed
	moveq	#0,d0                           ; opened
	rts
open_found_file_none:
	moveq	#-1,d0                          ; not found
	rts

;------------------------------------------------------------------------------
; Program menu "Run with GEM" (Alt-K): flip the setting and its check mark.
;------------------------------------------------------------------------------
menu_run_with_gem:	; from: editor_alt_key
	not.b	run_with_gem(a6)                ; flip the setting

;------------------------------------------------------------------------------
; Set the "Run with GEM" menu item's check mark from run_with_gem.
;------------------------------------------------------------------------------
set_gem_check:	; from: editor_init
	move.w	#$34,intin(a6)                  ; menu item 52: Run with GEM
	tst.b	run_with_gem(a6)                ; on?
	sne	d0                              ; 1 when on
	andi.w	#$1,d0
	move.w	d0,intin1(a6)                   ; check or not
	lea	menu_tree,a0                    ; the menu tree
	move.l	a0,ptsin(a6)
	moveq	#31,d0                          ; menu_icheck
	bra.w	aes_call

;------------------------------------------------------------------------------
; Change the file selector path's extension to "*", so that every file shows (for Run Other).
;------------------------------------------------------------------------------
fsel_path_any_ext:	; from: menu_run_other_drop
	lea	fsel_path(a6),a0                ; the file selector path
	bsr.w	find_extension                  ; its extension
	beq.s	fsel_path_any_ext_done          ; none
	movea.l	d1,a1                           ; at the extension
	move.b	#$2a,(a1)+                      ; "*"
	clr.b	(a1)                            ; ends there
fsel_path_any_ext_done:
	rts

;------------------------------------------------------------------------------
; Program menu "Run Other" (Alt-O): pick a program with the file selector and run it.  A .PRG runs as a GEM
; program with an empty command line; anything else is asked for a command line and runs as a TOS program.
; Errors other than -32 are shown.  Goes back to the editor loop.  This entry drops a return address first.
;------------------------------------------------------------------------------
menu_run_other_drop:	; from: editor_alt_key
	addq.l	#4,sp                           ; drop the caller's return
menu_run_other:	; from: editor_command_event
	bsr.w	confirm_lose_changes            ; changes in the text: ask to go on
	bne.w	run_other_done                  ; no
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	clr.w	$80(a0)                         ; no command line of its own
	bsr.s	fsel_path_any_ext               ; show all files
	clr.b	selector_name(a6)               ; no name in the file selector
	lea	text_run_other(a6),a0           ; "Run Other Program"
	bsr.w	file_selector                   ; the file selector
	bne.w	run_other_done                  ; cancelled
	lea	selector_name(a6),a0            ; the name chosen
	bsr.w	make_full_path                  ; the full path
	bsr.w	find_extension                  ; its extension
	lea	selector_name(a6),a1            ; the name: shown in the command line dialog, or emptied as the command
                                                ;   line
	cmp.l	#$505247,d0                     ; .PRG?
	bne.s	run_other_tos                   ; no: a TOS program
	clr.w	(a1)                            ; empty command line
	bsr.s	exec_gem_program                ; run it under GEM
	bra.s	run_other_go
run_other_tos:
	bsr.w	run_other_dialog                ; ask for the command line
	bne.w	run_other_done                  ; cancelled
	bsr.s	exec_tos_program                ; run it without GEM
run_other_go:
	move.w	d0,-(sp)                        ; keep the result
	jsr	(a3)                            ; put the screen back
	move.w	(sp)+,d0                        ; the result
	bpl.s	run_other_done                  ; no error
	cmp.w	#$ffe0,d0                       ; -32?
	beq.s	run_other_done                  ; yes: not shown
	bsr.w	show_dos_error                  ; show the error
run_other_done:
	bra.w	editor_loop                     ; back to the editor loop

;------------------------------------------------------------------------------
; Run the program at a0 (full path) with command line a1 as a GEM program: GenST leaves GEM first.
; Out: d0 = Pexec's result, NE when the screen could not be prepared; a3 = the routine that puts GenST back.
;------------------------------------------------------------------------------
exec_gem_program:	; from: menu_run_other_drop
	bsr.w	prepare_gem_program             ; leave GEM
	bra.s	exec_program_pexec

;------------------------------------------------------------------------------
; Run the program at a0 (full path) with command line a1 as a TOS program, on a text screen.
; Out: d0 = Pexec's result, NE when the screen could not be prepared; a3 = the routine that puts GenST back.
;------------------------------------------------------------------------------
exec_tos_program:	; from: menu_run_other_drop
	bsr.w	prepare_tos_screen              ; text screen
exec_program_pexec:	; from: exec_gem_program
	bne.w	exec_program_done               ; failed
	movea.l	own_basepage(a6),a2             ; GenST's basepage
	move.l	$2c(a2),-(sp)                   ; its environment
	move.l	a1,-(sp)                        ; the command line
	move.l	a0,-(sp)                        ; the program
	clr.w	-(sp)                           ; load and go
	move.w	#$4b,-(sp)
	trap	#1                              ; Pexec, Pexec: run the program
	lea	$10(sp),sp
exec_program_done:
	rts

;------------------------------------------------------------------------------
; Make the screen ready for a TOS program: a desk-sized window hides the desktop, the menu bar goes, the mouse
; is hidden and the VDI enters text mode with the cursor on and line wrap.  Out: a3 = restore_tos_screen,
; d0 = 0 (Z) when done, negative when no window was left.
;------------------------------------------------------------------------------
prepare_tos_screen:	; from: cmd_monst, cmd_run, cmd_assemble, exec_tos_program
	movem.l	d0-d3/a0-a2,-(sp)
	lea	restore_tos_screen(pc),a3       ; the routine to come back with
	movem.w	desk_area(a6),d0-d3             ; the desk area
	movem.w	d0-d3,intin1(a6)                ; for wind_create
	clr.w	intin(a6)                       ; no window parts
	moveq	#100,d0                         ; wind_create
	bsr.w	aes_call
	move.w	d0,run_window(a6)               ; the cover window
	bmi.s	prepare_tos_screen_out          ; none left
	bsr.w	menu_bar_off                    ; no menu bar
	move.w	run_window(a6),intin(a6)        ; open it
	moveq	#101,d0                         ; wind_open
	bsr.w	aes_call
	move.w	#$100,intin(a6)                 ; M_OFF: mouse hidden
	moveq	#78,d0                          ; graf_mouse
	bsr.w	aes_call
	clr.w	contrl_count(a6)                ; no points
	clr.w	contrl_intin_count(a6)          ; no integers
	move.w	#$3,contrl_subcode(a6)          ; escape 3: enter text mode
	moveq	#5,d0                           ; VDI escape
	bsr.w	vdi_call
	move.w	#$3,intin(a6)                   ; BEG_MCTRL
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	clr.w	intin(a6)                       ; END_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	moveq	#27,d1                          ; Esc
	bsr.s	bios_screen_char
	moveq	#118,d1                         ; v: line wrap on
	bsr.s	bios_screen_char
	bra.s	prepare_tos_screen_ok           ; done

;------------------------------------------------------------------------------
; Send the character d1 to the screen (Bconout to the console).  Keeps a0.
;------------------------------------------------------------------------------
bios_screen_char:	; from: prepare_tos_screen
	move.l	a0,-(sp)
	move.w	d1,-(sp)                        ; the character
	move.l	#$30002,-(sp)                   ; the console, Bconout
	trap	#13                             ; Bconout, Bconout: to the screen
	addq.l	#6,sp
	movea.l	(sp)+,a0
	rts
prepare_tos_screen_ok:	; from: prepare_tos_screen
	moveq	#0,d0                           ; done
prepare_tos_screen_out:	; from: prepare_tos_screen
	movem.l	(sp)+,d0-d3/a0-a2
	rts

;------------------------------------------------------------------------------
; After a TOS program: the screen mode back, the AES given the mouse and screen again, text mode left, events
; thrown away, the cover window closed and deleted, the mouse shown and the menu bar back.
;------------------------------------------------------------------------------
restore_tos_screen:	; from: prepare_tos_screen
	bsr.w	restore_screen_mode             ; the screen mode back
	move.w	#$2,intin(a6)                   ; END_MCTRL
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	move.w	#$1,intin(a6)                   ; BEG_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	clr.w	contrl_count(a6)                ; no points
	clr.w	contrl_intin_count(a6)          ; no integers
	move.w	#$2,contrl_subcode(a6)          ; escape 2: leave text mode
	moveq	#5,d0                           ; VDI escape
	bsr.w	vdi_call
	bsr.w	gem_flush_events                ; drop the events waiting
	move.w	run_window(a6),intin(a6)        ; the cover window
	moveq	#102,d0                         ; wind_close
	bsr.w	aes_call
	moveq	#103,d0                         ; wind_delete
	bsr.w	aes_call
	move.w	#$101,intin(a6)                 ; M_ON: mouse shown
	moveq	#78,d0                          ; graf_mouse
	bsr.w	aes_call
	bsr.w	show_mouse_forced               ; the mouse shown at once
	bra.w	menu_bar_on                     ; the menu bar back

;------------------------------------------------------------------------------
; Take the menu bar off the screen.
;------------------------------------------------------------------------------
menu_bar_off:	; from: prepare_tos_screen, prepare_gem_program
	move.l	menu_tree_address(a6),ptsin(a6) ; the menu tree
	clr.w	intin(a6)                       ; off
	moveq	#30,d0                          ; menu_bar
	bra.w	aes_call

;------------------------------------------------------------------------------
; Make GenST leave GEM for a GEM program: no menu bar, the menu bar's area cleared, the editor window closed
; (its size kept in dialog_rect) and appl_exit.  Out: a3 = restore_gem_program, d0 = 0 (Z).
;------------------------------------------------------------------------------
prepare_gem_program:	; from: cmd_monst, cmd_run, exec_gem_program
	movem.l	d1-d3/a0-a2,-(sp)
	lea	restore_gem_program(pc),a3      ; the routine to come back with
	bsr.s	menu_bar_off                    ; no menu bar
	clr.w	intin(a6)                       ; clipping off
	move.w	#$2,contrl_count(a6)            ; 2 points
	move.w	#$1,contrl_intin_count(a6)      ; 1 integer
	move.w	vdi_handle(a6),contrl_handle(a6) ; the workstation
	move.w	#$81,d0                         ; vs_clip
	bsr.w	vdi_call_handle_set
	movem.w	desk_area(a6),d0-d3             ; the desk area
	move.w	d1,d3
	subq.w	#2,d3                           ; to just above it
	moveq	#0,d1                           ; from the top
	movem.w	d0-d3,ptsin(a6)                 ; the menu bar's area
	move.w	#$2,contrl_count(a6)            ; 2 points
	clr.w	contrl_intin_count(a6)          ; no integers
	moveq	#114,d0                         ; vr_recfl: cleared
	bsr.w	vdi_call
	bsr.w	clip_to_window                  ; clip to the window again
	move.w	window_handle(a6),intin(a6)     ; the editor window
	move.w	#$5,intin1(a6)                  ; WF_CURRXYWH
	moveq	#104,d0                         ; wind_get
	bsr.w	aes_call
	move.l	intout1(a6),dialog_rect(a6)     ; kept for its return
	move.l	intout3(a6),dialog_rect_size(a6)
	moveq	#102,d0                         ; wind_close
	bsr.w	aes_call
	clr.w	intin(a6)                       ; END_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	moveq	#19,d0                          ; appl_exit
	bsr.w	aes_call
	movem.l	(sp)+,d1-d3/a0-a2
	moveq	#0,d0                           ; done
	rts

;------------------------------------------------------------------------------
; After a GEM program: the screen mode back, the desktop background back to plain, appl_init again, events
; thrown away, the editor window opened where it was, the mouse shown and the menu bar back.
;------------------------------------------------------------------------------
restore_gem_program:	; from: prepare_gem_program
	bsr.w	restore_screen_mode             ; the screen mode back
	move.l	#$e,intin(a6)                   ; 0 (desktop), WF_NEWDESK
	clr.l	intin2(a6)                      ; no tree
	clr.w	intin4(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
	moveq	#10,d0                          ; appl_init
	bsr.w	aes_call
	move.w	d0,ap_id(a6)                    ; the new application id
	bsr.s	gem_flush_events                ; drop the events waiting
	move.w	#$1,intin(a6)                   ; BEG_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	move.w	window_handle(a6),intin(a6)     ; the editor window
	move.l	dialog_rect(a6),intin1(a6)      ; where it was
	move.l	dialog_rect_size(a6),intin3(a6)
	moveq	#101,d0                         ; wind_open
	bsr.w	aes_call
	bsr.w	show_mouse_forced               ; the mouse shown at once
	bsr.w	arrow_mouse                     ; arrow mouse
menu_bar_on:	; from: restore_tos_screen
	move.l	menu_tree_address(a6),ptsin(a6) ; the menu tree
	move.w	#$1,intin(a6)                   ; on
	moveq	#30,d0                          ; menu_bar
	bra.w	aes_call

;------------------------------------------------------------------------------
; Throw away every key, click and message waiting: evnt_multi with a 1 ms timer until only the timer comes.
;------------------------------------------------------------------------------
gem_flush_events:	; from: restore_tos_screen, restore_gem_program
	move.w	#$33,intin(a6)                  ; keys, button, messages and timer
	moveq	#1,d0
	move.w	d0,intin1(a6)                   ; 1 click
	move.w	d0,intin2(a6)                   ; left button
	move.w	d0,intin3(a6)                   ; down
	move.w	d0,intin4(a6)
	move.w	d0,intin14(a6)                  ; 1 ms
	clr.w	intin15(a6)
	lea	message_buffer(a6),a0           ; the message buffer
	move.l	a0,ptsin(a6)
	moveq	#25,d0                          ; evnt_multi
	bsr.w	aes_call
	btst	#$5,d0                          ; the timer?
	beq.s	gem_flush_events                ; no: more to drop
	rts

;------------------------------------------------------------------------------
; Setscreen back to GenST's screen addresses, and to the start resolution when a program changed it.
;------------------------------------------------------------------------------
restore_screen_mode:	; from: restore_tos_screen, restore_gem_program
	move.w	#$4,-(sp)
	trap	#14                             ; Getrez, Getrez: the resolution now
	addq.l	#2,sp
	moveq	#0,d1
	move.b	start_rez(a6),d1                ; the resolution at the start
	cmp.b	d0,d1                           ; the same?
	bne.s	restore_screen_mode_set         ; no: set it
	moveq	#-1,d1                          ; yes: leave it
restore_screen_mode_set:
	move.w	d1,-(sp)                        ; the resolution
	move.l	physical_screen(a6),-(sp)       ; the physical screen
	move.l	screen_mfdb(a6),-(sp)           ; the logical screen
	move.w	#$5,-(sp)
	trap	#14                             ; Setscreen, Setscreen: screen back
	lea	$c(sp),sp
	rts

;------------------------------------------------------------------------------
; Give back the program assembled to memory and the block buffer, if there are any.
;------------------------------------------------------------------------------
free_program_memory:	; from: cmd_assemble, menu_preferences
	move.l	program_block(a6),d0            ; a program in memory?
	beq.s	free_program_memory_block       ; no
	movea.l	d0,a0
	bsr.w	dos_mfree                       ; free it
	clr.l	program_block(a6)               ; none now
free_program_memory_block:
	move.l	block_copy(a6),d0               ; a block buffer?
	beq.s	free_program_memory_done        ; no
	movea.l	d0,a0
	bsr.w	dos_mfree                       ; free it
	clr.l	block_copy(a6)                  ; none now
free_program_memory_done:
	rts

;------------------------------------------------------------------------------
; Run a program already in memory: a4 = its text, a1 = its command line.  A basepage is made (Pexec 5) and
; started (Pexec 4); both blocks are freed after.  Out: d0 = its exit code, or -39 when under 4000 bytes
; are free; flags from d0.
;------------------------------------------------------------------------------
exec_in_memory:	; from: cmd_monst, cmd_assemble
	move.l	a1,-(sp)
	moveq	#-1,d0                          ; the largest free block
	bsr.w	dos_malloc
	moveq	#-39,d1                         ; -39: not enough memory
	exg	d0,d1                           ; d1 = its size
	movea.l	(sp)+,a1
	cmp.l	#$fa0,d1                        ; 4000 bytes?
	bcs.s	exec_in_memory_done             ; no
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	move.l	$2c(a0),-(sp)                   ; its environment
	move.l	a1,-(sp)                        ; the command line
	clr.l	-(sp)                           ; no file
	move.w	#$5,-(sp)                       ; mode 5: create a basepage
	move.w	#$4b,-(sp)
	trap	#1                              ; Pexec, Pexec: create a basepage
	lea	$10(sp),sp
	tst.l	d0                              ; made?
	bmi.s	exec_in_memory_done             ; no
	movea.l	d0,a0                           ; the basepage
	move.l	a4,8(a0)                        ; its text: the program in memory
	lea	$100(a0),a1
	move.l	a1,$18(a0)                      ; its BSS just past the basepage
	clr.l	-(sp)
	move.l	a0,-(sp)                        ; the basepage
	clr.l	-(sp)
	move.w	#$4,-(sp)                       ; mode 4: just go
	move.w	#$4b,-(sp)
	movea.l	a0,a4
	trap	#1                              ; GEMDOS, Pexec: run it
	lea	$10(sp),sp
	move.l	d0,d4                           ; the exit code
	move.l	$2c(a4),-(sp)                   ; its environment
	movea.l	a4,a0                           ; the basepage
	bsr.s	dos_mfree                       ; freed
	movea.l	(sp)+,a0                        ; the environment
	bsr.s	dos_mfree                       ; freed
	move.l	d4,d0
	ext.l	d0                              ; as a word
exec_in_memory_done:
	tst.l	d0
	rts

;------------------------------------------------------------------------------
; Malloc d0 bytes but only when 4000 bytes are still free after.  Out: a0/d0 = the block, 0 (Z) when not.
;------------------------------------------------------------------------------
malloc_leave_free:	; from: load_program_image, cmd_assemble, menu_preferences, alloc_edit_buffer, remember_block
	bsr.s	dos_malloc                      ; get it
	beq.s	malloc_leave_free_done          ; failed
	move.l	d0,-(sp)
	moveq	#-1,d0
	bsr.s	dos_malloc                      ; what is left
	cmp.l	#$fa0,d0                        ; 4000 bytes?
	bcs.s	malloc_leave_free_fail          ; no
	move.l	(sp)+,d0
	movea.l	d0,a0                           ; the block
	rts
malloc_leave_free_fail:
	movea.l	(sp)+,a0
	bsr.s	dos_mfree                       ; give it back
	moveq	#0,d0                           ; none
malloc_leave_free_done:
	rts

;------------------------------------------------------------------------------
; Malloc d0 bytes (-1: the largest free block's size).  Out: a0/d0 = the block, flags from d0.
;------------------------------------------------------------------------------
dos_malloc:	; from: exec_in_memory, malloc_leave_free, help_dialog
	move.l	d0,-(sp)                        ; the size
	move.w	#$48,-(sp)
	trap	#1                              ; Malloc
	addq.l	#6,sp
	movea.l	d0,a0
	tst.l	d0
	rts

;------------------------------------------------------------------------------
; Mfree the block at a0.
;------------------------------------------------------------------------------
dos_mfree:                                      ; from: run_program_image, free_program_memory, exec_in_memory,
                                                ;   malloc_leave_free, menu_preferences, remember_block
	move.l	a0,-(sp)                        ; the block
	move.w	#$49,-(sp)
	trap	#1                              ; Mfree
	addq.l	#6,sp
	rts

;------------------------------------------------------------------------------
; Fcreate the file a0.  Out: d3 = the handle, d0 = 0 when made, else the error (negative).
;------------------------------------------------------------------------------
dos_fcreate:	; from: save_preferences
	clr.w	-(sp)                           ; normal file
	move.l	a0,-(sp)                        ; the name
	move.w	#$3c,-(sp)
	trap	#1                              ; Fcreate
	bra.s	dos_open_result

;------------------------------------------------------------------------------
; Fopen the file a0 for reading.  Out: d3 = the handle, d0 = 0 when opened, else the error (negative).
;------------------------------------------------------------------------------
dos_fopen_read:	; from: monst_settings, load_preferences
	clr.w	-(sp)                           ; read only
	move.l	a0,-(sp)                        ; the name
	move.w	#$3d,-(sp)
	trap	#1                              ; Fopen
dos_open_result:	; from: dos_fcreate
	addq.l	#8,sp
	move.w	d0,d3                           ; the handle
	bmi.s	dos_open_done                   ; an error
	moveq	#0,d0                           ; done
dos_open_done:
	rts
	move.w	#$2,-(sp)                       ; not used: d4 = the length of the file d3, and back to its start
	move.w	d3,-(sp)
	clr.l	-(sp)
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek, Fseek: to the end
	lea	$a(sp),sp
	move.l	d0,d4                           ; the length
	clr.w	-(sp)
	move.w	d3,-(sp)
	clr.l	-(sp)
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek, Fseek: to the start
	lea	$a(sp),sp
	rts
	move.w	#$0,-(sp)                       ; not used: seek the file d3 to d4 from its start
dos_fseek:
	move.w	d3,-(sp)                        ; the handle
	move.l	d4,-(sp)                        ; the offset
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek
	lea	$a(sp),sp
	cmp.l	d4,d0                           ; got there?
	rts
	move.w	#$1,-(sp)                       ; not used: from the position now, d0 = where the file d3 is
	moveq	#0,d4
	bra.s	dos_fseek

;------------------------------------------------------------------------------
; Fread d4 bytes from the file d3 to a0.  Out: NE when fewer came.  Keeps a0.
;------------------------------------------------------------------------------
dos_fread:	; from: monst_settings, load_preferences
	move.l	a0,-(sp)
	move.l	a0,-(sp)                        ; the buffer
	move.l	d4,-(sp)                        ; the length
	move.w	d3,-(sp)                        ; the handle
	move.w	#$3f,-(sp)
	trap	#1                              ; Fread
	lea	$c(sp),sp
	movea.l	(sp)+,a0
	cmp.l	d4,d0                           ; all of it?
	rts

;------------------------------------------------------------------------------
; Fwrite d4 bytes from a0 to the file d3.  Out: d0 = 0 (Z) when all written, else the file is closed and
; d0 = -50.
;------------------------------------------------------------------------------
dos_fwrite:	; from: radio_index
	move.l	a0,-(sp)                        ; the buffer
	move.l	d4,-(sp)                        ; the length
	move.w	d3,-(sp)                        ; the handle
	move.w	#$40,-(sp)
	trap	#1                              ; Fwrite
	lea	$c(sp),sp
	cmp.l	d0,d4                           ; all of it?
	beq.s	dos_fwrite_done                 ; yes
	bsr.s	dos_fclose                      ; no: close it
	moveq	#-50,d0                         ; -50
dos_fwrite_done:
	rts

;------------------------------------------------------------------------------
; Fclose the file d3.
;------------------------------------------------------------------------------
dos_fclose:	; from: monst_settings, dos_fwrite, radio_index, radio_select_index
	move.w	d3,-(sp)                        ; the handle
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose
	addq.w	#4,sp
	rts

;------------------------------------------------------------------------------
; Open a virtual VDI workstation on the AES's physical one, raster coordinates.
; Out: d0 = the new handle (0, Z, when none); d4 = the AES character width.
;------------------------------------------------------------------------------
open_workstation:	; from: gem_screen_setup
	moveq	#77,d0                          ; graf_handle
	bsr.w	aes_call
	move.w	intout1(a6),d4                  ; the character width
	moveq	#1,d0                           ; work_in: 1 for each of the ten settings
	lea	intin(a6),a0
	moveq	#9,d1
open_workstation_fill:
	move.w	d0,(a0)+
	dbra	d1,open_workstation_fill
	move.w	#$2,(a0)                        ; raster coordinates
	clr.w	contrl_count(a6)                ; no points
	move.w	#$b,contrl_intin_count(a6)      ; 11 integers
	move.w	intout(a6),contrl_handle(a6)    ; on the AES's workstation
	moveq	#100,d0                         ; v_opnvwk
	bsr.w	vdi_call_handle_set
	move.w	contrl_handle(a6),d0            ; the new handle
	rts

;------------------------------------------------------------------------------
; Open the workstation (an illegal instruction stops GenST if it cannot) and read the screen: its MFDB size
; from the Line-A variables, the desk area, the start resolution, and narrow_screen when the desk is under 80
; characters wide (the Find and command line dialogs are then made 40 characters narrower).
;------------------------------------------------------------------------------
gem_screen_setup:	; from: gem_init
	bsr.s	open_workstation                ; open the workstation
	bne.s	gem_screen_setup_ok             ; opened
	illegal                                 ; no workstation: stop
gem_screen_setup_ok:
	move.w	d0,vdi_handle(a6)               ; the VDI handle
	dc.w	$a000                           ; Line-A $0, Line-A variables
	move.w	2(a0),d0                        ; bytes per screen line
	move.w	(a0),d1                         ; planes
	divu.w	d1,d0                           ; bytes per plane line
	lsr.w	#1,d0                           ; words per line
	move.w	d0,screen_width_words(a6)       ; for the screen MFDB
	lsl.w	#4,d0                           ; pixels per line
	move.w	d0,screen_width(a6)
	move.w	intout1(a6),d0                  ; the bottom pixel row
	addq.w	#1,d0                           ; the screen height
	move.w	d0,screen_height(a6)
	clr.w	intin(a6)                       ; window 0: the desk
	move.w	#$4,intin1(a6)                  ; WF_WORKXYWH
	moveq	#104,d0                         ; wind_get
	bsr.w	aes_call
	movem.w	intout1(a6),d0-d3               ; the desk area
	movem.w	d0-d3,desk_area(a6)
	add.w	d1,d3                           ; its bottom
	move.w	d3,desk_bottom(a6)
	ext.l	d2
	divu.w	d4,d2                           ; width in characters
	sf	narrow_screen(a6)               ; wide screen
	cmp.w	#$50,d2                         ; 80 characters?
	bge.s	gem_screen_setup_rez            ; yes
	bsr.s	narrow_dialogs                  ; no: narrower dialogs
	st	narrow_screen(a6)               ; a narrow screen
gem_screen_setup_rez:
	move.w	#$4,-(sp)
	trap	#14                             ; Getrez, Getrez: the resolution now
	addq.l	#2,sp
	move.b	d0,start_rez(a6)                ; kept, to set back after programs
	rts
narrow_dialog_list:	; from: narrow_dialogs
	dc.l	run_other_tree                  ; the dialogs made narrower: command line
	dc.l	find_tree                       ; Find/Replace

;------------------------------------------------------------------------------
; Shorten the editable text object a0 by d1 characters (when it is longer): te_txtlen and te_tmplen, and
; the template ends there.
;------------------------------------------------------------------------------
narrow_text_field:	; from: narrow_dialogs
	movea.l	$c(a0),a1                       ; its tedinfo
	move.w	$18(a1),d0                      ; te_txtlen
	sub.w	d1,d0                           ; less the cut
	ble.s	narrow_text_field_done          ; too short: as it is
	move.w	d0,$18(a1)                      ; te_txtlen
	move.w	d0,$1a(a1)                      ; te_tmplen
	movea.l	4(a1),a1                        ; the template
	clr.b	-$1(a1,d0.w)                    ; ends there
narrow_text_field_done:
	rts

;------------------------------------------------------------------------------
; Make the command line and Find dialogs 40 characters narrower for a low resolution screen: the box, the
; text fields shorter, buttons 40 to the left and boxed text 20 to the left.
;------------------------------------------------------------------------------
narrow_dialogs:	; from: gem_screen_setup
	moveq	#1,d5                           ; two trees
	lea	narrow_dialog_list(pc),a3       ; the list
narrow_dialogs_tree:
	movea.l	(a3)+,a0                        ; the tree
	moveq	#40,d1                          ; 40 characters
	sub.w	d1,$14(a0)                      ; off the box's width
narrow_dialogs_object:
	move.w	6(a0),d0                        ; the object's type
	cmp.w	#$1d,d0                         ; G_FTEXT?
	bne.s	narrow_dialogs_button           ; no
	bsr.s	narrow_text_field               ; yes: shorter
	bra.s	narrow_dialogs_next
narrow_dialogs_button:
	cmp.w	#$1a,d0                         ; G_BUTTON?
	bne.s	narrow_dialogs_boxtext          ; no
	move.w	$10(a0),d0                      ; its x
	sub.w	d1,d0                           ; 40 to the left
	ble.s	narrow_dialogs_next             ; not past the edge
	move.w	d0,$10(a0)
	bra.s	narrow_dialogs_next
narrow_dialogs_boxtext:
	cmp.w	#$16,d0                         ; G_BOXTEXT?
	bne.s	narrow_dialogs_next             ; no
	move.w	d1,d0
	lsr.w	#1,d0                           ; half of it
	sub.w	d0,$10(a0)                      ; to the left
	nop
narrow_dialogs_next:
	btst	#$5,9(a0)                       ; the last object?
	lea	$18(a0),a0                      ; the next
	beq.s	narrow_dialogs_object           ; no: on
	dbra	d5,narrow_dialogs_tree          ; the next tree
	rts

;------------------------------------------------------------------------------
; rsrc_obfix every object of the nine trees in the list at $4436: character to pixel positions.
;------------------------------------------------------------------------------
fix_resource_trees:	; from: gem_init
	moveq	#8,d5                           ; nine trees
	lea	object_tree_list(pc),a3         ; the list
fix_resource_trees_tree:
	movea.l	(a3)+,a0                        ; the tree
	clr.w	intin(a6)                       ; from object 0
	move.l	a0,ptsin(a6)
fix_resource_trees_object:
	move.l	a0,-(sp)
	moveq	#114,d0                         ; rsrc_obfix
	bsr.w	aes_call
	addq.w	#1,intin(a6)                    ; the next object
	movea.l	(sp)+,a0
	btst	#$5,9(a0)                       ; the last?
	lea	$18(a0),a0
	beq.s	fix_resource_trees_object       ; no: on
	dbra	d5,fix_resource_trees_tree      ; the next tree
	rts

;------------------------------------------------------------------------------
; GEM and editor set-up at the start: the AES and VDI parameter blocks, appl_init, the workstation, the
; character cell, the resource trees fixed, empty Find, Replace and command line fields, the casing button
; names, the editor window opened, the mouse, the screen MFDB.  The file selector path and name come from
; the command line when there is one, else the current folder with *.S.  Default settings, the caps table.
;------------------------------------------------------------------------------
gem_init:	; from: aes_call
	bsr.w	vdi_init_params                 ; the VDI parameter block
	bsr.w	aes_init_params                 ; the AES parameter block
	moveq	#10,d0                          ; appl_init
	bsr.w	aes_call
	move.w	d0,ap_id(a6)                    ; the application id
	bsr.w	gem_screen_setup                ; the workstation and screen
	bsr.w	get_char_cell                   ; the character cell
	bsr.s	fix_resource_trees              ; resource trees to pixels
	movea.l	find_text_spec(a6),a0           ; the Find text
	movea.l	(a0),a0
	clr.b	(a0)                            ; empty
	movea.l	replace_text_spec(a6),a0        ; the Replace text
	movea.l	(a0),a0
	clr.b	(a0)                            ; empty
	movea.l	run_command_spec(a6),a0         ; the command line text
	movea.l	(a0),a0
	clr.b	(a0)                            ; empty
	lea	find_case_object(a6),a0         ; the first casing button
	move.l	#ignore_case_text,$c(a0)        ; "test=TEST"
	lea	find_case_button(a6),a0         ; the second casing button
	move.l	#match_case_text,$c(a0)         ; "test<>TEST"
	move.w	#$1,intin(a6)                   ; BEG_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	bsr.w	set_version_title               ; the version in the window title
	bsr.w	open_editor_window              ; the editor window
	bsr.w	clear_text_area
	bsr.w	show_menu_bar
	bsr.w	get_screen_info                 ; the screen MFDB
	clr.w	intin(a6)                       ; ARROW
	clr.l	ptsin(a6)                       ; no own form
	moveq	#78,d0                          ; graf_mouse
	bsr.w	aes_call
	clr.w	selector_name(a6)               ; no file name
	clr.b	file_name(a6)                   ; no title
	move.w	#$1,line_count(a6)              ; one line
	tst.b	command_line_given(a6)          ; a command line?
	beq.w	gem_init_no_file                ; no
	movea.l	own_basepage(a6),a0             ; GenST's basepage
	moveq	#0,d0
	lea	$80(a0),a0                      ; its command line
	move.b	(a0)+,d0                        ; its length
	clr.b	0(a0,d0.w)                      ; ends there
	bsr.w	parse_command_line_name         ; the path and name from it
	bra.s	gem_init_named
gem_init_no_file:
	bsr.w	default_fsel_path               ; the current folder
gem_init_named:
	move.w	#$0,output_mode(a6)             ; output to the window
	tst.b	command_line_given(a6)          ; a command line?
	bne.s	gem_init_defaults               ; yes
	bsr.w	set_file_name                   ; no: the title shows no name
gem_init_defaults:
	move.b	default_numeric_pad(pc),numpad_cursor(a6) ; numeric pad default
	clr.b	auto_indent(a6)                 ; no auto indent
	move.w	default_tab_size(pc),tab_size(a6) ; tab default
	moveq	#-1,d0                          ; keep each table
	move.l	d0,-(sp)
	move.l	d0,-(sp)
	move.l	d0,-(sp)
	move.w	#$10,-(sp)
	trap	#14                             ; Keytbl, Keytbl: the keyboard tables
	lea	$e(sp),sp
	movea.l	d0,a0
	move.l	8(a0),caps_table(a6)            ; the caps lock table
	clr.w	held_key(a6)                    ; no key held back
	rts

;------------------------------------------------------------------------------
; Take the file name on the command line (a0): the folder part, upper case, goes to fsel_path with *.S after
; it, the name to fsel_name.  With no folder, the current folder is used.
;------------------------------------------------------------------------------
parse_command_line_name:	; from: gem_init
	lea	fsel_path(a6),a1                ; the file selector path
	moveq	#0,d2                           ; no folder seen
parse_name_skip:
	cmpi.b	#$20,(a0)                       ; a space?
	bne.s	parse_name_loop                 ; no
	addq.l	#1,a0                           ; skip it
	bra.s	parse_name_skip
parse_name_loop:
	move.b	(a0)+,d1                        ; a character
	beq.s	parse_name_end                  ; the end
	cmp.b	#$20,d1                         ; a space?
	beq.s	parse_name_end                  ; yes: the end
	cmp.b	#$5c,d1                         ; a backslash?
	beq.s	parse_name_separator            ; yes
	cmp.b	#$3a,d1                         ; a colon?
	beq.s	parse_name_separator            ; yes
	bsr.w	find_upper_case                 ; upper case
	move.b	d1,(a1)+                        ; stored
	bra.s	parse_name_loop
parse_name_separator:
	move.b	d1,(a1)+                        ; stored
	move.l	a1,d2                           ; the name starts after it
	bra.s	parse_name_loop
parse_name_end:
	clr.b	(a1)                            ; ends there
	tst.l	d2                              ; a folder?
	bne.s	parse_name_has_path             ; yes
	lea	fsel_path(a6),a0                ; no: all of it is the name
	bsr.s	copy_fsel_name                  ; to the name
	bra.s	default_fsel_path               ; the path from the current folder
parse_name_has_path:
	movea.l	d2,a0                           ; the name part
	bsr.s	copy_fsel_name                  ; to the name
	movea.l	d2,a0                           ; the path ends there
	bra.s	fsel_path_add_mask              ; add *.S

;------------------------------------------------------------------------------
; Make the file selector path the current drive and folder with *.S on the end.
;------------------------------------------------------------------------------
default_fsel_path:	; from: gem_init, parse_command_line_name
	move.w	#$19,-(sp)
	trap	#1                              ; Dgetdrv, Dgetdrv: the current drive
	addq.l	#2,sp
	addi.b	#$41,d0                         ; its letter
	lsl.w	#8,d0
	move.b	#$3a,d0                         ; and ':'
	move.w	d0,fsel_path(a6)
	clr.w	-(sp)                           ; the current drive
	pea	fsel_path_folder(a6)            ; after the "X:"
	move.w	#$47,-(sp)
	trap	#1                              ; Dgetpath, Dgetpath: the current folder
	addq.l	#8,sp
	lea	fsel_path(a6),a0
default_fsel_path_end:
	tst.b	(a0)+                           ; to its end
	bne.s	default_fsel_path_end
	subq.l	#1,a0
	cmpi.b	#$5c,-$1(a0)                    ; a backslash at the end?
	beq.s	fsel_path_add_mask              ; yes
	move.b	#$5c,(a0)+                      ; no: add it
fsel_path_add_mask:	; from: parse_command_line_name
	move.b	#$2a,(a0)+                      ; "*"
	move.b	#$2e,(a0)+                      ; "."
	lea	default_extension(pc),a1        ; the default extension, "S"
fsel_path_add_mask_loop:
	move.b	(a1)+,(a0)+
	bne.s	fsel_path_add_mask_loop
	rts

;------------------------------------------------------------------------------
; Copy the name at a0 (to a space or 0) to fsel_name in 8.3 form: a '.' goes in after 8 characters when there
; is none, and it is cut at 12 characters.
;------------------------------------------------------------------------------
copy_fsel_name:	; from: parse_command_line_name
	lea	selector_name(a6),a1            ; the file selector name
	moveq	#0,d0                           ; the count
	moveq	#0,d3                           ; no '.' seen
copy_fsel_name_loop:
	move.b	(a0)+,d1                        ; a character
	beq.s	copy_fsel_name_end              ; the end
	cmp.b	#$20,d1                         ; a space?
	beq.s	copy_fsel_name_end              ; yes: the end
	cmp.b	#$2e,d1                         ; a '.'?
	bne.s	copy_fsel_name_count            ; no
	st	d3                              ; yes
copy_fsel_name_count:
	addq.b	#1,d0
	cmp.b	#$9,d0                          ; the ninth?
	beq.s	copy_fsel_name_dot              ; yes
	cmp.b	#$d,d0                          ; the 13th?
	beq.s	copy_fsel_name_end              ; yes: cut there
copy_fsel_name_store:
	move.b	d1,(a1)+
	bra.s	copy_fsel_name_loop
copy_fsel_name_dot:
	tst.b	d3                              ; a '.' already?
	bne.s	copy_fsel_name_store            ; yes
	move.b	#$2e,(a1)+                      ; no: one now
	bra.s	copy_fsel_name_loop
copy_fsel_name_end:
	clr.b	(a1)                            ; ends there
	rts

;------------------------------------------------------------------------------
; Read the text size with vqt_attributes: cell_width and cell_height.
;------------------------------------------------------------------------------
get_char_cell:	; from: gem_init
	clr.w	contrl_count(a6)                ; no points
	clr.w	contrl_intin_count(a6)          ; no integers
	moveq	#38,d0                          ; vqt_attributes
	bsr.w	vdi_call
	move.w	ptsout2(a6),char_width(a6)      ; the cell width
	move.w	ptsout3(a6),char_height(a6)     ; the cell height
	rts

;------------------------------------------------------------------------------
; No window could be made: tell them, close the workstation and stop GenST.
;------------------------------------------------------------------------------
no_window_quit:	; from: open_editor_window
	clr.w	intin(a6)                       ; END_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	lea	alert_no_window(a6),a1          ; "There are no more windows available"
	moveq	#1,d1
	bsr.w	gem_alert
	clr.l	contrl_count(a6)                ; no points or integers
	moveq	#101,d0                         ; v_clsvwk
	bsr.w	vdi_call
	bra.w	editor_terminate                ; Pterm0

;------------------------------------------------------------------------------
; Create and open the editor window over the whole desk: every window part, the title and an empty info line;
; then on into window_geometry.
;------------------------------------------------------------------------------
open_editor_window:	; from: gem_init
	movem.w	desk_area(a6),d0-d3             ; the desk area
	movem.w	d0-d3,intin1(a6)
	move.w	#$fff,intin(a6)                 ; every window part
	moveq	#100,d0                         ; wind_create
	bsr.w	aes_call
	move.w	d0,window_handle(a6)            ; the window
	bmi.s	no_window_quit                  ; none: stop
	move.w	d0,intin(a6)
	move.w	#$2,intin1(a6)                  ; WF_NAME
	lea	window_title_text(pc),a0        ; the title
	move.l	a0,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
	addq.w	#1,intin1(a6)                   ; WF_INFO
	lea	info_line_text(pc),a0           ; empty
	move.l	a0,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
	movem.w	desk_area(a6),d0-d3             ; the desk area
	movem.w	d0-d3,window_previous(a6)       ; the window's area
	movem.w	d0-d3,intin1(a6)
	moveq	#101,d0                         ; wind_open
	bsr.w	aes_call

;------------------------------------------------------------------------------
; Work out the editor's layout from the window's work area: the text origin (x rounded up to 8), the status
; line's y in the info line, the first row's y, the columns and rows, the area for scrolling, and the
; horizontal slider's size for 256 column lines.
;------------------------------------------------------------------------------
window_geometry:	; from: window_sized
	move.w	window_handle(a6),intin(a6)     ; the window
	move.w	#$4,intin1(a6)                  ; WF_WORKXYWH
	moveq	#104,d0                         ; wind_get
	bsr.w	aes_call
	movem.w	intout1(a6),d0-d3               ; the work area
	add.w	d0,d2
	add.w	d1,d3
	subq.w	#1,d2                           ; as x1,y1,x2,y2
	subq.w	#1,d3
	movem.w	d0-d3,work_area(a6)
	movem.w	intout1(a6),d0-d3
	move.w	d1,-(sp)                        ; the top
	addq.w	#8,d0                           ; x rounded up to 8
	andi.w	#$fff8,d0
	move.w	d0,text_x(a6)                   ; the text's left edge
	subq.w	#4,d1                           ; the info line
	move.w	d1,status_y(a6)                 ; the status line's y
	clr.w	contrl_count(a6)                ; no points
	clr.w	contrl_intin_count(a6)          ; no integers
	moveq	#38,d0                          ; vqt_attributes
	bsr.w	vdi_call
	move.w	(sp)+,d1                        ; the top
	add.w	ptsout1(a6),d1                  ; and the character height
	addq.w	#1,d1
	move.w	d1,text_y(a6)                   ; the first row's y
	move.w	ptsout3(a6),d0                  ; the cell height
	sub.w	ptsout1(a6),d0                  ; less the character height
	move.w	d0,char_descent(a6)             ; the gap under it
	moveq	#0,d0
	move.w	work_right(a6),d0               ; the right edge
	sub.w	text_x(a6),d0                   ; less the left
	divu.w	char_width(a6),d0               ; in columns
	subq.w	#1,d0
	move.w	d0,window_columns(a6)           ; columns less 1
	moveq	#0,d0
	move.w	work_y2(a6),d0                  ; the bottom
	sub.w	work_y1(a6),d0                  ; less the top
	divu.w	char_height(a6),d0              ; in rows
	subq.w	#1,d0
	move.w	d0,last_row(a6)                 ; rows less 1
	lea	scroll_rect(a6),a0              ; the scroll area
	move.w	text_x(a6),d0                   ; the left
	move.w	d0,(a0)+
	move.w	work_y1(a6),d2                  ; the top
	addq.w	#1,d2
	move.w	d2,(a0)+
	move.w	window_columns(a6),d1           ; the columns
	addq.w	#1,d1
	mulu.w	char_width(a6),d1
	add.w	d0,d1                           ; the right
	move.w	d1,(a0)+
	move.w	last_row(a6),d0                 ; the rows
	addq.w	#1,d0
	mulu.w	char_height(a6),d0
	add.w	work_y1(a6),d0                  ; the bottom
	move.w	d0,(a0)
	move.w	window_columns(a6),d0           ; the columns
	mulu.w	#$3e7,d0                        ; in 1000ths of 256
	lsr.l	#8,d0
	addq.w	#1,d0
	lea	intin(a6),a0
	move.w	window_handle(a6),(a0)+         ; the window
	move.w	#$f,(a0)+                       ; WF_HSLSIZE
	move.w	d0,(a0)                         ; the size
	moveq	#105,d0                         ; wind_set
	bra.w	aes_call

;------------------------------------------------------------------------------
; Keep a new window size d2 x d3 (pixels) at least 37 columns and 10 rows.
;------------------------------------------------------------------------------
limit_window_size:	; from: window_sized
	move.l	d4,-(sp)
	move.w	char_width(a6),d4               ; the cell width
	mulu.w	#$25,d4                         ; 37 columns
	cmp.w	d4,d2                           ; wide enough?
	bcc.s	limit_window_height             ; yes
	move.w	d4,d2                           ; no: 37
limit_window_height:
	move.w	char_height(a6),d4              ; the cell height
	mulu.w	#$a,d4                          ; 10 rows
	cmp.w	d4,d3                           ; high enough?
	bcc.s	limit_window_size_done          ; yes
	move.w	d4,d3                           ; no: 10
limit_window_size_done:
	move.l	(sp)+,d4
	rts

;------------------------------------------------------------------------------
; Have the AES send a redraw for the whole editor window: form_dial FMD_START then FMD_FINISH over it.
;------------------------------------------------------------------------------
redraw_whole_window:	; from: window_sized
	movem.l	d0-d3/a0-a2,-(sp)
	move.w	window_handle(a6),intin(a6)     ; the window
	move.w	#$5,intin1(a6)                  ; WF_CURRXYWH
	moveq	#104,d0                         ; wind_get
	bsr.w	aes_call
	movem.w	intout1(a6),d0-d3               ; its area
	lea	intin(a6),a0
	clr.w	(a0)+                           ; FMD_START
	movem.w	d0-d3,(a0)                      ; the small box
	addq.l	#8,a0
	movem.w	d0-d3,(a0)                      ; the big box
	moveq	#51,d0                          ; form_dial
	bsr.w	aes_call
	addq.w	#3,intin(a6)                    ; FMD_FINISH
	moveq	#51,d0                          ; form_dial: redraw it
	bsr.w	aes_call
	movem.l	(sp)+,d0-d3/a0-a2
	rts

;------------------------------------------------------------------------------
; Desk menu "About GenST2...": the About dialog.
;------------------------------------------------------------------------------
about_dialog:	; from: editor_command_event
	lea	about_tree-data_base(a6),a0     ; the About tree
	moveq	#100,d4                         ; always put away

;------------------------------------------------------------------------------
; Show the dialog a0 centred and let them fill it in (form_do).  d4 = the lowest exit object that leaves the
; dialog on screen (100: none).  The Assembly Options dialog starts at its file name field.  The exit
; button is made normal again.  Out: d4 = the exit object, a0 = the tree, dialog_rect = where it was.
;------------------------------------------------------------------------------
gem_dialog:	; from: find_dialog, run_other_dialog, cmd_assemble, help_dialog, menu_preferences, goto_line_dialog
	move.l	a0,ptsin(a6)                    ; the tree
	moveq	#54,d0                          ; form_center
	bsr.w	aes_call
	clr.w	intin(a6)                       ; FMD_START
	movem.l	intout1(a6),d0-d1               ; where it goes
	movem.l	d0-d1,intin1(a6)
	movem.l	d0-d1,intin5(a6)
	movem.l	d0-d1,dialog_rect(a6)           ; kept
	moveq	#51,d0                          ; form_dial
	bsr.w	aes_call
	move.l	intin3(a6),intin4(a6)           ; as the clip area
	move.l	intin1(a6),intin2(a6)
	clr.w	intin(a6)                       ; from the root
	move.w	#$4,intin1(a6)                  ; all levels
	moveq	#42,d0                          ; objc_draw
	bsr.w	aes_call
	clr.w	intin(a6)                       ; no edit field
	lea	options_tree(pc),a0             ; the Assembly Options tree?
	cmpa.l	ptsin(a6),a0
	bne.s	gem_dialog_form                 ; no
	move.w	#$15,intin(a6)                  ; yes: the file name field
gem_dialog_form:
	moveq	#50,d0                          ; form_do
	bsr.w	aes_call
	move.w	intout(a6),d0                   ; the exit object
	bclr	#$f,d0                          ; not the double click bit
	move.w	d0,-(sp)
	move.w	d0,intin(a6)                    ; the object
	clr.w	intin1(a6)
	move.l	dialog_rect(a6),intin2(a6)      ; the dialog's area
	move.l	dialog_rect_size(a6),intin4(a6)
	move.l	#$1,intin6(a6)                  ; normal, redrawn
	moveq	#47,d0                          ; objc_change
	bsr.w	aes_call
	move.w	(sp)+,d3                        ; the exit object
	exg	d3,d4                           ; d3 = the lowest kept
	cmp.w	d3,d4                           ; one that stays?
	bcc.s	gem_dialog_done                 ; yes
	move.w	#$3,intin(a6)                   ; FMD_FINISH
	movem.l	dialog_rect(a6),d0-d1           ; the dialog's area
	movem.l	d0-d1,intin1(a6)
	movem.l	d0-d1,intin5(a6)
	moveq	#51,d0                          ; form_dial: off the screen
	bsr.w	aes_call
gem_dialog_done:
	movea.l	ptsin(a6),a0                    ; the tree
	rts

;------------------------------------------------------------------------------
; form_alert: a1 = the alert string, d1 = the default button.  Out: d1 = the button chosen.
;------------------------------------------------------------------------------
gem_alert:	; from: monst_settings, editor_init, cmd_run, no_window_quit, confirm_lose_changes, get_event, 4 more
	move.w	d1,intin(a6)                    ; the default button
	move.l	a1,ptsin(a6)                    ; the string
	moveq	#52,d0                          ; form_alert
	bsr.w	aes_call
	move.w	intout(a6),d1                   ; the button
	rts

;------------------------------------------------------------------------------
; The Help key: the editor's key summary dialog with its title and the free memory (the largest block).
;------------------------------------------------------------------------------
help_dialog:	; from: cmd_help
	move.l	a5,-(sp)
	lea	help_title_text(pc),a5          ; the title
	move.l	a5,help_title_spec              ; into the title button
	movea.l	help_free_spec(a6),a5           ; the free memory string
	move.w	output_mode(a6),-(sp)
	moveq	#-1,d0                          ; to memory at a5
	move.w	d0,output_mode(a6)
	bsr.w	dos_malloc                      ; the largest free block
	move.l	d0,d1
	moveq	#1,d2
	bsr.w	print_decimal_long              ; as a number
	clr.b	(a5)                            ; ends there
	move.w	(sp)+,output_mode(a6)           ; the output as before
	movea.l	(sp)+,a5
	lea	help_tree-data_base(a6),a0      ; the help tree
	moveq	#100,d4                         ; always put away
	bra.w	gem_dialog                      ; show it
help_title_text:
	dc.b	'HiSoft Screen Editor Version 1.10',0 ; the help dialog's title

;------------------------------------------------------------------------------
; Cut the rectangle d0-d3 (x,y,w,h) to the one at a0.  Out: Z with the overlap in d0-d3, or NE and d0-d3 = 0
; when they do not overlap.
;------------------------------------------------------------------------------
intersect_rect:	; from: appl_find_name
	movem.l	d4-d7,-(sp)
	movem.w	(a0),d4-d7                      ; the other one
	bsr.s	intersect_axis                  ; the y range
	bcs.s	intersect_rect_none             ; none
	bsr.s	intersect_axis                  ; the x range
	bcs.s	intersect_rect_none             ; none
	movem.l	(sp)+,d4-d7
	rts                                     ; Z: they overlap
intersect_rect_none:
	moveq	#0,d0                           ; no rectangle
	move.l	d0,d1
	move.l	d0,d2
	move.l	d0,d3
	andi.b	#$1b,ccr                        ; NE
	movem.l	(sp)+,d4-d7
	rts

;------------------------------------------------------------------------------
; One axis of intersect_rect: swaps the x and y halves over, then cuts d0/d2 (start/length) to d4/d6.
; Out: C when they do not meet, else Z and d0/d2 the part in both.
;------------------------------------------------------------------------------
intersect_axis:	; from: intersect_rect
	exg	d0,d1                           ; the other axis in place
	exg	d2,d3
	exg	d4,d5
	exg	d6,d7
	add.w	d0,d2                           ; the end
	add.w	d4,d6                           ; the other's end
	cmp.w	d4,d2                           ; ends before the other starts?
	bcs.s	intersect_axis_done             ; yes: none
	cmp.w	d0,d6                           ; the other ends before this starts?
	bcs.s	intersect_axis_done             ; yes: none
	cmp.w	d0,d4                           ; the later start
	bcs.s	intersect_axis_end
	move.w	d4,d0
intersect_axis_end:
	cmp.w	d2,d6                           ; the earlier end
	bcc.s	intersect_axis_length
	move.w	d6,d2
intersect_axis_length:
	sub.w	d0,d2                           ; the length
	cmp.b	d1,d1                           ; Z, no carry
intersect_axis_done:
	rts

;------------------------------------------------------------------------------
; When the text has changes, ask whether to lose them (Cancel is the default).  Out: Z to go on, NE to stop.
;------------------------------------------------------------------------------
confirm_lose_changes:	; from: cmd_quit, cmd_load, cmd_clear, menu_run_other_drop, menu_preferences
	tst.b	text_modified(a6)               ; changes?
	beq.s	confirm_lose_changes_done       ; no: Z
	lea	alert_lose_changes(pc),a1       ; the alert
	moveq	#2,d1                           ; Cancel the default
	bsr.w	gem_alert
	cmp.w	#$1,d1                          ; OK?
confirm_lose_changes_done:
	rts
alert_lose_changes:
	dc.b	'[3][You have made changes that|will be lost. Click OK if you|don',$27 ; the alert for losing changes
	dc.b	't mind losing them][OK|Cancel]',0
	dc.w	$48e7,$b0f0,$7014,$6100,$d6a2,$3f2e,$1db2,$6100 ; not used: an older key reader (evnt_keybd, the key as
                                                ;   event 3)
	dc.w	$07ac,$321f,$3d7c,$0003,$1e62,$4cdf,$0f0d,$4e75

;------------------------------------------------------------------------------
; The decimal number at a1 (digits to a 0) in d1.l.
;------------------------------------------------------------------------------
parse_decimal:	; from: menu_preferences
	moveq	#0,d1                           ; the value
parse_decimal_loop:
	move.b	(a1)+,d0                        ; a digit
	beq.s	parse_decimal_done              ; the end
	subi.b	#$30,d0                         ; its value
	move.l	d1,d2
	add.l	d1,d1                           ; times 2
	lsl.l	#3,d2                           ; times 8
	add.l	d2,d1                           ; times 10
	andi.l	#$f,d0
	add.l	d0,d1                           ; added
	bra.s	parse_decimal_loop
parse_decimal_done:
	rts

;------------------------------------------------------------------------------
; Select the first of the two radio buttons at a0 when Z, else the second.
;------------------------------------------------------------------------------
set_radio_if_zero:	; from: menu_preferences
	beq.s	radio_select_first              ; Z: the first
radio_select_second:	; from: set_radio_if_set
	bclr	#$0,$b(a0)                      ; the first off
	bset	#$0,$23(a0)                     ; the second on
	rts
radio_select_first:	; from: set_radio_if_set
	bset	#$0,$b(a0)                      ; the first on
	bclr	#$0,$23(a0)                     ; the second off
	rts

;------------------------------------------------------------------------------
; Select the first of the two radio buttons at a0 when NE, else the second.
;------------------------------------------------------------------------------
set_radio_if_set:	; from: menu_preferences
	bne.s	radio_select_first              ; NE: the first
	bra.s	radio_select_second

;------------------------------------------------------------------------------
; Options menu "Preferences..." (^T): the Editor Preferences dialog.  Tab setting 2-16, text buffer size,
; numeric pad as numbers or cursor keys, backups, auto indent, flashing cursor, end of line stop or wrap and
; Load MonST.  OK takes them; Save also writes GENST2.INF.  A new buffer size frees the text (they are asked
; first when it has changes) and gets a new buffer, 4000 bytes smaller each time it does not fit.
;------------------------------------------------------------------------------
menu_preferences:	; from: editor_key
	movea.l	prefs_tab_spec(a6),a1           ; the tab setting text
	movea.l	(a1),a1
	moveq	#0,d1
	move.w	tab_size(a6),d1                 ; the tab setting
	bsr.w	decimal_to_text                 ; as text
	movea.l	prefs_buffer_spec(a6),a1        ; the buffer size text
	movea.l	(a1),a1
	move.l	text_buffer_size(a6),d1         ; the buffer size
	bsr.w	decimal_to_text                 ; as text
	lea	prefs_numbers_button(a6),a0     ; Numbers / Cursor
	tst.b	numpad_cursor(a6)               ; numbers?
	bsr.s	set_radio_if_zero
	lea	prefs_backups_button(a6),a0     ; Backups Yes / No
	move.b	default_backups(pc),d0          ; on?
	bsr.s	set_radio_if_set
	lea	prefs_indent_button(a6),a0      ; Auto indent Yes / No
	tst.b	auto_indent(a6)                 ; on?
	bsr.s	set_radio_if_set
	lea	prefs_flash_button(a6),a0       ; Cursor Flash / Still
	tst.b	cursor_still(a6)                ; flash?
	bsr.s	set_radio_if_zero
	lea	prefs_monst_button(a6),a0       ; Load MonST Yes / No
	tst.b	monst_wanted(a6)                ; on?
	bsr.s	set_radio_if_set
	lea	prefs_stop_button(a6),a0        ; End of line Stop / Wrap
	tst.b	end_of_line_wrap(a6)            ; stop?
	bsr.s	set_radio_if_zero
	lea	prefs_tree-data_base(a6),a0     ; the Preferences tree
	moveq	#100,d4                         ; always put away
	bsr.w	gem_dialog                      ; show it
	cmp.w	#$1c,d4                         ; Cancel?
	beq.w	editor_loop                     ; yes: as it was
	btst	#$0,prefs_numbers_state(a6)     ; Numbers?
	seq	numpad_cursor(a6)               ; no: cursor keys
	lea	default_backups(pc),a0
	btst	#$0,prefs_backups_state(a6)     ; Backups Yes?
	sne	(a0)
	btst	#$0,prefs_indent_state(a6)      ; Auto indent Yes?
	sne	auto_indent(a6)
	btst	#$0,prefs_flash_state(a6)       ; Flash?
	seq	cursor_still(a6)                ; no: still
	btst	#$0,prefs_monst_state(a6)       ; Load MonST Yes?
	sne	monst_wanted(a6)
	btst	#$0,prefs_stop_state(a6)        ; Stop?
	seq	end_of_line_wrap(a6)            ; no: wrap
	movea.l	prefs_tab_spec(a6),a1           ; the tab setting text
	movea.l	(a1),a1
	bsr.w	parse_decimal                   ; as a number
	moveq	#0,d5                           ; no change yet
	cmp.w	#$2,d1                          ; at least 2?
	bcs.s	prefs_check_buffer              ; no: ignored
	cmp.w	#$11,d1                         ; over 16?
	bcc.s	prefs_check_buffer              ; yes: ignored
	cmp.w	tab_size(a6),d1                 ; the same?
	beq.s	prefs_check_buffer              ; yes
	move.w	d1,tab_size(a6)                 ; the new tab
	st	d5                              ; the text to redraw
prefs_check_buffer:
	movea.l	prefs_buffer_spec(a6),a1        ; the buffer size text
	movea.l	(a1),a1
	bsr.w	parse_decimal                   ; as a number
	cmp.l	text_buffer_size(a6),d1         ; the same?
	bne.s	prefs_new_buffer                ; no
prefs_same_buffer:
	cmp.w	#$1d,d4                         ; Save?
	bne.s	prefs_check_tab                 ; no
	bsr.s	save_preferences                ; yes: write GENST2.INF
prefs_check_tab:
	tst.b	d5                              ; a new tab?
	beq.w	editor_loop                     ; no: back to the editor
	bsr.w	gem_drop_messages               ; drop the redraw messages
	bra.w	editor_redraw_window            ; redraw the text
prefs_new_buffer:
	cmp.w	#$1d,d4                         ; Save?
	seq	d5
	move.l	d1,-(sp)                        ; the new size
	bsr.w	confirm_lose_changes            ; changes: ask to go on
	movem.l	(sp)+,d4                        ; the new size
	bne.s	prefs_same_buffer               ; no: the size stays
	cmp.l	#$fa0,d4                        ; at least 4000?
	bcc.s	prefs_free_buffer               ; yes
	move.l	#$fa0,d4                        ; no: 4000
prefs_free_buffer:
	bsr.w	free_program_memory             ; the program and block buffers freed
	movea.l	text_start(a6),a0               ; the text buffer
	bsr.w	dos_mfree                       ; freed
prefs_alloc_loop:
	move.l	d4,d0                           ; the size
	bsr.w	malloc_leave_free               ; get it
	bne.s	prefs_buffer_ok                 ; got it
	subi.l	#$fa0,d4                        ; 4000 less
	bcs.s	prefs_no_memory                 ; none left
	cmp.l	#$1f40,d4                       ; still 8000?
	bcc.s	prefs_alloc_loop                ; yes: again
prefs_no_memory:
	bra.w	quit_no_memory                  ; out of memory: stop
prefs_buffer_ok:
	move.l	d0,text_start(a6)               ; the new text buffer
	move.l	d4,text_buffer_size(a6)         ; its size
	pea	editor_loop(pc)                 ; back to the editor after
	tst.b	d5                              ; Save?
	beq.w	editor_clear_text               ; no: a new empty text
	bsr.s	save_preferences                ; yes: write GENST2.INF
	bra.w	editor_clear_text               ; a new empty text

;------------------------------------------------------------------------------
; Write the 30 byte GENST2.INF in the current folder: 'GENS', the tab, the buffer size, numeric pad, backups,
; auto indent and still cursor bytes, the assembly options' Max:___k text (3 bytes and a 0), the button
; chosen in each of the five Assembly Options groups, run with GEM, load MonST, wrap, find case sensitive,
; and 3 zero bytes.  An error is shown.
;------------------------------------------------------------------------------
save_preferences:	; from: menu_preferences
	bsr.w	busy_mouse                      ; busy mouse
	lea	inf_file_name(pc),a0            ; "GENST2.INF"
	bsr.w	dos_fcreate                     ; Fcreate
	bne.w	save_preferences_error          ; failed
	lea	path_buffer(a6),a0              ; the record
	movea.l	a0,a1
	move.l	inf_file_name(pc),(a0)+         ; 'GENS'
	move.w	tab_size(a6),(a0)+              ; the tab
	move.l	text_buffer_size(a6),(a0)+      ; the buffer size
	move.b	numpad_cursor(a6),(a0)+         ; the numeric pad
	move.b	default_backups(pc),(a0)+       ; backups
	move.b	auto_indent(a6),(a0)+           ; auto indent
	move.b	cursor_still(a6),(a0)+          ; still cursor
	move.l	options_max_text(pc),d0         ; the Max:___k text
	clr.b	d0
	move.l	d0,(a0)+
	lea	options_exec_obj(pc),a1         ; Program type
	bsr.s	radio_index
	lea	options_case_obj(pc),a1         ; Symbols case
	bsr.s	radio_index
	lea	options_debug_obj(pc),a1        ; Debug info
	bsr.s	radio_index
	lea	options_list_obj(pc),a1         ; List
	bsr.s	radio_index
	lea	options_output_obj(pc),a1       ; Output to
	bsr.s	radio_index
	move.b	run_with_gem(a6),(a0)+          ; run with GEM
	move.b	monst_wanted(a6),(a0)+          ; load MonST
	move.b	end_of_line_wrap(a6),(a0)+      ; wrap
	cmpi.w	#$4e75,case_fold_code(a6)       ; find case sensitive?
	seq	(a0)+
	clr.b	(a0)+                           ; spare
	clr.w	(a0)+
	bra.s	save_preferences_write

;------------------------------------------------------------------------------
; Store at (a0)+ the number of the selected button in the radio group whose first button is a1.
;------------------------------------------------------------------------------
radio_index:	; from: save_preferences
	moveq	#0,d0                           ; from the first
radio_index_loop:
	btst	#$0,$b(a1)                      ; selected?
	bne.s	radio_index_found               ; yes
	addq.b	#1,d0
	adda.w	#$18,a1                         ; the next button
	bra.s	radio_index_loop
radio_index_found:
	move.b	d0,(a0)+                        ; stored
	rts
save_preferences_write:	; from: save_preferences
	moveq	#30,d4                          ; 30 bytes
	lea	path_buffer(a6),a0              ; the record
	bsr.w	dos_fwrite                      ; Fwrite
	bne.s	save_preferences_error          ; failed
	bsr.w	dos_fclose                      ; Fclose
	bra.w	arrow_mouse                     ; arrow mouse
save_preferences_error:	; from: save_preferences
	bra.w	show_dos_error                  ; show the error

;------------------------------------------------------------------------------
; At the start: the default flashing cursor and 60000 byte buffer, then GENST2.INF (found by shel_find) when
; there is one with 'GENS' at its start: every setting save_preferences writes.
;------------------------------------------------------------------------------
load_preferences:	; from: editor_init
	sf	cursor_still(a6)                ; flashing cursor
	move.l	#$ea60,text_buffer_size(a6)     ; 60000 bytes
	lea	inf_file_name(pc),a0            ; "GENST2.INF"
	lea	inf_path(a6),a1                 ; to the search buffer
	move.l	a1,ptsin(a6)                    ; for shel_find
load_preferences_name:
	move.b	(a0)+,(a1)+
	bne.s	load_preferences_name
	moveq	#124,d0                         ; shel_find
	bsr.w	aes_call
	beq.w	load_preferences_done           ; not found
	lea	inf_path(a6),a0                 ; the path found
	bsr.w	dos_fopen_read                  ; Fopen
	bne.w	load_preferences_done           ; failed
	lea	path_buffer(a6),a0              ; the record
	moveq	#30,d4                          ; 30 bytes
	bsr.w	dos_fread                       ; Fread
	bne.w	load_preferences_close          ; short
	move.l	inf_file_name(pc),d0            ; 'GENS'
	cmp.l	(a0)+,d0                        ; there?
	bne.w	load_preferences_close          ; no
	move.w	(a0)+,tab_size(a6)              ; the tab
	move.l	(a0)+,text_buffer_size(a6)      ; the buffer size
	move.b	(a0)+,numpad_cursor(a6)         ; the numeric pad
	lea	default_backups(pc),a1          ; backups
	move.b	(a0)+,(a1)
	move.b	(a0)+,auto_indent(a6)           ; auto indent
	move.b	(a0)+,cursor_still(a6)          ; still cursor
	lea	options_max_text(pc),a1         ; the Max:___k text
	move.l	(a0)+,(a1)
	lea	options_exec_obj(pc),a1         ; Program type
	bsr.s	radio_select_index
	lea	options_case_obj(pc),a1         ; Symbols case
	bsr.s	radio_select_index
	lea	options_debug_obj(pc),a1        ; Debug info
	bsr.s	radio_select_index
	lea	options_list_obj(pc),a1         ; List
	bsr.s	radio_select_index
	lea	options_output_obj(pc),a1       ; Output to
	bsr.s	radio_select_index
	move.b	(a0)+,run_with_gem(a6)          ; run with GEM
	move.b	(a0)+,monst_wanted(a6)          ; load MonST
	move.b	(a0)+,end_of_line_wrap(a6)      ; wrap
	tst.b	(a0)+                           ; find case sensitive?
	beq.s	load_preferences_skip           ; no
	move.w	#$4e75,case_fold_code(a6)       ; yes: its routine just returns
load_preferences_skip:
	addq.w	#3,a0                           ; past the spare bytes
	bra.s	load_preferences_close

;------------------------------------------------------------------------------
; Select button d0 = (a0)+ of the radio group whose first button is a1 (0: the first stays as it is).
;------------------------------------------------------------------------------
radio_select_index:	; from: load_preferences
	moveq	#0,d0
	move.b	(a0)+,d0                        ; the button
	beq.s	radio_select_index_done         ; the first: as it is
	bclr	#$0,$b(a1)                      ; the first off
	mulu.w	#$18,d0
	bset	#$0,$b(a1,d0.w)                 ; that one on
radio_select_index_done:
	rts
load_preferences_close:	; from: load_preferences
	bsr.w	dos_fclose                      ; Fclose
load_preferences_done:	; from: load_preferences
	rts
inf_file_name:	; from: save_preferences, load_preferences
	dc.b	'GENST2.INF',0                  ; the settings file; its first 4 bytes are the file's magic
	dc.b	$00

;------------------------------------------------------------------------------
; Search menu "Goto Line" (Alt-G): the Goto Line dialog.  Out: d4 = the line number, 0 (Z) for Cancel.
;------------------------------------------------------------------------------
goto_line_dialog:	; from: cmd_goto_line
	lea	goto_line_tree-data_base(a6),a0 ; the Goto Line tree
	movea.l	goto_line_spec(a6),a1           ; its text field
	movea.l	(a1),a1
	clr.b	(a1)                            ; empty
	moveq	#100,d4                         ; always put away
	move.l	a1,-(sp)
	bsr.w	gem_dialog                      ; show it
	bsr.w	gem_drop_messages               ; drop the redraw messages
	bsr.w	redraw_under_dialog             ; redraw the text under it
	movea.l	(sp)+,a1                        ; the text
	subq.w	#2,d4                           ; Cancel?
	beq.s	parse_line_number_done          ; yes: 0

;------------------------------------------------------------------------------
; The decimal number at a1 (digits to a 0) in d4.w.
;------------------------------------------------------------------------------
parse_line_number:	; from: cmd_assemble
	moveq	#0,d4                           ; the value
parse_line_number_loop:
	move.b	(a1)+,d1                        ; a digit
	beq.s	parse_line_number_done          ; the end
	mulu.w	#$a,d4                          ; times 10
	subi.b	#$30,d1                         ; its value
	andi.w	#$ff,d1
	add.w	d1,d4                           ; added
	bra.s	parse_line_number_loop
parse_line_number_done:	; from: goto_line_dialog
	rts

;------------------------------------------------------------------------------
; Redraw the text in the area the last dialog covered, then clip to the window again.  Keeps d4.
;------------------------------------------------------------------------------
redraw_under_dialog:	; from: find_dialog, goto_line_dialog
	move.l	#$20001,contrl_count(a6)        ; 2 points, 1 integer
	move.w	vdi_handle(a6),contrl_handle(a6) ; the workstation
	st	intin(a6)                       ; clipping on
	movem.l	dialog_rect(a6),d0-d1           ; the dialog's area
	add.l	d0,d1                           ; as x1,y1,x2,y2
	movem.l	d0-d1,ptsin(a6)
	move.w	#$81,d0                         ; vs_clip
	bsr.w	vdi_call_handle_set
	move.w	d4,-(sp)
	bsr.w	redraw_window                   ; redraw the text
	bsr.w	clip_to_window                  ; clip to the window again
	move.w	(sp)+,d4
	rts

;------------------------------------------------------------------------------
; Take every message waiting (the redraws a dialog leaves) without acting on them, then redraw the status line.
;------------------------------------------------------------------------------
gem_drop_messages:                              ; from: editor_load_file, find_dialog, cmd_insert_file, cmd_assemble,
                                                ;   menu_preferences, goto_line_dialog
	move.w	#$30,intin(a6)                  ; messages and timer
	lea	message_buffer(a6),a0           ; the message buffer
	move.l	a0,ptsin(a6)
	move.l	#$20000,intin14(a6)             ; 2 ms
	moveq	#25,d0                          ; evnt_multi
	bsr.w	aes_call
	move.w	intout(a6),d0
	btst	#$5,d0                          ; the timer?
	beq.s	gem_drop_messages               ; no: more
	bsr.w	draw_status_line                ; the status line
	move.w	#$0,output_mode(a6)             ; output to the window
	rts

;------------------------------------------------------------------------------
; Fopen the file a1 for reading.  Out: a0 = the handle and d0 = 0 (Z), or d0 = the error.
;------------------------------------------------------------------------------
open_file_read:	; from: save_text_file
	clr.w	-(sp)                           ; read only
	move.l	a1,-(sp)                        ; the name
	move.w	#$3d,-(sp)
	trap	#1                              ; Fopen
	addq.l	#8,sp
	tst.l	d0                              ; opened?
	bpl.s	open_file_read_ok               ; yes
	rts
open_file_read_ok:
	movea.w	d0,a0                           ; the handle
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Find the extension of the name a0 (to a space or 0).  Out: d1 = the address after the '.', 0 (Z) when none;
; d0 = its last 4 characters packed into a long; a1 = past the name's end.
;------------------------------------------------------------------------------
find_extension:	; from: fsel_path_any_ext, menu_run_other_drop, save_text_file
	movea.l	a0,a1
find_extension_end:
	move.b	(a1)+,d1                        ; a character
	beq.s	find_extension_back             ; the end
	cmp.b	#$20,d1                         ; a space?
	bne.s	find_extension_end              ; no: on
find_extension_back:
	move.l	a1,-(sp)                        ; past the end
	moveq	#0,d0                           ; none yet
find_extension_loop:
	move.b	-(a1),d1                        ; back a character
	cmp.b	#$2e,d1                         ; a '.'?
	beq.s	find_extension_found            ; yes
	cmp.b	#$5c,d1                         ; a backslash?
	beq.s	find_extension_none             ; yes: no extension
	cmpa.l	a0,a1                           ; the start?
	bne.s	find_extension_loop             ; no: on
find_extension_none:
	moveq	#0,d1                           ; none
	bra.s	find_extension_done
find_extension_found:
	addq.l	#1,a1                           ; past the '.'
	move.l	a1,d1
find_extension_pack:
	move.b	(a1)+,d2                        ; a character
	beq.s	find_extension_done             ; the end
	lsl.l	#8,d0
	move.b	d2,d0                           ; packed in
	bra.s	find_extension_pack
find_extension_done:
	movea.l	(sp)+,a1                        ; past the end
	tst.l	d1
	rts

;------------------------------------------------------------------------------
; The full path of the name a0 in path_buffer: the file selector path's folder with the name in place of the
; mask.  Out: a0 = path_buffer.
;------------------------------------------------------------------------------
make_full_path:	; from: cmd_delete_file, menu_run_other_drop, save_text_file, open_input_file
	lea	path_buffer(a6),a2              ; the path buffer

;------------------------------------------------------------------------------
; The same into the buffer a2 (a0 still comes back as path_buffer).
;------------------------------------------------------------------------------
make_path_in:	; from: set_file_name, save_text_file
	lea	fsel_path(a6),a1                ; the file selector path
	moveq	#0,d2                           ; no folder end yet
make_path_loop:
	move.b	(a1)+,d1                        ; a character
	beq.s	make_path_name                  ; the end
	move.b	d1,(a2)+                        ; copied
	cmp.b	#$3a,d1                         ; a colon?
	beq.s	make_path_separator             ; yes
	cmp.b	#$5c,d1                         ; a backslash?
	bne.s	make_path_loop                  ; no
make_path_separator:
	move.l	a2,d2                           ; the name goes here
	bra.s	make_path_loop
make_path_name:
	movea.l	a2,a1                           ; at the end
	tst.l	d2                              ; a folder?
	beq.s	make_path_copy                  ; no
	movea.l	d2,a1                           ; yes: after it
make_path_copy:
	move.b	(a0)+,(a1)+                     ; the name
	bne.s	make_path_copy
	lea	path_buffer(a6),a0
	rts
window_title_text:	; from: open_editor_window, set_window_title
	dc.b	' GenST Editor/Assembler from HiSoft v ' ; the window title
title_version:	; from: set_version_title
	dc.w	$202e,$2020                     ; the version, put in from the assembler's version text
	dc.b	$20
info_line_text:	; from: open_editor_window
	dc.b	$00,$00,$00                     ; the info line: empty

;------------------------------------------------------------------------------
; Throw away the keys waiting in the BIOS keyboard buffer, so that held cursor and delete keys stop at once.
;------------------------------------------------------------------------------
flush_bios_keys:	; from: get_event
	movem.l	d0-d3/a0-a3,-(sp)
flush_bios_keys_loop:
	move.w	#$2,-(sp)                       ; the console
	move.w	#$1,-(sp)
	trap	#13                             ; Bconstat, Bconstat: a key waiting?
	addq.l	#4,sp
	tst.w	d0
	beq.s	flush_bios_keys_done            ; no
	move.l	#$20002,-(sp)                   ; the console, Bconin
	trap	#13                             ; Bconin, Bconin: thrown away
	addq.l	#4,sp
	bra.s	flush_bios_keys_loop
flush_bios_keys_done:
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; The editor's event reader.  Waits (evnt_multi, 400 ms timer for the flashing cursor) and turns what comes
; into event_type: 3 = a key in d1 (ASCII, or a control code: cursor keys as WordStar keys, F1-F10 and shift
; F1-F5 as $e8-$fa, -3/-2 line start/end); 7 = a command letter in event_code's high byte (Alt keys, menu
; items with a letter, 'H' for Help, 'Q' for the closer); 5 = event_code 1 a menu item without a letter
; (item in event_window), 2 a click in the text (click_x/y), else a window message for the editor window;
; 4 = another AES message, left in message_buffer for handle_message.  A key that comes with other events
; is held back until next time.  Also checks that the Find case routine is intact.  d1 is the result.
;------------------------------------------------------------------------------
get_event:	; from: editor_loop, line_edit
	movem.l	d0/d2-d4/a0-a3,-(sp)
	move.w	case_fold_code(a6),d0           ; the Find case routine
	cmp.w	#$4e75,d0                       ; case sensitive (rts)?
	beq.s	get_event_start                 ; yes: fine
	cmp.w	find_upper_case(pc),d0          ; the upper case routine?
	beq.s	get_event_start                 ; yes: fine
	lea	alert_find_corrupt(pc),a1       ; no: it was overwritten
	moveq	#1,d1
	bsr.w	gem_alert                       ; tell them
	bra.s	get_event_start
alert_find_corrupt:
	dc.b	'[1][WARNING: whatever you|just did corrupted the|FIND code][ Bug','! ]' ; the alert for the Find routine
                                                ;   overwritten
	dc.b	0
get_event_start:
	bsr.w	toggle_cursor                   ; draw the cursor (XOR)
	moveq	#-1,d4                          ; it is drawn
get_event_wait:	; from: appl_find_name
	tst.w	held_key(a6)                    ; a key held back?
	beq.s	get_event_multi                 ; no
	move.w	held_key(a6),intout5(a6)        ; yes: as the key
	clr.w	held_key(a6)
	moveq	#1,d0                           ; a key event
	bra.w	get_event_got
get_event_multi:
	clr.w	intin(a6)                       ; END_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	move.w	#$33,intin(a6)                  ; keys, button, messages and timer
	lea	message_buffer(a6),a0           ; the message buffer
	move.l	a0,ptsin(a6)
	clr.b	intout4_low(a6)
	move.w	#$1,intin1(a6)                  ; 1 click
	move.w	#$1,intin2(a6)                  ; left button
	move.w	#$1,intin3(a6)                  ; down
	move.l	#$1900000,intin14(a6)           ; 400 ms
	moveq	#25,d0                          ; evnt_multi
	bsr.w	aes_call
	move.w	intout(a6),-(sp)                ; the events
	move.w	#$1,intin(a6)                   ; BEG_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	move.w	(sp)+,d0
	cmp.w	#$20,d0                         ; only the timer?
	bne.s	get_event_got                   ; no
	bsr.w	update_sliders                  ; the sliders
	bsr.w	window_on_top                   ; on top?
	bne.s	get_event_wait                  ; no: no flashing
	tst.b	cursor_still(a6)                ; a still cursor?
	bne.s	get_event_wait                  ; yes
	bsr.w	toggle_cursor                   ; flash the cursor
	not.b	d4                              ; on or off
	bra.w	get_event_wait
get_event_got:
	tst.b	d4                              ; the cursor drawn?
	beq.s	get_event_kind                  ; no
	move.w	d0,-(sp)
	bsr.w	toggle_cursor                   ; yes: off
	not.b	d4
	move.w	(sp)+,d0
get_event_kind:
	btst	#$0,d0                          ; a key?
	beq.w	event_message                   ; no
get_event_key_only:
	cmp.w	#$1,d0                          ; only the key?
	beq.s	event_key                       ; yes
	move.w	intout5(a6),held_key(a6)        ; no: held back for next time
	bra.w	event_message                   ; the other events first
event_key:
	move.w	intout5(a6),d1                  ; scan code and ASCII
	move.w	d1,d0
	lsr.w	#8,d0                           ; the scan code
	tst.b	d1                              ; an ASCII code?
	beq.w	event_key_scan                  ; no
	lea	key_remap_table(pc),a0          ; the keys to change
	moveq	#5,d2                           ; six
event_key_remap:
	cmp.w	(a0)+,d1                        ; this one?
	dbeq	d2,event_key_remap
	bne.s	event_key_special               ; no
	move.w	$a(a0),d1                       ; yes: what it becomes
	bra.s	event_key_char
event_key_special:
	cmp.w	#$4737,d1                       ; shift Clr/Home?
	beq.w	event_saved_acc                 ; yes: the SAVED! accessory
	cmp.b	#$67,d0                         ; the numeric pad?
	bcs.s	event_key_char                  ; no
	cmp.b	#$70,d0
	bcc.s	event_key_char                  ; no
	tst.b	numpad_cursor(a6)               ; as cursor keys?
	beq.s	event_key_char                  ; no
	cmp.w	#$6a14,d1                       ; ctrl 4?
	beq.s	event_key_line_start            ; yes
	cmp.w	#$6c1e,d1                       ; ctrl 6?
	beq.s	event_key_line_end              ; yes
	move.b	get_event_key_only+3(pc,d0.w),d1 ; the code for the pad key
	beq.w	get_event_wait                  ; none (5): ignored
	bra.s	event_key_char
event_key_line_start:
	moveq	#-3,d1                          ; line start
	bra.s	event_key_char
event_key_line_end:
	moveq	#-2,d1                          ; line end
	bra.s	event_key_char
	dc.w	$fd05,$1213,$0004,$fe18,$0300   ; numeric pad 7-3 as cursor keys: line start, ^E, ^R, ^S, none, ^D, line
                                                ;   end, ^X, ^C
event_key_char:	; from: appl_find_name
	cmp.b	#$8,d1                          ; backspace?
	beq.s	event_key_flush                 ; yes
	cmp.b	#$7f,d1                         ; delete?
	beq.s	event_key_flush                 ; yes
	cmp.b	#$20,d1                         ; a control code?
	bcc.s	event_key_done                  ; no
	move.l	#$32c017a,d0                    ; the repeating ones: ^A ^C-^F ^H ^R ^S ^U ^X ^Y
	btst	d1,d0                           ; one of them?
	beq.s	event_key_done                  ; no
event_key_flush:
	bsr.w	flush_bios_keys                 ; stop key repeat running on
event_key_done:
	bsr.w	clear_shown_message             ; the message off the info line
	move.w	#$3,event_type(a6)              ; a key
	movem.l	(sp)+,d0/d2-d4/a0-a3
	rts
event_key_scan:
	cmp.b	#$3b,d0                         ; below F1?
	bcs.s	event_key_alt                   ; yes
	cmp.b	#$75,d0                         ; past ctrl right?
	bcc.s	event_key_alt                   ; yes
	cmp.b	#$62,d0                         ; Help?
	beq.s	event_key_help                  ; yes
	subi.b	#$3b,d0
	andi.w	#$ff,d0
	lea	scan_key_table(pc),a0           ; what the key gives
	move.b	0(a0,d0.w),d1
	bra.s	event_key_char
event_key_help:
	move.b	#$48,event_code(a6)             ; 'H': help
	bra.s	event_command_done
event_key_alt:
	cmp.b	#$10,d0                         ; an Alt letter (Q to M rows)?
	bcs.w	get_event_wait                  ; no
	cmp.b	#$33,d0
	bcc.w	get_event_wait                  ; no
	andi.w	#$ff,d0
	movea.l	caps_table(a6),a0               ; the caps lock table
	move.b	0(a0,d0.w),d0                   ; the letter
	cmp.b	#$53,d0                         ; S?
	bne.s	event_key_command               ; no
	moveq	#22,d3                          ; menu item 22: Save
	andi.b	#$3,intout4_low(a6)             ; with shift?
	bne.w	event_menu_item                 ; yes: as the menu item
event_key_command:
	move.b	d0,event_code(a6)               ; the command letter
event_command_done:	; from: appl_find_name
	move.w	#$7,event_type(a6)              ; a command letter
	bsr.w	clear_shown_message             ; the message off the info line
	movem.l	(sp)+,d0/d2-d4/a0-a3
	rts
scan_key_table:
	dc.w	$e8ec,$f0f4,$f800,$0000,$0000,$0000,$0005,$0000 ; scan codes $3b-$74 to codes: F1-F5 $e8 $ec $f0 $f4
                                                ;   $f8, cursor keys ^E ^S ^D ^X
	dc.w	$1300,$0400,$0018,$0000,$00ea,$eefa,$f6f2,$0000 ; shift F1-F5 $ea $ee $fa $f6 $f2
	dc.w	$0000,$0000,$0000,$1500,$0000,$0000,$0000,$0000 ; Undo ^U
	dc.w	$0000,$0000,$0000,$0000,$fdfe   ; ctrl left / right: line start, line end
key_remap_table:
	dc.b	'K4M6H8P2)'                     ; keys changed: shift left, right, up, down and two more (scan code and
                                                ;   ASCII)
	dc.b	$ff,$28,$ba,$00,$01,$00,$06,$00,$12,$00,$03,$00,$5f,$00,$27
event_message:
	btst	#$4,d0                          ; a message?
	beq.w	event_button                    ; no
	move.w	message_buffer(a6),d0           ; its type
	cmp.w	#$a,d0                          ; MN_SELECTED?
	beq.w	event_menu                      ; yes
	cmp.w	#$16,d0                         ; WM_CLOSED?
	beq.w	event_closed                    ; yes
	cmp.w	#$18,d0                         ; WM_ARROWED?
	beq.w	event_arrowed                   ; yes
	cmp.w	#$15,d0                         ; WM_TOPPED?
	beq.w	event_window_message            ; yes
	cmp.w	#$1b,d0                         ; WM_SIZED?
	beq.w	event_window_message            ; yes
	cmp.w	#$1c,d0                         ; WM_MOVED?
	beq.w	event_window_message            ; yes
	cmp.w	#$17,d0                         ; WM_FULLED?
	beq.w	event_window_message            ; yes
	cmp.w	#$1a,d0                         ; WM_VSLID?
	beq.w	event_window_message            ; yes
	cmp.w	#$19,d0                         ; WM_HSLID?
	beq.w	event_window_message            ; yes
event_pass_message:	; from: appl_find_name
	move.w	#$4,event_type(a6)              ; a message for handle_message
event_return:	; from: appl_find_name
	movem.l	(sp)+,d0/d2-d4/a0-a3
	rts
event_saved_acc:
	move.w	#$2a,message_buffer(a6)         ; as message $2a: wake the SAVED! accessory
	bra.s	event_pass_message
event_button:
	btst	#$1,d0                          ; a click?
	beq.w	get_event_wait                  ; no: wait again
	move.l	intout1(a6),-(sp)               ; where
	bsr.w	window_on_top                   ; on top?
	movem.l	(sp)+,d0
	bne.w	get_event_wait                  ; no: ignored
	move.w	d0,d1                           ; y
	swap	d0                              ; x
	cmp.w	work_area(a6),d0                ; left of the text?
	bcs.w	get_event_wait                  ; yes
	cmp.w	work_right(a6),d0               ; right of it?
	bcc.w	get_event_wait                  ; yes
	cmp.w	work_y1(a6),d1                  ; above it?
	bcs.w	get_event_wait                  ; yes
	cmp.w	work_y2(a6),d1                  ; below it?
	bcc.w	get_event_wait                  ; yes
	move.w	#$5,event_type(a6)              ; a window event
	move.w	#$2,event_code(a6)              ; a click
	move.w	d0,click_x(a6)                  ; x
	move.w	d1,click_y(a6)                  ; y
	bra.s	event_return

;------------------------------------------------------------------------------
; When a message is on the info line: $ff blanks it, a positive value redraws the whole status line.
; Keeps d1.
;------------------------------------------------------------------------------
clear_shown_message:	; from: get_event, wait_key_or_click
	tst.b	message_state(a6)               ; a message there?
	beq.s	clear_shown_message_done        ; no
	bpl.s	clear_shown_message_status      ; positive: redraw the status line
	move.w	d1,-(sp)
	lea	msg_blank(pc),a1                ; two spaces
	bsr.w	message_show                    ; over it
	sf	message_state(a6)               ; none now
	move.w	(sp)+,d1
clear_shown_message_done:
	rts
clear_shown_message_status:
	movem.l	d0-d3/a0-a3,-(sp)
	move.w	output_mode(a6),-(sp)
	bsr.w	draw_status_line                ; redraw the status line
	move.w	(sp)+,output_mode(a6)
	movem.l	(sp)+,d0-d3/a0-a3
	sf	message_state(a6)               ; none now
	rts

;------------------------------------------------------------------------------
; Z when the editor window is the top window.
;------------------------------------------------------------------------------
window_on_top:	; from: get_event, appl_find_name
	movem.l	d1-d3/a0-a3,-(sp)
	moveq	#10,d0                          ; WF_TOP
	move.w	vdi_handle(a6),d1
	bsr.w	window_get                      ; wind_get
	move.w	intout1(a6),d0                  ; the top window
	movem.l	(sp)+,d1-d3/a0-a3
	cmp.w	window_handle(a6),d0            ; ours?
	rts

;------------------------------------------------------------------------------
; Act on an AES message left by get_event (event_type 4): a redraw, a scroll of one line (the cursor stays on
; its line) or message $2a (wake the SAVED! accessory with AC_OPEN).
;------------------------------------------------------------------------------
handle_message:	; from: editor_loop, line_edit
	cmpi.w	#$4,event_type(a6)              ; a message?
	beq.s	handle_message_go               ; yes
	rts
handle_message_go:
	movem.l	d0-d3/a0-a3,-(sp)
	move.w	message_buffer(a6),d0           ; its type
	cmp.w	#$18,d0                         ; WM_ARROWED?
	beq.w	message_arrowed                 ; yes
	cmp.w	#$14,d0                         ; WM_REDRAW?
	beq.s	message_redraw                  ; yes
	cmp.w	#$2a,d0                         ; the SAVED! message?
	bne.s	handle_message_done             ; no
	lea	saved_acc_name(pc),a0           ; "SAVED!  "
	bsr.s	appl_find_name                  ; appl_find
	bpl.s	saved_acc_write                 ; found
	lea	saved_acc_other_name(pc),a0     ; "SAVED   "
	bsr.s	appl_find_name                  ; appl_find
	bmi.s	handle_message_done             ; not found
saved_acc_write:
	move.w	d0,intin(a6)                    ; to it
	move.w	#$10,intin1(a6)                 ; 16 bytes
	lea	message_buffer(a6),a0           ; the message
	move.l	a0,ptsin(a6)
	move.w	#$28,(a0)                       ; AC_OPEN
	moveq	#12,d0                          ; appl_write
	bsr.w	aes_call
handle_message_done:	; from: appl_find_name
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; appl_find the application named at a0 (8 characters).  Out: d0 = its id, negative when not found.
;------------------------------------------------------------------------------
appl_find_name:	; from: handle_message
	move.l	a0,ptsin(a6)                    ; the name
	moveq	#13,d0                          ; appl_find
	bra.w	aes_call
saved_acc_name:	; from: handle_message
	dc.b	'SAVED!  ',0                    ; the SAVED! accessory's name
saved_acc_other_name:	; from: handle_message
	dc.b	'SAVED   ',0                    ; its other name
message_redraw:	; from: handle_message
	move.w	message_window(a6),d0           ; our window?
	cmp.w	window_handle(a6),d0
	bne.s	handle_message_done             ; no
	move.w	#$1,intin(a6)                   ; BEG_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	movem.l	d4-d7/a4,-(sp)
	move.w	output_mode(a6),-(sp)           ; the output mode
	move.w	#$0,output_mode(a6)             ; to the window
	moveq	#11,d0                          ; WF_FIRSTXYWH
message_redraw_rect:
	move.w	window_handle(a6),d1            ; the window
	bsr.w	window_get                      ; wind_get
	move.w	intout3(a6),d0                  ; width
	or.w	intout4(a6),d0                  ; or height?
	beq.s	message_redraw_end              ; none: all done
	move.w	#$2,contrl_count(a6)            ; 2 points
	move.w	#$1,contrl_intin_count(a6)      ; 1 integer
	move.w	vdi_handle(a6),contrl_handle(a6) ; the workstation
	st	intin(a6)                       ; clipping on
	movem.w	intout1(a6),d0-d3               ; the rectangle
	subq.w	#1,d2
	subq.w	#1,d3
	lea	message_values(a6),a0           ; the area to redraw
	bsr.w	intersect_rect                  ; the part in both
	bne.s	message_redraw_next             ; none
	add.w	d0,d2                           ; as x1,y1,x2,y2
	add.w	d1,d3
	movem.w	d0-d3,ptsin(a6)
	move.w	#$81,d0                         ; vs_clip
	bsr.w	vdi_call_handle_set
	move.w	left_column(a6),d6              ; the left column
	bsr.w	redraw_text                     ; the text redrawn
message_redraw_next:
	moveq	#12,d0                          ; WF_NEXTXYWH
	bra.s	message_redraw_rect
message_redraw_end:
	clr.w	intin(a6)                       ; END_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	bsr.w	clip_to_window                  ; clip to the window again
	bsr.w	window_on_top                   ; on top?
	bne.s	message_redraw_done             ; no
	bsr.w	draw_status_line                ; the status line
	bsr.w	message_area_clear              ; the rest of the info line
message_redraw_done:
	move.w	(sp)+,output_mode(a6)           ; the output mode back
	movem.l	(sp)+,d4-d7/a4
	bsr.w	editor_cursor_visible           ; the cursor's place
	bra.w	handle_message_done
event_arrowed:	; from: get_event
	move.w	message_window(a6),d0           ; our window?
	cmp.w	window_handle(a6),d0
	bne.w	get_event_wait                  ; no: ignored
	move.w	message_values(a6),d0           ; the arrow action
	cmp.w	#$2,d0                          ; a line up?
	beq.w	event_pass_message              ; yes: for handle_message
	cmp.w	#$3,d0                          ; a line down?
	beq.w	event_pass_message              ; yes: for handle_message
event_arrowed_key:
	move.b	arrow_key_table(pc,d0.w),d1     ; as a key
	bne.w	event_key_char
	moveq	#24,d0                          ; page left or right
	bra.w	event_window_message            ; as a window event
arrow_key_table:
	dc.w	$1203,$0518,$0000,$1304         ; arrow actions 0-7 as keys: ^R, ^C, ^E, ^X, none, none, ^S, ^D
message_arrowed:	; from: handle_message
	cmpi.w	#$3,message_values(a6)          ; a line down?
	beq.s	arrowed_down                    ; yes
	tst.w	top_line_number(a6)             ; at the top?
	beq.s	event_arrowed_key               ; yes: as the up key
	movem.l	d7/a4,-(sp)
	movea.l	top_line(a6),a4                 ; the window's first line
	bsr.w	scroll_to_previous_line         ; a line before it, the text down a row
	moveq	#0,d7
	subq.w	#1,top_line_number(a6)          ; the first line one less
	bsr.w	editor_cursor_visible
	bsr.w	redraw_cursor_line              ; the new top line drawn
	movem.l	(sp)+,d7/a4
	cmp.w	last_row(a6),d7                 ; the cursor at the bottom?
	beq.s	arrowed_up_cursor               ; yes
	addq.w	#1,d7                           ; no: a row lower, the same line
	bsr.w	editor_cursor_visible
	bra.w	editor_loop                     ; back to the editor loop
arrowed_up_cursor:
	bsr.w	editor_cursor_visible
	bsr.w	text_prev_line                  ; the cursor a line up
	bra.w	editor_loop                     ; back to the editor loop
arrowed_down:
	move.w	line_count(a6),d1               ; the line count
	cmp.w	top_line_number(a6),d1          ; the top line the last?
	beq.s	event_arrowed_key               ; yes: as the down key
	movem.l	d7/a4,-(sp)
	sub.w	last_row(a6),d7                 ; rows below the cursor
	neg.w	d7
arrowed_down_find:
	bsr.w	text_next_line                  ; the next line
	dbne	d7,arrowed_down_find            ; to the bottom row's next
	bne.s	arrowed_down_end                ; the end of the text: nothing
	bsr.w	scroll_text_up                  ; the text up a row
	move.w	last_row(a6),d7                 ; the bottom row
	addq.w	#1,top_line_number(a6)          ; the first line one more
	bsr.w	editor_cursor_visible
	bsr.w	redraw_cursor_line              ; the new bottom line drawn
	movea.l	top_line(a6),a4                 ; the old top line
	bsr.w	text_next_line                  ; the one after it
	move.l	a4,top_line(a6)                 ; the new top line
	movem.l	(sp)+,d7/a4
	tst.w	d7                              ; the cursor at the top?
	beq.s	arrowed_down_cursor             ; yes
	subq.w	#1,d7                           ; no: a row higher, the same line
	bsr.w	editor_cursor_visible
	bra.w	editor_loop                     ; back to the editor loop
arrowed_down_cursor:
	bsr.w	editor_cursor_visible
	bsr.w	text_next_line                  ; the cursor a line down
	bra.w	editor_loop                     ; back to the editor loop
arrowed_down_end:
	movem.l	(sp)+,d7/a4
	bra.w	editor_loop                     ; back to the editor loop
event_closed:	; from: get_event
	move.b	#$51,event_code(a6)             ; the closer: 'Q', quit
	bra.w	event_command_done
event_menu:	; from: get_event
	move.w	message_window(a6),intin(a6)    ; the menu title
	move.w	#$1,intin1(a6)                  ; normal
	move.l	menu_tree_address(a6),ptsin(a6) ; the menu tree
	moveq	#33,d0                          ; menu_tnormal
	bsr.w	aes_call
	bsr.w	window_on_top                   ; on top?
	bne.w	get_event_wait                  ; no: ignored
	move.w	message_values(a6),d3           ; the item
	lea	menu_key_table(pc),a0           ; items and their keys
event_menu_find:
	move.b	(a0)+,d0                        ; an item
	beq.s	event_menu_item                 ; none: as a menu item
	cmp.b	d3,d0                           ; this one?
	beq.s	event_menu_found                ; yes
	addq.w	#1,a0
	bra.s	event_menu_find
event_menu_found:
	move.b	(a0)+,d0                        ; its key
	cmp.b	#$20,d0                         ; a control code?
	bcs.s	event_menu_control              ; yes
	cmp.b	#$80,d0
	bcc.s	event_menu_control
	move.b	d0,event_code(a6)               ; a command letter
	bra.w	event_command_done
event_menu_control:
	move.b	d0,d1                           ; as a key
	bra.w	event_key_char
menu_key_table:
	dc.w	$1343,$144c,$1753,$1957,$1a49   ; menu items and their command letters, a control code for Preferences
                                                ;   (^T)
	dc.b	$1e
	dc.b	'Q F"N#P%R+T,B.'
	dc.b	$14                             ; ^T
	dc.b	')G0A1X2D3M4K6J8O',0
	dc.b	$00
event_menu_item:	; from: get_event
	swap	d3                              ; the item
	move.w	#$1,d3                          ; 1: a menu item
	swap	d3
	move.l	d3,event_code(a6)               ; event_code and event_window
	move.w	#$5,event_type(a6)              ; a window event
	bra.w	event_return
event_window_message:	; from: get_event
	move.w	#$5,event_type(a6)              ; a window event
	move.w	message_window(a6),event_item(a6) ; the window
	move.w	d0,event_code(a6)               ; the message
	bra.w	event_return
	dc.w	$414d,$5021,$4e75               ; not used: 'AMP!' and an rts

;------------------------------------------------------------------------------
; A new text: one line, at the top, and the sliders set again.
;------------------------------------------------------------------------------
reset_view:	; from: aes_call
	move.w	#$1,line_count(a6)              ; one line
	clr.w	top_line_number(a6)             ; from the first
	move.w	#$ffff,shown_slider_size(a6)    ; slider size not shown yet
	move.w	#$ffff,shown_slider_place(a6)   ; slider place not shown yet

;------------------------------------------------------------------------------
; Set the vertical slider's size and place (1-1000) from the line count, when they change.
;------------------------------------------------------------------------------
update_sliders:	; from: window_sized, editor_clear_text, get_event
	clr.b	sliders_stale(a6)               ; done
	move.w	last_row(a6),d0                 ; the rows
	mulu.w	#$3e7,d0                        ; in 1000ths
	divu.w	line_count(a6),d0               ; of the lines
	addq.w	#1,d0
	cmp.w	#$3e8,d0                        ; over 1000?
	bcs.s	update_sliders_size             ; no
	move.w	#$3e8,d0                        ; 1000
update_sliders_size:
	cmp.w	shown_slider_size(a6),d0        ; as shown?
	beq.s	update_sliders_position         ; yes
	move.w	d0,shown_slider_size(a6)
	move.w	window_handle(a6),intin(a6)     ; the window
	move.w	#$10,intin1(a6)                 ; WF_VSLSIZE
	move.w	d0,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
update_sliders_position:
	move.w	top_line_number(a6),d0          ; the first line
	mulu.w	#$3e7,d0                        ; in 1000ths
	move.w	line_count(a6),d1               ; the lines
	sub.w	last_row(a6),d1                 ; less a window full
	bls.s	update_sliders_end              ; all in the window
	divu.w	d1,d0
	cmp.w	#$3e7,d0                        ; over 999?
	bcs.s	update_sliders_set              ; no
update_sliders_end:
	move.w	#$3e7,d0                        ; at the end
update_sliders_set:
	addq.w	#1,d0
	cmp.w	shown_slider_place(a6),d0       ; as shown?
	beq.s	update_sliders_done             ; yes
	move.w	d0,shown_slider_place(a6)
	move.w	window_handle(a6),intin(a6)     ; the window
	move.w	#$9,intin1(a6)                  ; WF_VSLIDE
	move.w	d0,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
update_sliders_done:
	rts

;------------------------------------------------------------------------------
; Print the text a1 that has a length word in front.
;------------------------------------------------------------------------------
editor_print_counted:	; from: draw_status_line, message_show, message_replaced
	move.w	(a1)+,d2                        ; its length
	subq.w	#1,d2
editor_print_counted_loop:
	move.b	(a1)+,d1                        ; a character
	bsr.w	editor_put_char                 ; printed
	dbra	d2,editor_print_counted_loop
	rts

;------------------------------------------------------------------------------
; Z when a key is waiting and it is Esc.
;------------------------------------------------------------------------------
editor_check_escape:	; from: replace_all
	movem.l	d0/d2/a0-a2,-(sp)
	bsr.s	read_bios_key                   ; a key
	cmp.b	#$1b,d0                         ; Esc?
	movem.l	(sp)+,d0/d2/a0-a2
	rts

;------------------------------------------------------------------------------
; d0 = the key waiting at the console (Bconin), 0 when none.
;------------------------------------------------------------------------------
read_bios_key:	; from: editor_check_escape
	move.w	#$2,-(sp)                       ; the console
	move.w	#$1,-(sp)
	trap	#13                             ; Bconstat, Bconstat: a key?
	addq.l	#4,sp
	tst.w	d0
	beq.s	read_bios_key_done              ; no
	move.l	#$20002,-(sp)                   ; the console, Bconin
	trap	#13                             ; Bconin
	addq.l	#4,sp
read_bios_key_done:
	rts

;------------------------------------------------------------------------------
; Scroll the window sideways (16 columns at a time) so that the cursor column d6 shows, then work out the
; cursor's place on the screen from d6 and the row d7.
;------------------------------------------------------------------------------
editor_cursor_visible:                          ; from: key_cursor_left, key_cursor_right, key_cursor_up,
                                                ;   key_cursor_down, cursor_line_start, key_page_up, 11 more
	move.w	window_columns(a6),d0           ; the columns
	subq.w	#8,d0                           ; less 8
	move.w	left_column(a6),d2              ; the left column
	move.w	d6,d1
	sub.w	d2,d1                           ; the cursor in the window
	bcs.s	editor_scroll_left              ; left of it: scroll left
	tst.w	d2                              ; the left column 0?
	beq.s	editor_cursor_visible_right     ; yes
	cmp.w	#$8,d1                          ; in the first 8?
	bcs.s	editor_scroll_left              ; yes: scroll left
editor_cursor_visible_right:
	cmp.w	d0,d1                           ; within 8 of the right?
	bcc.w	editor_scroll_right             ; yes: scroll right
editor_cursor_visible_place:	; from: editor_place_cursor_column
	move.w	d1,d0                           ; the column in the window
	bra.s	editor_place_cursor_column

;------------------------------------------------------------------------------
; The cursor's place on the screen (cursor_x, cursor_y) from the column d6 and the row d7.
;------------------------------------------------------------------------------
editor_place_cursor:	; from: command_mouse, window_check_arrowed, redraw_text
	move.w	d6,d0
	sub.w	left_column(a6),d0              ; in the window

;------------------------------------------------------------------------------
; The same with the window column in d0.
;------------------------------------------------------------------------------
editor_place_cursor_column:	; from: editor_cursor_visible, redraw_text, clear_window_home
	mulu.w	char_width(a6),d0               ; to pixels
	add.w	text_x(a6),d0
	move.w	d0,cursor_x(a6)                 ; the x
	move.w	d7,d0                           ; the row
	mulu.w	char_height(a6),d0              ; to pixels
	add.w	text_y(a6),d0
	move.w	d0,cursor_y(a6)                 ; the y
	rts
editor_scroll_left:	; from: editor_cursor_visible
	subi.w	#$10,left_column(a6)            ; 16 columns left
	cmp.w	left_column(a6),d6              ; far enough?
	bcs.s	editor_scroll_left              ; no
	sub.w	left_column(a6),d2              ; how far it moved
	beq.s	editor_scroll_left_done         ; not at all
	cmp.w	window_columns(a6),d2           ; a window full or more?
	bcc.s	editor_scroll_left_redraw       ; yes: redraw it all
	mulu.w	char_width(a6),d2               ; in pixels
	bsr.w	scroll_text_right               ; the text moved right
	movem.w	ptsin+8(a6),d0-d3               ; the area left
	move.w	d0,d2
	addq.w	#2,d2
	move.w	ptsin(a6),d0
	bsr.w	editor_set_clip                 ; clip to it
editor_scroll_left_redraw:
	bsr.s	editor_draw_text_kept           ; draw the text
	bsr.w	clip_to_window                  ; clip to the window again
editor_scroll_left_done:
	move.w	d6,d1
	sub.w	left_column(a6),d1              ; the column in the window
	bra.s	editor_cursor_visible_place
editor_scroll_right:	; from: editor_cursor_visible
	addi.w	#$10,left_column(a6)            ; 16 columns right
	addi.w	#$10,d0
	cmp.w	d0,d1                           ; far enough?
	bcc.s	editor_scroll_right             ; no
	move.w	left_column(a6),d0
	sub.w	d2,d0                           ; how far it moved
	beq.s	editor_scroll_right_done        ; not at all
	cmp.w	window_columns(a6),d0           ; a window full or more?
	bcc.s	editor_scroll_right_redraw      ; yes: redraw it all
	mulu.w	char_width(a6),d0               ; in pixels
	move.w	d0,d2
	bsr.w	scroll_text_left                ; the text moved left
	movem.w	ptsin+8(a6),d0-d3               ; the area left
	move.w	d2,d0
	subq.w	#2,d0
	move.w	ptsin+4(a6),d2
	bsr.s	editor_set_clip                 ; clip to it
editor_scroll_right_redraw:
	bsr.s	editor_draw_text_kept           ; draw the text
	bsr.w	clip_to_window                  ; clip to the window again
editor_scroll_right_done:
	move.w	d6,d1
	sub.w	left_column(a6),d1              ; the column in the window
	bra.w	editor_cursor_visible_place

;------------------------------------------------------------------------------
; Clip the VDI to x1,y1,x2,y2 in d0-d3.
;------------------------------------------------------------------------------
editor_set_clip:	; from: editor_place_cursor_column
	movem.w	d0-d3,ptsin(a6)                 ; the area
	move.w	#$2,contrl_count(a6)            ; 2 points
	move.w	#$1,contrl_intin_count(a6)      ; 1 integer
	move.w	vdi_handle(a6),contrl_handle(a6) ; the workstation
	st	intin(a6)                       ; clipping on
	move.w	#$81,d0                         ; vs_clip
	bsr.w	vdi_call_handle_set
	rts

;------------------------------------------------------------------------------
; Draw the window's text, keeping d4-d7 and a4.
;------------------------------------------------------------------------------
editor_draw_text_kept:	; from: editor_place_cursor_column
	movem.l	d4-d7/a4,-(sp)
	bsr.w	redraw_text
	movem.l	(sp)+,d4-d7/a4
	rts

;------------------------------------------------------------------------------
; Cursor to the first column of the first row.
;------------------------------------------------------------------------------
editor_cursor_home:	; from: aes_call, window_sized, editor_clear_text
	moveq	#0,d6                           ; column 0
	move.w	d6,d7                           ; row 0
	bra.w	editor_cursor_visible

;------------------------------------------------------------------------------
; The window title: the file's name, or the GenST title when there is none.
;------------------------------------------------------------------------------
set_window_title:	; from: editor_load_file, cmd_save_as, editor_clear_text
	movem.l	d0-d3/a0-a3,-(sp)
	lea	file_name(a6),a1                ; the file name
	tst.b	(a1)                            ; one?
	bne.s	set_window_title_set            ; yes
	lea	window_title_text(pc),a1        ; no: the GenST title
set_window_title_set:
	move.w	window_handle(a6),intin(a6)     ; the window
	move.w	#$2,intin1(a6)                  ; WF_NAME
	move.l	a1,intin2(a6)
	moveq	#105,d0                         ; wind_set
	bsr.w	aes_call
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; Read the open file text_file_handle into a3 (d1 bytes at most), as editor text: a closing ^Z becomes CR,
; CR LF and a lone LF become CR.  The file is closed.  Out: d1 = the length, d0 = 0; an error is shown and
; leaves an empty text.
;------------------------------------------------------------------------------
read_text_file:	; from: editor_load_file, cmd_insert_file
	bsr.w	busy_mouse                      ; busy mouse
	movea.l	a3,a5
	move.l	a3,-(sp)                        ; the buffer
	move.l	d1,-(sp)                        ; the most
	move.w	text_file_handle(a6),-(sp)      ; the file
	move.w	#$3f,-(sp)
	trap	#1                              ; Fread
	lea	$c(sp),sp
	movea.l	a5,a0
	movea.l	a0,a1                           ; to the same place
	moveq	#0,d1                           ; no length yet
	tst.l	d0                              ; empty?
	beq.s	read_text_close                 ; yes
	bmi.s	read_text_error                 ; an error
	cmpi.b	#$1a,-$1(a0,d0.l)               ; ^Z at the end?
	bne.s	read_text_convert               ; no
	move.b	#$d,-$1(a0,d0.l)                ; yes: CR
read_text_convert:
	moveq	#10,d3                          ; LF
	moveq	#13,d4                          ; CR
	cmp.b	(a0),d3                         ; an LF first?
	bne.s	read_text_loop                  ; no
	move.b	d4,(a0)                         ; yes: CR
read_text_loop:
	move.b	(a0)+,d2                        ; a character
	cmp.b	d3,d2                           ; LF?
	bne.s	read_text_store                 ; no
	cmp.b	-$2(a0),d4                      ; after a CR?
	beq.s	read_text_next                  ; yes: dropped
	move.b	d4,d2                           ; no: CR
read_text_store:
	move.b	d2,(a1)+                        ; stored
	addq.l	#1,d1                           ; counted
read_text_next:
	subq.l	#1,d0
	bne.s	read_text_loop
read_text_close:
	move.l	d1,-(sp)
	move.w	text_file_handle(a6),-(sp)      ; the file
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose
	addq.l	#4,sp
	bsr.w	arrow_mouse                     ; arrow mouse
	st	text_touched(a6)                ; a new text
	move.l	(sp)+,d1                        ; the length
	moveq	#0,d0
	rts
read_text_error:
	move.b	#$d,(a5)                        ; an empty text
	bsr.w	show_dos_error                  ; show the error
	moveq	#0,d1
	bra.s	read_text_close

;------------------------------------------------------------------------------
; When the buffer has room for an LF after every CR: spread the text a3 (d1 bytes) out with them, write it in
; one go (less the closing CR LF) and close it up again; returns through save_text_file's end.  Without the
; room it returns to save_text_file.
;------------------------------------------------------------------------------
write_with_lf:	; from: save_text_file
	move.l	d1,-(sp)
	subq.l	#1,d1
	moveq	#0,d0                           ; the CR count
	move.l	#$10000,d2                      ; 64K steps for dbra
	movea.l	a3,a0
write_with_lf_count:
	cmpi.b	#$d,(a0)+                       ; a CR?
	bne.s	write_with_lf_count_next        ; no
	addq.l	#1,d0
write_with_lf_count_next:
	dbra	d1,write_with_lf_count
	sub.l	d2,d1
	bcc.s	write_with_lf_count
	move.l	d0,d4                           ; the LFs to add
	add.l	text_end(a6),d0                 ; past the text's end
	cmp.l	text_limit(a6),d0               ; room?
	bcs.s	write_with_lf_room              ; yes
	move.l	(sp)+,d1                        ; no: line by line
	rts
write_with_lf_room:
	move.l	(sp)+,d1
	addq.l	#4,sp                           ; drop the return
	move.l	d1,-(sp)
	lea	0(a3,d1.l),a0                   ; the text's end
	subq.l	#1,d1
	move.l	d4,d3
	movea.l	a3,a4
write_with_lf_spread:
	move.b	-(a0),d0                        ; from the end
	cmp.b	#$d,d0                          ; a CR?
	bne.s	write_with_lf_move              ; no
	move.b	#$a,0(a0,d4.l)                  ; yes: an LF after it
	subq.l	#1,d4
write_with_lf_move:
	move.b	d0,0(a0,d4.l)                   ; moved up
	dbra	d1,write_with_lf_spread
	sub.l	d2,d1
	bcc.s	write_with_lf_spread
	move.l	d3,d4
	movea.l	a3,a0                           ; the text
	move.l	(sp),d0                         ; the length
	add.l	d4,d0                           ; with the LFs
	subq.l	#2,d0                           ; less the closing CR LF
	bsr.w	write_text                      ; written
	movea.l	a4,a0
	move.l	(sp)+,d1
	move.l	d0,-(sp)                        ; the result
	subq.l	#1,d1
	move.l	#$10000,d2
write_with_lf_squeeze:
	move.b	(a4)+,d0                        ; a character
	cmp.b	#$a,d0                          ; an LF?
	beq.s	write_with_lf_squeeze           ; yes: dropped
	move.b	d0,(a0)+                        ; back
	dbra	d1,write_with_lf_squeeze
	sub.l	d2,d1
	bcc.s	write_with_lf_squeeze
	move.l	(sp)+,d0                        ; the result
	bmi.w	save_text_error                 ; failed
	bra.w	save_text_ok                    ; done

;------------------------------------------------------------------------------
; Save the text a3, d1 bytes, as fsel_name in the file selector folder with CR LF line ends.  d0 = 0 for the
; whole text: with Backups on, an old file becomes .BAK first.  Out: d0 = 0 when saved (no changes now),
; else the error, which is shown.
;------------------------------------------------------------------------------
save_text_file:	; from: key_block_save, editor_save_text
	movem.l	d0-d1/a3,-(sp)
	bsr.w	busy_mouse                      ; busy mouse
	not.b	d0                              ; the whole text?
	and.b	default_backups(pc),d0          ; and backups?
	beq.s	save_text_create                ; no
	lea	selector_name(a6),a0            ; the name
	lea	expanded_line(a6),a2            ; the backup name buffer
	bsr.w	make_path_in                    ; the full path
	lea	expanded_line(a6),a1
	bsr.w	open_file_read                  ; an old file?
	bne.s	save_text_rename                ; no
	move.w	a0,-(sp)                        ; yes
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose
	addq.l	#4,sp
	lea	expanded_line(a6),a0
	bsr.w	find_extension                  ; its extension
	movea.l	d1,a0
	bne.s	save_text_bak                   ; has one
	movea.l	a1,a0                           ; none: at the end
save_text_bak:
	move.b	#$2e,-$1(a0)                    ; '.'
	move.b	#$42,(a0)+                      ; "BAK"
	move.b	#$41,(a0)+
	move.b	#$4b,(a0)+
	clr.b	(a0)
	pea	expanded_line(a6)               ; the .BAK name
	move.w	#$41,-(sp)
	trap	#1                              ; Fdelete, Fdelete: the old .BAK
	addq.l	#6,sp
save_text_rename:
	lea	selector_name(a6),a0            ; the name
	bsr.w	make_full_path                  ; the full path
	pea	expanded_line(a6)               ; the .BAK name
	move.l	a0,-(sp)                        ; the file
	clr.w	-(sp)
	move.w	#$56,-(sp)
	trap	#1                              ; Frename, Frename: the old file to .BAK
	lea	$c(sp),sp
	tst.l	d0
save_text_create:
	lea	selector_name(a6),a0            ; the name
	bsr.w	make_full_path                  ; the full path
	clr.w	-(sp)                           ; normal file
	move.l	a0,-(sp)
	move.w	#$3c,-(sp)
	trap	#1                              ; Fcreate
	addq.l	#8,sp
	tst.l	d0                              ; made?
	bpl.s	save_text_open                  ; yes
	lea	$c(sp),sp                       ; no: drop the saved registers
	bsr.w	arrow_mouse                     ; arrow mouse
	bra.w	open_failed                     ; show the error
save_text_open:
	move.w	d0,text_file_handle(a6)         ; the handle
	movem.l	(sp)+,d0-d1/a3                  ; the text and its length
	movem.l	d5/a4,-(sp)
	movea.l	a3,a4                           ; the text
	move.l	d1,d5                           ; its length
	bsr.w	busy_mouse                      ; busy mouse
	tst.b	d0                              ; the whole text?
	bne.s	save_text_lines                 ; no
	bsr.w	write_with_lf                   ; yes: in one go when there is room
save_text_lines:
	tst.l	d5                              ; more?
	bls.s	save_text_ok                    ; no: done
	moveq	#0,d1
save_text_line_end:
	addq.l	#1,d1
	cmpi.b	#$d,-$1(a4,d1.l)                ; the end of the line?
	beq.s	save_text_line_write            ; yes
	cmp.l	d1,d5                           ; the end of the text?
	bne.s	save_text_line_end              ; no
save_text_line_write:
	movea.l	a4,a0                           ; the line
	move.l	d1,d0                           ; its length
	adda.l	d1,a4                           ; past it
	sub.l	d1,d5
	bsr.w	write_text                      ; written
	bmi.s	save_text_error                 ; failed
	moveq	#1,d0                           ; one byte
	lea	lf_byte(pc),a0                  ; an LF
	bsr.w	write_text                      ; written
	bpl.s	save_text_lines                 ; on
save_text_error:	; from: write_with_lf
	bsr.w	show_dos_error                  ; show the error
	movem.l	(sp)+,d5/a4
	bra.s	save_text_close
save_text_ok:	; from: write_with_lf
	movem.l	(sp)+,d5/a4
	moveq	#0,d0                           ; done
	sf	text_modified(a6)               ; no changes now
save_text_close:
	move.l	d0,-(sp)
	bsr.w	close_text_file                 ; close it
	bsr.w	arrow_mouse                     ; arrow mouse
	move.l	(sp)+,d0                        ; the result
	rts
	lea	$c(sp),sp                       ; not used: another way out of a save
	move.l	d0,-(sp)
	bsr.s	close_text_file                 ; close it
	movem.l	(sp)+,d0/d5-d6
	sf	text_modified(a6)               ; no changes now
	bsr.w	arrow_mouse                     ; arrow mouse
	moveq	#0,d0
	rts
lf_byte:
	dc.w	$0a0a                           ; an LF

;------------------------------------------------------------------------------
; Fclose text_file_handle.
;------------------------------------------------------------------------------
close_text_file:	; from: editor_load_file, cmd_insert_file, save_text_file
	move.w	text_file_handle(a6),-(sp)      ; the file
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; Show the GEMDOS error d0 with form_error (0 counts as -50).  Keeps d0.
;------------------------------------------------------------------------------
show_dos_error:                                 ; from: cmd_delete_file, cmd_monst, cmd_assemble, menu_run_other_drop,
                                                ;   radio_index, read_text_file, 2 more
	tst.w	d0                              ; an error code?
	bne.s	show_dos_error_code             ; yes
	moveq	#-50,d0                         ; no: -50
show_dos_error_code:
	move.l	d0,-(sp)
	neg.w	d0                              ; as a positive number
	move.w	d0,intin(a6)
	moveq	#53,d0                          ; form_error
	bsr.w	aes_call
	move.l	(sp)+,d0
	rts

;------------------------------------------------------------------------------
; Fwrite d0 bytes from a0 to text_file_handle.  Out: d0 = 1 when all written, -50 when short, the error
; (negative) when failed.
;------------------------------------------------------------------------------
write_text:	; from: write_with_lf, save_text_file
	move.l	d0,-(sp)                        ; the length
	move.l	a0,-(sp)                        ; the buffer
	move.l	d0,-(sp)
	move.w	text_file_handle(a6),-(sp)      ; the file
	move.w	#$40,-(sp)
	trap	#1                              ; Fwrite
	lea	$c(sp),sp
	move.l	(sp)+,d1                        ; the length
	tst.l	d0                              ; an error?
	bmi.s	write_text_done                 ; yes
	cmp.l	d0,d1                           ; all of it?
	bne.s	write_text_short                ; no
	moveq	#1,d0                           ; done
write_text_done:
	rts
write_text_short:
	moveq	#-50,d0                         ; -50
	rts

;------------------------------------------------------------------------------
; Draw the whole status line on the info line: its labels and then every number.
;------------------------------------------------------------------------------
draw_status_line:	; from: editor_command_event, gem_drop_messages, clear_shown_message, appl_find_name
	bsr.w	hide_mouse                      ; mouse off
	move.w	text_x(a6),status_x(a6)         ; from the left
	move.w	#$4,output_mode(a6)             ; output to the status line
	lea	status_template(pc),a1          ; the labels
	bsr.w	editor_print_counted
	clr.w	shown_column(a6)                ; column not shown
	clr.w	shown_line(a6)                  ; line not shown
	clr.l	shown_free(a6)                  ; free memory not shown
	st	shown_left_column(a6)           ; left column not shown
	bsr.w	show_mouse                      ; mouse on

;------------------------------------------------------------------------------
; Update the status line's numbers that changed: the line (at column 5), the column (at 15), the free bytes
; (at 25), and the horizontal slider for the left column.
;------------------------------------------------------------------------------
update_status_line:	; from: editor_loop, editor_key, line_edit, cmd_jump_error
	movem.l	d0-d4/a0-a2,-(sp)
	bsr.w	hide_mouse                      ; mouse off
	move.w	output_mode(a6),-(sp)
	move.w	#$4,output_mode(a6)             ; output to the status line
	move.w	d7,d4                           ; the cursor row
	addq.w	#1,d4
	add.w	top_line_number(a6),d4          ; the line number
	cmp.w	shown_line(a6),d4               ; as shown?
	beq.s	update_status_column            ; yes
	sf	sliders_stale(a6)
	moveq	#5,d1                           ; at column 5
	move.w	d4,shown_line(a6)
	bsr.s	status_number_at                ; shown
update_status_column:
	move.w	d6,d4                           ; the column
	addq.w	#1,d4
	cmp.w	shown_column(a6),d4             ; as shown?
	beq.s	update_status_free              ; yes
	moveq	#15,d1                          ; at column 15
	move.w	d4,shown_column(a6)
	bsr.s	status_number_at                ; shown
update_status_free:
	move.l	text_limit(a6),d4               ; the buffer's end
	sub.l	text_end(a6),d4                 ; less the text's end
	cmp.l	shown_free(a6),d4               ; as shown?
	beq.s	update_status_hslider           ; yes
	moveq	#25,d1                          ; column 25
	mulu.w	char_width(a6),d1
	add.w	text_x(a6),d1
	move.w	d1,status_x(a6)
	move.l	d4,shown_free(a6)
	move.l	d4,d1                           ; the free bytes
	moveq	#1,d2
	bsr.w	print_decimal_long              ; printed
	cmpi.l	#$186a0,shown_free(a6)          ; under 100000?
	bcc.s	update_status_hslider           ; no
	moveq	#32,d1                          ; a space over the old digits
	bsr.w	editor_put_char
	cmpi.l	#$2710,shown_free(a6)           ; under 10000?
	bcc.s	update_status_hslider           ; no
	moveq	#32,d1                          ; another space
	bsr.w	editor_put_char
update_status_hslider:
	move.w	left_column(a6),d0              ; the left column
	cmp.w	shown_left_column(a6),d0        ; as shown?
	beq.s	update_status_done              ; yes
	move.w	d0,shown_left_column(a6)
	bsr.s	set_hslider                     ; the horizontal slider
update_status_done:
	move.w	(sp)+,output_mode(a6)           ; the output mode back
	bsr.w	show_mouse                      ; mouse on
	movem.l	(sp)+,d0-d4/a0-a2
	rts

;------------------------------------------------------------------------------
; Print the number d4 in the status line at column d1: 5 digits with leading spaces, then a space.
; In: d1 column, d4 number (word).  Out: status_x moved past it.
;------------------------------------------------------------------------------
status_number_at:	; from: update_status_line
	mulu.w	char_width(a6),d1               ; the column in pixels
	add.w	text_x(a6),d1                   ; from the text's left edge
	move.w	d1,status_x(a6)                 ; where the status line output goes
	bra.w	status_number                   ; print d4 and a space

;------------------------------------------------------------------------------
; Set the window's horizontal slider from d0, the first column shown (0-255 maps to 1-1000).
;------------------------------------------------------------------------------
set_hslider:	; from: update_status_line
	mulu.w	#$3e7,d0                        ; scale to 999
	lsr.l	#8,d0                           ; over 256 columns
	addq.w	#1,d0                           ; 1 on
	cmp.w	#$3e9,d0                        ; past 1000?
	bcs.s	set_hslider_pos                 ; no
	move.w	#$3e8,d0                        ; at most 1000
set_hslider_pos:
	lea	intin(a6),a0                    ; wind_set's intin
	move.w	window_handle(a6),(a0)+         ; the editor window
	move.w	#$8,(a0)+                       ; WF_HSLIDE
	move.w	d0,(a0)                         ; the position
	moveq	#105,d0                         ; wind_set
	bra.w	aes_call                        ; set the slider

;------------------------------------------------------------------------------
; Alert: not enough room in the edit buffer to load the file.  Out: d1 the button.
;------------------------------------------------------------------------------
alert_no_room_to_load:	; from: editor_load_file
	moveq	#1,d1                           ; default button 1
	lea	alert_no_room(a6),a1            ; "There is not enough memory in the edit buffer..."
	bra.w	gem_alert                       ; form_alert

;------------------------------------------------------------------------------
; Show the message at a1 (length word in front) in the status line and ring the bell.
;------------------------------------------------------------------------------
message_beep:                                   ; from: show_end_of_file, editor_check_block, key_block_copy,
                                                ;   editor_alt_key, cmd_jump_error, editor_goto_line, 2 more
	bsr.s	message_show                    ; show it
	bra.w	editor_bell                     ; ring the bell

;------------------------------------------------------------------------------
; Show the message at a1 (length word in front) in the status line's message area.
; It stays until message_state says to clear it.  All registers kept but d0/a0/a1.
;------------------------------------------------------------------------------
message_show:	; from: clear_shown_message, message_beep
	movem.l	d1-d3/a2,-(sp)
	move.w	output_mode(a6),-(sp)           ; keep the output target
	move.l	a1,-(sp)                        ; keep the message
	bsr.s	message_area_clear              ; clear the message area, output to it
	bsr.w	hide_mouse                      ; hide the mouse
	movea.l	(sp)+,a1                        ; the message
	bsr.w	editor_print_counted            ; print it
	bsr.w	show_mouse                      ; show the mouse
	st	message_state(a6)               ; a message is showing
	move.w	(sp)+,output_mode(a6)           ; restore the output target
	movem.l	(sp)+,d1-d3/a2
	rts

;------------------------------------------------------------------------------
; Clear the message part of the status line (from column 32 to the right edge) and send the output
; there: status_x at its start, output_target 4.  Uses the clip rectangle of the whole window.
;------------------------------------------------------------------------------
message_area_clear:	; from: appl_find_name, message_show, message_area_prepare, message_replaced
	move.w	char_width(a6),d0               ; column 32
	mulu.w	#$20,d0                         ; in pixels
message_area_clear_at:	; from: message_area_prepare
	add.w	text_x(a6),d0                   ; from the text's left edge (d0 = 0: the whole line)
	move.w	d0,status_x(a6)                 ; the status output starts there
	bsr.w	hide_mouse                      ; hide the mouse
	moveq	#1,d0                           ; replace mode
	bsr.w	set_write_mode                  ; vswr_mode
	move.w	status_x(a6),ptsin(a6)          ; rectangle x1: the message start
	move.w	work_right(a6),d0               ; x2: the right edge
	add.w	char_width(a6),d0               ; and one more character
	move.w	d0,ptsin+4(a6)
	move.w	status_y(a6),d0                 ; the status line's baseline
	addq.w	#2,d0                           ; 2 below it
	move.w	d0,ptsin+6(a6)                  ; y2
	sub.w	char_height(a6),d0              ; up a character height
	move.w	d0,ptsin+2(a6)                  ; y1
	move.w	#$2,contrl_count(a6)            ; 2 points
	clr.w	contrl_intin_count(a6)          ; no intin
	moveq	#114,d0                         ; vr_recfl
	bsr.w	vdi_call                        ; fill it with the background
	bsr.w	clip_to_window                  ; clip to the window and its status line
	bsr.w	show_mouse                      ; show the mouse
	move.w	#$4,output_mode(a6)             ; output to the status line
	rts

;------------------------------------------------------------------------------
; Clear the status line for a message: on a wide screen just the message area; on a narrow one the
; whole line, and message_state is made positive so that the line is redrawn afterwards.
;------------------------------------------------------------------------------
message_area_prepare:	; from: cmd_jump_error
	st	message_state(a6)               ; a message is showing
	tst.b	narrow_screen(a6)               ; narrow screen?
	beq.s	message_area_clear              ; no: just the message area
	moveq	#0,d0                           ; yes: from column 0
	addq.b	#2,message_state(a6)            ; $ff + 2 = 1: redraw the status line later
	bra.s	message_area_clear_at           ; clear it all
	rts                                     ; never reached

;------------------------------------------------------------------------------
; Not called: wait for a key or a mouse click, then take the message off the status line.
;------------------------------------------------------------------------------
wait_key_or_click:
	movem.l	d0-d3/a0-a3,-(sp)
	bsr.s	flush_keyboard                  ; empty the keyboard first
	move.w	#$3,intin(a6)                   ; MU_KEYBD + MU_BUTTON
	move.w	#$1,intin1(a6)                  ; 1 click
	move.w	#$1,intin2(a6)                  ; of the left button
	move.w	#$1,intin3(a6)                  ; down
	moveq	#25,d0                          ; evnt_multi
	bsr.w	aes_call                        ; wait
	bsr.w	clear_shown_message             ; clear the message
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; Read and drop keys until none is waiting.
;------------------------------------------------------------------------------
flush_keyboard:	; from: wait_key_or_click
	move.w	#$ff,-(sp)                      ; Crawio($ff): read a key without waiting
	move.w	#$6,-(sp)
	trap	#1                              ; Crawio
	addq.l	#4,sp
	tst.b	d0                              ; got one?
	bne.s	flush_keyboard                  ; yes: again
	rts

;------------------------------------------------------------------------------
; Clear the window and draw every row from top_line on.  In: d6 the cursor column.
; Out: a4 = top_line, d7 = 0, the cursor on row 0 at column d6.  Changes d0-d5/a0/a1.
;------------------------------------------------------------------------------
redraw_text:                                    ; from: key_page_up, window_check_arrowed, editor_load_file,
                                                ;   editor_clear_text, replace_all, cmd_insert_file, 3 more
	bsr.w	clear_window_home               ; home the cursor and clear the text area
	bsr.w	hide_mouse                      ; hide the mouse
	move.w	d6,-(sp)                        ; keep the cursor column
	movea.l	top_line(a6),a4                 ; from the window's top line
	moveq	#0,d7                           ; row 0
redraw_text_line:
	bsr.w	editor_expand_line              ; expand the line's tabs into the line buffer (a0), d5 its length with
                                                ;   the CR
	subq.w	#1,d5                           ; without the CR
	sub.w	left_column(a6),d5              ; less the columns scrolled off to the left
	bcs.s	redraw_text_next                ; nothing left to show
	adda.w	left_column(a6),a0              ; the first character shown
	cmp.w	window_columns(a6),d5           ; wider than the window?
	bls.s	redraw_text_draw                ; no
	move.w	window_columns(a6),d5           ; yes: the window's width
	addq.w	#1,d5
redraw_text_draw:
	move.w	d5,contrl_intin_count(a6)       ; nintin: the characters
	subq.w	#1,d5
	bcs.s	redraw_text_next                ; none
	lea	intin(a6),a1                    ; one intin word each
	moveq	#0,d1
redraw_text_char:
	move.b	(a0)+,d1
	move.w	d1,(a1)+
	dbra	d5,redraw_text_char
	clr.w	(a1)                            ; end the string
	move.w	cursor_x(a6),ptsin(a6)          ; at the cursor's row start
	move.w	cursor_y(a6),ptsin+2(a6)        ; its baseline
	move.w	#$1,contrl_count(a6)            ; 1 point
	moveq	#8,d0                           ; v_gtext
	bsr.w	vdi_call                        ; draw the line
	tst.b	block_shown(a6)                 ; a block marked?
	beq.s	redraw_text_next                ; no
	bsr.w	block_highlight                 ; yes: show the part of it on this line
redraw_text_next:
	cmp.w	last_row(a6),d7                 ; the window's last row?
	beq.s	redraw_text_done                ; yes: done
	addq.w	#1,d7                           ; the next row
	moveq	#0,d0                           ; column 0
	bsr.w	editor_place_cursor_column      ; cursor to the row's start
	bsr.w	text_next_line                  ; the next line
	beq.s	redraw_text_line                ; there is one: draw it
redraw_text_done:
	movea.l	top_line(a6),a4                 ; back to the top line
	bsr.w	show_mouse                      ; show the mouse
	moveq	#0,d7                           ; row 0
	move.w	(sp)+,d6                        ; the cursor column
	bra.w	editor_place_cursor             ; place the cursor

;------------------------------------------------------------------------------
; Redraw the whole window text, keeping the cursor where it was (d6 column, d7 row, a4 line).
;------------------------------------------------------------------------------
redraw_window:	; from: key_block_start, show_cursor_line, cmd_assemble, redraw_under_dialog, redraw_and_loop
	movem.l	d6-d7/a4,-(sp)
	move.w	left_column(a6),d6              ; draw from the first column shown
	bsr.w	redraw_text                     ; redraw
	movem.l	(sp)+,d6-d7/a4
	bra.w	editor_cursor_visible           ; put the cursor back, scrolling sideways if need be

;------------------------------------------------------------------------------
; Ring the bell: Bconout(CON, 7).  All registers kept.
;------------------------------------------------------------------------------
editor_bell:	; from: message_beep
	movem.l	d0-d3/a0-a3,-(sp)
	move.w	#$7,-(sp)                       ; BEL
	move.w	#$2,-(sp)                       ; CON
	move.w	#$3,-(sp)
	trap	#13                             ; Bconout
	addq.l	#6,sp
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; Fill in the screen's MFDB for the scrolling blits: its address from Logbase, the physical screen
; address, the planes from vq_extnd and the standard-format flag.
;------------------------------------------------------------------------------
get_screen_info:	; from: gem_init
	move.w	#$3,-(sp)
	trap	#14                             ; Logbase
	move.l	d0,screen_mfdb(a6)              ; the MFDB's address
	move.w	#$2,-(sp)
	trap	#14                             ; Physbase
	move.l	d0,physical_screen(a6)          ; the screen shown
	addq.l	#4,sp
	clr.w	contrl_count(a6)                ; no points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	move.w	#$1,intin(a6)                   ; extended information
	moveq	#102,d0                         ; vq_extnd
	bsr.w	vdi_call
	move.w	intout4(a6),screen_planes(a6)   ; intout[4]: the planes
	move.w	#$1,screen_standard(a6)         ; standard format
	rts

;------------------------------------------------------------------------------
; Set up vro_cpyfm to copy the text area onto itself, screen to screen: both rectangles are
; text_rect, replace mode.  The caller then moves the edges.  Out: d0 the character height.
;------------------------------------------------------------------------------
blit_setup:                                     ; from: scroll_text_up, scroll_text_down, scroll_open_line,
                                                ;   scroll_close_line, scroll_text_right, scroll_text_left, 1 more
	movem.w	scroll_rect(a6),d0-d3           ; the text area
	movem.w	d0-d3,ptsin(a6)                 ; the source
	movem.w	d0-d3,ptsin+8(a6)               ; and the destination
	move.w	#$4,contrl_count(a6)            ; 4 points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	lea	screen_mfdb(a6),a0              ; the screen MFDB
	move.l	a0,contrl_source_mfdb(a6)       ; as the source
	move.l	a0,contrl_dest_mfdb(a6)         ; and the destination
	move.w	#$3,intin(a6)                   ; S_ONLY: replace
	move.w	char_height(a6),d0              ; the distance: one line
	rts

;------------------------------------------------------------------------------
; Clip the blit to the screen.  a0 and a1 point at the y2 of the two rectangles, a0's the lower one.
; Both x2 are cut at the screen's width and both y2 at the desktop's bottom.
; Out: carry clear when y2 was cut at the bottom (part of the window is off the screen).
;------------------------------------------------------------------------------
blit_clip:	; from: blit_up, blit_down
	moveq	#1,d0
	add.w	-$2(a0),d0                      ; x2 + 1
	sub.w	screen_width(a6),d0             ; past the screen's width?
	bcs.s	blit_clip_bottom                ; no
	sub.w	d0,-$2(a0)                      ; yes: cut both x2 back
	sub.w	d0,-$2(a1)
blit_clip_bottom:
	move.w	(a0),d0                         ; y2
	sub.w	desk_bottom(a6),d0              ; at or below the desktop's bottom?
	bcs.s	blit_clip_done                  ; no: carry set
	sub.w	d0,(a0)                         ; yes: cut both
	sub.w	d0,(a1)
	or.w	d0,d0                           ; carry clear
blit_clip_done:
	rts

;------------------------------------------------------------------------------
; Do the blit for a scroll up (the source lower): clip it, and when the window runs off the
; bottom of the screen ask for a full redraw by a pending Esc key.
;------------------------------------------------------------------------------
blit_up:	; from: scroll_text_up, scroll_close_line, editor_put_char
	lea	ptsin+6(a6),a0                  ; the source's y2
	lea	ptsin+14(a6),a1                 ; the destination's y2
	bsr.s	blit_clip                       ; clip
	bcs.s	blit_copy                       ; not cut: copy
	move.w	#$1b,held_key(a6)               ; cut: the lines from below cannot be copied, so Esc redraws later
	bra.s	blit_copy

;------------------------------------------------------------------------------
; Do the blit for a scroll down (the destination lower): clip it and copy.
;------------------------------------------------------------------------------
blit_down:	; from: scroll_text_down, scroll_text_right
	lea	ptsin+6(a6),a1                  ; the source's y2
	lea	ptsin+14(a6),a0                 ; the destination's y2
	bsr.s	blit_clip                       ; clip
blit_copy:	; from: blit_up
	move.w	ptsin+2(a6),d0                  ; the source's y1
	cmp.w	ptsin+6(a6),d0                  ; above its y2?
	bcc.s	blit_done                       ; no: nothing to copy
	moveq	#109,d0                         ; vro_cpyfm
	bsr.w	vdi_call                        ; copy
blit_done:
	rts

;------------------------------------------------------------------------------
; Scroll the text area up one line (the top line goes, the bottom row is left to be drawn).
;------------------------------------------------------------------------------
scroll_text_up:	; from: window_scroll_forward, key_return, appl_find_name
	bsr.w	hide_mouse                      ; hide the mouse
	bsr.w	blit_setup                      ; the blit of the text area
	add.w	d0,ptsin+2(a6)                  ; from the second row
	sub.w	d0,ptsin+14(a6)                 ; to one line shorter
	bsr.s	blit_up                         ; copy
scroll_show_mouse:	; from: scroll_text_down, scroll_close_line
	bra.w	show_mouse                      ; show the mouse

;------------------------------------------------------------------------------
; Make the line before a4 the window's top line and scroll the text down one line for it.
;------------------------------------------------------------------------------
scroll_to_previous_line:	; from: key_cursor_left, key_cursor_up, appl_find_name
	bsr.w	text_prev_line                  ; a4 to the previous line's start
	move.l	a4,top_line(a6)                 ; the new top line

;------------------------------------------------------------------------------
; Scroll the text area down one line (the top row is left to be drawn).
;------------------------------------------------------------------------------
scroll_text_down:	; from: key_undo
	bsr.w	hide_mouse                      ; hide the mouse
	bsr.w	blit_setup                      ; the blit of the text area
	add.w	d0,ptsin+10(a6)                 ; to one line lower
	sub.w	d0,ptsin+6(a6)                  ; from one line shorter
scroll_down_copy:	; from: scroll_open_line
	bsr.s	blit_down                       ; clip and copy
	bra.s	scroll_show_mouse               ; show the mouse

;------------------------------------------------------------------------------
; Open an empty row below the cursor's row: the rows below it move down one line.
;------------------------------------------------------------------------------
scroll_open_line:	; from: key_return, key_undo
	bsr.w	hide_mouse                      ; hide the mouse
	bsr.w	blit_setup                      ; the blit of the text area
	move.w	cursor_y(a6),d1                 ; the cursor's baseline
	add.w	char_descent(a6),d1             ; the next row's top
	move.w	d1,ptsin+2(a6)                  ; the source's y1
	add.w	d0,d1                           ; a line lower
	move.w	d1,ptsin+10(a6)                 ; the destination's y1
	sub.w	d0,ptsin+6(a6)                  ; one line shorter
	bra.s	scroll_down_copy                ; clip and copy

;------------------------------------------------------------------------------
; Close up the row below the cursor's row: the rows under it move up one line.
;------------------------------------------------------------------------------
scroll_close_line:	; from: editor_close_line_gap
	bsr.w	hide_mouse                      ; hide the mouse
	bsr.w	blit_setup                      ; the blit of the text area
	move.w	cursor_y(a6),d1                 ; the cursor's baseline
	add.w	char_descent(a6),d1             ; the next row's top
	move.w	d1,ptsin+10(a6)                 ; the destination's y1
	add.w	d0,d1                           ; a line lower
	move.w	d1,ptsin+2(a6)                  ; the source's y1
	sub.w	d0,ptsin+14(a6)                 ; one line shorter
	cmp.w	ptsin+6(a6),d1                  ; anything below it?
	bcc.s	scroll_show_mouse               ; no
	bsr.w	blit_up                         ; clip and copy
	bra.s	scroll_show_mouse               ; show the mouse

;------------------------------------------------------------------------------
; Scroll the text area right by d2 pixels (the text moves right, the left part is left to draw).
;------------------------------------------------------------------------------
scroll_text_right:	; from: editor_place_cursor_column
	move.w	d2,-(sp)                        ; keep the distance
	bsr.w	hide_mouse                      ; hide the mouse
	bsr.w	blit_setup                      ; the blit of the text area
	move.w	(sp)+,d2                        ; the distance
	sub.w	d2,ptsin+4(a6)                  ; the source d2 narrower
	add.w	d2,ptsin+8(a6)                  ; the destination d2 further right
scroll_sideways_copy:	; from: scroll_text_left
	bsr.w	blit_down                       ; clip and copy
	bra.w	show_mouse                      ; show the mouse

;------------------------------------------------------------------------------
; Scroll the text area left by d2 pixels (the text moves left, the right part is left to draw).
;------------------------------------------------------------------------------
scroll_text_left:	; from: editor_place_cursor_column
	move.w	d2,-(sp)                        ; keep the distance
	bsr.w	hide_mouse                      ; hide the mouse
	bsr.w	blit_setup                      ; the blit of the text area
	move.w	(sp)+,d2                        ; the distance
	add.w	d2,ptsin(a6)                    ; the source from d2 in
	sub.w	d2,ptsin+12(a6)                 ; the destination d2 narrower
	bra.s	scroll_sideways_copy            ; copy

;------------------------------------------------------------------------------
; Redraw the whole window and go back to the editor's main loop.
;------------------------------------------------------------------------------
redraw_and_loop:	; from: editor_key
	bsr.w	clip_to_window                  ; clip to the window
	bsr.w	redraw_window                   ; redraw it
	bra.w	editor_loop                     ; the main loop

;------------------------------------------------------------------------------
; Redraw the cursor's row from the line at a4: its text, then clear the rest of the row and show any
; block on it.  a3 is kept.
;------------------------------------------------------------------------------
redraw_cursor_line:                             ; from: key_cursor_left, key_cursor_up, window_scroll_forward,
                                                ;   editor_close_line_gap, key_delete_to_end, line_edit, 4 more
	bsr.w	hide_mouse                      ; hide the mouse
	move.w	text_x(a6),ptsin(a6)            ; at the row's start
	move.w	cursor_y(a6),ptsin+2(a6)        ; the cursor's baseline
	bsr.w	editor_expand_line              ; expand the line's tabs, d5 its length with the CR
	subq.w	#1,d5                           ; without the CR
	sub.w	left_column(a6),d5              ; less the columns scrolled off
	bcc.s	redraw_line_skip                ; some left
	moveq	#0,d5                           ; none: draw nothing
redraw_line_skip:
	adda.w	left_column(a6),a0              ; the first character shown
	cmp.w	window_columns(a6),d5           ; wider than the window?
	bls.s	redraw_line_build               ; no
	move.w	window_columns(a6),d5           ; yes: the window's width
	addq.w	#1,d5
redraw_line_build:
	lea	intin(a6),a1                    ; one intin word per character
	moveq	#0,d1
	moveq	#0,d2
	move.w	d5,d0                           ; the count
	move.w	ptsin(a6),d3                    ; x after the text
	subq.w	#1,d0
	bcs.s	redraw_line_rest                ; none
redraw_line_char:
	move.b	(a0)+,d1
	move.w	d1,(a1)+
	add.w	char_width(a6),d3               ; one character on
	dbra	d0,redraw_line_char
	move.w	#$1,contrl_count(a6)            ; 1 point
	move.w	d5,contrl_intin_count(a6)       ; the characters
	move.w	d3,-(sp)                        ; keep the end x
	moveq	#8,d0                           ; v_gtext
	bsr.w	vdi_call                        ; draw it
	move.w	(sp)+,d3
redraw_line_rest:
	move.w	d3,d0                           ; rectangle x1: where the text ended
	move.w	work_right(a6),d2               ; x2: the right edge
	cmp.w	d0,d2                           ; any room left?
	bls.s	redraw_line_block               ; no
	move.w	cursor_y(a6),d3                 ; the cursor's baseline
	add.w	char_descent(a6),d3             ; the next row's top
	move.w	d3,d1
	sub.w	char_height(a6),d1              ; y1: this row's top
	subq.w	#1,d3                           ; y2: the row's bottom
	movem.w	d0-d3,ptsin(a6)
	move.w	#$2,contrl_count(a6)            ; 2 points
	clr.w	contrl_intin_count(a6)          ; no intin
	moveq	#114,d0                         ; vr_recfl
	bsr.w	vdi_call                        ; clear the rest of the row
redraw_line_block:
	tst.b	block_shown(a6)                 ; a block marked?
	beq.w	show_mouse                      ; no: show the mouse and return
	move.l	a3,-(sp)                        ; keep a3
	bsr.s	block_highlight                 ; show the block's part on this line
	movea.l	(sp)+,a3
	bra.w	show_mouse                      ; show the mouse
block_highlight_none:	; from: block_highlight
	rts

;------------------------------------------------------------------------------
; Show in reverse (an XOR fill) the part of the line at a4 that lies inside the marked block
; (block_start to block_end), on the cursor's row.  Changes a3, d0-d3.
;------------------------------------------------------------------------------
block_highlight:	; from: redraw_text, redraw_cursor_line
	movea.l	a4,a3                           ; from the line's start
block_highlight_find_end:
	cmpa.l	text_end(a6),a3                 ; at the text's end?
	bcc.s	block_highlight_text_end        ; yes
	cmpi.b	#$d,(a3)+                       ; the line's CR?
	bne.s	block_highlight_find_end        ; no
	bra.s	block_highlight_check           ; a3 just past the line
block_highlight_text_end:
	movea.l	text_end(a6),a3                 ; the line ends with the text
block_highlight_check:
	cmpa.l	block_end(a6),a4                ; the line starts after the block?
	bgt.s	block_highlight_none            ; yes: nothing
	cmpa.l	block_end(a6),a3                ; the block ends inside this line?
	bgt.s	block_highlight_ends_here       ; yes
	cmpa.l	block_start(a6),a3              ; the block starts after the line?
	ble.s	block_highlight_none            ; yes: nothing
	cmpa.l	block_start(a6),a4              ; the block starts in this line?
	ble.s	block_highlight_from_start      ; yes
	bra.s	block_highlight_whole           ; no: the line lies all inside it
block_highlight_ends_here:
	cmpa.l	block_start(a6),a4              ; from the block's start (column 0 when before the line)
	ble.s	block_highlight_from_start
	bra.s	block_highlight_from_start
block_highlight_whole:
	movea.l	block_end(a6),a1                ; to the block's end, stopped at the line's end
	bsr.s	column_of_address               ; its column
	move.w	d3,d2                           ; the end column
	moveq	#0,d0                           ; from column 0
	bra.s	block_highlight_columns
block_highlight_from_start:
	movea.l	block_start(a6),a1              ; the block's start
	bsr.s	column_of_address               ; its column (0 when before the line)
	move.w	d3,d0                           ; the start column
	movea.l	block_end(a6),a1                ; the block's end
	bsr.s	column_of_address               ; its column (the line's length when past it)
	move.w	d3,d2                           ; the end column
	bra.s	block_highlight_columns

;------------------------------------------------------------------------------
; The column of address a1 on the line at a4, with tabs expanded; a1 at or before a4 gives 0 and
; a1 past the line's CR gives the line's length.  Out: d3 the column.
;------------------------------------------------------------------------------
column_of_address:	; from: block_highlight
	moveq	#0,d3                           ; column 0
	cmpa.l	a4,a1                           ; before the line?
	ble.s	column_of_address_done          ; yes: 0
	movea.l	a4,a0                           ; from the line's start
column_of_address_loop:
	move.b	(a0)+,d1                        ; a character
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	column_of_address_done          ; yes: stop
	cmp.b	#$9,d1                          ; a tab?
	bne.s	column_of_address_char          ; no
	swap	d3                              ; yes: to the next tab stop
	clr.w	d3
	swap	d3
	divu.w	tab_size(a6),d3
	addq.w	#1,d3
	mulu.w	tab_size(a6),d3
	bra.s	column_of_address_next
column_of_address_char:
	addq.w	#1,d3                           ; one column
column_of_address_next:
	cmpa.l	a0,a1                           ; at a1?
	bne.s	column_of_address_loop          ; no
column_of_address_done:	; from: column_to_screen
	rts

;------------------------------------------------------------------------------
; Turn the column d0 into a row position on the screen: less the first column shown, at least 0 and
; at most one past the window's width.
;------------------------------------------------------------------------------
column_to_screen:
	sub.w	left_column(a6),d0              ; less the columns scrolled off
	bcc.s	column_to_screen_clamp          ; still on the screen
	moveq	#0,d0                           ; off to the left: 0
	rts
column_to_screen_clamp:
	cmp.w	window_columns(a6),d0           ; past the window's width?
	bls.s	column_to_screen_done           ; no
	move.w	window_columns(a6),d0           ; yes: just past it
	addq.w	#1,d0
column_to_screen_done:
	rts
block_highlight_columns:	; from: block_highlight
	exg	d0,d2                           ; the end column on the screen
	bsr.s	column_to_screen
	exg	d0,d2
	bsr.s	column_to_screen                ; the start column on the screen
	cmp.w	d0,d2                           ; nothing between them?
	beq.s	column_of_address_done          ; yes: done
	movem.w	d0/d2,-(sp)
	moveq	#3,d0                           ; XOR mode
	bsr.w	set_write_mode                  ; vswr_mode
	movem.w	(sp)+,d0/d2
	mulu.w	char_width(a6),d0               ; the start in pixels
	mulu.w	char_width(a6),d2               ; the end in pixels
	add.w	text_x(a6),d0                   ; from the text's left edge
	add.w	text_x(a6),d2
	move.w	cursor_y(a6),d3                 ; the cursor's baseline
	add.w	char_descent(a6),d3             ; the next row's top
	move.w	d3,d1
	sub.w	char_height(a6),d1              ; y1: this row's top
	subq.w	#1,d3                           ; y2: the row's bottom
	subq.w	#1,d2                           ; x2: the end's last pixel
	movem.w	d0-d3,ptsin(a6)
	move.w	#$2,contrl_count(a6)            ; 2 points
	clr.w	contrl_intin_count(a6)          ; no intin
	moveq	#114,d0                         ; vr_recfl
	bsr.w	vdi_call                        ; invert the block's part
	moveq	#1,d0                           ; back to replace mode
	bra.w	set_write_mode                  ; vswr_mode

;------------------------------------------------------------------------------
; Show "Replaced <d4>" in the status line after a replace-all.  In: d4 the count.
;------------------------------------------------------------------------------
message_replaced:	; from: replace_all
	move.w	output_mode(a6),-(sp)           ; keep the output target
	bsr.w	message_area_clear              ; clear the message area, output to it
	bsr.w	hide_mouse                      ; hide the mouse
	lea	msg_replaced(pc),a1             ; "Replaced"
	bsr.w	editor_print_counted            ; print it
	bsr.w	print_number_spaced             ; then the count with a space either side
	move.w	(sp)+,output_mode(a6)           ; restore the output target
	bsr.w	show_mouse                      ; show the mouse
	st	message_state(a6)               ; a message is showing
	rts
msg_replaced:
	dc.w	$0008                           ; its length
	dc.b	'Replaced'                      ; the message

;------------------------------------------------------------------------------
; Print the lines from a4 to a3 (the block) on the printer, after asking the user to get it ready.
;------------------------------------------------------------------------------
print_block:	; from: cmd_print_block
	move.l	a3,d5                           ; keep the block's end
	lea	alert_print_block(a6),a1        ; "Print Block - Ensure printer is connected and on line"
	moveq	#1,d1                           ; default button 1
	bsr.w	gem_alert                       ; form_alert
	cmp.w	#$1,d1                          ; OK?
	bne.s	print_block_exit                ; no: done
	move.w	#$8,output_mode(a6)             ; output to the printer
	bsr.w	busy_mouse                      ; busy mouse
	movea.l	d5,a3                           ; the block's end
print_block_line:
	cmpa.l	a4,a3                           ; past the block's end?
	bcs.s	print_block_exit                ; yes: done
	bsr.w	editor_expand_line              ; expand the line's tabs, d5 its length with the CR
	subq.w	#1,d5
print_block_char:
	move.b	(a0)+,d1                        ; a character
	bsr.w	editor_put_char                 ; print it (a CR prints CR LF)
	dbra	d5,print_block_char
	bsr.w	text_next_line                  ; the next line
	beq.s	print_block_line                ; there is one
print_block_exit:
	bsr.w	arrow_mouse                     ; arrow mouse
	move.w	#$0,output_mode(a6)             ; output to the window again
	rts

;------------------------------------------------------------------------------
; Allocate the edit buffer of buffer_size bytes and start an empty text in it; with no memory for
; it say so and quit.
;------------------------------------------------------------------------------
alloc_edit_buffer:	; from: aes_call, alloc_edit_buffer_smaller
	move.l	text_buffer_size(a6),d0         ; the size wanted
	bsr.w	malloc_leave_free               ; Malloc it, leaving 4000 bytes free
	beq.w	quit_no_memory                  ; none: quit
	bne.s	alloc_edit_buffer_got           ; got it

;------------------------------------------------------------------------------
; Never reached (both branches above leave): try 4K less, down to 4K.
;------------------------------------------------------------------------------
alloc_edit_buffer_smaller:
	lea	text_buffer_size(a6),a0
	subi.l	#$1000,(a0)                     ; 4K less
	bcs.w	quit_no_memory                  ; none left: quit
	cmpi.l	#$1000,(a0)                     ; below 4K?
	bcs.w	quit_no_memory                  ; yes: quit
	bra.s	alloc_edit_buffer               ; try again
alloc_edit_buffer_got:	; from: alloc_edit_buffer
	move.l	d0,text_start(a6)               ; the buffer

;------------------------------------------------------------------------------
; Empty the edit buffer: the text is one CR, no block marks.
;------------------------------------------------------------------------------
clear_text:	; from: editor_load_file, editor_clear_text
	movea.l	text_start(a6),a0               ; the buffer
	move.b	#$d,(a0)                        ; a single CR
	move.l	a0,text_end(a6)                 ; the text's end
	adda.l	text_buffer_size(a6),a0
	lea	-$14(a0),a0                     ; 20 bytes short of the buffer's end
	move.l	a0,text_limit(a6)               ; the room limit
	clr.l	block_start(a6)                 ; no block start
	clr.l	block_end(a6)                   ; no block end
	st	text_touched(a6)                ; new text
	rts

;------------------------------------------------------------------------------
; Copy the block (a3, d1 bytes) into a new memory block for pasting later, freeing the old copy.
; Out: Z set to go ahead (copied, or no memory and the user chose Delete anyway), Z clear for Cancel.
;------------------------------------------------------------------------------
remember_block:	; from: key_block_delete, key_block_remember
	move.l	d1,-(sp)                        ; keep the length
	tst.l	block_copy(a6)                  ; an old copy?
	beq.s	remember_block_alloc            ; no
	movea.l	block_copy(a6),a0               ; yes: free it
	bsr.w	dos_mfree                       ; Mfree
	clr.l	block_copy(a6)
remember_block_alloc:
	move.l	(sp),d0                         ; the length
	beq.s	remember_block_done             ; empty: Z set
	bsr.w	malloc_leave_free               ; Malloc it
	bne.s	remember_block_copy             ; got it
	lea	alert_block_memory(a6),a1       ; "There is not enough memory to remember the block" [Delete|Cancel]
	moveq	#2,d1                           ; default button 2
	bsr.w	gem_alert                       ; form_alert
	subq.w	#1,d1                           ; Z set for Delete
remember_block_done:
	movem.l	(sp)+,d1                        ; the length back (flags kept)
	rts
remember_block_copy:
	move.l	a0,block_copy(a6)               ; the copy
	move.l	(sp),d1
	move.l	d1,remembered_length(a6)        ; its length
	movea.l	a3,a1                           ; from the block
remember_block_loop:
	move.b	(a1)+,(a0)+                     ; copy it
	subq.l	#1,d1
	bne.s	remember_block_loop
	bra.s	remember_block_done             ; Z set

;------------------------------------------------------------------------------
; Put the cursor on row 0, column 0 of the window and clear the text area.  d6/d7 kept.
;------------------------------------------------------------------------------
clear_window_home:	; from: redraw_text, quit_editor
	movem.w	d6-d7,-(sp)
	moveq	#0,d0                           ; column 0
	moveq	#0,d7                           ; row 0
	bsr.w	editor_place_cursor_column      ; cursor there
	movem.w	(sp)+,d6-d7
	bsr.s	clear_text_area                 ; clear the text area
	rts

;------------------------------------------------------------------------------
; Clear the window's work area to the background colour (solid fill, colour 0).
;------------------------------------------------------------------------------
clear_text_area:	; from: gem_init, clear_window_home
	bsr.w	hide_mouse                      ; hide the mouse
	clr.w	contrl_count(a6)                ; no points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	move.w	#$1,intin(a6)                   ; solid
	moveq	#23,d0                          ; vsf_interior
	bsr.w	vdi_call
	clr.w	contrl_count(a6)                ; no points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	clr.w	intin(a6)                       ; colour 0
	moveq	#25,d0                          ; vsf_color
	bsr.w	vdi_call_handle_set
	move.w	#$2,contrl_count(a6)            ; 2 points
	clr.w	contrl_intin_count(a6)          ; no intin
	move.l	work_area(a6),ptsin(a6)         ; the work area's x1,y1
	move.l	work_right(a6),ptsin+4(a6)      ; and x2,y2
	moveq	#114,d0                         ; vr_recfl
	bsr.w	vdi_call                        ; clear it
	bra.w	show_mouse                      ; show the mouse

;------------------------------------------------------------------------------
; Set the VDI clip rectangle to the window's work area and the status line above it.  All kept.
;------------------------------------------------------------------------------
clip_to_window:                                 ; from: window_sized, prepare_gem_program, redraw_under_dialog,
                                                ;   appl_find_name, editor_place_cursor_column, message_area_clear, 1
                                                ;   more
	movem.l	d0-d3/a0-a3,-(sp)
	movem.w	work_area(a6),d0-d3             ; the work area
	sub.w	char_height(a6),d1              ; up a character height
	subq.w	#2,d1                           ; and 2 more: the status line
	movem.w	d0-d3,ptsin(a6)                 ; the rectangle
	st	intin(a6)                       ; clipping on
	move.w	#$2,contrl_count(a6)            ; 2 points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	move.w	vdi_handle(a6),contrl_handle(a6) ; the VDI handle
	move.w	#$81,d0                         ; vs_clip
	bsr.w	vdi_call_handle_set
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; Output the character d1 to output_target: 0 the window at the cursor (wrapping at the right edge and
; scrolling at the bottom), 4 the status line, 8 the printer, negative the memory at a5.
; A CR goes to the next row, a backspace moves back.  All registers kept (a5 moves for memory).
;------------------------------------------------------------------------------
editor_put_char:                                ; from: cmd_jump_error, status_number, print_number_spaced,
                                                ;   print_decimal_word, print_decimal_long, editor_print_counted, 2 more
	movem.l	d0-d3/a0-a4,-(sp)
	move.w	output_mode(a6),d0              ; where to?
	bmi.w	put_char_memory                 ; memory
	cmp.w	#$8,d0                          ; the printer?
	beq.w	put_char_printer                ; yes
	cmp.w	#$0,d0                          ; the window?
	bne.s	put_char_draw                   ; no: the status line
	move.w	cursor_x(a6),d0                 ; the cursor's x
	add.w	char_width(a6),d0               ; one character on
	cmp.w	work_right(a6),d0               ; past the right edge?
	bls.s	put_char_check_bottom           ; no
	bsr.w	next_text_line                  ; yes: the next row
put_char_check_bottom:
	move.w	cursor_y(a6),d0                 ; the cursor's y
	cmp.w	text_bottom(a6),d0              ; below the text area?
	bls.s	put_char_draw                   ; no
	move.w	d1,-(sp)                        ; keep the character
	bsr.w	blit_setup                      ; the blit of the text area
	add.w	d0,ptsin+2(a6)                  ; scroll up: from the second row
	sub.w	d0,ptsin+14(a6)                 ; one line shorter
	sub.w	d0,cursor_y(a6)                 ; the cursor up a line
	bsr.w	blit_up                         ; copy
	bsr.s	clear_bottom_line               ; clear the bottom row
	move.w	(sp)+,d1
	bra.s	put_char_draw

;------------------------------------------------------------------------------
; Clear the bottom row of the text area (x1/x2 already in ptsin from blit_setup).
;------------------------------------------------------------------------------
clear_bottom_line:	; from: editor_close_line_gap, editor_put_char
	move.w	text_bottom(a6),d0              ; the text area's bottom
	addq.w	#1,d0                           ; and 1
	move.w	d0,ptsin+6(a6)                  ; y2
	sub.w	char_height(a6),d0              ; up a character height
	move.w	d0,ptsin+2(a6)                  ; y1
	move.l	#$20000,contrl_count(a6)        ; 2 points, no intin
	moveq	#114,d0                         ; vr_recfl
	bsr.w	vdi_call                        ; clear it
	rts
put_char_draw:	; from: editor_put_char
	cmp.b	#$d,d1                          ; a CR?
	beq.s	put_char_newline                ; yes: the next row
	move.w	output_mode(a6),d0              ; the target
	lea	0(a6,d0.w),a4                   ; a4 + $1c10/$1c12 = the window's cursor or the status line's position
	move.w	#$1,contrl_count(a6)            ; 1 point
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	andi.w	#$ff,d1                         ; the character
	move.w	d1,intin(a6)
	clr.w	intin1(a6)                      ; ended
	cmp.b	#$8,d1                          ; a backspace?
	bne.s	put_char_text                   ; no
	move.w	char_width(a6),d0               ; yes: back one character
	sub.w	d0,$1c10(a4)
	bra.s	put_char_done
put_char_text:
	move.w	$1c10(a4),ptsin(a6)             ; at the position
	move.w	$1c12(a4),ptsin+2(a6)
	moveq	#8,d0                           ; v_gtext
	bsr.w	vdi_call                        ; draw the character
	move.w	char_width(a6),d0               ; one character on
	add.w	d0,$1c10(a4)
put_char_done:
	movem.l	(sp)+,d0-d3/a0-a4
	rts
put_char_memory:	; from: editor_put_char
	move.b	d1,(a5)+                        ; store it at a5
	bra.s	put_char_done
put_char_newline:
	bsr.s	next_text_line                  ; the next row
	bra.s	put_char_done

;------------------------------------------------------------------------------
; Move the window's cursor to the start of the next row (no scrolling).
;------------------------------------------------------------------------------
next_text_line:	; from: editor_put_char, clear_bottom_line
	move.w	char_height(a6),d0              ; a character height
	add.w	d0,cursor_y(a6)                 ; down
	move.w	text_x(a6),cursor_x(a6)         ; the left edge
	rts
put_char_printer:	; from: editor_put_char
	andi.w	#$ff,d1                         ; the character
	bsr.s	editor_printer_out              ; print it
	cmp.b	#$d,d1                          ; a CR?
	bne.s	put_char_printer_done           ; no
	moveq	#10,d1                          ; yes: a LF after it
	bsr.s	editor_printer_out
put_char_printer_done:
	movem.l	(sp)+,d0-d3/a0-a4
	rts

;------------------------------------------------------------------------------
; Send d1 to the printer port Setprt chose: GEMDOS 5 Cprnout, or 4 Cauxout for a serial printer.
;------------------------------------------------------------------------------
editor_printer_out:	; from: next_text_line
	move.w	d1,-(sp)                        ; the character
	move.w	#$ffff,-(sp)                    ; -1: read the printer configuration
	move.w	#$21,-(sp)
	trap	#14                             ; Setprt
	addq.l	#4,sp
	moveq	#5,d1                           ; Cprnout
	btst	#$4,d0                          ; serial printer?
	beq.s	printer_out_port                ; no
	moveq	#4,d1                           ; yes: Cauxout
printer_out_port:
	move.w	d1,-(sp)
	trap	#1                              ; Cauxout, Cprnout or Cauxout
	move.w	2(sp),d1                        ; d1 back
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; Draw or take off the text cursor: an XOR block over the character cell at the cursor.
;------------------------------------------------------------------------------
toggle_cursor:	; from: get_event
	bsr.w	hide_mouse                      ; hide the mouse
	moveq	#3,d0                           ; XOR mode
	bsr.s	set_write_mode                  ; vswr_mode
	move.w	#$2,contrl_count(a6)            ; 2 points
	clr.w	contrl_intin_count(a6)          ; no intin
	move.w	cursor_x(a6),d0                 ; the cursor's x
	move.w	d0,ptsin(a6)                    ; x1
	add.w	char_width(a6),d0               ; one character wide
	subq.w	#1,d0
	move.w	d0,ptsin+4(a6)                  ; x2
	move.w	cursor_y(a6),d0                 ; the cursor's baseline
	add.w	char_descent(a6),d0             ; the next row's top
	move.w	d0,ptsin+6(a6)                  ; y2
	sub.w	char_height(a6),d0              ; up a character height
	move.w	d0,ptsin+2(a6)                  ; y1
	subq.w	#1,ptsin+6(a6)                  ; less 1: the row's bottom
	moveq	#114,d0                         ; vr_recfl
	bsr.w	vdi_call                        ; invert the cell
	moveq	#1,d0                           ; replace mode
	bsr.s	set_write_mode                  ; vswr_mode
	bra.s	show_mouse                      ; show the mouse

;------------------------------------------------------------------------------
; vswr_mode(d0): 1 replace, 3 XOR.
;------------------------------------------------------------------------------
set_write_mode:	; from: message_area_clear, column_to_screen, toggle_cursor
	clr.w	contrl_count(a6)                ; no points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	move.w	d0,intin(a6)                    ; the mode
	moveq	#32,d0                          ; vswr_mode
	bsr.w	vdi_call
	rts

;------------------------------------------------------------------------------
; Show the mouse however many times it was hidden: v_show_c with reset 0.
;------------------------------------------------------------------------------
show_mouse_forced:	; from: restore_tos_screen, restore_gem_program
	clr.w	intin(a6)                       ; reset 0
	bra.s	show_mouse_count                ; v_show_c

;------------------------------------------------------------------------------
; Hide the mouse: v_hide_c.  All registers kept.
;------------------------------------------------------------------------------
hide_mouse:                                     ; from: cmd_jump_error, draw_status_line, update_status_line,
                                                ;   message_show, message_area_clear, redraw_text, 10 more
	movem.l	d0-d3/a0-a3,-(sp)
	clr.w	contrl_count(a6)                ; no points
	clr.w	contrl_intin_count(a6)          ; no intin
	moveq	#123,d0                         ; v_hide_c
	bsr.w	vdi_call
mouse_call_done:	; from: show_mouse
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; Undo one hide_mouse: v_show_c with reset 1.  All registers kept.
;------------------------------------------------------------------------------
show_mouse:                                     ; from: cmd_jump_error, draw_status_line, update_status_line,
                                                ;   message_show, message_area_clear, redraw_text, 6 more
	move.w	#$1,intin(a6)                   ; reset 1: count the hides
show_mouse_count:	; from: show_mouse_forced
	movem.l	d0-d3/a0-a3,-(sp)
	clr.w	contrl_count(a6)                ; no points
	move.w	#$1,contrl_intin_count(a6)      ; 1 intin word
	moveq	#122,d0                         ; v_show_c
	bsr.w	vdi_call
	bra.s	mouse_call_done

;------------------------------------------------------------------------------
; Mouse form the busy bee (graf_mouse 2).  All registers kept.
;------------------------------------------------------------------------------
busy_mouse:	; from: cmd_monst, editor_init, cmd_run, save_preferences, read_text_file, save_text_file, 2 more
	movem.l	d0-d3/a0-a3,-(sp)
	moveq	#2,d0                           ; BUSYBEE
set_mouse_form:	; from: arrow_mouse
	move.w	d0,intin(a6)                    ; the form
	moveq	#78,d0                          ; graf_mouse
	bsr.w	aes_call
	movem.l	(sp)+,d0-d3/a0-a3
	rts

;------------------------------------------------------------------------------
; Mouse form the arrow (graf_mouse 0).  All registers kept.
;------------------------------------------------------------------------------
arrow_mouse:	; from: cmd_monst, editor_init, restore_gem_program, radio_index, read_text_file, save_text_file, 2 more
	movem.l	d0-d3/a0-a3,-(sp)
	moveq	#0,d0                           ; ARROW
	bra.s	set_mouse_form
msg_blank:	; from: clear_shown_message
	dc.w	$0002,$2020                     ; a message of 2 spaces: clears the message area

;------------------------------------------------------------------------------
; wind_get(d1 handle, d0 field); the values come back in intout+2 on.
;------------------------------------------------------------------------------
window_get:	; from: window_check_fulled, window_on_top, appl_find_name
	move.w	d0,intin1(a6)                   ; the field
	move.w	d1,intin(a6)                    ; the handle
	moveq	#104,d0                         ; wind_get
	bsr.w	aes_call
	rts

;------------------------------------------------------------------------------
; Not enough memory: say so and quit the editor.
;------------------------------------------------------------------------------
quit_no_memory:	; from: aes_call, menu_preferences, alloc_edit_buffer, alloc_edit_buffer_smaller
	lea	alert_no_memory(a6),a1          ; "There is insufficient memory for the program's requirements" [ Quit ]
	moveq	#1,d1                           ; default button 1
	bsr.w	gem_alert                       ; form_alert

;------------------------------------------------------------------------------
; Quit: close and delete the window, free the text buffer, close the workstation, take the menu
; bar down, appl_exit and Pterm(0).
;------------------------------------------------------------------------------
quit_editor:	; from: aes_call, cmd_quit
	move.w	#$0,output_mode(a6)             ; output to the window
	bsr.w	clear_window_home               ; clear it
	move.w	window_handle(a6),intin(a6)     ; the window
	moveq	#102,d0                         ; wind_close
	bsr.w	aes_call
	moveq	#103,d0                         ; wind_delete
	bsr.w	aes_call
	clr.w	intin(a6)                       ; END_UPDATE
	moveq	#107,d0                         ; wind_update
	bsr.w	aes_call
	move.l	text_start(a6),d0               ; the text buffer
	bsr.s	free_if_set                     ; free it
	clr.l	contrl_count(a6)
	moveq	#101,d0                         ; v_clsvwk
	bsr.w	vdi_call                        ; close the workstation
	lea	menu_tree,a0                    ; the menu tree
	move.w	#$0,intin(a6)                   ; 0: take the bar down
	move.l	a0,ptsin(a6)
	moveq	#30,d0                          ; menu_bar
	bsr.w	aes_call
	moveq	#19,d0                          ; appl_exit
	bsr.w	aes_call
editor_terminate:	; from: no_window_quit
	clr.w	-(sp)                           ; return code 0
	move.w	#$4c,-(sp)
	trap	#1                              ; Pterm

;------------------------------------------------------------------------------
; Mfree the block at d0 unless it is 0 (flags from the caller's move).
;------------------------------------------------------------------------------
free_if_set:	; from: quit_editor
	beq.s	free_if_set_done                ; none
	move.l	d0,-(sp)
	move.w	#$49,-(sp)
	trap	#1                              ; Mfree
	addq.l	#6,sp
free_if_set_done:
	rts

;------------------------------------------------------------------------------
; Show the editor's menu bar and remember its tree in menu_tree_address.
;------------------------------------------------------------------------------
show_menu_bar:	; from: gem_init
	lea	menu_tree-data_base(a6),a0      ; the menu tree
	move.w	#$1,intin(a6)                   ; 1: show it
	move.l	a0,ptsin(a6)
	move.l	a0,menu_tree_address(a6)        ; remembered
	moveq	#30,d0                          ; menu_bar
	bsr.w	aes_call
	rts

;------------------------------------------------------------------------------
; File selector titled "Load a file".  Out: d0 0 (Z) for OK, -1 for Cancel.
;------------------------------------------------------------------------------
select_load_file:	; from: cmd_load
	lea	title_load_file(a6),a0          ; the title
	bra.s	file_selector

;------------------------------------------------------------------------------
; File selector titled "Insert a file".
;------------------------------------------------------------------------------
select_insert_file:	; from: cmd_insert_file
	lea	title_insert_file(a6),a0        ; the title
	bra.s	file_selector

;------------------------------------------------------------------------------
; File selector titled "Save a file".
;------------------------------------------------------------------------------
select_save_file:	; from: cmd_save_as
	lea	title_save_file(a6),a0          ; the title
	bra.s	file_selector

;------------------------------------------------------------------------------
; File selector titled "Save a block".
;------------------------------------------------------------------------------
select_save_block:	; from: key_block_save
	lea	title_save_block(a6),a0         ; the title
	nop

;------------------------------------------------------------------------------
; The file selector with a title: the title box (object 1's text = a0) is drawn centred, then
; fsel_input on selector_path and selector_file.  Out: d0 0 (Z set) for OK, -1 for Cancel or failure.
;------------------------------------------------------------------------------
file_selector:	; from: cmd_delete_file, menu_run_other_drop, select_load_file, select_insert_file, select_save_file
	lea	file_title_spec(a6),a1          ; the title object's text pointer
	move.l	a0,(a1)                         ; the title
	lea	fsel_title_tree-data_base(a6),a0 ; the title box tree
	move.l	a0,ptsin(a6)                    ; addrin[0]
	moveq	#54,d0                          ; form_center
	bsr.w	aes_call                        ; centre it
	movem.l	intout1(a6),d0-d1               ; its x, y, w, h
	movem.l	d0-d1,dialog_rect(a6)           ; kept
	clr.w	intin(a6)                       ; FMD_START
	movem.l	d0-d1,intin1(a6)                ; the small rectangle
	movem.l	d0-d1,intin5(a6)                ; and the big one
	moveq	#51,d0                          ; form_dial
	bsr.w	aes_call                        ; reserve the area
	move.l	#$2,intin(a6)                   ; from the root, 2 levels
	clr.w	intin(a6)
	movem.l	dialog_rect(a6),d0-d1           ; clipped to the box
	movem.l	d0-d1,intin2(a6)
	moveq	#42,d0                          ; objc_draw
	bsr.w	aes_call                        ; draw the title box
	lea	fsel_path(a6),a0                ; the path
	move.l	a0,ptsin(a6)                    ; addrin[0]
	lea	selector_name(a6),a0            ; the file name
	move.l	a0,ptsin+4(a6)                  ; addrin[1]
	moveq	#90,d0                          ; fsel_input
	bsr.w	aes_call                        ; let the user choose
	swap	d0                              ; its result to the high word
	move.w	intout1(a6),d0                  ; the button: 1 OK, 0 Cancel
	move.l	d0,-(sp)
	move.w	#$3,intin(a6)                   ; FMD_FINISH
	movem.l	dialog_rect(a6),d0-d1           ; the box
	movem.l	d0-d1,intin1(a6)
	movem.l	d0-d1,intin5(a6)
	moveq	#51,d0                          ; form_dial
	bsr.w	aes_call                        ; redraw what was under it
	move.l	(sp)+,d0
	swap	d0                              ; fsel_input's result
	tst.w	d0                              ; failed?
	beq.s	file_selector_cancel            ; yes
	swap	d0                              ; the button
	subq.w	#1,d0                           ; 0 for OK (Z set), -1 for Cancel
	rts
file_selector_cancel:
	moveq	#-1,d0                          ; as Cancel
	rts

;------------------------------------------------------------------------------
; Open the file selector_file names (made a full path) for reading and find its length.
; Out: file_handle, d1 the length, N clear; on an error the alert is shown and N set.
;------------------------------------------------------------------------------
open_input_file:	; from: editor_load_file, cmd_insert_file
	lea	selector_name(a6),a0            ; the name
	bsr.w	make_full_path                  ; make it a full path
	bsr.w	busy_mouse                      ; busy mouse
	clr.w	-(sp)                           ; read only
	move.l	a0,-(sp)
	move.w	#$3d,-(sp)
	trap	#1                              ; Fopen
	addq.l	#8,sp
	bsr.w	arrow_mouse                     ; arrow mouse
	tst.l	d0                              ; opened?
	bpl.s	open_input_file_length          ; yes
open_failed:	; from: save_text_file
	bsr.w	show_dos_error                  ; form_error for the GEMDOS error d0
	tst.l	d0                              ; N set
	rts
open_input_file_length:
	move.w	d0,text_file_handle(a6)         ; the handle
	bsr.w	busy_mouse                      ; busy mouse
	move.w	#$2,-(sp)                       ; from the end
	move.w	text_file_handle(a6),-(sp)
	clr.l	-(sp)                           ; offset 0
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek, Fseek: to the end, d0 = the length
	move.l	d0,path_buffer(a6)              ; keep it
	clr.w	8(sp)                           ; from the start
	clr.l	2(sp)                           ; offset 0
	trap	#1                              ; GEMDOS, Fseek: back to the start
	lea	$a(sp),sp
	bsr.w	arrow_mouse                     ; arrow mouse
	move.l	path_buffer(a6),d1              ; the length
	tst.l	d0                              ; N clear
	rts

;------------------------------------------------------------------------------
; Not called: revert to the file on disk when it has a name, else start a new file.
;------------------------------------------------------------------------------
revert_text:
	movem.l	d1-d7/a0-a5,-(sp)
	tst.b	file_name(a6)                   ; a file name?
	beq.s	revert_new_file                 ; no
	bsr.w	selector_from_file
	bsr.w	editor_save_text
	bra.s	revert_done
revert_new_file:
	bsr.w	cmd_save_as
revert_done:
	movem.l	(sp)+,d1-d7/a0-a5
	rts

;------------------------------------------------------------------------------
; The object trees whose coordinates the editor converts with rsrc_obfix at the start: 8 trees in
; the data section, the assembly options dialog below and the menu (9 in all).
;------------------------------------------------------------------------------
object_tree_list:	; from: fix_resource_trees
	dc.l	goto_line_tree
	dc.l	prefs_tree
	dc.l	run_other_tree
	dc.l	help_tree
	dc.l	about_tree
	dc.l	find_tree
	dc.l	fsel_title_tree                 ; the file selector's title box
	dc.l	options_tree                    ; the assembly options dialog
	dc.l	menu_tree                       ; the menu bar

;------------------------------------------------------------------------------
; The Assembly Options dialog (40 x 21 characters).  Each object is 24 bytes: next, head, tail, type,
; flags, state, spec, x, y, w, h.  The radio buttons' state bytes are read to build the assembler's
; command line (bit 0 = selected); the tree is also saved and loaded with the configuration.
;------------------------------------------------------------------------------
options_tree:	; from: cmd_assemble, gem_dialog, object_tree_list
	dc.w	$ffff,$0001,$001b,$0014,$0000,$0010,$0002,$1181 ; 0: root: G_BOX, outlined, border/colours $21181, the
                                                ;   head 1 and tail 27
	dc.w	$0000,$0000,$0028,$0015,$0002,$ffff,$ffff,$001a ; x 0, y 0, w 40, h 21; then 1: G_BUTTON
	dc.w	$0007,$0000                     ; selectable, default, exit
	dc.l	options_assemble_text           ; "Assemble"
	dc.w	$001c,$0013,$000a,$0401,$0003,$ffff,$ffff,$001a ; x 28, y 19, w 10, h 1+4 pixels; then 2: G_BUTTON
	dc.w	$0005,$0000                     ; selectable, exit
	dc.l	options_cancel_text             ; "Cancel"
	dc.w	$0002,$0013,$000a,$0401,$0004,$ffff,$ffff,$001c ; x 2, y 19, w 10, h 1+4; then 3: G_STRING
	dc.w	$0000,$0030                     ; outlined, shadowed
	dc.l	options_title_text              ; " Assembly Options"
	dc.w	$000b,$0001,$0012,$0001,$0008,$0005,$0007,$001c ; x 11, y 1, w 18, h 1; then 4: G_STRING with children
                                                ;   5-7
	dc.w	$0000,$0000
	dc.l	options_type_text               ; "Program type"
	dc.w	$0001,$0003,$0028,$0001         ; x 1, y 3, w 40, h 1
options_exec_obj:	; from: save_preferences, load_preferences
	dc.w	$0006,$ffff,$ffff,$001a,$0011   ; 5: G_BUTTON, selectable radio button
	dc.b	$00                             ; the state's high byte
options_exec_state:	; from: cmd_assemble
	dc.b	$01                             ; selected: executable output (else -L)
	dc.l	options_exec_text               ; "Exec"
	dc.w	$000d,$0000,$0007,$0001,$0007,$ffff,$ffff,$001a ; x 13, y 0, w 7, h 1; then 6: G_BUTTON
	dc.w	$0011                           ; selectable radio button
	dc.b	$00
options_gst_state:	; from: cmd_assemble
	dc.b	$00                             ; selected: GST linkable (-L), else DRI (-L2)
	dc.l	options_gst_text                ; "GST"
	dc.w	$0015,$0000,$0007,$0001,$0004,$ffff,$ffff,$001a ; x 21, y 0, w 7, h 1; then 7: G_BUTTON
	dc.w	$0011,$0000                     ; selectable radio button, not selected
	dc.l	options_dri_text                ; "DRI"
	dc.w	$001d,$0000,$0007,$0001,$000b,$0009,$000a,$001c ; x 29, y 0, w 7, h 1; then 8: G_STRING with children
                                                ;   9-10
	dc.w	$0000,$0000
	dc.l	options_case_text               ; "Symbols case"
	dc.w	$0001,$0005,$0028,$0001         ; x 1, y 5, w 40, h 1
options_case_obj:	; from: save_preferences, load_preferences
	dc.w	$000a,$ffff,$ffff,$001a,$0011   ; 9: G_BUTTON, selectable radio button
	dc.b	$00
options_case_state:	; from: cmd_assemble
	dc.b	$01                             ; selected: case dependent (else -C)
	dc.l	options_dependent_text          ; "Dependent"
	dc.w	$000d,$0000,$000c,$0001,$0008,$ffff,$ffff,$001a ; x 13, y 0, w 12, h 1; then 10: G_BUTTON
	dc.w	$0011,$0000                     ; selectable radio button, not selected
	dc.l	options_independent_text        ; "Independent"
	dc.w	$001a,$0000,$000c,$0001,$000f,$000c,$000e,$001c ; x 26, y 0, w 12, h 1; then 11: G_STRING with children
                                                ;   12-14
	dc.w	$0000,$0000
	dc.l	options_debug_text              ; "Debug info"
	dc.w	$0001,$0007,$0028,$0001         ; x 1, y 7, w 40, h 1
options_debug_obj:	; from: save_preferences, load_preferences
	dc.w	$000d,$ffff,$ffff,$001a,$0011,$0001 ; 12: G_BUTTON, selectable radio button, selected
	dc.l	options_none_text               ; "None"
	dc.w	$000d,$0000,$0007,$0001,$000e,$ffff,$ffff,$001a ; x 13, y 0, w 7, h 1; then 13: G_BUTTON
	dc.w	$0011                           ; selectable radio button
	dc.b	$00
options_debug_normal_state:	; from: cmd_assemble
	dc.b	$00                             ; selected: -D
	dc.l	options_normal_text             ; "Normal"
	dc.w	$0015,$0000,$0007,$0001,$000b,$ffff,$ffff,$001a ; x 21, y 0, w 7, h 1; then 14: G_BUTTON
	dc.w	$0011                           ; selectable radio button
	dc.b	$00
options_debug_extended_state:	; from: cmd_assemble
	dc.b	$00                             ; selected: -X
	dc.l	options_extended_text           ; "Extended"
	dc.w	$001d,$0000,$0009,$0001,$0014,$0010,$0013,$001c ; x 29, y 0, w 9, h 1; then 15: G_STRING, the parent of
                                                ;   16-19
	dc.w	$0000,$0000
	dc.l	options_stuff_text              ; "stuff": text left in the resource
	dc.w	$0001,$000d,$0028,$0005         ; x 1, y 13, w 40, h 5
options_output_obj:	; from: save_preferences, load_preferences
	dc.w	$0011,$ffff,$ffff,$001a,$0011   ; 16: G_BUTTON, selectable radio button
	dc.b	$00
options_output_none_state:	; from: cmd_assemble
	dc.b	$01                             ; selected: no binary (-B)
	dc.l	options_none_text               ; "None"
	dc.w	$0000,$0002,$0008,$0001,$0012,$ffff,$ffff,$001a ; x 0, y 2, w 8, h 1; then 17: G_BUTTON
	dc.w	$0011                           ; selectable radio button
	dc.b	$00
options_output_memory_state:	; from: cmd_assemble
	dc.b	$00                             ; selected: assemble to memory
