;------------------------------------------------------------------------------
; Keep the block marks right after the rest of a line from a3 on was replaced by text d1 bytes longer
; (negative: shorter).  A mark on that part of the line goes to a3; marks after it move by d1; both
; marks there end the block.
;------------------------------------------------------------------------------
adjust_marks_after_replace:	; from: adjust_block_marks
	movem.l	d6-d7/a3-a4,-(sp)
	movea.l	a3,a4                           ; the change's start
	move.l	d1,d7                           ; the change in length
	moveq	#0,d6                           ; which marks lie on the changed part: bit 0 the start, bit 1 the end
	movea.l	a4,a3                           ; from the change's start
	bra.s	adjust_marks_loop
adjust_marks_scan:
	movea.l	block_start(a6),a0              ; the block's start here?
	cmpa.l	a3,a0
	bne.s	adjust_marks_check_end          ; no
	bset	#$0,d6                          ; yes
adjust_marks_check_end:
	movea.l	block_end(a6),a0                ; the block's end here?
	cmpa.l	a3,a0
	bne.s	adjust_marks_next               ; no
	bset	#$1,d6                          ; yes
adjust_marks_next:
	move.b	(a3)+,d0                        ; a character
	moveq	#13,d1
	cmp.b	d1,d0                           ; the line's end?
	beq.s	adjust_marks_found              ; yes
adjust_marks_loop:
	cmpa.l	text_end(a6),a3                 ; at the text's end?
	bcs.s	adjust_marks_scan               ; no: on
adjust_marks_found:
	move.l	d6,d0
	tst.w	d0                              ; no mark on the changed part?
	beq.s	adjust_marks_shift              ; yes: move the marks after it
	subq.w	#1,d0
	beq.s	adjust_marks_start_here         ; the start only
	subq.w	#1,d0
	beq.s	adjust_marks_end_here           ; the end only
	subq.w	#1,d0
	beq.s	adjust_marks_both_here          ; both
	bra.s	adjust_marks_done
adjust_marks_start_here:
	add.l	d7,block_end(a6)                ; the end moves by the change
	move.l	a4,block_start(a6)              ; the start goes to the change
	bra.s	adjust_marks_done
adjust_marks_end_here:
	move.l	a4,block_end(a6)                ; the end goes to the change
	bra.s	adjust_marks_done
adjust_marks_both_here:
	suba.l	a0,a0
	move.l	a0,block_end(a6)                ; no block end
	move.l	a0,block_start(a6)              ; no block start
	clr.b	block_shown(a6)                 ; no block
	bra.s	adjust_marks_done
adjust_marks_shift:
	movea.l	block_start(a6),a0              ; the block's start
	cmpa.l	a0,a4                           ; after the change?
	bcc.s	adjust_marks_shift_end          ; no
	add.l	d7,block_start(a6)              ; yes: moved
adjust_marks_shift_end:
	movea.l	block_end(a6),a0                ; the block's end
	cmpa.l	a0,a4                           ; after the change?
	bcc.s	adjust_marks_done               ; no
	add.l	d7,block_end(a6)                ; yes: moved
adjust_marks_done:
	movem.l	(sp)+,d6-d7/a3-a4
	rts
	dc.w	$0000                           ; pad

;------------------------------------------------------------------------------
; The assembler.  It runs as a program of its own: the editor starts it with Pexec (create basepage,
; text base = this address) and gives it a command line and, at its basepage+$80, 'AMP' and the source
; in memory (start, end, error list, output buffer and size).  It sets a6 to its basepage's BSS + 2,
; so in the assembler d(a6) are its own variables (asm_...), not the editor's.
; Command line: the source file, then -B no binary, -C case insensitive, -D debug, -X extended debug,
; -E<symbol=value> symbols (the rest of the line), -L GST linkable, -L2 DRI linkable, -M small file
; buffers (slow), -O<file> output name, -P[file] listing, -Q wait for a key at the end, -S symbols in
; the listing, -T<n> the listing's tab width, -Z list in pass 1 as well.  No command line: it asks.
; Two passes over the source: pass 1 finds the labels' values, pass 2 makes the code and the listing.
;------------------------------------------------------------------------------
asm_entry:	; from: aes_call, cmd_jump_error, set_version_title, cmd_assemble
	bra.s	asm_start                       ; over the identification
	dc.w	$5ad5,$47f2,$5080               ; identification words
	dc.b	'GenST (C) HiSoft 1985-91'
asm_start:
	bsr.w	asm_startup                     ; a6, the stack, Mshrink
	bsr.w	listing_init                    ; the listing state
	moveq	#0,d0                           ; 0: the banner
	bsr.w	print_asm_message               ; print it
	lea	upper_case_table(pc),a0         ; the variables' first values
	lea	-$2(a6),a1                      ; from a6-2
	moveq	#63,d0                          ; 256 bytes
asm_start_copy_vars:
	move.l	(a0)+,(a1)+
	dbra	d0,asm_start_copy_vars
	lea	asm_ignore_case(a6),a0          ; then clear asm_ignore_case on
	move.w	#$61,d0                         ; 196 bytes
asm_start_clear_vars:
	clr.w	(a0)+
	dbra	d0,asm_start_clear_vars
	sf	return_code(a6)                 ; return code 0
	sf	pass_two(a6)                    ; pass 1
	bsr.w	symbol_block_alloc              ; the first symbol memory block
	lea	asm_name_root(a6),a1            ; the names tree's root
	clr.l	(a1)                            ; empty
	move.l	a1,asm_name_tree(a6)
	lea	asm_global_root(a6),a1          ; the global symbols' root
	clr.l	(a1)                            ; empty
	move.l	a1,equate_tree(a6)
	bsr.w	macro_stack_init                ; the macro memory
	bsr.w	init_mnemonic_hash              ; the mnemonic hash table
	clr.l	asm_source_name(a6)             ; no source file named yet
	clr.b	asm_output_name(a6)             ; no output name
	clr.w	asm_incdir_list(a6)             ; no INCDIR paths
	sf	cmdline_linkable(a6)            ; not linkable
	clr.w	linker_format(a6)               ; GST format
	move.b	#$64,return_code(a6)            ; return code 100 while the command line is read
	bsr.w	command_line                    ; read the command line
	bne.w	asm_end_close_listing           ; bad: stop
	sf	return_code(a6)                 ; return code 0
	move.l	cmdline_case(a6),asm_ignore_case(a6) ; the options -C, -L, -S, -P to their flags
	move.l	asm_source_name(a6),d0          ; a source file named?
	beq.s	asm_pass_one                    ; no: the source is in memory
	movea.l	d0,a0                           ; its name
	bsr.w	include_open                    ; open it as an include file
	beq.s	asm_pass_one                    ; opened
	moveq	#10,d0                          ; "Could not open file "
	bsr.w	print_asm_message               ; print it
	movea.l	asm_source_name(a6),a0          ; the name
	moveq	#0,d0
	move.b	5(a0),d0                        ; its length
	clr.b	5(a0,d0.w)                      ; ended with a 0
	addq.w	#6,a0                           ; the name's text
	bsr.w	print_string                    ; print it
	bsr.w	print_newline                   ; a CR
	move.b	#$64,return_code(a6)            ; return code 100
	bra.w	asm_end_close_listing           ; stop
asm_pass_one:
	bsr.w	asm_init_pass                   ; start the pass
	lea	line_code(a6),a0                ; pass 1 code goes to a scratch buffer
	move.l	a0,code_buffer_ptr(a6)
	moveq	#1,d0                           ; "Pass 1"
	bsr.w	print_asm_message               ; print it
	move.b	asm_listing_wanted(a6),asm_listing_active(a6) ; listing output active when a listing is wanted
	tst.l	asm_cmdline_symbols(a6)         ; command-line symbols?
	beq.s	asm_pass_one_loop               ; no
	bsr.w	asm_next_line                   ; the first line
	bne.s	asm_pass_one_done               ; no source
	bsr.w	asm_line                        ; assemble it (it may hold OPTs)
	bsr.w	asm_list_line                   ; list it
	bsr.w	define_cmdline_symbols          ; then define the command-line symbols
asm_pass_one_loop:
	bsr.w	asm_next_line                   ; the next line
	bne.s	asm_pass_one_done               ; the end
	bsr.w	asm_line                        ; assemble it
	bsr.w	asm_list_line                   ; list it
	bra.s	asm_pass_one_loop
asm_pass_one_done:
	tst.b	asm_error_count(a6)             ; errors?
	bne.w	asm_finish                      ; yes: no pass 2
	bsr.w	asm_end_pass_one                ; finish pass 1, get ready for pass 2
	sf	asm_listing_active(a6)          ; listing output off
	moveq	#2,d0                           ; "Pass 2"
	bsr.w	print_asm_message               ; print it
	tst.b	asm_end_seen(a6)                ; interrupted?
	bgt.w	asm_interrupted                 ; yes: stop
	move.b	asm_listing_wanted(a6),asm_listing_active(a6) ; listing output active when a listing is wanted
	bsr.w	listing_page_end                ; the listing's page start
	st	pass_two(a6)                    ; pass 2
	bsr.w	asm_init_pass                   ; start the pass
	tst.b	asm_listing_wanted(a6)          ; a listing?
	beq.s	asm_pass_two_source             ; no
	sf	asm_list_level(a6)              ; list level 0
	st	asm_listing_on(a6)              ; listing on
asm_pass_two_source:
	tst.l	asm_source_name(a6)             ; a source file?
	beq.s	asm_pass_two_loop               ; no
	movea.l	asm_source_name(a6),a0          ; its name
	bsr.w	include_open                    ; open it again
	bne.w	asm_fatal_error                 ; failed: stop
asm_pass_two_loop:
	bsr.w	asm_next_line                   ; the next line
	bne.s	asm_pass_two_done               ; the end
	bsr.w	asm_line                        ; assemble it
	bsr.w	asm_list_line                   ; list it
	bra.s	asm_pass_two_loop
asm_pass_two_done:
	bsr.w	asm_check_endc                  ; IF without ENDC?
	bsr.w	save_section_pc                 ; the section's PC kept
	bsr.w	end_module_output               ; the end of pass 2's output work
	bsr.w	obj_finish                      ; write the output
	tst.b	asm_list_symbols(a6)            ; symbols in the listing?
	beq.s	asm_finish                      ; no
	bsr.w	symbol_listing                  ; the global symbols list

;------------------------------------------------------------------------------
; The end, after the passes or a fatal error: close the listing and the files, print the totals.
;------------------------------------------------------------------------------
asm_finish:	; from: asm_entry, asm_fatal_error
	sf	asm_listing_active(a6)          ; listing output off
	bsr.w	listing_close                   ; close the listing
	bsr.w	binary_close                    ; free the output buffer
	bsr.w	include_close_all               ; close the include files
	bsr.w	print_newline                   ; a new line
	moveq	#0,d1
	move.b	asm_error_count(a6),d1          ; the error count
	bsr.w	print_decimal                   ; print it
	moveq	#3,d0                           ; " errors found"
	cmpi.b	#$1,asm_error_count(a6)         ; just 1?
	bne.s	asm_finish_lines                ; no
	addq.b	#1,d0                           ; " error found"
asm_finish_lines:
	bsr.w	print_asm_message               ; print it
	moveq	#0,d1
	move.w	asm_lines_total(a6),d1          ; the lines
	bsr.w	print_decimal                   ; print them
	moveq	#5,d0                           ; " lines assembled into "
	bsr.w	print_asm_message
	move.l	asm_code_size(a6),d1            ; the code size
	bsr.w	print_decimal                   ; print it
	moveq	#12,d0                          ; " bytes, "
	bsr.w	print_asm_message
	bsr.w	obj_print_format                ; the output format's name
	moveq	#22,d0                          ; " absolute"
	tst.b	asm_absolute_code(a6)           ; ORG code?
	bne.s	asm_finish_kind                 ; yes
	moveq	#18,d0                          ; " position-independent"
	tst.b	asm_relocated(a6)               ; relocated?
	beq.s	asm_finish_kind                 ; no
	moveq	#17,d0                          ; " relocatable"
asm_finish_kind:
	bsr.w	print_asm_message               ; print it
	moveq	#19,d0                          ; " code"
	bsr.w	print_asm_message
	moveq	#0,d1
	move.w	asm_optimise_count(a6),d1       ; optimisations made?
	beq.s	asm_end_close_listing           ; none
	bsr.w	print_decimal                   ; print the count
	moveq	#13,d0                          ; " optimisations saving "
	bsr.w	print_asm_message
	moveq	#0,d0
	move.w	asm_optimise_saved(a6),d1       ; the bytes saved
	bsr.w	print_decimal                   ; print them
	moveq	#14,d0                          ; " bytes"
	bsr.w	print_asm_message
asm_end_close_listing:	; from: asm_entry
	bsr.w	listing_close_file              ; close the listing file
	bsr.w	show_memory_time                ; the memory used and the time taken
	move.l	incbin_handle(a6),d3            ; an INCBIN file left open?
	beq.s	asm_exit_free                   ; no
	jsr	close_binary_file               ; close it
	clr.l	incbin_handle(a6)
asm_exit_free:
	bsr.w	free_blocks                     ; free the memory
	bsr.w	asm_exit                        ; wait for a key if asked, and terminate

;------------------------------------------------------------------------------
; Set up a pass: rewind the source, no lines, PC 0, no symbols scopes, no IF, macro or REPT,
; options back to their defaults, the anonymous module with a TEXT section.
;------------------------------------------------------------------------------
asm_init_pass:	; from: asm_entry
	moveq	#0,d0
	move.w	d0,asm_lines_total(a6)          ; no lines
	move.w	d0,line_number(a6)              ; line 0
	move.l	memory_source(a6),asm_source_ptr(a6) ; rewind the source in memory
	move.l	d0,asm_code_size(a6)            ; no code
	move.l	d0,program_counter(a6)          ; PC 0
	move.l	d0,asm_local_tree(a6)           ; no local symbols
	move.l	d0,asm_module_tree(a6)          ; no module symbols
	move.l	d0,reserve_bytes(a6)            ; no DS or INCBIN count
	move.w	d0,if_depth(a6)                 ; no IF
	move.w	d0,macro_call_number(a6)        ; no macro calls
	move.l	d0,macro_frame(a6)              ; no macro running
	move.b	d0,asm_position_independent(a6) ; not position independent
	move.b	d0,asm_absolute_code(a6)        ; not ORG
	move.b	d0,asm_list_marker(a6)          ; no value to list
	move.w	d0,asm_optimise_flags(a6)       ; no optimisations
	move.w	#$ffff,asm_optimise_warnings(a6) ; warnings for all of them
	move.b	d0,type_check_off(a6)           ; type checking on
	move.l	d0,rept_block(a6)               ; no REPT
	move.w	d0,macro_depth(a6)              ; macro depth 0
	move.w	d0,rept_macro_depth(a6)
	move.l	d0,oss_format(a6)               ; no PASCAL section
	move.l	d0,rs_counter(a6)               ; RS counter 0
	moveq	#1,d0
	move.l	d0,rs_step(a6)                  ; RS step +1
	st	asm_list_level(a6)              ; list level -1
	st	asm_warnings(a6)                ; warnings on
	move.w	#$80,symbol_length(a6)          ; symbols significant to 127 characters
	bsr.w	optimisations_start_pass        ; the pass's record list
	sf	asm_relocated(a6)               ; no relocation yet
	sf	asm_end_seen(a6)                ; END not seen
	sf	asm_nested_macro_line(a6)       ; no nested macro call line
	sf	asm_list_macros(a6)             ; macro expansions not listed
	sf	in_macro(a6)                    ; not in a macro
	sf	asm_auto_pc(a6)                 ; no automatic PC-relative
	sf	asm_warn_hash(a6)               ; no # warnings
	st	asm_odd_check(a6)               ; odd address checks on
	move.b	#$2e,local_char(a6)             ; locals start with "."
	move.b	#$1,asm_section_type(a6)        ; TEXT
	bsr.w	start_anon_module               ; ANON_MODULE and its TEXT section
	lea	asm_incdir_list(a6),a0          ; no INCDIR paths
	clr.w	(a0)
	rts

;------------------------------------------------------------------------------
; An IF left open at the end gives "missing ENDC".
;------------------------------------------------------------------------------
asm_check_endc:	; from: asm_entry, asm_end_pass_one
	tst.w	if_depth(a6)                    ; IF open?
	bne.s	asm_check_endc_missing          ; yes
	rts
asm_check_endc_missing:
	moveq	#48,d0                          ; "missing ENDC"
	bra.w	asm_error                       ; report it

;------------------------------------------------------------------------------
; End of pass 1: check IFs, keep the section's PC, close the includes, reset the sections and set up the
; output for pass 2.
;------------------------------------------------------------------------------
asm_end_pass_one:	; from: asm_entry
	bsr.s	asm_check_endc                  ; IF open?
	bsr.w	save_section_pc                 ; the section's PC kept
	bsr.w	end_module_output
	bsr.w	include_close_all               ; close the include files
	bsr.s	asm_reset_sections              ; sections back to 0, sizes even
	bsr.w	obj_buffers_init                ; set up the output
	clr.l	line_end_hook(a6)               ; no action after the line
	rts

;------------------------------------------------------------------------------
; Before pass 2: every module's section PCs back to 0; the TEXT, DATA and BSS sizes rounded up to
; even; the BSS starts after the data.
;------------------------------------------------------------------------------
asm_reset_sections:	; from: asm_end_pass_one
	moveq	#0,d2
	tst.b	linkable_output(a6)             ; linkable?
	beq.s	asm_reset_sections_walk         ; no
	tst.w	linker_format(a6)               ; DRI format?
	seq	d2                              ; d2 $ff for GST linkable (not used below)
asm_reset_sections_walk:
	movea.l	asm_name_tree(a6),a3            ; the names tree
	movea.l	(a3),a3                         ; its root
	lea	asm_section_table(a6),a1        ; the section table (not used below)
	bsr.s	asm_reset_module_sections       ; clear the sections of every module
	lea	text_size(a6),a0                ; the TEXT size
	bsr.s	asm_round_section               ; even
	lea	data_size(a6),a0                ; the DATA size
	bsr.s	asm_round_section               ; even
	lea	bss_size(a6),a0                 ; the BSS size
	bsr.s	asm_round_section               ; even
	move.l	asm_data_start(a6),d0           ; the data's start
	add.l	d0,asm_bss_start(a6)            ; added to the BSS start
	rts

;------------------------------------------------------------------------------
; Round the section size at a0 up to even, and the field 8 bytes on with it.
;------------------------------------------------------------------------------
asm_round_section:	; from: asm_reset_sections
	btst	#$0,3(a0)                       ; odd?
	beq.s	asm_round_section_done          ; no
	addq.l	#1,(a0)                         ; yes: one more
	addq.l	#1,8(a0)
asm_round_section_done:
	rts

;------------------------------------------------------------------------------
; Walk the names tree at a3 (left, node, right); for each module node (type 9) clear its sections.
;------------------------------------------------------------------------------
asm_reset_module_sections:	; from: asm_reset_sections
	tst.l	(a3)                            ; a left branch?
	beq.s	asm_reset_module_this           ; no
	move.l	a3,-(sp)
	movea.l	(a3),a3                         ; walk it
	bsr.s	asm_reset_module_sections
	movea.l	(sp)+,a3
asm_reset_module_this:
	cmpi.b	#$9,$d(a3)                      ; a module?
	bne.s	asm_reset_module_right          ; no
	movea.l	8(a3),a2                        ; its section tree
	bsr.s	asm_clear_section_pcs           ; clear their PCs
asm_reset_module_right:
	tst.l	4(a3)                           ; a right branch?
	beq.s	asm_reset_module_done           ; no
	move.l	a3,-(sp)
	movea.l	4(a3),a3                        ; walk it
	bsr.s	asm_reset_module_sections
	movea.l	(sp)+,a3
asm_reset_module_done:
	rts

;------------------------------------------------------------------------------
; Walk the section tree at a2 and set every section's PC (value) to 0.
;------------------------------------------------------------------------------
asm_clear_section_pcs:	; from: asm_reset_module_sections
	tst.l	(a2)                            ; a left branch?
	beq.s	asm_clear_section_this          ; no
	move.l	a2,-(sp)
	movea.l	(a2),a2                         ; walk it
	bsr.s	asm_clear_section_pcs
	movea.l	(sp)+,a2
asm_clear_section_this:
	clr.l	8(a2)                           ; PC 0
	tst.l	4(a2)                           ; a right branch?
	beq.s	asm_clear_section_done          ; no
	move.l	a2,-(sp)
	movea.l	4(a2),a2                        ; walk it
	bsr.s	asm_clear_section_pcs
	movea.l	(sp)+,a2
asm_clear_section_done:
	rts

;------------------------------------------------------------------------------
; The first character of the next source line, without reading the line (for a macro call that goes
; on to the next line).  Out: d0 the character, Z set; d0 -1, Z clear at the end of the source.
;------------------------------------------------------------------------------
asm_peek_line:	; from: macro_call
	tst.l	rept_block(a6)                  ; in a REPT?
	bne.s	asm_peek_line_rept              ; yes
	tst.b	in_macro(a6)                    ; in a macro?
	bne.s	asm_peek_line_macro             ; yes
	tst.l	include_file(a6)                ; in an include file?
	bne.s	asm_peek_line_include           ; yes
	movea.l	asm_source_ptr(a6),a0           ; the source in memory
	cmpa.l	asm_source_end(a6),a0           ; at its end?
	bge.s	asm_peek_line_end               ; yes
asm_peek_line_char:
	move.b	(a0),d0                         ; the character
	cmp.b	d0,d0                           ; Z set
	rts
asm_peek_line_end:
	moveq	#-1,d0                          ; the end
	rts
asm_peek_line_rept:
	tst.b	in_macro(a6)                    ; a macro too?
	beq.s	asm_peek_line_rept_text         ; no
	move.w	macro_depth(a6),d0              ; the macro depth
	cmp.w	rept_macro_depth(a6),d0         ; deeper than at the REPT?
	bhi.s	asm_peek_line_macro             ; yes: from the macro
asm_peek_line_rept_text:
	movea.l	rept_block(a6),a1               ; the REPT block
	movea.l	rept_read(a6),a0                ; its read pointer
	cmpa.l	4(a1),a0                        ; at the block's end?
	bne.s	asm_peek_line_char              ; no
	movea.l	8(a1),a0                        ; yes: back to its start
	bra.s	asm_peek_line_char
asm_peek_line_macro:
	movea.l	macro_frame(a6),a2              ; the running macro
	movea.l	4(a2),a1                        ; its definition
	movea.l	$10(a2),a0                      ; the read pointer
	cmpa.l	4(a1),a0                        ; at the definition's end?
	bne.s	asm_peek_line_char              ; no
	movea.l	8(a1),a1                        ; yes: the line after the call
	movea.l	0(a1),a0
	bra.s	asm_peek_line_char
asm_peek_line_include:
	movea.l	include_file(a6),a1             ; the include file
	movea.l	8(a1),a2                        ; its buffer
	movea.l	0(a2),a0                        ; the read pointer
	cmpa.l	8(a2),a0                        ; at the buffer's end?
	bcc.s	asm_peek_line_bad               ; yes: cannot look ahead
	cmpi.b	#$a,(a0)+                       ; a LF?
	beq.s	asm_peek_line_char              ; yes: skip it
	subq.l	#1,a0                           ; no: back to it
	bra.s	asm_peek_line_char
asm_peek_line_bad:
	moveq	#68,d0                          ; "INTERNAL:invalid multi-line macro call"
	bra.w	asm_fatal_error                 ; fatal
	dc.w	$4afb                           ; ILLEGAL and a text left from debugging
	dc.b	'include_longmac',0
asm_source_ended:	; from: asm_next_line, asm_read_line
	bpl.s	asm_interrupted                 ; positive: interrupted
	rts                                     ; END seen: Z clear, the end
asm_interrupted:	; from: asm_entry
	moveq	#78,d0                          ; "assembly interrupted"
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Get the next line to assemble, from a running macro, a REPT, an include file or the source.
; Out: a4 at the line, Z set (d0 0); Z clear (d0 -1) at the end of the source or after END.
;------------------------------------------------------------------------------
asm_next_line:	; from: asm_entry, if_skip, macro_call, directive_rept
	tst.b	asm_end_seen(a6)                ; END seen?
	bne.s	asm_source_ended                ; yes
	addq.w	#1,asm_lines_total(a6)          ; one more line
	tst.b	in_macro(a6)                    ; in a macro?
	bne.w	macro_next_line                 ; yes: its next line
	tst.l	rept_block(a6)                  ; in a REPT?
	bne.w	rept_next_line                  ; yes: its next line

;------------------------------------------------------------------------------
; Read the next line of the source, from the include file in use or else the source in memory.
; A line of more than 252 characters is cut: a CR and a "*" go in at its 252nd and 253rd, so the
; rest becomes a comment line.
; Out: a4 at the line (also in asm_line_start), Z set; Z clear at the end.
;------------------------------------------------------------------------------
asm_read_line:	; from: directive_macro, macro_store_line, directive_rept
	tst.b	asm_end_seen(a6)                ; END seen?
	bne.s	asm_source_ended                ; yes
	moveq	#13,d1                          ; CR
	move.w	#$fe,d2
	addq.w	#1,line_number(a6)              ; the line number in this file
	tst.l	include_file(a6)                ; in an include file?
	bne.s	asm_read_include_line           ; yes
	movea.l	asm_source_ptr(a6),a4           ; the source in memory
	cmpa.l	asm_source_end(a6),a4           ; at its end?
	bge.s	asm_read_line_end               ; yes
	movea.l	a4,a0
	move.l	a4,asm_line_start(a6)           ; this line
asm_read_line_cr:
	cmp.b	(a0)+,d1                        ; to past the CR
	bne.s	asm_read_line_cr
asm_read_line_lf:
	cmpi.b	#$a,(a0)+                       ; skip the LFs
	beq.s	asm_read_line_lf
	subq.l	#1,a0
	move.l	a0,asm_source_ptr(a6)           ; the next line
	moveq	#0,d0                           ; Z set
	rts
asm_read_line_end:
	moveq	#-1,d0                          ; the end
	rts
asm_read_include_line:
	movea.l	include_file(a6),a1             ; the include file
	movea.l	8(a1),a0                        ; its buffer
	movea.l	0(a0),a4                        ; the read pointer
asm_read_include_skip_lf:
	cmpa.l	8(a0),a4                        ; at the buffer's end?
	bcc.w	asm_read_include_empty          ; yes
	cmpi.b	#$a,(a4)                        ; a LF?
	bne.s	asm_read_include_find_cr        ; no
	addq.l	#1,a4                           ; yes: skip it
	bra.s	asm_read_include_skip_lf
asm_read_include_find_cr:
	move.w	#$fc,d0                         ; at most 253 characters
	moveq	#13,d2                          ; CR
	move.l	a4,asm_line_start(a6)           ; this line
	movea.l	a4,a2
asm_read_include_scan:
	cmp.b	(a2)+,d2                        ; the CR?
	dbeq	d0,asm_read_include_scan
	beq.s	asm_read_include_found          ; found
	cmpa.l	8(a0),a2                        ; past the buffer's end?
	bhi.s	asm_read_include_refill         ; yes: read more
	move.b	#$2a,-(a2)                      ; too long: the rest starts with "*"
	move.b	#$d,-$1(a2)                     ; and this part ends here
	move.l	a2,0(a0)                        ; the next read
	moveq	#0,d0                           ; Z set
	rts
asm_read_include_found:
	moveq	#10,d0                          ; LF
asm_read_include_lf:
	cmpa.l	8(a0),a2                        ; past the buffer's end?
	bhi.s	asm_read_include_refill         ; yes: read more
	cmp.b	(a2)+,d0                        ; a LF?
	beq.s	asm_read_include_lf             ; yes: skip it
	subq.l	#1,a2
	move.l	a2,0(a0)                        ; the next read
	moveq	#0,d0                           ; Z set
	rts
asm_read_include_refill:
	move.l	4(a0),d1                        ; the buffer's size
	lea	$e(a0,d1.l),a2                  ; its data's end
	cmpa.l	8(a0),a2                        ; the buffer full (more file to come)?
	bne.s	asm_read_include_close          ; no: the file ended
	move.l	8(a0),d2
	sub.l	a4,d2                           ; the part of a line left
	beq.s	asm_read_include_empty          ; none
	movem.l	d2/a1,-(sp)
	subq.l	#1,d2
	movea.l	a4,a1
	lea	$e(a0),a2                       ; to the buffer's start
	move.l	a2,0(a0)
asm_read_include_move:
	move.b	(a1)+,(a2)+
	dbra	d2,asm_read_include_move
	movem.l	(sp)+,d2/a1
	move.l	4(a0),d1                        ; the room after it
	sub.l	d2,d1
	bsr.w	include_read_more               ; read more of the file after it
	bra.s	asm_read_include_read
asm_read_include_empty:
	lea	$e(a0),a2                       ; the buffer's start
	move.l	a2,0(a0)                        ; the read pointer
	move.l	4(a0),d1                        ; its size
	lea	$e(a0,d1.l),a2
	cmpa.l	8(a0),a2                        ; the buffer full (more file to come)?
	bne.s	asm_read_include_close          ; no: the file ended
	bsr.w	include_read                    ; read the next buffer full
asm_read_include_read:
	beq.w	asm_read_include_line           ; read: try the line again
	bra.w	asm_fatal_error                 ; failed: fatal
asm_read_include_close:
	move.w	$c(a0),line_number(a6)          ; back to the line number in the outer file
	clr.w	$c(a0)
	move.l	$98(a1),d2                      ; the file's handle
	beq.s	asm_read_include_pop            ; none
	move.l	a1,-(sp)
	bsr.w	close_source_file               ; close it
	movea.l	(sp)+,a1
	clr.l	$98(a1)
asm_read_include_pop:
	move.l	$10(a1),include_file(a6)        ; back to the outer file
	bra.w	asm_read_line                   ; its next line

;------------------------------------------------------------------------------
; LIST: in pass 2 listing on; LIST+ and LIST- add 1 to or take 1 from the list level, and the listing
; is on while the level is 0 or more.  The LIST line itself is not listed.
;------------------------------------------------------------------------------
asm_dir_list:	; from: mnemonic_table
	st	line_not_listed(a6)             ; this line not listed
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_dir_list_pass_one           ; no
	cmp.b	#$2b,d1                         ; LIST+?
	beq.s	asm_dir_list_plus               ; yes
	cmp.b	#$2d,d1                         ; LIST-?
	beq.s	asm_dir_list_minus              ; yes
	moveq	#13,d1                          ; the rest of the line ignored
	st	asm_listing_on(a6)              ; listing on
	rts
asm_dir_list_pass_one:
	moveq	#13,d1                          ; the rest ignored
	rts
asm_dir_list_minus:
	subq.b	#1,asm_list_level(a6)           ; one level down
	bra.s	asm_dir_list_set
asm_dir_list_plus:
	addq.b	#1,asm_list_level(a6)           ; one level up
asm_dir_list_set:
	spl	asm_listing_on(a6)              ; listing on while the level is 0 or more
	move.b	(a4)+,d1                        ; the next character
	rts

;------------------------------------------------------------------------------
; NOLIST: listing off and the list level -1 (in pass 2).  The line itself is not listed.
;------------------------------------------------------------------------------
asm_dir_nolist:	; from: long_mnemonic_table
	st	line_not_listed(a6)             ; this line not listed
	moveq	#13,d1                          ; the rest ignored
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_dir_nolist_done             ; no
	sf	asm_listing_on(a6)              ; listing off
	st	asm_list_level(a6)              ; level -1
asm_dir_nolist_done:
	rts

;------------------------------------------------------------------------------
; List the line just assembled when it should be: always after an error; in pass 1 only with -Z; in
; pass 2 when the listing is on, unless LIST/NOLIST or a macro's lines (without OPT M) say no.
;------------------------------------------------------------------------------
asm_list_line:	; from: asm_entry, if_skip, directive_macro, macro_store_line, macro_call, directive_rept
	tst.b	asm_line_had_error(a6)          ; an error on the line?
	bne.s	asm_list_line_print             ; yes: list it
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	asm_list_line_pass_two          ; yes
	tst.b	cmdline_z(a6)                   ; listing in pass 1 asked for?
	beq.s	asm_list_line_done              ; no
	bra.s	asm_list_line_print             ; yes
asm_list_line_pass_two:
	tst.b	asm_listing_on(a6)              ; listing on?
	beq.s	asm_list_line_done              ; no
	tst.b	line_not_listed(a6)             ; this line not to be listed?
	bne.s	asm_list_line_done              ; yes
	tst.b	in_macro(a6)                    ; in a macro?
	beq.s	asm_list_line_print             ; no: list it
	tst.b	asm_nested_macro_line(a6)       ; a macro call inside a macro?
	bne.s	asm_list_line_print             ; yes: list it
	tst.b	asm_list_macros(a6)             ; macro expansions listed?
	bne.s	asm_list_line_print             ; yes
asm_list_line_done:
	sf	line_not_listed(a6)
	clr.b	asm_list_marker(a6)             ; no value to list
	sf	asm_nested_macro_line(a6)
	rts
asm_list_line_print:
	sf	asm_line_had_error(a6)
	bsr.w	listing_source_line             ; print the listing line
	bra.s	asm_list_line_done
asm_line_empty:	; from: asm_line
	rts

;------------------------------------------------------------------------------
; Assemble the line at a4: an optional label (from column 1, ':' and '::' allowed), then a mnemonic,
; directive, macro call or '=' equate, or a comment.  A label alone is defined at the PC.
; The stack is kept in asm_line_sp so that a fatal error in the line can give it up.
;------------------------------------------------------------------------------
asm_line:	; from: asm_entry, directive_rept
	move.l	sp,asm_line_sp(a6)              ; for errors that abandon the line
	movea.l	code_buffer_ptr(a6),a5          ; the code goes here
	move.l	a5,line_code_start(a6)          ; this line's code starts here
	clr.l	line_code_size(a6)              ; no code yet
	sf	line_has_error(a6)              ; no error yet
	move.b	(a4)+,d1                        ; the first character
	cmp.b	#$d,d1                          ; an empty line?
	beq.s	asm_line_empty                  ; yes
	cmp.b	#$9,d1                          ; a tab?
	beq.s	asm_line_no_label               ; yes: no label
	cmp.b	#$20,d1                         ; a space?
	bne.s	asm_line_label                  ; no: a label
asm_line_no_label:
	clr.l	line_label(a6)                  ; no label
	bra.w	asm_line_skip_space
asm_line_label:
	st	d2
	lea	line_label(a6),a0               ; the label
	clr.b	4(a0)                           ; not exported
	bsr.w	read_symbol_name                ; read its name
	bne.s	asm_line_comment                ; not a name
	cmp.b	#$3a,d1                         ; a colon after it?
	bne.s	asm_line_field                  ; no
asm_line_colon:	; from: asm_mnemonic
	move.b	(a4)+,d1
	cmp.b	#$3a,d1                         ; a second colon?
	bne.s	asm_line_field                  ; no
	st	asm_label_exported(a6)          ; yes: the label is exported
asm_line_skip_space:
	move.b	(a4)+,d1
asm_line_field:
	cmp.b	#$9,d1                          ; skip tabs
	beq.s	asm_line_skip_space
	cmp.b	#$20,d1                         ; and spaces
	beq.s	asm_line_skip_space
	cmp.b	#$d,d1                          ; the end?
	beq.w	asm_define_label                ; yes: just the label
	ext.w	d1
	lea	label_start_chars(pc),a0        ; the character class table
	tst.b	0(a0,d1.w)                      ; a letter?
	beq.s	asm_mnemonic                    ; yes: a mnemonic
	cmp.b	#$3d,d1                         ; "="?
	beq.w	mnemonic_dispatch_equ           ; yes: an equate
asm_line_comment:
	cmp.b	#$3b,d1                         ; a ";" comment?
	beq.w	asm_define_label                ; yes: just the label
	cmp.b	#$2a,d1                         ; a "*" comment?
	beq.w	asm_define_label                ; yes: just the label
	bra.w	err_line_malformed              ; "line malformed"

;------------------------------------------------------------------------------
; The mnemonic field at a4-1 (d1 its first character): a built-in instruction or directive (its
; name upper case, padded to 8 characters at asm_mnemonic_name), else a macro call, else a label
; written with a colon after it.  Does not return for an instruction (its handler goes on).
;------------------------------------------------------------------------------
asm_mnemonic:	; from: asm_line, dir_iif
	lea	-$1(a4),a2                      ; its start
	lea	line_code(a6),a1                ; the name buffer's end
	move.l	#$20202020,-(a1)                ; 8 spaces
	move.l	#$20202020,-(a1)
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	moveq	#7,d2                           ; 7 more at most
	move.b	d1,(a1)+                        ; the first
asm_mnemonic_char:
	move.b	(a4)+,d1                        ; the next
	cmp.b	#$d,d1                          ; the end?
	beq.s	asm_mnemonic_builtin            ; yes
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	cmp.b	#$41,d1                         ; A to Z?
	bcs.s	asm_mnemonic_end                ; no
	cmp.b	#$5b,d1
	bcc.s	asm_mnemonic_end                ; no
	move.b	d1,(a1)+
	dbra	d2,asm_mnemonic_char
	bra.s	asm_mnemonic_macro              ; too long for a built-in
asm_mnemonic_end:
	cmp.b	#$2e,d1                         ; a size?
	beq.s	asm_mnemonic_builtin            ; yes
	cmp.b	#$9,d1                          ; a tab?
	beq.s	asm_mnemonic_builtin            ; yes
	cmp.b	#$20,d1                         ; a space?
	bne.s	asm_mnemonic_macro              ; no: not a built-in
asm_mnemonic_builtin:
	bsr.w	find_mnemonic                   ; look it up and assemble it
asm_mnemonic_macro:
	movea.l	a2,a4                           ; from the start again
	move.b	(a4)+,d1
	lea	asm_mnemonic_symbol(a6),a0      ; the name
	bsr.w	read_name_cut_dot               ; read it
	bne.w	err_line_malformed              ; not a name: "line malformed"
	movea.l	asm_name_tree(a6),a2            ; the names tree
	move.l	a1,d4                           ; past the name
	movem.l	d2/a3-a5,-(sp)
	bsr.w	asm_tree_find                   ; a macro of that name?
	movem.l	(sp)+,d2/a3-a5
	beq.w	macro_call                      ; yes: call it
	movea.l	d4,a4                           ; no
	move.b	-$1(a4),d1                      ; the character after it
	cmp.b	#$3a,d1                         ; a colon?
	bne.w	report_not_recognised           ; no: "instruction not recognised"
	lea	line_label(a6),a1               ; the label
	tst.l	(a1)                            ; one already?
	bne.w	report_not_recognised           ; yes: "instruction not recognised"
	move.b	d2,5(a0)                        ; its length
	bsr.s	asm_copy_label                  ; it is the label
	movea.l	a1,a0
	clr.b	4(a0)                           ; not exported
	bra.w	asm_line_colon                  ; on after the colon

;------------------------------------------------------------------------------
; Copy the symbol descriptor a0 to a1 (name pointer, flag, length, name).  With case ignored the
; name was made upper case in the descriptor itself, so its text is copied too.
;------------------------------------------------------------------------------
asm_copy_label:	; from: asm_mnemonic
	move.b	5(a0),5(a1)                     ; the length
	tst.b	asm_ignore_case(a6)             ; case ignored?
	bne.s	asm_copy_label_name             ; yes
	move.l	(a0),(a1)                       ; the name in the source
	move.b	6(a0),6(a1)                     ; the first character
	rts
asm_copy_label_name:
	move.b	5(a0),d0                        ; the length
	lea	6(a1),a2                        ; the copy's own buffer
	move.l	a2,(a1)                         ; its pointer
	addq.w	#6,a0                           ; the name
asm_copy_label_loop:
	move.b	(a0)+,(a2)+
	subq.b	#1,d0
	bne.s	asm_copy_label_loop
	rts
asm_symbol_type_letters:	; from: symbol_listing_tree
	dc.b	'?RA?rl??????O',0               ; one letter per symbol type for the symbol listing

;------------------------------------------------------------------------------
; Find the symbol of descriptor a0: in the local symbols, the module's, then the global ones.
; Out: Z set and a1 the node when found; else Z clear (d0 -1), and the three insert links kept.
;------------------------------------------------------------------------------
asm_find_symbol:                                ; from: asm_tree_find, asm_define_symbol, expr_symbol, dir_equ,
                                                ;   cmdline_symbols_parse, dir_rs, 5 more
	movem.l	a3-a5,-(sp)
	move.l	asm_local_tree(a6),d0           ; local symbols?
	beq.s	asm_find_symbol_module          ; no
	movea.l	d0,a2
	bsr.s	asm_tree_find                   ; search them
	beq.s	asm_find_symbol_done            ; found
	move.l	a1,asm_local_link(a6)           ; where it would go
asm_find_symbol_module:
	movea.l	asm_module_tree(a6),a2          ; the module's symbols
	bsr.s	asm_tree_find                   ; search them
	beq.s	asm_find_symbol_done            ; found
	move.l	a1,asm_module_link(a6)          ; where it would go
	movea.l	equate_tree(a6),a2              ; the global symbols
	bsr.s	asm_tree_find                   ; search them
	beq.s	asm_find_symbol_done            ; found
	move.l	a1,asm_global_link(a6)          ; where it would go
	moveq	#-1,d0                          ; not found
asm_find_symbol_done:
	movem.l	(sp)+,a3-a5
	rts

;------------------------------------------------------------------------------
; Search the tree whose root link is at a2 for the name of descriptor a0 (shorter names first, then
; by their bytes).  Node: +0 left, +4 right, +8 value, +12 flags, +13 type, +14 section, +16 locals,
; +22 length, +23 name.  Out: Z set, a1 the node; or Z clear (d0 3) and a1 the empty link to fill.
;------------------------------------------------------------------------------
asm_tree_find:                                  ; from: asm_mnemonic, asm_find_symbol, parse_register, dir_equr,
                                                ;   asm_parse_register_list, dir_reg, 4 more
	move.l	(a2),d0                         ; the root
	beq.w	asm_tree_find_empty             ; empty
	movea.l	d0,a1
	move.b	5(a0),d2                        ; the length
	movea.l	(a0),a5                         ; the name
	bra.s	asm_tree_find_node
asm_tree_find_left:
	move.l	(a1),d0                         ; the left branch
	beq.s	asm_tree_find_none              ; none: not found
	movea.l	d0,a1
asm_tree_find_node:
	cmp.b	$16(a1),d2                      ; shorter than this node's?
	bcs.s	asm_tree_find_left              ; yes: left
	bhi.s	asm_tree_find_right             ; longer: right
	move.b	d2,d3
	lea	$17(a1),a3                      ; the node's name
	movea.l	a5,a4                           ; ours
asm_tree_find_compare:
	cmpm.b	(a3)+,(a4)+
	bcs.s	asm_tree_find_left              ; lower: left
	bhi.s	asm_tree_find_right             ; higher: right
	subq.b	#1,d3
	bne.s	asm_tree_find_compare
	rts                                     ; found: Z set
asm_tree_find_right:
	move.l	4(a1),d0                        ; the right branch
	beq.s	asm_tree_find_right_link        ; none
	movea.l	d0,a1
	bra.s	asm_tree_find_node
asm_tree_find_right_link:
	addq.w	#4,a1                           ; the right link to fill
asm_tree_find_none:
	moveq	#3,d0                           ; Z clear
	rts
asm_tree_find_empty:
	movea.l	a2,a1                           ; the root link to fill
	moveq	#3,d0                           ; Z clear
	rts
asm_define_label_pass_two:	; from: asm_define_symbol
	bsr.s	asm_find_symbol                 ; find it
	bne.w	report_additional_symbol        ; missing: "additional symbol on pass 2"
	bset	#$6,$c(a1)                      ; defined in pass 2
	bne.w	report_defined_twice            ; already: "symbol defined twice"
	move.b	asm_section_type(a6),d3         ; the section type
	cmp.b	$d(a1),d3                       ; the same as in pass 1?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	cmp.l	8(a1),d4                        ; the same value?
	bne.w	report_phasing                  ; no: "phasing error"
	move.b	$17(a1),d0                      ; its first character
	cmp.b	local_char(a6),d0               ; a local?
	beq.s	asm_define_label_done           ; yes: no new scope
asm_new_local_scope:	; from: asm_define_symbol
	lea	$10(a1),a0                      ; its locals
	move.l	a0,asm_local_tree(a6)           ; the new local scope
asm_define_label_done:
	rts

;------------------------------------------------------------------------------
; Define the line's label, if it has one, at the PC.
;------------------------------------------------------------------------------
asm_define_label:	; from: asm_line, dir_iif, macro_call, find_mnemonic
	move.l	program_counter(a6),d4          ; the PC
	lea	line_label(a6),a0               ; the label
	tst.l	(a0)                            ; one?
	bne.s	asm_define_symbol               ; yes: define it
	rts
asm_align_no_label:	; from: asm_define_code_label
	btst	#$0,program_counter+3(a6)       ; the PC odd?
	bne.w	asm_pad_even                    ; yes: align it
	rts

;------------------------------------------------------------------------------
; For an instruction: make the PC even, then define the line's label there.
;------------------------------------------------------------------------------
asm_define_code_label:	; from: data_align_label, macro_call, find_mnemonic
	lea	line_label(a6),a0               ; the label
	tst.l	(a0)                            ; one?
	beq.s	asm_align_no_label              ; no: just align
	move.l	program_counter(a6),d4          ; the PC
	btst	#$0,d4                          ; odd?
	beq.s	asm_define_symbol               ; no
	bsr.w	asm_pad_even                    ; yes: align it
	lea	line_label(a6),a0
	move.l	program_counter(a6),d4          ; the even PC

;------------------------------------------------------------------------------
; Define the symbol of descriptor a0 with the value d4 in the current section (pass 1: add it; pass 2:
; check it).  A label not starting with the local character starts a new local scope.
;------------------------------------------------------------------------------
asm_define_symbol:	; from: asm_define_label, asm_define_code_label, asm_cnop, data_align_label
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	asm_define_label_pass_two       ; yes: check it
	bsr.w	asm_find_symbol                 ; find it
	beq.w	report_defined_twice            ; there: "symbol defined twice"
	move.b	asm_section_type(a6),d3         ; the section type
	move.b	6(a0),d0                        ; its first character
	cmp.b	local_char(a6),d0               ; a local?
	beq.s	asm_define_local                ; yes
	pea	asm_new_local_scope(pc)         ; afterwards a new local scope
	lea	asm_module_tree(a6),a2          ; into the module's symbols
	bra.s	asm_add_symbol
asm_define_local:
	lea	asm_local_tree(a6),a2           ; into the local symbols
	tst.l	(a2)                            ; a local scope?
	beq.w	report_local_not_allowed        ; no: "local not allowed"

;------------------------------------------------------------------------------
; Add a symbol at the insert link that asm_find_symbol left in the table at a2 (+4).
;------------------------------------------------------------------------------
asm_add_symbol:	; from: asm_define_symbol, dir_equ, cmdline_symbols_parse, dir_rs, dir_set
	movea.l	4(a2),a1                        ; the link

;------------------------------------------------------------------------------
; Make a symbol node at link a1: name from descriptor a0, value d4, type d3, the current section.
; Out: a1 the node.  Takes a new 10K block when fewer than 152 bytes are left.
;------------------------------------------------------------------------------
asm_new_symbol:	; from: asm_new_record, dir_equr, dir_reg, directive_xref, directive_macro, start_module, 1 more
	cmpi.w	#$98,asm_symbol_room(a6)        ; room?
	bcc.s	asm_new_symbol_make             ; yes
	movem.l	d3/a0-a1,-(sp)
	bsr.w	symbol_block_alloc              ; no: a new block
	movem.l	(sp)+,d3/a0-a1
asm_new_symbol_make:
	movea.l	asm_symbol_free(a6),a2          ; the free memory
	move.l	a2,(a1)                         ; linked in
	movea.l	a2,a1
	moveq	#0,d0
	move.l	d0,(a2)                         ; no left branch
	move.l	d0,4(a2)                        ; no right branch
	move.l	d4,8(a2)                        ; the value
	move.b	d3,$d(a2)                       ; the type
	move.w	d0,$14(a2)
	move.b	d0,$c(a2)                       ; no flags
	move.b	current_section(a6),$e(a2)      ; the section
	move.l	d0,$10(a2)                      ; no locals
	lea	$16(a2),a2                      ; the name
	move.b	5(a0),d0                        ; its length
	movea.l	(a0),a0
	move.b	d0,(a2)+
asm_new_symbol_name:
	move.b	(a0)+,(a2)+
	subq.b	#1,d0
	bne.s	asm_new_symbol_name
	move.l	a2,d0                           ; the node's size
	sub.l	a1,d0
	addq.l	#1,d0
	bclr	#$0,d0                          ; even
	sub.w	d0,asm_symbol_room(a6)          ; taken
	add.l	d0,asm_symbol_free(a6)
	rts

;------------------------------------------------------------------------------
; Make a symbol node with d0 bytes in all (for records such as an include file's).
;------------------------------------------------------------------------------
asm_new_record:	; from: include_open
	cmp.w	asm_symbol_room(a6),d0          ; room?
	bcs.s	asm_new_record_make             ; yes
	movem.l	d0/d3/a0-a1,-(sp)
	bsr.w	symbol_block_alloc              ; no: a new block
	movem.l	(sp)+,d0/d3/a0-a1
asm_new_record_make:
	move.l	d0,-(sp)
	bsr.s	asm_new_symbol                  ; make the node
	sub.l	d0,asm_symbol_free(a6)          ; give back its size
	add.w	d0,asm_symbol_room(a6)
	move.l	(sp)+,d0
	sub.w	d0,asm_symbol_room(a6)          ; take d0 bytes
	add.l	d0,asm_symbol_free(a6)
	rts

;------------------------------------------------------------------------------
; Evaluate the expression at a4 (d1 its first character).  Out: d2 the value, d3 its type (the section
; type in the low byte, bit 15 set for an imported symbol).  d5-d7 kept.
;------------------------------------------------------------------------------
asm_expression:                                 ; from: evaluate_no_import, ea_parse, evaluate_immediate, asm_add_quick,
                                                ;   asm_bcc_word, asm_branch_offset, 11 more
	bsr.w	reloc_terms_reset               ; no relocated terms
	lea	asm_operator_stack(a6),a0       ; the operator stack
	clr.w	(a0)                            ; empty
	lea	asm_value_stack(a6),a0          ; the value stack
	clr.w	(a0)                            ; empty
	moveq	#0,d4
	movem.l	d5-d7,-(sp)
	bsr.s	asm_parse_expression            ; parse it
	movem.l	(sp)+,d5-d7
	tst.w	asm_operator_stack(a6)          ; anything left on the stacks?
	bne.s	asm_expression_mismatch         ; yes
	tst.w	asm_value_stack(a6)
	bne.s	asm_expression_mismatch         ; yes
	rts
asm_expression_mismatch:	; from: asm_parse_expression
	moveq	#18,d0                          ; "expression mismatch"
	bra.w	asm_line_error                  ; fatal for the line

;------------------------------------------------------------------------------
; Operator characters: token, character.  Tokens: 2 (, 3 ), 4 *, 5 /, 8 =, 14 &, 15 | (and !),
; 16 ^, 17 +, 18 -, 19 ~; negative: number and string prefixes $, %, @, ' and ", and !.
;------------------------------------------------------------------------------
asm_operator_chars:	; from: expr_get_token
	dc.w	$112b,$122d,$042a,$052f,$0228,$0329,$137e,$083d
	dc.w	$0e26,$ea21,$105e,$0f7c,$fe24,$fa25,$f840,$f427
	dc.w	$f422
	dc.b	$00                             ; the end

;------------------------------------------------------------------------------
; The priority of each token 0-22 (higher binds first): * / 4, << >> 22, comparisons 20, & | ^ 18,
; + - 2, ~ 29, unary - and + 30.
;------------------------------------------------------------------------------
asm_operator_priority:	; from: asm_parse_expression
	dc.b	$00,$00,$00,$00,$04,$04,$16,$16,$14,$14,$14,$14,$14,$14,$12,$12
	dc.b	$12,$02,$02,$1d,$1e,$1e,$00

;------------------------------------------------------------------------------
; The routine for each operator token 4-21, as an offset from here.
;------------------------------------------------------------------------------
asm_operator_handlers:	; from: expr_apply_operator
	dc.w	expr_op_multiply-asm_operator_handlers
	dc.w	expr_op_divide-asm_operator_handlers
	dc.w	expr_op_shift_left-asm_operator_handlers
	dc.w	expr_op_shift_right-asm_operator_handlers
	dc.w	expr_op_equal-asm_operator_handlers
	dc.w	expr_op_not_equal-asm_operator_handlers
	dc.w	expr_op_less-asm_operator_handlers
	dc.w	expr_op_greater-asm_operator_handlers
	dc.w	expr_op_less_equal-asm_operator_handlers
	dc.w	expr_op_greater_equal-asm_operator_handlers
	dc.w	expr_op_and-asm_operator_handlers
	dc.w	expr_op_or-asm_operator_handlers
	dc.w	expr_op_xor-asm_operator_handlers
	dc.w	expr_op_add-asm_operator_handlers
	dc.w	expr_op_subtract-asm_operator_handlers
	dc.w	expr_op_not-asm_operator_handlers
	dc.w	expr_op_negate-asm_operator_handlers
	dc.w	expr_op_plus-asm_operator_handlers

;------------------------------------------------------------------------------
; Parse an expression with an operator stack and a value stack, a bracket by calling itself.
; Out: d2/d3 the value; a4 after it (or after its ")"), d7 the token that ended it.
;------------------------------------------------------------------------------
asm_parse_expression:	; from: asm_expression
	lea	asm_operator_stack(a6),a0       ; the operator stack
	move.w	(a0),d0
	addq.w	#2,(a0)+                        ; one more
	move.w	#$0,0(a0,d0.w)                  ; a 0 marker
	moveq	#1,d5                           ; an operand is wanted
	bsr.w	expr_get_token                  ; the first token
asm_parse_token:
	cmp.b	#$2,d5                          ; after an operand?
	bne.s	asm_parse_operand               ; no
	cmp.b	#$4,d7                          ; a binary operator?
	bcs.w	asm_parse_end                   ; no: the end
	cmp.b	#$16,d7
	bcc.w	asm_parse_end                   ; no: the end
asm_parse_operand:
	cmp.b	#$1,d7                          ; a value?
	bne.s	asm_parse_operator              ; no
asm_parse_push_value:
	lea	asm_value_stack(a6),a0          ; onto the value stack
	move.w	(a0),d0
	addq.w	#8,(a0)+
	move.l	d2,0(a0,d0.w)                   ; the value
	move.l	d3,4(a0,d0.w)                   ; its type
	bra.w	asm_parse_next
asm_parse_operator:
	cmp.b	#$2,d7                          ; "("?
	beq.w	asm_parse_bracket               ; yes
	cmp.b	#$4,d7                          ; an operator?
	bcs.w	asm_parse_finish                ; no: the end
	cmp.b	#$16,d7
	bcc.w	asm_parse_finish                ; no: the end
	cmp.b	#$1,d5                          ; an operand wanted?
	bne.s	asm_parse_priority              ; no: a binary operator
	cmp.b	#$11,d7                         ; "+"?
	beq.s	asm_parse_unary_plus            ; yes: unary plus
	cmp.b	#$12,d7                         ; "-"?
	beq.s	asm_parse_unary_minus           ; yes: unary minus
	cmp.b	#$4,d7                          ; "*"?
	beq.s	asm_parse_pc                    ; yes: the PC
	cmp.b	#$13,d7                         ; "~"?
	bne.w	asm_expression_mismatch         ; no: "expression mismatch"
	bra.s	asm_parse_priority
asm_parse_pc:
	move.l	program_counter(a6),d2          ; "*" is the PC
	moveq	#0,d3
	move.b	asm_section_type(a6),d3         ; in the section's type
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	asm_parse_pc_value              ; no
	addq.b	#1,relocatable_terms(a6)        ; one more relocated term
asm_parse_pc_value:
	tst.b	linkable_output(a6)             ; linkable?
	bne.s	asm_parse_push_value            ; yes: as it is
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_parse_push_value            ; no
	moveq	#0,d0
	move.b	current_section(a6),d0          ; the section
	lea	asm_section_table(a6),a0        ; the section table
	add.l	0(a0,d0.w),d2                   ; plus the section's start
	bra.s	asm_parse_push_value
asm_parse_unary_plus:
	moveq	#21,d7                          ; unary plus
	bra.s	asm_parse_priority
asm_parse_unary_minus:
	moveq	#20,d7                          ; unary minus
asm_parse_priority:
	lea	asm_operator_priority(pc),a2    ; the priorities
	lea	asm_operator_stack(a6),a0       ; the operator stack
	move.w	(a0),d0
	move.w	0(a0,d0.w),d6                   ; its top
	move.b	0(a2,d6.w),d6                   ; its priority
	cmp.b	0(a2,d7.w),d6                   ; lower than this operator's?
	bge.s	asm_parse_apply                 ; no: work it out first
	addq.w	#2,(a0)+                        ; push this one
	move.w	d7,0(a0,d0.w)
	bra.s	asm_parse_pushed_operator
asm_parse_apply:
	bsr.w	expr_apply_operator             ; work out the top operator
	bra.s	asm_parse_priority              ; try again
asm_parse_pushed_operator:
	moveq	#0,d5                           ; an operand is wanted
	bra.s	asm_parse_next
asm_parse_bracket:
	bsr.w	asm_parse_expression            ; the bracket's expression
	lea	asm_value_stack(a6),a0          ; onto the value stack
	move.w	(a0),d0
	addq.w	#8,(a0)+
	move.l	d2,0(a0,d0.w)                   ; the value
	move.l	d3,4(a0,d0.w)                   ; its type
	tst.w	d3                              ; imported?
	bpl.s	asm_parse_bracket_close         ; no
	moveq	#41,d0                          ; "XREFs not allowed within brackets"
	bsr.w	asm_error                       ; report it
asm_parse_bracket_close:
	cmp.b	#$3,d7                          ; ended by ")"?
	beq.s	asm_parse_after_bracket         ; yes
asm_missing_bracket:	; from: emit_immediate_byte
	moveq	#19,d0                          ; "missing close bracket"
	bra.w	asm_line_error                  ; fatal for the line
asm_parse_after_bracket:
	moveq	#1,d5                           ; as after an operand
asm_parse_next:
	addq.w	#1,d5
	bsr.w	expr_get_token                  ; the next token
	bra.w	asm_parse_token
asm_parse_end:
	cmp.b	#$3,d7                          ; ")"?
	beq.s	asm_parse_finish                ; yes: a4 stays after it
	movea.l	a0,a4                           ; back to the token's start
	move.b	-$1(a4),d1                      ; its first character
asm_parse_finish:
	lea	asm_operator_priority(pc),a2    ; the priorities
asm_parse_finish_loop:
	lea	asm_operator_stack(a6),a0       ; the operator stack
	move.w	(a0),d0
	tst.w	0(a0,d0.w)                      ; down to the marker?
	beq.s	asm_parse_result                ; yes
	bsr.w	expr_apply_operator             ; work out the top operator
	bra.s	asm_parse_finish_loop
asm_parse_result:
	subq.w	#2,asm_operator_stack(a6)       ; drop the marker
	lea	asm_value_stack(a6),a0          ; the value stack
	subq.w	#8,(a0)                         ; pop the result
	move.w	(a0)+,d0
	move.l	0(a0,d0.w),d2                   ; the value
	move.l	4(a0,d0.w),d3                   ; its type
	rts
asm_stack_underflow:	; from: expr_apply_operator
	bra.w	asm_expression_mismatch         ; "expression mismatch"

;------------------------------------------------------------------------------
; Apply the operator on top of the operator stack to the value stack: pop the right operand (and the left
; one for a binary operator), call the operator's handler from the table at $52c6 and push the result.
; In: d1 = the operator code (4-21).  Handlers take d2/d3 = left value and type, d0/d6 = right value and
; type, and leave the result in d2/d3; d4.b is set to $ff when the result is not known yet.
; A type long: low byte 1 = relocatable, 2 = absolute ($d after ORG); bit 15 = imported (XREF).
;------------------------------------------------------------------------------
expr_apply_operator:	; from: asm_parse_expression
	lea	asm_value_stack(a6),a0          ; the value stack
	subq.w	#8,(a0)                         ; one entry less
	bcs.s	asm_stack_underflow             ; empty: expression mismatch
	move.w	(a0)+,d0                        ; the top entry's offset
	move.l	0(a0,d0.w),d2                   ; its value
	move.l	4(a0,d0.w),d3                   ; its type
	move.w	d1,-(sp)                        ; keep the operator
	lea	asm_operator_stack(a6),a1       ; the operator stack
	subq.w	#2,(a1)                         ; pop it
	move.w	(a1)+,d1                        ; the new top
	move.w	0(a1,d1.w),d1                   ; the operator code under it
	cmp.b	#$13,d1                         ; unary (~, -, +)?
	bcc.s	expr_apply_call                 ; yes: one operand
	subq.w	#8,-(a0)                        ; binary: pop the left operand too
	bcs.s	asm_stack_underflow             ; none: expression mismatch
	move.w	(a0)+,d0
	move.l	4(a0,d0.w),d6                   ; its type
	move.l	0(a0,d0.w),d0                   ; its value
	exg	d0,d2                           ; d2/d3 = left, d0/d6 = right
	exg	d6,d3
expr_apply_call:
	lea	asm_operator_handlers(pc),a1    ; the handler table
	add.w	d1,d1
	move.w	-$8(a1,d1.w),d1                 ; its offset (from code 4)
	jsr	0(a1,d1.w)                      ; do the operator
	move.w	(sp)+,d1
	move.w	-(a0),d0                        ; push the result
	addq.w	#8,(a0)+
	move.l	d2,0(a0,d0.w)                   ; its value
	move.l	d3,4(a0,d0.w)                   ; and type
	rts

;------------------------------------------------------------------------------
; Operator +: add; relocatable + relocatable is a type error, relocatable + absolute stays relocatable.
;------------------------------------------------------------------------------
expr_op_add:	; from: asm_operator_handlers
	add.l	d0,d2                           ; +
	cmp.b	#$1,d3                          ; left relocatable?
	beq.s	expr_add_relative               ; yes
	cmp.b	#$1,d6                          ; right relocatable?
	beq.s	expr_add_result_relative        ; yes: the result is
expr_add_flags:
	andi.w	#$ff00,d6                       ; the right operand's flags
	or.w	d6,d3                           ; into the result's
	rts
expr_add_relative:
	cmp.b	#$1,d6                          ; both relocatable?
	beq.s	expr_type_error                 ; yes: type error
expr_add_result_relative:
	move.b	#$1,d3                          ; the result is relocatable
	bra.s	expr_add_flags

;------------------------------------------------------------------------------
; Illegal type combination: error 21 on pass 2 (none with OPT T-); the value is marked not known (d4) and
; the result made absolute (d3 = 2).
;------------------------------------------------------------------------------
expr_type_error:	; from: expr_op_add, expr_op_subtract, expr_need_absolute, expr_op_equal, expr_op_not
	tst.b	type_check_off(a6)              ; OPT T-?
	bne.s	expr_type_error_done            ; yes: no error
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	expr_unresolved                 ; no: only mark it
	moveq	#21,d0                          ; illegal type combination
expr_report_error:	; from: expr_op_divide
	bsr.w	asm_error                       ; report error d0
expr_unresolved:	; from: expr_op_divide
	st	d4                              ; the value is not known
expr_type_error_done:
	moveq	#2,d3                           ; absolute
	rts
expr_imported_error:	; from: expr_need_absolute, expr_op_equal
	moveq	#20,d0                          ; imported label not allowed
	bra.s	expr_report_error

;------------------------------------------------------------------------------
; Operator -: subtract; relocatable - relocatable gives absolute, absolute - relocatable is a type error.
; An imported right operand turns its reference into a subtracted one.
;------------------------------------------------------------------------------
expr_op_subtract:	; from: asm_operator_handlers
	sub.l	d0,d2                           ; -
	move.w	d3,d0                           ; the imported flags of both
	or.w	d6,d0
	andi.w	#$8000,d0
	tst.w	d6                              ; right imported?
	bmi.s	expr_sub_imported               ; yes: mark its reference subtracted
	cmp.b	#$1,d6                          ; right relocatable?
	bne.s	expr_sub_types                  ; no
	subq.b	#2,relocatable_terms(a6)        ; one relocatable term taken off (it was counted once)
expr_sub_types:
	cmp.b	d3,d6                           ; the same type?
	beq.s	expr_sub_absolute               ; yes: absolute
	cmp.b	#$1,d6                          ; right relocatable (left absolute)?
	bne.s	expr_sub_flags                  ; no: left relocatable stays
	bsr.s	expr_type_error                 ; yes: type error
expr_sub_absolute:
	move.b	#$2,d3                          ; absolute
expr_sub_flags:
	or.w	d0,d3                           ; the imported flag
	rts
expr_sub_imported:
	bsr.w	reloc_term_negate               ; the last reference becomes '--'
	bra.s	expr_sub_types

;------------------------------------------------------------------------------
; Operator *: both absolute; signed multiply.
;------------------------------------------------------------------------------
expr_op_multiply:	; from: asm_operator_handlers
	bsr.s	expr_need_absolute              ; *: both absolute?
	bsr.w	expr_multiply                   ; multiply
	moveq	#2,d3                           ; absolute
	rts

;------------------------------------------------------------------------------
; Check both operands are absolute and not imported: a type error (or error 20) if not.
;------------------------------------------------------------------------------
expr_need_absolute:	; from: expr_op_multiply, expr_op_divide, expr_op_and
	cmp.b	#$1,d6                          ; right relocatable?
	beq.s	expr_type_error                 ; yes: type error
	or.w	d3,d6                           ; either imported?
	bmi.s	expr_imported_error             ; yes: imported label not allowed
	cmp.b	#$1,d3                          ; left relocatable?
	beq.s	expr_type_error                 ; yes: type error
	rts

;------------------------------------------------------------------------------
; Operator /: both absolute; signed divide (error 59 on pass 2 for a divide by 0).
;------------------------------------------------------------------------------
expr_op_divide:	; from: asm_operator_handlers
	bsr.s	expr_need_absolute              ; /: both absolute?
	move.l	d7,-(sp)
	bsr.w	expr_divide                     ; divide
	movem.l	(sp)+,d7
	bne.s	expr_divide_error               ; divide by 0?
	rts
expr_divide_error:
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	expr_report_error               ; yes: report it
	bra.s	expr_unresolved                 ; no: only mark the value not known

;------------------------------------------------------------------------------
; Operators & | ^ << >>: both absolute.
;------------------------------------------------------------------------------
expr_op_and:	; from: asm_operator_handlers
	and.l	d0,d2                           ; &
	bra.s	expr_need_absolute
expr_op_or:	; from: asm_operator_handlers
	or.l	d0,d2                           ; |
	bra.s	expr_need_absolute
expr_op_xor:	; from: asm_operator_handlers
	eor.l	d0,d2                           ; ^
	bra.s	expr_need_absolute
expr_op_shift_left:	; from: asm_operator_handlers
	lsl.l	d0,d2                           ; <<
	bra.s	expr_need_absolute
expr_op_shift_right:	; from: asm_operator_handlers
	lsr.l	d0,d2                           ; >>
	bra.s	expr_need_absolute

;------------------------------------------------------------------------------
; Comparisons = <> < > <= >=: -1 for true, 0 for false; both of one type.
;------------------------------------------------------------------------------
expr_op_equal:	; from: asm_operator_handlers
	cmp.l	d0,d2                           ; =
	seq	d2
expr_compare_result:
	ext.w	d2                              ; the byte to a long: 0 or -1
	ext.l	d2
	move.w	d3,d0
	or.w	d6,d0                           ; either imported?
	bmi.w	expr_imported_error             ; yes: imported label not allowed
	cmp.b	d3,d6                           ; the same type?
	beq.s	expr_compare_absolute           ; yes: fine
	cmp.b	#$1,d3                          ; one relocatable: type error
	beq.w	expr_type_error
	cmp.b	#$1,d6
	beq.w	expr_type_error
expr_compare_absolute:
	moveq	#2,d3                           ; the result is absolute
	rts
expr_op_not_equal:	; from: asm_operator_handlers
	cmp.l	d0,d2                           ; <>
	sne	d2
	bra.s	expr_compare_result
expr_op_less:	; from: asm_operator_handlers
	cmp.l	d0,d2                           ; <
	slt	d2
	bra.s	expr_compare_result
expr_op_greater:	; from: asm_operator_handlers
	cmp.l	d0,d2                           ; >
	sgt	d2
	bra.s	expr_compare_result
expr_op_less_equal:	; from: asm_operator_handlers
	cmp.l	d0,d2                           ; <=
	sle	d2
	bra.s	expr_compare_result
expr_op_greater_equal:	; from: asm_operator_handlers
	cmp.l	d0,d2                           ; >=
	sge	d2
	bra.s	expr_compare_result

;------------------------------------------------------------------------------
; Unary ~ and -: the operand must not be relocatable.  Unary + is the rts at $5598.
;------------------------------------------------------------------------------
expr_op_not:	; from: asm_operator_handlers
	not.l	d2                              ; ~
expr_unary_check:
	cmp.w	#$1,d3                          ; relocatable?
	beq.w	expr_type_error                 ; yes: type error
expr_op_plus:	; from: asm_operator_handlers
	rts                                     ; (also unary +)
expr_op_negate:	; from: asm_operator_handlers
	neg.l	d2                              ; unary -
	bra.s	expr_unary_check

;------------------------------------------------------------------------------
; Signed 32-bit multiply: d2 = d2 * d0 (the low 32 bits).  Changes d0, d3, d6.
;------------------------------------------------------------------------------
expr_multiply:	; from: expr_op_multiply
	move.l	d2,d6                           ; the result's sign
	eor.l	d0,d6
	tst.l	d2                              ; make both positive
	bgt.s	expr_multiply_sign
	neg.l	d2
expr_multiply_sign:
	tst.l	d0
	bgt.s	expr_multiply_parts
	neg.l	d0
expr_multiply_parts:
	move.l	d2,d3                           ; d3 = the left's high word
	swap	d3
	mulu.w	d0,d2                           ; low * low
	swap	d0                              ; the right's high word
	tst.w	d3                              ; left high word 0?
	beq.s	expr_multiply_high_right        ; yes: try the right's
	swap	d0                              ; no: left high * right low
	bra.s	expr_multiply_cross
expr_multiply_high_right:
	tst.w	d0                              ; both high words 0?
	beq.s	expr_multiply_negate            ; yes: done
	swap	d3                              ; the left's low word
expr_multiply_cross:
	mulu.w	d3,d0                           ; the cross product
	swap	d0                              ; into the high word
	add.l	d0,d2
expr_multiply_negate:
	tst.l	d6                              ; negative result?
	bpl.s	expr_multiply_done
	neg.l	d2
expr_multiply_done:
	rts

;------------------------------------------------------------------------------
; Signed 32-bit divide: d2 = d2 / d0, d0 = the remainder (with the dividend's sign).  Z set when done;
; d0 = 59 (division by zero) and Z clear when d0 was 0.  Changes d6, d7.
;------------------------------------------------------------------------------
expr_divide:	; from: expr_op_divide, asm_cnop
	tst.l	d0                              ; by 0?
	beq.s	expr_divide_by_zero             ; yes
	move.l	d2,d6                           ; the quotient's sign
	eor.l	d0,d6
	move.l	d6,-(sp)
	move.l	d2,-(sp)                        ; the dividend's sign
	tst.l	d0                              ; make both positive
	bpl.s	expr_divide_abs
	neg.l	d0
expr_divide_abs:
	tst.l	d2
	bpl.s	expr_divide_start
	neg.l	d2
expr_divide_start:
	moveq	#31,d6                          ; 32 shifts at most
	move.l	d0,d7                           ; the divisor
	moveq	#0,d0                           ; the quotient
expr_divide_align:
	add.l	d7,d7                           ; shift the divisor up to its top bit
	dbcs	d6,expr_divide_align
	roxr.l	#1,d7                           ; the bit back
	subi.w	#$1f,d6                         ; d6 = the number of shifts
	neg.w	d6
expr_divide_loop:
	add.l	d0,d0                           ; the next quotient bit
	cmp.l	d7,d2                           ; does it go?
	bcs.s	expr_divide_next                ; no
	addq.l	#1,d0                           ; yes
	sub.l	d7,d2
expr_divide_next:
	lsr.l	#1,d7
	dbra	d6,expr_divide_loop
	move.l	(sp)+,d6                        ; the dividend's sign
	bpl.s	expr_divide_quotient_sign
	neg.l	d2                              ; on the remainder
expr_divide_quotient_sign:
	move.l	(sp)+,d6                        ; the quotient's sign
	bpl.s	expr_divide_done
	neg.l	d0
expr_divide_done:
	exg	d0,d2                           ; d2 = quotient, d0 = remainder
	cmp.b	d0,d0                           ; Z set
	rts
expr_divide_by_zero:
	moveq	#59,d0                          ; division by zero
	rts                                     ; Z clear
expr_token_end:	; from: expr_get_token
	movea.l	a4,a0                           ; the end of the expression
	rts

;------------------------------------------------------------------------------
; Read the next expression token.  In: d1 = its first character, a4 just past it.
; Out: d7 = the token code: 1 value (d2 = value, d3 = type), 2 (, 3 ), 4 *, 5 /, 6 <<, 7 >>, 8 =, 9 <> or !=,
; 10 <, 11 >, 12 <=, 13 >=, 14 &, 15 | or !, 16 ^, 17 +, 18 -, 19 ~, 22 the end (space, tab, comma, CR,
; anything else); d1 = the character after the token, a0 = a4 on entry (to put the token back).
; Numbers: decimal, $hex, %binary, @octal, 'text' or "text" (up to 4 characters); symbols and nn$ locals.
;------------------------------------------------------------------------------
expr_get_token:	; from: asm_parse_expression
	moveq	#22,d7                          ; the end
	cmp.b	#$d,d1                          ; CR?
	beq.s	expr_token_end
	cmp.b	#$9,d1                          ; tab?
	beq.s	expr_token_end
	cmp.b	#$20,d1                         ; space?
	beq.s	expr_token_end
	cmp.b	#$2c,d1                         ; comma?
	beq.s	expr_token_end
	movem.l	d5-d6/a1-a2,-(sp)
	move.l	a4,-(sp)                        ; the position for a0
	moveq	#0,d7
	cmp.b	#$41,d1                         ; a letter?
	bcs.s	expr_token_operator
	cmp.b	#$5b,d1                         ; A-Z: a symbol
	bcs.s	expr_token_symbol
	cmp.b	#$61,d1
	bcs.s	expr_token_operator
	cmp.b	#$7b,d1                         ; a-z: a symbol
	bcs.s	expr_token_symbol
expr_token_operator:
	lea	asm_operator_chars(pc),a0       ; the table of operator characters
expr_token_operator_loop:
	move.b	(a0)+,d7                        ; the code
	beq.s	expr_token_other                ; the end of the table
	cmp.b	(a0)+,d1                        ; this character?
	bne.s	expr_token_operator_loop        ; no: the next pair
	tst.b	d7                              ; a number prefix or quote?
	bmi.w	expr_token_prefixed             ; yes
	bra.s	expr_token_next_char            ; an operator
expr_token_other:
	cmp.b	#$3c,d1                         ; <?
	beq.s	expr_token_less
	cmp.b	#$3e,d1                         ; >?
	beq.s	expr_token_greater
	moveq	#0,d2
	cmp.b	#$3a,d1                         ; a digit?
	bcc.s	expr_token_symbol               ; no: try a symbol
	cmp.b	#$30,d1
	bcc.s	expr_token_decimal              ; yes: decimal
expr_token_symbol:
	lea	name_buffer(a6),a0              ; the name buffer
	bsr.w	read_symbol_name                ; read a name
	beq.w	expr_symbol                     ; got one
	moveq	#22,d7                          ; no: the end
	bra.s	expr_token_done
expr_token_not_equal:
	move.b	(a4)+,d1                        ; after !: = ?
	cmp.b	#$3d,d1
	beq.s	expr_token_ne                   ; yes: != is <>
	moveq	#15,d7                          ; no: ! is |
	bra.s	expr_token_done
expr_token_less:
	moveq	#10,d7                          ; <
	move.b	(a4)+,d1
	cmp.b	#$3c,d1                         ; <<?
	beq.s	expr_token_shift
	cmp.b	#$3e,d1                         ; <>?
	beq.s	expr_token_ne
	bra.s	expr_token_or_equal             ; <=?
expr_token_ne:
	moveq	#9,d7                           ; <>
	bra.s	expr_token_next_char
expr_token_greater:
	moveq	#11,d7                          ; >
	move.b	(a4)+,d1
	cmp.b	#$3e,d1                         ; >>?
	beq.s	expr_token_shift
expr_token_or_equal:
	cmp.b	#$3d,d1                         ; <= or >=?
	bne.s	expr_token_done                 ; no: < or >
	addq.w	#2,d7                           ; 12 or 13
	bra.s	expr_token_next_char
expr_token_shift:
	subq.w	#4,d7                           ; 6 or 7
expr_token_next_char:
	move.b	(a4)+,d1                        ; the next character
expr_token_done:	; from: expr_symbol, expr_local_number
	movea.l	(sp)+,a0                        ; a0 = the position on entry
	movem.l	(sp)+,d5-d6/a1-a2
	rts
expr_token_decimal:
	lea	-$1(a4),a0                      ; the number's start (for nn$)
expr_decimal_loop:
	add.l	d2,d2                           ; value * 10
	move.l	d2,d0
	add.l	d0,d0
	add.l	d0,d0
	add.l	d0,d2
	subi.b	#$30,d1                         ; the digit
	andi.l	#$f,d1
	add.l	d1,d2                           ; added
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$3a,d1                         ; a digit?
	bcc.s	expr_decimal_end
	cmp.b	#$30,d1
	bcc.s	expr_decimal_loop               ; yes: on
expr_decimal_end:
	moveq	#1,d7                           ; a value
	moveq	#2,d3                           ; absolute
	cmp.b	#$24,d1                         ; nn$: a numbered local label?
	bne.s	expr_token_done                 ; no
	bra.w	expr_local_number               ; yes
expr_token_string:
	moveq	#4,d0                           ; 4 characters at most
	move.b	d1,d3                           ; the quote
expr_string_loop:
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$d,d1                          ; the line's end?
	beq.w	expr_invalid_number             ; yes: invalid number
	cmp.b	d3,d1                           ; the quote?
	bne.s	expr_string_char                ; no: a character
	move.b	(a4)+,d1                        ; doubled?
	cmp.b	d3,d1
	beq.s	expr_string_char                ; yes: one quote character
	moveq	#2,d3                           ; no: the end, absolute
	bra.s	expr_token_done
expr_string_char:
	subq.b	#1,d0                           ; room for it?
	bcs.w	expr_number_too_large           ; no: number too large
	lsl.l	#8,d2                           ; in at the bottom
	move.b	d1,d2
	bra.s	expr_string_loop
expr_token_binary:
	move.b	(a4)+,d1                        ; %: the first digit
	subi.b	#$30,d1
	bcs.w	expr_invalid_number             ; not 0 or 1: invalid number
	cmp.b	#$2,d1
	bcc.w	expr_invalid_number
expr_binary_loop:
	add.l	d2,d2                           ; shift in the bit
	bcs.w	expr_number_too_large           ; overflow: number too large
	or.b	d1,d2
	move.b	(a4)+,d1                        ; the next character
	subi.b	#$30,d1
	bcs.s	expr_number_end                 ; not a digit: the end
	cmp.b	#$2,d1
	bcs.s	expr_binary_loop                ; 0 or 1: on
	bra.s	expr_number_end
expr_token_prefixed:
	neg.b	d7                              ; the table's negative code: an index
	ext.w	d7
	moveq	#0,d2                           ; the value 0
	moveq	#2,d3                           ; absolute
	moveq	#1,d0
	exg	d0,d7                           ; d7 = 1 (a value), d0 = the index
expr_prefix_jump:
	jmp	expr_prefix_jump+2(pc,d0.w)     ; go to the prefix's routine
	bra.w	expr_token_hex                  ; 2: $ hex
	bra.s	expr_token_binary               ; 6: % binary
	bra.w	expr_token_octal                ; 8: @ octal
	bra.s	expr_token_string               ; 12: ' or " text
	bra.w	expr_token_less                 ; 14: (not in the table)
	bra.w	expr_token_greater              ; 18: (not in the table)
	bra.w	expr_token_not_equal            ; 22: ! (or !=)
expr_octal_not:
	moveq	#64,d1                          ; @ without a digit: the start of a name
	bra.w	expr_token_symbol
expr_token_octal:
	move.b	(a4),d0                         ; @: the first digit
	subi.b	#$30,d0
	bcs.s	expr_octal_not                  ; none: a name
	cmp.b	#$9,d0
	bcc.s	expr_octal_not
	move.b	d0,d1
	addq.l	#1,a4                           ; past it
expr_octal_loop:
	lsl.l	#3,d2                           ; shift in the digit
	bcs.s	expr_number_too_large           ; overflow: number too large
	or.b	d1,d2
	move.b	(a4)+,d1                        ; the next character
	subi.b	#$30,d1
	bcs.s	expr_number_end                 ; not a digit: the end
	cmp.b	#$9,d1
	bcs.s	expr_octal_loop
	bra.s	expr_number_end
expr_token_hex:
	lea	hex_digit_table(pc),a0          ; $: the hex digit table
	moveq	#0,d1
	move.b	(a4)+,d1                        ; the first digit
	bmi.s	expr_invalid_number             ; not ASCII: invalid number
	move.b	0(a0,d1.w),d1                   ; its value
	bmi.s	expr_invalid_number             ; not a digit: invalid number
expr_hex_loop:
	lsl.l	#4,d2                           ; shift it in
	or.b	d1,d2
	move.b	(a4)+,d1                        ; the next character
	bmi.s	expr_number_end                 ; not ASCII: the end
	move.b	0(a0,d1.w),d1                   ; its value
	bpl.s	expr_hex_loop                   ; a digit: on
expr_number_end:
	move.b	-$1(a4),d1                      ; the character after the number
	bra.w	expr_token_done
expr_invalid_number:
	moveq	#22,d0                          ; invalid number
expr_number_error:
	bsr.w	asm_error                       ; report it
	st	d4                              ; the value is not known
	bra.s	expr_number_end
expr_number_too_large:
	moveq	#23,d0                          ; number too large
	bra.s	expr_number_error

;------------------------------------------------------------------------------
; 128 bytes, one per ASCII character: its hex digit value, or $ff when it is not one.
;------------------------------------------------------------------------------
hex_digit_table:	; from: expr_get_token
	dcb.w	24,$ffff                        ; $00-$2f: none
	dc.w	$0001,$0203,$0405,$0607,$0809,$ffff,$ffff,$ffff ; 0-9, then none
	dc.w	$ff0a,$0b0c,$0d0e,$0fff,$ffff,$ffff,$ffff,$ffff ; A-F
	dcb.w	8,$ffff
	dc.w	$ff0a,$0b0c,$0d0e,$0fff,$ffff,$ffff,$ffff,$ffff ; a-f
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff

;------------------------------------------------------------------------------
; Give the value of a 4-character reserved symbol: NARG (the macro's argument count, 0 outside a macro),
; __LK (0 executable, 1 GST, 2 DRI), __G2 (42) or __RS (the RS counter).  In: a0 = the name buffer.
; Out: Z set and d2 = the value when it is one, d0 = 0.
;------------------------------------------------------------------------------
expr_reserved_symbol:	; from: expr_symbol, ifd_test, macro_expand_put
	movea.l	(a0),a1                         ; the name
	subq.l	#4,sp
	move.b	(a1)+,2(sp)                     ; its first 4 characters
	move.b	(a1)+,3(sp)                     ; as c3 c4 c1 c2
	move.b	(a1)+,(sp)
	move.b	(a1)+,1(sp)
	move.l	(sp)+,d0
	cmp.l	#$52474e41,d0                   ; NARG?
	beq.s	expr_reserved_narg              ; yes
	cmp.w	#$5f5f,d0                       ; __ at the start?
	bne.s	expr_reserved_done              ; no
	swap	d0                              ; the last two
	cmp.w	#$5253,d0                       ; __RS?
	beq.s	expr_reserved_rs
	cmp.w	#$4732,d0                       ; __G2?
	beq.s	expr_reserved_g2
	cmp.w	#$4c4b,d0                       ; __LK?
	beq.s	expr_reserved_lk
	bne.s	expr_reserved_done              ; none of them
expr_reserved_lk:
	moveq	#0,d2                           ; __LK: 0 for an executable
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	expr_reserved_found             ; no
	move.w	linker_format(a6),d2            ; the linker format + 1
	addq.w	#1,d2
	bra.s	expr_reserved_found
expr_reserved_g2:
	moveq	#42,d2                          ; __G2
expr_reserved_found:
	moveq	#0,d0                           ; Z set
	rts
expr_reserved_rs:
	move.l	rs_counter(a6),d2               ; __RS: the RS counter
	bra.s	expr_reserved_found
expr_reserved_done:
	rts
expr_reserved_narg:
	moveq	#0,d2                           ; NARG: 0 outside a macro
	tst.b	in_macro(a6)                    ; in a macro?
	beq.s	expr_reserved_done              ; no: Z set
	movea.l	macro_frame(a6),a1              ; the macro's frame
	move.w	8(a1),d2                        ; its argument count
	bra.s	expr_reserved_found

;------------------------------------------------------------------------------
; A name was read into the name buffer (a0): its value as a token.  Pass 1 takes unknown names as 0 not
; known; pass 2 reports them.  Relocatable values get their section's base (or a linker reference).
; A '#' after a name is skipped (in linkable output it sets the buffer's flag at +4).
;------------------------------------------------------------------------------
expr_symbol:	; from: expr_get_token
	moveq	#1,d7                           ; a value
	cmp.b	#$23,d1                         ; # after it?
	seq	4(a0)
	bne.s	expr_symbol_reserved            ; no
	move.b	(a4)+,d1                        ; skip it
	tst.b	linkable_output(a6)
	sne	4(a0)
expr_symbol_reserved:
	cmpi.b	#$4,5(a0)                       ; 4 characters long?
	bne.s	expr_symbol_lookup              ; no
	bsr.w	expr_reserved_symbol            ; a reserved symbol?
	bne.s	expr_symbol_lookup              ; no
	moveq	#2,d3                           ; yes: absolute
	bra.s	expr_symbol_done
expr_symbol_lookup:	; from: expr_local_number
	tst.b	pass_two(a6)                    ; pass 2?
	bne.w	expr_symbol_pass2               ; yes
	bsr.w	asm_find_symbol                 ; find the symbol
	beq.s	expr_symbol_pass1_found         ; found
	moveq	#0,d2                           ; not yet defined: 0
	st	d4                              ; not known
	moveq	#2,d3                           ; absolute
	tst.b	4(a0)
	beq.s	expr_symbol_done
	bra.s	expr_symbol_done
expr_symbol_pass1_found:
	move.l	8(a1),d2                        ; its value
	moveq	#0,d3
	move.b	$d(a1),d3                       ; its type
	btst	#$4,$c(a1)                      ; an XREF?
	bne.s	expr_symbol_xref                ; yes
expr_symbol_type:
	cmp.b	#$2,d3                          ; absolute?
	beq.s	expr_symbol_done
	cmp.b	#$d,d3                          ; absolute after ORG?
	beq.s	expr_symbol_done
	cmp.b	#$1,d3                          ; relocatable?
	beq.s	expr_symbol_relative
	cmp.b	#$5,d3                          ; a register list?
	bne.w	expr_symbol_misuse              ; no: misuse of label
	moveq	#2,d3                           ; yes: taken as absolute
	moveq	#7,d0                           ; misuse of register list
	bsr.w	asm_warning                     ; warn
expr_symbol_done:
	move.b	-$1(a4),d1                      ; the character after the name
	bra.w	expr_token_done
expr_symbol_xref:
	st	d4                              ; an XREF: not known
	swap	d3
	move.w	$14(a1),d3                      ; its import number
	bsr.w	reloc_term_import               ; add it to the reference list
	swap	d3
	move.b	-$1(a4),d1                      ; the character after the name
	tst.b	pass_two(a6)                    ; pass 2?
	beq.w	expr_token_done                 ; no
	ori.w	#$8000,d3                       ; yes: imported
	bra.w	expr_token_done
expr_symbol_relative:
	tst.b	linkable_output(a6)             ; linkable output?
	bne.s	expr_symbol_section             ; yes
	tst.b	$e(a1)                          ; in the TEXT section?
	beq.s	expr_symbol_done                ; yes: known
expr_symbol_section:
	move.b	current_section(a6),d0          ; in the current section?
	cmp.b	$e(a1),d0
	beq.s	expr_symbol_done                ; yes: known
	st	d4                              ; no: not known until the sections are placed
	bra.s	expr_symbol_done
expr_symbol_pass2:
	bsr.w	asm_find_symbol                 ; find the symbol
	sne	d0                              ; d0 nonzero: not found
	move.b	-$1(a4),d1
	cmp.b	#$23,d1                         ; # after it?
	bne.s	expr_symbol_pass2_check
	move.b	(a4)+,d1                        ; skip it
expr_symbol_pass2_check:
	tst.b	d0                              ; not found?
	bne.w	expr_symbol_undefined           ; undefined symbol
	btst	#$7,$c(a1)                      ; a SET symbol?
	beq.s	expr_symbol_pass2_value
	btst	#$6,$c(a1)                      ; not set yet on pass 2?
	beq.w	expr_symbol_undefined           ; undefined symbol
expr_symbol_pass2_value:
	move.l	8(a1),d2                        ; its value
	moveq	#0,d3
	move.b	$d(a1),d3                       ; its type
	tst.b	linkable_output(a6)             ; linkable output?
	bne.s	expr_symbol_linker              ; yes
	cmp.b	#$1,d3                          ; relocatable?
	bne.w	expr_symbol_type                ; no: check the type
	moveq	#0,d0                           ; yes: add its section's base
	move.b	$e(a1),d0
	lea	asm_section_table(a6),a0
	add.l	0(a0,d0.w),d2
	bra.w	expr_token_done
expr_symbol_linker:
	btst	#$4,$c(a1)                      ; an XREF?
	bne.w	expr_symbol_xref                ; yes
	cmp.b	#$1,d3                          ; relocatable?
	bne.w	expr_symbol_type                ; no: check the type
	move.b	current_section(a6),d0          ; in the current section?
	cmp.b	$e(a1),d0
	bne.s	expr_symbol_other_section       ; no
	addq.b	#1,relocatable_terms(a6)        ; yes: one more relocatable term
	bra.w	expr_token_done
expr_symbol_other_section:
	ori.w	#$8000,d3                       ; another section: imported
	st	d4                              ; not known
	bsr.w	reloc_term_section              ; add a section reference
	bra.w	expr_token_done

;------------------------------------------------------------------------------
; nn$: make the local label name (the local prefix character and the digits) in the name buffer and
; look it up as a symbol.  In: a0 = the first digit, a4 past the $.
;------------------------------------------------------------------------------
expr_local_number:	; from: expr_get_token
	movea.l	a0,a1                           ; the digits
	lea	name_buffer(a6),a0              ; the name buffer
	lea	6(a0),a2                        ; its text
	move.l	a2,(a0)                         ; the name pointer
	sf	4(a0)                           ; no flag
	move.b	local_char(a6),(a2)+            ; the local prefix character
	move.l	a4,d0
	sub.l	a1,d0                           ; the digits and the $
	move.b	d0,5(a0)                        ; the name's length
	subq.b	#1,d0                           ; the digits
expr_local_number_copy:
	move.b	(a1)+,(a2)+
	subq.b	#1,d0
	bne.s	expr_local_number_copy
	move.b	(a4)+,d1                        ; the next character
	moveq	#1,d7                           ; a value
	bra.w	expr_symbol_lookup              ; look it up
expr_symbol_misuse:	; from: expr_symbol
	moveq	#24,d0                          ; misuse of label
expr_symbol_error:
	moveq	#2,d3                           ; absolute
	st	d4                              ; not known
	bsr.w	asm_error                       ; report it
	bra.w	expr_token_done
expr_symbol_undefined:	; from: expr_symbol
	moveq	#3,d0                           ; undefined symbol
	bra.s	expr_symbol_error

;------------------------------------------------------------------------------
; Evaluate an expression (asm_expression) that may not be imported: in linkable output an XREF gives error 20.
; Out: d2 value, d3 type, d4.b nonzero when not known, d1 the next character.
;------------------------------------------------------------------------------
evaluate_no_import:	; from: evaluate_absolute, dir_equ, ins_movep, dir_set, ins_trap
	bsr.w	asm_expression                  ; evaluate
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	evaluate_no_import_done         ; no
	tst.w	d3                              ; imported?
	bmi.s	evaluate_no_import_error        ; yes
evaluate_no_import_done:
	rts
evaluate_no_import_error:
	st	d4                              ; not known
	moveq	#20,d0                          ; imported label not allowed
	bra.w	asm_error

;------------------------------------------------------------------------------
; Evaluate an expression that must not be imported or relocatable (error 32 unless OPT T-).  d0 = 0.
;------------------------------------------------------------------------------
evaluate_absolute:	; from: dir_listchar, ins_addq_subq, dir_rs, dir_rsset, ins_shift, dir_spc, 1 more
	bsr.s	evaluate_no_import              ; evaluate
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	evaluate_absolute_done          ; no
	tst.b	type_check_off(a6)              ; OPT T-?
	beq.w	err_absolute_not_allowed        ; no: error 32
evaluate_absolute_done:
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Parse an effective address, OR its mode into the opcode at instruction_start and check it against the
; mode mask in the word after the call (see ea_check_mode); returns past that word.
;------------------------------------------------------------------------------
ea_parse_check:	; from: asm_addi_subi_cmpi, asm_btst, asm_bit_change, ins_logic_imm, ins_move_from_sr, ins_movem
	movea.l	(sp),a0                         ; the mask word
	addq.l	#2,(sp)                         ; return past it
	bra.s	ea_parse_check_mask

;------------------------------------------------------------------------------
; As ea_parse_check, but first write the opcode d6 to the code (a5)+.
;------------------------------------------------------------------------------
ea_store_parse_check:                           ; from: asm_add_quick, asm_adda_suba_cmpa, asm_chk_mul_div, ins_jmp_jsr,
                                                ;   ins_lea, ins_addq_subq, 6 more
	movea.l	(sp),a0                         ; the mask word
	addq.l	#2,(sp)                         ; return past it
	move.w	d6,(a5)+                        ; the opcode
ea_parse_check_mask:	; from: ea_parse_check
	move.w	(a0),d0                         ; the mask
	move.w	d0,-(sp)
	btst	#$6,d0                          ; PC-relative allowed?
	beq.s	ea_parse_check_no_pc            ; no
	bsr.w	ea_parse_pc_allowed             ; yes: parse it, OPT A applies
	move.w	(sp)+,d0                        ; the mask
	bra.s	ea_or_check
ea_parse_check_no_pc:
	bsr.w	ea_parse                        ; parse it
	move.w	(sp)+,d0                        ; the mask

;------------------------------------------------------------------------------
; OR the mode d5 into the opcode at instruction_start, then check it (ea_check_mode).
;------------------------------------------------------------------------------
ea_or_check:	; from: ea_store_parse_check, ins_logic, ins_movem, ins_shift
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	or.w	d5,(a0)                         ; the mode into it

;------------------------------------------------------------------------------
; Check mode d5 against mask d0: bit 0 Dn, 1 An, 2 (An), 3 (An)+, 4 -(An), 5 d16(An), d8(An,Xn) and
; absolute, 6 PC-relative, 7 #immediate; the high byte allows CCR (1), SR (2), USP (4).  A special register
; that is allowed returns 2 bytes past the caller's return (it skips the instruction after the call).
; Error 17 (addressing mode not allowed) when it is not in the mask.
;------------------------------------------------------------------------------
ea_check_mode:	; from: asm_add_subtract, asm_cmp, ins_logic
	cmp.b	#$30,d5                         ; Dn to d16(An)?
	bcs.s	ea_check_basic                  ; yes: the mode's bit
	cmp.b	#$3a,d5                         ; d8(An,Xn) or absolute?
	bcs.s	ea_check_memory                 ; yes: bit 5
	cmp.b	#$3c,d5                         ; #immediate?
	beq.s	ea_check_immediate              ; yes: bit 7
	btst	#$6,d5                          ; a special register?
	bne.s	ea_check_special                ; yes
	btst	#$6,d0                          ; PC-relative: bit 6
	beq.s	ea_mode_not_allowed
	rts
ea_check_memory:
	btst	#$5,d0                          ; bit 5
	beq.s	ea_mode_not_allowed
	rts
ea_check_immediate:
	tst.b	d0                              ; bit 7
	bpl.s	ea_mode_not_allowed
	rts
ea_check_basic:
	move.b	d5,d2                           ; the mode number
	lsr.b	#3,d2
	btst	d2,d0                           ; its bit
	beq.s	ea_mode_not_allowed
	rts
ea_mode_not_allowed:                            ; from: asm_abcd_sbcd, asm_add_subtract, asm_cmp, asm_postinc_register,
                                                ;   ins_logic, ins_move, 1 more
	moveq	#17,d0                          ; addressing mode not allowed
	bra.w	asm_error
ea_check_special:
	andi.w	#$bf,d5                         ; the register's bit
	move.w	d5,d2
	rol.w	#8,d2                           ; into the high byte
	and.w	d2,d0                           ; allowed?
	beq.s	ea_mode_not_allowed             ; no
	movea.l	(sp)+,a0                        ; yes: return past the next instruction
	jmp	2(a0)
ea_data_register_missing:	; from: parse_data_register
	moveq	#36,d0                          ; data register expected
	bra.w	asm_line_error

;------------------------------------------------------------------------------
; Parse a data register (fatal error 36 if it is not one).  Out: d2 = its number, d1 the next character.
;------------------------------------------------------------------------------
parse_data_register:	; from: asm_btst, asm_bit_change, asm_chk_mul_div, asm_dbcc, ins_ext, ins_logic, 4 more
	bsr.s	parse_register                  ; a register?
	bne.s	ea_data_register_missing        ; no
	tst.b	d0                              ; an address register?
	bne.s	ea_data_register_missing        ; yes
	rts

;------------------------------------------------------------------------------
; Parse an address register.  Z clear when it is no register at all; a data register gives error 16.
; Out: d2 = its number.
;------------------------------------------------------------------------------
parse_address_register:	; from: ea_check_address, asm_adda_suba_cmpa, ins_link, ins_move, ins_movea, ins_movep, 1 more
	bsr.s	parse_register                  ; a register?
	bne.s	address_register_done           ; no: Z clear

address_register_check:	; from: emit_immediate_byte
	tst.b	d0                              ; an address register?
	bne.s	address_register_ok             ; yes
address_register_error:	; from: asm_adda_suba_cmpa, ins_lea
	moveq	#16,d0                          ; address register expected
	bsr.w	asm_error
address_register_ok:
	cmp.b	d0,d0                           ; Z set
address_register_done:	; from: parse_address_register
	rts

;------------------------------------------------------------------------------
; Parse a register name: D0-D7, A0-A7, SP, R0-R15 or a register equate (EQUR).  In: d1 = the first
; character, a4 past it.  Out: Z set if it is one, d2 = its number, d0 = 1 for an address register, a4 and
; d1 past it; Z clear and a4/d1 as they were if not.
;------------------------------------------------------------------------------
parse_register:                                 ; from: parse_data_register, parse_address_register, ea_parse,
                                                ;   emit_immediate_byte, dir_equr, ins_exg, 4 more
	move.b	d1,d0
	movea.l	a4,a0
	ext.w	d0
	move.b	upper_case(a6,d0.w),d0          ; upper case
	cmp.b	#$41,d0                         ; A?
	beq.s	parse_register_number
	cmp.b	#$44,d0                         ; D?
	beq.s	parse_register_number
	cmp.b	#$52,d0                         ; R?
	beq.s	parse_register_rn
	cmp.b	#$53,d0                         ; S?
	bne.w	parse_register_equate           ; no: an equate?
	move.b	(a0)+,d0
	ext.w	d0
	move.b	upper_case(a6,d0.w),d0
	cmp.b	#$50,d0                         ; SP?
	bne.s	parse_register_equate
	moveq	#1,d0                           ; yes: A7
	moveq	#7,d2
	bra.s	parse_register_end
parse_register_number:
	move.b	(a0)+,d2                        ; the digit
	cmp.b	#$37,d2                         ; 0-7?
	bhi.s	parse_register_equate
	subi.b	#$30,d2
	bcs.s	parse_register_equate
	cmp.b	#$41,d0                         ; A: an address register
	seq	d0
parse_register_end:
	andi.b	#$1,d0                          ; d0 = 0 or 1
	moveq	#0,d1
	move.b	(a0)+,d1                        ; the next character
	lea	symbol_chars(pc),a1             ; the name character table
	tst.b	0(a1,d1.w)                      ; more of a name?
	beq.s	parse_register_equate           ; yes: not a register
	movea.l	a0,a4                           ; past it
	cmp.b	d0,d0                           ; Z set
	rts
parse_register_rn:
	move.b	(a0)+,d2                        ; R: the digit
	cmp.b	#$39,d2
	bhi.s	parse_register_equate
	cmp.b	#$30,d2
	bcs.s	parse_register_equate
	cmp.b	#$31,d2                         ; 1?
	bne.s	parse_register_rn_type
	move.b	(a0),d0                         ; R10-R15?
	cmp.b	#$36,d0
	bcc.s	parse_register_rn_type
	cmp.b	#$30,d0
	bcs.s	parse_register_rn_type
	addi.b	#$a,d0
	move.b	d0,d2
	addq.l	#1,a0
parse_register_rn_type:
	subi.b	#$30,d2                         ; the number
	cmp.b	#$8,d2                          ; 8 and on: an address register
	scc	d0
	bra.s	parse_register_end
parse_register_equate:
	lea	name_buffer(a6),a0              ; the name buffer
	movem.l	a2/a4,-(sp)
	move.b	-$1(a4),d1                      ; the first character again
	bsr.w	read_name_cut_dot               ; read a name
	bne.s	parse_register_none             ; none
	movea.l	equate_tree(a6),a2              ; the absolute symbols
	movem.l	d1/d3/a3-a5,-(sp)
	bsr.w	asm_tree_find                   ; find it
	movem.l	(sp)+,d1/d3/a3-a5
	bne.s	parse_register_none             ; not there
	cmpi.b	#$4,$d(a1)                      ; a register equate?
	bne.s	parse_register_none             ; no
	move.b	9(a1),d0                        ; its address register flag
	move.b	$b(a1),d2                       ; its number
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	parse_register_equate_found     ; no
	btst	#$6,$c(a1)                      ; defined on pass 2?
	beq.s	parse_register_none             ; no
parse_register_equate_found:
	movem.l	(sp)+,a0/a2                     ; a2 back, a4 past the name
	movea.l	a0,a2
	cmp.b	d0,d0                           ; Z set
	rts
parse_register_none:
	movem.l	(sp)+,a2/a4                     ; a2 and a4 back
	move.b	-$1(a4),d1                      ; the first character again
	moveq	#-1,d0                          ; Z clear
	rts

;------------------------------------------------------------------------------
; Parse an effective address where PC-relative is allowed: with OPT A+ absolute addresses become d16(PC).
;------------------------------------------------------------------------------
ea_parse_pc_allowed:	; from: ea_store_parse_check, asm_add_subtract, asm_cmp, ins_logic, ins_move, ins_shift
	tst.b	asm_auto_pc(a6)                 ; OPT A+?
	beq.s	ea_parse                        ; no
	st	operand_pc_relative(a6)         ; yes: absolute addresses become PC-relative
	bra.s	ea_parse_start

;------------------------------------------------------------------------------
; Parse an effective address.  In: d1 = its first character, a4 past it, a5 = where its extension words
; go, operand_size.  Out: d5 = mode and register (mode * 8 + register: 56 abs.W, 57 abs.L, 58 d16(PC),
; 59 d8(PC,Xn), 60 #imm; $41 CCR, $42 SR, $44 USP), the extension written to (a5)+, d2/d3 the value and
; type, d4 flags (low byte nonzero: not known; bit 15: no size given for an address), d1 the next char.
;------------------------------------------------------------------------------
ea_parse:                                       ; from: ea_store_parse_check, ea_parse_pc_allowed, asm_abcd_sbcd,
                                                ;   asm_add_subtract, asm_cmp, asm_postinc_register, 3 more
	sf	operand_pc_relative(a6)         ; not made PC-relative
ea_parse_start:	; from: ea_parse_pc_allowed
	bsr.w	parse_register                  ; a register?
	bne.s	ea_parse_not_register           ; no
	moveq	#0,d5                           ; Dn
	or.b	d2,d5
	tst.b	d0                              ; An?
	beq.s	ea_parse_register_done
	ori.b	#$8,d5                          ; An
	cmpi.b	#$1,size_code(a6)               ; byte size?
	beq.w	report_invalid_size             ; yes: invalid size
ea_parse_register_done:
	rts
ea_parse_not_register:
	movea.l	a4,a2                           ; the start, to go back to
	cmp.b	#$28,d1                         ; (?
	beq.w	ea_parse_bracket
	cmp.b	#$2d,d1                         ; -?
	beq.w	ea_parse_minus
	cmp.b	#$23,d1                         ; #?
	beq.w	ea_parse_immediate
	ext.w	d1                              ; upper case
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$43,d1                         ; C?
	beq.s	ea_parse_ccr
	cmp.b	#$53,d1                         ; S?
	beq.s	ea_parse_sr
	cmp.b	#$55,d1                         ; U?
	bne.s	ea_parse_expression
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$53,d1                         ; S?
	bne.s	ea_parse_expression
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$50,d1                         ; P?
	bne.s	ea_parse_expression
	moveq	#4,d5                           ; USP
	bra.w	ea_special_register
ea_parse_sr:
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$52,d1                         ; R?
	bne.s	ea_parse_expression
	moveq	#2,d5                           ; SR
	bra.w	ea_special_register
ea_parse_ccr:
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$43,d1                         ; C?
	bne.s	ea_parse_expression
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$52,d1                         ; R?
	bne.s	ea_parse_expression
	moveq	#1,d5                           ; CCR
	bra.w	ea_special_register
ea_parse_expression:	; from: ea_check_address, ea_special_register
	movea.l	a2,a4                           ; back to the start
	move.b	-$1(a4),d1
	bsr.w	asm_expression                  ; evaluate
	cmp.b	#$28,d1                         ; ( after it: a displacement
	beq.w	ea_parse_displacement
	cmp.b	#$2e,d1                         ; .W or .L?
	beq.s	ea_parse_size_suffix
	cmp.b	#$5c,d1                         ; \W or \L?
	beq.s	ea_parse_size_suffix
	tst.b	org_short(a6)                   ; ORG with a short size?
	bne.s	ea_absolute_word                ; yes: abs.W
	btst	#$2,optimise_flags(a6)          ; short absolute optimising?
	beq.s	ea_parse_absolute               ; no
	movea.w	d2,a0                           ; fits in a word?
	cmpa.l	d2,a0
	bne.s	ea_parse_absolute               ; no
	tst.b	d4                              ; known?
	bne.s	ea_parse_absolute               ; no
	cmp.b	#$1,d3                          ; relocatable?
	beq.s	ea_parse_absolute               ; yes
	bsr.w	optimisation_check              ; done on pass 1 too?
	bne.s	ea_parse_absolute               ; no
	move.w	d2,(a5)+                        ; the word
	bset	#$f,d4                          ; no size given
	bsr.w	ea_check_address                ; check the address
	moveq	#56,d5                          ; abs.W
	moveq	#10,d0                          ; short word addressing used
	bra.w	asm_optimisation                ; count it
ea_parse_absolute:
	tst.b	operand_pc_relative(a6)         ; made PC-relative?
	beq.s	ea_absolute_long                ; no: abs.L
	bra.w	ea_pc_relative                  ; yes: d16(PC)
ea_parse_size_suffix:
	move.b	(a4),d0                         ; the size
	ext.w	d0
	move.b	upper_case(a6,d0.w),d0
	cmp.b	#$4c,d0                         ; L?
	beq.s	ea_absolute_long_given
	cmp.b	#$57,d0                         ; W?
	bne.s	ea_absolute_long                ; no: abs.L
	addq.l	#1,a4                           ; past it
	move.b	(a4)+,d1
ea_absolute_word:
	moveq	#56,d5                          ; abs.W
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ea_absolute_word_store          ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ea_absolute_word_check          ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_disp_word              ; yes: a word reference
ea_absolute_word_check:
	bsr.w	check_signed_word_absolute      ; a word, not relocatable?
	bclr	#$e,d4
	bsr.w	ea_check_address                ; check the address
ea_absolute_word_store:
	move.w	d2,(a5)+                        ; the word
	rts
ea_absolute_long_given:
	addq.l	#1,a4                           ; past the L
	move.b	(a4)+,d1
	bclr	#$f,d4                          ; the size was given
	bra.s	ea_absolute_long_set
ea_absolute_long:
	bset	#$f,d4                          ; no size given
ea_absolute_long_set:
	moveq	#57,d5                          ; abs.L
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ea_absolute_long_store          ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ea_absolute_long_check          ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_long                   ; yes: a long reference
ea_absolute_long_check:
	bsr.s	ea_check_address                ; check the address
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	ea_absolute_long_store          ; no
	bsr.w	obj_relocation                  ; yes: a relocation
ea_absolute_long_store:
	move.l	d2,(a5)+                        ; the long
	rts

;------------------------------------------------------------------------------
; Check an address d2 for an instruction: odd for a word or long size (OPT E+, error 34), and an absolute
; address given without a size (OPT I+, error 80 '# probably missing').  Not for BTST and the like.
;------------------------------------------------------------------------------
ea_check_address:	; from: ea_parse, emit_immediate_byte
	tst.b	address_operand(a6)             ; no checks for this instruction?
	bne.s	ea_check_address_done
	cmpi.b	#$1,size_code(a6)               ; byte size?
	beq.s	ea_check_address_hash           ; yes: no odd check
	tst.b	asm_odd_check(a6)               ; OPT E+?
	beq.s	ea_check_address_hash
	btst	#$0,d2                          ; odd?
	bne.s	ea_check_address_odd            ; yes
ea_check_address_hash:
	btst	#$f,d4                          ; no size given?
	beq.s	ea_check_address_done
	cmp.b	#$2,d3                          ; absolute?
	bne.s	ea_check_address_done
	tst.b	asm_warn_hash(a6)               ; OPT I+?
	beq.s	ea_check_address_done
	moveq	#80,d0                          ; # probably missing
	bsr.w	asm_error
ea_check_address_done:
	rts
ea_check_address_odd:
	moveq	#34,d0                          ; odd address
	bra.w	asm_error
ea_parse_bracket:	; from: ea_parse
	move.b	(a4)+,d1                        ; ( : the next character
	bsr.w	parse_address_register          ; an address register?
	bne.w	ea_parse_expression             ; no: a bracketed expression
	move.b	d2,d4                           ; its number
	cmp.b	#$29,d1                         ; )?
	beq.s	ea_parse_indirect
	cmp.b	#$2c,d1                         ; (An,Xn)?
	bne.w	report_mode_not_recognised      ; no: addressing mode not recognised
	clr.l	-(sp)                           ; a displacement of 0
	moveq	#2,d3
	bra.w	ea_parse_index
ea_parse_indirect:
	move.b	(a4)+,d1
	moveq	#16,d5                          ; (An)
	cmp.b	#$2b,d1                         ; +?
	bne.s	ea_parse_indirect_done
	moveq	#24,d5                          ; (An)+
	move.b	(a4)+,d1
ea_parse_indirect_done:
	or.b	d4,d5                           ; the register
	rts
ea_parse_minus:	; from: ea_parse
	cmpi.b	#$28,(a4)+                      ; -(?
	bne.w	ea_parse_expression             ; no: an expression
	move.b	(a4)+,d1
	bsr.w	parse_address_register          ; an address register?
	bne.w	ea_parse_expression             ; no: an expression
	cmp.b	#$29,d1                         ; )?
	bne.w	report_mode_not_recognised      ; no: addressing mode not recognised
	move.b	(a4)+,d1
	moveq	#32,d5                          ; -(An)
	or.b	d2,d5
	rts
ea_parse_immediate:	; from: ea_parse
	move.b	(a4)+,d1                        ; #: the next character

;------------------------------------------------------------------------------
; Evaluate an immediate operand and write it for operand_size (emit_immediate).
;------------------------------------------------------------------------------
evaluate_immediate:	; from: asm_addi_subi_cmpi, ins_logic_imm
	bsr.w	asm_expression                  ; evaluate

;------------------------------------------------------------------------------
; Write the immediate d2 (type d3) to (a5)+ for operand_size: a word for none, .B and .W, a long for .L.
; d5 = 60 (#imm).  Range and relocation checks on pass 2.
;------------------------------------------------------------------------------
emit_immediate:	; from: asm_add_quick, ins_move_try_moveq
	moveq	#60,d5                          ; #imm
	move.b	size_code(a6),d0                ; the size
	beq.s	emit_immediate_word             ; none: a word
	subq.b	#1,d0
	beq.s	emit_immediate_byte             ; .B: a byte
	subq.b	#1,d0
	beq.s	emit_immediate_word             ; .W: a word

;------------------------------------------------------------------------------
; Write the long d2 to (a5)+: on pass 2 a linker reference for an import, a relocation if relocatable.
;------------------------------------------------------------------------------
emit_immediate_long:	; from: dir_dc
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	emit_immediate_long_store       ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	emit_immediate_long_reloc       ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_long                   ; yes: a long reference
emit_immediate_long_reloc:
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	emit_immediate_long_store       ; no
	bsr.w	obj_relocation                  ; yes: a relocation
emit_immediate_long_store:
	move.l	d2,(a5)+                        ; the long
	rts

;------------------------------------------------------------------------------
; Write the word d2 to (a5)+, checked on pass 2 (fits in a word, not relocatable).
;------------------------------------------------------------------------------
emit_immediate_word:	; from: emit_immediate, dir_dc, ins_link, ins_stop
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	emit_immediate_word_store       ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	emit_immediate_word_check       ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_word                   ; yes: a word reference
emit_immediate_word_check:
	bsr.w	check_word_range                ; a word, not relocatable?
emit_immediate_word_store:	; from: emit_immediate_byte
	move.w	d2,(a5)+                        ; the word
	rts

;------------------------------------------------------------------------------
; Write the byte d2 as a word to (a5)+, checked on pass 2 (fits in a byte, not relocatable).
;------------------------------------------------------------------------------
emit_immediate_byte:	; from: emit_immediate, asm_btst, asm_bit_change
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	emit_immediate_word_store       ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	emit_immediate_byte_check       ; no
	tst.w	d3                              ; imported?
	bmi.s	emit_immediate_byte_import      ; yes
emit_immediate_byte_check:
	bsr.w	check_byte_range                ; a byte, not relocatable?
	andi.w	#$ff,d2
	move.w	d2,(a5)+
	rts
emit_immediate_byte_import:
	move.b	#$0,(a5)+                       ; the high byte 0
	bra.w	obj_xref_byte                   ; a byte reference
ea_parse_displacement:	; from: ea_parse
	move.b	(a4)+,d1                        ; value(: the next character
	move.l	d2,-(sp)                        ; keep the displacement
	bsr.w	parse_register                  ; a register?
	bne.w	ea_parse_pc                     ; no: (PC
	bsr.w	address_register_check          ; an address register
	cmp.b	#$29,d1                         ; )?
	bne.s	ea_parse_index_comma            ; no: an index
	btst	#$1,optimise_flags(a6)          ; removing 0 offsets?
	beq.s	ea_displacement_an              ; no
	tst.b	d4                              ; known?
	bne.s	ea_displacement_an
	tst.l	(sp)                            ; 0?
	bne.s	ea_displacement_an
	moveq	#16,d5                          ; (An)
	or.b	d2,d5
	move.l	(sp)+,d2
	bsr.w	optimisation_check              ; done on pass 1 too?
	bne.s	ea_displacement_keep            ; no
	move.b	(a4)+,d1
	moveq	#9,d0                           ; offset removed
	bra.w	asm_optimisation                ; count it
ea_displacement_keep:
	move.l	d2,-(sp)                        ; the displacement back
	move.b	d5,d2                           ; the register
	andi.b	#$7,d2
ea_displacement_an:
	moveq	#40,d5                          ; d16(An)
	or.b	d2,d5
	move.l	(sp)+,d2                        ; the displacement
	move.b	(a4)+,d1                        ; past the )
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ea_displacement_store           ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_disp_word              ; yes: a word reference
ea_displacement_store:
	move.w	d2,(a5)+                        ; the word
	tst.b	pass_two(a6)                    ; pass 2: a word, not relocatable?
	bne.w	check_signed_word_absolute
	rts
ea_parse_index_comma:
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
ea_parse_index:	; from: ea_check_address
	moveq	#48,d5                          ; d8(An,Xn)
	or.b	d2,d5
	move.b	(a4)+,d1
	bsr.w	parse_register                  ; the index register
	bne.w	report_mode_not_recognised      ; none: addressing mode not recognised
	lsl.b	#3,d0                           ; D/A and number
	or.b	d2,d0
	lsl.b	#4,d0                           ; in the extension's high bits
	swap	d3
	move.b	d0,d3                           ; the extension byte in d3
	move.l	(sp)+,d2                        ; the displacement
	cmp.b	#$2e,d1                         ; .W or .L?
	beq.s	ea_index_size
	cmp.b	#$5c,d1
	bne.s	ea_index_close                  ; no: .W
ea_index_size:
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$57,d1                         ; W?
	beq.s	ea_index_size_done
	cmp.b	#$4c,d1                         ; L?
	bne.w	report_index_size               ; no: .W or .L expected
	ori.b	#$8,d3                          ; long index
ea_index_size_done:
	move.b	(a4)+,d1
ea_index_close:
	cmp.b	#$29,d1                         ; )?
	bne.w	asm_missing_bracket             ; no: missing close bracket
	move.b	(a4)+,d1
	move.b	d3,(a5)+                        ; the extension byte
	swap	d3
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ea_index_store                  ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_disp_byte              ; yes: a byte reference
ea_index_store:
	move.b	d2,(a5)+                        ; the displacement byte
	tst.b	pass_two(a6)                    ; pass 2: a byte?
	bne.w	check_signed_byte
	rts
ea_parse_pc:
	ext.w	d1                              ; upper case
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$50,d1                         ; P?
	bne.w	report_mode_not_recognised      ; no: addressing mode not recognised
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$43,d1                         ; C?
	bne.w	report_mode_not_recognised
	move.l	(sp)+,d2                        ; the address
	move.b	(a4)+,d1
	cmp.b	#$29,d1                         ; )?
	bne.s	ea_pc_index                     ; no: an index
	move.b	(a4)+,d1
ea_pc_relative:	; from: ea_parse
	moveq	#58,d5                          ; d16(PC)
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ea_pc_relative_store            ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ea_pc_relative_type             ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_pcrel_word             ; yes: a PC-relative word reference
ea_pc_relative_type:
	cmp.b	#$2,d3                          ; absolute?
	beq.s	ea_pc_relative_absolute         ; yes
ea_pc_relative_offset:
	bclr	#$f,d4
	bsr.w	ea_check_address                ; check the address
	sub.l	program_counter(a6),d2          ; from the program counter
	move.l	a5,d0                           ; and the extension word's place
	sub.l	code_buffer_ptr(a6),d0
	sub.l	d0,d2
	move.w	d2,(a5)+                        ; the displacement
	bra.w	check_signed_word               ; fits in a word?
ea_pc_relative_absolute:
	tst.b	type_check_off(a6)              ; OPT T-?
	bne.s	ea_pc_relative_offset           ; yes: taken anyway
	moveq	#32,d0                          ; absolute not allowed
	bsr.w	asm_error
ea_pc_relative_store:
	move.w	d2,(a5)+
	rts
ea_pc_index:
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_mode_not_recognised      ; no: addressing mode not recognised
	moveq	#59,d5                          ; d8(PC,Xn)
	move.l	d2,-(sp)                        ; the address
	move.b	(a4)+,d1
	bsr.w	parse_register                  ; the index register
	bne.w	report_mode_not_recognised      ; none: addressing mode not recognised
	lsl.b	#3,d0                           ; D/A and number
	or.b	d2,d0
	lsl.b	#4,d0                           ; in the extension's high bits
	move.b	d0,d4                           ; the extension byte in d4
	cmp.b	#$2e,d1                         ; .W or .L?
	beq.s	ea_pc_index_size
	cmp.b	#$5c,d1
	bne.s	ea_pc_index_store               ; no: .W
ea_pc_index_size:
	move.b	(a4)+,d1
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1
	cmp.b	#$57,d1                         ; W?
	beq.s	ea_pc_index_size_done
	cmp.b	#$4c,d1                         ; L?
	bne.w	report_index_size               ; no: .W or .L expected
	ori.b	#$8,d4                          ; long index
ea_pc_index_size_done:
	move.b	(a4)+,d1
ea_pc_index_store:
	move.l	(sp)+,d2                        ; the address
	move.b	d4,(a5)+                        ; the extension byte
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ea_pc_index_byte                ; no
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ea_pc_index_type                ; no
	tst.w	d3                              ; imported?
	bmi.s	ea_pc_index_import              ; yes
ea_pc_index_type:
	tst.b	type_check_off(a6)              ; OPT T-?
	bne.s	ea_pc_index_offset              ; yes
	cmp.b	#$2,d3                          ; absolute?
	beq.s	ea_pc_index_absolute            ; yes: not allowed
ea_pc_index_offset:
	sub.l	program_counter(a6),d2          ; from the program counter
	move.l	a5,d0                           ; and the extension's place
	sub.l	code_buffer_ptr(a6),d0
	sub.l	d0,d2
	addq.l	#1,d2
	bsr.w	check_signed_byte               ; fits in a byte?
	bra.s	ea_pc_index_byte
ea_pc_index_import:
	bsr.w	obj_xref_pcrel_byte             ; a PC-relative byte reference
	bra.s	ea_pc_index_close
ea_pc_index_absolute:
	moveq	#32,d0                          ; absolute not allowed
	bsr.w	asm_error
ea_pc_index_byte:
	move.b	d2,(a5)+                        ; the displacement byte
ea_pc_index_close:
	cmp.b	#$29,d1                         ; )?
	bne.w	asm_missing_bracket             ; no: missing close bracket
	move.b	(a4)+,d1
	rts

;------------------------------------------------------------------------------
; CCR, SR or USP was read (d5 = 1, 2 or 4): it must not go on as a name; then d5 gets bit 6.
;------------------------------------------------------------------------------
ea_special_register:	; from: ea_parse
	moveq	#0,d1
	move.b	(a4)+,d1                        ; the next character
	lea	symbol_chars(pc),a1
	tst.b	0(a1,d1.w)                      ; more of a name?
	beq.w	ea_parse_expression             ; yes: an expression
	bset	#$6,d5                          ; a special register
	rts

;------------------------------------------------------------------------------
; ADDX, SUBX: Dy,Dx or -(Ay),-(Ax), any size.
;------------------------------------------------------------------------------
asm_addx_subx:	; from: mnemonic_table
	bsr.w	or_size_bits                    ; the size bits
	bra.s	asm_x_operands

;------------------------------------------------------------------------------
; ABCD, SBCD: Dy,Dx or -(Ay),-(Ax), .B only.
;------------------------------------------------------------------------------
asm_abcd_sbcd:	; from: mnemonic_table
	bsr.w	asm_size_byte                   ; .B only
asm_x_operands:	; from: asm_addx_subx
	bsr.w	ea_parse                        ; the source
	move.b	d5,d0
	andi.w	#$78,d0                         ; its mode
	beq.s	asm_x_operands_dest             ; Dn
	cmp.b	#$20,d0                         ; -(An)?
	bne.w	ea_mode_not_allowed             ; no: not allowed
	ori.b	#$8,d6                          ; the memory form
asm_x_operands_dest:
	andi.w	#$7,d5                          ; the source register
	or.w	d5,d6
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	move.w	d0,-(sp)                        ; the source's mode
	bsr.w	ea_parse                        ; the destination
	move.b	d5,d0
	andi.w	#$78,d0
	cmp.w	(sp)+,d0                        ; the same mode?
	bne.w	ea_mode_not_allowed             ; no: not allowed
	andi.w	#$7,d5                          ; its register
	ror.w	#7,d5                           ; to bits 9-11
	or.w	d5,d6
	move.w	d6,(a5)+                        ; the opcode
	rts

;------------------------------------------------------------------------------
; ADD/SUB #1-8 with OPT O quick forms: made ADDQ/SUBQ when the data is known, else the immediate form.
;------------------------------------------------------------------------------
asm_add_quick:	; from: asm_add_subtract
	move.b	(a4)+,d1                        ; past the #
	bsr.w	asm_expression                  ; evaluate
	cmp.b	#$2c,d1                         ; ,?
	bne.s	asm_add_immediate               ; no
	tst.b	d4                              ; known?
	bne.s	asm_add_immediate               ; no
	cmp.b	#$2,d3                          ; absolute?
	bne.s	asm_add_immediate               ; no
	cmp.l	#$9,d2                          ; 1-8?
	bcc.s	asm_add_immediate
	tst.l	d2
	ble.s	asm_add_immediate
	subq.l	#2,a5                           ; the opcode's place again
	bsr.w	optimisation_check              ; done on pass 1 too?
	bne.s	asm_add_quick_off               ; no
	andi.w	#$4000,d6                       ; ADD or SUB
	bchg	#$e,d6                          ; SUB: bit 8
	lsr.w	#6,d6
	ori.w	#$5000,d6                       ; ADDQ/SUBQ
	bsr.w	or_size_bits                    ; the size bits
	cmp.b	#$8,d2                          ; 8?
	bne.s	asm_add_quick_data
	moveq	#0,d2                           ; is 0
asm_add_quick_data:
	ror.w	#7,d2                           ; the data to bits 9-11
	or.w	d2,d6
	move.b	(a4)+,d1                        ; past the ,
	bsr.w	ea_store_parse_check            ; the opcode and the destination
	dc.w	$3f                             ; Dn An (An) (An)+ -(An) d16(An) d8(An,Xn) abs
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_add_quick_note              ; no
	moveq	#0,d0
	move.b	size_code(a6),d0
	move.b	quick_saving_table(pc,d0.w),d0  ; the bytes saved for this size
	add.w	d0,asm_optimise_saved(a6)
asm_add_quick_note:
	moveq	#12,d0                          ; quick form used
	bra.w	asm_optimisation                ; count it
quick_saving_table:
	dc.w	$0202,$0204                     ; bytes saved by a quick form, by size: none, .B, .W, .L
asm_add_quick_off:
	addq.l	#2,a5                           ; the opcode's place back
asm_add_immediate:
	move.b	(a4)+,d1                        ; past the ,
	bsr.w	emit_immediate                  ; write the immediate
	bra.w	asm_add_sub_dest                ; the destination
	btst	#$e,d6                          ; (not reached)
	bne.s	asm_add_immediate
	neg.l	d2
	bra.s	asm_add_immediate

;------------------------------------------------------------------------------
; ADD, SUB: <ea>,Dn  Dn,<ea>  #imm,<ea> (ADDI/SUBI)  <ea>,An (ADDA/SUBA); #1-8 to ADDQ/SUBQ with OPT O.
;------------------------------------------------------------------------------
asm_add_subtract:	; from: mnemonic_table
	addq.l	#2,a5                           ; room for the opcode
	cmp.b	#$23,d1                         ; #?
	bne.s	asm_add_sub_source
	btst	#$4,optimise_flags(a6)          ; quick forms?
	bne.w	asm_add_quick                   ; yes
asm_add_sub_source:
	bsr.w	ea_parse_pc_allowed             ; the source
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
asm_add_sub_dest:	; from: asm_add_quick
	move.w	d5,-(sp)                        ; the source's mode
	bsr.w	ea_parse                        ; the destination
	move.w	(sp)+,d4                        ; d4 = the source
	movea.l	code_buffer_ptr(a6),a0          ; the opcode's place
	move.b	d5,d2
	andi.b	#$78,d2                         ; its mode
	cmp.b	#$8,d2                          ; An?
	beq.w	asm_add_sub_adda                ; yes: ADDA
	cmp.b	#$3c,d4                         ; #imm source?
	beq.s	asm_add_sub_addi                ; yes: ADDI
	bsr.w	or_size_bits                    ; the size bits
	move.w	d6,(a0)
	tst.b	d2                              ; to Dn?
	bne.s	asm_add_sub_to_memory           ; no
	add.b	d5,d5                           ; its register to bits 9-11
	or.b	d5,(a0)+
	cmp.b	#$40,d4                         ; a special register source?
	bcc.w	ea_mode_not_allowed             ; not allowed
	or.b	d4,(a0)                         ; the source
	rts
asm_add_sub_to_memory:
	move.b	d4,d0                           ; the source must be Dn
	andi.b	#$78,d0
	bne.w	ea_mode_not_allowed
	add.b	d4,d4                           ; its register to bits 9-11
	addq.b	#1,d4                           ; and bit 8: to <ea>
	or.b	d4,(a0)+
	or.b	d5,(a0)                         ; the destination
	moveq	#60,d0                          ; (An) (An)+ -(An) d16(An) d8(An,Xn) abs
	bra.s	asm_add_sub_check
asm_add_sub_addi:
	ror.w	#5,d6                           ; ADDI or SUBI
	andi.w	#$700,d6
	bsr.w	or_size_bits                    ; the size bits
	or.b	d5,d6                           ; the destination
	move.w	d6,(a0)
	moveq	#61,d0                          ; Dn (An) (An)+ -(An) d16(An) d8(An,Xn) abs
asm_add_sub_check:
	bra.w	ea_check_mode                   ; check it
asm_add_sub_adda:
	ori.b	#$c0,d6                         ; ADDA/SUBA
	or.b	d4,d6                           ; the source
	andi.w	#$7,d5                          ; the register
	ror.w	#7,d5                           ; to bits 9-11
	or.w	d5,d6
	cmpi.b	#$3,size_code(a6)               ; .L?
	bne.s	asm_add_sub_adda_store
	bset	#$8,d6                          ; yes
asm_add_sub_adda_store:
	move.w	d6,(a0)
	move.w	d4,d5
	cmp.b	#$40,d5                         ; a special register?
	bcc.w	ea_mode_not_allowed             ; not allowed

;------------------------------------------------------------------------------
; Error 10 (invalid size) for a .B size.
;------------------------------------------------------------------------------
asm_size_not_byte:	; from: asm_adda_suba_cmpa, asm_cmp, ins_ext
	cmpi.b	#$1,size_code(a6)               ; .B?
	beq.w	report_invalid_size             ; invalid size
	rts

;------------------------------------------------------------------------------
; ADDA, SUBA, CMPA: <ea>,An, .W or .L.
;------------------------------------------------------------------------------
asm_adda_suba_cmpa:	; from: mnemonic_table
	cmpi.b	#$3,size_code(a6)               ; .L?
	bne.s	asm_adda_operands
	ori.w	#$100,d6                        ; yes
asm_adda_operands:
	bsr.w	ea_store_parse_check            ; the opcode and the source
	dc.w	$ff                             ; any mode
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.w	parse_address_register          ; an address register
	bne.w	address_register_error          ; none: address register expected
	add.b	d2,d2                           ; to bits 9-11
	movea.l	code_buffer_ptr(a6),a0
	or.b	d2,(a0)
	bra.s	asm_size_not_byte               ; not .B

;------------------------------------------------------------------------------
; ADDI, SUBI, CMPI: #imm,<ea>.
;------------------------------------------------------------------------------
asm_addi_subi_cmpi:	; from: mnemonic_table
	bsr.w	or_size_bits                    ; the size bits
	move.w	d6,(a5)+                        ; the opcode
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; no: immediate data expected
	move.b	(a4)+,d1
	bsr.w	evaluate_immediate              ; the immediate
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.w	ea_parse_check                  ; the destination
	dc.w	$3d                             ; Dn (An) (An)+ -(An) d16(An) d8(An,Xn) abs
	rts

;------------------------------------------------------------------------------
; Bcc, BRA, BSR: .S (.B) a byte offset, .W a word one, .L taken as .W (warning 5); no size: a word one,
; or a short one with OPT O when it fits and is known on pass 1.
;------------------------------------------------------------------------------
asm_bcc:	; from: mnemonic_table
	move.b	size_code(a6),d0                ; the size
	beq.w	asm_bcc_auto                    ; none
	cmp.b	#$1,d0                          ; .S?
	beq.s	asm_bcc_short
	cmp.b	#$2,d0                          ; .W?
	beq.w	asm_bcc_word
	moveq	#5,d0                           ; .L: size should be .W
	bsr.w	asm_warning
	bra.s	asm_bcc_word
	moveq	#33,d0                          ; (not reached: wrong processor)
	bra.w	asm_error
asm_bcc_short:
	bsr.w	asm_branch_offset               ; the offset
	beq.s	asm_bcc_short_nop               ; pass 1: room only
	lsr.w	#8,d6                           ; the opcode's high byte
	move.b	d6,(a5)+
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	asm_bcc_short_offset            ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_pcrel_byte             ; yes: a PC-relative byte reference
asm_bcc_short_offset:
	tst.l	d2                              ; offset 0?
	bne.s	asm_bcc_short_byte              ; no
	cmp.b	#$61,d6                         ; BSR.S?
	beq.s	asm_bsr_short_zero              ; yes
	btst	#$6,optimise_flags(a6)          ; 0 branches to NOP?
	bne.s	asm_bcc_short_nop_note          ; yes
	moveq	#81,d0                          ; short branch cannot be 0 bytes
	bsr.w	asm_error
	bra.s	asm_bcc_short_to_nop
asm_bcc_short_nop_note:
	moveq	#14,d0                          ; short branch converted to NOP
	bsr.w	asm_optimisation                ; count it
asm_bcc_short_to_nop:
	movea.l	code_buffer_ptr(a6),a5          ; back to the opcode
asm_bcc_short_nop:
	move.w	#$4e71,(a5)+                    ; NOP (or room on pass 1)
	rts
asm_bsr_short_zero:
	move.b	#$ff,(a5)+
	moveq	#61,d0                          ; illegal BSR.S
	bra.w	asm_error
asm_bcc_short_byte:
	bsr.w	check_signed_byte               ; fits in a byte?
	move.b	d2,(a5)+                        ; the offset
	rts

;------------------------------------------------------------------------------
; A word branch (also DBcc): the offset as a word after the opcode.
;------------------------------------------------------------------------------
asm_bcc_word:	; from: asm_bcc, asm_dbcc
	bsr.s	asm_branch_offset               ; the offset
asm_bcc_word_emit:
	beq.s	asm_bcc_word_pass1              ; pass 1: room only
	move.w	d6,(a5)+                        ; the opcode
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	asm_bcc_word_check              ; no
	tst.w	d3                              ; imported?
	bmi.w	obj_xref_pcrel_word             ; yes: a PC-relative word reference
asm_bcc_word_check:
	bsr.w	check_signed_word               ; fits in a word?
	move.w	d2,(a5)+                        ; the offset
	rts
asm_bcc_word_pass1:
	addq.l	#4,a5                           ; room for both
	rts
asm_bcc_auto:	; from: asm_bcc
	btst	#$0,optimise_flags(a6)          ; optimising branches?
	beq.s	asm_bcc_word                    ; no: a word branch
	bsr.w	asm_expression                  ; evaluate
	tst.b	d4                              ; known?
	bne.s	asm_bcc_auto_offset             ; no: a word branch
	tst.b	type_check_off(a6)              ; OPT T-?
	bne.s	asm_bcc_auto_try
	cmp.b	#$2,d3                          ; absolute?
	beq.s	asm_bcc_auto_offset             ; yes: a word branch
asm_bcc_auto_try:
	move.l	d2,-(sp)
	sub.l	program_counter(a6),d2          ; the offset
	subq.l	#2,d2
	beq.s	asm_bcc_auto_word               ; 0: not short
	move.b	d2,d0                           ; fits in a byte?
	ext.w	d0
	ext.l	d0
	cmp.l	d0,d2
	bne.s	asm_bcc_auto_word               ; no
	bsr.w	optimisation_check              ; done on pass 1 too?
	bne.s	asm_bcc_auto_could              ; no
	addq.l	#4,sp
	or.b	d2,d6                           ; the short branch
	move.w	d6,(a5)+
	moveq	#8,d0                           ; branch made short
	bra.w	asm_optimisation                ; count it
asm_bcc_auto_could:
	btst	#$5,optimise_flags(a6)          ; tell where it could be?
	beq.s	asm_bcc_auto_word
	moveq	#13,d0                          ; branch could be short
	bsr.w	asm_optimisation
asm_bcc_auto_word:
	move.l	(sp)+,d2                        ; the target
asm_bcc_auto_offset:
	pea	asm_bcc_word_emit(pc)           ; return to the word branch
	bra.s	asm_branch_offset_value

;------------------------------------------------------------------------------
; Evaluate a branch target and make it an offset from the opcode + 2 (in d2).  On pass 2 an absolute
; target gives error 32 (unless OPT T-) and an odd one error 34.  Out: Z set on pass 1.
;------------------------------------------------------------------------------
asm_branch_offset:	; from: asm_bcc, asm_bcc_word
	bsr.w	asm_expression                  ; evaluate
asm_branch_offset_value:	; from: asm_bcc_word
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	asm_branch_offset_check         ; yes
	tst.b	d4                              ; known?
	bne.s	asm_branch_offset_done          ; no
	cmp.b	#$2,d3                          ; absolute?
	bne.s	asm_branch_offset_done
	tst.b	type_check_off(a6)              ; OPT T-?
	bne.s	asm_branch_offset_done
asm_branch_offset_check:
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	asm_branch_offset_type          ; no
	tst.w	d3                              ; imported?
	bmi.s	asm_branch_offset_done          ; yes
asm_branch_offset_type:
	tst.b	type_check_off(a6)              ; OPT T-?
	bne.s	asm_branch_offset_odd
	cmp.b	#$2,d3                          ; absolute?
	beq.s	asm_branch_offset_absolute      ; yes
asm_branch_offset_odd:
	btst	#$0,d2                          ; odd?
	beq.s	asm_branch_offset_from_pc
	moveq	#34,d0                          ; odd address
	bsr.w	asm_error
asm_branch_offset_from_pc:
	sub.l	program_counter(a6),d2          ; from the program counter
	subq.l	#2,d2                           ; + 2
asm_branch_offset_done:
	tst.b	pass_two(a6)                    ; Z set on pass 1
	rts
asm_branch_offset_absolute:
	moveq	#32,d0                          ; absolute not allowed
	bsr.w	asm_error
	tst.b	pass_two(a6)
	rts

;------------------------------------------------------------------------------
; BTST Dn,<ea> or #n,<ea>: .L for Dn, .B for memory.
;------------------------------------------------------------------------------
asm_btst:	; from: mnemonic_table
	st	address_operand(a6)             ; no address checks
	cmp.b	#$23,d1                         ; #?
	beq.s	asm_btst_static                 ; yes
	bsr.w	parse_data_register             ; the bit number register
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	add.b	d2,d2                           ; to bits 9-11
	addq.b	#1,d2                           ; and bit 8
	move.b	d2,(a5)+
	move.b	d6,(a5)+                        ; the opcode's low byte
	bsr.w	ea_parse_check                  ; the destination
	dc.w	$fd                             ; all but An
	bra.s	asm_bit_size
asm_btst_static:
	move.w	d6,(a5)+                        ; the opcode
	move.b	(a4)+,d1
	bsr.w	asm_expression                  ; the bit number
	bsr.w	emit_immediate_byte             ; as a byte
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.w	ea_parse_check                  ; the destination
	dc.w	$7d                             ; Dn (An) (An)+ -(An) d16(An) d8(An,Xn) abs d(PC)
asm_bit_size:	; from: asm_bit_change
	andi.w	#$38,d5                         ; memory?
	bne.s	asm_size_byte                   ; yes: .B

;------------------------------------------------------------------------------
; Error 10 unless the size is .L or none.
;------------------------------------------------------------------------------
asm_size_long:	; from: ins_exg, ins_lea, ins_move, ins_pea
	moveq	#3,d0                           ; .L
	bra.w	asm_size_must_be

;------------------------------------------------------------------------------
; Error 10 unless the size is .B or none.
;------------------------------------------------------------------------------
asm_size_byte:	; from: asm_abcd_sbcd, asm_btst, ins_nbcd, ins_scc, ins_tas
	moveq	#1,d0                           ; .B
	bra.w	asm_size_must_be

;------------------------------------------------------------------------------
; BCLR, BSET, BCHG Dn,<ea> or #n,<ea>: data alterable modes; .L for Dn, .B for memory.
;------------------------------------------------------------------------------
asm_bit_change:	; from: mnemonic_table
	st	address_operand(a6)             ; no address checks
	cmp.b	#$23,d1                         ; #?
	beq.s	asm_bit_change_static           ; yes
	bsr.w	parse_data_register             ; the bit number register
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	add.b	d2,d2                           ; to bits 9-11
	addq.b	#1,d2                           ; and bit 8
	move.b	d2,(a5)+
	move.b	d6,(a5)+                        ; the opcode's low byte
	bsr.w	ea_parse_check                  ; the destination
	dc.w	$3d                             ; Dn (An) (An)+ -(An) d16(An) d8(An,Xn) abs
	bra.s	asm_bit_size
asm_bit_change_static:
	move.w	d6,(a5)+                        ; the opcode
	move.b	(a4)+,d1
	bsr.w	asm_expression                  ; the bit number
	bsr.w	emit_immediate_byte             ; as a byte
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.w	ea_parse_check                  ; the destination
	dc.w	$3d                             ; Dn (An) (An)+ -(An) d16(An) d8(An,Xn) abs
	bra.s	asm_bit_size

;------------------------------------------------------------------------------
; CHK, MULU, MULS, DIVU, DIVS: <ea>,Dn, .W only.
;------------------------------------------------------------------------------
asm_chk_mul_div:	; from: mnemonic_table
	bsr.w	ea_store_parse_check            ; the opcode and the source
	dc.w	$fd                             ; all but An
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.w	parse_data_register             ; the data register
	movea.l	code_buffer_ptr(a6),a0
	add.b	d2,d2                           ; to bits 9-11
	or.b	d2,(a0)

;------------------------------------------------------------------------------
; Error 10 unless the size is .W or none.
;------------------------------------------------------------------------------
asm_size_word:	; from: asm_dbcc, ins_move, ins_move_from_sr, ins_shift, ins_swap
	moveq	#2,d0                           ; .W
	bra.w	asm_size_must_be

;------------------------------------------------------------------------------
; CMP: <ea>,Dn; to CMPA for An, CMPI for #imm, CMPM for (Ay)+,(Ax)+.
;------------------------------------------------------------------------------
asm_cmp:	; from: mnemonic_table
	bsr.w	or_size_bits                    ; the size bits
	move.w	d6,(a5)+                        ; the opcode
	bsr.w	ea_parse_pc_allowed             ; the source
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	move.w	d5,-(sp)                        ; the source's mode
	bsr.w	ea_parse                        ; the destination
	move.w	(sp)+,d4                        ; d4 = the source
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	move.w	d5,d0
	andi.b	#$78,d0                         ; its mode
	beq.s	asm_cmp_data_register           ; Dn
	cmp.b	#$8,d0                          ; An?
	beq.s	asm_cmpa                        ; yes: CMPA
	cmp.b	#$3c,d4                         ; #imm source?
	beq.s	asm_cmpi                        ; yes: CMPI
	move.b	d4,d0                           ; (An)+ source?
	andi.b	#$78,d0
	cmp.b	#$18,d0
	bne.s	asm_cmp_bad_mode                ; no: not allowed
	move.b	d5,d0                           ; and (An)+ destination?
	andi.b	#$78,d0
	cmp.b	#$18,d0
	bne.s	asm_cmp_bad_mode                ; no: not allowed
	move.w	#$b108,d6                       ; CMPM
	bsr.w	or_size_bits                    ; the size bits
	move.b	d4,d0                           ; the source register
	andi.b	#$7,d0
	or.b	d0,d6
	move.b	d5,d0                           ; the destination register
	andi.w	#$7,d0
	ror.w	#7,d0                           ; to bits 9-11
	or.w	d0,d6
	movea.l	code_buffer_ptr(a6),a0
	move.w	d6,(a0)
	rts
asm_cmp_bad_mode:
	bra.w	ea_mode_not_allowed             ; addressing mode not allowed
asm_cmp_data_register:
	add.b	d5,d5                           ; the register to bits 9-11
	or.b	d5,(a0)
	move.w	d4,d5                           ; the source
	or.w	d5,(a0)
	move.w	#$ff,d0                         ; any mode
	bra.w	ea_check_mode                   ; check it
asm_cmpa:
	andi.b	#$7,d5                          ; the register
	add.b	d5,d5                           ; to bits 9-11
	cmpi.b	#$3,size_code(a6)               ; .L?
	bne.s	asm_cmpa_store
	addq.b	#1,d5                           ; yes: bit 8
asm_cmpa_store:
	or.b	d5,(a0)
	move.w	d4,d5                           ; the source
	ori.w	#$c0,d4                         ; CMPA's size bits
	or.w	d4,(a0)
	move.w	#$ff,d0                         ; any mode
	bsr.w	ea_check_mode                   ; check it
	bra.w	asm_size_not_byte               ; not .B
asm_cmpi:
	move.w	#$c00,d6                        ; CMPI
	bsr.w	or_size_bits                    ; the size bits
	or.w	d5,d6                           ; the destination
	move.w	d6,(a0)
	moveq	#61,d0                          ; Dn (An) (An)+ -(An) d16(An) d8(An,Xn) abs
	bra.w	ea_check_mode                   ; check it

;------------------------------------------------------------------------------
; CMPM (Ay)+,(Ax)+.
;------------------------------------------------------------------------------
asm_cmpm:	; from: mnemonic_table
	bsr.w	or_size_bits                    ; the size bits
	bsr.s	asm_postinc_register            ; the source
	or.b	d5,d6
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.s	asm_postinc_register            ; the destination
	ror.w	#7,d5                           ; to bits 9-11
	or.w	d5,d6
	move.w	d6,(a5)+                        ; the opcode
	rts

;------------------------------------------------------------------------------
; Parse an (An)+ operand (error 17 if it is not one).  Out: d5 = the register number.
;------------------------------------------------------------------------------
asm_postinc_register:	; from: asm_cmpm
	bsr.w	ea_parse                        ; parse it
	move.b	d5,d0
	andi.b	#$78,d0                         ; its mode
	cmp.b	#$18,d0                         ; (An)+?
	bne.w	ea_mode_not_allowed             ; no: not allowed
	andi.w	#$7,d5                          ; the register
	rts

;------------------------------------------------------------------------------
; CNOP offset,alignment: pad with 0 bytes to the next multiple of the alignment, plus the offset (less than
; 128 bytes); a label on the line gets the new address.
;------------------------------------------------------------------------------
asm_cnop:	; from: mnemonic_table
	bsr.w	eval_absolute                   ; the offset
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	move.l	d2,d5
	bsr.w	eval_absolute                   ; the alignment
	move.l	d2,d0
	beq.s	asm_cnop_offset                 ; 0: the offset only
	bmi.s	asm_cnop_too_large              ; negative: data too large
	move.l	d2,-(sp)
	move.l	program_counter(a6),d2          ; the program counter
	move.l	(sp),d0
	bsr.w	expr_divide                     ; divided by it
	move.l	(sp)+,d2
	tst.l	d0                              ; on the alignment already?
	beq.s	asm_cnop_offset
	sub.l	d2,d0                           ; no: up to the next
	neg.l	d0
asm_cnop_offset:
	add.l	d5,d0                           ; plus the offset
	move.l	d0,d4
	beq.s	asm_cnop_label                  ; nothing to pad
	cmp.l	#$80,d0                         ; 128 or more?
	bcc.s	asm_cnop_too_large              ; yes: data too large
asm_cnop_pad:
	move.b	#$0,(a5)+                       ; a 0 byte
	subq.b	#1,d0
	bne.s	asm_cnop_pad
asm_cnop_label:
	add.l	program_counter(a6),d4          ; the new address
	lea	line_label(a6),a0               ; the line's label
	tst.l	(a0)                            ; one?
	bne.w	asm_define_symbol               ; yes: define it there
	rts
asm_cnop_too_large:
	moveq	#28,d0                          ; data too large
	bra.w	asm_error

;------------------------------------------------------------------------------
; COMMENT text: the rest of the line goes to the object file on pass 2 (obj_comment).
;------------------------------------------------------------------------------
asm_comment:	; from: long_mnemonic_table
	lea	-$1(a4),a1                      ; the text's start
	cmp.b	#$d,d1                          ; none?
	beq.s	asm_comment_done
asm_comment_skip:
	move.b	(a4)+,d1                        ; to the line's end
	cmp.b	#$d,d1
	bne.s	asm_comment_skip
	move.l	a4,d2                           ; its length
	sub.l	a1,d2
	subq.w	#1,d2
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_comment_done                ; no
	bsr.w	obj_comment                     ; write it
	moveq	#13,d1                          ; the line's end
asm_comment_done:
	rts

;------------------------------------------------------------------------------
; DBcc Dn,label (DBRA, DBF ...): .W only.
;------------------------------------------------------------------------------
asm_dbcc:	; from: mnemonic_table
	bsr.w	parse_data_register             ; the counter register
	or.b	d2,d6                           ; in the opcode
	cmp.b	#$2c,d1                         ; ,?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1
	bsr.w	asm_size_word                   ; .W only
	bra.w	asm_bcc_word                    ; the word branch

;------------------------------------------------------------------------------
; Instruction and directive handlers.  The dispatcher (find_mnemonic) calls each with d6 = the opcode word from the
; mnemonic table, size_code = the size suffix (0 none, 1 .B/.S, 2 .W, 3 .L), d1 = the first character of the
; operand field and a4 just past it, a5 = the line's code buffer; a handler returns d1 = the character after
; its operands (the dispatcher then wants end of line or a comment).
; DC/DCB/DS start: unless the size is .B, align the PC to even and define the line's label; a .B only
; defines the label.  Returns d0 = the size (none is taken as 2, .W).  Keeps d1.
;------------------------------------------------------------------------------
data_align_label:	; from: dir_dcb, dir_dc, dir_ds
	move.w	d1,-(sp)                        ; keep the operand character
	move.b	size_code(a6),d0                ; the size
	beq.s	data_align_even                 ; none: align
	cmp.b	#$1,d0                          ; .B?
	beq.s	data_align_byte                 ; yes: no alignment
data_align_even:
	bsr.w	asm_define_code_label           ; align to even, define the label
	move.b	size_code(a6),d0                ; the size
	bne.s	data_align_done                 ; given
	moveq	#2,d0                           ; none: .W
data_align_done:
	move.w	(sp)+,d1
	rts
data_align_byte:
	lea	line_label(a6),a0               ; the line's label
	tst.l	(a0)                            ; any?
	beq.s	data_align_byte_size            ; no
	move.l	program_counter(a6),d4          ; the PC as its value
	bsr.w	asm_define_symbol               ; define it
data_align_byte_size:
	move.b	size_code(a6),d0                ; size 1
	bra.s	data_align_done

;------------------------------------------------------------------------------
; DCB count,value: count items of the given size, each the value (0 if left out).
;------------------------------------------------------------------------------
dir_dcb:	; from: mnemonic_table
	bsr.s	data_align_label                ; align, define the label
	bsr.w	eval_absolute                   ; the count (absolute, defined)
	cmp.b	#$2c,d1                         ; a value follows?
	beq.s	dir_dcb_value                   ; yes
	move.l	d2,-(sp)                        ; keep the count
	moveq	#0,d2                           ; no value: 0
	bra.s	dir_dcb_fill
dir_dcb_value:
	move.b	(a4)+,d1                        ; past the comma
	move.l	d2,-(sp)                        ; keep the count
	bsr.w	eval_absolute                   ; the value
dir_dcb_fill:
	moveq	#0,d3
	lea	data_size_shifts(pc),a0         ; shift per size
	move.l	d2,d1                           ; d1 = the fill value
	move.b	size_code(a6),d3                ; the size
	move.b	0(a0,d3.w),d3                   ; d3 = log2 of the item size
	move.l	(sp)+,d4                        ; d4 = the count

;------------------------------------------------------------------------------
; Fill d4 items of 2^d3 bytes with the value d1 (DS, DCB, RORG gaps).  When no binary is made, or in pass 1,
; only the byte count goes to reserve_bytes and the line's end steps the PC past it; in pass 2 with a binary the
; items are written to the output one by one (a BSS or OFFSET section still only reserves).
;------------------------------------------------------------------------------
data_fill:	; from: dir_ds, org_pad_to
	clr.l	line_code_size(a6)              ; no bytes made on this line
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	data_fill_reserve               ; no: reserve
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	data_fill_write                 ; yes: write the items
data_fill_reserve:
	lsl.l	d3,d4                           ; count to bytes
	bpl.w	data_fill_set_skip              ; not negative
	moveq	#82,d0                          ; "DCB or DS count must not be negative"
	bra.w	asm_line_error
data_fill_set_skip:
	move.l	d4,reserve_bytes(a6)            ; the line's end steps the PC
data_fill_done:
	move.b	-$1(a4),d1                      ; the character after the operands
	rts
data_fill_write:
	move.b	#$ff,asm_list_marker(a6)        ; the listing shows the address
	move.l	program_counter(a6),listing_value(a6) ; the PC for the listing
	bsr.w	obj_no_data                     ; a section without data?
	beq.s	data_fill_reserve               ; yes: reserve only
	clr.l	reserve_bytes(a6)               ; offset from the PC
	subq.l	#1,d4                           ; the dbra count
	bcs.s	data_fill_done                  ; none
	pea	data_fill_done(pc)              ; return through data_fill_done
	subq.b	#1,d3                           ; size 0: bytes
	bcs.s	data_fill_byte_loop
	beq.s	data_fill_word_loop             ; size 1: words
data_fill_long_loop:
	move.l	d1,(a5)+                        ; one long
	moveq	#4,d5                           ; 4 bytes
	bsr.s	data_fill_flush                 ; to the output
	dbra	d4,data_fill_long_loop          ; the next
	subi.l	#$10000,d4                      ; count above 64K
	bcc.s	data_fill_long_loop
	rts
data_fill_word_loop:
	move.w	d1,(a5)+                        ; one word
	moveq	#2,d5                           ; 2 bytes
	bsr.s	data_fill_flush                 ; to the output
	dbra	d4,data_fill_word_loop          ; the next
	subi.l	#$10000,d4                      ; count above 64K
	bcc.s	data_fill_word_loop
	rts
data_fill_byte_loop:
	move.b	d1,(a5)+                        ; one byte
	moveq	#1,d5                           ; 1 byte
	bsr.s	data_fill_flush                 ; to the output
	dbra	d4,data_fill_byte_loop          ; the next
	subi.l	#$10000,d4                      ; count above 64K
	bcc.s	data_fill_byte_loop
	rts

;------------------------------------------------------------------------------
; Write the d5 bytes in the code buffer to the output at PC + reserve_bytes, step reserve_bytes on and reset
; a5 to the buffer's start.  Keeps d1.
;------------------------------------------------------------------------------
data_fill_flush:	; from: data_fill
	move.l	d1,-(sp)                        ; keep the fill value
	move.l	d5,d1                           ; the byte count
	move.l	program_counter(a6),d2          ; the PC
	add.l	reserve_bytes(a6),d2            ; plus the bytes so far
	bsr.w	obj_emit                        ; write them
	add.l	d5,reserve_bytes(a6)            ; step on
	move.l	(sp)+,d1
	movea.l	code_buffer_ptr(a6),a5          ; the buffer again
	rts

;------------------------------------------------------------------------------
; DC.B/.W/.L: a list of values, and for .B also quoted strings.
;------------------------------------------------------------------------------
dir_dc:	; from: mnemonic_table
	bsr.w	data_align_label                ; align, define the label; d0 = size
	cmp.b	#$1,d0                          ; .B?
	beq.s	dir_dc_byte_loop                ; yes
	cmp.b	#$3,d0                          ; .L?
	beq.s	dir_dc_long_loop                ; yes
dir_dc_word_loop:
	bsr.w	asm_expression                  ; a value
	bsr.w	emit_immediate_word             ; store a word
	bsr.s	data_next_item                  ; a comma: on, else leave
	bra.s	dir_dc_word_loop
dir_dc_long_loop:
	bsr.w	asm_expression                  ; a value
	bsr.w	emit_immediate_long             ; store a long
	bsr.s	data_next_item                  ; a comma: on, else leave
	bra.s	dir_dc_long_loop

;------------------------------------------------------------------------------
; Within a DC list: at a comma, skip it and the blanks after it and return with d1 the next character; at
; anything else return from the caller instead (the list is over).
;------------------------------------------------------------------------------
data_next_item:	; from: dir_dc
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	data_next_item_none             ; no: the list ends
data_next_item_skip:
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$9,d1                          ; a tab?
	beq.s	data_next_item_skip             ; skip it
	cmp.b	#$20,d1                         ; a space?
	beq.s	data_next_item_skip             ; skip it
	rts
data_next_item_none:
	addq.l	#4,sp                           ; drop the caller's return
	rts                                     ; back to the caller's caller
dir_dc_byte_loop:	; from: dir_dc
	cmp.b	#$27,d1                         ; a single quote?
	beq.s	dir_dc_string                   ; a string
	cmp.b	#$22,d1                         ; a double quote?
	beq.s	dir_dc_string                   ; a string
dir_dc_byte_expr:
	bsr.w	asm_expression                  ; a value
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	dir_dc_byte_store               ; no: just store
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	dir_dc_byte_check               ; no
	tst.w	d3                              ; an imported symbol?
	bmi.s	dir_dc_byte_xref                ; yes: a byte reference
dir_dc_byte_check:
	bsr.w	check_byte_range                ; fits a byte?
dir_dc_byte_store:
	move.b	d2,(a5)+                        ; store it
dir_dc_byte_next:
	bsr.s	data_next_item                  ; a comma: on, else leave
	bra.s	dir_dc_byte_loop
dir_dc_byte_xref:
	bsr.w	obj_xref_byte                   ; a byte reference to the import
	bra.s	dir_dc_byte_next
dir_dc_string:
	move.b	d1,d3                           ; d3 = the quote
	movem.l	a4-a5,-(sp)                     ; keep them: it may be an expression
dir_dc_string_loop:
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	dir_dc_string_unclosed          ; yes: no closing quote
	cmp.b	d3,d1                           ; the quote?
	bne.s	dir_dc_string_char              ; no: store it
	move.b	(a4)+,d1                        ; after it
	cmp.b	d1,d3                           ; a second quote: one quote
	bne.s	dir_dc_string_end               ; no: the string ends
dir_dc_string_char:
	move.b	d1,(a5)+                        ; store a character
	bra.s	dir_dc_string_loop
dir_dc_string_end:
	cmp.b	#$d,d1                          ; then end of line,
	beq.s	dir_dc_string_done
	cmp.b	#$9,d1                          ; tab,
	beq.s	dir_dc_string_done
	cmp.b	#$20,d1                         ; space
	beq.s	dir_dc_string_done
	cmp.b	#$2c,d1                         ; or comma?
	beq.s	dir_dc_string_done              ; yes: it was a string
	movem.l	(sp)+,a4-a5                     ; no: an expression ('a'+1): back
	move.b	d3,d1                           ; the quote again
	bra.s	dir_dc_byte_expr                ; evaluate it
dir_dc_string_done:
	addq.l	#8,sp                           ; drop the saved a4/a5
	bsr.w	data_next_item                  ; a comma: on, else leave
	bra.s	dir_dc_byte_loop
dir_dc_string_unclosed:
	addq.l	#8,sp                           ; drop the saved a4/a5
	moveq	#53,d0                          ; "missing quote"
	bra.w	asm_error
data_size_shifts:	; from: dir_dcb, dir_ds
	dc.w	$0100,$0102                     ; log2 of the item size by size code: none 1, .B 0, .W 1, .L 2

;------------------------------------------------------------------------------
; DS count: reserve count items of the size (none is .W), zero-filled when written to the binary.
;------------------------------------------------------------------------------
dir_ds:	; from: mnemonic_table
	bsr.w	data_align_label                ; align, define the label; d0 = size
	ext.w	d0
	move.b	data_size_shifts(pc,d0.w),d6    ; log2 of the item size
	bsr.w	eval_absolute                   ; the count (absolute, defined)
	tst.l	d2                              ; none?
	beq.s	dir_ds_none                     ; yes: nothing to do
	move.l	d2,d4                           ; the count
	move.b	d6,d3                           ; the shift
	moveq	#0,d1                           ; filled with 0
	bra.w	data_fill                       ; fill or reserve
dir_ds_none:
	rts

;------------------------------------------------------------------------------
; END: the source ends here.
;------------------------------------------------------------------------------
dir_end:	; from: mnemonic_table
	st	asm_end_seen(a6)                ; end of source
	moveq	#13,d1                          ; the line is eaten
	rts

;------------------------------------------------------------------------------
; Check that the line has a label and that it is not a local one, for EQU, EQUR, SET and REG; errors (and
; the line's end) otherwise.  Returns a0 = line_label.
;------------------------------------------------------------------------------
need_global_label:	; from: dir_equ, dir_equr, dir_reg, dir_set, directive_macro
	lea	line_label(a6),a0               ; the line's label
	tst.l	(a0)                            ; any?
	beq.s	need_label_missing              ; no
	move.b	6(a0),d0                        ; its first character
	cmp.b	local_char(a6),d0               ; the local-label character?
	beq.s	need_label_local                ; yes
	rts
need_label_missing:
	moveq	#40,d0                          ; "symbol expected"
	bra.w	asm_line_error
need_label_local:
	moveq	#7,d0                           ; "local not allowed"
	bra.w	asm_line_error

;------------------------------------------------------------------------------
; label EQU value.  Pass 1 makes the symbol (absolute values in the equate tree, relocatable ones in the
; label tree) unless the value is not yet known; pass 2 checks the value and type have not changed.
;------------------------------------------------------------------------------
dir_equ:	; from: mnemonic_table
	bsr.s	need_global_label               ; a global label
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	dir_equ_pass2                   ; yes
	move.l	a0,-(sp)                        ; keep the label
	bsr.w	evaluate_no_import              ; the value: d2 value, d3 type, d4 undefined
	movea.l	(sp)+,a0
	tst.b	d4                              ; not known yet?
	bne.w	dir_equ_done                    ; then leave it undefined
	movem.l	d2-d3,-(sp)                     ; keep value and type
	bsr.w	asm_find_symbol                 ; look the name up
	movem.l	(sp)+,d4-d5                     ; d4 value, d5 type
	beq.w	report_defined_twice            ; found: "symbol defined twice"
	move.b	d5,d3                           ; the type
	pea	equate_list_reload(pc)          ; then show the value
	lea	equate_tree(a6),a2              ; the equate tree
	subq.b	#2,d5                           ; absolute?
	beq.w	asm_add_symbol                  ; yes: add it there
	lea	asm_module_tree(a6),a2          ; relocatable: the label tree
	bra.w	asm_add_symbol                  ; add it
dir_equ_pass2:
	bsr.w	asm_find_symbol                 ; look the name up
	bne.w	report_forward_reference        ; missing: "forward reference"
	btst	#$6,$c(a1)                      ; already set in pass 2?
	bne.w	report_defined_twice            ; yes: "symbol defined twice"
	move.l	a1,-(sp)                        ; keep the symbol
	bsr.w	evaluate_no_import              ; the value
	movea.l	(sp)+,a1
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	dir_equ_compare                 ; no
	tst.b	linkable_output(a6)             ; linkable output?
	bne.s	dir_equ_compare                 ; yes: as it is
	moveq	#0,d0
	move.b	current_section(a6),d0          ; the section
	lea	asm_section_table(a6),a0        ; the section bases
	sub.l	0(a0,d0.w),d2                   ; the value without its section's base
dir_equ_compare:
	cmp.l	8(a1),d2                        ; the same as in pass 1?
	bne.w	report_phasing                  ; no: "phasing error"
	cmp.b	$d(a1),d3                       ; the same type?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	bset	#$6,$c(a1)                      ; set in pass 2

;------------------------------------------------------------------------------
; Show d2 as "=value" in the listing; equate_list_reload first reloads d1 with the last character read.
;------------------------------------------------------------------------------
equate_list_reload:	; from: dir_equ, dir_set
	move.b	-$1(a4),d1                      ; the character after the operands
equate_list_value:	; from: dir_rs, dir_rsset, dir_set
	move.b	#$3d,asm_list_marker(a6)        ; "=" in the listing
	move.l	d2,listing_value(a6)            ; with this value
dir_equ_done:	; from: dir_equ
	rts

;------------------------------------------------------------------------------
; Define the symbols given on the command line (name=value, separated by commas, spaces or tabs, text at
; cmdline_symbols) as absolute constants, with the line number 0 for their error messages.
;------------------------------------------------------------------------------
define_cmdline_symbols:	; from: asm_entry
	move.l	a4,-(sp)                        ; keep a4
	clr.w	line_number(a6)                 ; line 0 for errors
	bsr.s	cmdline_symbols_parse           ; define them
	movea.l	(sp)+,a4
	addq.w	#1,line_number(a6)              ; line 1
	sf	asm_line_had_error(a6)          ; no error on this line
	rts

;------------------------------------------------------------------------------
; The loop of define_cmdline_symbols.  An error ("in command-line symbol") goes back to the caller through
; error_stack.
;------------------------------------------------------------------------------
cmdline_symbols_parse:	; from: define_cmdline_symbols
	move.l	sp,asm_line_sp(a6)              ; where an error returns to
	movea.l	asm_cmdline_symbols(a6),a4      ; the text
cmdline_symbols_skip:
	move.b	(a4)+,d1                        ; the next character
cmdline_symbols_char:
	tst.b	d1                              ; the end?
	beq.s	cmdline_symbols_done            ; yes
	cmp.b	#$d,d1                          ; CR: the end
	beq.s	cmdline_symbols_done
	cmp.b	#$9,d1                          ; tab,
	beq.s	cmdline_symbols_skip            ; skip
	cmp.b	#$20,d1                         ; space,
	beq.s	cmdline_symbols_skip            ; skip
	cmp.b	#$2c,d1                         ; comma
	beq.s	cmdline_symbols_skip            ; skip
	st	d2
	lea	line_label(a6),a0               ; the name buffer
	clr.b	4(a0)
	bsr.w	read_symbol_name                ; read the name
	bne.s	cmdline_symbols_bad             ; not a name
	cmp.b	#$3d,d1                         ; then "="?
	bne.s	cmdline_symbols_bad             ; no
	move.b	(a4)+,d1                        ; past it
	bsr.w	asm_expression                  ; the value
	tst.b	d4                              ; known?
	bne.s	cmdline_symbols_bad             ; no
	cmp.b	#$2,d3                          ; absolute?
	bne.s	cmdline_symbols_bad             ; no
	lea	line_label(a6),a0               ; the name
	movem.l	d1-d2,-(sp)                     ; keep value and character
	bsr.w	asm_find_symbol                 ; look it up
	movem.l	(sp)+,d1/d4                     ; d4 = the value
	beq.s	cmdline_symbols_bad             ; already there
	lea	equate_tree(a6),a2              ; the equate tree
	moveq	#2,d3                           ; absolute
	move.w	d1,-(sp)
	bsr.w	asm_add_symbol                  ; add it
	move.w	(sp)+,d1
	bra.s	cmdline_symbols_char            ; the next
cmdline_symbols_bad:
	moveq	#79,d0                          ; "in command-line symbol"
	bra.w	asm_error
cmdline_symbols_done:
	rts
dir_equr_bad:	; from: dir_equr
	moveq	#45,d0                          ; "register expected"
	bra.w	asm_error

;------------------------------------------------------------------------------
; label EQUR register: a register name, kept in the equate tree as type 4 with the A flag in byte 9 and
; the register number in byte $b of the value.
;------------------------------------------------------------------------------
dir_equr:	; from: mnemonic_table
	bsr.w	need_global_label               ; a global label
	bsr.w	parse_register                  ; a register: d0 0 data 1 address, d2 number
	bne.s	dir_equr_bad                    ; no
	swap	d2
	move.w	d0,d2                           ; A flag in the high word
	swap	d2
	andi.l	#$ff00ff,d2                     ; two bytes of it
	movea.l	equate_tree(a6),a2              ; the equate tree
	lea	line_label(a6),a0               ; the name
	movem.l	d2/a3-a5,-(sp)                  ; keep the value
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	dir_equr_pass2                  ; yes
	bsr.w	asm_tree_find                   ; look the name up
	movem.l	(sp)+,d4/a3-a5                  ; d4 = the value
	beq.w	report_defined_twice            ; found: "symbol defined twice"
	moveq	#4,d3                           ; type 4: register
	bsr.w	asm_new_symbol                  ; add it
	moveq	#13,d1                          ; the line is eaten
	rts
dir_equr_pass2:
	bsr.w	asm_tree_find                   ; look the name up
	movem.l	(sp)+,d4/a3-a5                  ; d4 = the value
	bne.w	report_additional_symbol        ; missing: "additional symbol on pass 2"
	cmpi.b	#$4,$d(a1)                      ; a register name?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	cmp.l	8(a1),d4                        ; the same register?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	bset	#$6,$c(a1)                      ; set in pass 2
	bne.w	report_defined_twice            ; twice: "symbol defined twice"
	moveq	#13,d1                          ; the line is eaten
	rts

;------------------------------------------------------------------------------
; EVEN: the dispatcher has aligned the PC already (instruction flag); no size allowed.
;------------------------------------------------------------------------------
dir_even:	; from: mnemonic_table
	tst.b	size_code(a6)                   ; a size?
	bne.w	report_invalid_size             ; "invalid size"
	move.w	#$d,d1                          ; the line is eaten
	rts

;------------------------------------------------------------------------------
; EXG Rx,Ry (opcode $c100): data, address or mixed pair; size .L or none.
;------------------------------------------------------------------------------
ins_exg:	; from: mnemonic_table
	bsr.w	asm_size_long                   ; size .L
	bsr.w	parse_register                  ; the first register
	bne.s	ins_exg_bad                     ; not one
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	movem.w	d0/d2,-(sp)                     ; keep kind and number
	bsr.w	parse_register                  ; the second register
	movem.w	(sp)+,d3-d4                     ; d3 kind, d4 number of the first
	bne.s	ins_exg_bad                     ; not one
	cmp.b	d0,d3                           ; the same kind?
	beq.s	ins_exg_same                    ; yes
	ori.b	#$88,d6                         ; mixed: mode $88
	tst.b	d3                              ; first is an address register?
	beq.s	ins_exg_store                   ; no
	exg	d4,d2                           ; the data register goes in Rx
ins_exg_store:
	or.b	d2,d6                           ; Ry
	andi.w	#$7,d4
	ror.w	#7,d4                           ; Rx to bits 9-11
	or.w	d4,d6
	move.w	d6,(a5)+                        ; the opcode
	rts
ins_exg_same:
	ori.b	#$40,d6                         ; mode $40: two data registers
	tst.b	d0                              ; address registers?
	beq.s	ins_exg_store                   ; no
	ori.b	#$8,d6                          ; mode $48: two address registers
	exg	d4,d2
	bra.s	ins_exg_store
ins_exg_bad:
	addq.l	#2,a5                           ; room for the opcode
	moveq	#45,d0                          ; "register expected"
	bra.w	asm_error

;------------------------------------------------------------------------------
; EXT.W/.L Dn (opcode $4880).
;------------------------------------------------------------------------------
ins_ext:	; from: mnemonic_table
	bsr.w	asm_size_not_byte               ; not .B
	cmpi.b	#$3,size_code(a6)               ; .L?
	bne.s	ins_ext_reg                     ; no
	ori.b	#$40,d6                         ; yes: bit 6
ins_ext_reg:
	bsr.w	parse_data_register             ; a data register
	or.b	d2,d6
	move.w	d6,(a5)+                        ; the opcode
	rts

;------------------------------------------------------------------------------
; FAIL: report "user error".
;------------------------------------------------------------------------------
dir_fail:	; from: mnemonic_table
	moveq	#13,d1                          ; the line is eaten
	moveq	#54,d0                          ; "user error"
	bra.w	asm_error

;------------------------------------------------------------------------------
; FORMAT n+/n-,...: set (+) or clear (-) listing format bit 7-n, n 0-7, in listing_format.
;------------------------------------------------------------------------------
dir_format:	; from: long_mnemonic_table
	lea	listing_format(a6),a0           ; the format flags
dir_format_loop:
	cmp.b	#$d,d1                          ; the end?
	beq.s	dir_format_done
	cmp.b	#$9,d1
	beq.s	dir_format_done
	cmp.b	#$20,d1
	beq.s	dir_format_done
	subi.b	#$30,d1                         ; a digit
	bcs.s	dir_format_bad                  ; below 0
	cmp.b	#$8,d1
	bcc.s	dir_format_bad                  ; above 7
	moveq	#7,d0                           ; the bit: 7-n
	sub.b	d1,d0
	move.b	(a4)+,d1                        ; then + or -
	cmp.b	#$2b,d1                         ; +?
	beq.s	dir_format_on                   ; yes
	cmp.b	#$2d,d1                         ; -?
	bne.s	dir_format_bad                  ; neither
	bclr	d0,(a0)                         ; - clears it
	bra.s	dir_format_next
dir_format_on:
	bset	d0,(a0)                         ; + sets it
dir_format_next:
	move.b	(a4)+,d1                        ; after it
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	dir_format_done                 ; no: done
	move.b	(a4)+,d1                        ; past it
	bra.s	dir_format_loop                 ; the next
dir_format_done:
	rts
dir_format_bad:
	moveq	#74,d0                          ; "invalid FORMAT parameter"
	bra.w	asm_error

;------------------------------------------------------------------------------
; IIF expression instruction: assemble the rest of the line only when the expression is not 0.
;------------------------------------------------------------------------------
dir_iif:	; from: mnemonic_table
	bsr.w	eval_absolute                   ; the condition (absolute, defined)
	tst.l	d2                              ; false?
	beq.w	asm_define_label                ; yes: just define the label
dir_iif_skip:
	cmp.b	#$9,d1                          ; a tab?
	beq.s	dir_iif_blank                   ; skip
	cmp.b	#$20,d1                         ; a space?
	bne.s	dir_iif_assemble                ; no: the instruction
dir_iif_blank:
	move.b	(a4)+,d1                        ; the next character
	bra.s	dir_iif_skip
dir_iif_assemble:
	bsr.w	asm_mnemonic                    ; assemble the rest as a line
	lea	dir_iif_after(pc),a0            ; the line's end does nothing more
	move.l	a0,line_end_hook(a6)
	moveq	#13,d1                          ; the line is eaten
dir_iif_after:
	rts

;------------------------------------------------------------------------------
; INCBIN filename: put the file's bytes into the code here (written straight to the binary in pass 2).
;------------------------------------------------------------------------------
dir_incbin:	; from: long_mnemonic_table
	tst.b	offset_section(a6)              ; BSS or OFFSET?
	bne.w	report_bss_data                 ; "BSS or OFFSET section cannot contain data"
	lea	line_label(a6),a0               ; the name buffer
	moveq	#0,d3                           ; 0 after the name
	bsr.w	read_string_name                ; read the file name
	lea	line_label_text(a6),a0          ; its text
	bsr.w	open_binary_file                ; open it: d3 handle, d2 length
	bne.s	dir_incbin_not_found            ; "file not found"
	move.l	d3,incbin_handle(a6)            ; the handle
	move.l	d2,reserve_bytes(a6)            ; the length: reserved
	beq.s	dir_incbin_close                ; empty
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	dir_incbin_close                ; no
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	dir_incbin_close                ; no
	move.l	d2,d1                           ; the length
	bsr.w	incbin_buffer_alloc             ; a buffer for it
	move.l	a0,-(sp)                        ; keep it
	move.l	reserve_bytes(a6),d1            ; the length
	move.l	incbin_handle(a6),d3            ; the handle
	bsr.w	read_binary_file                ; Fread the file
	move.l	reserve_bytes(a6),d1            ; the length
	movea.l	(sp),a0                         ; the buffer
	move.l	program_counter(a6),d2          ; at the PC
	bsr.w	obj_incbin                      ; to the binary
	movea.l	(sp)+,a0
	bsr.w	incbin_buffer_free              ; free the buffer
dir_incbin_close:
	move.l	incbin_handle(a6),d3            ; the handle
	clr.l	incbin_handle(a6)
	bsr.w	close_binary_file               ; Fclose
	moveq	#13,d1                          ; the line is eaten
	rts
dir_incbin_not_found:
	moveq	#26,d0                          ; "file not found"
	bra.w	asm_error

;------------------------------------------------------------------------------
; INCDIR dir,dir...: add directories to the include search list (names with a 0 after each, two 0s at the
; end, 500 bytes at most); a name may be in quotes.
;------------------------------------------------------------------------------
dir_incdir:	; from: long_mnemonic_table
	lea	asm_incdir_list(a6),a3          ; the list
	move.l	a3,d2                           ; its start
dir_incdir_find_end:
	tst.b	(a3)+                           ; to the end of a name
	bne.s	dir_incdir_find_end
	tst.b	(a3)+                           ; two 0s?
	bne.s	dir_incdir_find_end             ; no: the next name
	move.l	a3,d3
	sub.l	d2,d3                           ; d3 = the bytes used
	subq.l	#1,a3                           ; back on the last 0
dir_incdir_name:
	moveq	#0,d2                           ; no quote
	cmp.b	#$22,d1                         ; a double quote?
	beq.s	dir_incdir_quoted
	cmp.b	#$27,d1                         ; a single quote?
	bne.s	dir_incdir_char                 ; no
dir_incdir_quoted:
	move.b	d1,d2                           ; the quote
	move.b	(a4)+,d1                        ; past it
dir_incdir_char:
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	dir_incdir_done                 ; yes: done
	cmp.b	#$20,d1                         ; a space?
	bne.s	dir_incdir_not_space            ; no
	tst.b	d2                              ; inside quotes: part of the name
	bne.s	dir_incdir_store
	bra.s	dir_incdir_done                 ; else the end
dir_incdir_not_space:
	cmp.b	#$9,d1                          ; a tab: the end
	beq.s	dir_incdir_done
	cmp.b	d2,d1                           ; the closing quote?
	beq.s	dir_incdir_close_quote          ; yes
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	dir_incdir_store                ; no
	tst.b	d2                              ; inside quotes?
	beq.s	dir_incdir_end_name             ; no: the name ends
dir_incdir_store:
	addq.w	#1,d3                           ; count it
	cmp.w	#$1f4,d3                        ; full?
	bcc.s	dir_incdir_full                 ; yes
	move.b	d1,(a3)+                        ; store it
	move.b	(a4)+,d1                        ; the next character
	bra.s	dir_incdir_char
dir_incdir_close_quote:
	move.b	(a4)+,d1                        ; past the quote (the comma)
dir_incdir_end_name:
	addq.w	#1,d3                           ; count the 0
	cmp.w	#$1f4,d3                        ; full?
	bcc.s	dir_incdir_full                 ; yes
	clr.b	(a3)+                           ; end the name
	move.b	(a4)+,d1                        ; past the comma
	bra.s	dir_incdir_name                 ; the next name
dir_incdir_done:
	clr.b	(a3)+                           ; end the name
	clr.b	(a3)+                           ; and the list
	rts
dir_incdir_full:
	clr.w	asm_incdir_list(a6)             ; empty the list
	moveq	#77,d0                          ; "invalid INCDIR"
	bra.w	asm_error

;------------------------------------------------------------------------------
; INCLUDE filename: assemble the file's lines here; a failure is fatal.
;------------------------------------------------------------------------------
dir_include:	; from: long_mnemonic_table
	lea	line_label(a6),a0               ; the name buffer
	moveq	#11,d3                          ; terminator 11 after the name
	bsr.w	read_string_name                ; read the file name
	bsr.w	include_open                    ; include the file
	bne.w	asm_fatal_error                 ; failed: fatal error
	moveq	#13,d1                          ; the line is eaten
	rts

;------------------------------------------------------------------------------
; JMP/JSR <ea> (opcode $4ec0/$4e80): control addressing, no size.
;------------------------------------------------------------------------------
ins_jmp_jsr:	; from: mnemonic_table
	bsr.w	ea_store_parse_check            ; the opcode, then a control <ea>
	dc.w	$64                             ; modes: (An), memory, PC
	tst.b	size_code(a6)                   ; a size?
	bne.w	report_invalid_size             ; "invalid size"
	rts

;------------------------------------------------------------------------------
; LEA <ea>,An (opcode $41c0).
;------------------------------------------------------------------------------
ins_lea:	; from: mnemonic_table
	st	address_operand(a6)             ; an address operand
	bsr.w	ea_store_parse_check            ; the opcode, then a control <ea>
	dc.w	$64                             ; modes: (An), memory, PC
	sf	address_operand(a6)
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_register                  ; a register
	bne.w	address_register_error          ; no: "address register expected"
	tst.b	d0                              ; an address register?
	beq.w	address_register_error          ; no: "address register expected"
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	add.b	d2,d2                           ; An to bits 9-11
	or.b	d2,(a0)
	bsr.w	asm_size_long                   ; size .L or none
	rts

;------------------------------------------------------------------------------
; LINK An,#displacement (opcode $4e50); warns when the displacement is odd or above 0.
;------------------------------------------------------------------------------
ins_link:	; from: mnemonic_table
	tst.b	size_code(a6)                   ; a size?
	bne.w	report_invalid_size             ; "invalid size"
	bsr.w	parse_address_register          ; an address register
	or.b	d2,d6
	move.w	d6,(a5)+                        ; the opcode
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; "immediate data expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	asm_expression                  ; the displacement
	bsr.w	emit_immediate_word             ; store a word
	btst	#$0,d2                          ; odd?
	bne.s	ins_link_warn                   ; yes: warn
	tst.w	d2                              ; above 0?
	bgt.s	ins_link_warn                   ; yes: warn
	rts
ins_link_warn:
	moveq	#3,d0                           ; "invalid LINK displacement"
	bra.w	asm_warning                     ; a warning
dir_listchar_next:	; from: dir_listchar
	move.b	(a4)+,d1                        ; past the comma

;------------------------------------------------------------------------------
; LISTCHAR value,...: send bytes to the listing (printer control codes), in pass 2 when listing is on.
;------------------------------------------------------------------------------
dir_listchar:	; from: long_mnemonic_table
	bsr.w	evaluate_absolute               ; a value
	bsr.w	check_byte_range                ; fits a byte?
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	dir_listchar_comma              ; no
	tst.b	asm_listing_active(a6)          ; listing on?
	beq.s	dir_listchar_comma              ; no
	move.w	d1,-(sp)                        ; keep d1
	move.b	d2,d1                           ; the byte
	bsr.w	listing_put_char                ; to the listing
	move.w	(sp)+,d1
dir_listchar_comma:
	cmp.b	#$2c,d1                         ; a comma?
	beq.s	dir_listchar_next               ; the next
	st	line_not_listed(a6)             ; the line is not listed
	rts

;------------------------------------------------------------------------------
; LLEN n: the listing's line length, 38 to 254.
;------------------------------------------------------------------------------
dir_llen:	; from: mnemonic_table
	bsr.w	eval_absolute                   ; the value (absolute, defined)
	cmp.l	#$26,d2                         ; below 38?
	bcs.w	printer_param_bad               ; "invalid printer parameter"
	cmp.l	#$ff,d2                         ; above 254?
	bcc.w	printer_param_bad               ; "invalid printer parameter"
	move.w	d2,page_width(a6)               ; the line length
	st	line_not_listed(a6)             ; the line is not listed
	rts

;------------------------------------------------------------------------------
; ANDI/ORI/EORI #data,<ea> (opcodes $0200/$0000/$0a00), also to CCR and SR.  The <ea> parse returns past its
; mask word plus 2 (at $6c7c) for CCR or SR.
;------------------------------------------------------------------------------
ins_logic_imm:	; from: mnemonic_table
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; "immediate data expected"
	move.b	(a4)+,d1                        ; past it
ins_logic_imm_ea:	; from: ins_logic_to_imm
	bsr.w	or_size_bits                    ; the size bits
	move.w	d6,(a5)+                        ; the opcode
	bsr.w	evaluate_immediate              ; the immediate data, by size
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	ea_parse_check                  ; the <ea>, no opcode store
	dc.w	$33d                            ; modes: data alterable, CCR, SR
	rts
	movea.l	code_buffer_ptr(a6),a0          ; CCR or SR: here.  the opcode
	addq.l	#1,a0                           ; its low byte
	subq.b	#1,d5                           ; CCR?
	beq.s	ins_logic_imm_ccr               ; yes
	move.b	#$7c,(a0)                       ; to SR: $7c
	moveq	#2,d0                           ; size .W or none
	bra.s	asm_size_must_be
ins_logic_imm_ccr:
	move.b	#$3c,(a0)+                      ; to CCR: $3c
	cmpi.b	#$3,size_code(a6)               ; .L?
	beq.w	report_invalid_size             ; "invalid size"
	rts

;------------------------------------------------------------------------------
; Error "invalid size" unless the size is d0 or none.
;------------------------------------------------------------------------------
asm_size_must_be:	; from: asm_size_long, asm_size_byte, asm_size_word, ins_logic_imm
	cmp.b	size_code(a6),d0                ; the size wanted?
	beq.s	asm_size_ok                     ; yes
	tst.b	size_code(a6)                   ; none?
	bne.w	report_invalid_size             ; no: "invalid size"
asm_size_ok:
	rts

;------------------------------------------------------------------------------
; AND/OR/EOR #data: assembled as ANDI/ORI/EORI.
;------------------------------------------------------------------------------
ins_logic_to_imm:	; from: ins_logic
	move.b	(a4)+,d1                        ; past the #
	move.w	d6,d0                           ; which one
	move.w	#$200,d6                        ; ANDI
	cmp.w	#$c000,d0                       ; AND?
	beq.s	ins_logic_imm_ea
	moveq	#0,d6                           ; ORI
	cmp.w	#$8000,d0                       ; OR?
	beq.s	ins_logic_imm_ea
	move.w	#$a00,d6                        ; EORI
	bra.s	ins_logic_imm_ea

;------------------------------------------------------------------------------
; AND/OR/EOR (opcodes $c000/$8000/$b000): <ea>,Dn or Dn,<ea>; EOR only Dn,<ea>; #data goes to the I forms.
;------------------------------------------------------------------------------
ins_logic:	; from: mnemonic_table
	cmp.b	#$23,d1                         ; #?
	beq.s	ins_logic_to_imm                ; yes: the immediate form
	bsr.w	or_size_bits                    ; the size bits
	move.w	d6,(a5)+                        ; the opcode
	bsr.w	ea_parse_pc_allowed             ; the first <ea>, PC-relative allowed
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	move.b	d5,d0                           ; the first <ea>
	andi.b	#$78,d0                         ; a data register?
	bne.w	ins_logic_to_dn                 ; no: then <ea>,Dn
	add.b	d5,d5                           ; Dn to bits 9-11
	addq.b	#1,d5                           ; and bit 8: Dn,<ea>
	or.b	d5,-$2(a5)
	bsr.w	ea_parse                        ; the second <ea>
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	move.w	#$3c,d0                         ; modes: memory alterable
	move.b	d5,d2
	andi.b	#$78,d2                         ; a data register too?
	bne.s	ins_logic_to_mem                ; no
	move.w	#$fd,d0                         ; modes: all but An
	btst	#$d,d6                          ; EOR?
	bne.s	ins_logic_to_mem                ; yes: EOR Dx,Dy as it is
	move.b	(a0),d0                         ; AND/OR Dx,Dy: as Dx,Dy in the <ea>,Dn form
	lsr.b	#1,d0                           ; the first register from bits 9-11
	andi.w	#$7,d0
	or.w	d0,(a0)                         ; as the <ea>
	add.b	d5,d5
	andi.w	#$f0ff,(a0)                     ; clear bits 8-11
	or.b	d5,(a0)                         ; the second in bits 9-11
	rts
ins_logic_to_mem:
	or.w	d5,(a0)                         ; the <ea>
	bra.w	ea_check_mode                   ; allowed?
ins_logic_to_dn:
	btst	#$d,d6                          ; EOR?
	bne.w	ea_mode_not_allowed             ; yes: "addressing mode not allowed"
	move.w	#$fd,d0                         ; modes: all but An
	bsr.w	ea_or_check                     ; check and store the first <ea>
	bsr.w	parse_data_register             ; then a data register
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	add.b	d2,d2                           ; Dn to bits 9-11
	or.b	d2,(a0)
	rts

;------------------------------------------------------------------------------
; ADDQ/SUBQ #1-8,<ea> (opcodes $5000/$5100).
;------------------------------------------------------------------------------
ins_addq_subq:	; from: mnemonic_table
	bsr.w	or_size_bits                    ; the size bits
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; "immediate data expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	evaluate_absolute               ; the count
	bsr.s	quick_count_check               ; 1-8, 8 as 0
	ror.w	#7,d2                           ; to bits 9-11
	or.w	d2,d6
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	ea_store_parse_check            ; the opcode, then the <ea>
	dc.w	$3f                             ; modes: alterable
	rts

;------------------------------------------------------------------------------
; In pass 2 check d2 is 1-8 (error "data too large" otherwise) and turn 8 into 0.
;------------------------------------------------------------------------------
quick_count_check:	; from: ins_addq_subq, ins_shift
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	quick_count_ok                  ; no
	tst.l	d2                              ; 0?
	beq.s	quick_count_bad                 ; bad
	cmp.l	#$8,d2                          ; above 8?
	bhi.s	quick_count_bad                 ; bad
	bne.s	quick_count_ok                  ; below 8: as it is
	moveq	#0,d2                           ; 8 is 0
quick_count_ok:
	rts
quick_count_bad:
	moveq	#28,d0                          ; "data too large"
	bra.w	asm_error

;------------------------------------------------------------------------------
; MODULE/IDNT name: start a new module in GST linkable output; ignored otherwise.
;------------------------------------------------------------------------------
dir_module:	; from: mnemonic_table, long_mnemonic_table
	bsr.w	linkable_only                   ; linkable output only
	move.w	linker_format(a6),d2            ; the output format
	tst.w	d2                              ; GST?
	bne.s	dir_module_ignored              ; no: ignored
	bsr.w	end_module_output               ; in pass 2 tell the output a module starts
	movea.l	a4,a0                           ; the name
	move.b	-$1(a4),d1
	bsr.w	start_module_text               ; set the module name
	moveq	#13,d1                          ; the line is eaten
	rts
dir_module_ignored:
	moveq	#6,d0                           ; "directive ignored"
	bra.w	asm_warning                     ; a warning

;------------------------------------------------------------------------------
; MOVE.L #n,Dn with optimising option 4 on: made MOVEQ when n is known, absolute and fits a byte.
;------------------------------------------------------------------------------
ins_move_try_moveq:	; from: ins_move
	move.b	(a4)+,d1                        ; past the #
	bsr.w	asm_expression                  ; the value
	tst.b	d4                              ; not known yet?
	bne.w	ins_move_imm_source             ; then MOVE.L
	cmp.b	#$2,d3                          ; absolute?
	bne.s	ins_move_imm_source             ; no: MOVE.L
	cmp.b	#$2c,d1                         ; then a comma?
	bne.s	ins_move_imm_source             ; no: MOVE.L
	move.l	d2,d4                           ; the value
	move.l	a4,-(sp)                        ; keep the place
	move.b	(a4)+,d1                        ; past the comma
	bsr.w	parse_register                  ; a register?
	bne.s	ins_move_moveq_no               ; no
	tst.b	d0                              ; a data register?
	bne.s	ins_move_moveq_no               ; no
	move.l	d4,d0
	ext.w	d0
	ext.l	d0
	cmp.l	d0,d4                           ; fits a signed byte?
	bne.s	ins_move_moveq_no               ; no
	btst	#$3,optimise_flags(a6)          ; optimising option 4?
	beq.w	ins_move_moveq_no               ; no
	subq.l	#2,a5                           ; drop the MOVE opcode
	bsr.w	optimisation_check              ; the optimisation allowed?
	bne.s	ins_move_moveq_undo             ; no
	addq.l	#4,sp                           ; drop the saved place
	ori.b	#$38,d2                         ; MOVEQ
	add.b	d2,d2                           ; Dn to bits 9-11
	lsl.w	#8,d2
	or.b	d4,d2                           ; the byte
	move.w	d2,(a5)+                        ; the opcode
	moveq	#11,d0                          ; count optimisation 11
	bra.w	asm_optimisation
ins_move_moveq_undo:
	addq.l	#2,a5                           ; the MOVE opcode back
ins_move_moveq_no:
	movea.l	(sp)+,a4                        ; back to the comma
	moveq	#44,d1                          ; a comma
	move.l	d4,d2                           ; the value
ins_move_imm_source:
	bsr.w	emit_immediate                  ; store it as immediate data
	bra.s	ins_move_dest                   ; then the destination
move_size_bits:	; from: ins_move
	dc.w	$3000,$1000,$3000,$2000         ; MOVE size bits by size code: none .W, .B, .W, .L

;------------------------------------------------------------------------------
; MOVE <ea>,<ea> (table opcode 0), also to and from CCR, SR and USP; MOVE.L #n,Dn may become MOVEQ.
;------------------------------------------------------------------------------
ins_move:	; from: mnemonic_table
	moveq	#0,d0
	move.b	size_code(a6),d0                ; the size
	add.b	d0,d0
	or.w	move_size_bits(pc,d0.w),d6      ; its size bits
	move.w	d6,(a5)+                        ; the opcode
	cmp.b	#$6,d0                          ; .L?
	bne.s	ins_move_source                 ; no
	cmp.b	#$23,d1                         ; #?
	bne.s	ins_move_source                 ; no
	btst	#$3,optimise_flags(a6)          ; optimising option 4?
	bne.w	ins_move_try_moveq              ; yes: try MOVEQ
ins_move_source:
	bsr.w	ea_parse_pc_allowed             ; the source, PC-relative allowed
ins_move_dest:	; from: ins_move_try_moveq
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	btst	#$6,d5                          ; CCR, SR or USP?
	bne.w	ins_move_from_special           ; yes
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	or.w	d5,(a0)                         ; the source <ea>
	bsr.w	ea_parse                        ; the destination
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	btst	#$6,d5                          ; CCR, SR or USP?
	bne.s	ins_move_to_special             ; yes
	move.w	d5,d2
	move.w	d5,d0
	andi.b	#$7,d0                          ; the register
	add.b	d0,d0                           ; to bits 9-11
	or.b	d0,(a0)
	andi.w	#$38,d5                         ; the mode
	add.w	d5,d5                           ; to bits 6-8
	add.w	d5,d5
	add.w	d5,d5
	or.w	d5,(a0)
	andi.w	#$3f,d2
	cmp.w	#$3a,d2                         ; PC-relative or immediate?
	bcc.w	ea_mode_not_allowed             ; yes: "addressing mode not allowed"
	rts
ins_move_to_special:
	move.w	(a0),d4                         ; the opcode with the source
	lsr.b	#1,d5                           ; CCR?
	bcs.s	ins_move_to_ccr                 ; yes
	lsr.b	#1,d5                           ; SR?
	bcs.s	ins_move_to_sr                  ; yes
	move.b	d4,d0                           ; to USP: the source mode
	andi.b	#$38,d0
	cmp.b	#$8,d0                          ; an address register?
	bne.w	ea_mode_not_allowed             ; no: "addressing mode not allowed"
	andi.w	#$7,d4                          ; its number
	ori.w	#$4e60,d4                       ; MOVE An,USP
	move.w	d4,(a0)
	bra.w	asm_size_long                   ; size .L or none
ins_move_to_ccr:
	move.w	#$44c0,d6                       ; MOVE to CCR
	cmpi.b	#$3,size_code(a6)               ; .L?
	bne.s	ins_move_to_sr_ea               ; no
	bsr.w	report_invalid_size             ; "invalid size"
ins_move_to_sr_ea:
	andi.w	#$3f,d4                         ; the source <ea>
	move.b	d4,d0
	andi.b	#$38,d0
	cmp.b	#$8,d0                          ; an address register?
	beq.w	ea_mode_not_allowed             ; yes: "addressing mode not allowed"
	or.w	d4,d6
	move.w	d6,(a0)                         ; the opcode
	rts
ins_move_to_sr:
	bsr.w	asm_size_word                   ; size .W or none
	move.w	#$46c0,d6                       ; MOVE to SR
	bra.s	ins_move_to_sr_ea
ins_move_from_special:
	movea.l	code_buffer_ptr(a6),a2          ; the opcode
	lsr.b	#1,d5                           ; from CCR?
	bcs.s	ins_move_from_ccr               ; yes
	lsr.b	#1,d5                           ; from SR?
	bcs.s	ins_move_from_sr                ; yes
	bsr.w	parse_address_register          ; from USP: an address register
	move.w	#$4e68,d6                       ; MOVE USP,An
	or.b	d2,d6
	move.w	d6,(a2)                         ; the opcode
	bra.w	asm_size_long                   ; size .L or none

;------------------------------------------------------------------------------
; MOVE SR,<ea>: opcode $40c0 at a2, a data alterable <ea>, size .W.
;------------------------------------------------------------------------------
ins_move_from_sr:	; from: ins_move
	move.w	#$40c0,(a2)                     ; MOVE from SR
	bsr.w	ea_parse_check                  ; the <ea>
	dc.w	$3d                             ; modes: data alterable
	bra.w	asm_size_word                   ; size .W or none
ins_move_from_ccr:	; from: ins_move
	bsr.s	ins_move_from_sr                ; as MOVE from SR
	moveq	#4,d0                           ; "68010 instruction, converted to MOVE SR"
	bra.w	asm_warning                     ; a warning

;------------------------------------------------------------------------------
; MOVEM.W/.L list,<ea> or <ea>,list (opcode $4880); a list is registers with - and /, or a REG name.
;------------------------------------------------------------------------------
ins_movem:	; from: long_mnemonic_table
	move.b	size_code(a6),d0                ; the size
	beq.s	ins_movem_parse                 ; none
	cmp.b	#$2,d0                          ; .W?
	beq.s	ins_movem_parse
	cmp.b	#$3,d0                          ; .L?
	bne.w	report_invalid_size             ; no: "invalid size"
	ori.b	#$40,d6                         ; .L: bit 6
ins_movem_parse:
	bsr.s	asm_parse_register_list         ; a register list first?
	bne.w	ins_movem_to_regs               ; no: <ea>,list
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	move.w	d6,(a5)+                        ; the opcode
	move.w	d4,(a5)+                        ; the mask
	bsr.w	ea_parse                        ; the <ea>
	cmp.w	#$40,d5                         ; CCR, SR or USP?
	bcc.w	ea_mode_not_allowed             ; yes: "addressing mode not allowed"
	move.b	d5,d2
	andi.b	#$38,d2                         ; the mode
	cmp.b	#$20,d2                         ; -(An)?
	bne.s	ins_movem_check_ea              ; no
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ins_movem_check_ea              ; no
	movea.l	code_buffer_ptr(a6),a0          ; the code
	move.l	(a0),d0                         ; opcode and mask
	moveq	#0,d2
	moveq	#15,d3                          ; 16 bits
ins_movem_reverse:
	lsl.w	#1,d0                           ; reverse the mask for -(An)
	roxr.w	#1,d2
	dbra	d3,ins_movem_reverse
	move.w	d2,2(a0)                        ; the new mask
ins_movem_check_ea:
	moveq	#52,d0                          ; modes: (An), -(An), memory
	bra.w	ea_or_check                     ; check and store the <ea>
ins_movem_to_regs:
	ori.w	#$400,d6                        ; memory to registers
	move.w	d6,(a5)+                        ; the opcode
	addq.l	#2,a5                           ; room for the mask
	bsr.w	ea_parse_check                  ; the <ea>
	dc.w	$6c                             ; modes: (An), (An)+, memory, PC
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.s	asm_parse_register_list         ; the register list
	bne.s	reglist_bad                     ; "invalid register list"
	movea.l	code_buffer_ptr(a6),a0
	move.w	d4,2(a0)                        ; the mask
	rts

;------------------------------------------------------------------------------
; Read a MOVEM register list (D0-D7 bits 0-7, A0-A7 bits 8-15, ranges with -, / between) or a REG name.
; Returns Z and d0 = 0 with d4 = the mask, or NE when the operand is not a list; errors on a bad range.
;------------------------------------------------------------------------------
asm_parse_register_list:	; from: ins_movem, dir_reg
	moveq	#0,d4                           ; the mask
	bsr.w	parse_register                  ; a register?
	beq.s	reglist_register                ; yes
	lea	name_buffer(a6),a0              ; else a name
	movem.l	d1/a4,-(sp)
	bsr.w	read_symbol_name                ; read the name
	bne.s	reglist_not_list                ; not one
	movea.l	equate_tree(a6),a2              ; the equate tree
	movem.l	d1/d3/a3-a5,-(sp)
	bsr.w	asm_tree_find                   ; look it up
	movem.l	(sp)+,d1/d3/a3-a5
	bne.s	reglist_not_list                ; not there
	cmpi.b	#$5,$d(a1)                      ; a REG name?
	bne.s	reglist_not_list                ; no
	move.l	8(a1),d4                        ; its mask
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	reglist_symbol_ok               ; no
	btst	#$6,$c(a1)                      ; set in pass 2?
	beq.s	reglist_symbol_undefined        ; no
reglist_symbol_ok:
	addq.l	#8,sp                           ; drop the saved d1/a4
	moveq	#0,d0                           ; Z: a list
	rts
reglist_symbol_undefined:
	moveq	#-1,d0                          ; NE
reglist_not_list:
	movem.l	(sp)+,d1/a4                     ; back where it started
	rts
reglist_register:
	lsl.b	#3,d0                           ; address registers from 8
	add.b	d2,d0                           ; the bit
	cmp.b	#$2d,d1                         ; a range?
	beq.s	reglist_range                   ; yes
	bset	d0,d4                           ; the register's bit
reglist_separator:
	cmp.b	#$2f,d1                         ; a / ?
	beq.s	reglist_next                    ; yes: another
	moveq	#0,d0                           ; Z: done
	rts
reglist_next:
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_register                  ; a register?
	beq.s	reglist_register                ; yes
reglist_bad:	; from: ins_movem, dir_reg
	moveq	#55,d0                          ; "invalid register list"
	bra.w	asm_line_error
reglist_range:
	move.b	(a4)+,d1                        ; after the -
	cmp.b	#$38,d1                         ; a digit alone (D0-7)?
	bcc.s	reglist_range_register          ; no
	cmp.b	#$30,d1
	bcs.s	reglist_range_register          ; no
	move.b	d0,d3                           ; the first
	andi.b	#$8,d0                          ; the same kind
	subi.b	#$30,d1
	add.b	d1,d0                           ; the last
	move.b	(a4)+,d1                        ; past it
	bra.s	reglist_range_check
reglist_range_register:
	move.w	d0,-(sp)                        ; keep the first
	bsr.w	parse_register                  ; the last: a register
	bne.s	reglist_bad                     ; no: bad
	lsl.b	#3,d0
	add.b	d2,d0                           ; the last's bit
	move.w	(sp)+,d3                        ; the first
reglist_range_check:
	cmp.b	d3,d0                           ; backwards?
	bcs.s	reglist_bad                     ; yes: bad
	addq.b	#1,d0
reglist_range_loop:
	bset	d3,d4                           ; set first to last
	addq.b	#1,d3
	cmp.b	d0,d3
	bne.s	reglist_range_loop
	bra.s	reglist_separator

;------------------------------------------------------------------------------
; MOVEA.W/.L <ea>,An (opcode $2040, .L; .W or none makes $3040).
;------------------------------------------------------------------------------
ins_movea:	; from: long_mnemonic_table
	bsr.w	ea_store_parse_check            ; the opcode, then any <ea>
	dc.w	$ff                             ; all modes
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_address_register          ; an address register
	add.b	d2,d2                           ; to bits 9-11
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	or.b	d2,(a0)
	move.b	size_code(a6),d0                ; the size
	beq.s	ins_movea_word                  ; none: .W
	cmp.b	#$3,d0                          ; .L?
	beq.s	ins_movea_done                  ; yes
	cmp.b	#$2,d0                          ; .W?
	bne.w	report_invalid_size             ; no: "invalid size"
ins_movea_word:
	ori.b	#$10,(a0)                       ; MOVEA.W
ins_movea_done:
	rts

;------------------------------------------------------------------------------
; MOVEP.W/.L Dn,d(An) or d(An),Dn (opcode $0108).
;------------------------------------------------------------------------------
ins_movep:	; from: long_mnemonic_table
	move.b	size_code(a6),d0                ; the size
	cmp.b	#$1,d0                          ; .B?
	beq.w	report_invalid_size             ; "invalid size"
	cmp.b	#$3,d0                          ; .L?
	bne.s	ins_movep_operands              ; no
	ori.b	#$40,d6                         ; .L: bit 6
ins_movep_operands:
	bsr.w	parse_register                  ; a register first?
	bne.s	ins_movep_from_mem              ; no: d(An),Dn
	tst.b	d0                              ; an address register?
	bne.w	ins_movep_bad                   ; "invalid MOVEP addressing mode"
	ori.b	#$80,d6                         ; register to memory
	andi.w	#$7,d2                          ; the data register
	ror.w	#7,d2                           ; to bits 9-11
	or.w	d2,d6
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	moveq	#0,d2                           ; displacement 0
	cmp.b	#$28,d1                         ; no displacement?
	beq.s	ins_movep_to_mem_an             ; yes
	bsr.w	evaluate_no_import              ; the displacement
	bsr.w	check_signed_word_absolute      ; fits a word?
	cmp.b	#$28,d1                         ; then (?
	bne.s	ins_movep_bad                   ; no: "invalid MOVEP addressing mode"
ins_movep_to_mem_an:
	move.b	(a4)+,d1                        ; past it
	move.w	d2,d3                           ; the displacement
	bsr.w	parse_address_register          ; an address register
	or.b	d2,d6
	cmp.b	#$29,d1                         ; )?
	bne.s	ins_movep_bad                   ; no: "invalid MOVEP addressing mode"
	move.b	(a4)+,d1                        ; past it
ins_movep_store:
	move.w	d6,(a5)+                        ; the opcode
	move.w	d3,(a5)+                        ; the displacement
	rts
ins_movep_from_mem:
	moveq	#0,d2                           ; displacement 0
	cmp.b	#$28,d1                         ; no displacement?
	beq.s	ins_movep_from_mem_an           ; yes
	bsr.w	evaluate_no_import              ; the displacement
	bsr.w	check_signed_word_absolute      ; fits a word?
	cmp.b	#$28,d1                         ; then (?
	bne.s	ins_movep_bad                   ; no: "invalid MOVEP addressing mode"
ins_movep_from_mem_an:
	move.b	(a4)+,d1                        ; past it
	move.w	d2,d3                           ; the displacement
	bsr.w	parse_address_register          ; an address register
	or.b	d2,d6
	cmp.b	#$29,d1                         ; )?
	bne.s	ins_movep_bad                   ; no: "invalid MOVEP addressing mode"
	move.b	(a4)+,d1                        ; past it
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_data_register             ; a data register
	andi.w	#$7,d2
	ror.w	#7,d2                           ; to bits 9-11
	or.w	d2,d6
	bra.s	ins_movep_store                 ; store
ins_movep_bad:
	moveq	#46,d0                          ; "invalid MOVEP addressing mode"
	bra.w	asm_error

;------------------------------------------------------------------------------
; MOVEQ #n,Dn (opcode $7000): 128-255 is taken with a warning unless .L, larger is an error.
;------------------------------------------------------------------------------
ins_moveq:	; from: long_mnemonic_table
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; "immediate data expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	asm_expression                  ; the value
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ins_moveq_reg                   ; no
	bsr.w	check_not_relative              ; relocatable: "relative not allowed"
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	ins_moveq_range                 ; no
	tst.w	d3                              ; an import?
	bmi.s	ins_moveq_xref                  ; yes: a byte reference
ins_moveq_range:
	move.b	d2,d0
	ext.w	d0
	ext.l	d0
	cmp.l	d0,d2                           ; fits a signed byte?
	beq.s	ins_moveq_reg                   ; yes
	cmp.l	#$100,d2                        ; up to 255?
	bcs.s	ins_moveq_sign_warn             ; yes
	bsr.w	report_data_too_large           ; no: "data too large"
	bra.s	ins_moveq_reg
ins_moveq_sign_warn:
	cmpi.b	#$3,size_code(a6)               ; .L given?
	beq.s	ins_moveq_reg                   ; yes: no warning
	moveq	#1,d0                           ; "sign extended operand"
	bsr.w	asm_warning                     ; a warning
ins_moveq_reg:
	move.b	d2,d6                           ; the data byte
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_data_register             ; a data register
	add.b	d2,d2                           ; to bits 9-11
	moveq	#112,d0                         ; $70 high byte
	or.b	d2,d0
	move.b	d0,(a5)+                        ; the opcode's high byte
	move.b	d6,(a5)+                        ; the data
	rts
ins_moveq_xref:
	move.l	d2,-(sp)                        ; keep the value
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_data_register             ; a data register
	add.b	d2,d2                           ; to bits 9-11
	moveq	#112,d0                         ; $70 high byte
	or.b	d2,d0
	move.b	d0,(a5)+                        ; the opcode's high byte
	move.l	(sp)+,d2
	bra.w	obj_xref_byte                   ; the low byte: a byte reference

;------------------------------------------------------------------------------
; NBCD <ea> (opcode $4800), size .B.
;------------------------------------------------------------------------------
ins_nbcd:	; from: mnemonic_table
	bsr.w	asm_size_byte                   ; size .B or none
	bsr.w	ea_store_parse_check            ; the opcode, then the <ea>
	dc.w	$3d                             ; modes: data alterable
	rts

;------------------------------------------------------------------------------
; OFFSET [address]: start the offset section at the address (0 if none): labels become absolute and no
; data may be made.
;------------------------------------------------------------------------------
dir_offset:	; from: long_mnemonic_table
	cmp.b	#$9,d1                          ; a tab?
	beq.s	dir_offset_skip                 ; skip
	cmp.b	#$20,d1                         ; a space?
	bne.s	dir_offset_value                ; no
dir_offset_skip:
	move.b	(a4)+,d1                        ; skip
	bra.s	dir_offset
dir_offset_value:
	moveq	#0,d2                           ; none: 0
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	dir_offset_set
	cmp.b	#$2a,d1                         ; a comment?
	beq.s	dir_offset_set
	cmp.b	#$3b,d1
	beq.s	dir_offset_set
	bsr.w	eval_absolute                   ; the start (absolute, defined)
dir_offset_set:
	move.l	d2,-(sp)                        ; keep it
	bsr.w	save_section_pc                 ; save the current section's PC
	move.l	(sp)+,d2
	lea	offset_section_record(a6),a1    ; the offset section's record
	move.l	a1,current_section_record(a6)   ; as the current section
	move.l	d2,8(a1)                        ; its PC
	clr.b	$e(a1)
	move.l	d2,program_counter(a6)          ; the PC
	lea	line_code(a6),a0                ; the normal code buffer
	move.l	a0,code_buffer_ptr(a6)
	move.b	#$2,asm_section_type(a6)        ; labels are absolute
	st	offset_section(a6)              ; no data allowed
	move.b	-$1(a4),d1                      ; the character after the operands
opt_end:	; from: dir_opt
	rts

;------------------------------------------------------------------------------
; ORG address[.W]: absolute code from the address on, where the output format allows it.  ORG.B/.W also makes
; absolute addresses short.
;------------------------------------------------------------------------------
dir_org:	; from: mnemonic_table
	bsr.w	eval_absolute                   ; the address (absolute, defined)
	move.l	d2,-(sp)                        ; keep it
	bsr.w	obj_org                         ; allowed here?
	movem.l	(sp)+,d2
	bne.s	org_not_allowed                 ; no: "ORG/RORG not allowed"
	move.l	d2,program_counter(a6)          ; the PC
	lea	listing_no_code(pc),a0          ; at the line's end
	move.l	a0,line_end_hook(a6)
	move.b	-$1(a4),d1                      ; the character after the operands
	st	asm_absolute_code(a6)           ; ORG used
	sf	org_short(a6)                   ; long absolute addresses
	move.b	#$d,asm_section_type(a6)        ; labels get the ORG type
	move.b	size_code(a6),d0                ; the size
	beq.s	dir_org_done                    ; none: long
	cmp.b	#$3,d0                          ; .L?
	beq.s	dir_org_done                    ; yes
	st	org_short(a6)                   ; .B/.W: short absolute addresses
dir_org_done:
	rts
org_not_allowed:	; from: dir_rorg
	moveq	#67,d0                          ; "ORG/RORG not allowed"
	bra.w	asm_error
dir_opt_next:	; from: dir_opt
	move.b	(a4)+,d1                        ; past the comma

;------------------------------------------------------------------------------
; OPT letter...,letter...: the assembler options, by the A-Z table opt_letter_table.
;------------------------------------------------------------------------------
dir_opt:	; from: mnemonic_table
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	opt_end                         ; done
	cmp.b	#$9,d1                          ; a tab?
	beq.w	opt_end                         ; done
	cmp.b	#$20,d1                         ; a space?
	beq.w	opt_end                         ; done
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	subi.b	#$41,d1                         ; a letter?
	bcs.s	opt_invalid                     ; no
	cmp.b	#$1a,d1
	bcc.s	opt_invalid                     ; no
	ext.w	d1
	add.w	d1,d1
	move.w	opt_letter_table(pc,d1.w),d0    ; its handler
	beq.s	opt_invalid                     ; none: invalid
	move.b	(a4)+,d1                        ; the character after the letter
	jsr	opt_letter_table(pc,d0.w)       ; the option
	cmp.b	#$2c,d1                         ; a comma?
	beq.s	dir_opt_next                    ; the next
	rts
opt_invalid:	; from: opt_read_sign, opt_case, opt_linkable, opt_optimise
	moveq	#56,d0                          ; "invalid option"
	bra.w	asm_line_error
opt_letter_table:
	dc.w	opt_auto_pc-opt_letter_table
	dc.w	0
	dc.w	opt_case-opt_letter_table
	dc.w	opt_debug-opt_letter_table
	dc.w	opt_odd_check-opt_letter_table
	dc.w	0
	dc.w	0
	dc.w	0
	dc.w	opt_hash_check-opt_letter_table
	dc.w	0
	dc.w	0
	dc.w	opt_linkable-opt_letter_table
	dc.w	opt_macro_list-opt_letter_table
	dc.w	0
	dc.w	opt_optimise-opt_letter_table
	dc.w	opt_pic_check-opt_letter_table
	dc.w	0
	dc.w	0
	dc.w	opt_symbol_list-opt_letter_table
	dc.w	opt_type_check-opt_letter_table
	dc.w	opt_underscore_local-opt_letter_table
	dc.w	0
	dc.w	opt_warnings-opt_letter_table
	dc.w	opt_extended_debug-opt_letter_table
	dc.w	0
	dc.w	0
opt_not_at_start:	; from: opt_linkable
	moveq	#62,d0                          ; "option must be at start"
	bra.w	asm_error

;------------------------------------------------------------------------------
; Read an option's + or -: Z for +, NE for -, "invalid option" otherwise; d1 = the next character.
;------------------------------------------------------------------------------
opt_read_sign:	; from: opt_debug, opt_type_check, opt_macro_list, opt_pic_check, opt_symbol_list, opt_warnings, 6 more
	move.b	(a4)+,d0                        ; the next character
	exg	d0,d1                           ; d0 = the sign
	cmp.b	#$2b,d0                         ; +?
	beq.s	opt_read_sign_done              ; Z
	cmp.b	#$2d,d0                         ; -?
	bne.s	opt_invalid                     ; neither
	tst.b	d0                              ; NE
opt_read_sign_done:
	rts

;------------------------------------------------------------------------------
; D+/D-: debug symbols in the output (1 when on).
;------------------------------------------------------------------------------
opt_debug:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	d0
	andi.b	#$1,d0                          ; 1 for +
	move.b	d0,debug_symbols(a6)
	rts

;------------------------------------------------------------------------------
; T+/T-: type checking of relocatable against absolute values (flag 0 when on).
;------------------------------------------------------------------------------
opt_type_check:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	sne	type_check_off(a6)              ; 0 for +
	rts

;------------------------------------------------------------------------------
; M+/M-: list macro expansions.
;------------------------------------------------------------------------------
opt_macro_list:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_list_macros(a6)
	rts

;------------------------------------------------------------------------------
; P+/P-: check the code is position-independent.
;------------------------------------------------------------------------------
opt_pic_check:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_position_independent(a6)
	rts

;------------------------------------------------------------------------------
; S+/S-: the symbol table in the listing.
;------------------------------------------------------------------------------
opt_symbol_list:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_list_symbols(a6)
	rts

;------------------------------------------------------------------------------
; W+/W-: report warnings.
;------------------------------------------------------------------------------
opt_warnings:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_warnings(a6)
	rts

;------------------------------------------------------------------------------
; X+/X-: extended debug symbols ($ff when on).
;------------------------------------------------------------------------------
opt_extended_debug:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	debug_symbols(a6)
	rts

;------------------------------------------------------------------------------
; A+/A-: make absolute addresses PC-relative where they can be.
;------------------------------------------------------------------------------
opt_auto_pc:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_auto_pc(a6)
	rts

;------------------------------------------------------------------------------
; I+/I-: report "# probably missing" for an absolute address that is a plain number.
;------------------------------------------------------------------------------
opt_hash_check:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_warn_hash(a6)
	rts

;------------------------------------------------------------------------------
; E+/E-: report "odd address" for an odd absolute word or long operand address.
;------------------------------------------------------------------------------
opt_odd_check:	; from: dir_opt
	bsr.s	opt_read_sign                   ; + or -
	seq	asm_odd_check(a6)
	rts

;------------------------------------------------------------------------------
; U+/U-: local labels start with _ (U+) or . (U-).
;------------------------------------------------------------------------------
opt_underscore_local:	; from: dir_opt
	moveq	#95,d2                          ; _
	bsr.s	opt_read_sign                   ; + or -
	beq.s	opt_underscore_local_set        ; +
	moveq	#46,d2                          ; .
opt_underscore_local_set:
	move.b	d2,local_char(a6)               ; the local-label character
	rts

;------------------------------------------------------------------------------
; C[n][+/-]: n (8-127) significant characters in names; + is case sensitive, - is not.
;------------------------------------------------------------------------------
opt_case:	; from: dir_opt
	bsr.w	opt_parse_decimal               ; a number?
	bne.s	opt_case_sign                   ; no
	cmp.w	#$8,d2                          ; below 8?
	bcs.w	opt_invalid                     ; invalid
	cmp.w	#$80,d2                         ; above 127?
	bcc.w	opt_invalid                     ; invalid
	addq.w	#1,d2
	move.w	d2,symbol_length(a6)            ; the significant length
opt_case_sign:
	cmp.b	#$2b,d1                         ; +?
	beq.s	opt_case_set
	cmp.b	#$2d,d1                         ; -?
	bne.s	opt_case_done                   ; no: done
	tst.b	d1                              ; NE
opt_case_set:
	sne	asm_ignore_case(a6)             ; $ff for -: ignore case
	move.b	(a4)+,d1                        ; the next character
opt_case_done:
	rts

;------------------------------------------------------------------------------
; L+/L-/L0/L1/L2: linkable output (L+ and L1 GST, L2 DRI), only before any code, read in pass 1.
;------------------------------------------------------------------------------
opt_linkable:	; from: dir_opt
	tst.l	asm_code_size(a6)               ; code already made?
	bne.w	opt_not_at_start                ; "option must be at start"
	move.b	d1,d0                           ; the letter after L
	move.b	(a4)+,d1                        ; the next character
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	opt_linkable_done               ; yes: already done
	cmp.b	#$2b,d0                         ; +?
	beq.s	opt_linkable_on
	cmp.b	#$2d,d0                         ; -?
	beq.s	opt_linkable_off
	subi.b	#$30,d0                         ; a digit?
	bcs.w	opt_invalid                     ; no
	ext.w	d0
	beq.s	opt_linkable_off                ; 0: off
	subq.w	#1,d0                           ; formats from 0
	cmp.w	#$7,d0
	bcc.w	opt_invalid
	btst	d0,#$3                          ; 0 or 1 only
	beq.w	opt_invalid
	st	linkable_output(a6)             ; linkable on
	move.w	d0,linker_format(a6)            ; the format
	bra.s	opt_linkable_reset
opt_linkable_off:
	sf	linkable_output(a6)             ; linkable off
	bra.s	opt_linkable_reset
opt_linkable_on:
	st	linkable_output(a6)             ; linkable on
	clr.w	linker_format(a6)               ; GST
opt_linkable_reset:
	movea.l	current_section_record(a6),a1   ; the current section
	movea.l	current_module(a6),a0           ; the section list
	clr.l	name_after_comma(a6)
	bsr.w	assign_section_number           ; start the sections again for the format
	move.b	-$1(a4),d1                      ; the character
opt_linkable_done:
	rts

;------------------------------------------------------------------------------
; O+/O-/On+/On-/OW...: optimising options 1-7 (OW: their warnings), all with + or -, or one by number.
;------------------------------------------------------------------------------
opt_optimise:	; from: dir_opt
	lea	asm_optimise_flags(a6),a1       ; the optimising flags
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	cmp.b	#$57,d1                         ; W?
	bne.s	opt_optimise_which              ; no
	lea	asm_optimise_warnings(a6),a1    ; the optimising warnings
	move.b	(a4)+,d1                        ; past it
opt_optimise_which:
	cmp.b	#$2d,d1                         ; -: all off
	beq.s	opt_optimise_all_off
	cmp.b	#$2b,d1                         ; +: all on
	beq.s	opt_optimise_all_on
	bsr.w	opt_parse_decimal               ; the number
	subq.w	#1,d2                           ; from bit 0
	bmi.w	opt_invalid                     ; none: invalid
	cmp.w	#$6,d2                          ; up to 7
	bhi.w	opt_invalid                     ; invalid
	bsr.w	opt_read_sign                   ; + or -
	beq.s	opt_optimise_bit_on             ; +
	move.w	(a1),d0
	bclr	d2,d0                           ; -: clear it
	move.w	d0,(a1)
	rts
opt_optimise_bit_on:
	move.w	(a1),d0
	bset	d2,d0                           ; set it
	move.w	d0,(a1)
	rts
opt_optimise_all_off:
	clr.w	(a1)
	bra.s	opt_optimise_done
opt_optimise_all_on:
	move.w	#$ffff,(a1)
opt_optimise_done:
	move.b	(a4)+,d1                        ; the next character
	rts

;------------------------------------------------------------------------------
; Read a decimal number from d1 on: Z with d2 = the number and d1 the character after it, NE when d1 is not
; a digit.
;------------------------------------------------------------------------------
opt_parse_decimal:	; from: opt_case, opt_optimise
	cmp.b	#$30,d1                         ; a digit?
	bcs.s	opt_parse_decimal_none          ; no
	cmp.b	#$39,d1
	bhi.s	opt_parse_decimal_none          ; no
	moveq	#0,d2
	subi.b	#$30,d1
	move.b	d1,d2                           ; the first digit
opt_parse_decimal_loop:
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$30,d1                         ; a digit?
	bcs.s	opt_parse_decimal_done
	cmp.b	#$3a,d1
	bcc.s	opt_parse_decimal_done
	mulu.w	#$a,d2                          ; times 10
	subi.b	#$30,d1
	andi.w	#$f,d1
	add.w	d1,d2                           ; plus the digit
	bra.s	opt_parse_decimal_loop
opt_parse_decimal_done:
	moveq	#0,d0                           ; Z
opt_parse_decimal_none:
	rts

;------------------------------------------------------------------------------
; OUTPUT filename: the binary's name, unless one is set already (the command line wins).
;------------------------------------------------------------------------------
dir_output:	; from: long_mnemonic_table
	lea	asm_output_name(a6),a0          ; the output name
	moveq	#0,d2                           ; the length
	tst.b	(a0)                            ; set already?
	beq.s	dir_output_copy                 ; no
	moveq	#13,d1                          ; yes: ignore the line
	rts
dir_output_copy:
	cmp.b	#$d,d1                          ; the end?
	beq.s	dir_output_end
	cmp.b	#$9,d1
	beq.s	dir_output_end
	cmp.b	#$20,d1
	beq.s	dir_output_end
	move.b	d1,(a0)+                        ; copy a character
	move.b	(a4)+,d1
	addq.b	#1,d2                           ; count it
	cmp.b	#$52,d2                         ; 82 characters at most
	bne.s	dir_output_copy
	moveq	#13,d1                          ; the rest is ignored
dir_output_end:
	clr.b	(a0)                            ; end the name
	rts

;------------------------------------------------------------------------------
; PEA <ea> (opcode $4840): control addressing, size .L.
;------------------------------------------------------------------------------
ins_pea:	; from: mnemonic_table
	bsr.w	asm_size_long                   ; size .L or none
	st	address_operand(a6)             ; an address operand
	bsr.w	ea_store_parse_check            ; the opcode, then the <ea>
	dc.w	$64                             ; modes: (An), memory, PC
	rts

;------------------------------------------------------------------------------
; PAGE: a new page in the listing, in pass 2.
;------------------------------------------------------------------------------
dir_page:	; from: mnemonic_table
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	dir_page_done                   ; no
	bset	#$0,listing_format(a6)          ; a page throw
	bsr.w	listing_page_end                ; throw the listing page
dir_page_done:
	moveq	#13,d1                          ; the line is eaten
	st	line_not_listed(a6)             ; the line is not listed
	rts
	bclr	#$0,listing_format(a6)          ; not reached
	rts

;------------------------------------------------------------------------------
; PLEN n: the listing's page length, 12 to 254.
;------------------------------------------------------------------------------
dir_plen:	; from: mnemonic_table
	bsr.w	eval_absolute                   ; the value (absolute, defined)
	cmp.l	#$c,d2                          ; below 12?
	bcs.s	printer_param_bad               ; invalid
	cmp.l	#$ff,d2                         ; above 254?
	bcc.s	printer_param_bad               ; invalid
	move.w	d2,page_length(a6)              ; the page length
	st	line_not_listed(a6)             ; the line is not listed
	rts
printer_param_bad:	; from: dir_llen, dir_spc
	moveq	#73,d0                          ; "invalid printer parameter"
	bra.w	asm_error

;------------------------------------------------------------------------------
; label REG list: a name for a MOVEM register list, in the equate tree as type 5 with the mask as value.
;------------------------------------------------------------------------------
dir_reg:	; from: mnemonic_table
	bsr.w	need_global_label               ; a global label
	bsr.w	asm_parse_register_list         ; the register list
	bne.w	reglist_bad                     ; "invalid register list"
	moveq	#0,d2
	move.w	d4,d2                           ; the mask
	movea.l	equate_tree(a6),a2              ; the equate tree
	lea	line_label(a6),a0               ; the name
	movem.l	d2/a3-a5,-(sp)                  ; keep the mask
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	dir_reg_pass2                   ; yes
	bsr.w	asm_tree_find                   ; look the name up
	movem.l	(sp)+,d4/a3-a5                  ; d4 = the mask
	beq.w	report_defined_twice            ; found: "symbol defined twice"
	moveq	#5,d3                           ; type 5: register list
	bsr.w	asm_new_symbol                  ; add it
dir_reg_done:
	move.b	-$1(a4),d1                      ; the character after the operands
	rts
dir_reg_pass2:
	bsr.w	asm_tree_find                   ; look the name up
	movem.l	(sp)+,d4/a3-a5                  ; d4 = the mask
	bne.w	report_additional_symbol        ; missing: "additional symbol on pass 2"
	cmpi.b	#$5,$d(a1)                      ; a register list?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	cmp.l	8(a1),d4                        ; the same?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	bset	#$6,$c(a1)                      ; set in pass 2
	bne.w	report_defined_twice            ; twice: "symbol defined twice"
	bra.s	dir_reg_done
rs_size_shifts:	; from: dir_rs
	dc.w	$0100,$0102                     ; log2 of the item size by size code: none 1, .B 0, .W 1, .L 2

;------------------------------------------------------------------------------
; [label] RS.size count: give the label the RS counter's value, then step the counter by count items;
; except for .B an odd counter is first made even.
;------------------------------------------------------------------------------
dir_rs:	; from: mnemonic_table
	lea	line_label(a6),a0               ; the line's label
	moveq	#0,d0
	move.b	size_code(a6),d0                ; the size
	cmp.b	#$1,d0                          ; .B?
	beq.s	dir_rs_label                    ; yes: no alignment
	btst	#$0,rs_counter_low(a6)          ; the counter odd?
	beq.s	dir_rs_label                    ; no
	move.l	rs_step(a6),d2                  ; the step
	add.l	d2,rs_counter(a6)               ; make it even
dir_rs_label:
	tst.l	(a0)                            ; a label?
	bne.s	dir_rs_define                   ; yes
	bsr.w	evaluate_absolute               ; the count
dir_rs_step:
	moveq	#0,d0
	move.b	size_code(a6),d0                ; the size
	move.b	rs_size_shifts(pc,d0.w),d0      ; log2 of the item size
	lsl.l	d0,d2                           ; to bytes
	tst.b	rs_step(a6)                     ; counting down?
	bpl.s	dir_rs_up                       ; no
	neg.l	d2
dir_rs_up:
	move.l	rs_counter(a6),d0               ; the old value
	add.l	d2,rs_counter(a6)               ; step the counter
	move.l	d0,d2                           ; the listing shows the old value
	bra.w	equate_list_value
dir_rs_define:
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	dir_rs_pass2                    ; yes
	move.l	a0,-(sp)                        ; keep the label
	bsr.w	evaluate_absolute               ; the count
	movea.l	(sp)+,a0
	bne.s	dir_rs_undefined
	tst.b	d4                              ; known?
	bne.s	dir_rs_undefined                ; no: nothing done
	move.l	d2,d5                           ; keep the count
	bsr.w	asm_find_symbol                 ; look the label up
	beq.w	report_defined_twice            ; found: "symbol defined twice"
	lea	equate_tree(a6),a2              ; the equate tree
	moveq	#2,d3                           ; absolute
	move.l	rs_counter(a6),d4               ; the counter as value
	bsr.w	asm_add_symbol                  ; add it
	move.l	d5,d2                           ; the count
	move.b	-$1(a4),d1                      ; the character after it
	bra.s	dir_rs_step                     ; step the counter
dir_rs_pass2:
	bsr.w	asm_find_symbol                 ; look the label up
	bne.w	report_forward_reference        ; missing: "forward reference"
	cmpi.b	#$2,$d(a1)                      ; absolute?
	bne.w	report_forward_reference        ; no: "forward reference"
	move.l	8(a1),d0                        ; its value
	cmp.l	rs_counter(a6),d0               ; the same as the counter?
	bne.w	report_phasing                  ; no: "phasing error"
	bset	#$6,$c(a1)                      ; set in pass 2
	bne.w	report_defined_twice            ; twice: "symbol defined twice"
	bsr.w	evaluate_absolute               ; the count
	bra.w	dir_rs_step                     ; step the counter
dir_rs_undefined:
	rts

;------------------------------------------------------------------------------
; RORG address: go on at this relocatable address; a gap from the PC is padded with zeros.
;------------------------------------------------------------------------------
dir_rorg:	; from: mnemonic_table
	bsr.w	eval_defined_value              ; the address (relocatable, defined)
	tst.l	d2                              ; negative?
	bmi.w	org_not_allowed                 ; "ORG/RORG not allowed"
	move.l	d2,-(sp)                        ; keep it
	bsr.w	obj_rorg                        ; pad to it, where the format allows
	movem.l	(sp)+,d2
	bne.w	org_not_allowed                 ; "ORG/RORG not allowed"
	clr.l	line_code_size(a6)              ; no bytes on this line
	sub.l	program_counter(a6),d2          ; the distance from the PC
	move.l	d2,reserve_bytes(a6)            ; the line's end steps the PC
	move.b	-$1(a4),d1                      ; the character after the operands
	rts

;------------------------------------------------------------------------------
; Pad with zero bytes from d1 up to the address d2: Z when done, C set when d2 is below d1.
;------------------------------------------------------------------------------
org_pad_to:	; from: obj_rorg
	sub.l	d1,d2                           ; the gap
	bcs.s	org_pad_below                   ; backwards
	beq.s	org_pad_done                    ; none
	move.l	d2,d4                           ; bytes
	moveq	#0,d3                           ; of size 1
	moveq	#0,d1                           ; 0
	bsr.w	data_fill                       ; fill
org_pad_done:
	moveq	#0,d0                           ; Z
org_pad_below:
	rts

;------------------------------------------------------------------------------
; RSRESET: the RS counter to 0.
;------------------------------------------------------------------------------
dir_rsreset:	; from: dir_rsset, long_mnemonic_table
	clr.l	rs_counter(a6)
	moveq	#13,d1                          ; the line is eaten
	rts

;------------------------------------------------------------------------------
; RSSET value: the RS counter to the value (0 when it is not known).
;------------------------------------------------------------------------------
dir_rsset:	; from: long_mnemonic_table
	bsr.w	evaluate_absolute               ; the value
	bne.s	dir_rsreset
	tst.b	d4                              ; known?
	bne.s	dir_rsreset                     ; no: 0
	move.l	d2,rs_counter(a6)               ; the counter
	bra.w	equate_list_value               ; the listing shows it

;------------------------------------------------------------------------------
; Scc <ea> (opcodes $50c0-$5fc0), size .B.
;------------------------------------------------------------------------------
ins_scc:	; from: mnemonic_table
	bsr.w	asm_size_byte                   ; size .B or none
	st	address_operand(a6)             ; an address operand
	bsr.w	ea_store_parse_check            ; the opcode, then the <ea>
	dc.w	$3d                             ; modes: data alterable
	rts

;------------------------------------------------------------------------------
; DATA, BSS and TEXT: SECTION with that name.
;------------------------------------------------------------------------------
dir_data:	; from: mnemonic_table
	bsr.s	select_named_section            ; SECTION DATA
	dc.b	'DATA',0                        ; the name
	dc.b	$00
dir_bss:	; from: mnemonic_table
	bsr.s	select_named_section            ; SECTION BSS
	dc.b	'BSS',0                         ; the name
dir_text:	; from: mnemonic_table
	bsr.s	select_named_section            ; SECTION TEXT
	dc.b	'TEXT',0                        ; the name
	dc.b	$00

;------------------------------------------------------------------------------
; Run SECTION on the name that follows the call (0 after it), then return to the caller's caller.
;------------------------------------------------------------------------------
select_named_section:	; from: dir_data
	movea.l	(sp)+,a0                        ; the name
	lea	name_buffer(a6),a1              ; a line buffer
	bsr.w	obj_copy_name                   ; copy the name
	move.b	#$d,(a1)+                       ; end the line
	movem.l	d1/a4,-(sp)                     ; keep the real line's place
	lea	name_buffer(a6),a4              ; the made-up line
	move.b	(a4)+,d1
	bsr.s	dir_section                     ; SECTION
	movem.l	(sp)+,d1/a4
	rts

;------------------------------------------------------------------------------
; SECTION name: save the PC of the current section and go to the named one (made if new).
;------------------------------------------------------------------------------
dir_section:	; from: select_named_section, long_mnemonic_table
	bsr.w	save_section_pc                 ; save the current section's PC
	move.b	-$1(a4),d1                      ; the name's first character
	moveq	#1,d3
	bsr.w	start_section                   ; go to the section
	moveq	#13,d1                          ; the line is eaten
	rts

;------------------------------------------------------------------------------
; label SET value: a symbol that may be given a new value later; marked by bit 7 of its flags.
;------------------------------------------------------------------------------
dir_set:	; from: mnemonic_table
	bsr.w	need_global_label               ; a global label
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	dir_set_pass2                   ; yes
	move.l	a0,-(sp)                        ; keep the label
	bsr.w	evaluate_no_import              ; the value
	movea.l	(sp)+,a0
	tst.b	d4                              ; not known?
	bne.s	dir_set_undefined               ; "undefined symbol"
	movem.l	d2-d3,-(sp)                     ; keep value and type
	bsr.w	asm_find_symbol                 ; look the name up
	movem.l	(sp)+,d4-d5                     ; d4 value, d5 type
	bne.s	dir_set_new                     ; new
	btst	#$7,$c(a1)                      ; a SET symbol?
	beq.w	report_defined_twice            ; no: "symbol defined twice"
	move.b	d5,d3                           ; the type
	move.l	d4,d2                           ; the value
	bra.s	dir_set_value                   ; set it
dir_set_new:
	pea	dir_set_mark(pc)                ; then mark it
	move.b	d5,d3                           ; the type
	lea	equate_tree(a6),a2              ; the equate tree
	subq.b	#2,d5                           ; absolute?
	beq.w	asm_add_symbol                  ; yes: add it there
	lea	asm_module_tree(a6),a2          ; relocatable: the label tree
	bra.w	asm_add_symbol                  ; add it
dir_set_mark:
	bset	#$7,$c(a1)                      ; a SET symbol
	bra.w	equate_list_reload              ; show the value
dir_set_pass2:
	bsr.w	asm_find_symbol                 ; look the name up
	bne.w	report_forward_reference        ; missing: "forward reference"
	btst	#$7,$c(a1)                      ; a SET symbol?
	beq.w	report_forward_reference        ; no: "forward reference"
	move.l	a1,-(sp)                        ; keep it
	bsr.w	evaluate_no_import              ; the value
	movea.l	(sp)+,a1
	bset	#$6,$c(a1)                      ; set in pass 2
dir_set_value:
	move.l	d2,8(a1)                        ; the new value
	cmp.b	$d(a1),d3                       ; the same type?
	bne.w	report_defined_twice            ; no: "symbol defined twice"
	bra.w	equate_list_value               ; show the value
dir_set_undefined:
	moveq	#3,d0                           ; "undefined symbol"
	bra.w	asm_error

;------------------------------------------------------------------------------
; ASL/ASR/LSL/LSR/ROL/ROR/ROXL/ROXR: #n,Dn or Dx,Dy or Dn (by 1), or <ea> (memory, .W, by 1).
;------------------------------------------------------------------------------
ins_shift:	; from: mnemonic_table
	cmp.b	#$23,d1                         ; #?
	beq.s	ins_shift_imm                   ; yes: by a count
	addq.l	#2,a5                           ; room for the opcode
	bsr.w	ea_parse_pc_allowed             ; the operand
	move.b	d5,d0
	andi.b	#$78,d0                         ; a data register?
	beq.s	ins_shift_dn                    ; yes
	move.w	d6,d2                           ; memory: the shift type
	andi.w	#$18,d2                         ; bits 3-4
	lsl.w	#6,d2                           ; to bits 9-10
	andi.w	#$ff00,d6                       ; the direction
	ori.w	#$c0,d6                         ; the memory form
	or.w	d2,d6
	movea.l	code_buffer_ptr(a6),a0          ; the opcode
	move.w	d6,(a0)
	bsr.w	asm_size_word                   ; size .W or none
	moveq	#60,d0                          ; modes: memory alterable
	bra.w	ea_or_check                     ; check the <ea>
ins_shift_by_one:
	ori.w	#$200,d6                        ; count 1
	or.b	d5,d6                           ; the register
	move.w	d6,(a5)+                        ; the opcode
	rts
ins_shift_dn:
	movea.l	code_buffer_ptr(a6),a5          ; no extension words
	bsr.w	or_size_bits                    ; the size bits
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	ins_shift_by_one                ; no: by 1
	ori.b	#$20,d6                         ; the count in a register
	move.w	d6,(a5)
	add.b	d5,d5                           ; Dx to bits 9-11
	or.b	d5,(a5)+
	move.b	(a4)+,d1                        ; past the comma
	bsr.w	parse_data_register             ; a data register
	or.b	d2,(a5)+                        ; Dy
	rts
ins_shift_imm:
	move.b	(a4)+,d1                        ; past the #
	bsr.w	evaluate_absolute               ; the count
	bsr.w	quick_count_check               ; 1-8, 8 as 0
	ror.w	#7,d2                           ; to bits 9-11
	or.w	d2,d6
	bsr.w	or_size_bits                    ; the size bits
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; "comma expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	parse_data_register             ; a data register
	or.b	d2,d6
	move.w	d6,(a5)+                        ; the opcode
	rts

;------------------------------------------------------------------------------
; SPC n: n blank lines in the listing.
;------------------------------------------------------------------------------
dir_spc:	; from: mnemonic_table
	bsr.w	evaluate_absolute               ; the count
	cmp.l	#$ff,d2                         ; 255 or more?
	bcc.w	printer_param_bad               ; "invalid printer parameter"
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	dir_spc_done                    ; no
	tst.b	asm_listing_active(a6)          ; listing on?
	beq.s	dir_spc_done                    ; no
	move.w	d2,d4
dir_spc_loop:
	bsr.w	print_newline                   ; a blank line
	subq.w	#1,d4
	bne.s	dir_spc_loop
dir_spc_done:
	move.b	-$1(a4),d1                      ; the character after the operands
	st	line_not_listed(a6)             ; the line is not listed
	rts

;------------------------------------------------------------------------------
; STOP #data (opcode $4e72), no size.
;------------------------------------------------------------------------------
ins_stop:	; from: mnemonic_table
	move.w	d6,(a5)+                        ; the opcode
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; "immediate data expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	asm_expression                  ; the data
	bsr.w	emit_immediate_word             ; a word
	tst.b	size_code(a6)                   ; a size?
	bne.w	report_invalid_size             ; "invalid size"
	rts

;------------------------------------------------------------------------------
; SWAP Dn (opcode $4840), size .W.
;------------------------------------------------------------------------------
ins_swap:	; from: mnemonic_table
	bsr.w	asm_size_word                   ; size .W or none
	bsr.w	parse_data_register             ; a data register
	or.b	d2,d6
	move.w	d6,(a5)+                        ; the opcode
	rts

;------------------------------------------------------------------------------
; TAS <ea> (opcode $4ac0), size .B.
;------------------------------------------------------------------------------
ins_tas:	; from: mnemonic_table
	bsr.w	asm_size_byte                   ; size .B or none
	bsr.w	ea_store_parse_check            ; the opcode, then the <ea>
	dc.w	$3d                             ; modes: data alterable
	rts

;------------------------------------------------------------------------------
; TRAP #0-15 (opcode $4e40), no size.
;------------------------------------------------------------------------------
ins_trap:	; from: mnemonic_table
	tst.b	size_code(a6)                   ; a size?
	bne.w	report_invalid_size             ; "invalid size"
	cmp.b	#$23,d1                         ; #?
	bne.w	report_immediate_expected       ; "immediate data expected"
	move.b	(a4)+,d1                        ; past it
	bsr.w	evaluate_no_import              ; the vector
	bsr.w	check_not_relative              ; relocatable: "relative not allowed"
	or.b	d2,d6
	move.w	d6,(a5)+                        ; the opcode
	cmp.l	#$10,d2                         ; 0-15?
	bcc.s	ins_trap_too_large              ; no
	rts
ins_trap_too_large:
	moveq	#28,d0                          ; "data too large"
	bra.w	asm_error

;------------------------------------------------------------------------------
; CLR/NEG/NEGX/NOT/TST <ea> (opcodes $4200/$4400/$4000/$4600/$4a00).
;------------------------------------------------------------------------------
ins_unary:	; from: mnemonic_table
	bsr.w	or_size_bits                    ; the size bits
	bsr.w	ea_store_parse_check            ; the opcode, then the <ea>
	dc.w	$3d                             ; modes: data alterable
	rts

;------------------------------------------------------------------------------
; TTL title: the listing's title, up to 80 characters, optionally in single quotes.  In pass 1 only the first
; one is kept.
;------------------------------------------------------------------------------
dir_ttl:	; from: mnemonic_table
	lea	listing_title(a6),a2            ; the title buffer

;------------------------------------------------------------------------------
; Copy the title text into a2 (TTL and SUBTTL).
;------------------------------------------------------------------------------
title_copy:	; from: dir_subttl
	moveq	#0,d2                           ; the length
	st	line_not_listed(a6)             ; the line is not listed
	moveq	#13,d3                          ; ends at CR
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	title_copy_start                ; yes
	tst.b	(a2)                            ; set already?
	beq.s	title_copy_start                ; no
	moveq	#13,d1                          ; yes: ignore the line
	rts
title_copy_start:
	cmp.b	#$27,d1                         ; a quote?
	bne.s	title_copy_char                 ; no
	moveq	#39,d3                          ; ends at the quote
title_copy_next:
	move.b	(a4)+,d1                        ; the next character
title_copy_char:
	cmp.b	d1,d3                           ; the end?
	beq.s	title_copy_end_quote
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	title_copy_done
	move.b	d1,(a2)+                        ; copy it
	addq.b	#1,d2                           ; count it
	cmp.b	#$50,d2                         ; 80 at most
	bne.s	title_copy_next
	moveq	#13,d1                          ; the rest is ignored
	bra.s	title_copy_done
title_copy_end_quote:
	cmp.b	#$d,d3                          ; ended at CR?
	beq.s	title_copy_done                 ; yes
	move.b	(a4)+,d1                        ; past the quote
title_copy_done:
	clr.b	(a2)                            ; end the text
	rts

;------------------------------------------------------------------------------
; SUBTTL title: the listing's subtitle, as TTL.
;------------------------------------------------------------------------------
dir_subttl:	; from: long_mnemonic_table
	lea	listing_subtitle(a6),a2         ; the subtitle buffer
	bra.s	title_copy

;------------------------------------------------------------------------------
; UNLK An (opcode $4e58), no size.
;------------------------------------------------------------------------------
ins_unlk:	; from: mnemonic_table
	bsr.w	parse_address_register          ; an address register
	or.b	d2,d6
	move.w	d6,(a5)+                        ; the opcode
	tst.b	size_code(a6)                   ; a size?
	bne.w	report_invalid_size             ; "invalid size"
	rts

;------------------------------------------------------------------------------
; Directives that only mean something in linkable output (XDEF, XREF): without OPT L the caller's return is
; dropped and d1 = CR, so the rest of the line is ignored and the directive returns at once.
;------------------------------------------------------------------------------
linkable_only:	; from: dir_module, directive_xdef, directive_xref
	tst.b	linkable_output(a6)             ; linkable output?
	bne.s	linkable_only_done              ; yes: go on
	addq.l	#4,sp                           ; no: return from the directive itself
	moveq	#13,d1                          ; as if at the line's end
linkable_only_done:
	rts
xdef_next:	; from: directive_xdef
	move.b	(a4)+,d1                        ; past the comma: the next name

;------------------------------------------------------------------------------
; XDEF name[,name...]: export each symbol (pass 2 marks it exported and writes its definition to the object
; file).  Ignored without linkable output.
;------------------------------------------------------------------------------
directive_xdef:	; from: mnemonic_table
	bsr.s	linkable_only                   ; only with OPT L
	lea	line_label(a6),a0               ; the name's descriptor
	bsr.w	read_symbol_name                ; read the name
	bne.w	asm_error                       ; not a name: the error
	move.w	d1,-(sp)                        ; keep the next character
	bsr.s	xdef_symbol                     ; export it
	move.w	(sp)+,d1
	cmp.b	#$2c,d1                         ; a comma: another name
	beq.s	xdef_next
	rts

;------------------------------------------------------------------------------
; Export the symbol named in label_name: a local is error 7; on pass 2 it must exist and be neither imported nor
; a SET symbol (error 43), then the first XDEF of it marks it (bit 5) and writes it to the object file.
;------------------------------------------------------------------------------
xdef_symbol:	; from: directive_xdef
	move.b	6(a0),d0                        ; the name's first character
	cmp.b	local_char(a6),d0               ; a local?
	beq.w	report_local_not_allowed        ; yes: local not allowed
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	xdef_symbol_done                ; no: nothing to do yet
	bsr.w	asm_find_symbol                 ; find the symbol
	bne.s	xdef_cannot_export              ; not found: cannot export
	move.b	$c(a1),d0                       ; its flags
	andi.b	#$90,d0                         ; imported or SET?
	bne.s	xdef_cannot_export              ; yes: cannot export
	bset	#$5,$c(a1)                      ; mark it exported
	beq.w	obj_export                      ; the first time: write the definition
xdef_symbol_done:
	rts
xdef_cannot_export:
	moveq	#43,d0                          ; error 43: cannot export symbol
	bra.w	asm_error
xref_local:	; from: directive_xref
	moveq	#42,d0                          ; error 42: cannot import symbol
	bra.w	asm_line_error                  ; fatal to the line
xref_next:	; from: directive_xref
	move.b	(a4)+,d1                        ; past the comma: the next name

;------------------------------------------------------------------------------
; XREF[.L] name[,name...]: import each symbol.  Pass 1 adds it (type 1, or 2 for XREF.L, value 0); each one
; then gets the next import number of the module.  Ignored without linkable output.
;------------------------------------------------------------------------------
directive_xref:	; from: mnemonic_table
	bsr.s	linkable_only                   ; only with OPT L
	lea	line_label(a6),a0               ; the name's descriptor
	bsr.w	read_symbol_name                ; read the name
	bne.w	asm_error                       ; not a name: the error
	move.b	6(a0),d0                        ; the name's first character
	cmp.b	local_char(a6),d0               ; a local?
	beq.s	xref_local                      ; yes: cannot import
	moveq	#1,d3                           ; type 1: a relocatable import
	cmpi.b	#$3,size_code(a6)               ; XREF.L?
	bne.s	xref_find                       ; no
	moveq	#2,d3                           ; type 2: an absolute import
xref_find:
	move.w	d1,-(sp)                        ; keep the next character
	move.w	d3,-(sp)                        ; and the type
	bsr.w	asm_find_symbol                 ; find the symbol
	movem.w	(sp)+,d3                        ; the type back (flags kept)
	beq.s	xref_mark                       ; found
	movea.l	asm_module_link(a6),a1          ; where the search ended
	moveq	#0,d4                           ; value 0
	bsr.w	asm_new_symbol                  ; add the symbol
xref_mark:
	bsr.s	xref_symbol                     ; mark it imported
	move.w	(sp)+,d1                        ; the next character
	cmp.b	#$2c,d1                         ; a comma: another name
	beq.s	xref_next
	rts

;------------------------------------------------------------------------------
; Mark symbol a1 imported for XREF with type d3: it must have that type, not be exported, not be a SET symbol and
; not be local (error 42); the first time it gets the module's next import number in its word at $14.
;------------------------------------------------------------------------------
xref_symbol:	; from: directive_xref
	cmp.b	$d(a1),d3                       ; the same type?
	bne.s	xref_cannot_import              ; no: cannot import
	btst	#$5,$c(a1)                      ; exported?
	bne.s	xref_cannot_import              ; yes: cannot import
	btst	#$7,$c(a1)                      ; a SET symbol?
	bne.s	xref_cannot_import              ; yes: cannot import
	move.b	$17(a1),d0                      ; its name's first character
	cmp.b	local_char(a6),d0               ; a local?
	beq.s	xref_cannot_import              ; yes: cannot import
	bset	#$4,$c(a1)                      ; mark it imported
	bne.s	xref_symbol_done                ; already: done
	movea.l	current_module(a6),a0           ; the module
	addq.w	#1,$14(a0)                      ; its next import number
	move.w	$14(a0),$14(a1)                 ; is the symbol's
xref_symbol_done:
	rts
xref_cannot_import:
	move.w	#$2a,d0                         ; error 42: cannot import symbol
	bra.w	asm_error

;------------------------------------------------------------------------------
; Put the size bits of opcode_size into the opcode d6 (bits 7-6: .B 00, .W 01, .L 10; none counts as .W).
;------------------------------------------------------------------------------
or_size_bits:	; from: asm_addx_subx, asm_add_quick, asm_add_subtract, asm_addi_subi_cmpi, asm_cmp, asm_cmpm, 5 more
	moveq	#0,d0
	move.b	size_code(a6),d0                ; the size: 0 none, 1 .B, 2 .W, 3 .L
	or.b	size_bits(pc,d0.w),d6           ; its bits into the opcode
	rts
size_bits:
	dc.w	$4000,$4080                     ; the bits for no size, .B, .W, .L
ifc_missing_quote:	; from: ifc_compare
	moveq	#53,d0                          ; error 53: missing quote
	bra.w	asm_line_error                  ; fatal to the line

;------------------------------------------------------------------------------
; Compare two quoted strings 'a','b' for IFC/IFNC; d1 = the first quote.  Z set when they are the same, with d1 =
; the character after them.  A string without its quotes or ending at the line's end is error 53, no comma 30.
; The second string's length is not checked: one longer with the same start counts as the same (the next
; character is skipped as its quote, so the line then ends in garbage, error 14).
;------------------------------------------------------------------------------
ifc_compare:	; from: directive_ifc, directive_ifnc
	move.b	d1,d2                           ; the first quote
	cmp.b	#$22,d1                         ; double quote?
	beq.s	ifc_first                       ; yes
	cmp.b	#$27,d1                         ; single quote?
	bne.s	ifc_missing_quote               ; no: missing quote
ifc_first:
	movea.l	a4,a2                           ; the first string's start
ifc_first_loop:
	move.b	(a4)+,d1                        ; a character
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	ifc_missing_quote               ; yes: missing quote
	cmp.b	d2,d1                           ; the closing quote?
	bne.s	ifc_first_loop                  ; no: on
	move.b	(a4)+,d1                        ; the character after it
	cmp.b	d2,d1                           ; a doubled quote?
	beq.s	ifc_first_loop                  ; yes: part of the string
	move.l	a4,d4
	sub.l	a2,d4
	subq.w	#1,d4                           ; the first string's length
	cmp.b	#$2c,d1                         ; a comma?
	bne.w	report_comma_expected           ; no: comma expected
	move.b	(a4)+,d1                        ; the second quote
	move.b	d1,d3
	cmp.b	#$27,d1                         ; single quote?
	beq.s	ifc_compare_loop                ; yes
	cmp.b	#$22,d1                         ; double quote?
	bne.s	ifc_missing_quote               ; no: missing quote
ifc_compare_loop:
	subq.w	#1,d4                           ; all of the first string?
	bcs.s	ifc_compare_end                 ; yes
	cmpm.b	(a4)+,(a2)+                     ; the same character?
	beq.s	ifc_compare_loop                ; yes: on
	rts                                     ; no: different (Z clear)
ifc_compare_end:
	moveq	#13,d0
	exg	d0,d1                           ; d1 = CR, d0 = the second string's opening quote
	cmp.b	d3,d0                           ; so always the same here
	bne.s	ifc_compare_done
	addq.l	#1,a4                           ; past the character, taken as the closing quote
	move.b	(a4)+,d1                        ; the character after it
	moveq	#0,d0                           ; the same (Z set)
ifc_compare_done:
	rts

;------------------------------------------------------------------------------
; IFC 'a','b': assemble on when the strings are the same.
;------------------------------------------------------------------------------
directive_ifc:	; from: mnemonic_table
	bsr.s	ifc_compare                     ; compare the strings
	seq	d0                              ; true when the same
	bra.w	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFNC 'a','b': assemble on when the strings differ.
;------------------------------------------------------------------------------
directive_ifnc:	; from: mnemonic_table
	bsr.s	ifc_compare                     ; compare the strings
	sne	d0                              ; true when different
	bra.w	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; Is the symbol in label_name defined?  Z set when it is: a built-in name always is; on pass 2 a SET symbol only
; counts once it has been set on this pass, so IFD gives the same answer on both passes.
;------------------------------------------------------------------------------
ifd_test:	; from: directive_ifd, directive_ifnd
	bsr.w	expr_reserved_symbol            ; a built-in name?
	beq.s	ifd_test_done                   ; yes: defined
	bsr.w	asm_find_symbol                 ; find the symbol
	bne.s	ifd_test_done                   ; not found: undefined (Z clear)
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	ifd_test_done                   ; no: defined
	move.b	$c(a1),d0                       ; its flags
	btst	#$7,d0                          ; a SET symbol?
	beq.s	ifd_test_done                   ; no: defined
	andi.b	#$40,d0                         ; set on this pass?
	cmp.b	#$40,d0                         ; Z set when it has been
ifd_test_done:
	rts

;------------------------------------------------------------------------------
; IFD name: assemble on when the symbol is defined.
;------------------------------------------------------------------------------
directive_ifd:	; from: mnemonic_table
	lea	line_label(a6),a0               ; the name's descriptor
	bsr.w	read_symbol_name                ; read the name
	bne.w	asm_error                       ; not a name: the error
	bsr.s	ifd_test                        ; defined?
	seq	d0                              ; true when it is
	bra.w	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFND name: assemble on when the symbol is not defined.
;------------------------------------------------------------------------------
directive_ifnd:	; from: mnemonic_table
	lea	line_label(a6),a0               ; the name's descriptor
	bsr.w	read_symbol_name                ; read the name
	bne.w	asm_error                       ; not a name: the error
	bsr.s	ifd_test                        ; defined?
	sne	d0                              ; true when it is not
	bra.s	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; Evaluate an expression that must have a value now (for RORG): no forward reference, no import in linkable
; output and not type 2; error 60 otherwise.  Out as for the evaluator: d2 the value, d3 its type.
;------------------------------------------------------------------------------
eval_defined_value:	; from: dir_rorg
	bsr.w	asm_expression                  ; evaluate
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	eval_defined_value_type         ; no
	tst.w	d3                              ; an import?
	bmi.s	eval_must_evaluate              ; yes: must evaluate
eval_defined_value_type:
	cmp.b	#$2,d3                          ; type 2?
	beq.s	eval_must_evaluate              ; yes: must evaluate
	tst.b	d4                              ; a forward reference?
	bne.s	eval_must_evaluate              ; yes: must evaluate
	rts

;------------------------------------------------------------------------------
; Evaluate an absolute expression that must have a value now: no forward reference, no import in linkable
; output, not relocatable; error 60 (absolute expression MUST evaluate) otherwise.  Out: d2 the value, d3 type.
;------------------------------------------------------------------------------
eval_absolute:	; from: asm_cnop, dir_dcb, dir_ds, dir_iif, dir_llen, dir_offset, 4 more
	bsr.w	asm_expression                  ; evaluate
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	eval_absolute_type              ; no
	tst.w	d3                              ; an import?
	bmi.s	eval_must_evaluate              ; yes: must evaluate
eval_absolute_type:
	cmp.b	#$1,d3                          ; relocatable?
	beq.s	eval_must_evaluate              ; yes: must evaluate
	tst.b	d4                              ; a forward reference?
	bne.s	eval_must_evaluate              ; yes: must evaluate
	rts
eval_must_evaluate:	; from: eval_defined_value
	moveq	#60,d0                          ; error 60: absolute expression MUST evaluate
	bra.w	asm_line_error                  ; fatal to the line

;------------------------------------------------------------------------------
; Evaluate the IF expression (absolute) and show it as "= value" in the listing; the flags are those of the
; value in d2, for the Scc that follows.
;------------------------------------------------------------------------------
if_value:	; from: directive_ifgt, directive_ifge, directive_iflt, directive_ifle, directive_ifeq, directive_ifne
	bsr.s	eval_absolute                   ; evaluate
	move.b	#$3d,asm_list_marker(a6)        ; the listing shows "="
	move.l	d2,listing_value(a6)            ; and the value; flags from it
	rts
	moveq	#49,d0                          ; error 49: invalid IF expression (not used)
	bra.w	asm_line_error
error_source_expired:	; from: if_skip, directive_macro, macro_store_line, macro_call, directive_rept
	move.w	#$32,d0                         ; error 50: source expired prematurely
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; IFGT expr: assemble on when the value is above 0.
;------------------------------------------------------------------------------
directive_ifgt:	; from: mnemonic_table
	bsr.s	if_value                        ; the value
	sgt	d0                              ; true when above 0
	bra.s	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFGE expr: assemble on when the value is 0 or above.
;------------------------------------------------------------------------------
directive_ifge:	; from: mnemonic_table
	bsr.s	if_value                        ; the value
	sge	d0                              ; true when 0 or above
	bra.s	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFLT expr: assemble on when the value is below 0.
;------------------------------------------------------------------------------
directive_iflt:	; from: mnemonic_table
	bsr.s	if_value                        ; the value
	slt	d0                              ; true when below 0
	bra.s	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFLE expr: assemble on when the value is 0 or below.
;------------------------------------------------------------------------------
directive_ifle:	; from: mnemonic_table
	bsr.s	if_value                        ; the value
	sle	d0                              ; true when 0 or below
	bra.s	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFEQ expr: assemble on when the value is 0.
;------------------------------------------------------------------------------
directive_ifeq:	; from: mnemonic_table
	bsr.s	if_value                        ; the value
	seq	d0                              ; true when 0
	bra.s	if_result                       ; into the conditional

;------------------------------------------------------------------------------
; IFNE expr: assemble on when the value is not 0.
;------------------------------------------------------------------------------
directive_ifne:	; from: mnemonic_table
	bsr.s	if_value                        ; the value
	sne	d0                              ; true when not 0

;------------------------------------------------------------------------------
; The conditional with its result in d0: one IF level deeper; true assembles on, false skips lines.
;------------------------------------------------------------------------------
if_result:                                      ; from: directive_ifc, directive_ifnc, directive_ifd, directive_ifnd,
                                                ;   directive_ifgt, directive_ifge, 3 more
	addq.w	#1,if_depth(a6)                 ; one level deeper
	tst.b	d0                              ; true?
	beq.s	if_skip                         ; no: skip
if_assemble:	; from: if_skip
	moveq	#13,d1                          ; the line is done
	rts

;------------------------------------------------------------------------------
; Skip source lines up to the ENDC (or ELSEIF/ELSE) that matches the level in if_depth, counting IFs nested in
; the skipped part.  An ENDM in a macro whose IF levels are left open ends the macro.  The source ending is
; fatal (error 50).  Also the ELSEIF of a part that was assembled: from it on to the ENDC.
;------------------------------------------------------------------------------
if_skip:	; from: if_result, directive_elseif
	bsr.w	asm_list_line                   ; list this line
	move.w	if_depth(a6),d7                 ; the level to come back to
if_skip_loop:
	bsr.w	asm_next_line                   ; the next line
	bne.s	error_source_expired            ; the end: source expired
	bsr.s	line_opcode                     ; its opcode into d1:d2
	beq.s	if_skip_next                    ; none: the next line
	tst.l	d2                              ; more than 4 letters?
	beq.s	if_skip_plain                   ; no
	cmp.l	#$454c5345,d1                   ; ELSE...
	bne.s	if_skip_next                    ; no: the next line
	cmp.l	#$49460000,d2                   ; ...IF?
	bne.s	if_skip_next                    ; no: the next line
if_skip_else:
	cmp.w	if_depth(a6),d7                 ; our level?
	beq.s	if_assemble                     ; yes: assemble from here
	bra.s	if_skip_next                    ; no: a nested one
if_skip_plain:
	cmp.l	#$454c5345,d1                   ; ELSE?
	beq.s	if_skip_else                    ; yes: as ELSEIF
	cmp.l	#$454e4443,d1                   ; ENDC?
	beq.s	if_skip_endc                    ; yes
	cmp.l	#$454e444d,d1                   ; ENDM?
	bne.s	if_skip_nested                  ; no: an IF?
	tst.b	in_macro(a6)                    ; in a macro?
	beq.s	if_skip_next                    ; no: the next line
	movea.l	macro_frame(a6),a0              ; the macro call's frame
	cmp.w	$e(a0),d7                       ; inside an IF the macro opened?
	bls.s	if_skip_next                    ; no: the next line
	bra.w	directive_endm                  ; yes: ENDM ends the macro
if_skip_endc:
	move.w	if_depth(a6),d0                 ; the level it closes
	subq.w	#1,if_depth(a6)                 ; one level less
	cmp.w	d0,d7                           ; ours?
	bne.s	if_skip_next                    ; no: a nested one
	bra.s	if_assemble                     ; yes: assemble from here
if_skip_nested:
	swap	d1                              ; the first two letters
	cmp.w	#$4946,d1                       ; IF?
	bne.s	if_skip_next                    ; no: the next line
	swap	d1                              ; the rest
	lea	if_nested_kinds(pc),a0          ; the IF kinds
if_skip_nested_loop:
	move.w	(a0)+,d0                        ; the next kind
	beq.s	if_skip_next                    ; none left: not an IF
	cmp.w	d0,d1                           ; this one?
	bne.s	if_skip_nested_loop             ; no
	addq.w	#1,if_depth(a6)                 ; yes: one level deeper
if_skip_next:
	bsr.w	asm_list_line                   ; list this line
	bra.s	if_skip_loop                    ; on

;------------------------------------------------------------------------------
; Read the opcode field of the line at a4: past the label (one that starts in column 1, up to a space, tab or
; colon) and the blanks, up to 7 letters upper-cased into d1:d2, padded with 0.  Z set when there is none (an
; empty or comment line, or 8 letters or more); Z clear with d0 = -1 when found.
;------------------------------------------------------------------------------
line_opcode:	; from: if_skip, directive_macro, macro_store_line, directive_rept
	move.b	(a4)+,d1                        ; the first character
	cmp.b	#$d,d1                          ; the line's end?
	beq.w	line_opcode_none                ; yes: none
	cmp.b	#$9,d1                          ; tab?
	beq.s	line_opcode_space               ; yes: no label
	cmp.b	#$20,d1                         ; space?
	beq.s	line_opcode_space               ; yes: no label
	cmp.b	#$2a,d1                         ; a * comment?
	beq.w	line_opcode_none                ; yes: none
	cmp.b	#$3b,d1                         ; a ; comment?
	beq.s	line_opcode_none                ; yes: none
line_opcode_label:
	move.b	(a4)+,d1                        ; past the label
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	line_opcode_none                ; yes: none
	cmp.b	#$9,d1                          ; tab?
	beq.s	line_opcode_space               ; yes: its end
	cmp.b	#$20,d1                         ; space?
	beq.s	line_opcode_space               ; yes: its end
	cmp.b	#$3a,d1                         ; a colon?
	bne.s	line_opcode_label               ; no: on
line_opcode_space:
	move.b	(a4)+,d1                        ; past the blanks
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	line_opcode_none                ; yes: none
	cmp.b	#$9,d1                          ; tab?
	beq.s	line_opcode_space               ; yes: on
	cmp.b	#$20,d1                         ; space?
	beq.s	line_opcode_space               ; yes: on
	cmp.b	#$2a,d1                         ; a * comment?
	beq.s	line_opcode_none                ; yes: none
	cmp.b	#$3b,d1                         ; a ; comment?
	beq.s	line_opcode_none                ; yes: none
	lea	line_code(a6),a0                ; the end of mnemonic_name
	clr.l	-(a0)                           ; cleared
	clr.l	-(a0)
	moveq	#7,d0                           ; 8 characters
	bra.s	line_opcode_store               ; store the first
line_opcode_loop:
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	line_opcode_found               ; yes: the name's end
	cmp.b	#$9,d1                          ; tab?
	beq.s	line_opcode_found               ; yes: the name's end
	cmp.b	#$20,d1                         ; space?
	beq.s	line_opcode_found               ; yes: the name's end
	cmp.b	#$2e,d1                         ; a size?
	beq.s	line_opcode_found               ; yes: the name's end
line_opcode_store:
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	move.b	d1,(a0)+                        ; into the name
	dbra	d0,line_opcode_loop             ; the next
	moveq	#0,d0                           ; 8 letters: none (Z set)
	rts
line_opcode_found:
	movem.l	mnemonic_name(a6),d1-d2         ; the name in d1:d2
	moveq	#-1,d0                          ; found (Z clear)
line_opcode_none:
	rts

;------------------------------------------------------------------------------
; ENDC: close one IF level; none open is error 47 (spurious ENDC).
;------------------------------------------------------------------------------
directive_endc:	; from: mnemonic_table
	tst.w	if_depth(a6)                    ; an IF open?
	beq.s	endc_spurious                   ; no: spurious
	subq.w	#1,if_depth(a6)                 ; one level less
	moveq	#13,d1                          ; the line is done
	rts
endc_spurious:
	moveq	#47,d0                          ; error 47: spurious ENDC
	bra.w	asm_error

;------------------------------------------------------------------------------
; ELSEIF reached while assembling: the part before it was assembled, so skip on to the ENDC.
;------------------------------------------------------------------------------
directive_elseif:	; from: long_mnemonic_table
	bra.w	if_skip                         ; skip, at this level

;------------------------------------------------------------------------------
; Start a new block of the macro text store: 5000 bytes from the memory allocator.  Out: a0 = the block,
; macro_store = it and macro_store_free = 5000.  Macro and REPT bodies are kept in these blocks as lines ended by
; CR; a body starts with a 16-byte header (text start, text end, next block, last block), a further block of it
; with a 12-byte one (text start, text end, next block).
;------------------------------------------------------------------------------
macro_store_block:	; from: directive_macro, macro_store_line, directive_rept
	move.l	#$1388,d1                       ; 5000 bytes
	move.w	d1,macro_store_free(a6)         ; all free
	bsr.w	alloc_block                     ; allocate
	move.l	a0,macro_store(a6)              ; the store goes on in it
	rts
macro_nested_error:	; from: directive_macro
	moveq	#52,d0                          ; error 52: cannot nest MACRO definitions or define in REPTs
	bra.w	asm_error

;------------------------------------------------------------------------------
; name MACRO: define a macro.  Pass 1 adds the name to the global table (type 8) with its value pointing to the
; stored body, and stores every line up to and with the ENDM; pass 2 checks it and skips the lines.  A size
; other than .B on MACRO marks it (bit 3) so the label of each call is made even.
;------------------------------------------------------------------------------
directive_macro:	; from: long_mnemonic_table
	tst.b	in_macro(a6)                    ; inside a macro?
	bne.s	macro_nested_error              ; yes: cannot nest
	tst.l	rept_block(a6)                  ; inside a REPT?
	bne.s	macro_nested_error              ; yes: cannot nest
	bsr.w	need_global_label               ; the line needs a label, not local
	movea.l	asm_name_tree(a6),a2            ; the global table
	movem.l	a4-a5,-(sp)
	bsr.w	asm_tree_find                   ; find the name
	sne	d0                              ; d0 set when not found
	movem.l	(sp)+,a4-a5
	tst.b	pass_two(a6)                    ; pass 2?
	bne.w	macro_define_pass2              ; yes
	tst.b	d0                              ; already defined?
	beq.w	report_defined_twice            ; yes: defined twice
	moveq	#8,d3                           ; type 8: a macro
	clr.l	d4                              ; value 0 for now
	bsr.w	asm_new_symbol                  ; add the name
	pea	8(a1)                           ; where its value goes
	move.b	size_code(a6),d0                ; the size on MACRO
	beq.s	macro_define_store              ; none
	cmp.b	#$1,d0                          ; .B?
	beq.s	macro_define_store              ; yes
	bset	#$3,$c(a1)                      ; .W or .L: calls make their label even
macro_define_store:
	movea.l	macro_store(a6),a0              ; the store
	cmpi.w	#$110,macro_store_free(a6)      ; room for a header and a line?
	bcc.s	macro_define_header             ; yes
	bsr.s	macro_store_block               ; no: a new block
macro_define_header:
	movea.l	(sp)+,a1                        ; the value field
	move.l	a0,(a1)                         ; the macro's body is here
	clr.l	8(a0)                           ; no next block
	lea	$10(a0),a1                      ; the text after the header
	move.l	a1,(a0)                         ; its start
	move.l	a1,4(a0)                        ; its end so far
	move.l	a0,$c(a0)                       ; the last block: this one
	move.l	a1,macro_store(a6)              ; the store goes on after the header
	subi.w	#$10,macro_store_free(a6)
	movea.l	a0,a3                           ; the header
macro_define_loop:
	bsr.w	asm_list_line                   ; list this line
	bsr.w	asm_read_line                   ; the next line of the file
	bne.w	error_source_expired            ; the end: source expired
	bsr.s	macro_store_line                ; store it
	bsr.w	line_opcode                     ; its opcode
	beq.s	macro_define_loop               ; none: the next
	cmp.l	#$454e444d,d1                   ; ENDM?
	bne.s	macro_define_loop               ; no: the next
	tst.l	d2                              ; ENDM exactly?
	bne.s	macro_define_loop               ; no: the next
	movea.l	$c(a3),a0                       ; the last block
	move.l	macro_store(a6),4(a0)           ; its text ends here
	moveq	#13,d1                          ; the line is done
	btst	#$0,macro_store+3(a6)           ; the store at an odd address?
	beq.s	macro_define_done               ; no
	subq.w	#1,macro_store_free(a6)         ; make it even
	addq.l	#1,macro_store(a6)
macro_define_done:
	rts

;------------------------------------------------------------------------------
; Store the source line at a4 (up to and with its CR) in the macro store of the body a3, taking a new block when
; fewer than 258 bytes are left.
;------------------------------------------------------------------------------
macro_store_line:	; from: directive_macro, directive_rept
	cmpi.w	#$102,macro_store_free(a6)      ; room for a line?
	bcc.s	macro_store_copy                ; yes
	movea.l	$c(a3),a0                       ; the last block
	move.l	macro_store(a6),4(a0)           ; its text ends here
	bsr.w	macro_store_block               ; a new block
	movea.l	$c(a3),a1                       ; the last block
	move.l	a0,8(a1)                        ; goes on in the new one
	move.l	a0,$c(a3)                       ; which is now the last
	lea	$c(a0),a1                       ; the text after its header
	move.l	a1,(a0)                         ; its start
	clr.l	4(a0)                           ; no end yet
	clr.l	8(a0)                           ; no next block
	moveq	#12,d0                          ; the 12-byte header
	adda.w	d0,a0
	add.l	d0,macro_store(a6)
	sub.w	d0,macro_store_free(a6)
macro_store_copy:
	movea.l	macro_store(a6),a0              ; where it goes
	movea.l	a4,a1                           ; the line
	moveq	#13,d1                          ; CR
macro_store_copy_loop:
	move.b	(a1)+,d0                        ; a character
	move.b	d0,(a0)+                        ; copied
	cmp.b	d0,d1                           ; the CR?
	bne.s	macro_store_copy_loop           ; no: on
	move.l	a0,macro_store(a6)              ; the store goes on here
	move.l	a1,d2                           ; the line's length
	sub.l	a4,d2
	sub.w	d2,macro_store_free(a6)         ; less free
	rts
macro_define_pass2:	; from: directive_macro
	tst.b	d0                              ; not found on pass 2?
	bne.w	report_additional_symbol        ; yes: additional symbol on pass 2
	cmpi.b	#$8,$d(a1)                      ; a macro?
	bne.w	report_defined_twice            ; no: defined twice
	bset	#$6,$c(a1)                      ; mark it defined on this pass
	bne.w	report_defined_twice            ; already: defined twice
macro_skip_loop:
	bsr.w	asm_list_line                   ; list this line
	bsr.w	asm_read_line                   ; the next line of the file
	bne.w	error_source_expired            ; the end: source expired
	bsr.w	line_opcode                     ; its opcode
	beq.s	macro_skip_loop                 ; none: the next
	cmp.l	#$454e444d,d1                   ; ENDM?
	bne.s	macro_skip_loop                 ; no: the next
	tst.l	d2                              ; ENDM exactly?
	bne.s	macro_skip_loop                 ; no: the next
	moveq	#13,d1                          ; the line is done
	rts

;------------------------------------------------------------------------------
; Allocate the 8000-byte stack of macro call frames.  A frame: 0 the previous frame, 4 the body's block being
; read, 8 the number of arguments, $a its \@ number, $c set once \@ is used, $e the IF level at the call, $10 the
; read pointer, $14 the expanded line (258 bytes), $116 the size string (\0) and the arguments, each ended by 0.
;------------------------------------------------------------------------------
macro_stack_init:	; from: asm_entry
	move.l	#$1f40,d1                       ; 8000 bytes
	move.w	d1,macro_stack_free(a6)         ; all free
	bsr.w	alloc_block                     ; allocate
	move.l	a0,macro_stack_top(a6)          ; the stack's top
	rts
macro_stack_full:	; from: macro_call
	moveq	#76,d0                          ; error 76: INTERNAL:macro memory
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Call the macro a1 (the line's opcode was found in the global table): define the line's label, take the size
; after a '.' as \0 (W when none), collect the arguments into a new frame (<...> brackets one with commas or
; blanks in it, >> in it is >; a comma at the line's end goes on with the next line, which starts with &) and
; from now on read lines from the macro's body.
;------------------------------------------------------------------------------
macro_call:	; from: asm_mnemonic
	cmpi.w	#$244,macro_stack_free(a6)      ; room for a frame?
	bcs.s	macro_stack_full                ; no: macro memory
	movem.l	d1/a1,-(sp)
	btst	#$3,$c(a1)                      ; labels made even?
	beq.s	macro_call_label_plain          ; no
	bsr.w	asm_define_code_label           ; the label at the even PC
	bra.s	macro_call_label_done
macro_call_label_plain:
	bsr.w	asm_define_label                ; the label at the PC
macro_call_label_done:
	movem.l	(sp)+,d1/a1
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	macro_call_size                 ; no
	btst	#$6,$c(a1)                      ; defined before this call on pass 2?
	beq.w	report_forward_reference        ; no: forward reference
macro_call_size:
	moveq	#87,d0                          ; \0 is W when no size is given
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	macro_call_frame                ; yes
	cmp.b	#$9,d1                          ; tab?
	beq.s	macro_call_frame                ; yes
	cmp.b	#$20,d1                         ; space?
	beq.s	macro_call_frame                ; yes
	cmp.b	#$2e,d1                         ; a size?
	bne.w	report_not_recognised           ; no: instruction not recognised
	moveq	#0,d0                           ; the size follows
macro_call_frame:
	movea.l	macro_stack_top(a6),a0          ; the new frame
	sf	$c(a0)                          ; \@ not used yet
	move.l	macro_frame(a6),(a0)            ; the previous frame
	move.l	a0,macro_frame(a6)              ; this is the current one
	move.w	macro_call_number(a6),$a(a0)    ; the \@ number of the last call
	movea.l	8(a1),a1                        ; the macro's body
	move.l	a1,4(a0)                        ; its first block
	move.l	(a1),$10(a0)                    ; read from its start
	move.w	if_depth(a6),$e(a0)             ; the IF level now
	lea	8(a0),a1                        ; the argument count
	clr.w	(a1)                            ; 0
	lea	$116(a0),a0                     ; the size string
	move.b	d0,(a0)+                        ; W, or 0 when a size follows
	bne.s	macro_call_size_done            ; W: done
	subq.l	#1,a0
macro_call_size_copy:
	move.b	(a4)+,d1                        ; a character of the size
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	macro_call_size_done            ; yes
	cmp.b	#$9,d1                          ; tab?
	beq.s	macro_call_size_end             ; yes
	cmp.b	#$20,d1                         ; space?
	beq.s	macro_call_size_end             ; yes
	move.b	d1,(a0)+                        ; into \0
	bra.s	macro_call_size_copy
macro_call_size_end:
	move.b	(a4)+,d1                        ; the character after the blank
macro_call_size_done:
	clr.b	(a0)+                           ; end \0
macro_call_args:
	cmp.b	#$d,d1                          ; the line's end?
	beq.w	macro_call_done                 ; yes: no arguments
	cmp.b	#$2a,d1                         ; a * comment?
	beq.s	macro_call_done                 ; yes
	cmp.b	#$3b,d1                         ; a ; comment?
	beq.s	macro_call_done                 ; yes
	cmp.b	#$9,d1                          ; tab?
	beq.s	macro_call_args_blank           ; yes: skip it
	cmp.b	#$20,d1                         ; space?
	bne.s	macro_call_arg                  ; no: the first argument
macro_call_args_blank:
	move.b	(a4)+,d1                        ; skip it
	bra.s	macro_call_args
macro_call_arg:
	addq.w	#1,(a1)                         ; one argument more
	cmp.b	#$2c,d1                         ; a comma: an empty one
	beq.s	macro_call_arg_end
	cmp.b	#$d,d1                          ; the line's end: an empty one
	beq.s	macro_call_arg_end
	cmp.b	#$3c,d1                         ; in brackets?
	bne.s	macro_call_arg_plain            ; no
macro_call_arg_bracket:
	move.b	(a4)+,d1                        ; a character
	beq.s	macro_call_arg_bracket          ; 0 bytes are left out
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	macro_call_arg_end              ; yes: the argument's end
	cmp.b	#$3e,d1                         ; >?
	bne.s	macro_call_arg_bracket_char     ; no: part of it
	move.b	(a4)+,d1                        ; the next
	cmp.b	#$3e,d1                         ; >> is one >
	bne.s	macro_call_arg_end              ; no: the argument's end
macro_call_arg_bracket_char:
	move.b	d1,(a0)+                        ; into the argument
	bra.s	macro_call_arg_bracket
macro_call_arg_plain:
	move.b	d1,(a0)+                        ; into the argument
macro_call_arg_plain_loop:
	move.b	(a4)+,d1                        ; a character
	beq.s	macro_call_arg_plain_loop       ; 0 bytes are left out
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	macro_call_arg_end              ; yes: the argument's end
	cmp.b	#$9,d1                          ; tab?
	beq.s	macro_call_arg_end              ; yes: the argument's end
	cmp.b	#$20,d1                         ; space?
	beq.s	macro_call_arg_end              ; yes: the argument's end
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	macro_call_arg_plain            ; no: part of it
macro_call_arg_end:
	clr.b	(a0)+                           ; end the argument
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	macro_call_done                 ; no: all of them
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$d,d1                          ; the line's end?
	bne.s	macro_call_arg                  ; no: the next argument
	bra.s	macro_call_more_line            ; yes: they go on on the next line
macro_call_frame_back:
	move.l	(sp)+,macro_frame(a6)           ; this frame current again
macro_call_done:
	move.l	a0,d0                           ; the frame's end
	addq.l	#1,d0                           ; made even
	bclr	#$0,d0
	move.l	macro_stack_top(a6),-(sp)
	move.l	d0,macro_stack_top(a6)          ; the stack's new top
	sub.l	(sp)+,d0                        ; the frame's size
	sub.w	d0,macro_stack_free(a6)         ; less free
	move.w	macro_depth(a6),d0              ; the macro depth
	beq.s	macro_call_depth                ; none: the first call
	st	asm_nested_macro_line(a6)       ; a call inside a macro: list the line
macro_call_depth:
	st	in_macro(a6)                    ; lines come from a macro now
	addq.w	#1,d0                           ; one deeper
	move.w	d0,macro_depth(a6)
	rts
macro_call_more_line:
	movea.l	macro_frame(a6),a2              ; this frame
	move.l	a2,-(sp)
	move.l	(a2),macro_frame(a6)            ; the caller's current for the read
	movem.l	a0-a1,-(sp)
	bsr.w	asm_peek_line                   ; the next line's first character
	movem.l	(sp)+,a0-a1
	bne.s	macro_call_frame_back           ; none: done
	cmp.b	#$26,d0                         ; &?
	bne.s	macro_call_frame_back           ; no: done
	movem.l	a0-a1,-(sp)
	bsr.w	asm_list_line                   ; list this line
	bsr.w	asm_next_line                   ; read the next one
	movem.l	(sp)+,a0-a1
	movea.l	(sp)+,a2                        ; this frame
	bne.w	error_source_expired            ; the end: source expired
	move.l	a2,macro_frame(a6)              ; current again
	move.b	(a4)+,d1                        ; the first character
	cmp.b	#$26,d1                         ; &?
	beq.s	macro_call_more_blank           ; yes
	moveq	#68,d0                          ; error 68: INTERNAL:invalid multi-line macro call
	bsr.w	asm_error
macro_call_more_blank:
	move.b	(a4)+,d1                        ; skip the blanks
	cmp.b	#$9,d1                          ; tab?
	beq.s	macro_call_more_blank           ; yes
	cmp.b	#$20,d1                         ; space?
	beq.s	macro_call_more_blank           ; yes
	bra.w	macro_call_arg                  ; the next argument
macro_line_rept:	; from: macro_next_line
	move.w	macro_depth(a6),d0              ; the macro depth
	cmp.w	rept_macro_depth(a6),d0         ; deeper than the REPT's?
	bhi.s	macro_line_read                 ; yes: the macro's next line
	bsr.w	rept_next_line                  ; the REPT's next line
	movea.l	a4,a0
	movea.l	macro_frame(a6),a2              ; the frame
	lea	$14(a2),a1                      ; its line buffer
	moveq	#0,d2                           ; 0 characters yet
	bra.s	macro_expand_loop               ; expand the macro's parameters in it

;------------------------------------------------------------------------------
; Get the next line while a macro runs (from read_line): from the REPT inside the macro when one plays, else
; from the macro's body.  A line with a \ is expanded into the frame's line buffer: \0-\9 and \A-\Z the size
; and the arguments, \@ _nnn (a number for each call), \# the number of arguments, \<sym> or \<$sym> the
; symbol's value in decimal or hex; at most 255 characters.  Out: a4 = the line, line_start, d0 = 0.
;------------------------------------------------------------------------------
macro_next_line:	; from: asm_next_line
	tst.l	rept_block(a6)                  ; a REPT playing?
	bne.s	macro_line_rept                 ; yes
macro_line_read:	; from: macro_call
	movea.l	macro_frame(a6),a2              ; the frame
	movea.l	4(a2),a1                        ; the block being read
	movea.l	$10(a2),a0                      ; the read pointer
	cmpa.l	4(a1),a0                        ; at the block's end?
	bne.s	macro_line_scan                 ; no
	movea.l	8(a1),a1                        ; the next block
	move.l	a1,4(a2)                        ; is the one being read
	movea.l	(a1),a0                         ; from its start
macro_line_scan:
	moveq	#13,d0                          ; CR
	movea.l	a0,a4                           ; the line
	moveq	#92,d2                          ; \
macro_line_scan_loop:
	move.b	(a0)+,d1                        ; a character
	cmp.b	d0,d1                           ; the line's end?
	beq.s	macro_line_ready                ; yes: no parameters
	cmp.b	d2,d1                           ; a parameter?
	bne.s	macro_line_scan_loop            ; no: on
	bra.s	macro_line_expand               ; yes: expand the line
macro_line_ready:
	tst.l	rept_block(a6)                  ; a REPT playing?
	beq.s	macro_line_advance              ; no
	move.w	macro_depth(a6),d0              ; the macro depth
	cmp.w	rept_macro_depth(a6),d0         ; the REPT's or less: the line came from the REPT
	bls.s	macro_line_done                 ; so the macro's pointer stays
macro_line_advance:
	move.l	a0,$10(a2)                      ; the macro's next line
macro_line_done:
	move.l	a4,asm_line_start(a6)           ; the line's start
	moveq	#0,d0
	rts
macro_line_expand:
	lea	$14(a2),a1                      ; the frame's line buffer
	move.l	a0,d2
	sub.l	a4,d2                           ; the characters before the \
	subq.w	#1,d2
	beq.s	macro_expand_loop               ; none
	move.l	a0,d1
	move.w	d2,d0
	movea.l	a4,a0
macro_line_copy_head:
	move.b	(a0)+,(a1)+                     ; copy them
	subq.w	#1,d0
	bne.s	macro_line_copy_head
	movea.l	d1,a0                           ; back to the \
macro_expand_loop:	; from: macro_call
	move.b	(a0)+,d1                        ; the character after a \
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	macro_expand_end                ; yes: done
	cmp.b	#$40,d1                         ; \@?
	beq.w	macro_expand_label_number       ; yes
	cmp.b	#$3c,d1                         ; \<?
	beq.w	macro_expand_value              ; yes
	moveq	#48,d0                          ; a digit?
	cmp.b	d0,d1
	bcs.s	macro_expand_other              ; below 0: \# or other
	cmp.b	#$3a,d1
	bcs.s	macro_expand_arg                ; 0-9
	moveq	#55,d0                          ; a letter?
	cmp.b	#$41,d1
	bcs.s	macro_expand_char               ; no: as it is
	cmp.b	#$5b,d1
	bcs.s	macro_expand_arg                ; A-Z
	moveq	#87,d0
	cmp.b	#$61,d1
	bcs.s	macro_expand_char               ; no: as it is
	cmp.b	#$7b,d1
	bcc.s	macro_expand_char               ; no: as it is
macro_expand_arg:
	sub.b	d0,d1                           ; the number: \0 = 0, \1-\9, \A-\Z = 10-35
	move.l	a0,-(sp)
	lea	$116(a2),a0                     ; the size and the arguments
	ext.w	d1
	beq.s	macro_expand_arg_copy           ; \0: the size
	cmp.w	8(a2),d1                        ; more than there are?
	bgt.s	macro_expand_arg_done           ; yes: empty
macro_expand_arg_skip:
	tst.b	(a0)+                           ; past the earlier ones
	bne.s	macro_expand_arg_skip
	subq.w	#1,d1
	bne.s	macro_expand_arg_skip
macro_expand_arg_copy:
	addq.b	#1,d2                           ; room?
	beq.s	macro_expand_full_pop           ; no: the line is full
	move.b	(a0)+,(a1)+                     ; copy it
	bne.s	macro_expand_arg_copy           ; up to its 0
	subq.l	#1,a1                           ; not the 0
macro_expand_arg_done:
	movea.l	(sp)+,a0                        ; the line again
	bra.s	macro_expand_text               ; on
macro_expand_char:
	addq.b	#1,d2                           ; room?
	beq.s	macro_expand_full               ; no: the line is full
	move.b	d1,(a1)+                        ; the character
macro_expand_text:	; from: macro_expand_put
	move.b	(a0)+,d1                        ; the next
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	macro_expand_end                ; yes: done
	cmp.b	#$5c,d1                         ; a \?
	bne.s	macro_expand_char               ; no: copy it
	bra.s	macro_expand_loop               ; yes: a parameter
macro_expand_full_pop:
	movea.l	(sp)+,a0                        ; the line again
macro_expand_full:	; from: macro_expand_put
	cmpi.b	#$d,(a0)+                       ; the rest of the line is lost
	bne.s	macro_expand_full
macro_expand_end:
	move.b	#$d,(a1)+                       ; end the line
	lea	$14(a2),a4                      ; the expanded line
	bra.w	macro_line_ready
macro_expand_other:
	cmp.b	#$23,d1                         ; \#?
	beq.w	macro_expand_count              ; yes
	bra.s	macro_expand_char               ; no: as it is
macro_expand_label_number:
	tst.b	$c(a2)                          ; \@ used in this call yet?
	bne.s	macro_expand_number_room        ; yes: its number
	st	$c(a2)                          ; no: now
	addq.w	#1,macro_call_number(a6)        ; the next number
	addq.w	#1,$a(a2)                       ; is this call's
macro_expand_number_room:
	cmp.b	#$f9,d2                         ; room for _ and the digits?
	bcc.s	macro_expand_full               ; no: the line is full
	addq.b	#1,d2
	move.b	#$5f,(a1)+                      ; _
	move.l	a0,-(sp)
	moveq	#0,d1
	move.w	$a(a2),d1                       ; the call's number
	cmp.w	#$a,d1                          ; below 10?
	bcs.s	macro_expand_pad2               ; yes: two zeros first
	cmp.w	#$64,d1                         ; below 100?
	bcs.s	macro_expand_pad1               ; yes: one zero first
macro_expand_decimal:	; from: macro_expand_put
	movem.l	d4/a2-a3,-(sp)
	movea.l	a1,a3                           ; where the digits go
	move.w	d2,d4                           ; the count
	lea	macro_expand_put(pc),a2         ; each digit into the line
	bsr.w	decimal_out                     ; d1 in decimal
	movea.l	a3,a1                           ; the line's end now
	move.w	d4,d2                           ; the count
	movem.l	(sp)+,d4/a2-a3
	movea.l	(sp)+,a0
	bra.s	macro_expand_text               ; on
macro_expand_pad2:
	addq.b	#1,d2
	move.b	#$30,(a1)+                      ; 0
macro_expand_pad1:
	addq.b	#1,d2
	move.b	#$30,(a1)+                      ; 0
	bra.s	macro_expand_decimal

;------------------------------------------------------------------------------
; The output routine for the number printers: digit d1 into the expanded line at a3, counted in d4.
;------------------------------------------------------------------------------
macro_expand_put:	; from: macro_next_line
	addq.b	#1,d4                           ; one more
	move.b	d1,(a3)+                        ; into the line
	rts
macro_expand_value:	; from: macro_next_line
	cmp.b	#$f5,d2                         ; room?
	bcc.w	macro_expand_full               ; no: the line is full
	move.b	(a0)+,d1                        ; the first character of the name
	movem.l	d2/d4/a0-a4,-(sp)
	cmp.b	#$24,d1                         ; $: in hex
	seq	d4
	bne.s	macro_expand_value_name         ; no: decimal
	move.b	(a0)+,d1                        ; past the $
	bra.s	macro_expand_value_name
macro_expand_value_builtin:
	move.l	d2,d1                           ; the built-in's value
	bra.s	macro_expand_value_print
macro_expand_value_name:
	movea.l	a0,a4                           ; the name
	lea	line_label(a6),a0               ; the name's descriptor
	bsr.w	read_symbol_name                ; read the name
	bne.s	macro_expand_value_bad          ; not a name: invalid expansion
	cmp.b	#$3e,d1                         ; ended by >?
	bne.s	macro_expand_value_bad          ; no: invalid expansion
	bsr.w	expr_reserved_symbol            ; a built-in name? (d2 its value)
	beq.s	macro_expand_value_builtin      ; yes
	bsr.w	asm_find_symbol                 ; find the symbol
	bne.s	macro_expand_value_bad          ; not found: invalid expansion
	move.l	8(a1),d1                        ; its value
macro_expand_value_print:
	movea.l	$c(sp),a3                       ; the line's end
	lea	macro_expand_put(pc),a2         ; each digit into the line
	tst.b	d4                              ; hex?
	beq.s	macro_expand_value_decimal      ; no
	move.l	(sp),d4                         ; the count
	bsr.w	hex_unpadded                    ; d1 in hex
	bra.s	macro_expand_value_done
macro_expand_value_decimal:
	move.l	(sp),d4                         ; the count
	bsr.w	decimal_out                     ; d1 in decimal
macro_expand_value_done:
	move.l	a3,d1                           ; the line's end now
	move.w	d4,d2                           ; the count
	move.l	a4,d3                           ; the source past the >
	movem.l	(sp)+,d0/d4/a0-a4
	movea.l	d1,a1
	movea.l	d3,a0
	bra.w	macro_expand_text               ; on
macro_expand_value_bad:
	movem.l	(sp)+,d2/d4/a0-a4
	moveq	#71,d0                          ; error 71: invalid numeric expansion
	bsr.w	asm_error
	bra.w	macro_expand_text               ; on
macro_expand_count:	; from: macro_next_line
	cmp.b	#$fc,d2                         ; room?
	bcc.w	macro_expand_full               ; no: the line is full
	moveq	#0,d1
	move.w	8(a2),d1                        ; the number of arguments
	move.l	a0,-(sp)
	bra.w	macro_expand_decimal            ; in decimal

;------------------------------------------------------------------------------
; ENDM or MEXIT: end the macro that is running: drop its frame, close the IF levels it left open (fewer than at
; the call is error 57, fatal) and read on from where it was called.  Outside a macro error 51.
;------------------------------------------------------------------------------
directive_endm:	; from: if_skip, mnemonic_table, long_mnemonic_table
	tst.b	in_macro(a6)                    ; in a macro?
	beq.s	endm_spurious                   ; no: spurious
	tst.b	asm_list_macros(a6)             ; listing the macros?
	bne.s	endm_pop                        ; yes
	st	line_not_listed(a6)             ; no: leave this line out
endm_pop:
	subq.w	#1,macro_depth(a6)              ; one less deep
	movea.l	macro_frame(a6),a2              ; the frame
	move.l	a2,d0
	sub.l	macro_stack_top(a6),d0          ; the frame's size
	sub.w	d0,macro_stack_free(a6)         ; more free
	move.l	a2,macro_stack_top(a6)          ; the stack's top again
	move.w	$e(a2),d0                       ; the IF level at the call
	cmp.w	if_depth(a6),d0                 ; more than now?
	bgt.s	endm_bad_conditional            ; yes: fatally bad conditional
	move.w	d0,if_depth(a6)                 ; IFs left open are closed
	move.l	(a2),d0                         ; the previous frame
	move.l	d0,macro_frame(a6)              ; current
	bne.s	endm_done                       ; none?
	sf	in_macro(a6)                    ; yes: lines come from the source again
endm_done:
	moveq	#13,d1                          ; the line is done
	rts
endm_spurious:
	moveq	#51,d0                          ; error 51: spurious ENDM or MEXIT
	bra.w	asm_error
endm_bad_conditional:
	moveq	#57,d0                          ; error 57: fatally bad conditional
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; REPT count: store the lines up to the ENDR in the macro store and assemble them count times; then the store is
; given back.  A count of 0 or less skips the lines.  REPT inside REPT is error 69.  Inside a macro the stored
; lines get the macro's parameters expanded as they play.
;------------------------------------------------------------------------------
directive_rept:	; from: mnemonic_table
	tst.l	rept_block(a6)                  ; a REPT already?
	bne.w	rept_nested                     ; yes: cannot nest
	bsr.w	eval_absolute                   ; the count
	move.l	d2,rept_count(a6)
	bgt.s	rept_record                     ; above 0: store and play
rept_skip_loop:
	bsr.w	asm_list_line                   ; list this line
	bsr.w	asm_read_line                   ; the next line of the file
	bne.w	error_source_expired            ; the end: source expired
	bsr.w	line_opcode                     ; its opcode
	beq.s	rept_skip_loop                  ; none: the next
	tst.l	d2                              ; more than 4 letters?
	bne.s	rept_skip_loop                  ; yes: the next
	cmp.l	#$52455054,d1                   ; REPT?
	beq.s	rept_nested                     ; yes: cannot nest
	cmp.l	#$454e4452,d1                   ; ENDR?
	bne.s	rept_skip_loop                  ; no: the next
	moveq	#13,d1                          ; the line is done
	rts
rept_nested:
	moveq	#69,d0                          ; error 69: cannot nest repeat loops
	bra.w	asm_line_error                  ; fatal to the line
rept_record:
	movea.l	macro_store(a6),a0              ; the store
	cmpi.w	#$110,macro_store_free(a6)      ; room for a header and a line?
	bcc.s	rept_record_header              ; yes
	bsr.w	macro_store_block               ; no: a new block
rept_record_header:
	move.l	a0,rept_block(a6)               ; the REPT's body
	move.w	macro_store_free(a6),-(sp)      ; the free count, to give it back
	clr.l	8(a0)                           ; no next block
	lea	$10(a0),a1                      ; the text after the header
	move.l	a1,(a0)                         ; its start
	move.l	a1,4(a0)                        ; its end so far
	move.l	a0,$c(a0)                       ; the last block: this one
	move.l	a1,macro_store(a6)              ; the store goes on after the header
	subi.w	#$10,macro_store_free(a6)
	movea.l	a0,a3                           ; the header
rept_record_loop:
	bsr.w	asm_list_line                   ; list this line
	clr.l	rept_block(a6)                  ; not playing while it is stored
	bsr.w	asm_next_line                   ; the next line
	bne.w	error_source_expired            ; the end: source expired
	move.l	a3,rept_block(a6)
	bsr.w	macro_store_line                ; store it
	bsr.w	line_opcode                     ; its opcode
	beq.s	rept_record_loop                ; none: the next
	cmp.l	#$454e4452,d1                   ; ENDR?
	bne.s	rept_record_loop                ; no: the next
	tst.l	d2                              ; ENDR exactly?
	bne.s	rept_record_loop                ; no: the next
	bsr.w	asm_list_line                   ; list the ENDR line
	st	line_not_listed(a6)             ; and not listed again
	movea.l	$c(a3),a0                       ; the last block
	move.l	macro_store(a6),4(a0)           ; its text ends here
	btst	#$0,macro_store+3(a6)           ; the store at an odd address?
	beq.s	rept_play                       ; no
	subq.w	#1,macro_store_free(a6)         ; make it even
	addq.l	#1,macro_store(a6)
	tst.b	in_macro(a6)                    ; in a macro?
	beq.s	rept_play                       ; no
	move.w	macro_depth(a6),rept_macro_depth(a6) ; the lines get its parameters
rept_play:
	subq.l	#1,rept_count(a6)               ; one time less
	bcs.s	rept_done                       ; all done
	move.l	a3,rept_block(a6)               ; the REPT plays
	lea	$10(a3),a1                      ; from its first line
	move.l	a1,rept_read(a6)
rept_play_loop:
	bsr.w	asm_next_line                   ; the next line
	bne.w	error_source_expired            ; the end: source expired
	movem.l	a3-a4,-(sp)
	bsr.w	line_opcode                     ; its opcode
	movem.l	(sp)+,a3-a4
	beq.s	rept_play_line                  ; none: assemble it
	cmp.l	#$454e4452,d1                   ; ENDR?
	bne.s	rept_play_line                  ; no: assemble it
	tst.l	d2                              ; ENDR exactly?
	beq.s	rept_play                       ; yes: the next time round
rept_play_line:
	st	line_not_listed(a6)             ; not listed
	move.l	a3,-(sp)
	bsr.w	asm_line                        ; assemble the line
	movea.l	(sp)+,a3
	bra.s	rept_play_loop                  ; on
rept_done:
	move.w	(sp)+,d0                        ; the free count before the REPT
	move.w	macro_store_free(a6),d2         ; now
	tst.l	8(a3)                           ; more than one block?
	beq.s	rept_free                       ; no
	moveq	#0,d0                           ; yes: the blocks stay used
rept_free:
	sub.w	d0,d2                           ; the bytes the body took
	sub.w	d2,macro_store_free(a6)         ; free again
	ext.l	d2
	add.l	d2,macro_store(a6)              ; the store goes back
	clr.l	rept_block(a6)                  ; no REPT now
	lea	listing_no_code(pc),a0          ; the line-end routine
	move.l	a0,line_end_hook(a6)            ; clears the line's code count
	moveq	#13,d1                          ; the line is done
	rts

;------------------------------------------------------------------------------
; ENDR met outside a REPT: error 70.
;------------------------------------------------------------------------------
directive_endr:	; from: mnemonic_table
	moveq	#70,d0                          ; error 70: spurious ENDR
	bra.w	asm_error

;------------------------------------------------------------------------------
; The next line of the REPT that plays (from read_line).  Out: a4 = the line, line_start, d0 = 0.
;------------------------------------------------------------------------------
rept_next_line:	; from: asm_next_line, macro_call
	movea.l	rept_block(a6),a1               ; the block being read
	movea.l	rept_read(a6),a0                ; the read pointer
	cmpa.l	4(a1),a0                        ; at the block's end?
	bne.s	rept_next_line_scan             ; no
	movea.l	8(a1),a1                        ; the next block
	move.l	a1,rept_block(a6)               ; is the one being read
	movea.l	(a1),a0                         ; from its start
rept_next_line_scan:
	movea.l	a0,a4                           ; the line
	moveq	#13,d0                          ; CR
rept_next_line_loop:
	cmp.b	(a0)+,d0                        ; to past its end
	bne.s	rept_next_line_loop
	move.l	a0,rept_read(a6)                ; the next line's start
	move.l	a4,asm_line_start(a6)           ; the line's start
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Hash a 4-letter mnemonic d3 (the letters as a long): d3 = (d3 mod 2335) * 2, the offset of its word in the
; hash table.  The division is done by shift and subtract.
;------------------------------------------------------------------------------
mnemonic_hash:	; from: init_mnemonic_hash, find_mnemonic
	moveq	#31,d0                          ; the bit count
	move.l	#$91f,d1                        ; 2335, a prime: the table's size
mnemonic_hash_align:
	add.l	d1,d1                           ; shift it up to the top bit
	dbcs	d0,mnemonic_hash_align
	roxr.l	#1,d1                           ; back one
	subi.w	#$1f,d0                         ; the number of shifts
	neg.w	d0
mnemonic_hash_loop:
	cmp.l	d1,d3                           ; fits?
	bcs.s	mnemonic_hash_shift             ; no
	sub.l	d1,d3                           ; subtract it
mnemonic_hash_shift:
	lsr.l	#1,d1                           ; the next lower
	dbra	d0,mnemonic_hash_loop
	add.w	d3,d3                           ; the word's offset
	rts

;------------------------------------------------------------------------------
; Make the hash table of the 158 4-letter mnemonics: each word is -1 (empty) or the offset of the record in
; mnemonic_table.  Two names with the same hash are fatal error 8 (INTERNAL:invalid hashing).
;------------------------------------------------------------------------------
init_mnemonic_hash:	; from: asm_entry
	lea	mnemonic_table(pc),a0           ; the records
	move.w	#$91e,d1                        ; 2335 words
	lea	mnemonic_hash_table(a6),a1      ; the table
	moveq	#-1,d2                          ; empty
init_mnemonic_hash_clear:
	move.w	d2,(a1)+
	dbra	d1,init_mnemonic_hash_clear
	move.w	#$9d,d4                         ; 158 records
	lea	mnemonic_hash_table(a6),a1
	moveq	#0,d2                           ; the first record's offset
init_mnemonic_hash_loop:
	move.l	(a0),d3                         ; its name
	bsr.s	mnemonic_hash                   ; its hash
	tst.w	0(a1,d3.w)                      ; the word empty?
	bpl.s	init_mnemonic_hash_clash        ; no: two names clash
	move.w	d2,0(a1,d3.w)                   ; the record's offset
	addi.w	#$a,d2                          ; the next record
	adda.w	#$a,a0
	dbra	d4,init_mnemonic_hash_loop
	rts
init_mnemonic_hash_clash:
	moveq	#8,d0                           ; error 8: INTERNAL:invalid hashing
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; The two letters after IF that make an IF nested in a skipped part (each a word; C and D with a 0): NE, EQ, C,
; NC, D, ND, GT, then "GL" where GE belongs (so an IFGE inside a skipped part is not counted), LT, LE; 0 ends.
;------------------------------------------------------------------------------
if_nested_kinds:	; from: if_skip
	dc.b	'NEEQC',0                       ; NE, EQ, C
	dc.b	'NCD',0                         ; NC, D
	dc.b	'NDGTGLLTLE',0                  ; ND, GT, GL, LT, LE
	dc.b	$00                             ; the end

;------------------------------------------------------------------------------
; The 4-letter mnemonics and directives, 10 bytes each: the name padded with spaces, the opcode word, the
; handler as an offset from its own word, and the label flags: bit 15 the line's label is set to the PC made
; even, bit 14 to the PC as it is, neither: the handler sees to the label.  158 are hashed; the last one (AMP!,
; a name no line can give) is MOVE, found by its own test.
;------------------------------------------------------------------------------
mnemonic_table:	; from: init_mnemonic_hash, find_mnemonic
