	dc.w	asm_bcc-*
	dc.w	$8000
	dc.b	'DBHS'                          ; DBHS, opcode $54c8, the DBcc handler, label even
	dc.w	$54c8
	dc.w	asm_dbcc-*
	dc.w	$8000
	dc.b	'DBLO'                          ; DBLO, opcode $55c8, the DBcc handler, label even
	dc.w	$55c8
	dc.w	asm_dbcc-*
	dc.w	$8000
	dc.b	'SHS '                          ; SHS, opcode $54c0, the Scc handler, label even
	dc.w	$54c0
	dc.w	ins_scc-*
	dc.w	$8000
	dc.b	'SLO '                          ; SLO, opcode $55c0, the Scc handler, label even
	dc.w	$55c0
	dc.w	ins_scc-*
	dc.w	$8000
	dc.b	'IIF '                          ; IIF, the IIF handler, label by handler
	dc.w	$0
	dc.w	dir_iif-*
