mnemonic_move:	; from: find_mnemonic
	dc.w	$0
	dc.w	ins_move-*
	dc.w	$8000

;------------------------------------------------------------------------------
; The 24 mnemonics and directives of 5 to 8 letters, 14 bytes each: the name padded with spaces to 8, then the
; opcode, handler offset and label flags as in mnemonic_table.  They are searched one by one.
;------------------------------------------------------------------------------
long_mnemonic_table:	; from: find_mnemonic
	dc.b	'MOVEQ   '                      ; MOVEQ, opcode $7000, the MOVEQ handler, label even
	dc.w	$7000
	dc.w	ins_moveq-*
	dc.w	$8000
	dc.b	'MOVEM   '                      ; MOVEM, opcode $4880, the MOVEM handler, label even
	dc.w	$4880
	dc.w	ins_movem-*
	dc.w	$8000
	dc.b	'MACRO   '                      ; MACRO, handler directive_macro, label by handler
	dc.w	$0
	dc.w	directive_macro-*
	dc.w	$0
	dc.b	'MOVEA   '                      ; MOVEA, opcode $2040, the MOVEA handler, label even
	dc.w	$2040
	dc.w	ins_movea-*
	dc.w	$8000
	dc.b	'MOVEP   '                      ; MOVEP, opcode $108, the MOVEP handler, label even
	dc.w	$108
	dc.w	ins_movep-*
	dc.w	$8000
	dc.b	'INCLUDE '                      ; INCLUDE, the INCLUDE handler, label at PC
	dc.w	$0
	dc.w	dir_include-*
	dc.w	$4000
	dc.b	'RESET   '                      ; RESET, opcode $4e70, no operands: the opcode alone, label even
	dc.w	$4e70
	dc.w	asm_no_operands-*
	dc.w	$8000
	dc.b	'TRAPV   '                      ; TRAPV, opcode $4e76, no operands: the opcode alone, label even
	dc.w	$4e76
	dc.w	asm_no_operands-*
	dc.w	$8000
	dc.b	'NOLIST  '                      ; NOLIST, the NOLIST handler, label at PC
	dc.w	$0
	dc.w	asm_dir_nolist-*
	dc.w	$4000
	dc.b	'MEXIT   '                      ; MEXIT, handler directive_endm, label by handler
	dc.w	$0
	dc.w	directive_endm-*
	dc.w	$0
	dc.b	'MODULE  '                      ; MODULE, the MODULE/IDNT handler, label even
	dc.w	$0
	dc.w	dir_module-*
	dc.w	$8000
	dc.b	'SECTION '                      ; SECTION, the SECTION handler, label by handler
	dc.w	$0
	dc.w	dir_section-*
	dc.w	$0
	dc.b	'LISTCHAR'                      ; LISTCHAR, the LISTCHAR handler, label at PC
	dc.w	$0
	dc.w	dir_listchar-*
	dc.w	$4000
	dc.b	'RSRESET '                      ; RSRESET, the RSRESET handler, label at PC
	dc.w	$0
	dc.w	dir_rsreset-*
	dc.w	$4000
	dc.b	'RSSET   '                      ; RSSET, the RSSET handler, label at PC
	dc.w	$0
	dc.w	dir_rsset-*
	dc.w	$4000
	dc.b	'INCBIN  '                      ; INCBIN, the INCBIN handler, label even
	dc.w	$0
	dc.w	dir_incbin-*
	dc.w	$8000
	dc.b	'ILLEGAL '                      ; ILLEGAL, opcode $4afc, no operands: the opcode alone, label even
	dc.w	$4afc
	dc.w	asm_no_operands-*
	dc.w	$8000
	dc.b	'ELSEIF  '                      ; ELSEIF, handler directive_elseif, label at PC
	dc.w	$0
	dc.w	directive_elseif-*
	dc.w	$4000
	dc.b	'OFFSET  '                      ; OFFSET, the OFFSET handler, label by handler
	dc.w	$0
	dc.w	dir_offset-*
	dc.w	$0
	dc.b	'OUTPUT  '                      ; OUTPUT, the OUTPUT handler, label at PC
	dc.w	$0
	dc.w	dir_output-*
	dc.w	$4000
	dc.b	'COMMENT '                      ; COMMENT, the COMMENT handler, label at PC
	dc.w	$0
	dc.w	asm_comment-*
	dc.w	$4000
	dc.b	'SUBTTL  '                      ; SUBTTL, the SUBTTL handler, label at PC
	dc.w	$0
	dc.w	dir_subttl-*
	dc.w	$4000
	dc.b	'FORMAT  '                      ; FORMAT, the FORMAT handler, label at PC
	dc.w	$0
	dc.w	dir_format-*
	dc.w	$4000
	dc.b	'INCDIR  '                      ; INCDIR, the INCDIR handler, label at PC
	dc.w	$0
	dc.w	dir_incdir-*
	dc.w	$4000
mnemonic_not_found:	; from: find_mnemonic
	rts                                     ; not one: the caller tries the macros

;------------------------------------------------------------------------------
; A line "label = value": run it as EQU.
;------------------------------------------------------------------------------
mnemonic_dispatch_equ:	; from: asm_line
	lea	mnemonic_equ(pc),a0             ; the EQU record
	bra.s	mnemonic_dispatch

;------------------------------------------------------------------------------
; Find the mnemonic in mnemonic_name (d2 < 4 when it has 5 letters or more) and run its handler.  When found
; this does not return: the size after a '.' goes to opcode_size (1 .B/.S, 2 .W, 3 .L, 0 none), a4 is moved
; past the blanks to the operand (d1 its first character), the line's label is set as the flags say, the handler
; runs with d6 = the opcode, and line_end_check follows.  Returns when the name is not a mnemonic.
;------------------------------------------------------------------------------
find_mnemonic:	; from: asm_mnemonic
	cmp.b	#$4,d2                          ; 5 letters or more?
	bcs.w	find_long_mnemonic              ; yes: the long table
	move.l	mnemonic_name(a6),d3            ; the name's 4 letters
	lea	mnemonic_move(pc),a0            ; the MOVE record
	cmp.l	#$4d4f5645,d3                   ; MOVE?
	beq.s	mnemonic_found                  ; yes
	move.l	d3,d4
	bsr.w	mnemonic_hash                   ; its hash
	lea	mnemonic_hash_table(a6),a0      ; the hash table
	move.w	0(a0,d3.w),d0                   ; the record's offset
	bmi.s	mnemonic_not_found              ; empty: not a mnemonic
	lea	mnemonic_table(pc),a0           ; the records
	adda.w	d0,a0                           ; the record
	cmp.l	(a0)+,d4                        ; the same name?
	bne.s	mnemonic_not_found              ; no: not a mnemonic
mnemonic_found:
	addq.l	#4,sp                           ; the caller's return is not used
mnemonic_dispatch:	; from: mnemonic_dispatch_equ
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	mnemonic_size                   ; no
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	mnemonic_size                   ; no
	bsr.w	obj_line_start                  ; start the line in the object file
mnemonic_size:
	move.b	-$1(a4),d1                      ; the character after the name
	moveq	#0,d0                           ; no size
	cmp.b	#$2e,d1                         ; a size?
	bne.s	mnemonic_skip_space             ; no
	move.b	(a4)+,d1                        ; its letter
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	moveq	#1,d0                           ; .B
	cmp.b	#$42,d1
	beq.s	mnemonic_size_end
	moveq	#2,d0                           ; .W
	cmp.b	#$57,d1
	beq.s	mnemonic_size_end
	moveq	#3,d0                           ; .L
	cmp.b	#$4c,d1
	beq.s	mnemonic_size_end
	moveq	#1,d0                           ; .S counts as .B
	cmp.b	#$53,d1
	beq.s	mnemonic_size_end
	cmp.b	#$9,d1                          ; tab?
	beq.s	mnemonic_size_blank             ; yes
	cmp.b	#$20,d1                         ; space?
	bne.w	report_invalid_size             ; no: invalid size
mnemonic_size_blank:
	bne.w	report_invalid_size
	moveq	#2,d0                           ; a '.' alone counts as .W
	subq.l	#1,a4                           ; back to the blank
mnemonic_size_end:
	move.b	(a4)+,d1                        ; the character after the size
	cmp.b	#$9,d1                          ; tab?
	beq.s	mnemonic_skip_space             ; yes
	cmp.b	#$20,d1                         ; space?
	beq.s	mnemonic_skip_space             ; yes
	cmp.b	#$d,d1                          ; the line's end?
	bne.w	report_invalid_size             ; no: invalid size
mnemonic_skip_space:
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	mnemonic_call                   ; yes: no operand
	move.b	(a4)+,d1                        ; the next character
	cmp.b	#$9,d1                          ; tab?
	beq.s	mnemonic_skip_space             ; yes: on
	cmp.b	#$20,d1                         ; space?
	beq.s	mnemonic_skip_space             ; yes: on
mnemonic_call:
	move.b	d0,size_code(a6)                ; the size
	sf	address_operand(a6)             ; the access checks apply
	move.w	(a0)+,d6                        ; the opcode
	move.w	(a0)+,d3                        ; the handler's offset
	pea	line_end_check(pc)              ; after the handler: the line's end
	pea	-$2(a0,d3.w)                    ; the handler
	move.w	(a0)+,d2                        ; the label flags
	move.w	d1,-(sp)                        ; keep the operand's first character
	btst	#$f,d2                          ; label at the even PC?
	beq.s	mnemonic_label_plain            ; no
	bsr.w	asm_define_code_label           ; yes
	bra.s	mnemonic_jump
mnemonic_label_plain:
	btst	#$e,d2                          ; label at the PC?
	beq.s	mnemonic_jump                   ; no: the handler sees to it
	bsr.w	asm_define_label                ; yes
mnemonic_jump:
	move.w	(sp)+,d1                        ; the operand's first character
	rts                                     ; to the handler
find_long_mnemonic:
	movem.l	mnemonic_name(a6),d0-d1         ; the name's 8 letters
	lea	long_mnemonic_table(pc),a0      ; the long records
	moveq	#10,d2                          ; the rest of a record
	moveq	#23,d3                          ; 24 records
find_long_mnemonic_loop:
	cmp.l	(a0)+,d0                        ; the first 4 letters?
	beq.s	find_long_mnemonic_second       ; yes
find_long_mnemonic_next:
	adda.l	d2,a0                           ; the next record
	dbra	d3,find_long_mnemonic_loop
	bra.w	mnemonic_not_found              ; none: not a mnemonic
find_long_mnemonic_second:
	cmp.l	(a0),d1                         ; the last 4 letters?
	bne.s	find_long_mnemonic_next         ; no: the next
	addq.l	#4,a0                           ; the record's fields
	bra.w	mnemonic_found                  ; run it

;------------------------------------------------------------------------------
; The handler of an instruction without operands (NOP, RTS, RESET...): the opcode alone.
;------------------------------------------------------------------------------
asm_no_operands:	; from: mnemonic_table, long_mnemonic_table
	move.w	d6,(a5)+                        ; the opcode
	moveq	#13,d1                          ; the line is done
	rts
line_end_hook_run:	; from: line_end_check
	movea.l	line_end_hook(a6),a0            ; the routine to run after the line
	clr.l	line_end_hook(a6)               ; once
	jmp	(a0)                            ; run it

;------------------------------------------------------------------------------
; After each handler: the operands must end in a blank, the line's end or a comment, else error 14 (garbage
; following instruction).  Then the PC moves on by the code the line made (written out on pass 2) or by the
; space it reserved, or the line-end routine runs.
;------------------------------------------------------------------------------
line_end_check:	; from: find_mnemonic
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	line_end_advance                ; yes
	cmp.b	#$9,d1                          ; tab?
	beq.s	line_end_advance                ; yes
	cmp.b	#$20,d1                         ; space?
	beq.s	line_end_advance                ; yes
	cmp.b	#$2a,d1                         ; a * comment?
	beq.s	line_end_advance                ; yes
	cmp.b	#$3b,d1                         ; a ; comment?
	beq.s	line_end_advance                ; yes
	moveq	#14,d0                          ; error 14: garbage following instruction
	bsr.w	asm_error
line_end_advance:
	tst.l	line_end_hook(a6)               ; a routine to run after the line?
	bne.s	line_end_hook_run               ; yes
	tst.l	reserve_bytes(a6)               ; space reserved (DS and the like)?
	beq.s	line_end_code                   ; no: the code made
	move.l	reserve_bytes(a6),d1            ; the reserved size
	clr.l	reserve_bytes(a6)               ; once
	add.l	d1,program_counter(a6)          ; the PC moves on
	tst.l	d1                              ; negative?
	bmi.s	line_end_reserved_done          ; yes: not in the size
	add.l	d1,asm_code_size(a6)            ; the code size
line_end_reserved_done:
	clr.l	line_code_size(a6)              ; no code on this line
	rts
line_end_code:
	move.l	a5,d1                           ; the code buffer's end
	sub.l	code_buffer_ptr(a6),d1          ; the bytes made
	move.l	d1,line_code_size(a6)
	beq.s	line_end_done                   ; none
	move.l	program_counter(a6),d2          ; their address
	add.l	d1,program_counter(a6)          ; the PC moves on
	add.l	d1,asm_code_size(a6)            ; the code size
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	line_end_done                   ; no
	tst.b	binary_on(a6)                   ; writing a binary file?
	bne.w	obj_emit                        ; yes: write the code
line_end_done:
	rts

;------------------------------------------------------------------------------
; Read a name as read_symbol_name does and cut it at its first '.' (a macro call's size).  Out: Z set when read;
; a1 = the source past the whole name, d2 = its full length; when cut a4 is just past the '.', d1 = '.'.
;------------------------------------------------------------------------------
read_name_cut_dot:	; from: asm_mnemonic, parse_register
	bsr.s	read_symbol_name                ; read the name
	bne.s	read_name_cut_dot_done          ; not a name
	movea.l	(a0),a1                         ; the name
	move.b	5(a0),d0                        ; its length
	moveq	#46,d2                          ; '.'
	addq.l	#1,a1                           ; from the second character
	bra.s	read_name_cut_dot_next
read_name_cut_dot_loop:
	cmp.b	(a1)+,d2                        ; a '.'?
	beq.s	read_name_cut_dot_found         ; yes: cut there
read_name_cut_dot_next:
	subq.b	#1,d0                           ; all of it?
	bne.s	read_name_cut_dot_loop          ; no: on
	move.b	5(a0),d2                        ; the length
	movea.l	a4,a1                           ; the source past it
	moveq	#0,d0                           ; read (Z set)
read_name_cut_dot_done:
	rts
read_name_cut_dot_found:
	movea.l	a4,a1                           ; the source past the whole name
	move.b	5(a0),d2                        ; its full length
	sub.b	d0,5(a0)                        ; shortened to before the '.'
	ext.w	d0
	suba.w	d0,a4                           ; the source back to just past the '.'
	move.b	-$1(a4),d1                      ; d1 = '.'
	moveq	#0,d0                           ; read (Z set)
	rts

;------------------------------------------------------------------------------
; Read a symbol name from the source (d1 its first character, a4 past it) into the descriptor a0: 0 the name's
; address, 5 its length, 6 a copy of its first character or the name itself.  A name of digits ended by $ (1$) is
; a local: the local character and the digits.  A trailing .B/.W/.L is left out (a4 back at the size letter, d1 =
; '.').  Ignoring case copies the name upper-cased, to 127 characters; else it stays in the source and its length
; counts to symbol_length.  Out: d0 = 0 and Z set, d1 the next character; error 40 (symbol expected) in d0 else.
;------------------------------------------------------------------------------
read_symbol_name:                               ; from: asm_line, expr_get_token, cmdline_symbols_parse,
                                                ;   asm_parse_register_list, directive_xdef, directive_xref, 4 more
	andi.w	#$ff,d1
	lea	symbol_chars(pc),a2             ; the character classes
	tst.b	0(a2,d1.w)                      ; a name character?
	beq.s	read_symbol_digit               ; yes
	bpl.s	read_symbol_none                ; a terminator: symbol expected
	move.b	(a4),d1                         ; a '.': the next character
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	cmp.b	#$57,d1                         ; W?
	beq.s	read_symbol_dot_size            ; yes
	cmp.b	#$42,d1                         ; B?
	beq.s	read_symbol_dot_size            ; yes
	cmp.b	#$4c,d1                         ; L?
	bne.s	read_symbol_dot                 ; no: a name
read_symbol_dot_size:
	move.b	1(a4),d1                        ; the character after it
	tst.b	0(a2,d1.w)                      ; a name goes on?
	ble.s	read_symbol_dot                 ; yes: a name
	moveq	#46,d1                          ; no: .B/.W/.L alone, not a name
	bra.s	read_symbol_none
read_symbol_dot:
	moveq	#46,d1                          ; a name that starts with '.'
	bra.s	read_symbol_plain
read_symbol_digit:
	cmp.b	#$3a,d1                         ; a digit?
	bcc.s	read_symbol_plain               ; no: a name
	lea	-$1(a4),a1                      ; its start
	movea.l	a4,a2
read_symbol_local_loop:
	move.b	(a2)+,d1                        ; the next character
	cmp.b	#$24,d1                         ; $?
	beq.s	read_symbol_local               ; yes: a local
	cmp.b	#$3a,d1                         ; a letter or more?
	bcc.s	read_symbol_none                ; yes: symbol expected
	cmp.b	#$30,d1                         ; a digit?
	bcc.s	read_symbol_local_loop          ; yes: on
read_symbol_local:
	movea.l	a2,a4                           ; the source past it
	move.l	a2,d0
	sub.l	a1,d0                           ; the digits and the $
	move.b	d0,5(a0)                        ; the length: the local character and the digits
	lea	6(a0),a2                        ; the name's copy
	move.l	a2,(a0)                         ; is the name
	move.b	local_char(a6),(a2)+            ; the local character
	subq.b	#1,d0
read_symbol_local_copy:
	move.b	(a1)+,(a2)+                     ; the digits
	subq.b	#1,d0
	bne.s	read_symbol_local_copy
	move.b	(a4)+,d1                        ; the next character
	moveq	#0,d0                           ; read
	rts
read_symbol_none:
	clr.l	(a0)                            ; no name
	moveq	#40,d0                          ; error 40: symbol expected
	rts
read_symbol_plain:
	tst.b	asm_ignore_case(a6)             ; ignoring case?
	bne.w	read_symbol_upper               ; yes: copy it upper-cased
	move.b	d1,6(a0)                        ; the first character, for the local test
	lea	-$1(a4),a1                      ; the name's start
	move.l	a1,(a0)                         ; in the source
	moveq	#0,d1
	moveq	#0,d2                           ; no '.' yet
read_symbol_scan:
	move.b	(a4)+,d1                        ; the next character
	tst.b	0(a2,d1.w)                      ; a name character?
	beq.s	read_symbol_scan                ; yes: on
	bpl.s	read_symbol_scan_end            ; a terminator: the end
	move.l	a4,d2                           ; a '.': where it is
	bra.s	read_symbol_scan                ; on
read_symbol_suffix:
	sub.l	a4,d2                           ; one character after the '.'?
	addq.l	#2,d2
	bne.s	read_symbol_length              ; no: part of the name
	move.b	-$2(a4),d2                      ; that character
	cmp.b	#$4c,d2                         ; L?
	beq.s	read_symbol_drop_size
	cmp.b	#$6c,d2                         ; l?
	beq.s	read_symbol_drop_size
	cmp.b	#$57,d2                         ; W?
	beq.s	read_symbol_drop_size
	cmp.b	#$77,d2                         ; w?
	beq.s	read_symbol_drop_size
	cmp.b	#$42,d2                         ; B?
	beq.s	read_symbol_drop_size
	cmp.b	#$62,d2                         ; b?
	bne.s	read_symbol_length              ; no: part of the name
read_symbol_drop_size:
	subq.l	#2,a4                           ; back to the size letter
	moveq	#46,d1                          ; d1 = '.'
	bra.s	read_symbol_length
read_symbol_scan_end:
	tst.l	d2                              ; a '.' in it?
	bne.s	read_symbol_suffix              ; yes: a size?
read_symbol_length:
	move.l	a4,d0
	sub.l	(a0),d0                         ; its length and one
	cmp.w	symbol_length(a6),d0            ; more than counts?
	bcs.s	read_symbol_store_length        ; no
	move.w	symbol_length(a6),d0            ; the significant length
read_symbol_store_length:
	subq.b	#1,d0
	move.b	d0,5(a0)                        ; the length
	moveq	#0,d0                           ; read
	rts
read_symbol_upper:
	lea	6(a0),a1                        ; the copy
	move.l	a1,(a0)                         ; is the name
	moveq	#1,d2                           ; one character
	moveq	#0,d0                           ; no '.' yet
read_symbol_upper_loop:
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	move.b	d1,(a1)+                        ; into the copy
	moveq	#0,d1
	move.b	(a4)+,d1                        ; the next character
	tst.b	0(a2,d1.w)                      ; a terminator?
	bgt.s	read_symbol_upper_end           ; yes: the end
	bmi.s	read_symbol_upper_dot           ; a '.'?
	addq.b	#1,d2                           ; no: one more
	bpl.s	read_symbol_upper_loop          ; up to 127
	moveq	#127,d2                         ; the longest
	bra.s	read_symbol_upper_skip          ; skip the rest
read_symbol_upper_dot:
	move.l	a4,d0                           ; where the '.' is
	addq.b	#1,d2                           ; one more
	bpl.s	read_symbol_upper_loop          ; up to 127
read_symbol_upper_skip:
	move.b	(a4)+,d1                        ; the next character
	tst.b	0(a2,d1.w)                      ; still the name?
	ble.s	read_symbol_upper_skip          ; yes: skip it
read_symbol_upper_end:
	tst.l	d0                              ; a '.' in it?
	beq.s	read_symbol_upper_done          ; no
	sub.l	a4,d0                           ; one character after it?
	addq.l	#2,d0
	bne.s	read_symbol_upper_done          ; no
	move.b	-$2(a4),d0                      ; that character
	cmp.b	#$4c,d0                         ; L?
	beq.s	read_symbol_upper_drop_size
	cmp.b	#$6c,d0                         ; l?
	beq.s	read_symbol_upper_drop_size
	cmp.b	#$57,d0                         ; W?
	beq.s	read_symbol_upper_drop_size
	cmp.b	#$77,d0                         ; w?
	bne.s	read_symbol_upper_done          ; no: part of the name (.B stays here)
read_symbol_upper_drop_size:
	moveq	#46,d1                          ; d1 = '.'
	subq.l	#2,a4                           ; back to the size letter
	subq.b	#2,d2                           ; the .L or .W is not in the name
read_symbol_upper_done:
	move.b	d2,5(a0)                        ; the length
	moveq	#0,d0                           ; read
	rts

;------------------------------------------------------------------------------
; Read a module or section name, in quotes or not, into the descriptor a0: the characters from 6 on (upper case
; unless d3 bit 17), 5 the length and one, and d3's low byte (the type) after them.  With d3 bit 16 a comma ends
; a name without quotes and name_after_comma is set past it (after quotes, a comma always does that).
;------------------------------------------------------------------------------
read_string_name:	; from: dir_incbin, dir_include, start_module, start_section
	moveq	#0,d0                           ; no characters
	move.b	d1,d2                           ; the quote, if any
	cmp.b	#$22,d1                         ; double quote?
	beq.s	read_string_loop                ; yes
	cmp.b	#$27,d1                         ; single quote?
	beq.s	read_string_loop                ; yes
	moveq	#0,d2                           ; no quotes
	subq.l	#1,a4                           ; the first character again
read_string_loop:
	move.b	(a4)+,d1                        ; a character
	cmp.b	#$d,d1                          ; the line's end?
	beq.s	read_string_end                 ; yes: the end
	cmp.b	d1,d2                           ; the closing quote?
	beq.s	read_string_quote_end           ; yes
	cmp.b	#$9,d1                          ; tab?
	beq.s	read_string_blank               ; yes
	cmp.b	#$20,d1                         ; space?
	bne.s	read_string_char                ; no
read_string_blank:
	tst.b	d2                              ; in quotes?
	beq.s	read_string_end                 ; no: the end
read_string_char:
	cmp.b	#$2c,d1                         ; a comma?
	bne.s	read_string_store               ; no
	btst	#$10,d3                         ; does a comma end it?
	beq.s	read_string_store               ; no: part of it
read_string_comma:
	move.l	a4,name_after_comma(a6)         ; what follows the comma
	bra.s	read_string_end                 ; the end
read_string_store:
	btst	#$11,d3                         ; keep the case?
	bne.s	read_string_put                 ; yes
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
read_string_put:
	move.b	d1,6(a0,d0.w)                   ; into the name
	addq.b	#1,d0                           ; one more
	bpl.s	read_string_loop                ; up to 127
	moveq	#126,d0
read_string_end:
	lea	5(a0),a1                        ; the length's byte
	addq.b	#1,d0                           ; and one for the type
	move.b	d0,(a1)+                        ; the length
	move.b	d3,5(a0,d0.w)                   ; the type after the name
	move.l	a1,(a0)                         ; the name's address
	rts
read_string_quote_end:
	cmpi.b	#$2c,(a4)+                      ; a comma after the quote?
	bne.s	read_string_end                 ; no: the end
	bra.s	read_string_comma               ; yes: what follows it
byte_high_mask:	; from: check_byte_range
	dc.w	$ffff,$ff00                     ; $ffffff00: all but a byte

;------------------------------------------------------------------------------
; Check that d2 fits a byte (0-255 or -256..-1, top 24 bits all 0 or all 1), else error 28 (data too large),
; then that it is not relocatable (d3 = 1 is error 29 unless OPT T-).
;------------------------------------------------------------------------------
check_byte_range:	; from: emit_immediate_byte, data_next_item, dir_listchar
	move.l	d2,d0
	and.l	byte_high_mask(pc),d0           ; the top 24 bits
	beq.s	check_not_relative              ; all 0: fits
	cmp.l	byte_high_mask(pc),d0           ; all 1?
	beq.s	check_not_relative              ; yes: fits
	bra.s	error_data_too_large            ; no: too large

;------------------------------------------------------------------------------
; Check that d2 fits a word (top word all 0 or all 1), else error 28; then not relocatable as check_byte_range.
;------------------------------------------------------------------------------
check_word_range:	; from: emit_immediate_word
	move.l	d2,d0
	swap	d0                              ; the top word
	tst.w	d0                              ; 0: fits
	beq.s	check_not_relative
	addq.w	#1,d0                           ; $ffff?
	beq.s	check_not_relative              ; yes: fits
	bra.s	error_data_too_large            ; no: too large
	cmp.b	#$1,d3                          ; relocatable? (not used)
	beq.s	error_relative

;------------------------------------------------------------------------------
; Check that d2 is a signed byte (-128..127), else error 28.  Relocation is not checked.
;------------------------------------------------------------------------------
check_signed_byte:	; from: emit_immediate_byte, asm_bcc
	move.b	d2,d0                           ; the low byte
	ext.w	d0                              ; signed
	bra.s	check_signed_fit

;------------------------------------------------------------------------------
; Check that d2 is not relocatable (error 29 unless OPT T-), then that it is a signed word.
;------------------------------------------------------------------------------
check_signed_word_absolute:	; from: ea_parse, emit_immediate_byte, ins_movep
	cmp.b	#$1,d3                          ; relocatable?
	beq.s	error_relative                  ; yes: relative not allowed

;------------------------------------------------------------------------------
; Check that d2 is a signed word (-32768..32767), else error 28.
;------------------------------------------------------------------------------
check_signed_word:	; from: emit_immediate_byte, asm_bcc_word
	move.w	d2,d0                           ; the low word
check_signed_fit:	; from: check_signed_byte
	ext.l	d0                              ; signed
	cmp.l	d0,d2                           ; the same as the value?
	bne.s	error_data_too_large            ; no: too large
	rts
error_data_too_large:	; from: check_byte_range, check_word_range
	moveq	#28,d0                          ; error 28: data too large
	bra.w	asm_error
error_relative:	; from: check_word_range, check_signed_word_absolute, check_not_relative
	moveq	#29,d0                          ; error 29: relative not allowed
	tst.b	type_check_off(a6)              ; type checking off?
	beq.w	asm_error                       ; no: the error
	rts                                     ; yes: allowed

;------------------------------------------------------------------------------
; Check that the value is not relocatable (d3 = 1): error 29 unless OPT T- turned type checking off.
;------------------------------------------------------------------------------
check_not_relative:	; from: ins_moveq, ins_trap, check_byte_range, check_word_range
	cmp.b	#$1,d3                          ; relocatable?
	beq.s	error_relative                  ; yes: relative not allowed
	rts

;------------------------------------------------------------------------------
; At the start of each pass: the module ANON_MODULE and its TEXT section, a4 kept.
;------------------------------------------------------------------------------
start_anon_module:	; from: asm_init_pass
	movea.l	a4,a0                           ; the source pointer, to keep
	lea	name_anon_module(pc),a4         ; the module's name
	move.b	(a4)+,d1                        ; its first character

;------------------------------------------------------------------------------
; Start the module named at a4 (d1 its first character) and its TEXT section; a4 comes back from a0.
;------------------------------------------------------------------------------
start_module_text:	; from: dir_module
	move.l	a0,-(sp)
	bsr.s	start_module                    ; start the module
	lea	name_text_section(pc),a4        ; the section's name
	move.b	(a4)+,d1                        ; its first character
	moveq	#1,d3                           ; type 1: TEXT
	bsr.w	start_section                   ; start the section
	movea.l	(sp)+,a4                        ; the source pointer back
	rts
name_anon_module:	; from: start_anon_module
	dc.b	'ANON_MODULE',13                ; "ANON_MODULE", ended by CR as a source line
name_text_section:
	dc.b	'TEXT',13,0                     ; "TEXT", ended by CR

;------------------------------------------------------------------------------
; Start the module whose name is at a4: no local symbols, the name read into label_name and found in the global
; table (added with type 9 on pass 1).  On pass 2 a name not known from pass 1 is fatal error 11.  The module
; becomes current_module and its start goes to the object file.
;------------------------------------------------------------------------------
start_module:	; from: start_module_text
	clr.l	asm_local_tree(a6)              ; no local symbols
	lea	line_label(a6),a0               ; the name's descriptor
	moveq	#9,d3                           ; type 9: a module
	bsr.w	read_string_name                ; read the name
	movea.l	asm_name_tree(a6),a2            ; the global table
	movem.l	a3-a5,-(sp)
	bsr.w	asm_tree_find                   ; find it
	sne	d0                              ; d0 set when not found
	movem.l	(sp)+,a3-a5
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	start_module_known              ; yes
	tst.b	d0                              ; known?
	beq.s	start_module_known              ; yes
	moveq	#0,d4                           ; value 0
	moveq	#9,d3                           ; type 9
	bsr.w	asm_new_symbol                  ; add it

;------------------------------------------------------------------------------
; Make the module a1 current: current_module and its symbol list.
;------------------------------------------------------------------------------
select_module:
	move.l	a1,current_module(a6)           ; the current module
	lea	$10(a1),a1                      ; its symbol list's head
	move.l	a1,asm_module_tree(a6)
	rts
start_module_known:	; from: start_module
	tst.b	d0                              ; known?
	bne.s	error_duplicate_module          ; no: on pass 2 an error
	bsr.s	select_module                   ; make it current
	bra.w	obj_module_start                ; its start to the object file
error_duplicate_module:	; from: assign_section_number
	moveq	#11,d0                          ; error 11: duplicate MODULE name
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Start or go back to the section whose name is at a4, of type d3 (the type labels in it get): read the name (a
; comma may end it) and find it among the module's sections; pass 1 adds a new one with the next section number.
; Then it becomes current_section, the PC comes from it and the object file is told.  Ends OFFSET and ORG.W.
;------------------------------------------------------------------------------
start_section:	; from: dir_section, start_module_text
	sf	offset_section(a6)              ; no OFFSET section
	sf	org_short(a6)                   ; no ORG.W
	move.b	d3,asm_section_type(a6)         ; the type for labels
	lea	line_label(a6),a0               ; the name's descriptor
	clr.l	name_after_comma(a6)            ; no comma yet
	bset	#$10,d3                         ; a comma ends the name
	bsr.w	read_string_name                ; read the name
	movea.l	current_module(a6),a2           ; the module
	addq.w	#8,a2                           ; its section list
	movem.l	d3/a3-a5,-(sp)
	bsr.w	asm_tree_find                   ; find it
	sne	d0                              ; d0 set when not found
	movem.l	(sp)+,d3/a3-a5
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	start_section_pass2             ; yes
	tst.b	d0                              ; new?
	beq.s	select_section                  ; no
	moveq	#0,d4                           ; value 0: the section's PC
	bsr.w	asm_new_symbol                  ; add it
	movea.l	current_module(a6),a0           ; the module
	subq.b	#1,$c(a0)                       ; the next section number (they count down)

;------------------------------------------------------------------------------
; Give the section a1 its number: from the module a0's count, or for DRI and executable output by its name.
;------------------------------------------------------------------------------
assign_section_number:	; from: opt_linkable
	move.b	$c(a0),d0                       ; the module's count
	bsr.w	section_name_number             ; by the name when it must be
	move.b	d0,$e(a1)                       ; the section's number
select_section:	; from: start_section
	move.l	a1,current_section_record(a6)   ; the current section
	move.l	8(a1),program_counter(a6)       ; the PC is its
	move.b	$e(a1),current_section(a6)      ; its number
	bra.w	obj_section_enter               ; to the object file
start_section_pass2:	; from: start_section
	tst.b	d0                              ; known from pass 1?
	beq.s	select_section                  ; yes
	bra.s	error_duplicate_module          ; no: an error

;------------------------------------------------------------------------------
; Keep the PC in the current section's record (before leaving it) and run the line-end routine after this line.
;------------------------------------------------------------------------------
save_section_pc:	; from: asm_entry, asm_end_pass_one, dir_offset, dir_section
	movea.l	current_section_record(a6),a1   ; the current section
	move.l	program_counter(a6),8(a1)       ; its PC
	bra.w	obj_section_leave

;------------------------------------------------------------------------------
; On pass 2, write the module's end to the object file.
;------------------------------------------------------------------------------
end_module_output:	; from: asm_entry, asm_end_pass_one, dir_module
	tst.b	pass_two(a6)                    ; pass 2?
	bne.w	obj_module_end                  ; yes: the module's end
	rts

;------------------------------------------------------------------------------
; The section number d0 for section a1: in GST linkable output d0 stays as given; in DRI or executable output the
; name must be TEXT (0), DATA (12) or BSS (24), else error 13 and TEXT.
;------------------------------------------------------------------------------
section_name_number:	; from: assign_section_number
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	section_name_check              ; no: by the name
	cmpi.w	#$1,linker_format(a6)           ; DRI format?
	bne.s	section_name_done               ; no: as given
section_name_check:
	move.b	$16(a1),d0                      ; the name's length
	move.l	$16(a1),d1                      ; and its first characters
	cmp.b	#$4,d0                          ; BSS?
	beq.s	section_name_bss
	cmp.b	#$5,d0                          ; TEXT or DATA?
	beq.s	section_name_long
section_name_bad:
	moveq	#13,d0                          ; error 13: invalid section name, TEXT assumed
	bsr.w	asm_error
	moveq	#0,d0                           ; TEXT
	rts
section_name_bss:
	cmp.l	#$4425353,d1                    ; "BSS"?
	bne.s	section_name_bad                ; no: invalid
	moveq	#24,d0                          ; 24: BSS
	rts
section_name_long:
	lsl.l	#8,d1
	move.b	$1a(a1),d1                      ; the 4 letters
	moveq	#0,d0                           ; 0: TEXT
	cmp.l	#$54455854,d1                   ; "TEXT"?
	beq.s	section_name_done               ; yes
	cmp.l	#$44415441,d1                   ; "DATA"?
	bne.s	section_name_bad                ; no: invalid
	moveq	#12,d0                          ; 12: DATA
section_name_done:
	rts

;------------------------------------------------------------------------------
; Empty the list of relocation terms the evaluator builds for linkable output: each term 4 bytes, "++" (added)
; or "--" (subtracted), then an import's number as a word or $ff and a section number; a 0 word ends the list.
;------------------------------------------------------------------------------
reloc_terms_reset:	; from: asm_expression
	lea	expr_terms(a6),a0               ; the list
	clr.w	(a0)                            ; empty
	move.l	a0,reloc_terms_end(a6)          ; its end
	sf	relocatable_terms(a6)           ; no terms counted
	rts

;------------------------------------------------------------------------------
; Add the import whose number is in d3 to the relocation terms.
;------------------------------------------------------------------------------
reloc_term_import:	; from: expr_symbol
	move.l	a0,-(sp)
	movea.l	reloc_terms_end(a6),a0          ; the list's end
	move.w	#$2b2b,(a0)+                    ; added
	move.w	d3,(a0)+                        ; the import's number
reloc_term_end:	; from: reloc_term_section
	move.l	a0,reloc_terms_end(a6)          ; the list's new end
	clr.w	(a0)                            ; ended
	movea.l	(sp)+,a0
	rts

;------------------------------------------------------------------------------
; Add the section of symbol a1 to the relocation terms.
;------------------------------------------------------------------------------
reloc_term_section:	; from: expr_symbol
	move.l	a0,-(sp)
	move.b	$e(a1),d0                       ; the symbol's section
	movea.l	reloc_terms_end(a6),a0          ; the list's end
	move.w	#$2b2b,(a0)+                    ; added
	st	(a0)+                           ; a section
	move.b	d0,(a0)+                        ; its number
	bra.s	reloc_term_end

;------------------------------------------------------------------------------
; Make the last relocation term subtracted.
;------------------------------------------------------------------------------
reloc_term_negate:	; from: expr_op_subtract
	move.l	a0,-(sp)
	movea.l	reloc_terms_end(a6),a0          ; the list's end
	move.w	#$2d2d,-$4(a0)                  ; subtracted
	movea.l	(sp)+,a0
	rts

;------------------------------------------------------------------------------
; The error and warning messages, numbered from 1 and each ended by 0; the error routine at $98be shows number d0.
;------------------------------------------------------------------------------
error_messages:	; from: asm_error
	dc.b	'line malformed',0              ; 1: line malformed
err_out_of_memory:
	dc.b	'out of memory',0               ; 2
err_undefined_symbol:
	dc.b	'undefined symbol',0            ; 3
err_additional_symbol:
	dc.b	'additional symbol on pass 2',0 ; 4
err_defined_twice:
	dc.b	'symbol defined twice',0        ; 5
err_phasing:
	dc.b	'phasing error',0               ; 6
err_local_not_allowed:
	dc.b	'local not allowed',0           ; 7
err_invalid_hashing:
	dc.b	'INTERNAL:invalid hashing',0    ; 8
err_not_recognised:
	dc.b	'instruction not recognised',0  ; 9
err_invalid_size:
	dc.b	'invalid size',0                ; 10
err_duplicate_module:
	dc.b	'duplicate MODULE name',0       ; 11
err_forward_reference:
	dc.b	'forward reference',0           ; 12
err_section_name:
