	dc.b	'short branch cannot be 0 bytes',0 ; 81
err_negative_count:
	dc.b	'DCB or DS count must not be negative',0 ; 82
	dc.w	$7027,$604c                     ; moveq #39,d0 / bra.s to the fatal error exit: "cannot create binary
                                                ;   file", not used

;------------------------------------------------------------------------------
; Write d1 bytes at a0 to the binary file; returns when all of them went.  A short write closes the file
; and ends the assembly with the fatal error 'during writing binary file'.
;------------------------------------------------------------------------------
binary_write:                                   ; from: binary_fill, exe_incbin, exe_flush_buffer, exe_finish,
                                                ;   exe_symbols_flush, exe_relocation_flush, 3 more
	bsr.w	output_write                    ; Fwrite them
	bne.s	binary_write_error              ; all written?
	rts                                     ; yes
binary_write_error:	; from: dri_symbol_record
	bsr.w	binary_close                    ; close the binary file
	moveq	#38,d0                          ; 'during writing binary file'
	bra.s	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Short entries for one error each: d0 = the error number, then on to the report.  The ones that jump to
; asm_line_error abandon the rest of the line.
;------------------------------------------------------------------------------
err_line_malformed:	; from: asm_line, asm_mnemonic
	moveq	#1,d0                           ; 'line malformed'
	bra.s	asm_error
report_defined_twice:	; from: asm_tree_find, asm_define_symbol, dir_equ, dir_equr, dir_reg, dir_rs, 3 more
	moveq	#5,d0                           ; 'symbol defined twice'
	bra.s	asm_error
report_additional_symbol:	; from: asm_tree_find, dir_equr, dir_reg, macro_store_line
	moveq	#4,d0                           ; 'additional symbol on pass 2'
	bra.s	asm_error
report_phasing:	; from: asm_tree_find, dir_equ, dir_rs
	moveq	#6,d0                           ; 'phasing error'
	bra.s	asm_error
report_local_not_allowed:	; from: asm_define_symbol, xdef_symbol
	moveq	#7,d0                           ; 'local not allowed'
	bra.s	asm_error
report_not_recognised:	; from: asm_mnemonic, macro_call
	moveq	#9,d0                           ; 'instruction not recognised'
	bra.s	asm_error

report_invalid_size:	; from: ea_parse, asm_size_not_byte, dir_even, ins_jmp_jsr, ins_link, ins_logic_imm, 9 more
	moveq	#10,d0                          ; 'invalid size'
	bra.s	asm_error
report_forward_reference:	; from: dir_equ, dir_rs, dir_set, macro_call
	moveq	#12,d0                          ; 'forward reference'
	bra.s	asm_error
err_absolute_not_allowed:	; from: evaluate_absolute
	moveq	#32,d0                          ; 'absolute not allowed'
	bra.s	asm_error

report_data_too_large:	; from: ins_moveq
	moveq	#28,d0                          ; 'data too large'
	bra.s	asm_error
report_bss_data:	; from: dir_incbin, exe_incbin, exe_emit
	moveq	#37,d0                          ; 'BSS or OFFSET section cannot contain data'
	bra.s	asm_error
report_mode_not_recognised:	; from: ea_check_address, emit_immediate_byte
	moveq	#15,d0                          ; 'addressing mode not recognised'
	bra.s	asm_line_error                  ; abandon the line
report_comma_expected:                          ; from: emit_immediate_byte, asm_abcd_sbcd, asm_add_subtract,
                                                ;   asm_adda_suba_cmpa, asm_addi_subi_cmpi, asm_btst, 19 more
	moveq	#30,d0                          ; 'comma expected'
	bra.s	asm_line_error                  ; abandon the line
report_index_size:	; from: emit_immediate_byte
	moveq	#31,d0                          ; '.W or .L expected as index size'
	bra.s	asm_line_error                  ; abandon the line
report_immediate_expected:                      ; from: asm_addi_subi_cmpi, ins_link, ins_logic_imm, ins_addq_subq,
                                                ;   ins_moveq, ins_stop, 1 more
	moveq	#35,d0                          ; 'immediate data expected'
	bra.s	asm_line_error                  ; abandon the line

;------------------------------------------------------------------------------
; Fatal error d0: report it on the screen (listing off), return code 20, and end the assembly at once.
;------------------------------------------------------------------------------
asm_fatal_error:	; from: asm_entry, asm_peek_line, asm_read_line, dir_include, if_value, macro_stack_init, 9 more
	sf	asm_listing_active(a6)          ; the report goes to the screen
	move.b	#$14,return_code(a6)            ; return code 20
	bsr.s	asm_error                       ; report it
	bra.w	asm_finish                      ; end the assembly
asm_error_done:	; from: asm_error
	rts

;------------------------------------------------------------------------------
; Error d0 that abandons the line: back to the stack at the line's start, so the report's rts returns
; from the line's routine.
;------------------------------------------------------------------------------
asm_line_error:                                 ; from: asm_expression, asm_parse_expression, ea_check_mode, data_fill,
                                                ;   need_global_label, asm_parse_register_list, 7 more
	movea.l	asm_line_sp(a6),sp              ; the stack as the line started

;------------------------------------------------------------------------------
; Report error d0 (a number in the table at $9116): only the line's first error is reported.  Raises
; the return code to 10, counts the error, adds it to the editor's error list and prints
; "Error <message> at line <n> [in file <name>]".  The line is then listed.  All registers kept.
;------------------------------------------------------------------------------
asm_error:                                      ; from: asm_check_endc, asm_parse_expression, expr_type_error,
                                                ;   expr_get_token, expr_local_number, evaluate_no_import, 44 more
	tst.b	line_has_error(a6)              ; already an error on this line?
	bne.s	asm_error_done                  ; yes: one is enough
	st	line_has_error(a6)              ; now there is
	cmpi.b	#$a,return_code(a6)             ; return code at least 10?
	bcc.s	asm_error_report                ; yes
	move.b	#$a,return_code(a6)             ; no: make it 10
asm_error_report:
	movem.l	d1-d3/a0-a3,-(sp)
	move.w	d0,-(sp)                        ; the error number
	moveq	#6,d0                           ; 'Error '
	bsr.w	print_asm_message
	lea	error_messages(pc),a0           ; the error messages
	addq.b	#1,asm_error_count(a6)          ; one more error
	moveq	#0,d2                           ; list flag: an error

;------------------------------------------------------------------------------
; The report for errors and warnings: d0 on the stack = the number, a0 = the message table, d2 = $8000
; for a warning, 0 for an error.
;------------------------------------------------------------------------------
asm_report_message:	; from: asm_warning
	move.w	(sp)+,d0                        ; the number
	tst.l	editor_error_list(a6)           ; an error list from the editor?
	beq.s	asm_report_print                ; no
	tst.l	include_file(a6)                ; in an include file?
	bne.s	asm_report_print                ; yes: the editor cannot show it
	movea.l	editor_error_list(a6),a1        ; the list: a size word, then line and number pairs, 0 at the end
	move.w	(a1)+,d3                        ; its size in words
	move.w	d3,d1                           ; words left
asm_report_find_end:
	tst.w	(a1)+                           ; the end?
	beq.s	asm_report_found_end            ; yes
	subq.w	#1,d1
	bne.s	asm_report_find_end             ; not full yet
	bra.s	asm_report_print                ; full: not added
asm_report_found_end:
	cmp.w	d1,d3                           ; the first entry?
	beq.s	asm_report_add                  ; yes: add it
	move.w	-$6(a1),d3                      ; the last entry's line
	bmi.s	asm_report_add
	cmp.w	line_number(a6),d3              ; already one for this line?
	beq.s	asm_report_print                ; yes: one entry a line
asm_report_add:
	move.w	line_number(a6),-$2(a1)         ; the line
	move.w	d0,(a1)                         ; the number
	or.w	d2,(a1)+                        ; marked when a warning
	clr.w	(a1)                            ; the new end
asm_report_print:
	subq.w	#1,d0                           ; messages count from 1
	bsr.w	print_string_number             ; print message d0 of table a0
	moveq	#9,d0                           ; ' at line '
	bsr.w	print_asm_message
	moveq	#0,d1
	move.w	line_number(a6),d1              ; the line number
	bsr.w	print_decimal                   ; in decimal
	tst.l	include_file(a6)                ; in an include file?
	beq.s	asm_report_done                 ; no
	moveq	#11,d0                          ; ' in file '
	bsr.w	print_asm_message
	movea.l	include_file(a6),a1             ; the include file's entry
	moveq	#0,d2
	move.b	$16(a1),d2                      ; its name's length
	subq.b	#2,d2                           ; all but its last byte, less one for dbra
	lea	$17(a1),a1                      ; its name
asm_report_file_name:
	move.b	(a1)+,d1
	bsr.w	print_char                      ; print it
	dbra	d2,asm_report_file_name
asm_report_done:
	bsr.w	print_newline                   ; end the line
	st	asm_line_had_error(a6)          ; list this line
	movem.l	(sp)+,d1-d3/a0-a3
asm_warning_done:	; from: asm_warning
	rts

;------------------------------------------------------------------------------
; Report warning d0 (a number in the table at msg_warnings), only in pass 2 and with warnings on (OPT W+).
; Raises the return code to 5 and prints "Warning <message> at line <n> [in file <name>]".
;------------------------------------------------------------------------------
asm_warning:	; from: expr_symbol, asm_bcc, ins_link, dir_module, ins_move_from_sr, ins_moveq, 2 more
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_warning_done                ; no: none
	tst.b	asm_warnings(a6)                ; warnings on?
	beq.s	asm_warning_done                ; no
	cmpi.b	#$5,return_code(a6)             ; return code at least 5?
	bcc.s	asm_warning_report              ; yes
	move.b	#$5,return_code(a6)             ; no: make it 5
asm_warning_report:
	movem.l	d1-d3/a0-a3,-(sp)
	move.w	d0,-(sp)                        ; the warning number
	moveq	#8,d0                           ; 'Warning '
	bsr.w	print_asm_message
	lea	msg_warnings(pc),a0             ; the warning messages
	move.w	#$8000,d2                       ; list flag: a warning
	bra.w	asm_report_message              ; as for an error

;------------------------------------------------------------------------------
; The warning messages, numbered from 1.  8-14 are optimisations.
;------------------------------------------------------------------------------
msg_warnings:	; from: asm_warning
	dc.b	'sign extended operand',0       ; 1
	dc.b	'relative cannot be relocated',0 ; 2
	dc.b	'invalid LINK displacement',0   ; 3
	dc.b	'68010 instruction, converted to MOVE SR',0 ; 4
	dc.b	'size should be .W',0           ; 5
	dc.b	'directive ignored',0           ; 6
	dc.b	'misuse of register list',0     ; 7
	dc.b	'branch made short',0           ; 8: optimisation
	dc.b	'offset removed',0              ; 9: optimisation
	dc.b	'short word addressing used',0  ; 10: optimisation
	dc.b	'MOVEQ substituted',0           ; 11: optimisation
	dc.b	'quick form used',0             ; 12: optimisation
	dc.b	'branch could be short',0       ; 13: shown only, nothing changed
	dc.b	'short branch converted to NOP',0 ; 14: optimisation
	dc.b	$00
optimisation_savings:	; from: asm_optimisation
	dc.w	$0202,$0204,$00ff,$0002,$0200,$0202 ; bytes saved by warnings 8-19, $ff = not an optimisation (not
                                                ;   counted)

;------------------------------------------------------------------------------
; Optimisation d0 (a warning number 8-14) was made: in pass 2 count it and the bytes saved, and show its
; warning when bit d0-8 of the optimisation warning mask is set.  d0 and d1 kept.
;------------------------------------------------------------------------------
asm_optimisation:	; from: ea_parse, emit_immediate_byte, asm_add_quick, asm_bcc, asm_bcc_word, ins_move_try_moveq
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_optimisation_done           ; no
	movem.w	d0-d1,-(sp)
	subq.w	#8,d0                           ; from warning 8
	move.b	optimisation_savings(pc,d0.w),d0 ; the bytes it saves
	bmi.s	asm_optimisation_warn           ; not an optimisation
	ext.w	d0
	add.w	d0,asm_optimise_saved(a6)       ; add them up
	addq.w	#1,asm_optimise_count(a6)       ; one more optimisation
asm_optimisation_warn:
	move.w	(sp),d0                         ; the warning number
	subq.w	#8,d0
	move.w	asm_optimise_warnings(a6),d1    ; the warning mask
	btst	d0,d1                           ; wanted?
	movem.w	(sp)+,d0-d1
	bne.w	asm_warning                     ; yes: warn
asm_optimisation_done:
	rts
report_program_buffer_full:                     ; from: binary_create, exe_buffers_init, exe_flush_buffer,
                                                ;   exe_symbols_flush, exe_relocation_flush, exe_finish_memory
	moveq	#65,d0                          ; 'program buffer full'
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Start reading the include file named by a0 (a name descriptor: pointer, length at 5): its entry (type 11)
; in the module and file table holds the handle at $98 and a buffer at 8.  The first time the whole file is
; buffered when it fits in half the free memory, else $1200 bytes at a time.  Out: d0 = 0 (Z) when open,
; else 25, 26 or 27; the entry becomes the current include file, the line number starts again.
; The buffer: +0 read pointer, +4 size, +8 data end, +$c the includer's line number, +$e data
;------------------------------------------------------------------------------
include_open:	; from: asm_entry, dir_include
	movea.l	asm_name_tree(a6),a2            ; the module and file table
	movem.l	a3-a5,-(sp)
	bsr.w	asm_tree_find                   ; find the file's entry
	sne	d0                              ; d0 set: not there yet
	movem.l	(sp)+,a3-a5
	tst.b	pass_two(a6)                    ; pass 2?
	bne.w	include_open_again              ; yes
	tst.b	d0                              ; new?
	bne.s	include_open_new                ; yes: make it
	move.l	a0,-(sp)
	movea.l	8(a1),a0                        ; its buffer
	tst.w	$c(a0)                          ; in use (a line number saved)?
	movea.l	(sp)+,a0
	bne.w	include_repeated                ; yes: it includes itself
	bra.w	include_open_again              ; no: use it again
include_open_new:
	moveq	#0,d4
	moveq	#11,d3                          ; type 11: an include file
	moveq	#118,d0                         ; room for 236 bytes more
	add.l	d0,d0
	bsr.w	asm_new_record                  ; add the entry
	clr.l	$98(a1)                         ; no handle yet
	move.l	a1,-(sp)
	bsr.w	open_source_file                ; open it: d4 = handle, d1 = length
	movea.l	(sp)+,a1
	bne.w	include_not_found               ; not found
	move.l	d4,$98(a1)                      ; the handle
	move.l	include_file(a6),$10(a1)        ; link to the file that includes it
	move.l	a1,include_file(a6)             ; now the current include file
	addq.l	#3,d1                           ; length rounded up to even, room for a CR
	bclr	#$0,d1
	move.l	#$1200,d2                       ; else $1200 bytes
	bsr.w	buffer_size                     ; the whole file if it fits
	move.l	a1,-(sp)
	move.l	d1,d3                           ; the buffer size
	addi.l	#$e,d1                          ; and its header
	bsr.w	alloc_block                     ; get the memory
	movea.l	(sp),a1                         ; the entry
	move.l	a0,8(a1)                        ; its buffer
	lea	$e(a0),a1                       ; the data's start
	move.l	d3,4(a0)                        ; the size
	adda.l	d3,a1
	move.l	a1,8(a0)                        ; empty: the end
	move.l	a1,(a0)                         ; and the read pointer
	move.w	line_number(a6),$c(a0)          ; save the includer's line number
	clr.w	line_number(a6)                 ; and start the count again
	movea.l	(sp)+,a1
	st	$e(a1)                          ; no reads yet ($ff, one read gives 0)
	bra.w	include_read                    ; fill the buffer
include_open_again:
	tst.b	d0                              ; not there in pass 2?
	bne.w	include_repeated                ; yes: error
	move.l	include_file(a6),$10(a1)        ; link to the file that includes it
	move.l	a1,include_file(a6)             ; now the current include file
	tst.b	$e(a1)                          ; more than one read the last time?
	beq.s	include_open_buffered           ; no: all of it is still in the buffer
	move.l	a1,-(sp)
	bsr.w	open_source_file                ; open it again
	movea.l	(sp)+,a1
	bne.w	include_not_found               ; not found
	move.l	d4,$98(a1)                      ; the handle
	movea.l	8(a1),a0                        ; its buffer
	move.w	line_number(a6),$c(a0)          ; save the includer's line number
	clr.w	line_number(a6)                 ; and start the count again
	lea	$e(a0),a2                       ; the data's start
	move.l	a2,(a0)                         ; the read pointer
	bra.s	include_read                    ; read it from the start
include_open_buffered:
	movea.l	8(a1),a0                        ; its buffer
	move.w	line_number(a6),$c(a0)          ; save the includer's line number
	clr.w	line_number(a6)                 ; and start the count again
	lea	$e(a0),a2                       ; the data's start
	move.l	a2,(a0)                         ; read from the start again
	moveq	#0,d0                           ; open
	rts

;------------------------------------------------------------------------------
; Read d1 more bytes of include file a1 into its buffer a0 at a2 (after a part line kept at its start).
;------------------------------------------------------------------------------
include_read_more:	; from: asm_read_line
	move.l	a0,(a0)                         ; the read pointer: the data's start
	addi.l	#$e,(a0)
	movea.l	a2,a0                           ; where to read to
	bra.s	include_read_into

;------------------------------------------------------------------------------
; Fill include file a1's buffer a0 from the file.  At the file's end make sure the text ends in CR LF,
; else add a CR.  Out: d0 = 0 (Z) or 25 'include file read error'.
;------------------------------------------------------------------------------
include_read:	; from: asm_read_line, include_open
	move.l	a0,(a0)                         ; the read pointer: the data's start
	addi.l	#$e,(a0)
	move.l	4(a0),d1                        ; a buffer's worth
	lea	$e(a0),a0
include_read_into:	; from: include_read_more
	move.l	$98(a1),d2                      ; the handle
	movem.l	d1/a0-a1,-(sp)
	bsr.w	read_source_file                ; Fread
	movem.l	(sp)+,d2/a0-a1                  ; d2 = bytes asked
	bne.s	include_read_error              ; failed
	lea	0(a0,d1.l),a2                   ; the end of the data
	cmp.l	d1,d2                           ; all of them: more to come
	beq.s	include_read_done
	clr.b	(a2)                            ; the file's end
	cmpi.b	#$a,-$1(a2)                     ; ends in LF?
	bne.s	include_read_add_cr             ; no
	cmpi.b	#$d,-$2(a2)                     ; after a CR?
	beq.s	include_read_done               ; yes
include_read_add_cr:
	move.b	#$d,(a2)+                       ; no: end the last line
include_read_done:
	movea.l	8(a1),a0                        ; the buffer
	move.l	a2,8(a0)                        ; its data end
	addq.b	#1,$e(a1)                       ; one more read
	moveq	#0,d0
	rts
include_read_error:
	moveq	#25,d0                          ; 'include file read error'
	rts
include_not_found:	; from: include_open
	moveq	#26,d0                          ; 'file not found'
	rts
include_repeated:	; from: include_open
	moveq	#27,d0                          ; 'repeated include file'
	rts

;------------------------------------------------------------------------------
; Close every include file still open (type 11 entries of the module and file table).
;------------------------------------------------------------------------------
include_close_all:	; from: asm_finish, asm_end_pass_one
	moveq	#11,d3                          ; type 11: include files
	lea	include_close_file(pc),a2       ; for each of them
	bra.s	symbols_walk_table
include_close_file:
	move.l	$98(a0),d2                      ; its handle
	beq.s	symbols_walk_done               ; closed
	clr.l	$98(a0)                         ; now it is
	movem.l	a0/a2,-(sp)
	bsr.w	close_source_file               ; Fclose
	movem.l	(sp)+,a0/a2
symbols_walk_done:	; from: symbols_walk_table
	rts

;------------------------------------------------------------------------------
; Call a2 for every entry of the module and file table of type d3 (0 = all) in order, a0 = the entry.
;------------------------------------------------------------------------------
symbols_walk_table:	; from: include_close_all, symbol_listing
	move.l	asm_name_tree(a6),d0            ; the table
	beq.s	symbols_walk_done               ; none
	movea.l	d0,a0
	move.l	(a0),d0                         ; its root
	beq.s	symbols_walk_done               ; empty
	movea.l	d0,a0

;------------------------------------------------------------------------------
; Call a2 for every node of the tree at a0 of type d3 (0 = all), in order; a0 = the node.
;------------------------------------------------------------------------------
symbols_walk_tree:	; from: gst_module_start
	tst.l	(a0)                            ; a left branch?
	beq.s	symbols_walk_node               ; no
	move.l	a0,-(sp)
	movea.l	(a0),a0
	bsr.s	symbols_walk_tree               ; walk it
	movea.l	(sp)+,a0
symbols_walk_node:
	tst.b	d3                              ; any type?
	beq.s	symbols_walk_call               ; yes
	cmp.b	$d(a0),d3                       ; the type wanted?
	bne.s	symbols_walk_right              ; no
symbols_walk_call:
	jsr	(a2)                            ; call the routine
symbols_walk_right:
	tst.l	4(a0)                           ; a right branch?
	beq.s	symbols_walk_tree_done          ; no
	move.l	a0,-(sp)
	movea.l	4(a0),a0
	bsr.s	symbols_walk_tree               ; walk it
	movea.l	(sp)+,a0
symbols_walk_tree_done:
	rts

;------------------------------------------------------------------------------
; Call a2 for every local symbol of module a1, in order; a1 = the symbol.
;------------------------------------------------------------------------------
module_walk_locals:	; from: module_walk_exports, exe_finish, exe_finish_memory, gst_module_end, dri_symbol
	tst.l	$10(a1)                         ; any locals?
	beq.s	symbol_tree_each_done           ; no
	movea.l	$10(a1),a1                      ; the module's own tree

;------------------------------------------------------------------------------
; Call a2 for every node of the tree at a1, in order; a1 = the node.
;------------------------------------------------------------------------------
symbol_tree_each:	; from: module_walk_exports, dri_symbol
	tst.l	(a1)                            ; a left branch?
	beq.s	symbol_tree_each_call           ; no
	move.l	a1,-(sp)
	movea.l	(a1),a1
	bsr.s	symbol_tree_each                ; walk it
	movea.l	(sp)+,a1
symbol_tree_each_call:
	jsr	(a2)                            ; call the routine
	tst.l	4(a1)                           ; a right branch?
	beq.s	symbol_tree_each_done           ; no
	move.l	a1,-(sp)
	movea.l	4(a1),a1
	bsr.s	symbol_tree_each                ; walk it
	movea.l	(sp)+,a1
symbol_tree_each_done:	; from: module_walk_locals
	rts

;------------------------------------------------------------------------------
; Not called: call a3 for each exported symbol of module a1, then for each exported global.
;------------------------------------------------------------------------------
module_walk_exports:
	move.l	a3,-(sp)
	movea.l	a2,a3                           ; the routine
	lea	exports_walk_check(pc),a2       ; the test for each symbol
	bsr.s	module_walk_locals              ; the module's locals
	movea.l	equate_tree(a6),a1              ; the global table
	tst.l	(a1)                            ; empty?
	beq.s	exports_walk_done               ; yes
	movea.l	(a1),a1                         ; its root
	bsr.s	symbol_tree_each                ; walk it
exports_walk_done:
	movea.l	(sp)+,a3
	rts
exports_walk_check:
	btst	#$5,$c(a1)                      ; exported (XDEF)?
	beq.s	exports_walk_skip               ; no
	jsr	(a3)                            ; yes: call it
exports_walk_skip:
	rts

;------------------------------------------------------------------------------
; Not called: call a2 for each imported symbol of module a1.
;------------------------------------------------------------------------------
module_walk_imports:
	tst.l	$10(a1)                         ; any locals?
	beq.s	symbol_tree_imports_done        ; no
	movea.l	$10(a1),a1                      ; the module's own tree

;------------------------------------------------------------------------------
; Call a2 for every imported (XREF) symbol of the tree at a1, in order; a1 = the symbol.
;------------------------------------------------------------------------------
symbol_tree_imports:
	tst.l	(a1)                            ; a left branch?
	beq.s	symbol_tree_imports_node        ; no
	move.l	a1,-(sp)
	movea.l	(a1),a1
	bsr.s	symbol_tree_imports             ; walk it
	movea.l	(sp)+,a1
symbol_tree_imports_node:
	bsr.s	symbol_import_call              ; this one
	tst.l	4(a1)                           ; a right branch?
	beq.s	symbol_tree_imports_done        ; no
	move.l	a1,-(sp)
	movea.l	4(a1),a1
	bsr.s	symbol_tree_imports             ; walk it
	movea.l	(sp)+,a1
symbol_tree_imports_done:	; from: module_walk_imports
	rts

;------------------------------------------------------------------------------
; Call a2 when symbol a1 is imported (flag bit 4).
;------------------------------------------------------------------------------
symbol_import_call:	; from: symbol_tree_imports
	btst	#$4,$c(a1)                      ; imported?
	beq.s	symbol_import_skip              ; no
	jsr	(a2)                            ; yes: call it
symbol_import_skip:
	rts

;------------------------------------------------------------------------------
; The optimisation records: pass 1 notes each optimisation (program offset, value) in a chain of blocks
; (+0 next, +4 bytes used, +6 50 records of 8 bytes) and pass 2 makes only the ones it finds there, so
; both passes give the same sizes.  At a pass's start: pass 1 gets the first block, pass 2 rewinds to it.
;------------------------------------------------------------------------------
optimisations_start_pass:	; from: asm_init_pass
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	optimisations_rewind            ; yes
	move.l	#$196,d1                        ; a block: 6 + 50 * 8 bytes
	bsr.w	alloc_block
	move.l	a0,optimisation_first(a6)       ; the first block
	move.l	a0,optimisation_block(a6)       ; and the current one
	clr.l	(a0)+                           ; no next block
	clr.w	(a0)                            ; none used
	rts
optimisations_rewind:
	movea.l	optimisation_block(a6),a0       ; the last block
	move.w	4(a0),d0                        ; its bytes used
	lea	6(a0,d0.w),a0
	move.l	a0,optimisation_end(a6)         ; the end of the records
	movea.l	optimisation_first(a6),a0       ; back to the first block
	move.l	a0,optimisation_block(a6)
	moveq	#-1,d0                          ; none
	tst.w	4(a0)                           ; any records?
	beq.s	optimisations_rewind_done       ; no
	clr.w	4(a0)                           ; now the read index
	move.l	6(a0),d0                        ; the first one's offset
optimisations_rewind_done:
	move.l	d0,next_optimisation(a6)        ; the next offset to optimise, -1 none
	rts

;------------------------------------------------------------------------------
; May the instruction at a5 be optimised (value d2)?  Pass 1 records it and says yes; pass 2 says yes only
; at the next recorded offset (an 'INTERNAL:invalid optimisation' when its value differs).  Out: Z = yes.
;------------------------------------------------------------------------------
optimisation_check:	; from: ea_parse, emit_immediate_byte, asm_add_quick, asm_bcc_word, ins_move_try_moveq
	move.l	a5,d0                           ; the program offset of a5
	sub.l	code_buffer_ptr(a6),d0
	add.l	asm_code_size(a6),d0
	tst.b	pass_two(a6)                    ; pass 2?
	bne.s	optimisation_match              ; yes
	move.l	d0,-(sp)
	movea.l	optimisation_block(a6),a0       ; the current block
	addq.l	#4,a0
	move.w	(a0)+,d0                        ; its bytes used
	cmp.w	#$190,d0                        ; full?
	beq.s	optimisation_new_block          ; yes: a new one
optimisation_record:
	move.l	(sp)+,0(a0,d0.w)                ; the offset
	move.l	d2,4(a0,d0.w)                   ; the value
	addq.w	#8,d0
	move.w	d0,-(a0)
	moveq	#0,d0                           ; yes
	rts
optimisation_new_block:
	movem.l	d1-d2/a1-a2,-(sp)
	move.l	#$196,d1                        ; another block
	bsr.w	alloc_block
	movea.l	optimisation_block(a6),a1       ; the current one
	move.l	a0,(a1)                         ; links to it
	move.l	a0,optimisation_block(a6)       ; now the current one
	clr.l	(a0)+                           ; no next block
	clr.w	(a0)+                           ; none used
	moveq	#0,d0
	movem.l	(sp)+,d1-d2/a1-a2
	bra.s	optimisation_record             ; record it there
optimisation_match:
	cmp.l	next_optimisation(a6),d0        ; the next recorded one?
	bne.s	optimisation_check_done         ; no: NE
	movea.l	optimisation_block(a6),a0       ; the current block
	addq.l	#4,a0
	move.w	(a0)+,d0                        ; the read index
	cmp.l	4(a0,d0.w),d2                   ; the same value as in pass 1?
	beq.s	optimisation_match_next         ; yes
	move.w	d0,-(sp)
	moveq	#63,d0                          ; 'INTERNAL:invalid optimisation'
	bsr.w	asm_error
	move.w	(sp)+,d0
optimisation_match_next:
	addq.w	#8,d0                           ; the next record
	cmp.w	#$190,d0                        ; past the block's end?
	beq.s	optimisation_match_block        ; yes: the next block
optimisation_match_store:
	move.w	d0,-$2(a0)                      ; the new read index
	adda.w	d0,a0                           ; the next record
	cmpa.l	optimisation_end(a6),a0         ; past the last one?
	beq.s	optimisation_match_end          ; yes
	move.l	(a0),next_optimisation(a6)      ; its offset
	moveq	#0,d0                           ; Z: yes
optimisation_check_done:
	rts
optimisation_match_block:
	movea.l	optimisation_block(a6),a0       ; the current block
	tst.l	(a0)                            ; another one?
	beq.s	optimisation_match_end          ; no
	movea.l	(a0),a0
	move.l	a0,optimisation_block(a6)       ; now the current one
	addq.w	#6,a0                           ; its records
	moveq	#0,d0                           ; from the first
	bra.s	optimisation_match_store
optimisation_match_end:
	moveq	#-1,d0                          ; no more to make
	move.l	d0,next_optimisation(a6)
	moveq	#0,d0                           ; Z: yes
	rts

;------------------------------------------------------------------------------
; Print message d0 of the assembler's messages (msg_assembler: 0 = the sign-on, 1 'Pass 1' ...).
;------------------------------------------------------------------------------
print_asm_message:                              ; from: asm_entry, asm_finish, asm_error, asm_report_message,
                                                ;   asm_warning, symbol_listing, 1 more
	lea	msg_assembler(pc),a0            ; the messages
	tst.w	d0                              ; the first?

;------------------------------------------------------------------------------
; Print string d0 of the zero-ended strings at a0, flags set from d0 on entry.
;------------------------------------------------------------------------------
print_string_number:	; from: asm_report_message
	beq.w	print_string                    ; this one: print it
print_string_skip:
	tst.b	(a0)+                           ; skip a string
	bne.s	print_string_skip
	subq.w	#1,d0
	bra.s	print_string_number

;------------------------------------------------------------------------------
; Print a CR (CR LF on the screen).
;------------------------------------------------------------------------------
print_newline:	; from: asm_entry, asm_finish, dir_spc, asm_report_message, symbol_listing, symbol_listing_tree, 2 more
	moveq	#13,d1                          ; CR
	bra.w	asm_output_char

;------------------------------------------------------------------------------
; Print two spaces.
;------------------------------------------------------------------------------
print_two_spaces:                               ; from: symbol_listing, symbol_listing_tree, listing_source_line,
                                                ;   listing_section, exe_list_section
	bsr.w	print_space                     ; one

;------------------------------------------------------------------------------
; Print a space.
;------------------------------------------------------------------------------
print_space:	; from: print_two_spaces, symbol_listing, listing_source_line
	moveq	#32,d1                          ; and one

;------------------------------------------------------------------------------
; Print character d1 to the listing or the screen; all registers kept.
;------------------------------------------------------------------------------
print_char:                                     ; from: asm_report_message, print_hex_digit, print_decimal,
                                                ;   symbol_listing, symbol_listing_tree, listing_page_header, 1 more
	movem.l	d0-d2/a0-a2,-(sp)
	bsr.w	asm_output_char                 ; out
	movem.l	(sp)+,d0-d2/a0-a2
	rts

;------------------------------------------------------------------------------
; Print d1 as 8 hex digits; 9e94 the low word as 4, 9e9c the low byte as 2, 9ea4 the low nibble as 1.
;------------------------------------------------------------------------------
print_hex_long:	; from: symbol_listing_tree, listing_source_line
	move.w	d1,-(sp)
	swap	d1                              ; the high word
	bsr.s	print_hex_word
	move.w	(sp)+,d1                        ; then the low word

print_hex_word:	; from: print_hex_long
	move.w	d1,-(sp)
	lsr.w	#8,d1                           ; the high byte
	bsr.s	print_hex_byte
	move.w	(sp)+,d1                        ; then the low byte

print_hex_byte:	; from: print_hex_word, listing_source_line, gst_list_section
	move.w	d1,-(sp)
	lsr.w	#4,d1                           ; the high nibble
	bsr.s	print_hex_digit
	move.w	(sp)+,d1                        ; then the low nibble

print_hex_digit:	; from: print_hex_byte
	andi.w	#$f,d1                          ; the nibble
	move.b	hex_digits(pc,d1.w),d1          ; its digit
	bra.s	print_char                      ; print it
hex_digits:	; from: hex_unpadded
	dc.b	'0123456789ABCDEF'              ; the hex digits

;------------------------------------------------------------------------------
; Put d1 as hex without leading zeros (at least one digit), each digit in d1 through routine a2.
;------------------------------------------------------------------------------
hex_unpadded:	; from: macro_expand_put
	moveq	#6,d3                           ; 7 digits that may be left out
	moveq	#0,d2                           ; no digit yet
hex_unpadded_loop:
	rol.l	#4,d1                           ; the next nibble to the bottom
	move.l	d1,-(sp)
	andi.w	#$f,d1
	bne.s	hex_unpadded_digit              ; not 0: put it
	tst.b	d2                              ; a digit before it?
	beq.s	hex_unpadded_next               ; no: leave it out
hex_unpadded_digit:
	st	d2                              ; digits from now on
	move.b	hex_digits(pc,d1.w),d1          ; its digit
	jsr	(a2)                            ; put it
hex_unpadded_next:
	move.l	(sp)+,d1
	dbra	d3,hex_unpadded_loop
	rol.l	#4,d1                           ; the last nibble
	andi.w	#$f,d1
	move.b	hex_digits(pc,d1.w),d1          ; always put
	jmp	(a2)

;------------------------------------------------------------------------------
; Print d1 as an unsigned decimal number without leading zeros.
;------------------------------------------------------------------------------
print_decimal:	; from: asm_finish, asm_report_message, listing_page_header, listing_source_line, show_memory_time
	lea	print_char(pc),a2               ; print each digit

;------------------------------------------------------------------------------
; Put d1 as an unsigned decimal number without leading zeros, each digit in d1 through routine a2.
;------------------------------------------------------------------------------
decimal_out:	; from: macro_next_line, macro_expand_put
	lea	asm_decimal_powers(pc),a0       ; the powers of ten
	moveq	#1,d2                           ; no digit yet (positive)
	moveq	#8,d0                           ; 9 powers, then the units
decimal_out_loop:
	moveq	#0,d3                           ; this digit
	cmp.l	(a0)+,d1                        ; below this power?
	bcs.s	decimal_out_zero                ; yes: a 0
	sub.l	-(a0),d1
decimal_out_count:
	addq.b	#1,d3                           ; count the subtractions
	sub.l	(a0),d1
	bcc.s	decimal_out_count
	add.l	(a0)+,d1                        ; one too many
	bra.s	decimal_out_digit
decimal_out_zero:
	tst.b	d2                              ; a digit before it?
	bpl.s	decimal_out_next                ; no: leave it out
decimal_out_digit:
	st	d2                              ; digits from now on
	addi.b	#$30,d3                         ; the digit
	exg	d3,d1
	jsr	(a2)                            ; put it
	exg	d3,d1
decimal_out_next:
	dbra	d0,decimal_out_loop
	addi.b	#$30,d1                         ; the units digit, always put
	jmp	(a2)
asm_decimal_powers:
	dc.w	$3b9a,$ca00,$05f5,$e100,$0098,$9680,$000f,$4240 ; 1000000000, 100000000, 10000000, 1000000
	dc.w	$0001,$86a0,$0000,$2710,$0000,$03e8,$0000,$0064 ; 100000, 10000, 1000, 100
	dc.w	$0000,$000a                     ; 10

;------------------------------------------------------------------------------
; The symbol table listing (OPT S+), after pass 2: "GLOBAL SYMBOLS" in name order, then for each module
; "MODULE <name>" and its local symbols with their section.  Each line: value, type letter, name.
;------------------------------------------------------------------------------
symbol_listing:	; from: asm_entry
	moveq	#20,d0                          ; 'GLOBAL SYMBOLS'
	bsr.w	print_asm_message
	movea.l	equate_tree(a6),a2              ; the global table
	lea	symbol_listing_gap(pc),a4       ; 3 spaces for the section column
	bsr.w	symbol_listing_tree             ; list it
	moveq	#9,d3                           ; type 9: modules
	lea	symbol_listing_module(pc),a2    ; for each module
	lea	symbol_listing_local_section(pc),a4 ; the locals' section column
	bra.w	symbols_walk_table
symbol_listing_local_section:
	cmpi.b	#$2,$d(a3)                      ; absolute?
	beq.s	symbol_listing_gap              ; yes: 3 spaces
	move.b	$e(a3),d0                       ; its section
	bra.w	listing_section_letter          ; its letter (or number)
symbol_listing_gap:
	bsr.w	print_space                     ; 3 spaces
	bra.w	print_two_spaces
symbol_listing_module:
	movem.l	d3/a0/a2,-(sp)
	move.l	a0,-(sp)                        ; the module's entry
	moveq	#21,d0                          ; 'MODULE '
	bsr.w	print_asm_message
	tst.b	linkable_output(a6)             ; linkable output?
	beq.s	symbol_listing_module_symbols   ; no: no name
	movea.l	(sp),a0
	lea	$16(a0),a0                      ; its name
	move.b	(a0)+,d2                        ; the length
symbol_listing_module_name:
	move.b	(a0)+,d1
	bsr.w	print_char                      ; print it
	subq.b	#1,d2
	bgt.s	symbol_listing_module_name
symbol_listing_module_symbols:
	bsr.w	print_newline
	bsr.w	print_newline                   ; a blank line
	movea.l	(sp)+,a0
	lea	$10(a0),a2                      ; its local tree
	bsr.s	symbol_listing_tree             ; list it
	movem.l	(sp)+,d3/a0/a2
	rts

;------------------------------------------------------------------------------
; List the symbols of the tree whose root pointer is at a2 in name order, a4 = the routine that prints
; the section column.  Flag bit 0 marks a symbol done; imported symbols are left out.
;------------------------------------------------------------------------------
symbol_listing_tree:	; from: symbol_listing
	move.l	a2,d0                           ; no table
	beq.s	symbol_listing_done
	move.l	(a2),d0                         ; the root
	beq.s	symbol_listing_done             ; empty
	movea.l	d0,a2
	suba.l	a3,a3
	lea	listing_sentinel_name(a6),a0    ; a dummy entry's name, above every other
	moveq	#127,d0                         ; length 127
	move.b	d0,(a0)+
symbol_listing_sentinel_fill:
	st	(a0)+                           ; 128 bytes $ff
	dbra	d0,symbol_listing_sentinel_fill
symbol_listing_next:
	lea	line_code(a6),a3                ; the lowest so far: the dummy
	move.b	$17(a3),d3                      ; its first character
	bsr.s	symbol_listing_find_lowest      ; find the lowest name not listed yet
	lea	line_code(a6),a0
	cmpa.l	a3,a0                           ; still the dummy?
	beq.s	symbol_listing_done             ; yes: all listed
	bset	#$0,$c(a3)                      ; listed now
	btst	#$4,$c(a3)                      ; imported?
	bne.s	symbol_listing_next             ; yes: left out
	move.l	8(a3),d1                        ; its value
	bsr.w	print_hex_long                  ; in hex
	bsr.w	print_two_spaces
	jsr	(a4)                            ; the section column
	moveq	#0,d1
	move.b	$d(a3),d1                       ; its type
	lea	asm_symbol_type_letters(pc),a0  ; the type letters
	move.b	0(a0,d1.w),d1                   ; its letter
	bsr.w	print_char                      ; print it
	bsr.w	print_two_spaces
	lea	$16(a3),a0                      ; its name
	move.b	(a0)+,d4                        ; the length
symbol_listing_name:
	move.b	(a0)+,d1
	bsr.w	print_char                      ; print it
	subq.b	#1,d4
	bne.s	symbol_listing_name
	bsr.w	print_newline                   ; end the line
	bra.s	symbol_listing_next             ; the next one
symbol_listing_done:
	rts

;------------------------------------------------------------------------------
; Walk the tree at a2: a3 = the lowest name not listed yet below a3's, d3 = its first character.
;------------------------------------------------------------------------------
symbol_listing_find_lowest:	; from: symbol_listing_tree
	tst.l	(a2)                            ; a left branch?
	beq.s	symbol_listing_test             ; no
	move.l	a2,-(sp)
	movea.l	(a2),a2
	bsr.s	symbol_listing_find_lowest      ; walk it
	movea.l	(sp)+,a2
symbol_listing_test:
	btst	#$0,$c(a2)                      ; listed already?
	bne.s	symbol_listing_right            ; yes
	cmp.b	$17(a2),d3                      ; its first character above the best's?
	bcs.s	symbol_listing_right            ; yes
	lea	$16(a3),a0                      ; the best's name
	lea	$16(a2),a1                      ; this one's
	move.b	(a0)+,d0                        ; the best's length
	move.b	(a1)+,d1                        ; this one's
symbol_listing_compare:
	cmpm.b	(a1)+,(a0)+                     ; the best's character below?
	bcs.s	symbol_listing_right            ; yes: the best stays
	bne.s	symbol_listing_lower            ; above: this one is lower
	subq.b	#1,d0                           ; the best ended?
	beq.s	symbol_listing_right            ; yes: it stays
	subq.b	#1,d1                           ; this one ended?
	bne.s	symbol_listing_compare          ; no: on
symbol_listing_lower:
	movea.l	a2,a3                           ; the new best
	move.b	$17(a3),d3                      ; its first character
symbol_listing_right:
	tst.l	4(a2)                           ; a right branch?
	beq.s	symbol_listing_find_done        ; no
	move.l	a2,-(sp)
	movea.l	4(a2),a2
	bsr.s	symbol_listing_find_lowest      ; walk it
	movea.l	(sp)+,a2
symbol_listing_find_done:
	rts

;------------------------------------------------------------------------------
; Get d1 bytes from the heap for INCBIN data, a0 = them; out of memory is fatal.
;------------------------------------------------------------------------------
incbin_buffer_alloc:	; from: dir_incbin
	bsr.w	heap_alloc                      ; get them
	beq.s	report_out_of_memory            ; no room
	move.l	a0,incbin_buffer(a6)            ; keep it to give back
incbin_buffer_done:	; from: incbin_buffer_free
	rts

;------------------------------------------------------------------------------
; Give back the INCBIN buffer, when there is one.
;------------------------------------------------------------------------------
incbin_buffer_free:	; from: dir_incbin, free_blocks
	move.l	incbin_buffer(a6),d0
	beq.s	incbin_buffer_done              ; none
	clr.l	incbin_buffer(a6)
	movea.l	d0,a0
	bra.w	heap_free                       ; give it back

;------------------------------------------------------------------------------
; Start a new 10 K block for symbol entries.
;------------------------------------------------------------------------------
symbol_block_alloc:	; from: asm_entry, asm_new_symbol, asm_new_record
	move.l	#$2800,d1                       ; 10 K
	move.w	d1,asm_symbol_room(a6)          ; all of it free
	bsr.s	alloc_block                     ; get it
	move.l	a0,asm_symbol_free(a6)          ; the free space's start
	rts

;------------------------------------------------------------------------------
; Get d1 bytes from the heap, linked at the end of the block chain; a0 = them.  Out of memory is fatal.
;------------------------------------------------------------------------------
alloc_block:                                    ; from: macro_store_block, macro_stack_init, include_open,
                                                ;   optimisations_start_pass, optimisation_check, symbol_block_alloc, 5
                                                ;   more
	lea	block_chain(a6),a0              ; the chain
	bra.s	alloc_block_end
alloc_block_walk:
	movea.l	d0,a0
alloc_block_end:
	move.l	(a0),d0                         ; the next block
	bne.s	alloc_block_walk                ; not the last
	addq.l	#4,d1                           ; and room for the link
	move.l	a0,-(sp)
	bsr.w	heap_alloc                      ; get it
	movea.l	(sp)+,a1                        ; the last link
	beq.s	report_out_of_memory            ; no room
	move.l	a0,(a1)                         ; linked
	clr.l	(a0)+                           ; the end of the chain
	rts
report_out_of_memory:	; from: incbin_buffer_alloc
	moveq	#2,d0                           ; 'out of memory'
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Give back every block of the chain, last first, then the INCBIN buffer.
;------------------------------------------------------------------------------
free_blocks:	; from: asm_finish
	pea	incbin_buffer_free(pc)          ; and the INCBIN buffer at the end
	move.l	block_chain(a6),d0              ; the first block
	movea.l	d0,a3
	bne.s	free_block_chain
	rts                                     ; none

free_block_chain:	; from: free_blocks
	tst.l	(a3)                            ; another after it?
	beq.s	free_block_this                 ; no
	move.l	a3,-(sp)
	movea.l	(a3),a3
	bsr.s	free_block_chain                ; those first
	movea.l	(sp)+,a3
free_block_this:
	movea.l	a3,a0
	bra.w	heap_free                       ; give it back

;------------------------------------------------------------------------------
; Set the listing to its defaults at the start: off, no file, page 132 by 60, tab 8, no title, every column.
;------------------------------------------------------------------------------
listing_init:	; from: asm_entry
	sf	asm_listing_wanted(a6)          ; no listing wanted
	sf	asm_listing_active(a6)          ; none now
	clr.l	listing_handle(a6)              ; no file
	lea	listing_buffer(a6),a0           ; the buffer
	lea	listing_pointer(a6),a1
	move.l	a0,(a1)                         ; empty
	move.l	a1,listing_buffer_end(a6)       ; its end
	move.w	#$84,page_width(a6)             ; 132 columns
	move.w	#$3c,page_length(a6)            ; 60 lines
	clr.w	listing_column(a6)              ; column 0
	move.w	#$ffff,page_line(a6)            ; a page header first
	clr.w	page_number(a6)                 ; page 0
	clr.b	listing_title(a6)               ; no title
	clr.b	listing_subtitle(a6)            ; no subtitle
	st	listing_format(a6)              ; every column and the headers
	move.w	#$8,tab_width(a6)               ; tab every 8
	lea	listing_date(a6),a3             ; today's date
	bsr.w	date_time_string                ; as text
	clr.b	(a3)
	rts

;------------------------------------------------------------------------------
; At the end: finish the page, write out the buffer and close the listing file.
;------------------------------------------------------------------------------
listing_close:	; from: asm_finish
	tst.l	listing_handle(a6)              ; a listing file?
	beq.s	listing_close_done              ; no
	bsr.w	listing_page_end_now            ; end the page
	bsr.w	listing_flush                   ; write out the rest
	bsr.s	listing_close_file              ; close it
listing_close_done:	; from: listing_close_file
	rts

;------------------------------------------------------------------------------
; Close the listing file when there is one.
;------------------------------------------------------------------------------
listing_close_file:	; from: asm_finish, listing_close
	tst.l	listing_handle(a6)
	beq.s	listing_close_done              ; none
	move.l	listing_handle(a6),d3
	clr.l	listing_handle(a6)              ; none now
	bra.w	listing_close_handle            ; close it

;------------------------------------------------------------------------------
; Put character d1 into the listing buffer, writing it out when full.  A failed write is fatal.
;------------------------------------------------------------------------------
listing_put_char:	; from: dir_listchar, listing_end_line, listing_page_end_now
	movea.l	listing_pointer(a6),a0
	cmpa.l	listing_buffer_end(a6),a0       ; full?
	beq.s	listing_buffer_full             ; yes
	move.b	d1,(a0)+
	move.l	a0,listing_pointer(a6)
	rts
listing_buffer_full:
	move.w	d1,-(sp)
	bsr.s	listing_flush                   ; write it out
	bne.s	listing_write_error             ; failed
	move.w	(sp)+,d1
	bra.s	listing_put_char                ; and again
listing_write_error:
	moveq	#72,d0                          ; 'during listing output'
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Write the listing buffer to the file; NE when the write failed.
;------------------------------------------------------------------------------
listing_flush:	; from: listing_close, listing_put_char
	move.l	d3,-(sp)
	move.l	listing_handle(a6),d3           ; the handle
	lea	listing_buffer(a6),a0
	move.l	listing_pointer(a6),d1
	sub.l	a0,d1                           ; the bytes
	beq.s	listing_flush_done              ; none
	lea	listing_buffer(a6),a1
	move.l	a1,listing_pointer(a6)          ; empty again
	bsr.w	file_write                      ; Fwrite
listing_flush_done:
	movem.l	(sp)+,d3
	rts

;------------------------------------------------------------------------------
; The page header: the assembler's name, the date and the page number, the title (or the include file),
; the subtitle and a blank line.  Only when page headers are on.
;------------------------------------------------------------------------------
listing_page_header:	; from: listing_char
	btst	#$0,listing_format(a6)          ; headers?
	bne.s	listing_page_header_print       ; yes
	rts
listing_page_header_print:
	addq.w	#1,page_number(a6)              ; the next page
	moveq	#16,d0                          ; 'HiSoft GenST 680x0 Macro Assembler v2.25'
	bsr.w	print_asm_message
	lea	listing_date(a6),a0             ; the date
	bsr.w	print_string
	moveq	#15,d0                          ; '  Page '
	bsr.w	print_asm_message
	moveq	#0,d1
	move.w	page_number(a6),d1              ; its number
	move.l	d3,-(sp)
	bsr.w	print_decimal
	move.l	(sp)+,d3
	bsr.w	print_newline
	lea	listing_title(a6),a0            ; the title
	tst.b	(a0)                            ; any?
	beq.s	listing_page_header_file        ; no
	bsr.w	print_string                    ; print it
	bra.s	listing_page_header_subtitle
listing_page_header_file:
	tst.l	include_file(a6)                ; in an include file?
	beq.s	listing_page_header_subtitle    ; no
	movea.l	include_file(a6),a1
	moveq	#0,d2
	move.b	$16(a1),d2                      ; its name's length
	subq.b	#2,d2                           ; all but its last byte, less one for dbra
	lea	$17(a1),a1
listing_page_header_name:
	move.b	(a1)+,d1
	bsr.w	print_char                      ; print it
	dbra	d2,listing_page_header_name
listing_page_header_subtitle:
	bsr.w	print_newline
	lea	listing_subtitle(a6),a0         ; the subtitle
	bsr.w	print_string
	bsr.w	print_newline
	bra.w	print_newline                   ; a blank line

;------------------------------------------------------------------------------
; Character d1 into the listing: a page header at a page's top, a line wrapped at the page width, a page
; thrown after the page length.
;------------------------------------------------------------------------------
listing_char:	; from: listing_end_line, asm_output_char
	tst.w	page_line(a6)                   ; a new page?
	bpl.s	listing_char_check              ; no
	clr.w	page_line(a6)                   ; line 0
	move.w	d1,-(sp)
	bsr.w	listing_page_header             ; the header
	move.w	(sp)+,d1
listing_char_check:
	cmp.b	#$d,d1                          ; the line's end?
	bne.s	listing_char_normal             ; no

;------------------------------------------------------------------------------
; End the listing line: CR LF, or a form feed when the page is full.
;------------------------------------------------------------------------------
listing_end_line:
	clr.w	listing_column(a6)              ; column 0
	move.w	page_line(a6),d0
	addq.w	#1,page_line(a6)                ; the next line
	cmp.w	page_length(a6),d0              ; the page full?
	beq.w	listing_page_end_now            ; yes: throw it
	moveq	#13,d1
	bsr.w	listing_put_char
	moveq	#10,d1
	bsr.w	listing_put_char
	rts
listing_char_normal:	; from: listing_char
	move.w	listing_column(a6),d0
	cmp.w	page_width(a6),d0               ; at the page's width?
	blt.s	listing_char_store              ; no
	move.w	d1,-(sp)
	bsr.s	listing_end_line                ; yes: a new line first
	move.w	(sp)+,d1
	bra.s	listing_char
listing_char_store:
	bsr.w	listing_put_char
	addq.w	#1,listing_column(a6)           ; the next column
	rts

;------------------------------------------------------------------------------
; Character d1 out: to the listing while it is on, else to the screen with CR as CR LF.
;------------------------------------------------------------------------------
asm_output_char:                                ; from: print_newline, print_char, print_string, listing_source_line,
                                                ;   listing_section, exe_list_section, 2 more
	tst.b	asm_listing_active(a6)          ; listing on?
	bne.s	listing_char                    ; yes
	cmp.b	#$d,d1                          ; a CR?
	bne.s	screen_char                     ; no
	bsr.s	screen_char
	moveq	#10,d1                          ; and a LF

;------------------------------------------------------------------------------
; Character d1 to the screen.
;------------------------------------------------------------------------------
screen_char:	; from: asm_output_char
	bra.w	dos_cconout                     ; Cconout

;------------------------------------------------------------------------------
; Print the zero-ended string at a0.
;------------------------------------------------------------------------------
print_string:	; from: asm_entry, print_string_number, listing_page_header, obj_print_format, command_line
	move.b	(a0)+,d1
	beq.s	print_string_done               ; the end
	move.l	a0,-(sp)
	bsr.s	asm_output_char                 ; print it
	movea.l	(sp)+,a0
	bra.s	print_string
print_string_done:
	rts

;------------------------------------------------------------------------------
; List one source line: the line number, the section and address (or a value), '+' for a macro line,
; the code bytes and the source with tabs expanded; each column only when the listing flags say so.
;------------------------------------------------------------------------------
listing_source_line:	; from: asm_list_line
	movem.l	d7/a3,-(sp)
	move.b	listing_format(a6),d7           ; the listing flags
	add.b	d7,d7                           ; bit 7: line numbers?
	bcc.s	listing_address                 ; no
	move.w	line_number(a6),d2              ; the line number
	cmp.w	#$2710,d2                       ; 5 digits?
	bcc.s	listing_line_number             ; yes
	bsr.w	print_space                     ; no: pad
	cmp.w	#$3e8,d2                        ; 4 digits?
	bcc.s	listing_line_number
	bsr.w	print_space
	cmp.w	#$64,d2                         ; 3?
	bcc.s	listing_line_number
	bsr.w	print_space
	cmp.w	#$a,d2                          ; 2?
	bcc.s	listing_line_number
	bsr.w	print_space
listing_line_number:
	moveq	#0,d1
	move.w	d2,d1
	bsr.w	print_decimal                   ; the number
	bsr.w	print_space
listing_address:
	move.l	line_code_size(a6),d4           ; the line's code bytes
	add.b	d7,d7                           ; bit 6: addresses?
	bcc.s	listing_macro_mark              ; no
	move.b	current_section(a6),d0          ; the section
	move.b	asm_list_marker(a6),d1          ; a value to show instead?
	beq.s	listing_section_address         ; no: the address
	cmp.b	#$ff,d1                         ; with the section?
	beq.s	listing_value_section           ; yes
	bsr.w	print_two_spaces
	move.b	asm_list_marker(a6),d1          ; the mark ('=' for an equate)
	bsr.w	asm_output_char
listing_value_out:
	move.l	listing_value(a6),d1            ; the value
	bsr.w	print_hex_long                  ; in hex
	moveq	#0,d4                           ; no code bytes
	bra.s	listing_macro_mark
listing_value_section:
	bsr.w	listing_section                 ; the section column
	bra.s	listing_value_out
listing_section_address:
	bsr.w	listing_section                 ; the section column
	move.l	line_code_size(a6),d4           ; the line's code bytes
	movea.l	line_code_start(a6),a3          ; their start
	move.l	program_counter(a6),d1
	sub.l	d4,d1                           ; the line's address
	bsr.w	print_hex_long                  ; in hex
listing_macro_mark:
	moveq	#32,d1
	tst.b	in_macro(a6)                    ; a macro line?
	beq.s	listing_macro_mark_out          ; no
	tst.b	asm_nested_macro_line(a6)       ; a repeat line?
	bne.s	listing_macro_mark_out          ; yes: no mark
	moveq	#43,d1                          ; '+'
listing_macro_mark_out:
	bsr.w	asm_output_char
	add.b	d7,d7                           ; bit 5: code bytes?
	bcc.s	listing_text                    ; no
	moveq	#5,d3                           ; 6 bytes
	cmpi.w	#$51,page_width(a6)             ; 81 columns or more?
	bcs.s	listing_code_bytes              ; no
	moveq	#9,d3                           ; 10 bytes
listing_code_bytes:
	tst.l	d4                              ; any?
listing_code_loop:
	beq.s	listing_code_pad                ; no more: pad
	move.b	(a3)+,d1
	bsr.w	print_hex_byte                  ; in hex
	subq.l	#1,d4
	dbra	d3,listing_code_loop
	bra.s	listing_text
listing_code_pad:
	bsr.w	print_two_spaces                ; 2 spaces a byte
	dbra	d3,listing_code_pad
listing_text:
	bsr.w	print_space
	movea.l	asm_line_start(a6),a3           ; the source line
	moveq	#0,d2                           ; column 0
listing_text_loop:
	move.b	(a3)+,d1
	cmp.b	#$d,d1                          ; the end?
	beq.s	listing_text_done               ; yes
	cmp.b	#$9,d1                          ; a tab?
	bne.s	listing_text_char               ; no
	moveq	#0,d0
	move.w	d2,d0
	divu.w	tab_width(a6),d0                ; the column in the tab
	swap	d0
	sub.w	tab_width(a6),d0
	neg.w	d0                              ; spaces to the next tab
listing_text_tab:
	bsr.w	print_space
	addq.w	#1,d2
	subq.w	#1,d0
	bne.s	listing_text_tab
	bra.s	listing_text_loop
listing_text_char:
	addq.w	#1,d2
	bsr.w	print_char                      ; print it
	bra.s	listing_text_loop
listing_text_done:
	bsr.w	asm_output_char                 ; the CR
	movem.l	(sp)+,d7/a3
	rts

;------------------------------------------------------------------------------
; The assembler's messages, numbered from 0 (print_asm_message).
;------------------------------------------------------------------------------
msg_assembler:	; from: print_asm_message
	dc.b	'GenST Macro Assembler Copyright ' ; 0: the sign-on
	dc.b	$bd                             ; the copyright sign
	dc.b	' HiSoft 1985-91',13,'All Rights Reserved - version 2.25',13,13,0
	dc.b	'Pass 1',13,0                   ; 1
	dc.b	'Pass 2',13,0                   ; 2
	dc.b	' errors found',13,0            ; 3
	dc.b	' error found',13,0             ; 4
	dc.b	' lines assembled into ',0      ; 5
	dc.b	'Error ',0                      ; 6
	dc.b	'Locals:',13,0                  ; 7
	dc.b	'Warning ',0                    ; 8
	dc.b	' at line ',0                   ; 9
	dc.b	'Could not open file ',0        ; 10
	dc.b	' in file ',0                   ; 11
	dc.b	' bytes, ',0                    ; 12
	dc.b	' optimisations saving ',0      ; 13
	dc.b	' bytes',13,0                   ; 14
	dc.b	'  Page ',0                     ; 15
	dc.b	'HiSoft GenST 680x0 Macro Assembler v2.25   ',0 ; 16: the listing's page header
	dc.b	' relocatable',0                ; 17
	dc.b	' position-independent',0       ; 18
	dc.b	' code',13,0                    ; 19
	dc.b	13,9,'GLOBAL SYMBOLS',13,13,0   ; 20
	dc.b	13,9,'MODULE ',0                ; 21
	dc.b	' absolute',0                   ; 22
	dc.b	$00

;------------------------------------------------------------------------------
; The output-format dispatch: the routine for executable output (OPT L-), GST linkable (L+ or L1) or DRI
; linkable (L2) by the linkable flag and the linker format word.  This one prints the format's name.
;------------------------------------------------------------------------------
obj_print_format:	; from: asm_finish
	pea	print_string(pc)                ; print what it gives
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_format_name                 ; no: executable
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_format_name                 ; yes
	bra.w	dri_format_name                 ; DRI

;------------------------------------------------------------------------------
; a0 = the binary file's default extension for the output format.
;------------------------------------------------------------------------------
obj_extension:	; from: create_output_file
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_extension                   ; no: .PRG
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_extension                   ; yes: .BIN
	bra.w	dri_extension                   ; DRI

;------------------------------------------------------------------------------
; Copy the zero-ended name at a0 to a1, a1 left at its end (the same for each format).
;------------------------------------------------------------------------------
obj_copy_name:	; from: select_named_section
	tst.b	linkable_output(a6)
	beq.w	copy_string
	tst.w	linker_format(a6)
	beq.w	copy_string
	bra.w	copy_string

;------------------------------------------------------------------------------
; At the end of pass 1: set up the output buffers for pass 2.
;------------------------------------------------------------------------------
obj_buffers_init:	; from: asm_end_pass_one
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_buffers_init                ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_start                       ; yes
	bra.w	dri_start                       ; DRI
report_executable_only:	; from: gst_start, dri_start
	moveq	#64,d0                          ; 'executable code only'
	bra.w	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; A MODULE: a1 = its entry.  Only with binary output; nothing for executable and DRI.
;------------------------------------------------------------------------------
obj_module_start:	; from: select_module
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	obj_module_done                 ; no
	movea.l	current_module(a6),a1           ; the module's entry
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_nothing                     ; no: nothing
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_module_start                ; yes
	bra.w	output_nothing                  ; DRI
obj_module_done:	; from: obj_module_end
	rts

;------------------------------------------------------------------------------
; The end of a module in pass 2.  Only with binary output.
;------------------------------------------------------------------------------
obj_module_end:	; from: end_module_output
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	obj_module_done                 ; no
	movea.l	current_module(a6),a1           ; the module's entry
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_nothing                     ; no: nothing
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_module_end                  ; yes
	bra.w	output_nothing                  ; DRI

;------------------------------------------------------------------------------
; An XDEF of the symbol at a1, the first time in pass 2.  Only with binary output.
;------------------------------------------------------------------------------
obj_export:	; from: xdef_symbol
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	obj_dispatch_done               ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xdef                        ; yes
	bra.w	output_nothing                  ; DRI: nothing
obj_dispatch_done:	; from: obj_comment, obj_emit
	rts

;------------------------------------------------------------------------------
; A COMMENT in pass 2: a1 = its text, d2 = the length.  Executable: HEAD= sets the header flags; GST: a
; comment record; DRI: PASCAL selects the OSS form.
;------------------------------------------------------------------------------
obj_comment:	; from: asm_comment
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	obj_dispatch_done               ; no
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_comment                     ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_comment                     ; yes
	bra.w	dri_comment                     ; DRI

;------------------------------------------------------------------------------
; The start of an instruction in pass 2 with linkable output (GST starts the line's relocation list).
;------------------------------------------------------------------------------
obj_line_start:	; from: find_mnemonic
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_nothing                     ; no: nothing
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_line_start                  ; yes
	bra.w	output_nothing                  ; DRI: nothing

;------------------------------------------------------------------------------
; The d1 bytes from the line's code pointer are done, at address d2: pass them to the output.  In an
; OFFSET section an error.  Out: the code pointer moved past them.
;------------------------------------------------------------------------------
obj_emit:	; from: data_fill_flush, line_end_check, asm_pad_even
	tst.b	offset_section(a6)              ; an OFFSET section?
	bne.s	obj_emit_offset_error           ; yes: error
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	obj_dispatch_done               ; no
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_emit                        ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_code                        ; yes
	bra.w	dri_code                        ; DRI
obj_emit_offset_error:
	moveq	#37,d0                          ; 'BSS or OFFSET section cannot contain data'
	bra.w	asm_error

;------------------------------------------------------------------------------
; Z set when the current section takes no data (OFFSET, or BSS for executable and DRI).
;------------------------------------------------------------------------------
obj_no_data:	; from: data_fill, asm_pad_even
	cmpi.b	#$ff,offset_section(a6)         ; an OFFSET section?
	beq.s	obj_no_data_done                ; yes: Z set
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_no_data                     ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_data_allowed                ; yes
	bra.w	exe_no_data                     ; DRI
obj_no_data_done:
	rts

;------------------------------------------------------------------------------
; INCBIN in pass 2: put the d1 bytes at a0 into the output at address d2.
;------------------------------------------------------------------------------
obj_incbin:	; from: dir_incbin
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_incbin                      ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_incbin                      ; yes
	bra.w	dri_incbin                      ; DRI

;------------------------------------------------------------------------------
; The listing's section column: 'O' in an OFFSET section, else T, D or B (GST: its section number).
;------------------------------------------------------------------------------
listing_section:	; from: listing_source_line
	tst.b	offset_section(a6)              ; an OFFSET section?
	bne.s	listing_section_offset          ; yes
listing_section_letter:	; from: symbol_listing
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_list_section                ; no: the letter
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_list_section                ; yes: the number
	bra.w	exe_list_section                ; DRI: the letter
listing_section_offset:
	moveq	#79,d1                          ; 'O'
	bsr.w	asm_output_char
	bra.w	print_two_spaces
err_cannot_create:	; from: binary_create
	moveq	#39,d0                          ; 'cannot create binary file'
	jmp	asm_fatal_error                 ; fatal

;------------------------------------------------------------------------------
; Create the binary file the first time output needs it (its name, or the source's with the format's
; extension).  When assembling to memory it means the memory is full.  Failure is fatal.
;------------------------------------------------------------------------------
binary_create:	; from: exe_incbin, exe_emit, exe_finish, gst_flush, dri_finish
	tst.l	program_buffer(a6)              ; to memory?
	bne.w	report_program_buffer_full      ; yes: the buffer is full
	tst.l	binary_handle(a6)               ; created already?
	bne.s	binary_create_done              ; yes
	movem.l	d1-d2/a0-a2,-(sp)
	lea	asm_output_name(a6),a0          ; the output name
	bsr.w	create_output_file              ; Fcreate
	bne.s	err_cannot_create               ; failed
	move.l	d2,binary_handle(a6)            ; the handle
	movem.l	(sp)+,d1-d2/a0-a2
binary_create_done:
	rts

;------------------------------------------------------------------------------
; Put a 0 byte to make the address even; in pass 2 it goes to the output unless the section takes no data.
;------------------------------------------------------------------------------
asm_pad_even:	; from: asm_define_label, asm_define_code_label
	move.l	program_counter(a6),d2          ; the address
	moveq	#1,d1                           ; one byte
	clr.b	(a5)+                           ; a 0
	add.l	d1,program_counter(a6)          ; the address on
	add.l	d1,asm_code_size(a6)            ; and the size
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	asm_pad_even_done               ; no
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	asm_pad_even_done               ; no
	bsr.w	obj_no_data                     ; data wanted?
	beq.s	asm_pad_even_done               ; no
	bsr.w	obj_emit                        ; out
asm_pad_even_done:
	movea.l	code_buffer_ptr(a6),a5          ; the next code
	move.l	a5,line_code_start(a6)          ; and the line's code start
	rts

;------------------------------------------------------------------------------
; Leave the current section (a section change): its code pointer is kept for when it comes back, and the
; line shows no code bytes.
;------------------------------------------------------------------------------
obj_section_leave:	; from: save_section_pc
	lea	listing_no_code(pc),a0          ; after the line
	move.l	a0,line_end_hook(a6)
	move.l	code_buffer_ptr(a6),d1          ; the code pointer
	tst.b	offset_section(a6)              ; an OFFSET section?
	bne.s	obj_section_leave_done          ; yes: nothing kept
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_section_leave               ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_section_leave               ; yes
	bra.w	exe_section_leave               ; DRI

;------------------------------------------------------------------------------
; The routine run after a line that shows no code bytes in the listing.
;------------------------------------------------------------------------------
listing_no_code:	; from: dir_org, directive_rept, obj_section_leave
	clr.l	line_code_size(a6)              ; none
obj_section_leave_done:	; from: obj_section_leave
	rts

;------------------------------------------------------------------------------
; Enter the section just selected: pass 1 notes the size so far, pass 2 takes back its code pointer.
;------------------------------------------------------------------------------
obj_section_enter:	; from: assign_section_number
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_section_enter               ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_section_enter               ; yes
	bra.w	exe_section_enter               ; DRI

;------------------------------------------------------------------------------
; The end of pass 2: write out the rest of the output and finish the file (header, relocation, symbols).
;------------------------------------------------------------------------------
obj_finish:	; from: asm_entry
	tst.b	binary_on(a6)                   ; binary output?
	beq.s	obj_finish_done                 ; no
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_finish                      ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_finish                      ; yes
	bra.w	dri_finish                      ; DRI
obj_finish_done:
	rts

;------------------------------------------------------------------------------
; Close the binary file when it is open.
;------------------------------------------------------------------------------
binary_close:	; from: asm_finish, binary_write
	move.l	binary_handle(a6),d2
	beq.s	binary_close_done               ; not open
	bsr.w	close_source_file               ; Fclose
	clr.l	binary_handle(a6)               ; closed
binary_close_done:
	rts

;------------------------------------------------------------------------------
; Write d1 bytes of filler (whatever is at a6 on) to the binary file in pieces of $62fc bytes at most:
; it makes the file long enough to seek to a later position.  d2 kept.
;------------------------------------------------------------------------------
binary_fill:	; from: exe_flush_buffer
	move.l	d2,-(sp)
binary_fill_loop:
	move.l	#$62fc,d0                       ; a piece
	sub.l	d0,d1
	bcc.s	binary_fill_write               ; at least that left
	add.l	d1,d0                           ; no: the rest
	moveq	#0,d1                           ; and nothing after it
binary_fill_write:
	movea.l	a6,a0                           ; the filler
	move.l	d1,-(sp)
	move.l	d0,d1
	bsr.w	binary_write                    ; write it
	move.l	(sp)+,d1
	bne.s	binary_fill_loop                ; more?
	move.l	(sp)+,d2
	rts

;------------------------------------------------------------------------------
; References to imported symbols, by size, for the linkable formats (d2 = the value, d3 = the type): this
; one a PC-relative byte (a short branch).
;------------------------------------------------------------------------------
obj_xref_pcrel_byte:	; from: emit_immediate_byte, asm_bcc
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_branch_short           ; yes
	bra.w	dri_restriction                 ; DRI

;------------------------------------------------------------------------------
; A PC-relative word that refers to an imported symbol.
;------------------------------------------------------------------------------
obj_xref_pcrel_word:	; from: emit_immediate_byte, asm_bcc_word
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_branch                 ; yes
	bra.w	dri_xref_branch                 ; DRI

;------------------------------------------------------------------------------
; A long that refers to an imported symbol.
;------------------------------------------------------------------------------
obj_xref_long:	; from: ea_parse, emit_immediate_long
	tst.b	asm_absolute_code(a6)           ; absolute code (ORG)?
	beq.s	obj_xref_long_record            ; no
	tst.w	linker_format(a6)               ; DRI?
	bne.s	obj_xref_long_done              ; yes: nothing
obj_xref_long_record:
	cmp.b	#$1,d3                          ; relocatable too?
	bne.s	obj_xref_long_format            ; no
	st	asm_relocated(a6)               ; the code is relocatable
obj_xref_long_format:
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_long                   ; yes
	bra.w	dri_xref_long                   ; DRI
obj_xref_long_done:
	rts

;------------------------------------------------------------------------------
; A signed word (a displacement or short address) that refers to an imported symbol.
;------------------------------------------------------------------------------
obj_xref_disp_word:	; from: ea_parse, emit_immediate_byte
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_word_signed            ; yes
	bra.w	dri_xref_word                   ; DRI

;------------------------------------------------------------------------------
; A word (DC.W) that refers to an imported symbol.
;------------------------------------------------------------------------------
obj_xref_word:	; from: emit_immediate_word
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_word                   ; yes
	bra.w	dri_xref_word                   ; DRI

;------------------------------------------------------------------------------
; A signed byte (an index displacement) that refers to an imported symbol.
;------------------------------------------------------------------------------
obj_xref_disp_byte:	; from: emit_immediate_byte
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_byte_signed            ; yes
	bra.w	dri_restriction                 ; DRI

;------------------------------------------------------------------------------
; A byte (DC.B) that refers to an imported symbol.
;------------------------------------------------------------------------------
obj_xref_byte:	; from: emit_immediate_byte, data_next_item, ins_moveq
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_xref_byte                   ; yes
	bra.w	dri_restriction                 ; DRI

;------------------------------------------------------------------------------
; A relocatable long is going in at a5: record it for the output's relocation.  OPT P+ makes it an
; error; absolute code (ORG) needs none.
;------------------------------------------------------------------------------
obj_relocation:	; from: ea_parse, emit_immediate_long
	tst.b	asm_position_independent(a6)    ; OPT P+?
	beq.s	obj_relocation_check            ; no
err_relocation_not_allowed:	; from: exe_relocate_long
	moveq	#58,d0                          ; 'relocation not allowed'
	bra.w	asm_error
obj_relocation_check:
	tst.b	asm_absolute_code(a6)           ; absolute code?
	bne.s	obj_relocation_done             ; yes: nothing
	movem.l	d1-d2,-(sp)
	st	asm_relocated(a6)               ; the code is relocatable
	move.l	a5,d0                           ; the long's address
	sub.l	code_buffer_ptr(a6),d0
	add.l	program_counter(a6),d0
	pea	obj_relocation_restore(pc)      ; back here after it
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_relocate_long               ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_relocate_long               ; yes
	bra.w	dri_relocate_long               ; DRI
obj_relocation_restore:
	movem.l	(sp)+,d1-d2
obj_relocation_done:
	rts

;------------------------------------------------------------------------------
; ORG to address d2: d0 = the section, d1 = the change of address.  Out: NE when not allowed here.
;------------------------------------------------------------------------------
obj_org:	; from: dir_org
	moveq	#0,d0
	move.b	current_section(a6),d0          ; the section
	move.l	d2,d1
	sub.l	program_counter(a6),d1          ; the change
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	exe_org                         ; no
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_org                         ; yes
	bra.w	dri_org                         ; DRI: not allowed

;------------------------------------------------------------------------------
; RORG to address d2: d0 = the section, d1 = the address; executable and DRI pad with zeros up to it.
; Out: NE when it lies behind.
;------------------------------------------------------------------------------
obj_rorg:	; from: dir_rorg
	moveq	#0,d0
	move.b	current_section(a6),d0          ; the section
	move.l	program_counter(a6),d1          ; the address
	tst.b	linkable_output(a6)             ; linkable?
	beq.w	org_pad_to                      ; no: pad
	tst.w	linker_format(a6)               ; GST?
	beq.w	gst_rorg                        ; yes
	bra.w	org_pad_to                      ; DRI: pad

;------------------------------------------------------------------------------
; Executable output: nothing to do.
;------------------------------------------------------------------------------
exe_nothing:	; from: obj_module_start, obj_module_end, obj_line_start
	rts

;------------------------------------------------------------------------------
; Executable COMMENT: "HEAD=<expression>" at a1 sets the program header's flags long.
;------------------------------------------------------------------------------
exe_comment:	; from: obj_comment
	lea	exe_head_keyword(pc),a0
	cmpm.b	(a0)+,(a1)+                     ; 'HEAD='?
	bne.s	exe_comment_done                ; no
	cmpm.b	(a0)+,(a1)+
	bne.s	exe_comment_done
	cmpm.b	(a0)+,(a1)+
	bne.s	exe_comment_done
	cmpm.b	(a0)+,(a1)+
	bne.s	exe_comment_done
	cmpm.b	(a0)+,(a1)+
	bne.s	exe_comment_done
	move.l	a4,-(sp)
	movea.l	a1,a4                           ; after it
	move.b	(a4)+,d1
	bsr.w	evaluate_absolute               ; its value
	move.l	d2,header_flags(a6)             ; the header flags
	movea.l	(sp)+,a4
exe_comment_done:
	rts
exe_head_keyword:
	dc.b	'HEAD=',0                       ; the COMMENT keyword

;------------------------------------------------------------------------------
; Executable at the end of pass 1: a buffer for the text and one for the data, each the section's size
; (plus a margin) when that fits in half the free memory, else $1200 bytes.  The text goes into the file
; at 28 (after the header), the data after the text.
;------------------------------------------------------------------------------
exe_buffers_init:	; from: obj_buffers_init
	tst.l	program_buffer(a6)              ; to memory?
	bne.s	exe_buffers_memory              ; yes
	move.l	#$104,d1                        ; the text, and room for a line
	add.l	text_size(a6),d1
	move.l	#$1200,d2                       ; else $1200 bytes
	bsr.w	buffer_size
	move.l	d1,exe_text_buffer_size(a6)     ; the text buffer's size
	move.l	d1,text_buffer_limit(a6)        ; and limit
	bsr.w	alloc_block                     ; get it
	move.l	a0,exe_text_buffer(a6)          ; the text buffer
	move.l	a0,exe_text_pointer(a6)         ; its code pointer
	move.l	a0,code_buffer_ptr(a6)          ; the code pointer
	move.l	#$82,d1                         ; the data, and room for a line
	add.l	data_size(a6),d1
	move.l	#$1200,d2                       ; else $1200 bytes
	bsr.w	buffer_size
	move.l	d1,data_buffer_size(a6)         ; the data buffer's size
	move.l	d1,data_buffer_limit(a6)        ; and limit
	bsr.w	alloc_block                     ; get it
	move.l	a0,data_buffer(a6)              ; the data buffer
	move.l	a0,exe_data_pointer(a6)         ; its code pointer
	moveq	#0,d0
	move.l	d0,binary_length(a6)            ; nothing written yet
	moveq	#28,d0                          ; the text after the header
	move.l	d0,text_file_position(a6)
	add.l	text_size(a6),d0                ; the data after the text
	move.l	d0,data_file_position(a6)
	clr.l	header_flags(a6)                ; no header flags
	rts
exe_buffers_memory:
	moveq	#28,d1                          ; to memory: the text after the header
	add.l	program_buffer(a6),d1
	move.l	d1,exe_text_buffer(a6)
	move.l	d1,exe_text_pointer(a6)
	move.l	d1,code_buffer_ptr(a6)          ; the code pointer
	move.l	text_size(a6),d2                ; the text size
	move.l	d1,exe_text_buffer_size(a6)
	move.l	d1,text_buffer_limit(a6)
	add.l	d2,d1                           ; the data after the text
	move.l	data_size(a6),data_buffer_size(a6)
	move.l	data_size(a6),data_buffer_limit(a6)
	move.l	d1,data_buffer(a6)
	move.l	d1,exe_data_pointer(a6)
	moveq	#28,d1                          ; header, text and data
	add.l	text_size(a6),d1
	add.l	data_size(a6),d1
	cmp.l	program_buffer_end(a6),d1       ; fit in the memory?
	bcc.w	report_program_buffer_full      ; no
	movea.l	program_buffer(a6),a1           ; the header
	clr.w	(a1)+                           ; the magic word, put in at the end
	move.l	text_size(a6),(a1)+             ; the text size
	move.l	data_size(a6),(a1)+             ; the data size
	move.l	bss_size(a6),(a1)+              ; the BSS size
	clr.l	(a1)+                           ; no symbols
	clr.b	(a1)+
	rts

;------------------------------------------------------------------------------
; Z set when the section is the BSS.
;------------------------------------------------------------------------------
exe_no_data:	; from: obj_no_data
	cmpi.b	#$18,current_section(a6)        ; BSS?
	rts

;------------------------------------------------------------------------------
; Executable INCBIN: d1 bytes at a0 at address d2.  When they fit they are copied to the section's buffer;
; else the buffer is written out and the bytes go straight to the file.
;------------------------------------------------------------------------------
exe_incbin:	; from: obj_incbin
	move.b	current_section(a6),d0          ; the section
	beq.s	exe_incbin_text                 ; text
	cmp.b	#$c,d0                          ; data?
	bne.w	report_bss_data                 ; no: BSS cannot have data
	move.l	d2,d0
	add.l	d1,d0                           ; the end address
	cmp.l	data_buffer_limit(a6),d0        ; within the data buffer?
	ble.s	exe_incbin_copy                 ; yes: copy them
	movem.l	d1-d2/a0,-(sp)
	bsr.w	binary_create                   ; the binary file
	lea	data_buffer(a6),a1              ; the data buffer
	move.l	data_file_position(a6),d1       ; at the data's file position
	bsr.w	exe_flush_buffer                ; write it out
	movem.l	(sp)+,d1-d2/a0
	add.l	d1,d0                           ; the file position after the bytes
	cmp.l	binary_length(a6),d0            ; the file longer?
	ble.s	exe_incbin_data_position        ; no
	move.l	d0,binary_length(a6)            ; its length
exe_incbin_data_position:
	add.l	d1,data_file_position(a6)       ; the data's file position past them
	bra.s	exe_incbin_write
exe_incbin_text:
	move.l	d2,d0
	add.l	d1,d0                           ; the end address
	cmp.l	text_buffer_limit(a6),d0        ; within the text buffer?
	bgt.s	exe_incbin_text_flush           ; no
exe_incbin_copy:
	add.l	d1,code_buffer_ptr(a6)          ; the code pointer past them
exe_incbin_copy_loop:
	move.b	(a0)+,(a5)+                     ; copy them
	subq.l	#1,d1
	bne.s	exe_incbin_copy_loop
	rts
exe_incbin_text_flush:
	movem.l	d1-d2/a0,-(sp)
	bsr.w	binary_create                   ; the binary file
	lea	exe_text_buffer(a6),a1          ; the text buffer
	move.l	text_file_position(a6),d1       ; at the text's file position
	bsr.w	exe_flush_buffer                ; write it out
	movem.l	(sp)+,d1-d2/a0
	add.l	d1,d0                           ; the file position after the bytes
	cmp.l	binary_length(a6),d0            ; the file longer?
	ble.s	exe_incbin_text_position        ; no
	move.l	d0,binary_length(a6)            ; its length
exe_incbin_text_position:
	add.l	d1,text_file_position(a6)       ; the text's file position past them
exe_incbin_write:
	btst	#$0,d0                          ; an odd end?
	beq.s	exe_incbin_write_file           ; no
	addq.l	#1,code_buffer_ptr(a6)          ; yes: the buffer starts a byte in, words stay even
exe_incbin_write_file:
	bra.w	binary_write                    ; the bytes to the file

;------------------------------------------------------------------------------
; Executable: d1 bytes at address d2 are in the section's buffer.  Once within 256 bytes of its limit the
; buffer is written out (from disk assembly) and the limit moves on.
;------------------------------------------------------------------------------
exe_emit:	; from: obj_emit
	moveq	#0,d0
	move.b	current_section(a6),d0          ; the section
	beq.s	exe_emit_text                   ; text
	cmp.b	#$c,d0                          ; data?
	beq.s	exe_emit_data                   ; yes
	bra.w	report_bss_data                 ; BSS cannot have data
exe_emit_text:
	move.l	d2,d0
	addi.l	#$100,d0                        ; and room for a line
	cmp.l	text_buffer_limit(a6),d0        ; within the text buffer?
	bcc.s	exe_emit_text_flush             ; no
exe_emit_text_room:
	add.l	d1,code_buffer_ptr(a6)          ; the code pointer past them
	rts
exe_emit_text_flush:
	tst.l	program_buffer(a6)              ; to memory?
	bne.s	exe_emit_text_room              ; yes: no limit
	bsr.w	binary_create                   ; the binary file
	lea	exe_text_buffer(a6),a1          ; the text buffer
	move.l	text_file_position(a6),d1       ; at the text's file position
	bsr.s	exe_flush_even                  ; write it out
	add.l	d1,text_buffer_limit(a6)        ; the limit moves on
	rts
exe_emit_data:
	move.l	d2,d0
	addi.l	#$100,d0                        ; and room for a line
	cmp.l	data_buffer_limit(a6),d0        ; within the data buffer?
	bcc.s	exe_emit_data_flush             ; no
exe_emit_data_room:
	add.l	d1,code_buffer_ptr(a6)          ; the code pointer past them
	rts
exe_emit_data_flush:
	tst.l	program_buffer(a6)              ; to memory?
	bne.s	exe_emit_data_room              ; yes: no limit
	bsr.w	binary_create                   ; the binary file
	lea	data_buffer(a6),a1              ; the data buffer
	move.l	data_file_position(a6),d1       ; at the data's file position
	bsr.s	exe_flush_even                  ; write it out
	add.l	d1,data_buffer_limit(a6)        ; the limit moves on
	rts

;------------------------------------------------------------------------------
; Executable output: write a section buffer to the file, keeping the writes an even length.  An odd last byte
; is held back and put at the start of the emptied buffer.  a1 = the section's buffer record, d1 = its file
; offset, a5 = the end of the bytes in the buffer.
;------------------------------------------------------------------------------
exe_flush_even:	; from: exe_emit
	move.l	a5,d0                           ; odd end?
	andi.b	#$1,d0
	beq.s	exe_flush_buffer                ; no: write it all
	move.b	-(a5),-(sp)                     ; yes: keep the last byte
	bsr.s	exe_flush_buffer                ; write the rest
	movea.l	code_buffer_ptr(a6),a0          ; the emptied buffer
	move.b	(sp)+,(a0)+                     ; the held byte goes first
	move.l	a0,code_buffer_ptr(a6)          ; the new write pointer
	rts

;------------------------------------------------------------------------------
; Write a section buffer (record a1: +0 buffer, +$10 file offset) from its start to a5 at file offset d1.
; A gap past the file's end is filled first; the buffer is emptied (code pointer back to its start) and
; the file length kept.  Assembling to memory the buffer cannot be flushed: program buffer full.
;------------------------------------------------------------------------------
exe_flush_buffer:	; from: exe_incbin, exe_flush_even, exe_finish
	tst.l	program_buffer(a6)              ; assembling to memory?
	bne.w	report_program_buffer_full      ; yes: program buffer full
	move.l	a1,-(sp)                        ; keep the record
	cmp.l	binary_length(a6),d1            ; past the file's end?
	ble.s	exe_flush_buffer_seek           ; no
	move.l	d1,-(sp)
	sub.l	binary_length(a6),d1            ; the gap
	add.l	d1,binary_length(a6)            ; the file grows by it
	bsr.w	binary_fill                     ; fill it with any bytes
	move.l	(sp)+,d1
exe_flush_buffer_seek:
	movea.l	(sp),a1                         ; the record
	move.l	d1,$10(a1)                      ; its file offset
	move.l	d1,d2
	bsr.w	output_seek                     ; Fseek there
	movea.l	(sp)+,a1
	movea.l	(a1),a0                         ; the buffer's start
	move.l	a5,d1                           ; the bytes' end
	move.l	a0,code_buffer_ptr(a6)          ; the code pointer back to the start
	sub.l	a0,d1                           ; the byte count
	add.l	d1,$10(a1)                      ; the file offset after them
	move.l	$10(a1),-(sp)
	move.l	d1,-(sp)
	bsr.w	binary_write                    ; write them
	move.l	(sp)+,d1
	move.l	(sp)+,d0                        ; the end of the bytes written
	cmp.l	binary_length(a6),d0            ; past the file's end?
	ble.s	exe_flush_buffer_done           ; no
	move.l	d0,binary_length(a6)            ; yes: the new file length
exe_flush_buffer_done:
	rts

;------------------------------------------------------------------------------
; Pass 1, leaving a section: add the bytes made in it to its size; the next section's base is this PC.
;------------------------------------------------------------------------------
exe_section_leave_pass1:	; from: exe_section_leave
	lea	asm_section_table(a6),a0        ; the section table
	moveq	#0,d0
	move.b	current_section(a6),d0          ; the section's offset in it (0, 12 or 24)
	move.l	asm_code_size(a6),d2            ; the bytes made so far
	sub.l	section_start_bytes(a6),d2      ; less those at the section's start
	add.l	d2,4(a0,d0.w)                   ; added to its size
	move.l	program_counter(a6),$c(a0,d0.w) ; the next section's base
	rts

;------------------------------------------------------------------------------
; Executable output, leaving a section (d1 = the code pointer): pass 2 keeps the code pointer of the text or
; data section for when it is entered again.
;------------------------------------------------------------------------------
exe_section_leave:	; from: obj_section_leave
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	exe_section_leave_pass1         ; no
	move.b	current_section(a6),d0          ; the section
	beq.s	exe_section_leave_text          ; text
	cmp.b	#$c,d0                          ; data?
	beq.s	exe_section_leave_data          ; yes
	rts                                     ; the BSS keeps none
exe_section_leave_text:
	move.l	d1,exe_text_pointer(a6)         ; the text's code pointer
	rts
exe_section_leave_data:
	move.l	d1,exe_data_pointer(a6)         ; the data's code pointer
	rts

;------------------------------------------------------------------------------
; Pass 1, entering a section: note the byte count at its start.
;------------------------------------------------------------------------------
exe_section_enter_pass1:	; from: exe_section_enter
	move.l	asm_code_size(a6),section_start_bytes(a6)
	rts

;------------------------------------------------------------------------------
; Executable output, entering a section: pass 2 takes back the code pointer kept for the text or data.
;------------------------------------------------------------------------------
exe_section_enter:	; from: obj_section_enter
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	exe_section_enter_pass1         ; no
	move.b	current_section(a6),d0          ; the section
	beq.s	exe_section_enter_text          ; text
	cmp.b	#$c,d0                          ; data?
	beq.s	exe_section_enter_data          ; yes
	rts                                     ; the BSS: no change
exe_section_enter_text:
	move.l	exe_text_pointer(a6),code_buffer_ptr(a6) ; the text's code pointer
	rts
exe_section_enter_data:
	move.l	exe_data_pointer(a6),code_buffer_ptr(a6) ; the data's code pointer
	rts

;------------------------------------------------------------------------------
; End of the assembly, executable output: write the rest of the text and data, pad the file even, then the
; symbol table (when debug is on), the relocation table and last the header at the file's start.  Assembling
; to memory the symbols and relocation go after the image in the program buffer instead.
;------------------------------------------------------------------------------
exe_finish:	; from: obj_finish
	tst.l	program_buffer(a6)              ; assembling to memory?
	bne.w	exe_finish_memory               ; yes: finish it there
	bsr.w	binary_create                   ; open the output file
	lea	exe_text_buffer(a6),a1          ; the text buffer
	move.l	text_file_position(a6),d1       ; its file offset
	movea.l	exe_text_pointer(a6),a5         ; its code pointer
	bsr.w	exe_flush_buffer                ; write it
	lea	data_buffer(a6),a1              ; the data buffer
	move.l	data_file_position(a6),d1
	movea.l	exe_data_pointer(a6),a5
	bsr.w	exe_flush_buffer                ; write it
	btst	#$0,exe_file_length_low(a6)     ; the file's length odd?
	beq.s	exe_finish_symbols              ; no
	moveq	#1,d1                           ; yes: one zero byte
	lea	line_code(a6),a0
	clr.b	(a0)
	bsr.w	binary_write
exe_finish_symbols:
	clr.l	symbol_table_size(a6)           ; no symbol table yet
	tst.b	debug_symbols(a6)               ; debug symbols?
	beq.w	exe_finish_relocation           ; no: the relocation
	movea.l	exe_text_buffer(a6),a4          ; the text buffer is free for them
	move.l	exe_text_buffer_size(a6),d4     ; its size
	lea	exe_symbol_record(pc),a2        ; for each symbol
	movea.l	current_module(a6),a1           ; the module
	bsr.w	module_walk_locals              ; of the module's symbol tree
	bsr.w	exe_symbols_flush               ; write the last of them
	bra.w	exe_finish_relocation           ; then the relocation

;------------------------------------------------------------------------------
; Put the symbol a1 into the DRI symbol table at a4 (d4 bytes left): labels only, 14 bytes, or 28 bytes for
; a name of 9 or more characters with -X.  The buffer is written out when full.
;------------------------------------------------------------------------------
exe_symbol_record:	; from: exe_finish, exe_finish_memory
	move.b	$d(a1),d0                       ; the symbol's type
	cmp.b	#$1,d0                          ; a label?
	bne.w	exe_symbol_record_done          ; no: none
	move.w	#$a200,d1                       ; defined, global, text based
	move.b	$e(a1),d0                       ; the section
	beq.s	exe_symbol_record_name          ; text
	move.w	#$a100,d1                       ; defined, global, BSS based
	cmp.b	#$18,d0                         ; the BSS?
	beq.s	exe_symbol_record_name          ; yes
	move.w	#$a400,d1                       ; defined, global, data based
exe_symbol_record_name:
	move.b	$16(a1),d0                      ; the name's length
	lea	$17(a1),a0                      ; the name
	tst.b	debug_symbols(a6)               ; extended names (-X)?
	bpl.s	exe_symbol_record_short         ; no
	cmp.b	#$9,d0                          ; 9 characters or more?
	bcs.s	exe_symbol_record_short         ; no: one record
	moveq	#28,d2                          ; two records
	cmp.l	d2,d4                           ; room for them?
	bge.s	exe_symbol_record_long          ; yes
	bsr.s	exe_symbols_flush               ; no: write the buffer first
exe_symbol_record_long:
	sub.l	d2,d4
	moveq	#7,d2                           ; the first 8 characters
exe_symbol_record_long_copy:
	move.b	(a0)+,(a4)+
	dbra	d2,exe_symbol_record_long_copy
	move.b	#$48,d1                         ; the type's low byte: the name goes on in the next record
	move.w	d1,(a4)+                        ; the type
	move.l	8(a1),(a4)+                     ; the value
	subi.b	#$9,d0                          ; the characters left
	ext.w	d0
	lea	$e(a4),a4                       ; past the second record
	move.l	a4,-(sp)
	clr.l	-(a4)                           ; clear it
	clr.l	-(a4)
	clr.l	-(a4)
	clr.w	-(a4)
exe_symbol_record_rest:
	move.b	(a0)+,(a4)+                     ; the rest of the name
	dbra	d0,exe_symbol_record_rest
	movea.l	(sp)+,a4                        ; past the second record
	rts
exe_symbol_record_short:
	moveq	#14,d2                          ; one record
	cmp.l	d2,d4                           ; room for it?
	bge.s	exe_symbol_record_short_room    ; yes
	bsr.s	exe_symbols_flush               ; no: write the buffer first
exe_symbol_record_short_room:
	sub.l	d2,d4
	moveq	#7,d2                           ; up to 8 characters
exe_symbol_record_short_copy:
	move.b	(a0)+,(a4)+
	subq.b	#1,d0                           ; the name's end?
	dbeq	d2,exe_symbol_record_short_copy
	subq.w	#1,d2                           ; the characters left
	bmi.s	exe_symbol_record_short_type    ; none
exe_symbol_record_short_pad:
	clr.b	(a4)+                           ; zeros to 8
	dbra	d2,exe_symbol_record_short_pad
exe_symbol_record_short_type:
	move.w	d1,(a4)+                        ; the type
	move.l	8(a1),(a4)+                     ; the value
exe_symbol_record_done:
	rts

;------------------------------------------------------------------------------
; Write the symbol records made in the text buffer (a4 at their end, d4 bytes left) and count them in the
; symbol table size; a4 and d4 then start again at the buffer's start.  Assembling to memory: buffer full.
;------------------------------------------------------------------------------
exe_symbols_flush:	; from: exe_finish, exe_symbol_record
	tst.l	program_buffer(a6)              ; assembling to memory?
	bne.w	report_program_buffer_full      ; yes: program buffer full
	movem.l	d0-d3/a0-a3,-(sp)
	move.l	exe_text_buffer_size(a6),d1     ; the buffer's size
	sub.l	d4,d1                           ; less the room left
	beq.s	exe_symbols_flush_done          ; nothing made
	add.l	d1,symbol_table_size(a6)        ; the symbol table grows by it
	movea.l	exe_text_buffer(a6),a0          ; the buffer
	movea.l	a0,a4                           ; the next record at its start
	bsr.w	binary_write                    ; write them
exe_symbols_flush_done:
	movem.l	(sp)+,d0-d3/a0-a3
	move.l	exe_text_buffer_size(a6),d4     ; all the buffer free again
	rts
	movea.l	exe_text_buffer(a6),a3          ; the text buffer (not reached: an empty relocation table)
	move.l	exe_text_buffer_size(a6),d4
	clr.l	(a3)+                           ; no relocation
	bra.w	exe_write_header                ; then the header
exe_finish_relocation:	; from: exe_finish
	movea.l	exe_text_buffer(a6),a3          ; the text buffer
	move.l	exe_text_buffer_size(a6),d4     ; its size
	bsr.s	exe_relocation_table            ; make the relocation table
	bra.w	exe_write_header                ; then the header

;------------------------------------------------------------------------------
; Make the executable's relocation table at a3 (d4 bytes left) from the text and data relocation lists: the
; first offset as a long, then byte steps (1 = 254 further), a 0 to end, or a 0 long when there are none.
; A list is blocks of +0 next, +4 last block, +8 free entries, +$a 50 long offsets.
;------------------------------------------------------------------------------
exe_relocation_table:	; from: exe_symbols_flush, exe_finish_memory
	move.l	text_relocation(a6),d0          ; text relocation?
	or.l	data_relocation(a6),d0          ; or data?
	bne.s	exe_relocation_table_first      ; yes
	clr.l	(a3)+                           ; none: a 0 long
	rts
exe_relocation_table_first:
	moveq	#0,d3                           ; text offsets as they are
	sf	d6                              ; the text list first
	lea	text_relocation(a6),a1
	tst.l	(a1)                            ; any?
	bne.s	exe_relocation_table_block      ; yes
	lea	data_relocation(a6),a1          ; no: the data list
	st	d6                              ; doing the data
	move.l	text_size(a6),d3                ; its offsets past the text
exe_relocation_table_block:
	movea.l	(a1),a1                         ; the first block
	lea	$a(a1),a0                       ; its offsets
	moveq	#50,d2
	sub.w	8(a1),d2                        ; less the free ones: those used
	move.l	(a0)+,d0                        ; the first offset
	add.l	d3,d0                           ; in the file's terms
	move.l	d0,(a3)+                        ; as a long
	subq.l	#4,d4
exe_relocation_table_next:
	subq.w	#1,d2                           ; the block done?
	beq.s	exe_relocation_table_link       ; yes
exe_relocation_table_entry:
	move.l	(a0)+,d1                        ; the next offset
	add.l	d3,d1
	move.l	d1,d5                           ; keep it
	sub.l	d0,d1                           ; the step from the last
exe_relocation_table_step:
	cmp.l	#$fe,d1                         ; more than 254?
	ble.s	exe_relocation_table_byte       ; no
	move.l	d1,-(sp)
	moveq	#1,d1                           ; yes: a 1 byte
	bsr.s	exe_relocation_byte
	moveq	#-127,d1                        ; less 254
	add.l	d1,d1
	add.l	(sp)+,d1
	bra.s	exe_relocation_table_step       ; again
exe_relocation_table_byte:
	bsr.s	exe_relocation_byte             ; the step
	move.l	d5,d0                           ; the last offset
	bra.s	exe_relocation_table_next
exe_relocation_table_link:
	tst.l	(a1)                            ; another block?
	beq.s	exe_relocation_table_list_end   ; no
	movea.l	(a1),a1                         ; yes
	lea	$a(a1),a0                       ; its offsets
	moveq	#50,d2
	sub.w	8(a1),d2                        ; those used
	bra.s	exe_relocation_table_entry
exe_relocation_table_list_end:
	tst.b	d6                              ; the data done too?
	bne.s	exe_relocation_table_end        ; yes: end
	st	d6                              ; now the data
	lea	data_relocation(a6),a1          ; its list
	move.l	text_size(a6),d3                ; its offsets past the text
	tst.l	(a1)                            ; any?
	bne.s	exe_relocation_table_link       ; yes
exe_relocation_table_end:
	moveq	#0,d1                           ; the 0 that ends the table

;------------------------------------------------------------------------------
; Put the relocation byte d1 at a3, writing the buffer when it is full.
;------------------------------------------------------------------------------
exe_relocation_byte:	; from: exe_relocation_table
	move.b	d1,(a3)+
	subq.l	#1,d4                           ; full?
	beq.s	exe_relocation_flush            ; yes: write it
	rts

;------------------------------------------------------------------------------
; Write the relocation bytes made in the text buffer (a3 at their end); a3 and d4 start again.
;------------------------------------------------------------------------------
exe_relocation_flush:	; from: exe_relocation_byte
	tst.l	program_buffer(a6)              ; assembling to memory?
	bne.w	report_program_buffer_full      ; yes: program buffer full
	movem.l	d0-d2/a0-a2,-(sp)
	movea.l	exe_text_buffer(a6),a0          ; the buffer
	move.l	a3,d1
	sub.l	a0,d1                           ; the byte count
	movea.l	a0,a3                           ; the next at its start
	bsr.w	binary_write                    ; write them
	move.l	exe_text_buffer_size(a6),d4     ; all the buffer free again
	movem.l	(sp)+,d0-d2/a0-a2
	rts
exe_write_header:	; from: exe_symbols_flush
	bsr.s	exe_relocation_flush            ; the last relocation bytes
	moveq	#0,d2                           ; the file's start
	bsr.w	output_seek                     ; Fseek there
	lea	line_code(a6),a0                ; make the header
	move.w	#$601a,(a0)+                    ; the magic
	move.l	text_size(a6),(a0)+             ; the text size
	move.l	data_size(a6),(a0)+             ; the data size
	move.l	bss_size(a6),(a0)+              ; the BSS size
	move.l	symbol_table_size(a6),(a0)+     ; the symbol table size
	clr.l	(a0)+                           ; reserved
	move.l	header_flags(a6),(a0)+          ; the flags (HEAD=)
	clr.w	(a0)+                           ; 0: relocation follows
	lea	line_code(a6),a0
	moveq	#28,d1                          ; 28 bytes
	bra.w	binary_write                    ; write it

;------------------------------------------------------------------------------
; End of assembling to memory: the symbols (with debug on) and the relocation table go after the text and
; data in the program buffer, then $601a marks the image complete.
;------------------------------------------------------------------------------
exe_finish_memory:	; from: exe_finish
	moveq	#0,d2                           ; no symbols yet
	move.l	program_buffer_end(a6),d4       ; the buffer's end
	sub.l	text_size(a6),d4                ; less the text
	sub.l	data_size(a6),d4                ; and the data
	subi.l	#$1e,d4                         ; and the header and 2: the room left
	tst.b	debug_symbols(a6)               ; debug symbols?
	beq.s	exe_finish_memory_relocation    ; no
	movea.l	program_buffer(a6),a4           ; the image
	lea	$1c(a4),a4                      ; past the header
	adda.l	text_size(a6),a4                ; past the text
	adda.l	data_size(a6),a4                ; and the data
	move.l	d4,-(sp)                        ; the room
	lea	exe_symbol_record(pc),a2        ; for each symbol
	movea.l	current_module(a6),a1           ; the module
	bsr.w	module_walk_locals              ; of the module's symbol tree
	move.l	(sp)+,d2
	sub.l	d4,d2                           ; the bytes used
	beq.s	exe_finish_memory_relocation    ; none
	movea.l	program_buffer(a6),a0           ; the image
	addq.l	#2,d2                           ; 2 more
	subq.l	#2,d4                           ; room for them?
	bcs.w	report_program_buffer_full      ; no: program buffer full
	move.l	d2,$e(a0)                       ; the symbol table size in the header
exe_finish_memory_relocation:
	movea.l	program_buffer(a6),a3           ; the image
	lea	$1c(a3),a3                      ; past the header
	adda.l	text_size(a6),a3                ; the text
	adda.l	data_size(a6),a3                ; the data
	adda.l	d2,a3                           ; and the symbols
	bsr.w	exe_relocation_table            ; the relocation table
	movea.l	program_buffer(a6),a0
	move.w	#$601a,(a0)                     ; the image is complete
	rts

;------------------------------------------------------------------------------
; A relocatable long at PC d0: add it to the current section's relocation list; in the BSS: relocation not
; allowed.  Nothing is kept with the binary off.
;------------------------------------------------------------------------------
exe_relocate_long:	; from: obj_relocation
	move.l	d0,d2                           ; the PC
	movea.l	current_section_record(a6),a1   ; the current section's symbol
	moveq	#0,d0
	move.b	$e(a1),d0                       ; its section
	cmp.b	#$18,d0                         ; the BSS?
	beq.w	err_relocation_not_allowed      ; yes: relocation not allowed
	tst.b	binary_on(a6)                   ; binary on?
	bne.s	exe_relocate_long_add           ; yes
	rts
exe_relocate_long_add:
	move.l	a2,-(sp)
	lea	text_relocation(a6),a1          ; the text's list
	adda.w	d0,a1                           ; or the data's
	movea.l	(a1),a2                         ; its first block
	tst.l	(a1)                            ; any?
	bne.s	exe_relocate_long_last          ; yes
	bsr.s	exe_relocation_block            ; no: the first block
	movea.l	a0,a2
	move.l	a0,4(a2)                        ; which is the last block too
	bra.s	exe_relocate_long_store

;------------------------------------------------------------------------------
; Get a new relocation block (210 bytes) and link it at (a1): no next, 50 entries free.  Out: a0 = the block.
;------------------------------------------------------------------------------
exe_relocation_block:	; from: exe_relocate_long
	movem.l	a1-a2,-(sp)
	move.l	#$d2,d1                         ; the block's size
	bsr.w	alloc_block                     ; allocate it
	movem.l	(sp)+,a1-a2
	move.l	a0,(a1)                         ; link it
	clr.l	(a0)                            ; no next
	move.w	#$32,8(a0)                      ; 50 free
	rts
exe_relocate_long_last:	; from: exe_relocate_long
	movea.l	4(a2),a0                        ; the last block
	tst.w	8(a0)                           ; any room?
	bne.s	exe_relocate_long_store         ; yes
	movea.l	a0,a1                           ; no: a new one after it
	bsr.s	exe_relocation_block
	move.l	a0,4(a2)                        ; now the last block
exe_relocate_long_store:	; from: exe_relocate_long
	moveq	#50,d0
	sub.w	8(a0),d0                        ; the entries used
	add.w	d0,d0
	add.w	d0,d0                           ; as long offsets
	subq.w	#1,8(a0)                        ; one fewer free
	move.l	d2,$a(a0,d0.w)                  ; the PC into the next
	movea.l	(sp)+,a2
	rts

;------------------------------------------------------------------------------
; ORG in an executable, d0 = the section, d1 = the step from the PC: pass 2 moves the buffer's limit by the
; step.  Out: d0 = -1 (not allowed) in the BSS, else 0.
;------------------------------------------------------------------------------
exe_org:	; from: obj_org
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	exe_org_check                   ; no
	tst.b	binary_on(a6)                   ; binary on?
	beq.s	exe_org_check                   ; no
	cmp.b	#$18,d0                         ; the BSS?
	beq.s	exe_org_check                   ; yes
	cmp.b	#$c,d0                          ; data?
	beq.s	exe_org_data                    ; yes
	add.l	d1,text_buffer_limit(a6)        ; the text buffer's limit
	bra.s	exe_org_ok
exe_org_data:
	add.l	d1,data_buffer_limit(a6)        ; the data buffer's limit
exe_org_check:
	cmp.b	#$18,d0                         ; the BSS?
	bne.s	exe_org_ok                      ; no
	moveq	#-1,d0                          ; yes: not allowed
	rts
exe_org_ok:
	moveq	#0,d0                           ; allowed
	rts

;------------------------------------------------------------------------------
; Listing: after a relocatable value show its section, T, D or B (d0 = the section), then spaces.
;------------------------------------------------------------------------------
exe_list_section:	; from: listing_section
	moveq	#84,d1                          ; T
	tst.b	d0                              ; text?
	beq.s	exe_list_section_show           ; yes
	moveq	#68,d1                          ; D
	cmp.b	#$c,d0                          ; data?
	beq.s	exe_list_section_show           ; yes
	moveq	#66,d1                          ; B
exe_list_section_show:
	bsr.w	asm_output_char                 ; the letter
	bra.w	print_two_spaces                ; the spaces

;------------------------------------------------------------------------------
; The output's description for the report: a0 = "executable".
;------------------------------------------------------------------------------
exe_format_name:	; from: obj_print_format
	lea	str_executable(pc),a0
	rts

;------------------------------------------------------------------------------
; The output file's default extension: a0 = ".PRG".
;------------------------------------------------------------------------------
exe_extension:	; from: obj_extension
	lea	str_ext_prg(pc),a0
	rts
str_executable:	; from: exe_format_name
	dc.b	'executable',0                  ; the format's description
str_ext_prg:
	dc.b	'.PRG',0                        ; the default extension

;------------------------------------------------------------------------------
; Copy the 0-ended string at a0 to a1 (all the output formats); a1 is left on the copy's 0.
;------------------------------------------------------------------------------
copy_string:	; from: obj_copy_name
	move.b	(a0)+,(a1)+
	bne.s	copy_string
	subq.l	#1,a1                           ; back on the 0
	rts

;------------------------------------------------------------------------------
; GST linkable output (-L), the .BIN format of the GST/QL linker: a stream of bytes with records that start
; with $FB and a type: $01 source (module name), $02 comment, $03 org, $04 section, $05 offset, $06 xdef,
; $07 xref, $10 define (a number for a section or an XREF), $13 end; a $FB in the code is written twice.
; The stream is made in one buffer that is written when full.  Here: after pass 1, get that buffer.
;------------------------------------------------------------------------------
gst_start:	; from: obj_buffers_init
	tst.l	program_buffer(a6)              ; assembling to memory?
	bne.w	report_executable_only          ; yes: executable code only
	move.l	#$4000,d1                       ; the size wanted
	move.l	#$400,d2                        ; at least
	bsr.w	buffer_size                     ; as memory allows
	move.l	d1,gst_buffer_size(a6)          ; the buffer's size
	move.l	d1,gst_room(a6)                 ; all of it free
	bsr.w	alloc_block                     ; allocate it
	move.l	a0,gst_buffer(a6)               ; the buffer
	move.l	a0,gst_pointer(a6)              ; the write pointer
	rts

;------------------------------------------------------------------------------
; GST, a module starts (a1 = the module): a source record with its name, a define record for each of its
; sections (numbers -1 down) and for each XREF of its symbols.
;------------------------------------------------------------------------------
gst_module_start:	; from: obj_module_start
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#1,d1                           ; source
	bsr.w	gst_record
	lea	$16(a1),a0                      ; the module's name
	move.b	(a0)+,d1                        ; its length
	subq.b	#1,d1                           ; less its end mark
	bsr.w	gst_put_string                  ; the name
	move.l	a2,gst_pointer(a6)
	lea	gst_define_section(pc),a2       ; for each section symbol
	moveq	#0,d3                           ; all types
	moveq	#0,d4                           ; section numbers from -1
gst_module_start_section:
	subq.b	#1,d4                           ; the next section number
	move.l	sp,walk_stack(a6)               ; the stack, to leave the walk when found
	movea.l	8(a1),a0                        ; the module's sections
	bsr.w	symbols_walk_tree               ; find that one
	trap	#15                             ; not found: cannot happen
gst_module_start_next:	; from: gst_define_section
	cmp.b	$c(a1),d4                       ; the module's last section?
	bne.s	gst_module_start_section        ; no
	movea.l	asm_module_tree(a6),a1          ; the module's symbols
	movea.l	(a1),a1
	movea.l	gst_pointer(a6),a2              ; the write pointer
	move.l	a1,d0                           ; any?
	beq.s	gst_module_start_done           ; no
	bsr.s	gst_define_xrefs                ; define the XREFs
gst_module_start_done:
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; Walk the symbol tree a1 (left, node, right) and write a define record for each XREF.
;------------------------------------------------------------------------------
gst_define_xrefs:	; from: gst_module_start
	tst.l	(a1)                            ; a left branch?
	beq.s	gst_define_xrefs_node           ; no
	move.l	a1,-(sp)
	movea.l	(a1),a1
	bsr.s	gst_define_xrefs                ; walk it
	movea.l	(sp)+,a1
gst_define_xrefs_node:
	btst	#$4,$c(a1)                      ; an XREF?
	beq.s	gst_define_xrefs_right          ; no
	bsr.s	gst_define_xref                 ; yes: define it
gst_define_xrefs_right:
	tst.l	4(a1)                           ; a right branch?
	beq.s	gst_define_xrefs_done           ; no
	move.l	a1,-(sp)
	movea.l	4(a1),a1
	bsr.s	gst_define_xrefs                ; walk it
	movea.l	(sp)+,a1
gst_define_xrefs_done:
	rts

;------------------------------------------------------------------------------
; Write a define record for the XREF a1: its number and its name.
;------------------------------------------------------------------------------
gst_define_xref:	; from: gst_define_xrefs
	moveq	#16,d1                          ; define
	bsr.w	gst_record
	move.w	$14(a1),d1                      ; the XREF's number
	bsr.w	gst_put_word
	lea	$16(a1),a0                      ; the name
	move.b	(a0)+,d1                        ; its length
	bra.w	gst_put_string

;------------------------------------------------------------------------------
; Write an xdef record for the symbol a1: name, value and section number (0 when it is absolute).  For XDEF
; and for the debug symbols.
;------------------------------------------------------------------------------
gst_xdef:	; from: obj_export, gst_debug_symbol
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#6,d1                           ; xdef
	bsr.w	gst_record
	lea	$16(a1),a0                      ; the name
	move.b	(a0)+,d1                        ; its length
	bsr.w	gst_put_string
	move.w	8(a1),d1                        ; the value: high word
	bsr.w	gst_put_word
	move.w	$a(a1),d1                       ; low word
	bsr.w	gst_put_word
	move.b	$e(a1),d1                       ; the section number
	ext.w	d1
	cmpi.b	#$1,$d(a1)                      ; a label?
	beq.s	gst_xdef_section                ; yes
	moveq	#0,d1                           ; no: absolute
gst_xdef_section:
	bsr.w	gst_put_word
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; Called for each section symbol a0 by the walk: the one numbered d4 gets a define record (number and
; name), then the walk is left by the stack kept at the start.
;------------------------------------------------------------------------------
gst_define_section:	; from: gst_module_start
	cmp.b	$e(a0),d4                       ; the one wanted?
	beq.s	gst_define_section_found        ; yes
	rts
gst_define_section_found:
	movem.l	a0/a2,-(sp)
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#16,d1                          ; define
	bsr.w	gst_record
	move.b	$e(a0),d1                       ; the section's number
	ext.w	d1
	bsr.w	gst_put_word
	lea	$16(a0),a0                      ; the name
	move.b	(a0)+,d1                        ; its length
	subq.b	#1,d1                           ; less its end mark
	bsr.w	gst_put_string
	move.l	a2,gst_pointer(a6)
	movem.l	(sp)+,a0/a2
	movea.l	walk_stack(a6),sp               ; leave the walk
	bra.w	gst_module_start_next           ; the next section

;------------------------------------------------------------------------------
; GST, a module ends in pass 2: a module that put only its 27 starting bytes into the buffer before the file
; was opened is dropped.  Else, with debug on, an xdef record for each label, then the end record.
;------------------------------------------------------------------------------
gst_module_end:	; from: obj_module_end
	move.l	gst_buffer_size(a6),d1          ; the buffer's size
	sub.l	gst_room(a6),d1                 ; less the room: the bytes in it
	cmp.l	#$1b,d1                         ; the start only?
	bne.s	gst_module_end_debug            ; no
	tst.l	binary_handle(a6)               ; the file open?
	bne.s	gst_module_end_debug            ; yes
	move.l	gst_buffer(a6),gst_pointer(a6)  ; drop them
	move.l	gst_buffer_size(a6),gst_room(a6)
	rts
gst_module_end_debug:
	tst.b	debug_symbols(a6)               ; debug symbols?
	beq.s	gst_module_end_record           ; no
	lea	gst_debug_symbol(pc),a2         ; for each symbol
	bsr.w	module_walk_locals              ; of the module's symbol tree
gst_module_end_record:
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#19,d1                          ; end
	bsr.w	gst_record
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; Called for each symbol a1: a local label (not XREF, XDEF or bit 7) gets an xdef record for the debugger.
;------------------------------------------------------------------------------
gst_debug_symbol:	; from: gst_module_end
	cmpi.b	#$1,$d(a1)                      ; a label?
	bne.s	gst_debug_symbol_done           ; no
	moveq	#-80,d0
	and.b	$c(a1),d0                       ; local?
	bne.s	gst_debug_symbol_done           ; no
	move.l	a2,-(sp)
	bsr.w	gst_xdef                        ; an xdef record
	movea.l	(sp)+,a2
gst_debug_symbol_done:
	rts

;------------------------------------------------------------------------------
; GST, entering a section in pass 2: a section record with its number.
;------------------------------------------------------------------------------
gst_section_enter:	; from: obj_section_enter
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	gst_section_leave               ; no
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#4,d1                           ; section
	bsr.w	gst_record
	move.b	current_section(a6),d1          ; its number
	ext.w	d1
	bsr.w	gst_put_word
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; GST, leaving a section: nothing.
;------------------------------------------------------------------------------
gst_section_leave:	; from: obj_section_leave, gst_section_enter
	rts

;------------------------------------------------------------------------------
; GST, a line starts: empty the line's list of xref records and their buffer.
;------------------------------------------------------------------------------
gst_line_start:	; from: obj_line_start
	lea	gst_fixups(a6),a1               ; the list
	move.l	a1,gst_fixups_end(a6)           ; the list's end
	clr.l	(a1)                            ; empty
	lea	gst_records(a6),a1              ; the records' buffer
	move.l	a1,gst_records_end(a6)          ; their end
	rts

;------------------------------------------------------------------------------
; GST, a long relocated by the current section at a5 (d2 = its value): an xref record (value, long,
; relocated, + the section) goes in the line's list to take the long's place in the stream.
;------------------------------------------------------------------------------
gst_relocate_long:	; from: obj_relocation
	tst.b	binary_on(a6)                   ; binary on?
	beq.s	gst_relocate_long_done          ; no
	movea.l	gst_fixups_end(a6),a0           ; the list's end
	move.l	a5,(a0)+                        ; the code's place
	move.l	gst_records_end(a6),(a0)+       ; the record
	move.w	#$4,(a0)+                       ; 4 bytes replaced
	move.l	a0,gst_fixups_end(a6)           ; the list's end
	clr.l	(a0)
	movea.l	gst_records_end(a6),a0          ; the record
	move.b	#$fb,(a0)+                      ; $FB
	move.b	#$7,(a0)+                       ; xref
	move.l	d2,-(sp)                        ; the value
	movea.l	sp,a1
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	#$54,(a0)+                      ; long, unsigned, relocated
	move.b	#$2b,(a0)+                      ; +
	st	(a0)+                           ; the section's number: $ff,
	move.b	current_section(a6),(a0)+       ; section
	move.b	#$fb,(a0)+                      ; the record's end
	move.l	a0,gst_records_end(a6)          ; the records' end
	addq.l	#4,sp
gst_relocate_long_done:
	rts

;------------------------------------------------------------------------------
; GST: data is allowed in every section (Z clear).
;------------------------------------------------------------------------------
gst_data_allowed:	; from: obj_no_data
	moveq	#-1,d0
	rts

;------------------------------------------------------------------------------
; GST, COMMENT: a comment record with the text a1, d2 characters (up to 127).
;------------------------------------------------------------------------------
gst_comment:	; from: obj_comment
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#2,d1                           ; comment
	bsr.w	gst_record
	andi.b	#$7f,d2                         ; up to 127
	move.b	d2,d1                           ; its length
	movea.l	a1,a0                           ; the text
	bsr.w	gst_put_string
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; GST, RORG d2: an offset record in pass 2.  Out: Z set (allowed).
;------------------------------------------------------------------------------
gst_rorg:	; from: obj_rorg
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	gst_address_record_done         ; no
	tst.b	binary_on(a6)                   ; binary on?
	beq.s	gst_address_record_done         ; no
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#5,d1                           ; offset
	bra.s	gst_address_record

;------------------------------------------------------------------------------
; GST, ORG d2: an org record in pass 2.  Out: Z set (allowed).
;------------------------------------------------------------------------------
gst_org:	; from: obj_org
	tst.b	pass_two(a6)                    ; pass 2?
	beq.s	gst_address_record_done         ; no
	tst.b	binary_on(a6)                   ; binary on?
	beq.s	gst_address_record_done         ; no
	movea.l	gst_pointer(a6),a2              ; the write pointer
	moveq	#3,d1                           ; org
gst_address_record:	; from: gst_rorg
	bsr.w	gst_record                      ; the record's start
	move.l	d2,d1                           ; the address
	swap	d1                              ; high word
	bsr.w	gst_put_word
	swap	d1                              ; low word
	bsr.w	gst_put_word
	move.l	a2,gst_pointer(a6)
	moveq	#0,d0                           ; allowed
gst_address_record_done:	; from: gst_rorg
	rts

;------------------------------------------------------------------------------
; GST, INCBIN: put d1 bytes from a0 into the stream, a $FB written twice.
;------------------------------------------------------------------------------
gst_incbin:	; from: obj_incbin
	movea.l	gst_pointer(a6),a2              ; the write pointer
	move.l	gst_room(a6),d3                 ; the room
gst_incbin_loop:
	subq.l	#1,d1                           ; all done?
	bcs.s	gst_incbin_done                 ; yes
	move.b	(a0)+,d0                        ; the byte
	bsr.s	gst_put_byte
	cmp.b	#$fb,d0                         ; $FB?
	bne.s	gst_incbin_loop                 ; no
	bsr.s	gst_put_byte                    ; yes: twice
	bra.s	gst_incbin_loop
gst_incbin_done:
	move.l	d3,gst_room(a6)
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; Put the byte d0 at a2 (d3 bytes left), writing the buffer when full.
;------------------------------------------------------------------------------
gst_put_byte:	; from: gst_incbin
	subq.l	#1,d3                           ; room?
	bcs.s	gst_put_byte_flush              ; no
	move.b	d0,(a2)+
	rts
gst_put_byte_flush:
	addq.l	#1,d3
	move.l	d3,gst_room(a6)
	bsr.w	gst_flush                       ; write the buffer
	move.l	gst_room(a6),d3
	bra.s	gst_put_byte                    ; again

;------------------------------------------------------------------------------
; GST, the line's code: d1 bytes from the code pointer into the stream, $FB written twice and the xref
; records of the line put in place of the bytes they stand for.
;------------------------------------------------------------------------------
gst_code:	; from: obj_emit
	movea.l	gst_pointer(a6),a2              ; the write pointer
	movea.l	code_buffer_ptr(a6),a1          ; the code
	move.l	gst_room(a6),d3                 ; the room
	moveq	#-5,d2                          ; $FB
	tst.l	gst_fixups(a6)                  ; any xref records?
	bne.w	gst_code_merge                  ; yes: merge them

;------------------------------------------------------------------------------
; Copy d1 bytes from a1 into the stream at a2 (d3 bytes left), d2 = $FB written twice.
;------------------------------------------------------------------------------
gst_copy_code:	; from: gst_copy_code_part
	subq.l	#1,d3                           ; room?
	bcs.s	gst_copy_code_flush             ; no
	move.b	(a1)+,d0                        ; the byte
	move.b	d0,(a2)+
	cmp.b	d2,d0                           ; $FB?
	beq.s	gst_copy_code_escape            ; yes
gst_copy_code_next:
	subq.l	#1,d1                           ; all done?
	bne.s	gst_copy_code                   ; no
	move.l	d3,gst_room(a6)
	move.l	a2,gst_pointer(a6)
	rts
gst_copy_code_escape:
	subq.l	#1,d3                           ; room for the second?
	bne.s	gst_copy_code_twice             ; yes
	addq.l	#1,d3
	move.l	d3,gst_room(a6)
	bsr.w	gst_flush                       ; no: write the buffer
	move.l	gst_room(a6),d3
	subq.l	#1,d3
gst_copy_code_twice:
	move.b	d2,(a2)+                        ; the second $FB
	bra.s	gst_copy_code_next
gst_copy_code_flush:
	addq.l	#1,d3
	move.l	d3,gst_room(a6)
	bsr.w	gst_flush                       ; write the buffer
	move.l	gst_room(a6),d3
	bra.s	gst_copy_code                   ; again
gst_put_escape:
	addq.l	#1,gst_room(a6)                 ; (not reached) a $FB with the buffer written first
	bsr.s	gst_flush
	subq.l	#1,gst_room(a6)
	bcs.s	gst_put_escape
	move.b	#$fb,(a2)+
	rts
gst_record_flush:	; from: gst_record
	addq.l	#2,gst_room(a6)
	bsr.s	gst_flush                       ; write the buffer

;------------------------------------------------------------------------------
; Start a record at a2: $FB and the type d1, writing the buffer when it is full.
;------------------------------------------------------------------------------
gst_record:                                     ; from: gst_module_start, gst_define_xref, gst_xdef, gst_define_section,
                                                ;   gst_module_end, gst_section_enter, 2 more
	subq.l	#2,gst_room(a6)                 ; room for 2?
	bcs.s	gst_record_flush                ; no
	move.b	#$fb,(a2)+
	move.b	d1,(a2)+                        ; the type
	rts
gst_put_word_flush:	; from: gst_put_word
	addq.l	#2,gst_room(a6)
	bsr.s	gst_flush                       ; write the buffer

;------------------------------------------------------------------------------
; Put the word d1 at a2, high byte first, writing the buffer when it is full.
;------------------------------------------------------------------------------
gst_put_word:	; from: gst_define_xref, gst_xdef, gst_define_section, gst_section_enter, gst_org
	subq.l	#2,gst_room(a6)                 ; room for 2?
	bcs.s	gst_put_word_flush              ; no
	move.w	d1,-(sp)
	move.b	(sp),(a2)+                      ; high byte
	move.b	1(sp),(a2)+                     ; low byte
	addq.l	#2,sp
	rts
gst_put_string_flush:	; from: gst_put_string
	bsr.s	gst_flush                       ; write the buffer

;------------------------------------------------------------------------------
; Put a string at a2: the length byte d1 then d1 characters from a0, writing the buffer when it is full.
;------------------------------------------------------------------------------
gst_put_string:	; from: gst_module_start, gst_define_xref, gst_xdef, gst_define_section, gst_comment
	ext.w	d1
	ext.l	d1
	cmp.l	gst_room(a6),d1                 ; room?
	bge.s	gst_put_string_flush            ; no
	sub.l	d1,gst_room(a6)
	subq.l	#1,gst_room(a6)                 ; and the length byte
	move.b	d1,(a2)+                        ; the length
gst_put_string_loop:
	move.b	(a0)+,(a2)+
	subq.b	#1,d1
	bne.s	gst_put_string_loop
	rts

;------------------------------------------------------------------------------
; Write the GST buffer's bytes to the output file (opening it first); a2 and the room start again.
;------------------------------------------------------------------------------
gst_flush:	; from: gst_put_byte, gst_copy_code, gst_record, gst_put_word, gst_finish, gst_code_merge
	movem.l	d0-d2/a0-a1,-(sp)
	bsr.w	binary_create                   ; open the output file
	movea.l	gst_buffer(a6),a0               ; the buffer
	move.l	gst_buffer_size(a6),d1          ; its size
	sub.l	gst_room(a6),d1                 ; less the room: the bytes in it
	bsr.w	binary_write                    ; write them
	movea.l	gst_buffer(a6),a2               ; the write pointer back
	move.l	gst_buffer_size(a6),gst_room(a6) ; all room again
	movem.l	(sp)+,d0-d2/a0-a1
	rts

;------------------------------------------------------------------------------
; End of the assembly, GST: write what is left in the buffer.
;------------------------------------------------------------------------------
gst_finish:	; from: obj_finish
	bra.s	gst_flush

;------------------------------------------------------------------------------
; GST references to XREFs and other sections.  Each puts an xref record into the line's list with the size
; and truncation rule d0 (bit 0 byte, 1 word, 2 long, 3 signed, 4 unsigned, 5 PC relative, 6 relocated),
; d2 = the value and the expression's terms; a5 steps past the bytes it stands for.  This one: a long.
;------------------------------------------------------------------------------
gst_xref_long:	; from: obj_xref_long
	moveq	#20,d0                          ; long, unsigned
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	gst_xref_record                 ; no
	moveq	#84,d0                          ; long, unsigned, relocated
	bra.s	gst_xref_record
gst_xref_byte:	; from: obj_xref_byte
	moveq	#1,d0                           ; byte
	bra.s	gst_xref_check
gst_xref_byte_signed:	; from: obj_xref_disp_byte
	moveq	#9,d0                           ; byte, signed
	bra.s	gst_xref_check
gst_xref_word:	; from: obj_xref_word
	moveq	#2,d0                           ; word
	bra.s	gst_xref_check
gst_xref_word_signed:	; from: obj_xref_disp_word
	moveq	#10,d0                          ; word, signed
	bra.s	gst_xref_check
gst_xref_branch_short:	; from: obj_xref_pcrel_byte
	moveq	#41,d0                          ; byte, signed, PC relative (BRA.S)
	subq.l	#1,d2                           ; from the byte after the opcode
	bra.s	gst_xref_record
gst_xref_branch:	; from: obj_xref_pcrel_word
	moveq	#42,d0                          ; word, signed, PC relative
	bra.s	gst_xref_record
gst_xref_check:
	cmp.b	#$1,d3                          ; relocatable?
	bne.s	gst_xref_record                 ; no
	move.w	d0,-(sp)
	moveq	#2,d0                           ; warning: relative cannot be relocated
	bsr.w	asm_warning
	move.w	(sp)+,d0
gst_xref_record:
	movea.l	gst_fixups_end(a6),a0           ; the list's end
	move.l	a5,(a0)+                        ; the code's place
	move.w	d0,d3
	andi.b	#$7,d3                          ; the size
	adda.w	d3,a5                           ; past the bytes
	move.l	gst_records_end(a6),(a0)+       ; the record
	move.w	d3,(a0)+                        ; the size
	move.l	a0,gst_fixups_end(a6)           ; the list's end
	clr.l	(a0)
	movea.l	gst_records_end(a6),a0          ; the record
	move.b	#$fb,(a0)+                      ; $FB
	move.b	#$7,(a0)+                       ; xref
	move.l	d2,-(sp)                        ; the value
	movea.l	sp,a1
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	(a1)+,(a0)+
	move.b	d0,(a0)+                        ; the truncation rule
	lea	expr_terms(a6),a1               ; the expression's XREF terms
	tst.b	relocatable_terms(a6)           ; relative to this section?
	beq.s	gst_xref_record_terms           ; no
	bpl.s	gst_xref_record_plus            ; added?
	move.b	#$2d,(a0)+                      ; no: -
	bra.s	gst_xref_record_section
gst_xref_record_plus:
	move.b	#$2b,(a0)+                      ; +
gst_xref_record_section:
	st	(a0)+                           ; the section's number: $ff,
	move.b	current_section(a6),(a0)+       ; section
gst_xref_record_terms:
	move.w	(a1)+,d0                        ; the next term
	beq.s	gst_xref_record_end             ; the end
	move.b	d0,(a0)+                        ; its operator
	move.w	(a1)+,(sp)                      ; its XREF's number
	move.b	(sp),(a0)+                      ; high byte
	move.b	1(sp),(a0)+                     ; low byte
	bra.s	gst_xref_record_terms
gst_xref_record_end:
	move.b	#$fb,(a0)+                      ; the record's end
	move.l	a0,gst_records_end(a6)          ; the records' end
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; The line's code with xref records: the code up to each record's place, the record, then on past the
; bytes it stands for; then the code that is left.
;------------------------------------------------------------------------------
gst_code_merge:	; from: gst_code
	move.l	d4,-(sp)
	lea	gst_fixups(a6),a0               ; the list
gst_code_merge_loop:
	move.l	(a0)+,d4                        ; the next record's place
	beq.s	gst_code_merge_rest             ; none: the rest
	sub.l	a1,d4                           ; the bytes before it
	bsr.s	gst_copy_code_part              ; copy them
	movem.l	a1/a3,-(sp)
	movea.l	(a0)+,a1                        ; the record
	movea.l	gst_records_end(a6),a3          ; its end: the records' end
	move.w	(a0)+,d0                        ; the size it stands for
	tst.l	(a0)                            ; another after it?
	beq.s	gst_code_merge_record           ; no
	movea.l	4(a0),a3                        ; yes: its record ends this one
gst_code_merge_record:
	move.l	a3,d4
	sub.l	a1,d4                           ; the record's length
	cmp.l	d3,d4                           ; room?
	ble.s	gst_code_merge_room             ; yes
	move.l	d3,gst_room(a6)
	bsr.w	gst_flush                       ; no: write the buffer
	move.l	gst_room(a6),d3
gst_code_merge_room:
	sub.l	d4,d3
gst_code_merge_copy:
	move.b	(a1)+,(a2)+                     ; the record as it is
	subq.l	#1,d4
	bne.s	gst_code_merge_copy
	movem.l	(sp)+,a1/a3
	ext.l	d0
	adda.l	d0,a1                           ; past the bytes it stands for
	sub.l	d0,d1
	bra.s	gst_code_merge_loop
gst_code_merge_rest:
	move.l	d1,d4                           ; the bytes left
	bsr.s	gst_copy_code_part              ; copy them
	move.l	d3,gst_room(a6)
	move.l	(sp)+,d4
	move.l	a2,gst_pointer(a6)
	rts

;------------------------------------------------------------------------------
; Copy d4 bytes of the code (from the d1 bytes left) with gst_copy_code; d1 less them.
;------------------------------------------------------------------------------
gst_copy_code_part:	; from: gst_code_merge
	tst.l	d4                              ; any?
	beq.s	gst_copy_code_part_done         ; no
	exg	d4,d1
	sub.l	d1,d4
	bsr.w	gst_copy_code
	exg	d1,d4
gst_copy_code_part_done:
	rts

;------------------------------------------------------------------------------
; Listing: after a relocatable value show its section number in hex and a dot.
;------------------------------------------------------------------------------
gst_list_section:	; from: listing_section
	move.b	d0,d1                           ; the section's number
	bsr.w	print_hex_byte                  ; in hex
	moveq	#46,d1                          ; .
	bra.w	asm_output_char

;------------------------------------------------------------------------------
; The output's description for the report: a0 = "GST linkable".
;------------------------------------------------------------------------------
gst_format_name:	; from: obj_print_format
	lea	str_gst_linkable(pc),a0
	rts

;------------------------------------------------------------------------------
; The output file's default extension: a0 = ".BIN".
;------------------------------------------------------------------------------
gst_extension:	; from: obj_extension
	lea	str_ext_bin(pc),a0
	rts
str_gst_linkable:	; from: gst_format_name
	dc.b	'GST linkable',0                ; the format's description
str_ext_bin:
	dc.b	'.BIN',0                        ; the default extension

;------------------------------------------------------------------------------
; DRI linkable output (-L2), the .O format of the DRI linker (OSS when COMMENT PASCAL is given): header,
; text, data, symbol table (XREFs first, in number order), then a relocation word for each word of text
; and data (OSS: code and relocation words in turn).  The text and data are each made whole in memory with
; their relocation words after them.  Here: after pass 1, get those two buffers.
;------------------------------------------------------------------------------
dri_start:	; from: obj_buffers_init
	tst.l	program_buffer(a6)              ; assembling to memory?
	bne.w	report_executable_only          ; yes: executable code only
	move.l	text_size(a6),d1                ; the text size
	add.l	d1,d1                           ; twice, for the relocation
	addi.l	#$64,d1                         ; and some
	bsr.w	alloc_block                     ; allocate it
	move.l	a0,exe_text_buffer(a6)          ; the text buffer
	move.l	a0,exe_text_pointer(a6)         ; its code pointer
	move.l	a0,code_buffer_ptr(a6)          ; the code pointer now
	move.l	text_size(a6),d1                ; the text size
	bsr.s	dri_clear_relocation            ; clear its relocation
	move.l	data_size(a6),d1                ; the data size
	add.l	d1,d1                           ; twice
	addi.l	#$64,d1                         ; and some
	bsr.w	alloc_block                     ; allocate it
	move.l	a0,data_buffer(a6)              ; the data buffer
	move.l	a0,exe_data_pointer(a6)         ; its code pointer
	move.l	data_size(a6),d1                ; the data size: clear its relocation

;------------------------------------------------------------------------------
; Clear the d1 bytes after the first d1 bytes of the buffer a0: the relocation words of its code.
;------------------------------------------------------------------------------
dri_clear_relocation:	; from: dri_start
	adda.l	d1,a0                           ; the relocation half
	lsr.l	#1,d1                           ; in words
	subq.l	#1,d1
	bcs.s	dri_clear_relocation_done       ; none
	moveq	#0,d0
dri_clear_relocation_loop:
	move.w	d0,(a0)+
	dbra	d1,dri_clear_relocation_loop
	subi.l	#$10000,d1                      ; the next 64 K words
	bcc.s	dri_clear_relocation_loop
dri_clear_relocation_done:
	rts

;------------------------------------------------------------------------------
; DRI, a long relocated by the current section at a5: its relocation words 5 (a long) then 2 (text) or 1.
;------------------------------------------------------------------------------
dri_relocate_long:	; from: obj_relocation
	tst.b	binary_on(a6)                   ; binary on?
	beq.s	dri_relocate_long_done          ; no
	move.l	text_size(a6),d0                ; the relocation's offset: the text size
	moveq	#2,d2                           ; text based
	tst.b	current_section(a6)             ; the text?
	beq.s	dri_relocate_long_store         ; yes
	move.l	data_size(a6),d0                ; the data size
	moveq	#1,d2                           ; data based
dri_relocate_long_store:
	move.w	#$5,0(a5,d0.l)                  ; a long
	move.w	d2,2(a5,d0.l)                   ; its section
dri_relocate_long_done:
	rts

;------------------------------------------------------------------------------
; DRI, INCBIN: copy d1 bytes from a0 to the code pointer a5.
;------------------------------------------------------------------------------
dri_incbin:	; from: obj_incbin
	add.l	d1,code_buffer_ptr(a6)          ; the code pointer past them
dri_incbin_loop:
	move.b	(a0)+,(a5)+
	subq.l	#1,d1
	bne.s	dri_incbin_loop
	rts

;------------------------------------------------------------------------------
; DRI, the line's code: it is in its buffer already; the code pointer goes past it.
;------------------------------------------------------------------------------
dri_code:	; from: obj_emit
	add.l	d1,code_buffer_ptr(a6)
	rts

;------------------------------------------------------------------------------
; Nothing to do for this output format.
;------------------------------------------------------------------------------
output_nothing:	; from: obj_module_start, obj_module_end, obj_export, obj_line_start
	rts

;------------------------------------------------------------------------------
; DRI, ORG: not allowed (d0 = -1).
;------------------------------------------------------------------------------
dri_org:	; from: obj_org
	moveq	#-1,d0
	rts

;------------------------------------------------------------------------------
; DRI, COMMENT: the text a1 (d2 characters) PASCAL, in any case, chooses the OSS format.
;------------------------------------------------------------------------------
dri_comment:	; from: obj_comment
	cmp.w	#$6,d2                          ; 6 characters?
	bne.s	dri_comment_done                ; no
	lea	str_pascal(pc),a0               ; PASCAL
dri_comment_loop:
	move.b	(a1)+,d0                        ; a character
	ext.w	d0
	move.b	upper_case(a6,d0.w),d0          ; upper case
	cmp.b	(a0)+,d0                        ; the same?
	bne.s	dri_comment_done                ; no
	subq.w	#1,d2
	bne.s	dri_comment_loop
	st	oss_format(a6)                  ; yes: OSS format
dri_comment_done:
	rts
str_pascal:
	dc.w	$5041,$5343,$414c               ; PASCAL, the COMMENT that chooses OSS
dri_restriction_pop:	; from: dri_xref_term
	addq.l	#4,sp                           ; drop the return

;------------------------------------------------------------------------------
; Error: linker format restriction.
;------------------------------------------------------------------------------
dri_restriction:	; from: obj_xref_pcrel_byte, obj_xref_disp_byte, obj_xref_byte, dri_xref_word, dri_xref_branch
	moveq	#66,d0
	bra.w	asm_error

;------------------------------------------------------------------------------
; For a DRI reference: d2 = the relocation words' offset (the section's size).  The expression must be one
; + term: an XREF gives d0 = its symbol index * 8 (N clear); a section gives N set, d0 low byte = it.  With
; the binary off the caller's caller is returned to.
;------------------------------------------------------------------------------
dri_xref_term:	; from: dri_xref_long, dri_xref_word, dri_xref_branch
	tst.b	binary_on(a6)                   ; binary on?
	beq.s	dri_xref_term_off               ; no
	move.l	text_size(a6),d2                ; the text size
	tst.b	current_section(a6)             ; the text?
	beq.s	dri_xref_term_check             ; yes
	move.l	data_size(a6),d2                ; the data size
dri_xref_term_check:
	lea	expr_terms(a6),a0               ; the terms
	move.w	(a0)+,d0                        ; the operator
	cmp.w	#$2b2b,d0                       ; +?
	bne.s	dri_restriction_pop             ; no: linker format restriction
	move.w	(a0)+,d0                        ; the XREF number
	bpl.s	dri_xref_term_index             ; an XREF
	rts                                     ; a section: N set
dri_xref_term_index:
	subq.w	#1,d0                           ; the index in the symbol table
	add.w	d0,d0
	add.w	d0,d0
	add.w	d0,d0                           ; times 8
	rts
dri_xref_term_off:
	addq.l	#4,sp                           ; return to the caller's caller
	rts

;------------------------------------------------------------------------------
; DRI, a long to an XREF or another section (d2 = its value) at a5.
;------------------------------------------------------------------------------
dri_xref_long:	; from: obj_xref_long
	move.l	d2,(a5)+                        ; the value
	bsr.s	dri_xref_term                   ; the term
	bmi.s	dri_xref_long_section           ; a section
	move.w	#$5,-$4(a5,d2.l)                ; a long
	ori.b	#$4,d0                          ; external
	move.w	d0,-$2(a5,d2.l)                 ; the symbol
	rts
dri_xref_long_section:
	move.w	#$5,-$4(a5,d2.l)                ; a long
	bsr.s	dri_section_word                ; the section's relocation word
	move.w	d0,-$2(a5,d2.l)
	rts

;------------------------------------------------------------------------------
; DRI, a word to an XREF (d2 = its value) at a5; to another section: linker format restriction.
;------------------------------------------------------------------------------
dri_xref_word:	; from: obj_xref_disp_word, obj_xref_word
	move.w	d2,(a5)+                        ; the value
	bsr.s	dri_xref_term                   ; the term
	bmi.s	dri_restriction                 ; a section: not allowed
	ori.b	#$4,d0                          ; external
	move.w	d0,-$2(a5,d2.l)
	rts

;------------------------------------------------------------------------------
; DRI, a PC relative word to an XREF at a5; to another section: linker format restriction.
;------------------------------------------------------------------------------
dri_xref_branch:	; from: obj_xref_pcrel_word
	move.w	d2,(a5)+                        ; the value
	bsr.s	dri_xref_term                   ; the term
	bmi.s	dri_restriction                 ; a section: not allowed
	ori.b	#$6,d0                          ; external, PC relative
	move.w	d0,-$2(a5,d2.l)
	rts

;------------------------------------------------------------------------------
; The DRI relocation word for the section d0 (0, 12 or 24): 2 text, 1 data, 3 BSS.
;------------------------------------------------------------------------------
dri_section_word:	; from: dri_xref_long
	tst.b	d0                              ; text?
	beq.s	dri_section_text                ; yes
	cmp.b	#$c,d0                          ; data?
	beq.s	dri_section_data                ; yes
	moveq	#3,d0                           ; BSS based
	rts
dri_section_text:
	moveq	#2,d0                           ; text based
	rts
dri_section_data:
	moveq	#1,d0                           ; data based
	rts

;------------------------------------------------------------------------------
; For OSS: the d1 bytes of code at a0 and their relocation words after them made into one buffer of code
; and relocation words in turn.  Out: a0, d1 = what to write.  Z set on entry (no code) or DRI: no change.
;------------------------------------------------------------------------------
dri_interleave:	; from: dri_finish
	beq.s	dri_interleave_done             ; no code
	tst.b	oss_format(a6)                  ; OSS?
	beq.s	dri_interleave_done             ; no
	movem.l	d1/a0,-(sp)
	add.l	d1,d1                           ; twice the size
	bsr.w	alloc_block                     ; allocate it
	movem.l	(sp)+,d1/a1                     ; the code
	move.l	a0,-(sp)
	move.l	d1,d0
	lsr.l	#1,d0                           ; in words
	lea	0(a1,d1.l),a2                   ; its relocation words
dri_interleave_loop:
	move.w	(a1)+,(a0)+                     ; a code word
	move.w	(a2)+,(a0)+                     ; its relocation word
	subq.l	#1,d0
	bne.s	dri_interleave_loop
	movea.l	(sp)+,a0                        ; the new buffer
	add.l	d1,d1                           ; its size
dri_interleave_done:
	rts

;------------------------------------------------------------------------------
; End of the assembly, DRI: header, text, data, symbol table, relocation, then the symbol table's size into
; the header.
;------------------------------------------------------------------------------
dri_finish:	; from: obj_finish
	bsr.w	binary_create                   ; open the output file
	lea	line_code(a6),a0                ; make the header
	move.w	#$601a,(a0)+                    ; the magic
	move.l	text_size(a6),(a0)+             ; the text size
	move.l	data_size(a6),(a0)+             ; the data size
	move.l	bss_size(a6),(a0)+              ; the BSS size
	clr.l	(a0)+                           ; the symbol table size, set later
	clr.l	(a0)+                           ; reserved
	clr.l	(a0)+
	moveq	#0,d0                           ; DRI
	tst.b	oss_format(a6)                  ; OSS?
	beq.s	dri_finish_header               ; no
	move.w	#$4a4c,d0                       ; yes: its mark
dri_finish_header:
	move.w	d0,(a0)+
	lea	line_code(a6),a0
	moveq	#28,d1                          ; 28 bytes
	bsr.w	binary_write                    ; write it
	movea.l	exe_text_buffer(a6),a0          ; the text
	move.l	text_size(a6),d1                ; its size
	bsr.s	dri_interleave                  ; interleaved for OSS
	bsr.w	binary_write                    ; write it
	movea.l	data_buffer(a6),a0              ; the data
	move.l	data_size(a6),d1
	bsr.s	dri_interleave
	bsr.w	binary_write                    ; write it
	clr.l	symbol_table_size(a6)           ; no symbol table yet
	movea.l	asm_module_tree(a6),a1          ; the module's symbols
	movea.l	(a1),a1
	move.l	a1,d0                           ; any?
	beq.w	dri_finish_symbols              ; no
	moveq	#0,d7                           ; the XREFs from number 1
	movea.l	current_module(a6),a0           ; the module
	move.w	$14(a0),d6                      ; its XREF count
dri_finish_xrefs:
	cmp.w	d6,d7                           ; all of them?
	beq.w	dri_finish_symbols              ; yes
	addq.w	#1,d7                           ; the next
	move.l	sp,gst_buffer_size(a6)          ; the stack, to leave the walk when found
	movea.l	asm_module_tree(a6),a1
	movea.l	(a1),a1                         ; the symbol tree
	bsr.s	dri_find_xref                   ; find that XREF
	trap	#15                             ; not found: cannot happen
dri_finish_xref_found:	; from: dri_find_xref
	move.w	#$8800,d2                       ; defined, external
	moveq	#0,d3                           ; value 0
	bsr.s	dri_symbol_record               ; its record
	bra.s	dri_finish_xrefs

;------------------------------------------------------------------------------
; Write a 14-byte DRI symbol record for the symbol a1: 8 characters of name, the type d2, the value d3; count
; it in the symbol table size.  A write error stops the assembly.
;------------------------------------------------------------------------------
dri_symbol_record:	; from: dri_finish, dri_symbol
	lea	line_code(a6),a0                ; the record
	moveq	#0,d0
	move.l	d0,(a0)                         ; the name cleared
	move.l	d0,4(a0)
	move.b	$16(a1),d0                      ; the name's length
	lea	$17(a1),a2                      ; the name
	cmp.w	#$9,d0                          ; 9 or more?
	bcs.s	dri_symbol_record_count         ; no
	moveq	#7,d0                           ; yes: 8
dri_symbol_record_name:
	move.b	(a2)+,(a0)+
dri_symbol_record_count:
	dbra	d0,dri_symbol_record_name
	lea	line_code(a6),a0
	move.w	d2,8(a0)                        ; the type
	move.l	d3,$a(a0)                       ; the value
	moveq	#14,d1                          ; 14 bytes
	add.l	d1,symbol_table_size(a6)        ; the symbol table grows
	move.l	a1,-(sp)
	bsr.w	output_write                    ; write it
	movea.l	(sp)+,a1
	bne.w	binary_write_error              ; error during writing binary file
	rts

;------------------------------------------------------------------------------
; Walk the symbol tree a1 for the XREF numbered d7; when found, leave the walk with a1 on it.
;------------------------------------------------------------------------------
dri_find_xref:	; from: dri_finish
	tst.l	(a1)                            ; a left branch?
	beq.s	dri_find_xref_node              ; no
	move.l	a1,-(sp)
	movea.l	(a1),a1
	bsr.s	dri_find_xref                   ; walk it
	movea.l	(sp)+,a1
dri_find_xref_node:
	btst	#$4,$c(a1)                      ; an XREF?
	beq.s	dri_find_xref_right             ; no
	cmp.w	$14(a1),d7                      ; the one wanted?
	bne.s	dri_find_xref_right             ; no
	movea.l	gst_buffer_size(a6),sp          ; yes: leave the walk
	bra.s	dri_finish_xref_found
dri_find_xref_right:
	tst.l	4(a1)                           ; a right branch?
	beq.s	dri_find_xref_done              ; no
	move.l	a1,-(sp)
	movea.l	4(a1),a1
	bsr.s	dri_find_xref                   ; walk it
	movea.l	(sp)+,a1
dri_find_xref_done:
	rts

;------------------------------------------------------------------------------
; Called for each symbol a1: XDEFs, and with debug on all the others, get a DRI symbol record; XREFs were
; written already.
;------------------------------------------------------------------------------
dri_symbol:
	move.w	#$2000,d2                       ; global
	btst	#$4,$c(a1)                      ; an XREF?
	bne.s	dri_symbol_done                 ; yes: done already
	btst	#$5,$c(a1)                      ; an XDEF?
	bne.s	dri_symbol_type                 ; yes
	moveq	#0,d2                           ; local
	tst.b	debug_symbols(a6)               ; debug symbols?
	beq.s	dri_symbol_done                 ; no
dri_symbol_type:
	move.b	$d(a1),d0                       ; the type
	cmp.b	#$1,d0                          ; a label?
	beq.s	dri_symbol_label                ; yes
	cmp.b	#$2,d0                          ; an equate?
	bne.s	dri_symbol_done                 ; no: none
	moveq	#14,d3                          ; equated
	bra.s	dri_symbol_write
dri_symbol_label:
	moveq	#9,d3                           ; text based
	move.b	$e(a1),d0                       ; the section
	beq.s	dri_symbol_write                ; text
	moveq	#10,d3                          ; data based
	cmp.b	#$c,d0                          ; data?
	beq.s	dri_symbol_write                ; yes
	moveq	#8,d3                           ; BSS based
dri_symbol_write:
	bset	d3,d2
	ori.w	#$8000,d2                       ; defined
	move.l	8(a1),d3                        ; the value
	move.l	a2,-(sp)
	bsr.w	dri_symbol_record               ; its record
	movea.l	(sp)+,a2
dri_symbol_done:
	rts
dri_finish_symbols:	; from: dri_finish
	movea.l	current_module(a6),a1           ; the module
	lea	dri_symbol(pc),a2               ; for each symbol
	bsr.w	module_walk_locals              ; of the module's symbol tree
	movea.l	equate_tree(a6),a1              ; the global symbols
	movea.l	(a1),a1
	move.l	a1,d0                           ; any?
	beq.s	dri_finish_relocation           ; no
	bsr.w	symbol_tree_each                ; for each of them too
dri_finish_relocation:
	tst.b	oss_format(a6)                  ; OSS?
	bne.s	dri_finish_size                 ; yes: written with the code
	movea.l	exe_text_buffer(a6),a0          ; the text
	move.l	text_size(a6),d1                ; its size
	adda.l	d1,a0                           ; its relocation words
	bsr.w	binary_write                    ; write them
	movea.l	data_buffer(a6),a0              ; the data
	move.l	data_size(a6),d1
	adda.l	d1,a0                           ; its relocation words
	bsr.w	binary_write                    ; write them
dri_finish_size:
	tst.l	symbol_table_size(a6)           ; any symbols?
	beq.s	dri_finish_done                 ; no
	moveq	#14,d2                          ; the header's symbol table size
	bsr.w	output_seek                     ; Fseek there
	lea	symbol_table_size(a6),a0
	moveq	#4,d1
	bsr.w	binary_write                    ; write it
dri_finish_done:
	rts

;------------------------------------------------------------------------------
; The output's description for the report: a0 = "DRI linkable" or "OSS linkable".
;------------------------------------------------------------------------------
dri_format_name:	; from: obj_print_format
	lea	str_dri_linkable(pc),a0
	tst.b	oss_format(a6)                  ; OSS?
	beq.s	dri_format_name_done            ; no
	lea	str_oss_linkable(pc),a0
dri_format_name_done:
	rts

;------------------------------------------------------------------------------
; The output file's default extension: a0 = ".O".
;------------------------------------------------------------------------------
dri_extension:	; from: obj_extension
	lea	str_ext_o(pc),a0
	rts
str_dri_linkable:	; from: dri_format_name
	dc.b	'DRI linkable',0                ; the format's description
str_oss_linkable:	; from: dri_format_name
	dc.b	'OSS linkable',0                ; the format's description for OSS

;------------------------------------------------------------------------------
; ".O", a 0 pad byte, then label_start_chars for the characters $80-$ff (b6ea-b769).
;------------------------------------------------------------------------------
str_ext_o:	; from: dri_extension
	dc.w	$2e4f,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; ".O",0,0 then for $80-$ff: accented letters 0
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0001
	dc.w	$0101,$0001,$0000,$0000,$0000,$0000,$0101,$0101
	dc.w	$0100,$0101,$0000,$0000,$0000,$0000,$0001,$0101
	dcb.w	34,$0101                        ; $a8-$ff: not letters

;------------------------------------------------------------------------------
; 0 for a character that can start a label: letters, '.', '_' and the accented letters; 1 for the others.
; Indexed by the signed character: $80-$ff are in the 128 bytes before.
;------------------------------------------------------------------------------
label_start_chars:	; from: asm_line
	dcb.w	23,$0101                        ; $00-$2d: no
	dc.w	$0001,$0101,$0101,$0101,$0101,$0101,$0101,$0101 ; '.' yes, '/'-'9' no
	dc.w	$0101,$0100,$0000,$0000,$0000,$0000,$0000,$0000 ; ':'-'@' no, 'A'-'Z' yes
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0101
	dc.w	$0100,$0100,$0000,$0000,$0000,$0000,$0000,$0000 ; '[' to '^' no, '_' yes, '`' no
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0101 ; 'a'-'z' yes
	dc.w	$0101                           ; '{' to $7f: no

;------------------------------------------------------------------------------
; The upper-case table, copied to -2(a6) at the start: for $80-$ff (the Atari's accented letters to their
; capitals) then $00-$7f, so that $7e(a6) indexed by the signed character upper-cases it.
;------------------------------------------------------------------------------
upper_case_table:	; from: asm_entry
	dc.w	$809a,$9083,$8eb6,$8f80,$8889,$8a8b,$8c8d,$8e8f ; $80-$8f
	dc.w	$9092,$9293,$9995,$9697,$9899,$9a9b,$9c9d,$9e9f ; $90-$9f
	dc.w	$a0a1,$a2a3,$a5a5,$a6a7,$a8a9,$aaab,$acad,$aeaf ; $a0-$af
	dc.w	$b7b8,$b2b2,$b4b4,$b6b7,$b8b9,$babb,$bcbd,$bebf ; $b0-$bf
	dc.w	$c1c1,$c2c3,$c4c5,$c6c7,$c8c9,$cacb,$cccd,$cecf ; $c0-$cf
	dc.w	$d0d1,$d2d3,$d4d5,$d6d7,$d8d9,$dadb,$dcdd,$dedf ; $d0-$df
	dc.w	$e0e1,$e2e3,$e4e5,$e6e7,$e8e9,$eaeb,$eced,$eeef ; $e0-$ef
	dc.w	$f0f1,$f2f3,$f4f5,$f6f7,$f8f9,$fafb,$fcfd,$feff ; $f0-$ff
	dc.w	$0001,$0203,$0405,$0607,$0809,$0a0b,$0c0d,$0e0f ; $00-$0f
	dc.w	$1011,$1213,$1415,$1617,$1819,$1a1b,$1c1d,$1e1f ; $10-$1f
	dc.b	' !"#$%&',$27                   ; $20-$7f: a-z to A-Z
	dc.b	'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\]^_`ABCDEFG'
	dc.b	'HIJKLMNOPQRSTUVWXYZ{|}~'
	dc.b	$7f

;------------------------------------------------------------------------------
; For each character 0-255: 0 for one that can be in a symbol (letters, digits, '_', '?', '@', accented
; letters), $ff for '.', 1 for one that ends a symbol.
;------------------------------------------------------------------------------
symbol_chars:	; from: parse_register, ea_special_register, read_symbol_name
	dcb.w	23,$0101                        ; $00-$2d: end
	dc.w	$ff01,$0000,$0000,$0000,$0000,$0000,$0101,$0101 ; '.' $ff, '/' end, '0'-'5' in
	dc.w	$0100,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; '6'-'9' in, ':'-'>' end, '?'-'O' in
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0101
	dc.w	$0100,$0100,$0000,$0000,$0000,$0000,$0000,$0000 ; '['-'^' end, '_' in, '`' end, 'a'-'o' in
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0101
	dc.w	$0101,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; '{'-$7f end, $80 on accented letters in
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0101
	dc.w	$0001,$0000,$0000,$0000,$0000,$0101,$0101,$0100
	dc.w	$0101,$0000,$0000,$0000,$0000,$0001,$0101,$0101 ; $a8 on: end
	dc.w	$0101,$0101,$0101,$0101,$0101,$0101,$0101,$0101
	dcb.w	25,$0101

;------------------------------------------------------------------------------
; Show the character d1 on the screen (Cconout).
;------------------------------------------------------------------------------
dos_cconout:	; from: screen_char
	andi.w	#$ff,d1
	move.w	d1,-(sp)
	move.w	#$2,-(sp)
	trap	#1                              ; Cconout, Cconout: show it
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; Write d1 bytes at a0 to the file d3.  Out: Z set when all were written.
;------------------------------------------------------------------------------
file_write:	; from: listing_flush
	move.l	d1,-(sp)
	move.l	a0,-(sp)
	move.l	d1,-(sp)
	move.w	d3,-(sp)
	move.w	#$40,-(sp)
	trap	#1                              ; Fwrite, Fwrite: write them
	lea	$c(sp),sp
	move.l	(sp)+,d1
	cmp.l	d0,d1                           ; all of them?
	rts

;------------------------------------------------------------------------------
; Close the listing's handle d3: a device (negative) or 0-4 is closed, 5 and up are not.
;------------------------------------------------------------------------------
listing_close_handle:	; from: listing_close_file
	tst.w	d3                              ; a device?
	bmi.s	listing_close_now               ; yes: close it
	cmp.w	#$5,d3                          ; 5 and up?
	bcc.s	listing_close_handle_done       ; yes: leave it
listing_close_now:
	move.w	d3,-(sp)
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose, Fclose: close it
	addq.l	#4,sp
listing_close_handle_done:
	rts

;------------------------------------------------------------------------------
; The assembler's start, called first: a5 = its basepage.  Under about 33 K of memory it ends (Pterm -39).
; a6 = the basepage's BSS + 2, the stack at $4768(a6), the heap from $62fc(a6) to 4000 bytes below the
; memory's top, and the rest given back (Mshrink).
;------------------------------------------------------------------------------
asm_startup:	; from: asm_entry
	movea.l	(sp)+,a3                        ; the return address
	movea.l	4(sp),a5                        ; the basepage
	move.l	4(a5),d0                        ; the memory's top
	sub.l	(a5),d0                         ; less its start: the memory there is
	subi.l	#$fa0,d0                        ; less 4000 kept
	bcs.s	asm_startup_fail                ; not enough
	cmp.l	#$739a,d0                       ; enough?
	bcs.s	asm_startup_fail                ; no
	movea.l	$18(a5),a6                      ; the variables
	addq.w	#2,a6
	move.l	a5,basepage(a6)                 ; the basepage
	lea	asm_stack_top(a6),sp            ; the stack
	lea	0(a5,d0.l),a0
	move.l	a0,heap_end(a6)                 ; the heap's end
	lea	heap_base(a6),a0                ; the heap starts after the variables
	move.l	a0,heap_start(a6)
	clr.l	heap_last(a6)                   ; no last block
	move.l	d0,-(sp)                        ; the size kept
	move.l	a5,-(sp)                        ; the basepage
	clr.w	-(sp)
	move.w	#$4a,-(sp)
	trap	#1                              ; Mshrink, Mshrink: give the rest back
	lea	$c(sp),sp
	tst.l	d0                              ; done?
	bne.s	asm_startup_fail                ; no
	sf	wait_at_exit(a6)                ; no key wait at the end yet
	jmp	(a3)
asm_startup_fail:
	move.w	#$ffd9,-(sp)                    ; -39: out of memory
	move.w	#$4c,-(sp)
	trap	#1                              ; Pterm, Pterm: end

;------------------------------------------------------------------------------
; Read the options.  From the editor (\0AMP at its parent's basepage +$80): the source's start and end, the
; error list, the program buffer and its end.  Then the command line ("Enter command line:" when there is
; none): the source file's name, then options from '-': B C D E L M O P Q S T X Z.  Out: d0 = -1 (NE) for
; none or an invalid one, else Z set.  Defaults: binary on, executable output, the clock started.
;------------------------------------------------------------------------------
command_line:	; from: asm_entry
	clr.l	memory_source(a6)               ; no source in memory
	clr.l	asm_source_end(a6)
	movea.l	basepage(a6),a0                 ; the basepage
	movea.l	$24(a0),a0                      ; its parent's
	lea	$80(a0),a0                      ; the parent's command line
	cmpi.l	#$414d50,(a0)+                  ; \0AMP: from the editor?
	bne.s	command_line_defaults           ; no
	move.l	(a0)+,memory_source(a6)         ; the source's start
	move.l	(a0)+,asm_source_end(a6)        ; and its end
	movea.l	(a0)+,a1                        ; the error list
	move.l	a1,editor_error_list(a6)
	move.l	a1,d0                           ; any?
	beq.s	command_line_memory             ; no
	clr.w	2(a1)                           ; empty it
command_line_memory:
	move.l	(a0)+,program_buffer(a6)        ; the program buffer: assemble to memory
	beq.s	command_line_buffer_end         ; none
	movea.l	program_buffer(a6),a1
	clr.w	(a1)                            ; not complete
command_line_buffer_end:
	move.l	(a0)+,program_buffer_end(a6)    ; its end
command_line_defaults:
	clr.l	cmdline_case(a6)                ; no -C -L -S -P
	clr.b	cmdline_z(a6)                   ; no -Z
	clr.b	output_base_name(a6)            ; no output name base
	clr.b	cmdline_small_buffers(a6)       ; no -M
	st	binary_on(a6)                   ; binary on
	sf	cmdline_linkable(a6)            ; not linkable
	clr.w	linker_format(a6)               ; GST if linkable
	move.l	heap_end(a6),d0                 ; the heap's end
	sub.l	heap_start(a6),d0               ; less its start
	move.l	d0,memory_total(a6)             ; the memory there is
	bsr.w	read_clock                      ; the clock
	move.l	d0,start_time(a6)               ; at the start
	movea.l	basepage(a6),a0                 ; the basepage
	lea	$80(a0),a0                      ; its command line
	moveq	#0,d0
	move.b	(a0)+,d0                        ; its length
	bne.s	command_line_parse              ; something there
	st	wait_at_exit(a6)                ; none: wait for a key at the end
	move.l	a0,-(sp)
	pea	str_enter_command_line(pc)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws, Cconws: "Enter command line:"
	addq.l	#6,sp
	movea.l	(sp)+,a0
	move.b	#$4c,-(a0)                      ; up to 76 characters
	move.l	a0,-(sp)                        ; into the basepage's command line
	move.w	#$a,-(sp)
	trap	#1                              ; Cconrs, Cconrs: read the line
	addq.l	#6,sp
	pea	str_new_line(pc)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws, Cconws: a new line
	addq.l	#6,sp
	movea.l	basepage(a6),a0                 ; the basepage
	lea	$81(a0),a0                      ; the count read
	moveq	#0,d0
	move.b	(a0)+,d0
	bne.s	command_line_typed              ; something there
	sf	wait_at_exit(a6)                ; nothing: no key wait
	moveq	#-1,d0                          ; none
	rts
command_line_typed:
	movem.l	d0/a0,-(sp)
	bsr.w	read_clock                      ; the clock
	move.l	d0,start_time(a6)               ; starts again
	movem.l	(sp)+,d0/a0
command_line_parse:
	clr.b	0(a0,d0.w)                      ; two 0s end the line
	clr.b	1(a0,d0.w)
	clr.b	listing_name(a6)                ; no listing name
command_line_next:
	move.b	(a0)+,d1                        ; the next character
	beq.w	command_line_end                ; the end
	cmp.b	#$20,d1                         ; a space?
	beq.s	command_line_next               ; yes: skip it
	cmp.b	#$2d,d1                         ; an option?
	beq.w	command_line_option             ; yes
	lea	output_base_name(a6),a1         ; a name: the output name base
	lea	source_name(a6),a2              ; the source's name
	move.l	a2,source_record(a6)            ; its record points to it
	clr.b	source_name_length(a6)          ; length 0
	lea	source_dir(a6),a3               ; the path
command_line_name_part:
	moveq	#0,d3                           ; no dot in this part
command_line_name_char:
	move.b	d1,(a2)+                        ; into the source's name
	move.b	d1,(a1)+                        ; the base
	move.b	d1,(a3)+                        ; and the path
	addq.b	#1,source_name_length(a6)
	move.b	(a0)+,d1                        ; the next
	beq.s	command_line_name_end           ; the name's end?
	cmp.b	#$20,d1
	beq.s	command_line_name_end
	cmp.b	#$5c,d1                         ; a folder's end?
	beq.s	command_line_name_part          ; yes: no dot yet
	cmp.b	#$2e,d1                         ; a dot?
	bne.s	command_line_name_char          ; no
	move.l	a1,d3                           ; yes: the base ends there
	bra.s	command_line_name_char
command_line_name_end:
	tst.l	d3                              ; a dot?
	bne.s	command_line_name_dot           ; yes
	clr.b	(a1)                            ; no: the base is all of it
	move.b	#$2e,(a2)+                      ; the source gets .S
	move.b	#$73,(a2)+
	addq.b	#2,source_name_length(a6)
	bra.s	command_line_name_done
command_line_name_dot:
	movea.l	d3,a1                           ; the base ends at the dot
	clr.b	(a1)
command_line_name_done:
	move.b	#$b,(a2)                        ; the name's end mark
	addq.b	#1,source_name_length(a6)
	clr.b	(a3)+                           ; the path's end
	move.l	a0,-(sp)
	lea	source_dir(a6),a0               ; the path
	bsr.w	find_file_name                  ; past its folders
	move.l	a0,source_dir_end(a6)           ; include files go there
	clr.b	(a0)                            ; the path is only the folders
	movea.l	(sp)+,a0
	lea	source_record(a6),a1            ; the source's record
	tst.l	memory_source(a6)               ; the source in memory?
	bne.w	command_line_next               ; yes: no file
	move.l	a1,asm_source_name(a6)          ; the file to assemble
	bra.w	command_line_next
command_line_option:
	move.b	(a0)+,d1                        ; the option's letter
	beq.w	command_line_end                ; the end
	cmp.b	#$20,d1                         ; a space?
	beq.s	command_line_end                ; yes: the end
	ext.w	d1
	move.b	upper_case(a6,d1.w),d1          ; upper case
	cmp.b	#$50,d1                         ; P?
	beq.w	option_listing                  ; listing
	cmp.b	#$53,d1                         ; S?
	beq.s	option_symbols                  ; symbol table
	cmp.b	#$4c,d1                         ; L?
	beq.w	option_linkable                 ; linkable
	cmp.b	#$43,d1                         ; C?
	beq.s	option_case                     ; case
	cmp.b	#$51,d1                         ; Q?
	beq.s	option_quit_wait                ; key wait
	cmp.b	#$44,d1                         ; D?
	beq.s	option_debug                    ; debug
	cmp.b	#$58,d1                         ; X?
	beq.s	option_debug_extended           ; extended debug
	cmp.b	#$4d,d1                         ; M?
	beq.s	option_small_buffers            ; small buffers
	cmp.b	#$42,d1                         ; B?
	beq.s	option_no_binary                ; no binary
	cmp.b	#$54,d1                         ; T?
	beq.w	option_tab                      ; tab width
	cmp.b	#$4f,d1                         ; O?
	beq.w	option_output                   ; output name
	cmp.b	#$45,d1                         ; E?
	beq.w	option_symbols_line             ; symbols
	cmp.b	#$5a,d1                         ; Z?
	beq.w	option_z
	bra.w	command_line_invalid            ; else invalid
command_line_end:
	move.l	asm_source_name(a6),d0          ; a source file
	or.l	memory_source(a6),d0            ; or one in memory?
	beq.w	command_line_invalid            ; no: invalid
	tst.b	asm_listing_wanted(a6)          ; a listing?
	bne.w	listing_create                  ; yes: create it
	rts                                     ; Z set: ready
option_symbols:
	st	cmdline_symbol_table(a6)        ; -S: the symbol table at the listing's end
	bra.w	command_line_option
option_case:
	st	cmdline_case(a6)                ; -C: labels in any case
	bra.w	command_line_option
option_quit_wait:
	st	wait_at_exit(a6)                ; -Q: wait for a key at the end
	bra.w	command_line_option
option_debug:
	move.b	#$1,debug_symbols(a6)           ; -D: debug symbols
	bra.w	command_line_option
option_debug_extended:
	st	debug_symbols(a6)               ; -X: debug symbols with long names
	bra.w	command_line_option
option_small_buffers:
	st	cmdline_small_buffers(a6)       ; -M: buffers at their smallest
	bra.w	command_line_option
option_no_binary:
	sf	binary_on(a6)                   ; -B: no binary file
	bra.w	command_line_option
option_linkable:
	st	cmdline_linkable(a6)            ; -L: linkable, GST
	move.b	(a0),d0                         ; a 2 after it?
	subi.b	#$32,d0
	bcs.w	command_line_option             ; no
	addq.b	#1,d0
	ext.w	d0
	cmp.w	#$2,d0                          ; 2?
	bcc.w	command_line_option             ; no
	move.w	d0,linker_format(a6)            ; -L2: DRI
	addq.l	#1,a0                           ; past it
	bra.w	command_line_option
option_z:
	st	cmdline_z(a6)                   ; -Z: the listing routine runs in pass 1 too
	bra.w	command_line_option
command_line_invalid:	; from: listing_create
	lea	str_invalid_command_line(pc),a0 ; "Invalid command line - see manual"
	bsr.w	print_string
	moveq	#-1,d0
	rts
option_tab:
	moveq	#0,d2                           ; -T: the listing's tab width, 1-99
	move.b	(a0)+,d2                        ; a digit
	subi.b	#$30,d2
	bcs.s	command_line_invalid            ; no: invalid
	cmp.b	#$a,d2
	bcc.s	command_line_invalid            ; no: invalid
	move.w	d2,tab_width(a6)
	move.b	(a0),d1                         ; a second digit?
	cmp.b	#$30,d1
	bcs.s	option_tab_check                ; no
	cmp.b	#$3a,d1
	bcc.s	option_tab_check                ; no
	mulu.w	#$a,d2                          ; tens
	subi.b	#$30,d1
	andi.w	#$ff,d1
	add.w	d1,d2
	move.w	d2,tab_width(a6)
	addq.l	#1,a0                           ; past it
option_tab_check:
	tst.w	tab_width(a6)                   ; 0?
	bne.w	command_line_option             ; no: on
	bra.s	command_line_invalid            ; yes: invalid
option_output:
	st	binary_on(a6)                   ; -O: the output file's name; binary on
	lea	asm_output_name(a6),a1
option_output_copy:
	move.b	(a0)+,d1
	beq.s	option_output_end               ; the end
	cmp.b	#$20,d1                         ; a space?
	beq.s	option_output_end               ; yes: the end
	move.b	d1,(a1)+
	bra.s	option_output_copy
option_output_end:
	clr.b	(a1)
option_name_done:
	subq.l	#1,a0                           ; back on the end
	bra.w	command_line_next               ; on with the command line
option_listing:
	st	cmdline_listing(a6)             ; -P: a listing
	move.l	#$3,listing_handle(a6)          ; to the printer
	st	asm_listing_wanted(a6)          ; listing on
	move.b	(a0),d1                         ; a name after it?
	beq.s	option_name_done                ; no
	cmp.b	#$20,d1
	beq.s	option_name_done                ; no
	lea	listing_name(a6),a1             ; the listing file's name
option_listing_copy:
	move.b	(a0)+,d1
	beq.s	option_listing_end              ; the end
	cmp.b	#$20,d1                         ; a space?
	beq.s	option_listing_end              ; yes: the end
	move.b	d1,(a1)+
	bra.s	option_listing_copy
option_listing_end:
	clr.b	(a1)
	subq.l	#1,a0                           ; back on the end
	bra.w	command_line_next               ; on with the command line
option_symbols_line:
	move.l	a0,asm_cmdline_symbols(a6)      ; -E: the rest of the line is symbol definitions
	bra.w	command_line_end                ; the end of the options

;------------------------------------------------------------------------------
; Find the file name in the path a0, past the last \ or colon.  Out: a0 = it and d0 = 0 (Z set), or a0 the
; path's start and d0 = -1 when there is no folder or drive.
;------------------------------------------------------------------------------
find_file_name:	; from: command_line, open_include
	moveq	#0,d0                           ; none yet
	movea.l	a0,a1                           ; the start
find_file_name_loop:
	move.b	(a0)+,d1
	beq.s	find_file_name_end              ; the end
	cmp.b	#$5c,d1                         ; \?
	beq.s	find_file_name_mark             ; yes
	cmp.b	#$3a,d1                         ; a colon?
	bne.s	find_file_name_loop             ; no
find_file_name_mark:
	move.l	a0,d0                           ; the name starts after it
	bra.s	find_file_name_loop
find_file_name_end:
	tst.l	d0                              ; any?
	bne.s	find_file_name_found            ; yes
	movea.l	a1,a0                           ; no: the start
	moveq	#-1,d0
	rts
find_file_name_found:
	movea.l	d0,a0
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Create the listing file: its name from -P, else the source's name with .LST.  An error is an invalid
; command line.
;------------------------------------------------------------------------------
listing_create:	; from: command_line
	lea	listing_name(a6),a0             ; the name given
	tst.b	(a0)                            ; any?
	bne.s	listing_create_open             ; yes
	lea	source_record(a6),a1            ; no: the source's name
	moveq	#0,d2                           ; no dot yet
	move.b	5(a1),d0                        ; its length
	subq.b	#1,d0                           ; less its end mark
	movea.l	(a1),a1
listing_create_copy:
	move.b	(a1)+,d1
	cmp.b	#$5c,d1                         ; a folder's end?
	beq.s	listing_create_folder           ; yes
	cmp.b	#$2e,d1                         ; a dot?
	bne.s	listing_create_char             ; no
	move.l	a0,d2                           ; yes: the name ends there
	bra.s	listing_create_char
listing_create_folder:
	moveq	#0,d2                           ; no dot yet
listing_create_char:
	move.b	d1,(a0)+
	subq.b	#1,d0
	bne.s	listing_create_copy
	tst.l	d2                              ; a dot?
	beq.s	listing_create_ext              ; no
	movea.l	d2,a0                           ; yes: the extension goes there
listing_create_ext:
	move.b	#$2e,(a0)+                      ; .LST
	move.b	#$4c,(a0)+
	move.b	#$53,(a0)+
	move.b	#$54,(a0)+
	clr.b	(a0)+
	lea	listing_name(a6),a0
listing_create_open:
	clr.w	-(sp)
	move.l	a0,-(sp)
	move.w	#$3c,-(sp)
	trap	#1                              ; Fcreate, Fcreate: make the listing file
	addq.l	#8,sp
	tst.l	d0                              ; made?
	bmi.w	command_line_invalid            ; no: invalid
	move.l	d0,listing_handle(a6)           ; the listing's handle
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; End the listing's page when the listing is going out (listing_page_end_now does not check that).
;------------------------------------------------------------------------------
listing_page_end:	; from: asm_entry, dir_page
	tst.b	asm_listing_active(a6)          ; listing out?
	beq.s	listing_page_end_done           ; no

;------------------------------------------------------------------------------
; With paging on and a page started: a new line and a form feed, then the next line starts a page.
;------------------------------------------------------------------------------
listing_page_end_now:	; from: listing_close, listing_end_line
	tst.w	page_line(a6)                   ; a page started?
	bmi.s	listing_page_end_done           ; no
	btst	#$0,listing_format(a6)          ; paging?
	beq.s	listing_page_end_done           ; no
	moveq	#13,d1
	bsr.w	listing_put_char
	moveq	#10,d1
	bsr.w	listing_put_char                ; a new line
	moveq	#12,d1
	bsr.w	listing_put_char                ; a form feed
	clr.w	listing_column(a6)              ; column 0
	move.w	#$ffff,page_line(a6)            ; no page started
listing_page_end_done:	; from: listing_page_end
	rts

;------------------------------------------------------------------------------
; Show " N bytes used out of M, took S.T seconds".
;------------------------------------------------------------------------------
show_memory_time:	; from: asm_finish
	bsr.s	read_clock                      ; the clock
	move.l	d0,-(sp)
	move.l	memory_total(a6),d1             ; the memory there was
	sub.l	heap_end(a6),d1                 ; less the heap's end
	add.l	heap_start(a6),d1               ; and its start: used
	bsr.w	print_decimal                   ; in decimal
	pea	str_bytes_used(pc)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws, Cconws: " bytes used out of "
	addq.l	#6,sp
	move.l	memory_total(a6),d1             ; the memory there was
	bsr.w	print_decimal
	pea	str_took(pc)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws, Cconws: ", took "
	addq.l	#6,sp
	move.l	(sp)+,d2                        ; the clock now
	sub.l	start_time(a6),d2               ; less at the start
	divu.w	#$c8,d2                         ; 200 ticks a second
	move.l	d2,-(sp)
	moveq	#0,d1
	move.w	d2,d1                           ; the seconds
	bsr.w	print_decimal
	moveq	#46,d1                          ; .
	bsr.w	asm_output_char
	move.l	(sp)+,d2
	clr.w	d2                              ; the ticks left
	swap	d2
	divu.w	#$14,d2                         ; in tenths
	moveq	#48,d1
	add.b	d2,d1                           ; as a digit
	bsr.w	asm_output_char
	pea	str_seconds(pc)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws, Cconws: " seconds"
	addq.l	#6,sp
	bra.w	print_newline                   ; a new line

;------------------------------------------------------------------------------
; d0 = the 200 Hz clock (_hz_200), read in supervisor mode.
;------------------------------------------------------------------------------
read_clock:	; from: command_line, show_memory_time
	pea	read_clock_super(pc)
	move.w	#$26,-(sp)
	trap	#14                             ; Supexec, Supexec: read it
	addq.l	#6,sp
	rts
read_clock_super:
	move.l	$4ba.w,d0                       ; _hz_200, _hz_200: the 200 Hz tick count
	rts
str_bytes_used:	; from: show_memory_time
	dc.b	' bytes used out of ',0
str_took:	; from: show_memory_time
	dc.b	', took ',0
str_seconds:	; from: show_memory_time
	dc.b	' seconds',0
str_enter_command_line:	; from: command_line
	dc.b	'Enter command line:'           ; the prompt when there is no command line
str_new_line:	; from: command_line
	dc.w	$0d0a                           ; CR LF
	dc.b	$00
str_press_key:	; from: asm_exit
	dc.b	13,10,'Press a key to exit',0
str_invalid_command_line:	; from: command_line
	dc.b	'Invalid command line - see manual',13,0

;------------------------------------------------------------------------------
; The assembler's end: when asked, wait for a key; then Pterm with the exit code (0, 5 warnings, 10 errors,
; 20 fatal, 100 no assembly).
;------------------------------------------------------------------------------
asm_exit:	; from: asm_finish
	tst.b	wait_at_exit(a6)                ; wait for a key?
	beq.s	asm_exit_end                    ; no
	pea	str_press_key(pc)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws, Cconws: "Press a key to exit"
	addq.l	#6,sp
asm_exit_flush:
	move.l	#$600ff,-(sp)
	trap	#1                              ; Crawio, Crawio: a key waiting?
	addq.l	#4,sp
	tst.w	d0
	bne.s	asm_exit_flush                  ; yes: throw it away
asm_exit_key:
	move.w	#$7,(sp)                        ; Cnecin
	trap	#1                              ; GEMDOS, Cnecin: wait for a key
	cmp.b	#$d,d0                          ; Return?
	beq.s	asm_exit_end                    ; yes
	cmp.b	#$20,d0                         ; a control key?
	bcs.s	asm_exit_key                    ; yes: wait on
asm_exit_end:
	move.b	return_code(a6),d0              ; the exit code
	ext.w	d0
	move.w	d0,-(sp)
	move.w	#$4c,-(sp)
	trap	#1                              ; Pterm, Pterm: end

;------------------------------------------------------------------------------
; Put the date and time at a3: "DD/MM/YY  HH:MM:SS", or "MM/DD/YY" when shift 3 is '#' (a US keyboard).
;------------------------------------------------------------------------------
date_time_string:	; from: listing_init
	moveq	#-1,d0
	move.l	d0,-(sp)
	move.l	d0,-(sp)
	move.l	d0,-(sp)
	move.w	#$10,-(sp)
	trap	#14                             ; Keytbl, Keytbl: the keyboard's tables
	lea	$e(sp),sp
	movea.l	d0,a0
	movea.l	4(a0),a0                        ; the shift table
	cmpi.b	#$23,4(a0)                      ; shift 3 '#'?
	seq	d0
	ext.w	d0
	move.w	d0,-(sp)                        ; keep it
	move.w	#$2a,-(sp)
	trap	#1                              ; Tgetdate, Tgetdate: the date
	addq.l	#2,sp
	move.w	d0,d1
	andi.w	#$1f,d1                         ; the day
	move.w	d0,d2
	lsr.w	#5,d2
	andi.w	#$f,d2                          ; the month
	tst.b	(sp)+                           ; US?
	beq.s	date_time_string_date           ; no
	exg	d2,d1                           ; yes: the month first
date_time_string_date:
	bsr.s	two_digits
	move.b	#$2f,(a3)+                      ; /
	move.w	d2,d1
	bsr.s	two_digits
	move.b	#$2f,(a3)+                      ; /
	move.w	d0,d1
	rol.w	#7,d1
	andi.w	#$7f,d1                         ; the year from 1980
	addi.w	#$50,d1
	bsr.s	two_digits
	move.b	#$20,(a3)+                      ; two spaces
	move.b	#$20,(a3)+
	move.w	#$2c,-(sp)
	trap	#1                              ; Tgettime, Tgettime: the time
	addq.l	#2,sp
	move.w	d0,d1
	rol.w	#5,d1
	andi.w	#$1f,d1                         ; the hours
	bsr.s	two_digits
	move.b	#$3a,(a3)+                      ; :
	move.w	d0,d1
	lsr.w	#5,d1
	andi.w	#$3f,d1                         ; the minutes
	bsr.s	two_digits
	move.b	#$3a,(a3)+                      ; :
	move.w	d0,d1
	andi.w	#$1f,d1
	add.w	d1,d1                           ; the seconds, in 2s

;------------------------------------------------------------------------------
; Put d1 (0-99) at a3 as two decimal digits.
;------------------------------------------------------------------------------
two_digits:	; from: date_time_string
	swap	d1
	clr.w	d1                              ; the low word only
	swap	d1
	divu.w	#$a,d1                          ; tens and units
	addi.b	#$30,d1
	move.b	d1,(a3)+                        ; the tens
	swap	d1
	addi.b	#$30,d1
	move.b	d1,(a3)+                        ; the units
	rts

;------------------------------------------------------------------------------
; Allocate d1 bytes (made even) from the heap.  Out: a0 = them and d0 = -1 (NE), or d0 = 0 (Z) when the heap
; is full.  The block is kept as the last one, so that heap_free can give it back.
;------------------------------------------------------------------------------
heap_alloc:	; from: incbin_buffer_alloc, alloc_block
	addq.l	#1,d1                           ; made even
	andi.b	#$fe,d1
	move.l	d1,d0
	add.l	heap_start(a6),d0               ; the heap's new start
	cmp.l	heap_end(a6),d0                 ; past its end?
	bcc.s	heap_alloc_full                 ; yes
	movea.l	heap_start(a6),a0               ; the block
	add.l	d1,heap_start(a6)               ; the heap starts after it
	move.l	a0,heap_last(a6)                ; the last block
	moveq	#-1,d0                          ; done
	rts
heap_alloc_full:
	moveq	#0,d0                           ; none
	rts

;------------------------------------------------------------------------------
; Free the block a0 when it is the last one allocated: the heap starts at it again.
;------------------------------------------------------------------------------
heap_free:	; from: incbin_buffer_free, free_block_chain
	cmpa.l	heap_last(a6),a0                ; the last one?
	bne.s	heap_free_done                  ; no
	move.l	a0,heap_start(a6)               ; back to it
	clr.l	heap_last(a6)                   ; no last block
heap_free_done:
	rts

;------------------------------------------------------------------------------
; Open the source or include file of the record a1 (name at +$17, its length at +$16).  Out: d4 = the
; handle, d1 = the length, Z set when it was opened.
;------------------------------------------------------------------------------
open_source_file:	; from: include_open
	lea	$16(a1),a0                      ; the name's length
	moveq	#0,d0
	move.b	(a0)+,d0
	lea	-$1(a0,d0.w),a1                 ; the end mark
	clr.b	(a1)                            ; a 0 for now
	move.l	a1,-(sp)
	bsr.s	open_include                    ; open it
	movea.l	(sp)+,a1
	move.b	#$b,(a1)                        ; the end mark back
	tst.l	d4                              ; opened?
	eori.b	#$4,ccr                         ; Z set if so
	rts

;------------------------------------------------------------------------------
; Open the file a0: as it is when it names a folder or drive; else from the source's folder, then each
; INCDIR folder.  Out: d4 = the handle (0 for none), d1 = the length.
;------------------------------------------------------------------------------
open_include:	; from: open_source_file, open_binary_file
	move.l	a0,-(sp)
	bsr.w	find_file_name                  ; a folder or drive?
	movea.l	(sp)+,a0
	beq.s	file_open_length                ; yes: open it so
	move.l	a0,-(sp)
	movea.l	source_dir_end(a6),a1           ; after the source's folder
open_include_copy:
	move.b	(a0)+,(a1)+                     ; the name
	bne.s	open_include_copy
	lea	source_dir(a6),a0               ; the source's folder
	bsr.s	file_open_length                ; open it
	movea.l	(sp)+,a0
	tst.l	d4                              ; opened?
	beq.s	open_include_dirs               ; no
	rts
open_include_dirs:
	lea	asm_incdir_list(a6),a1          ; the INCDIR folders
	tst.w	(a1)                            ; any?
	beq.s	file_open_length                ; no: open the plain name
	addq.l	#1,a1                           ; the first
open_include_dir:
	move.l	a0,-(sp)
	lea	include_path(a6),a2             ; the path to try
open_include_dir_copy:
	move.b	(a1)+,(a2)+                     ; the folder
	bne.s	open_include_dir_copy
	subq.l	#1,a2
open_include_dir_name:
	move.b	(a0)+,(a2)+                     ; then the name
	bne.s	open_include_dir_name
	move.l	a1,-(sp)                        ; the next folder
	lea	include_path(a6),a0
	bsr.s	file_open_length                ; open it
	movea.l	(sp)+,a1
	movea.l	(sp)+,a0
	tst.l	d4                              ; opened?
	bne.s	open_include_done               ; yes
	tst.b	(a1)                            ; another folder?
	bne.s	open_include_dir                ; yes
open_include_done:
	rts

;------------------------------------------------------------------------------
; Open the file a0 to read and find its length.  Out: d4 = the handle (0 when it cannot be opened), d1 = the
; length.
;------------------------------------------------------------------------------
file_open_length:	; from: open_include
	clr.w	-(sp)                           ; to read
	move.l	a0,-(sp)
	move.w	#$3d,-(sp)
	trap	#1                              ; Fopen, Fopen: open the file
	addq.l	#8,sp
	moveq	#0,d4                           ; none
	tst.l	d0                              ; opened?
	bmi.s	file_open_length_done           ; no
	move.l	d0,d4                           ; the handle
	move.w	#$2,-(sp)                       ; from the end
	move.w	d4,-(sp)
	clr.l	-(sp)
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek, Fseek: to the end, the length
	lea	$a(sp),sp
	move.l	d0,-(sp)
	clr.w	-(sp)                           ; from the start
	move.w	d4,-(sp)
	clr.l	-(sp)
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek, Fseek: back to the start
	lea	$a(sp),sp
	move.l	(sp)+,d1                        ; the length
file_open_length_done:
	rts

;------------------------------------------------------------------------------
; Close the file d2.
;------------------------------------------------------------------------------
close_source_file:	; from: asm_read_line, include_close_all, binary_close
	move.w	d2,-(sp)
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose, Fclose: close it
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; Read d1 bytes of the file d2 to a0.  Out: d1 = the count read, d0 = 0.
;------------------------------------------------------------------------------
read_source_file:	; from: include_read
	move.l	a0,-(sp)
	move.l	d1,-(sp)
	move.w	d2,-(sp)
	move.w	#$3f,-(sp)
	trap	#1                              ; Fread, Fread: read them
	lea	$c(sp),sp
	move.l	d0,d1                           ; the count
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Open the file a0 (INCBIN) the way include files are found.  Out: d3 = the handle, d2 = the length, Z set
; when it was opened.
;------------------------------------------------------------------------------
open_binary_file:	; from: dir_incbin
	move.l	d4,-(sp)
	bsr.w	open_include                    ; open it
	move.l	d1,d2                           ; the handle
	move.l	d4,d3
	movem.l	(sp)+,d4
	eori.b	#$4,ccr                         ; Z set if opened
	rts

;------------------------------------------------------------------------------
; Close the file d3.
;------------------------------------------------------------------------------
close_binary_file:	; from: asm_finish, dir_incbin
	move.w	d3,-(sp)
	move.w	#$3e,-(sp)
	trap	#1                              ; Fclose, Fclose: close it
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; Read d1 bytes of the file d3 to a0.  Out: d0 = the count read or an error.
;------------------------------------------------------------------------------
read_binary_file:	; from: dir_incbin
	move.l	a0,-(sp)
	move.l	d1,-(sp)
	move.w	d3,-(sp)
	move.w	#$3f,-(sp)
	trap	#1                              ; Fread, Fread: read them
	lea	$c(sp),sp
	rts

;------------------------------------------------------------------------------
; Create the output file: the name a0 (-O), or the source's base name with the name a0 when it starts with
; a dot, or with the format's extension when a0 is empty (up to 82 characters).  Out: d2 = the handle and
; d0 = 0 (Z set), else d0 = the error.
;------------------------------------------------------------------------------
create_output_file:	; from: binary_create
	lea	output_base_name(a6),a1         ; the source's base name
	move.b	(a0),d0                         ; the name given
	beq.s	create_output_file_base         ; none
	cmp.b	#$2e,d0                         ; an extension?
	bne.s	create_output_file_open         ; no: as it is
create_output_file_base:
	move.l	a1,d2
create_output_file_find_end:
	tst.b	(a1)+
	bne.s	create_output_file_find_end
	subq.l	#1,a1                           ; back on the 0
	sub.l	a1,d2
	neg.l	d2                              ; the base's length
	tst.b	d0                              ; none given?
	bne.s	create_output_file_add          ; no
	bsr.w	obj_extension                   ; the format's extension
create_output_file_add:
	cmp.b	#$52,d2                         ; full?
	beq.s	create_output_file_named        ; yes
	addq.b	#1,d2
	move.b	(a0)+,d1
	move.b	d1,(a1)+                        ; add the extension
	bne.s	create_output_file_add
create_output_file_named:
	lea	output_base_name(a6),a0         ; the name made
create_output_file_open:
	clr.w	-(sp)
	move.l	a0,-(sp)
	move.w	#$3c,-(sp)
	trap	#1                              ; Fcreate, Fcreate: make the file
	addq.l	#8,sp
	tst.l	d0                              ; made?
	bmi.s	create_output_file_done         ; no
	move.l	d0,d2                           ; the handle
	moveq	#0,d0
create_output_file_done:
	rts

;------------------------------------------------------------------------------
; Write d1 bytes at a0 to the output file.  Out: Z set when all were written (or none was asked for).
;------------------------------------------------------------------------------
output_write:	; from: binary_write, dri_symbol_record
	tst.l	d1                              ; any?
	beq.s	output_write_done               ; no
	movem.l	d1-d2,-(sp)
	move.l	binary_handle(a6),d2            ; the output file
	move.l	a0,-(sp)
	move.l	d1,-(sp)
	move.w	d2,-(sp)
	move.w	#$40,-(sp)
	trap	#1                              ; Fwrite, Fwrite: write them
	lea	$c(sp),sp
	movem.l	(sp)+,d1-d2
	cmp.l	d0,d1                           ; all of them?
output_write_done:
	rts

;------------------------------------------------------------------------------
; Move to the offset d2 from the output file's start.
;------------------------------------------------------------------------------
output_seek:	; from: exe_flush_buffer, exe_relocation_flush, dri_symbol
	clr.w	-(sp)                           ; from the start
	move.w	output_handle(a6),-(sp)         ; the output file
	move.l	d2,-(sp)
	move.w	#$42,-(sp)
	trap	#1                              ; Fseek, Fseek: move there
	lea	$a(sp),sp
	rts

;------------------------------------------------------------------------------
; Choose a buffer's size: d1 = the size wanted when it is less than half the free heap, else d2 = the
; smallest; the smallest always with -M or under 32000 bytes free.  Out: d1 = the size.
;------------------------------------------------------------------------------
buffer_size:	; from: include_open, exe_buffers_init, gst_start
	tst.b	cmdline_small_buffers(a6)       ; -M?
	bne.s	buffer_size_smallest            ; yes: the smallest
	move.l	heap_end(a6),d0                 ; the heap's end
	sub.l	heap_start(a6),d0               ; less its start: free
	cmp.l	#$7d00,d0                       ; under 32000?
	bcs.s	buffer_size_smallest            ; yes: the smallest
	asr.l	#1,d0                           ; half of it
	cmp.l	d0,d1                           ; the size wanted less?
	bcs.s	buffer_size_done                ; yes: it
buffer_size_smallest:
	move.l	d2,d1                           ; the smallest
buffer_size_done:
	rts
text_end_reloc:
	dc.l	text_end_reloc                  ; a relocated long pointing at itself, at the text's end

	section	data

;------------------------------------------------------------------------------
; The data section.  a6 points here (start: lea data_base,a6) all through the editor, so every
; d(a6) below $17d0 in the editor is in here.  The assembler half ($4924 on) is not: it runs as a
; process of its own (Pexec 5 and 4) with a6 at its basepage's BSS + 2.
; It is the editor's GEM resource in RCS order: the tedinfos of the first dialogs, their trees and
; strings (Find/Replace, Goto Line, the file selector title, Help, Run Other), the file selector
; titles and the alerts; then the tedinfos, trees and strings of Preferences, the menu bar and
; About.  fix_resource_trees runs rsrc_obfix over every object of the 9 trees in object_tree_list at the start.
; The tedinfos (te_ptext, te_ptmplt, te_pvalid, then font, -, justification, colour, -, border,
; text length, template length) of the Find/Replace, Goto Line and Run Other dialogs.
;------------------------------------------------------------------------------
data_base:	; from: start, find_tree
	dc.l	find_text_buffer                ; te_ptext: the Find text (65 characters)
	dc.l	find_text_template              ; te_ptmplt: all underscores
	dc.l	find_text_valid                 ; te_pvalid: 'X': any character
	dc.w	$0003,$0000,$0000,$1181,$0000,$0000,$0042,$0042 ; font 3 (system), left, colour $1181, border 0, text
                                                ;   length 66, template length 66

;------------------------------------------------------------------------------
; The Replace text's tedinfo.
;------------------------------------------------------------------------------
replace_tedinfo:	; from: find_tree
	dc.l	replace_text_buffer             ; te_ptext: the Replace text
	dc.l	replace_text_template           ; te_ptmplt: all underscores
	dc.l	replace_text_valid              ; te_pvalid: 'X': any character
	dc.w	$0003,$0000,$0000,$1181,$0000,$0000,$0042,$0042 ; font 3 (system), left, colour $1181, border 0, text
                                                ;   length 66, template length 66

;------------------------------------------------------------------------------
; The 'Casing:' label's tedinfo (a G_TEXT).
;------------------------------------------------------------------------------
casing_tedinfo:	; from: find_tree
	dc.l	casing_label_text               ; te_ptext: 'Casing:'
	dc.l	casing_template                 ; te_ptmplt: none
	dc.l	casing_valid                    ; te_pvalid: none
	dc.w	$0003,$0000,$0000,$1181,$0000,$0000,$0008,$0001 ; font 3 (system), left, colour $1181, border 0, text
                                                ;   length 8, template length 1

;------------------------------------------------------------------------------
; The Goto Line field's tedinfo.
;------------------------------------------------------------------------------
goto_line_tedinfo:	; from: goto_line_tree
	dc.l	goto_line_buffer                ; te_ptext: the line number (5 digits)
	dc.l	goto_line_template              ; te_ptmplt: 'Goto Line: _____'
	dc.l	goto_line_valid                 ; te_pvalid: '9': digits only
	dc.w	$0003,$0000,$0000,$1181,$0000,$0000,$0006,$0011 ; font 3 (system), left, colour $1181, border 0, text
                                                ;   length 6, template length 17

;------------------------------------------------------------------------------
; The Run Other command line's tedinfo.
;------------------------------------------------------------------------------
command_line_tedinfo:	; from: run_other_tree
	dc.l	command_line_buffer             ; te_ptext: the command line (74 characters)
	dc.l	command_line_template           ; te_ptmplt: all underscores
	dc.l	command_line_valid              ; te_pvalid: 'X': any character
	dc.w	$0003,$0000,$0000,$1181,$0000,$0000,$004b,$004b ; font 3 (system), left, colour $1181, border 0, text
                                                ;   length 75, template length 75

;------------------------------------------------------------------------------
; The Find/Replace dialog (Find Alt-F, Replace Alt-R), 12 objects: the Find and Replace texts,
; two radio buttons for the case and the exits Cancel (9), Previous (10) and Next (11).  Below 80
; columns narrow_dialogs narrows it by 40 characters.  Each object is 24 bytes: ob_next, ob_head,
; ob_tail, ob_type, ob_flags, ob_state, ob_spec (long), ob_x, ob_y, ob_w, ob_h (in characters
; until rsrc_obfix, the high byte adds pixels).
;------------------------------------------------------------------------------
find_tree:	; from: gem_screen_setup, object_tree_list
	dc.w	$ffff,$0001,$000b,$0014,$0000,$0010,$0002,$1181 ; object 0: the Find/Replace dialog (Search menu Find,
                                                ;   Replace); G_BOX at 1,1, 78x10, children 1-11 (outlined)
	dc.w	$0001,$0001,$004e,$000a,$0002,$ffff,$ffff,$001c ; object 1: 'Find:'; G_STRING at 2,1, 5x1
	dc.w	$0000,$0000                     ; object 1: ob_flags, ob_state
	dc.l	find_label_text                 ; object 1 ob_spec: 'Find:'
	dc.w	$0002,$0001,$0005,$0001,$0003,$ffff,$ffff,$001d ; object 2: the text to find; G_FTEXT at 11,1, 65x1
                                                ;   (editable)
	dc.w	$0008,$0000                     ; object 2: ob_flags, ob_state
	dc.l	data_base                       ; object 2 ob_spec: the Find tedinfo
	dc.w	$000b,$0001,$0041,$0001,$0004,$ffff,$ffff,$001c ; object 3: 'Replace:'; G_STRING at 2,3, 8x1
	dc.w	$0000,$0000                     ; object 3: ob_flags, ob_state
	dc.l	replace_label_text              ; object 3 ob_spec: 'Replace:'
	dc.w	$0002,$0003,$0008,$0001,$0005,$ffff,$ffff,$001d ; object 4: the text to put in its place; G_FTEXT at
                                                ;   11,3, 65x1 (editable)
	dc.w	$0008,$0000                     ; object 4: ob_flags, ob_state
	dc.l	replace_tedinfo                 ; object 4 ob_spec: the Replace tedinfo
	dc.w	$000b,$0003,$0041,$0001,$0006,$ffff,$ffff,$0015 ; object 5: 'Casing:'; G_TEXT at 2,5, 7x1
	dc.w	$0000,$0000                     ; object 5: ob_flags, ob_state
	dc.l	casing_tedinfo                  ; object 5 ob_spec: the Casing tedinfo
	dc.w	$0002,$0005,$0007,$0001,$0009,$0007,$0008,$0019 ; object 6: the box round the two Casing buttons; G_IBOX
                                                ;   at 11,5, 25x1, children 7-8
	dc.w	$0000,$0000,$0000,$1181,$000b,$0005,$0019,$0001 ; object 6: ob_flags, ob_state, ob_spec, ob_x, ob_y,
                                                ;   ob_w, ob_h
	dc.w	$0008,$ffff,$ffff,$001a,$0011,$0001 ; object 7: 'test=TEST': case ignored; G_BUTTON at 0,0, 12x1
                                                ;   (selectable, radio, selected)
	dc.l	ignore_case_button_text         ; object 7 ob_spec: its text, set to 'test=TEST' at the start
	dc.w	$0000,$0000,$000c,$0001,$0006,$ffff,$ffff,$001a ; object 8: 'test<>TEST': case matters; G_BUTTON at
                                                ;   13,0, 12x1 (selectable, radio)
	dc.w	$0011,$0000                     ; object 8: ob_flags, ob_state
	dc.l	match_case_button_text          ; object 8 ob_spec: its text, set to 'test<>TEST' at the start
	dc.w	$000d,$0000,$000c,$0001,$000a,$ffff,$ffff,$001a ; object 9: Cancel; G_BUTTON at 2,7, 10x2 (selectable,
                                                ;   exit)
	dc.w	$0005,$0000                     ; object 9: ob_flags, ob_state
	dc.l	find_cancel_text                ; object 9 ob_spec: 'Cancel'
	dc.w	$0002,$0007,$000a,$0002,$000b,$ffff,$ffff,$001a ; object 10: Previous: search backwards; G_BUTTON at
                                                ;   54,7, 10x2 (selectable, exit)
	dc.w	$0005,$0000                     ; object 10: ob_flags, ob_state
	dc.l	find_previous_text              ; object 10 ob_spec: 'Previous'
	dc.w	$0036,$0007,$000a,$0002,$0000,$ffff,$ffff,$001a ; object 11: Next: search forwards; G_BUTTON at 66,7,
                                                ;   10x2 (selectable, default, exit, last object)
	dc.w	$0027,$0000                     ; object 11: ob_flags, ob_state
	dc.l	find_next_text                  ; object 11 ob_spec: 'Next'
	dc.w	$0042,$0007,$000a,$0002         ; object 11: ob_x, ob_y, ob_w, ob_h

;------------------------------------------------------------------------------
; The Goto Line dialog (Alt-G), 4 objects: the line number, Cancel (2), Ok (3).
;------------------------------------------------------------------------------
goto_line_tree:	; from: object_tree_list
	dc.w	$ffff,$0001,$0003,$0014,$0000,$0010,$0002,$1181 ; object 0: the Goto Line dialog (Options menu); G_BOX
                                                ;   at 1+2 px,1, 40x5, children 1-3 (outlined)
	dc.w	$0201,$0001,$0028,$0005,$0002,$ffff,$ffff,$001d ; object 1: the line number; G_FTEXT at 2,2, 16x1
