	dc.w	$0002,$0002,$0010,$0001,$0003,$ffff,$ffff,$001a ; object 2: Cancel; G_BUTTON at 30,2, 8x1 (selectable,
                                                ;   exit)
	dc.w	$0005,$0000                     ; object 2: ob_flags, ob_state
	dc.l	goto_line_cancel_text           ; object 2 ob_spec: 'Cancel'
	dc.w	$001e,$0002,$0008,$0001,$0000,$ffff,$ffff,$001a ; object 3: Ok; G_BUTTON at 20,2, 8x1 (selectable,
