	dc.l	goto_line_ok_text               ; object 3 ob_spec: 'Ok'
	dc.w	$0014,$0002,$0008,$0001         ; object 3: ob_x, ob_y, ob_w, ob_h

;------------------------------------------------------------------------------
; The file selector title, 2 objects: an invisible box the size of the file selector,
