;------------------------------------------------------------------------------
; The strings of the Find/Replace dialog.
;------------------------------------------------------------------------------
find_label_text:	; from: find_tree
	dc.b	'Find:',0                       ; Find/Replace object 1: the Find label
find_text_buffer:	; from: data_base
	dcb.w	32,$5f5f                        ; the Find text: 65 characters and a 0, cleared at the start; the search
                                                ;   copies it to find_string
	dc.w	$5f00                           ; its last underscore and the 0
find_text_template:	; from: data_base
	dcb.w	32,$5f5f                        ; the Find template: 65 underscores (the whole field is input)
	dc.w	$5f00                           ; its last underscore and the 0
find_text_valid:	; from: data_base
	dc.b	'X',0                           ; the Find validation: X, any character
replace_label_text:	; from: find_tree
	dc.b	'Replace:',0                    ; Find/Replace object 3: the Replace label
replace_text_buffer:	; from: replace_tedinfo
	dc.b	'________________________________________________________________','_',0 ; the Replace text, cleared at
                                                ;   the start; copied to replace_string
replace_text_template:	; from: replace_tedinfo
	dc.b	'________________________________________________________________','_',0 ; the Replace template
replace_text_valid:	; from: replace_tedinfo
	dc.b	'X',0                           ; the Replace validation: any character
casing_label_text:	; from: casing_tedinfo
	dc.b	'Casing:',0                     ; the Casing label's text
casing_template:	; from: casing_tedinfo
	dc.b	$00                             ; its template: none
casing_valid:	; from: casing_tedinfo
	dc.b	$00                             ; its validation: none
ignore_case_button_text:	; from: find_tree
	dc.b	$00                             ; Casing button 1's text: empty, the start points it at 'test=TEST'
match_case_button_text:	; from: find_tree
	dc.b	$00                             ; Casing button 2's text: empty, the start points it at 'test<>TEST'
find_cancel_text:	; from: find_tree
	dc.b	'Cancel',0                      ; Find/Replace exit 9
find_previous_text:	; from: find_tree
	dc.b	'Previous',0                    ; Find/Replace exit 10: search backwards
find_next_text:	; from: find_tree
	dc.b	'Next',0                        ; Find/Replace exit 11 (default): search forwards

;------------------------------------------------------------------------------
; The strings of the Goto Line dialog.
;------------------------------------------------------------------------------
goto_line_buffer:	; from: goto_line_tedinfo
	dc.b	'@____',0                       ; the Goto Line number: 5 digits, cleared before each use ('@' first
                                                ;   shows an empty field)
goto_line_template:	; from: goto_line_tedinfo
	dc.b	'Goto Line: _____',0            ; its template
goto_line_valid:	; from: goto_line_tedinfo
	dc.b	'9',0                           ; its validation: 9, digits only
goto_line_cancel_text:	; from: goto_line_tree
	dc.b	'Cancel',0                      ; Goto Line exit 2
goto_line_ok_text:	; from: goto_line_tree
	dc.b	'Ok',0                          ; Goto Line exit 3 (default)

;------------------------------------------------------------------------------
; The file selector title's first text.
;------------------------------------------------------------------------------
fsel_title_text:	; from: fsel_title_tree
	dc.b	$00                             ; the file selector title button's first text (empty); each call sets a
                                                ;   title instead

;------------------------------------------------------------------------------
; The strings of the Help dialog.
;------------------------------------------------------------------------------
help_strings:	; from: help_title_spec
	dc.b	$00                             ; the Help title's first text (empty); the Help code sets the version
                                                ;   string instead
help_cursor_heading:	; from: help_title_spec
	dc.b	'Cursor',0                      ; Help: the heading over the cursor keys
help_blocks_heading:	; from: help_title_spec
	dc.b	'Blocks',0                      ; Help: the heading over the block keys
help_page_up_text:	; from: help_title_spec
	dc.b	'^R Page Up',0                  ; Help: Control-R
help_block_start_text:	; from: help_title_spec
	dc.b	'F1 Block Start',0              ; Help: F1
help_page_down_text:	; from: help_title_spec
	dc.b	'^C Page Down',0                ; Help: Control-C
help_block_end_text:	; from: help_title_spec
	dc.b	'F2 Block End',0                ; Help: F2
help_word_left_text:	; from: help_title_spec
	dc.b	'^A Word Left',0                ; Help: Control-A
help_block_save_text:	; from: help_title_spec
	dc.b	'F3 Block Save',0               ; Help: F3
help_word_right_text:	; from: help_title_spec
	dc.b	'^F Word Right',0               ; Help: Control-F
help_block_copy_text:	; from: help_title_spec
	dc.b	'F4 Block Copy',0               ; Help: F4
help_delete_line_text:	; from: help_title_spec
	dc.b	'^Y Delete Line',0              ; Help: Control-Y
help_block_remember_text:	; from: help_title_spec
	dc.b	$01                             ; Help: Shift-F4 ($01 is the Shift arrow)
	dc.b	'F4 Block Remember',0           ; remember the block without deleting it
help_block_paste_text:	; from: help_title_spec
	dc.b	'F5 Block Paste',0              ; Help: F5
help_block_delete_text:	; from: help_title_spec
	dc.b	$01                             ; Help: Shift-F5
	dc.b	'F5 Block Delete',0             ; delete the block
help_free_memory_label:	; from: help_title_spec
	dc.b	'TOS Free Memory:',0            ; Help: the free memory label
help_free_memory_number:	; from: help_title_spec
	dc.b	'9999000',0                     ; Help: the free memory number, written over at run time (7 digits)
help_ok_text:	; from: help_title_spec
	dc.b	'OK',0                          ; Help exit 18 (default)

;------------------------------------------------------------------------------
; The strings of the Run Other dialog, then the file selector titles (select_load_file-select_save_block,
; Delete File and Run Other pass them to file_selector) and the alerts for form_alert (gem_alert).
;------------------------------------------------------------------------------
command_line_label_text:	; from: run_other_tree
	dc.b	'Command line:',0               ; Run Other: the label above the command line
run_other_name_buffer:	; from: run_other_tree
	dc.b	'JOHNJOHN.PRG',0                ; Run Other: the program's name, copied over at run time (12 characters
                                                ;   and a 0)
command_line_buffer:	; from: command_line_tedinfo
	dc.b	'________________________________________________________________' ; the Run Other command line: 74
                                                ;   characters and a 0, cleared at the start
	dc.b	'__________',0
command_line_template:	; from: command_line_tedinfo
	dcb.w	37,$5f5f                        ; its template: 74 underscores
	dc.b	$00                             ; the template's 0
command_line_valid:	; from: command_line_tedinfo
	dc.b	'X',0                           ; its validation: any character
run_other_cancel_text:	; from: run_other_tree
	dc.b	'Cancel',0                      ; Run Other exit 4
run_other_ok_text:	; from: run_other_tree
	dc.b	'Ok',0                          ; Run Other exit 5 (default): run it
	dc.b	'Load a file',0                 ; file selector title: Load (Alt-L)
	dc.b	'Save a file',0                 ; file selector title: Save As (Alt-S)
	dc.b	'Insert a file',0               ; file selector title: Insert File (Alt-I)
	dc.b	'Save a block',0                ; file selector title: save the block (F3)
	dc.b	'Warning - DELETE a file',0     ; file selector title: Delete File
	dc.b	'Run Other Program',0           ; file selector title: Run Other (Alt-O)
	dc.b	'[1][There is insufficient memory|for the program',$27 ; alert: memory ran out (at the start or for a
                                                ;   new text buffer); Quit ends GenST
	dc.b	's requirements][ Quit ]',0
	dc.b	'[3][There is not enough|memory to remember|the block][Delete|Can' ; alert: no room to remember the
                                                ;   block; Delete deletes it anyway (Cancel is the default)
	dc.b	'cel]',0
	dc.b	'[1][Print Block| |Ensure printer is|connected and on line][OK|Ca' ; alert: Print Block (Alt-W) asks for
                                                ;   the printer
	dc.b	'ncel]',0
	dc.b	'[1][There is not enough memory|in the edit buffer to load|that f' ; alert: the file does not fit in the
                                                ;   text buffer
	dc.b	'ile][Cancel]',0
	dc.b	'[3][There are no more|windows available][ Quit ]',0 ; alert: no free GEM window

;------------------------------------------------------------------------------
; The tedinfos of the Preferences and About dialogs.
;------------------------------------------------------------------------------
prefs_title_tedinfo:	; from: prefs_tree
	dc.l	prefs_title_text                ; te_ptext: 'Editor Preferences'
	dc.l	prefs_title_template            ; te_ptmplt: none
	dc.l	prefs_title_valid               ; te_pvalid: none
