;------------------------------------------------------------------------------
; Strings the code uses directly: the Casing button texts and two alerts.
;------------------------------------------------------------------------------
ignore_case_text:	; from: gem_init
	dc.b	'test=TEST',0                   ; Casing button 1's text: matches whatever the case
match_case_text:	; from: gem_init
	dc.b	'test<>TEST',0                  ; Casing button 2's text: the case must match
alert_no_program:	; from: monst_settings, cmd_run
	dc.b	'[1][No program in memory][Cancel]',0 ; alert: no program assembled to memory to run or debug
alert_no_monst:	; from: editor_init
	dc.b	'[1][Could not find MonST2][ OK ]',0 ; alert: Load MonST is on but MonST2 could not be loaded
	dc.b	$00                             ; pad to an even address

	section	bss

;------------------------------------------------------------------------------
; The BSS: the editor's variables from $17d0(a6) up (6688 bytes); the stack's top is $31ec(a6).
;------------------------------------------------------------------------------
bss_variables:	ds.b	6688                    ; the editor variables, offsets $17d0-$31ef from a6
bss_end:

	end
